#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define CONFIG_SINGLE_SHOT 0x8000
#define CONFIG_MUX_AIN0 0x4000
#define CONFIG_PGA_4_096V 0x0200
#define CONFIG_DR_128SPS 0x0080
#define CONFIG_MODE_SINGLE 0x0100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to initialize the ADS1115
int init_ads1115() {
    // Configuration register value
    uint16_t config = CONFIG_SINGLE_SHOT | CONFIG_MUX_AIN0 | CONFIG_PGA_4_096V | CONFIG_DR_128SPS | CONFIG_MODE_SINGLE;

    // Write the configuration to the ADS1115
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;      // LSB

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115 configuration register!\n");
        return -1;
    }

    return 0;
}

// Function to read the current from the sensor
float read_current() {
    // Read the conversion register
    char buf[2];
    buf[0] = ADS1115_REG_CONVERT;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to ADS1115 conversion register!\n");
        return -1.0;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register!\n");
        return -1.0;
    }

    // Combine the two bytes into a 16-bit signed integer
    int16_t raw_value = (buf[0] << 8) | buf[1];

    // Convert the raw value to amperes (assuming 4.096V range and 1mA/LSB)
    float current = (float)raw_value * 0.001; // 1mA/LSB

    return current;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed!\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADS1115
    if (init_ads1115() != 0) {
        fprintf(stderr, "ADS1115 initialisation failed!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read the current
        float current = read_current();

        if (current >= 0) {
            // Log the current value
            printf("Current: %.3f A\n", current);
        } else {
            fprintf(stderr, "Error reading current!\n");
        }

        // Wait for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

