#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_FULL_SCALE_VOLTAGE 4.096
#define ADS1115_RESOLUTION 32767.0
#define TEMPERATURE_THRESHOLD 60.0
#define DEBOUNCE_DELAY_MS 50
#define BUZZER_DURATION_S 2
#define POLLING_INTERVAL_MS 100

// Global variables
static volatile bool running = true;
static int i2c_handle;
static FILE *log_file;

// Function prototypes
int init_gpio();
int init_i2c();
int read_flame_sensor();
int read_heat_sensor();
float convert_to_temperature(int16_t adc_value);
void activate_buzzer();
void deactivate_buzzer();
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off initially

    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, 4.096V range, single-shot mode, 128 SPS
    uint16_t config = 0x4003; // Single-shot mode, AIN0, +/-4.096V, 128 SPS
    uint8_t buf[3];
    buf[0] = ADS1115_CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, (char *)buf, 3) != 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_GPIO);
}

// Function to read the heat sensor
int read_heat_sensor() {
    uint8_t buf[2];
    buf[0] = ADS1115_CONVERSION_REG;

    if (i2cWriteDevice(i2c_handle, (char *)buf, 1) != 0) {
        fprintf(stderr, "Failed to write to I2C device for conversion read\n");
        return -1;
    }

    gpioDelay(10); // Wait for conversion

    if (i2cReadDevice(i2c_handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1;
    }

    int16_t adc_value = (buf[0] << 8) | buf[1];
    return adc_value;
}

// Function to convert ADC value to temperature (Celsius)
float convert_to_temperature(int16_t adc_value) {
    float voltage = (float)adc_value / ADS1115_RESOLUTION * ADS1115_FULL_SCALE_VOLTAGE;
    // Assuming a simple linear relationship for demonstration purposes
    // You'll need to calibrate this based on your specific LM393 setup
    float temperature = (voltage - 0.5) * 100; // Example conversion
    return temperature;
}

