#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define FAN_GPIO 18
#define CURRENT_THRESHOLD 10.0 // Amperes
#define SENSOR_SENSITIVITY 0.1 // Amperes per ADC unit
#define SENSOR_OFFSET 0.0 // Amperes
#define LOG_FILE "current_log.txt"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, uint32_t speed, uint8_t mode);
int read_adc(int spi_fd, int channel);
float convert_adc_to_current(int adc_value);
int log_current(float current);
int control_fan(int gpio_pin, int state);
void signal_handler(int signal);
int gpio_init(int gpio_pin);
int gpio_set_mode(int gpio_pin, int mode);
int gpio_write(int gpio_pin, int value);
int gpio_set_pull_up_down(int gpio_pin, int pud);

// SPI initialization function
int spi_init(const char *device, uint32_t speed, uint8_t mode) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_reg = SPI_MODE_0; // SPI_MODE_0 is defined in linux/spi/spidev.h
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_reg) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// ADC reading function
int read_adc(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message (MCP3008 single-ended read)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    // Check for sensor-absent condition
    if (adc_value == 0 || adc_value == 1023) {
        fprintf(stderr, "Sensor absent (ADC value: %d)\n", adc_value);
        return -1; // Indicate error
    }

    return adc_value;
}

// ADC to current conversion function
float convert_adc_to_current(int adc_value) {
    return (float)adc_value * SENSOR_SENSITIVITY + SENSOR_OFFSET;
}

// Logging function
int log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Fan control function
int control_fan(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// GPIO initialization function
int gpio_init(int gpio_pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// GPIO set mode function
int gpio_set_mode(int gpio_pin, int mode) {
    if (gpioSetMode(gpio_pin, mode) != 0) {
        fprintf(stderr, "Error setting GPIO %d mode\n", gpio_pin);
        return -1;
    }
    return 0;
}

// GPIO write function
int gpio_write(int gpio_pin, int value) {
    if (gpioWrite(gpio_pin, value) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// GPIO set pull-up/down function
int gpio_set_pull_up_down(int gpio_pin, int pud) {
    if (gpioSetPullUpDown(gpio_pin, pud) != 0) {
        fprintf(stderr, "Error setting GPIO %d pull-up/down\n", gpio_pin);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(FAN_GPIO) != 0) {
        close(spi_fd);
        return 1;
    }

    if (gpio_set_mode(FAN_GPIO, PI_OUTPUT) != 0) {
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    if (gpio_set_pull_up_down(FAN_GPIO, PI_PUD_OFF) != 0) {
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        // Convert ADC value to current
        float current = convert_adc_to_current(adc_value);

        // Log current
        if (log_current(current) != 0) {
            fprintf(stderr, "Error logging current\n");
        }

        // Control fan
        if (current > CURRENT_THRESHOLD) {
            if (control_fan(FAN_GPIO, 1) != 0) {
                fprintf(stderr, "Error turning fan ON\n");
            }
        } else {
            if (control_fan(FAN_GPIO, 0) != 0) {
                fprintf(stderr, "Error turning fan OFF\n");
            }
        }

        printf("Current: %.2f A\n", current);

        sleep(1); // Sample once per second
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (gpioWrite(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error turning fan OFF during cleanup\n");
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

