#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define FULL_SCALE_VOLTAGE 4.096 // +/- 4.096V
#define GAIN 1 // +/- 4.096V gain
#define REF_VOLTAGE 4.096
#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "co_log.txt"

// Calibration parameters (example values, replace with your sensor's calibration data)
#define A 0.1
#define B 0.5
#define C 1.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold calibration data
typedef struct {
    float a;
    float b;
    float c;
} calibration_data_t;

calibration_data_t calibration = {A, B, C};

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int16_t read_adc();
float convert_to_ppm(int16_t raw_value);
int log_data(float ppm_value);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-ended input A0, continuous conversion mode, and 128 SPS
    uint8_t config[3];
    config[0] = CONFIG_REG;
    config[1] = 0x44; // Single-ended A0, Continuous conversion
    config[2] = 0x83; // 128 SPS, Disable comparator

    if (i2cWriteDevice(i2c_handle, (char *)config, 3) != 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }

    return 0;
}

// Read raw ADC value from ADS1115
int16_t read_adc() {
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    int16_t raw_value = (buf[0] << 8) | buf[1];
    return raw_value;
}

// Convert raw ADC value to CO concentration in ppm using a logarithmic curve
float convert_to_ppm(int16_t raw_value) {
    // Convert raw value to voltage
    float voltage = (float)raw_value / 32767.0 * REF_VOLTAGE; // Assuming 16-bit ADC

    // Apply logarithmic calibration curve
    float ppm = calibration.a * log10(voltage) + calibration.b * pow(voltage, 2) + calibration.c;

    return ppm;
}

// Log data to file
int log_data(float ppm_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f ppm\n", timestamp, ppm_value);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read raw ADC value
        int16_t raw_value = read_adc();
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue; // Retry the loop
        }

        // Convert to ppm
        float ppm_value = convert_to_ppm(raw_value);

        // Log data
        if (log_data(ppm_value) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        printf("CO concentration: %.2f ppm\n", ppm_value);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

