int initialize_spi();
int read_flame_sensor();
int read_mcp3008(int channel);
float convert_to_temperature(int adc_value);
int log_data(int flame_present, float temperature);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int flame_pin;
    int ce_pin;
    int spi_channel;
    int spi_speed;
    char *filename;
} Config;

Config config = {FLAME_SENSOR_PIN, MCP3008_CE, SPI_CHANNEL, SPI_SPEED, "flame_data.csv"};

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO and SPI
    if (initialize_gpio() != 0 || initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen(config.filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s\n", config.filename);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        int flame_present = read_flame_sensor();
        int adc_value = read_mcp3008(0);
        float temperature = convert_to_temperature(adc_value);

        if (flame_present != -1 && adc_value != -1) {
            if (log_data(flame_present, temperature) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(1);
    }

    // Clean up resources
    fclose(fp);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioSetMode(config.flame_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", config.flame_pin);
        return 1;
    }
    return 0;
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", config.spi_channel, spi_handle);
        return 1;
    }
    return 0;
}

// Read flame sensor
int read_flame_sensor() {
    int value = gpioRead(config.flame_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", config.flame_pin);
        return -1;
    }
    return (value == 0) ? 1 : 0; // Flame detected if signal is LOW
}

// Read MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to temperature (Celsius)
float convert_to_temperature(int adc_value) {
    // Assuming a linear relationship between ADC value and temperature
    // You'll need to calibrate this based on your specific setup
    // This is a placeholder; replace with your actual calibration
    float temperature = (float)adc_value * (50.0 / 1023.0); // Example: 0-1023 maps to 0-50°C
    return temperature;
}

// Log data to CSV file
int log_data(int flame_present, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_present, temperature);
    fflush(fp); // Ensure data is written to file immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Ctrl+C pressed, exiting...\n");
}

