#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MICS4514_ADDR 0x49
#define CO_PPM_THRESHOLD 25.0
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define SAMPLE_INTERVAL_SEC 5

// Global variables for signal handling
static volatile int running = 1;
static int i2c_handle = -1;
static FILE *log_fp = NULL;
static FILE *alert_fp = NULL;

// Structure to hold sensor data
typedef struct {
    uint16_t ox;
    uint16_t red;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_to_ppm(uint16_t ox_value);
int log_data(float co_ppm);
int check_threshold(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// I2C initialization function
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MICS4514_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "I2C read failed: %d\n", bytes_read);
        return -1;
    }

    data->ox = (buf[0] << 8) | buf[1];
    data->red = (buf[2] << 8) | buf[3];

    return 0;
}

// Function to convert OX value to CO concentration in ppm
float convert_to_ppm(uint16_t ox_value) {
    // Simple linear conversion (replace with actual calibration data)
    return (float)ox_value * 0.1; // Example: 1 ADC unit = 0.1 ppm
}

// Function to log CO concentration to a file
int log_data(float co_ppm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(log_fp, "%s, CO: %.2f ppm\n", timestamp, co_ppm);
    fclose(log_fp);
    return 0;
}

// Function to check if CO concentration exceeds the threshold
int check_threshold(float co_ppm) {
    if (co_ppm >= CO_PPM_THRESHOLD) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        alert_fp = fopen(ALERT_FILE, "a");
        if (alert_fp == NULL) {
            fprintf(stderr, "Error opening alert file: %s\n", ALERT_FILE);
