#define IMP23ABSU_ADDR 0x68

// Define register addresses for the IMP23ABSU
#define IMP23ABSU_REG_WHO_AM_I 0x0F
#define IMP23ABSU_REG_CTRL_REG1 0x20
#define IMP23ABSU_REG_OUT_L 0x28
#define IMP23ABSU_REG_OUT_H 0x29

// Define sampling interval (in milliseconds)
#define SAMPLING_INTERVAL 100

// Define error value
#define ERROR_VALUE -999.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float level;
    int error;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int handle, float *level);
float calculate_average_level(float level1, float level2);
int log_data(float average_level);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(1, IMP23ABSU_ADDR, 0); // Bus 1, address 0x68, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Configure the IMP23ABSU (example: enable continuous mode)
    char buf[2];
    buf[0] = IMP23ABSU_REG_CTRL_REG1;
    buf[1] = 0x80; // Example value, check datasheet
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, float *level) {
    char buf[1];
    char data[2];
    int16_t raw_value;

    // Read the lower byte
    buf[0] = IMP23ABSU_REG_OUT_L;
    if (i2cWriteDevice(handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device (low byte)\n");
        return -1;
    }
    if (i2cReadDevice(handle, data, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device (low byte)\n");
        return -1;
    }

    // Read the higher byte
    buf[0] = IMP23ABSU_REG_OUT_H;
    if (i2cWriteDevice(handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device (high byte)\n");
        return -1;
    }
    if (i2cReadDevice(handle, data + 1, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device (high byte)\n");
        return -1;
    }

    raw_value = (data[1] << 8) | data[0];

    // Convert raw value to sound pressure level (example formula, adjust as needed)
    *level = (float)raw_value; // Replace with actual conversion formula

    return 0;
}

// Function to calculate the average level
float calculate_average_level(float level1, float level2) {
    return (level1 + level2) / 2.0;
}

// Function to log data to a file
int log_data(float average_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, average_level);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

