    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    float level1, level2, average_level;
    int read_error1, read_error2;

    // Main loop
    while (!terminate) {
        read_error1 = read_sensor_data(i2c_handle, &level1);
        if (read_error1 != 0) {
            level1 = ERROR_VALUE;
            fprintf(stderr, "Error reading sensor 1, logging error value\n");
        }

        read_error2 = read_sensor_data(i2c_handle, &level2);
        if (read_error2 != 0) {
            level2 = ERROR_VALUE;
            fprintf(stderr, "Error reading sensor 2, logging error value\n");
        }

        average_level = calculate_average_level(level1, level2);

        log_data(average_level);

        gpioDelay(SAMPLING_INTERVAL * 1000); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

