#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC1_CE 8
#define MIC2_CE 9
#define MISO 9
#define MOSI 10
#define SCLK 11
#define LED 27

// Define SPI channel
#define SPI_CHANNEL 0

// Define sampling parameters
#define SAMPLE_RATE 1000 // Hz
#define WINDOW_SIZE 100  // ms
#define NUM_SAMPLES (SAMPLE_RATE * WINDOW_SIZE / 1000)

// Define RMS threshold
#define RMS_THRESHOLD 1000.0

// Define LED on time
#define LED_ON_TIME 500 // ms

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold audio data
typedef struct {
    int16_t mic1_data[NUM_SAMPLES];
    int16_t mic2_data[NUM_SAMPLES];
} AudioData;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
double calculate_rms(int16_t *data, int num_samples);
void log_data(double mic1_rms, double mic2_rms);
void control_led(double mic1_rms, double mic2_rms);
void signal_handler(int signal);
void cleanup();

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MIC1_CE, PI_OUTPUT);
    gpioSetMode(MIC2_CE, PI_OUTPUT);
    gpioSetMode(MISO, PI_INPUT);
    gpioSetMode(MOSI, PI_OUTPUT);
    gpioSetMode(SCLK, PI_OUTPUT);
    gpioSetMode(LED, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0); // Channel 0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    return 0;
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel != 0 && channel != 1) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    // Build SPI command
    uint8_t spi_tx_buf[3];
    uint8_t spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    spi_tx_buf[2] = 0x00; // Don't care

    // Select the chip
    if (channel == 0) {
        gpioWrite(MIC1_CE, 0);
    } else {
        gpioWrite(MIC2_CE, 0);
    }

    // Transfer data
    spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);

    // Deselect the chip
    if (channel == 0) {
        gpioWrite(MIC1_CE, 1);
    } else {
        gpioWrite(MIC2_CE, 1);
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate RMS level
double calculate_rms(int16_t *data, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)data[i] * data[i];
    }
    return sqrt(sum_of_squares / num_samples);
}

// Function to log data to file
void log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to control the LED
void control_led(double mic1_rms, double mic2_rms) {
    if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
        gpioWrite(LED, 1); // Turn LED on
        gpioDelay(LED_ON_TIME * 1000); // Wait for 500ms
        gpioWrite(LED, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    terminate = 1;
}

// Function to clean up resources
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioWrite(LED, 0); // Turn off LED
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize the system
    if (initialize()) {
        return 1;
    }

    AudioData audio_data;

    // Main loop
    while (!terminate) {
        // Acquire audio samples
        for (int i = 0; i < NUM_SAMPLES; i++) {
            int mic1_value = read_mcp3008(0);
            int mic2_value = read_mcp3008(1);

            if (mic1_value == -1 || mic2_value == -1) {
                fprintf(stderr, "Error reading ADC values\n");
                cleanup();
                return 1;
            }

            audio_data.mic1_data[i] = (int16_t)mic1_value;
            audio_data.mic2_data[i] = (int16_t)mic2_value;
            gpioDelay(1); // Delay to achieve 1ms sampling rate
        }

        // Calculate RMS levels
        double mic1_rms = calculate_rms(audio_data.mic1_data, NUM_SAMPLES);
        double mic2_rms = calculate_rms(audio_data.mic2_data, NUM_SAMPLES);

        // Log data
        log_data(mic1_rms, mic2_rms);

        // Control LED
        control_led(mic1_rms, mic2_rms);
    }

    // Clean up resources before exiting
    cleanup();

    return 0;
}

