#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define A0_CHANNEL 0x01
#define FULL_SCALE_VOLTAGE 4.096
#define SENSITIVITY 0.066 // 66mV/A
#define SAMPLE_RATE 10 // Hz
#define BUFFER_SIZE 100
#define CURRENT_THRESHOLD 50.0 // Amps
#define LED_GPIO 17

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int configure_ads1115();
int16_t read_adc();
float convert_to_current(int16_t raw_value);
void update_circular_buffer(float current);
float calculate_average_current();
void control_led(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initializes the I2C connection
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configures the ADS1115 for single-ended A0, 4.096V, 128 SPS
int configure_ads1115() {
    // Configuration register value: Single-ended A0, 4.096V, 128 SPS, disable comparator
    uint16_t config_value = 0x4003; //0b0100000000000011;

    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Reads the ADC value from the ADS1115
int16_t read_adc() {
    char buf[1];
    char read_buf[2];
    int result;

    buf[0] = CONVERSION_REG;

    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to conversion register: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read conversion register: %d\n", result);
        return -1;
    }

    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];
    return raw_value;
}

// Converts the raw ADC value to current in Amperes
float convert_to_current(int16_t raw_value) {
    float voltage = (float)raw_value * FULL_SCALE_VOLTAGE / 32768.0;
    float current = voltage / SENSITIVITY;
    return current;
}

// Updates the circular buffer with the new current reading
void update_circular_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculates the average current from the circular buffer
float calculate_average_current() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Controls the LED (on or off)
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t raw_value = read_adc();
        if (raw_value == -1) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert to current
        float current = convert_to_current(raw_value);

        // Update circular buffer
        update_circular_buffer(current);

        // Calculate average current
        float average_current = calculate_average_current();

        // Check if average current exceeds threshold
        if (average_current > CURRENT_THRESHOLD) {
            control_led(1); // Turn on LED
        } else {
            control_led(0); // Turn off LED
        }

        printf("Current: %.2f A, Average Current: %.2f A\n", current, average_current);

        // Delay to achieve 10 Hz sampling rate
        gpioDelay(100); // 100 ms = 10 Hz
    }

    // Cleanup
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

