#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_I2C_ADDR 0x29

// TCS34725 register addresses
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_ID 0x92
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A

// Enable register values
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold color data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} color_data_t;

// Function prototypes
int tcs34725_init();
color_data_t tcs34725_read_color();
int log_color_data(color_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

// TCS34725 initialization function
int tcs34725_init() {
    int retries = 0;
    int status;

    // Enable power and ALS
    while (retries < 3) {
        status = i2cWriteByteData(i2c_handle, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN);
        if (status >= 0) break;
        fprintf(stderr, "Error writing to enable register (attempt %d): %d\n", retries + 1, status);
        gpioDelay(1000); // 1ms delay
        retries++;
    }
    if (retries >= 3) {
        fprintf(stderr, "Failed to write to enable register after multiple retries.\n");
        return -1;
    }

    // Set integration time (ATIME).  2.4ms integration time
    retries = 0;
    while (retries < 3) {
        status = i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xD5); // 2.4ms integration time
        if (status >= 0) break;
        fprintf(stderr, "Error writing to ATIME register (attempt %d): %d\n", retries + 1, status);
        gpioDelay(1000); // 1ms delay
        retries++;
    }
    if (retries >= 3) {
        fprintf(stderr, "Failed to write to ATIME register after multiple retries.\n");
        return -1;
    }

    // Verify sensor ID
    retries = 0;
    uint8_t id;
    while (retries < 3) {
        status = i2cReadByteData(i2c_handle, TCS34725_ID);
        if (status >= 0) {
            id = (uint8_t)status;
            break;
        }
        fprintf(stderr, "Error reading ID register (attempt %d): %d\n", retries + 1, status);
        gpioDelay(1000); // 1ms delay
        retries++;
    }
    if (retries >= 3) {
        fprintf(stderr, "Failed to read ID register after multiple retries.\n");
        return -1;
    }

    if (id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X (expected 0x44)\n", id);
        return -1;
    }

    return 0;
}

// Function to read color data from the sensor
color_data_t tcs34725_read_color() {
    color_data_t data;
    int status;

    // Read clear, red, green, and blue data
    status = i2cReadWordData(i2c_handle, TCS34725_CDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading clear data: %d\n", status);
        data.clear = 0; // Set to 0 on error
    } else {
        data.clear = (uint16_t)status;
    }

    status = i2cReadWordData(i2c_handle, TCS34725_RDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading red data: %d\n", status);
        data.red = 0; // Set to 0 on error
    } else {
        data.red = (uint16_t)status;
    }

    status = i2cReadWordData(i2c_handle, TCS34725_GDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading green data: %d\n", status);
        data.green = 0; // Set to 0 on error
    } else {
        data.green = (uint16_t)status;
    }

    status = i2cReadWordData(i2c_handle, TCS34725_BDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading blue data: %d\n", status);
        data.blue = 0; // Set to 0 on error
    } else {
        data.blue = (uint16_t)status;
    }

    return data;
}

// Function to log color data to a CSV file
int log_color_data(color_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Check if the file exists and is empty. If so, write the header.
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,clear,red,green,blue\n");
    }
    fseek(log_file, 0, SEEK_END); // Return to end of file for appending

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, data.clear, data.red, data.green, data.blue);
    fflush(log_file); // Flush the buffer to ensure data is written

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (tcs34725_init() != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        color_data_t color_data = tcs34725_read_color();
        log_color_data(color_data);
        gpioDelay(1000000); // 1 second delay using gpioDelay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

