#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0

// Define GPIO pins for CE0 (not directly used, but good to document)
#define CE0_PIN 8 // GPIO8 (BCM)

// Define MCP3008 channels for the moisture sensors
#define SENSOR1_CHANNEL 0
#define SENSOR2_CHANNEL 1

// Define the log file name
#define LOG_FILE "moisture_log.csv"

// Global variables for SPI file descriptor and log file pointer
int spi_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
int log_data(int moisture1, int moisture2);
void signal_handler(int signal);

// Structure to hold SPI configuration
typedef struct {
    int fd;
    uint8_t mode;
    uint8_t bits_per_word;
    uint32_t speed;
} spi_config_t;

// SPI configuration
spi_config_t spi_config = {
    .fd = -1,
    .mode = SPI_MODE,
    .bits_per_word = 8,
    .speed = 1000000 // 1 MHz
};

// Function to initialize the SPI interface
int spi_init(void) {
    spi_config.fd = open(SPI_DEVICE, O_RDWR);
    if (spi_config.fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(spi_config.fd, SPI_IOC_WR_MODE, &spi_config.mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_config.fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(spi_config.fd, SPI_IOC_WR_BITS_PER_WORD, &spi_config.bits_per_word) == -1) {
        perror("Error setting bits per word");
        close(spi_config.fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(spi_config.fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_config.speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_config.fd);
        return -1;
    }

    return 0;
}

// Function to read data from the MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct the SPI message to send to the MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = spi_config.speed;
    transfer[0].bits_per_word = spi_config.bits_per_word;

    if (ioctl(spi_config.fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to log the data to a CSV file
int log_data(int moisture1, int moisture2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get the current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Open the log file in append mode
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
        // Write the header if the file is newly created
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");
        }
    }

    // Write the data to the log file
    fprintf(log_file, "%s,%d,%d\n", timestamp, moisture1, moisture2);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Close the SPI device if it's open
    if (spi_config.fd != -1) {
        close(spi_config.fd);
        spi_config.fd = -1; // Reset the file descriptor
    }

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL; // Reset the file pointer
    }

    exit(0);
}

int main(void) {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the SPI interface
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    printf("Moisture sensor data logger started.\n");

    // Main loop
    while (1) {
        int moisture1, moisture2;

        // Read data from the moisture sensors
        moisture1 = read_mcp3008(SENSOR1_CHANNEL);
        if (moisture1 == -1) {
            fprintf(stderr, "Error reading sensor 1. Retrying in 5 seconds.\n");
            sleep(5);
            continue; // Skip logging and retry
        }

        moisture2 = read_mcp3008(SENSOR2_CHANNEL);
        if (moisture2 == -1) {
            fprintf(stderr, "Error reading sensor 2. Retrying in 5 seconds.\n");
            sleep(5);
            continue; // Skip logging and retry
        }

        // Log the data
        if (log_data(moisture1, moisture2) != 0) {
            fprintf(stderr, "Error logging data. Retrying in 5 seconds.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

