#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define MOTOR_CONTROL_GPIO 17
#define CURRENT_THRESHOLD 10.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
static volatile int running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
float adc_to_current(int adc_value);
int log_current(float current);
void control_motor(int state);
void signal_handler(int signal);
void cleanup(void);

// Structure for SPI configuration
typedef struct {
    int fd;
    uint8_t mode;
    uint8_t bits_per_word;
    uint32_t speed;
} spi_config_t;

// Initialize SPI
int spi_init(void) {
    int ret;
    spi_config_t config = {
        .fd = -1,
        .mode = SPI_MODE,
        .bits_per_word = SPI_BITS_PER_WORD,
        .speed = SPI_SPEED
    };

    config.fd = open(SPI_DEVICE, O_RDWR);
    if (config.fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    ret = ioctl(config.fd, SPI_IOC_WR_MODE, &config.mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(config.fd);
        return -1;
    }

    ret = ioctl(config.fd, SPI_IOC_WR_BITS_PER_WORD, &config.bits_per_word);
    if (ret == -1) {
        perror("Error setting SPI bits per word");
        close(config.fd);
        return -1;
    }

    ret = ioctl(config.fd, SPI_IOC_WR_MAX_SPEED_HZ, &config.speed);
    if (ret == -1) {
        perror("Error setting SPI speed");
        close(config.fd);
        return -1;
    }

    spi_fd = config.fd;
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];
    int ret;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer);
    if (ret < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    return ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
}

// Convert ADC reading to current (Amperes)
float adc_to_current(int adc_value) {
    // Assuming a linear relationship between ADC value and current
    // Adjust these values based on your sensor's datasheet and calibration
    float current = (float)adc_value / 1023.0 * 20.0; // Example: 0-1023 -> 0-20A
    return current;
}

// Log current to file
int log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen("current_log.csv", "a+");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }

        // Check if the file is empty, if so, write the header
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "Timestamp,Current (A)\n");
        }
        fseek(log_file, 0, SEEK_END); // Reset file pointer to the end
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Control motor (0 = off, 1 = on)
void control_motor(int state) {
    gpioWrite(MOTOR_CONTROL_GPIO, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    running = 0;
}

// Cleanup resources
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(MOTOR_CONTROL_GPIO, 1); // Ensure motor is off on exit
    gpioTerminate();
}

int main(void) {
    int adc_value;
    float current;
    int retries;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
