#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define PRESSURE_THRESHOLD 105.0 // kPa
#define SENT_RETRY_COUNT 3

// ADS1115 Registers
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration values
#define CONFIG_SINGLE_ENDED_0 0x4003 // AIN0, +/- 4.096V, Single-shot mode
#define CONFIG_SINGLE_ENDED_1 0x5003 // AIN1, +/- 4.096V, Single-shot mode
#define CONFIG_SINGLE_ENDED_2 0x6003 // AIN2, +/- 4.096V, Single-shot mode
#define CONFIG_SINGLE_ENDED_3 0x7003 // AIN3, +/- 4.096V, Single-shot mode

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function prototypes
int init_i2c();
int read_ads1115(int channel);
float convert_to_pressure(int raw_pressure);
float convert_to_temperature(int raw_temperature);
void control_led(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from ADS1115
int read_ads1115(int channel) {
    int config;
    switch (channel) {
        case 0:
            config = CONFIG_SINGLE_ENDED_0;
            break;
        case 1:
            config = CONFIG_SINGLE_ENDED_1;
            break;
        case 2:
            config = CONFIG_SINGLE_ENDED_2;
            break;
        case 3:
            config = CONFIG_SINGLE_ENDED_3;
            break;
        default:
            fprintf(stderr, "Invalid channel: %d\n", channel);
            return -1;
    }

    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing config to ADS1115\n");
        return -1;
    }

    // Wait for conversion to complete (at least 125ms for 8 SPS)
    gpioDelay(150000); // 150ms

    buf[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing register address for conversion\n");
        return -1;
    }

    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115\n");
        return -1;
    }

    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];
    return raw_value;
}

// Convert raw pressure reading to kPa (example conversion)
float convert_to_pressure(int raw_pressure) {
    // Replace with actual conversion formula from MLX90834 datasheet
    // This is a placeholder
    return (float)raw_pressure * 0.01; // Example: 0.01 kPa per raw unit
}

// Convert raw temperature reading to °C (example conversion)
float convert_to_temperature(int raw_temperature) {
    // Replace with actual conversion formula from NTC datasheet
    // This is a placeholder
    return (float)raw_temperature * 0.1 - 20.0; // Example: 0.1 °C per raw unit, offset
}

// Control the warning LED based on pressure
void control_led(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Pressure and Temperature Monitoring\n");

    while (!terminate) {
        // Read pressure and temperature
        int raw_pressure = read_ads1115(0);
        int raw_temperature = read_ads1115(1);

        if (raw_pressure == -1 || raw_temperature == -1) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100000); // 100ms delay before retry
            continue;
        }

        // Convert raw values to pressure and temperature
        float pressure = convert_to_pressure(raw_pressure);
        float temperature = convert_to_temperature(raw_temperature);

        // Control the LED
        control_led(pressure);

        // Print the results
        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

