            fprintf(stderr, "Invalid channel: %d\n", channel);
            return -1;
    }

    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing config to ADS1115\n");
        return -1;
