    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, current);
    fflush(log_file); // Flush to ensure data is written immediately
    printf("%s, %.2f\n", timestamp, current);
}

void shutdown_motor() {
    gpioWrite(config.motor_shutdown_gpio, 1); // Set GPIO HIGH
    printf("Motor shutdown!\n");
}

void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

