#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define ADS1115_CONFIG_OS_SINGLE (1 << 15) // Start a single conversion
#define ADS1115_CONFIG_MUX_AIN0GND (4 << 12) // AIN0 to ground
#define ADS1115_CONFIG_PGA_4_096V (2 << 9) // +/- 4.096V range
#define ADS1115_CONFIG_MODE_SINGLE (1 << 8) // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS (2 << 5) // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD (0 << 1) // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW (0 << 0) // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON (0 << 2) // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE (3 << 0) // Disable comparator

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int i2c_address;
    int sda_pin;
    int scl_pin;
    int sampling_rate;
    float min_pressure;
    float max_pressure;
    char *log_file_name;
} config_t;

// Function prototypes
int initialize_i2c(int sda_pin, int scl_pin, int i2c_address);
int16_t read_adc(int i2c_handle);
float convert_to_pressure(int16_t adc_value);
int validate_pressure(float pressure);
int log_pressure(float pressure, const char *timestamp);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c(int sda_pin, int scl_pin, int i2c_address) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(sda_pin, PI_ALT0); // Set SDA pin to ALT0
    gpioSetMode(scl_pin, PI_ALT0); // Set SCL pin to ALT0

    i2c_handle = i2cOpen(1, i2c_address, 0); // Open I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Reads the ADC value from the ADS1115
int16_t read_adc(int i2c_handle) {
    char config[3];
    int16_t adc_value;

    // Configure the ADS1115 for a single conversion
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0GND | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE) >> 8;
    config[2] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0GND | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE) & 0xFF;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write configuration to ADS1115\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10); // Wait 10ms

    // Read the conversion result
    char buffer[2];
    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Failed to read ADC value from ADS1115\n");
        return -1;
    }

    adc_value = (buffer[0] << 8) | buffer[1];

    // The ADS1115 returns a signed 16-bit value, but we only care about the magnitude for pressure.
    // If the value is negative, it indicates an error or an out-of-range reading.
    if (adc_value < 0) {
        fprintf(stderr, "ADC value is negative: %d\n", adc_value);
        return -1; // Indicate an error
    }

    return adc_value;
}

// Converts the ADC value to a pressure reading in kPa
float convert_to_pressure(int16_t adc_value) {
    // Assuming a linear relationship between ADC value and pressure
    // and that the ADC range is 0-32767 (2^15 - 1)
    // and the pressure range is 0-100 kPa
    float pressure = (float)adc_value / 32767.0 * 100.0;
    return pressure;
}

// Validates the pressure reading
int validate_pressure(float pressure) {
    if (pressure >= 0.0 && pressure <= 100.0) {
        return 0; // Valid
    } else {
        fprintf(stderr, "Pressure reading out of range: %.2f kPa\n", pressure);
        return -1; // Invalid
    }
}

// Logs the pressure reading to a file
int log_pressure(float pressure, const char *timestamp) {
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(log_file);
    return 0;
}

// Gets the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

int main() {
    config_t config = {
        .i2c_address = ADS1115_ADDR,
        .sda_pin = 2,
        .scl_pin = 3,
        .sampling_rate = 1,
        .min_pressure = 0.0,
        .max_pressure = 100.0,
        .log_file_name = "pressure_log.txt"
    };

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c(config.sda_pin, config.scl_pin, config.i2c_address) != 0) {
        return 1;
    }

    printf("Pressure sensor data acquisition started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int16_t adc_value = read_adc(i2c_handle);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert to pressure
        float pressure = convert_to_pressure(adc_value);

        // Validate pressure
        if (validate_pressure(pressure) == 0) {
            // Get timestamp
            char* timestamp = get_iso8601_timestamp();

            // Log pressure
            if (log_pressure(pressure, timestamp) != 0) {
                fprintf(stderr, "Error logging pressure data\n");
            }

            free(timestamp); // Free the allocated memory

            printf("Pressure: %.2f kPa, Timestamp: %s\n", pressure, timestamp);
        } else {
            fprintf(stderr, "Invalid pressure reading\n");
        }

        gpioDelay(1000); // Sample at 1 Hz
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

