#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define TMP36_VREF 3.3
#define TMP36_VOLTAGE_AT_0C 0.5
#define TMP36_VOLTAGE_SCALE 0.01
#define TEMP_MIN -40.0
#define TEMP_MAX 125.0
#define LOG_FILE "temperature_log.csv"

// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_adc(int channel);
float adc_to_temperature(int adc_value);
int log_temperature(float temperature);
void signal_handler(int signal);
void cleanup(void);

// Structure for SPI configuration
typedef struct {
    int fd;
    int mode;
    int bits_per_word;
    int speed;
} spi_config_t;

// Initialize SPI
int spi_init(void) {
    spi_config_t config = {
        .fd = -1,
        .mode = SPI_MODE,
        .bits_per_word = SPI_BITS_PER_WORD,
        .speed = SPI_SPEED
    };

    config.fd = open(SPI_DEVICE, O_RDWR);
    if (config.fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(config.fd, SPI_IOC_WR_MODE, &config.mode) == -1) {
        perror("Error setting SPI mode");
        close(config.fd);
        return -1;
    }

    if (ioctl(config.fd, SPI_IOC_WR_BITS_PER_WORD, &config.bits_per_word) == -1) {
        perror("Error setting SPI bits per word");
        close(config.fd);
        return -1;
    }

    if (ioctl(config.fd, SPI_IOC_WR_MAX_SPEED_HZ, &config.speed) == -1) {
        perror("Error setting SPI speed");
        close(config.fd);
        return -1;
    }

    return config.fd;
}

// Read ADC value from MCP3208
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Convert ADC value to temperature in Celsius
float adc_to_temperature(int adc_value) {
    float voltage = (float)adc_value * TMP36_VREF / 1024.0;
    float temperature = (voltage - TMP36_VOLTAGE_AT_0C) / TMP36_VOLTAGE_SCALE;
    return temperature;
}

// Log temperature to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a+");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }

        // Check if the file is empty, if so, write the header
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "timestamp,temperature_celsius\n");
        }
        fseek(log_file, 0, SEEK_END); // Reset file pointer to the end
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init();
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to temperature
        float temperature = adc_to_temperature(adc_value);

        // Validate temperature range
        if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
            fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
            continue; // Skip logging if temperature is out of range
        }

        // Log temperature
        if (log_temperature(temperature) != 0) {
            fprintf(stderr, "Error logging temperature\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    printf("Temperature monitoring stopped.\n");
    return 0;
}

