#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define ICP10125_ADDR 0x68 // Or 0x69, check your sensor
#define MEASURE_CMD 0x24 // High precision measurement command
#define DATA_LENGTH 6
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration coefficients (example values, replace with your sensor's actual values)
float c0 = 100.0;   // Example calibration coefficient
float c1 = 0.01;    // Example calibration coefficient
float c00 = 50.0;   // Example calibration coefficient
float c10 = 0.001;  // Example calibration coefficient
float c01 = 0.0001; // Example calibration coefficient
float c11 = 0.00001; // Example calibration coefficient

// Structure to hold raw sensor data
typedef struct {
    uint32_t pressure_raw;
    uint32_t temperature_raw;
} raw_data_t;

// Structure to hold calibrated sensor data
typedef struct {
    float temperature;
    float pressure;
} calibrated_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(raw_data_t *raw_data);
calibrated_data_t calibrate_data(const raw_data_t *raw_data);
int log_data(const calibrated_data_t *data);
void display_data(const calibrated_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICP10125_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(raw_data_t *raw_data) {
    char buf[DATA_LENGTH];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, MEASURE_CMD, 0); // No argument for the command
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for conversion (adjust as needed based on sensor datasheet)
    gpioDelay(10); // 10 ms delay

    // Read data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, DATA_LENGTH);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Combine MSB and LSB for pressure and temperature
    raw_data->pressure_raw = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | (uint32_t)buf[2];
    raw_data->temperature_raw = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | (uint32_t)buf[5];

    return 0;
}

// Function to calibrate sensor data
calibrated_data_t calibrate_data(const raw_data_t *raw_data) {
    calibrated_data_t calibrated_data;

    // Apply calibration formulas (replace with actual formulas from datasheet)
    calibrated_data.temperature = c0 + c1 * raw_data->temperature_raw;
    calibrated_data.pressure = c00 + c10 * raw_data->pressure_raw + c01 * raw_data->temperature_raw + c11 * raw_data->pressure_raw * raw_data->temperature_raw;

    return calibrated_data;
}

// Function to log data to file
int log_data(const calibrated_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->temperature, data->pressure);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to display data on console
void display_data(const calibrated_data_t *data) {
    printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", data->temperature, data->pressure);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Pressure (Pa)\n");
    }
    rewind(log_file);

    raw_data_t raw_data;
    calibrated_data_t calibrated_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_data) == 0) {
            // Calibrate data
            calibrated_data = calibrate_data(&raw_data);

            // Log data
            log_data(&calibrated_data);

            // Display data
            display_data(&calibrated_data);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying in %d seconds...\n", SAMPLE_INTERVAL);
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

