#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define MCP3008 channel assignments
#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global variables for SPI handle and program state
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Structure to hold microphone gains
typedef struct {
    int mic1_gain;
    int mic2_gain;
} MicrophoneGains;

// Function prototypes
int read_mcp3008(int channel);
int apply_noise_cancellation(int mic1_sample, int mic2_sample, int mic1_gain, int mic2_gain);
void print_csv(int mic1_sample, int mic2_sample, int noise_cancellation_result);
void signal_handler(int signal);
int initialize_spi();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to apply a basic noise-cancellation algorithm
int apply_noise_cancellation(int mic1_sample, int mic2_sample, int mic1_gain, int mic2_gain) {
    // Simple noise cancellation: subtract microphone 2 from microphone 1
    // Apply gain control
    int result = (mic1_sample * mic1_gain) - (mic2_sample * mic2_gain);
    return result;
}

// Function to print the audio samples in CSV format
void print_csv(int mic1_sample, int mic2_sample, int noise_cancellation_result) {
    printf("%d,%d,%d\n", mic1_sample, mic2_sample, noise_cancellation_result);
}

// Function to clean up resources before exiting
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Check for correct number of command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <mic1_gain> <mic2_gain>\n", argv[0]);
        return 1;
    }

    // Parse microphone gain values from command-line arguments
    int mic1_gain = atoi(argv[1]);
    int mic2_gain = atoi(argv[2]);

    // Validate microphone gain values
    if (mic1_gain < 0 || mic1_gain > 100 || mic2_gain < 0 || mic2_gain > 100) {
        fprintf(stderr, "Error: Microphone gain values must be between 0 and 100.\n");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI interface
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read audio samples from microphones
        int mic1_sample = read_mcp3008(MIC1_CHANNEL);
        int mic2_sample = read_mcp3008(MIC2_CHANNEL);

        // Check for errors during ADC reading
        if (mic1_sample < 0 || mic2_sample < 0) {
            fprintf(stderr, "Error reading ADC values. Retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        // Apply noise cancellation
        int noise_cancellation_result = apply_noise_cancellation(mic1_sample, mic2_sample, mic1_gain, mic2_gain);

        // Print the audio samples in CSV format
        print_csv(mic1_sample, mic2_sample, noise_cancellation_result);

        // Delay to control sampling rate
        gpioDelay(1000); // 1ms delay
    }

    // Clean up resources before exiting
    cleanup();

    return 0;
}

