#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define ADC_MAX_VALUE 1023
#define VREF 3.3 // Reference voltage

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init();
int read_adc(int channel);
float adc_to_voltage(int adc_value);
float read_ambient_temperature();
float compensate_voltage(float voltage, float temperature);
int log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void signal_handler(int signal);
void cleanup();

// SPI initialization function
int spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", SPI_DEVICE);
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode\n");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting SPI speed\n");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    // Validate ADC value
    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / ADC_MAX_VALUE) * VREF;
}

// Function to read ambient temperature from file
float read_ambient_temperature() {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file, using default 25.0\n");
        return 25.0;
    }

    float temperature;
    if (fscanf(fp, "%f", &temperature) != 1) {
        fprintf(stderr, "Error reading temperature from file, using default 25.0\n");
        fclose(fp);
        return 25.0;
    }

    fclose(fp);
    return temperature;
}

// Function to compensate voltage based on temperature
float compensate_voltage(float voltage, float temperature) {
    // Simple linear compensation (example)
    return voltage * (1.0 + 0.01 * (temperature - 25.0)); // Adjust 0.01 as needed
}

// Function to log data to file
int log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.1f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed, exiting...\n");
        program_running = 0;
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off initially

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read ADC value
        int adc_value = -1;
        for (int i = 0; i < 3; i++) {
            adc_value = read_adc(0);
            if (adc_value >= 0) break; // Success, exit retry loop
            fprintf(stderr, "ADC read failed, retrying (%d/3)\n", i + 1);
            usleep(100000); // 100ms delay
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after multiple retries\n");
            usleep(500000); // Wait 500ms before next attempt
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Read ambient temperature
        float temperature = read_ambient_temperature();

        // Compensate voltage
        float compensated_voltage = compensate_voltage(voltage, temperature);

        // Determine flame detection status
        int flame_detected = (compensated_voltage < 1.0) ? 1 : 0; // Example threshold

        // Log data
        log_data(adc_value, voltage, compensated_voltage, temperature, flame_detected);

        // Control buzzer
        gpioWrite(BUZZER_GPIO, flame_detected);

        usleep(500000); // Sample every 500ms
    }

    cleanup();
    return 0;
}

