// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0       // Mode 0
#define LED_GPIO 17
#define WATER_LEVEL_THRESHOLD_HIGH 75
#define WATER_LEVEL_THRESHOLD_LOW 70
#define SLEEP_DURATION_MS 100
#define READ_INTERVAL_S 5

// Global variables
int spi_handle;
FILE *json_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_percentage(int adc_value);
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size);
int write_json_entry(const char* timestamp, float percentage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate water level percentage
float calculate_percentage(int adc_value) {
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to get ISO 8601 timestamp with millisecond precision
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp_str + strlen(timestamp_str), timestamp_str_size - strlen(timestamp_str), ".%03ldZ", ts.tv_nsec / 1000000);

    return timestamp_str;
}

// Function to write JSON entry to file
int write_json_entry(const char* timestamp, float percentage) {
    if (json_file == NULL) {
        fprintf(stderr, "Error: JSON file is not open.\n");
        return -1;
    }

    fprintf(json_file, "{\"timestamp\": \"%s\", \"percentage\": %.2f},\n", timestamp, percentage);
    fflush(json_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stdout, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Turn LED off initially

    // Open JSON file
    json_file = fopen("water_levels.json", "a");
    if (json_file == NULL) {
        fprintf(stderr, "Error: Failed to open JSON file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Write opening bracket for JSON array
    fprintf(json_file, "[\n");
    fflush(json_file);

    return 0;
}

// Cleanup function
void cleanup() {
    // Close SPI channel
    spiClose(spi_handle);

    // Turn off LED
    gpioWrite(LED_GPIO, 0);

    // Terminate pigpio library
    gpioTerminate();

    // Close JSON file
    if (json_file != NULL) {
        // Seek to the beginning of the file to overwrite the opening bracket
        fseek(json_file, 0, SEEK_SET);
        fprintf(json_file, "[]");
        fclose(json_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    char timestamp_str[30];
    int adc_value;
    float percentage;

    // Main loop
    while (!terminate) {
        // Read ADC value
        adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate water level percentage
        percentage = calculate_percentage(adc_value);

        // Get timestamp
        get_iso8601_timestamp(timestamp_str, sizeof(timestamp_str));

        // Print water level percentage
        printf("Water level: %.2f%%\n", percentage);

        // Write JSON entry
        if (write_json_entry(timestamp_str, percentage) != 0) {
            fprintf(stderr, "Error: Failed to write JSON entry\n");
        }

        // Control LED with hysteresis
        if (percentage > WATER_LEVEL_THRESHOLD_HIGH) {
            gpioWrite(LED_GPIO, 1); // Turn LED on
        } else if (percentage < WATER_LEVEL_THRESHOLD_LOW) {
            gpioWrite(LED_GPIO, 0); // Turn LED off
        }

        // Sleep for a short duration
        for (int i = 0; i < READ_INTERVAL_S / SLEEP_DURATION_MS; ++i) {
            gpioDelay(SLEEP_DURATION_MS * 1000); // pigpioDelay takes microseconds
        }
    }

    // Cleanup
    cleanup();

    return 0;
}

