    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to Liters Per Minute (LPM)
float adc_to_lpm(int adc_value) {
    // Assuming a linear relationship between ADC value and LPM
    // You'll need to calibrate this based on your specific sensor and setup
    // This is a placeholder; replace with your actual calibration data
    float lpm = (float)adc_value * 0.01; // Example: 0-1023 -> 0-10.23 LPM
    return lpm;
}

// Function to log data to a CSV file
int log_data(float lpm) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    // Check if the file exists and is empty to write the header
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        // File doesn't exist, create it and write the header
        log_file = fopen(LOG_FILE, "w");
