            if (log_file == NULL) {
                fprintf(stderr, "Error: Could not open log file for appending: %s\n", LOG_FILE);
                return -1;
            }
        }
    }

    // Write data to the log file
    fprintf(log_file, "%s,%.2f\n", timestamp, lpm);
    fclose(log_file);
    return 0;
}

