    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            cleanup();
            return 1;
        }

        // Convert ADC value to LPM
        float lpm = adc_to_lpm(adc_value);

        // Log data
        if (log_data(lpm) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
            cleanup();
            return 1;
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

