float adc_to_pressure(int adc_value);
void log_data(float pressure);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_baud;
    float vref;
    int adc_max;
    float pressure_max;
} config_t;

config_t config = {SPI_CHANNEL, SPI_BAUD, VREF, ADC_MAX, PRESSURE_MAX};

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to pressure (kPa)
float adc_to_pressure(int adc_value) {
    if (adc_value < 0 || adc_value > config.adc_max) {
        fprintf(stderr, "Error: ADC value out of range (%d)\n", adc_value);
        return -1.0;
    }

    // Convert ADC value to voltage
    float voltage = (float)adc_value / config.adc_max * config.vref;

    // Convert voltage to pressure (linear relationship)
    float pressure = voltage * (config.pressure_max / config.vref);

    return pressure;
}

