    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins (though pigpio handles SPI internally, setting modes is good practice)
    gpioSetMode(CE0_PIN, PI_OUTPUT);
    gpioSetMode(SCLK_PIN, PI_OUTPUT);
    gpioSetMode(MOSI_PIN, PI_OUTPUT);
    gpioSetMode(MISO_PIN, PI_INPUT);

    // Open SPI channel
