#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPi.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_REG_CONFIG_DEFAULT 0x8383 // Single-shot, AIN0, +/-4.096V, 128 SPS
#define GPIO_RELAY 17
#define GPIO_DOOR_SENSOR 27
#define LOG_FILE "/var/log/door_events.log"
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_DELAY_MS 50
#define SAMPLE_DELAY_MS 200
#define RELAY_PULSE_MS 3000
#define THRESHOLD_PERCENTAGE 0.8 // 80% of baseline

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_ads1115(int fd, int16_t *value);
int write_ads1115_config(int fd, uint16_t config);
int read_relay_state(int gpio);
int write_relay_state(int gpio, int state);
int read_door_sensor(int gpio);
void log_event(const char *message);
void signal_handler(int sig);
int calibrate_sensor(int fd, int16_t *baseline);
int monitor_distance(int fd, int16_t baseline);

// Function to initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from ADS1115
int read_ads1115(int fd, int16_t *value) {
    uint8_t buf[2];
    uint16_t raw_value;

    // Set the ADS1115 to single-shot mode
    if (write_ads1115_config(fd, ADS1115_REG_CONFIG_DEFAULT) < 0) {
        log_event("Error configuring ADS1115 for single-shot read");
        return -1;
    }

    // Wait for conversion to complete (at least 125ms for 8 SPS)
    delay(125);

    // Read the conversion register
    if (read(fd, buf, 2) != 2) {
        log_event("Error reading from ADS1115");
        return -1;
    }

    raw_value = (buf[0] << 8) | buf[1];
    *value = (int16_t)raw_value;

    return 0;
}

// Function to write to ADS1115 configuration register
int write_ads1115_config(int fd, uint16_t config) {
    uint8_t buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (write(fd, buf, 3) != 3) {
        perror("Error writing to ADS1115 config register");
        return -1;
    }

    return 0;
}

// Function to read relay state
int read_relay_state(int gpio) {
    return digitalRead(gpio);
}

// Function to write relay state
int write_relay_state(int gpio, int state) {
    digitalWrite(gpio, state);
    return 0;
}

// Function to read door sensor state
int read_door_sensor(int gpio) {
    return digitalRead(gpio);
}

// Function to log events
void log_event(const char *message) {
    if (log_file == NULL) return;

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    fprintf(log_file, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, message);
    fflush(log_file);
}

// Signal handler
void signal_handler(int sig) {
    keep_running = 0;
    log_event("Received signal, shutting down...");
    write_relay_state(GPIO_RELAY, LOW); // De-energize relay
    if (i2c_fd != -1) close(i2c_fd);
    if (log_file != NULL) fclose(log_file);
    exit(0);
}

// Function to calibrate the sensor
int calibrate_sensor(int fd, int16_t *baseline) {
    int16_t sum = 0;
    int16_t value;

    log_event("Starting sensor calibration...");
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (read_ads1115(fd, &value) < 0) {
            log_event("Error reading sensor during calibration");
            return -1;
        }
        sum += value;
        delay(CALIBRATION_DELAY_MS);
    }

    *baseline = sum / CALIBRATION_SAMPLES;
    char message[100];
    snprintf(message, sizeof(message), "Calibration complete. Baseline: %d", *baseline);
    log_event(message);
    return 0;
}

// Function to monitor distance and control relay
int monitor_distance(int fd, int16_t baseline) {
    int16_t value;
    int threshold = (int)(baseline * THRESHOLD_PERCENTAGE);

    while (keep_running) {
        if (read_ads1115(fd, &value) < 0) {
            log_event("Error reading sensor, retrying...");
            delay(100); // Wait before retrying
            continue;
        }

        char message[100];
        snprintf(message, sizeof(message), "Sensor reading: %d, Threshold: %d", value, threshold);
        log_event(message);

        if (value < threshold) {
            log_event("Threshold breached, activating relay...");
            write_relay_state(GPIO_RELAY, HIGH); // Energize relay
            delay(RELAY_PULSE_MS);
            write_relay_state(GPIO_RELAY, LOW);  // De-energize relay

            int door_state = read_door_sensor(GPIO_DOOR_SENSOR);
            if (door_state == LOW) {
                log_event("Door opened");
            } else {
                log_event("Door not opened");
            }
        }

        delay(SAMPLE_DELAY_MS);
    }

    return 0;
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO modes
    pinMode(GPIO_RELAY, OUTPUT);
    pinMode(GPIO_DOOR_SENSOR, INPUT);
    pullUpDnControl(GPIO_DOOR_SENSOR, PUD_UP); // Enable pull-up resistor

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, ADS1115_ADDR);
    if (i2c_fd < 0) {
        log_event("I2C initialization failed");
        fclose(log_file);
        return 1;
    }

    // Calibrate sensor
    int16_t baseline;
    if (calibrate_sensor(i2c_fd, &baseline) < 0) {
        log_event("Sensor calibration failed");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Monitor distance and control relay
    monitor_distance(i2c_fd, baseline);

    // Cleanup (should not reach here if signal handler works correctly)
    close(i2c_fd);
    fclose(log_file);
    return 0;
}

