#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <wiringPi.h>

// Define GPIO pins for chip select lines
#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25

// Define SPI device
#define SPI_DEVICE "/dev/spidev0.0"

// Global variables
int spi_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init(void);
int read_adc(int chip_select_pin, int channel);
int log_data(int sensor1_value, int sensor2_value, int sensor3_value);
void signal_handler(int signal);
void cleanup(void);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// SPI initialization function
int spi_init(void) {
    int ret;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE_0;
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = 1000000; // 1 MHz
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read ADC value from MCP3008
int read_adc(int chip_select_pin, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];
    int ret;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Dummy byte

    // Configure SPI transfer
    memset(transfer, 0, sizeof(transfer));
    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    // Manually control chip select
    digitalWrite(chip_select_pin, LOW);
    delayMicroseconds(10); // Small delay after CS assertion

    // Perform SPI transfer
    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer);
    if (ret < 0) {
        perror("Error during SPI transfer");
        digitalWrite(chip_select_pin, HIGH);
        return -1;
    }

    digitalWrite(chip_select_pin, HIGH);
    delayMicroseconds(10); // Small delay after CS deassertion

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to log data to CSV file
int log_data(int sensor1_value, int sensor2_value, int sensor3_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current timestamp
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Check if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
    }

    // Write data to CSV file
    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, sensor3_value);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up...\n");

    // Close SPI device
    if (spi_fd > 0) {
        close(spi_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Reset GPIO pins to input mode (safer)
    pinMode(CS0_PIN, INPUT);
    pinMode(CS1_PIN, INPUT);
    pinMode(CS2_PIN, INPUT);

    printf("Cleanup complete.\n");
}

int main(void) {
    int sensor1_value, sensor2_value, sensor3_value;

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Set chip select pins as output
    pinMode(CS0_PIN, OUTPUT);
    pinMode(CS1_PIN, OUTPUT);
    pinMode(CS2_PIN, OUTPUT);

    // Initialize SPI
    if (spi_init() == -1) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("soil_moisture_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        sensor1_value = read_adc(CS0_PIN, 0);
        sensor2_value = read_adc(CS1_PIN, 0);
        sensor3_value = read_adc(CS2_PIN, 0);

        // Log data
