#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define PUMP_GPIO 18
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP 60
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
int threshold = DEFAULT_THRESHOLD;
int duration = DEFAULT_DURATION;
int sleep_interval = DEFAULT_SLEEP;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int control_pump(int state);
int log_message(const char *message);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[]);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message("Error: Invalid MCP3008 channel.");
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) == 0) {
            int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "SPI transfer failed (attempt %d).", retries + 1);
            log_message(error_message);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    log_message("Error: SPI transfer failed after multiple retries.");
    return -1;
}

// Function to control the water pump
int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        log_message("Error: Failed to write to GPIO.");
        return -1;
    }
    return 0;
}

// Function to log messages with timestamps
int log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure the message is written to the file immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_message("Received signal, shutting down...");
}

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                if (threshold < 0 || threshold > 100) {
                    fprintf(stderr, "Error: Threshold must be between 0 and 100.\n");
                    return -1;
                }
                break;
            case 'd':
                duration = atoi(optarg);
                if (duration <= 0) {
                    fprintf(stderr, "Error: Duration must be a positive integer.\n");
                    return -1;
                }
                break;
            case 's':
                sleep_interval = atoi(optarg);
                if (sleep_interval <= 0) {
                    fprintf(stderr, "Error: Sleep interval must be a positive integer.\n");
                    return -1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                return -1;
        }
    }
    return 0;
}

int main(int argc, char *argv[]) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Parse command-line arguments
    if (parse_arguments(argc, argv) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Configure GPIO for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially off

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        log_message("Error: Failed to open SPI channel.");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Irrigation system started.");

    while (!terminate) {
        // Read soil moisture sensor
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_message("Error: Failed to read ADC value.");
            gpioDelay(sleep_interval * 1000); // Sleep even if ADC read fails
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = ((float)adc_value / 1023.0) * 100.0;

        // Log moisture reading
        char log_message_buffer[100];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Moisture level: %.2f%% (ADC: %d)", moisture_percentage, adc_value);
        log_message(log_message_buffer);

        // Check if irrigation is needed
        if (moisture_percentage < threshold) {
            log_message("Moisture level below threshold, activating pump.");

            // Activate pump
            if (control_pump(1) == 0) {
                log_message("Pump activated.");
                gpioDelay(duration * 1000); // Run pump for specified duration

                // Deactivate pump
                if (control_pump(0) == 0) {
                    log_message("Pump deactivated.");
                } else {
                    log_message("Error: Failed to deactivate pump.");
                }
            } else {
                log_message("Error: Failed to activate pump.");
            }
        }

        // Sleep before next check
        gpioDelay(sleep_interval * 1000);
    }

    // Cleanup
    log_message("Shutting down irrigation system.");
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

