#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define SAMPLE_INTERVAL_MS 10
#define THRESHOLD_MULTIPLIER 1.5
#define MOVING_AVG_WINDOW_SIZE 10
#define LOG_FILE "/var/log/sound_events.log"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for moving average filter
typedef struct {
    float values[MOVING_AVG_WINDOW_SIZE];
    int index;
    int count;
} MovingAverageFilter;

// Function prototypes
int read_mcp3008(int channel);
float calculate_threshold(float moving_average);
void log_event(int adc_value);
void signal_handler(int signal);
void initialize_moving_average(MovingAverageFilter *filter);
float update_moving_average(MovingAverageFilter *filter, float new_value);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate the dynamic threshold
float calculate_threshold(float moving_average) {
    return moving_average * THRESHOLD_MULTIPLIER;
}

// Function to log events to a file
void log_event(int adc_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s,%d\n", timestamp, adc_value);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize moving average filter
void initialize_moving_average(MovingAverageFilter *filter) {
    for (int i = 0; i < MOVING_AVG_WINDOW_SIZE; i++) {
        filter->values[i] = 0.0;
    }
    filter->index = 0;
    filter->count = 0;
}

// Update moving average filter
float update_moving_average(MovingAverageFilter *filter, float new_value) {
    filter->values[filter->index] = new_value;
    filter->index = (filter->index + 1) % MOVING_AVG_WINDOW_SIZE;
    if (filter->count < MOVING_AVG_WINDOW_SIZE) {
        filter->count++;
    }

    float sum = 0.0;
    for (int i = 0; i < filter->count; i++) {
        sum += filter->values[i];
    }

    return sum / filter->count;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    MovingAverageFilter moving_average_filter;
    initialize_moving_average(&moving_average_filter);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Continue to the next iteration
        }

        // Update moving average
        float moving_average = update_moving_average(&moving_average_filter, (float)adc_value);

        // Calculate threshold
        float threshold = calculate_threshold(moving_average);

        // Detect peak
        if (adc_value > threshold) {
            log_event(adc_value);
            printf("Peak detected: ADC Value = %d, Threshold = %.2f\n", adc_value, threshold);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

