// PCF8591 I2C address
#define PCF8591_ADDR 0x48

// I2C bus number (typically 1 on Raspberry Pi)
#define I2C_BUS 1

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_fd = i2cOpen(I2C_BUS, PCF8591_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Dummy read to discard the previous conversion result
    char dummy_data[1];
    if (i2cReadDevice(i2c_fd, dummy_data, 1) != 1) {
        fprintf(stderr, "Dummy read failed\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop to continuously read the AIN0 channel
    while (1) {
        // Read the current 8-bit sample from AIN0
        char data[1];
        if (i2cReadDevice(i2c_fd, data, 1) != 1) {
            fprintf(stderr, "Failed to read data\n");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Print the 8-bit value to stdout
        printf("%d\n", (int)data[0]);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // The following lines will never be reached because of the infinite loop
    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
}

