#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define GPIO_SHUTDOWN 27
#define THRESHOLD_GAUSS 500.0
#define BUFFER_SIZE 10
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// ADS1115 Registers
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// ADS1115 Configuration Values
#define ADS1115_CONFIG_OS_SINGLE (1 << 15) // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 (4 << 12) // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V (2 << 9) // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE (1 << 8) // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS (2 << 5) // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD (0 << 1) // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW (0 << 0) // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON (0 << 2) // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE (3 << 0) // Disable comparator

// SS49E Sensor Parameters
#define SS49E_SENSITIVITY 0.002 // 2mV/Gauss
#define SS49E_ZERO_GAUSS_OUTPUT 2.5 // 2.5V at 0 Gauss

// Global Variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular Buffer Structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function Prototypes
int init_i2c();
int read_adc(int i2c_handle);
float adc_to_voltage(int adc_value);
float voltage_to_gauss(float voltage);
void circular_buffer_init(CircularBuffer *cb);
void circular_buffer_add(CircularBuffer *cb, float value);
float circular_buffer_average(CircularBuffer *cb);
void shutdown_gpio(int gpio_pin);
void signal_handler(int signal);
void cleanup();

// Function Implementations

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from ADS1115
int read_adc(int i2c_handle) {
    char config[3];
    int16_t adc_value;

    // Configure ADS1115 for single-ended AIN0, +/-4.096V, 128 SPS
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE) >> 8;
    config[2] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE) & 0xFF;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        syslog(LOG_ERR, "Failed to write configuration to ADS1115");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read ADC value
    char read_buffer[2];
    if (i2cReadDevice(i2c_handle, read_buffer, 2) != 2) {
        syslog(LOG_ERR, "Failed to read ADC value from ADS1115");
        return -1;
    }

    adc_value = (read_buffer[0] << 8) | read_buffer[1];

    // Sign extend 12-bit value
    if (adc_value & 0x800) {
        adc_value |= 0xF000; // Sign extend to 16 bits
    }

    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    // ADS1115 is a 16-bit ADC, but only 12 bits are used for the reading.
    // The remaining 4 bits are for the sign.
    // The full-scale range is +/- 4.096V, so each bit represents 8mV.
    return (float)adc_value * 8.0 / 32768.0; // 2^15 = 32768
}

// Convert voltage to magnetic field strength (Gauss)
float voltage_to_gauss(float voltage) {
    return (voltage - SS49E_ZERO_GAUSS_OUTPUT) / SS49E_SENSITIVITY;
}

// Initialize circular buffer
void circular_buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    memset(cb->buffer, 0, sizeof(cb->buffer));
}

// Add value to circular buffer
void circular_buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate average of values in circular buffer
float circular_buffer_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Shutdown GPIO
void shutdown_gpio(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set GPIO HIGH
    syslog(LOG_INFO, "Motor shutdown initiated!");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(GPIO_SHUTDOWN, 0); // Set GPIO LOW
    gpioTerminate();
    closelog();
}

int main() {
    // Initialize syslog
    openlog("hall_effect_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO_SHUTDOWN as output
    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, 0); // Set GPIO LOW initially

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer gauss_buffer;
    circular_buffer_init(&gauss_buffer);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Hall effect monitor started");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(i2c_handle);
        if (adc_value < 0) {
            syslog(LOG_WARNING, "Failed to read ADC value, skipping sample");
            gpioDelay(SAMPLE_PERIOD_US); // Wait for the next sample
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Validate voltage
        if (voltage < 0.0 || voltage > 3.3) {
            syslog(LOG_WARNING, "Voltage out of range: %.2f V", voltage);
            gpioDelay(SAMPLE_PERIOD_US); // Wait for the next sample
            continue;
        }

        // Convert voltage to Gauss
        float gauss = voltage_to_gauss(voltage);

        // Add Gauss value to circular buffer
        circular_buffer_add(&gauss_buffer, gauss);

        // Calculate rolling average
        float average_gauss = circular_buffer_average(&gauss_buffer);

        // Log data
        syslog(LOG_INFO, "ADC: %d, Voltage: %.2f V, Gauss: %.2f G, Average Gauss: %.2f G", adc_value, voltage, gauss, average_gauss);

        // Check threshold
        if (average_gauss > THRESHOLD_GAUSS) {
            shutdown_gpio(GPIO_SHUTDOWN);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

