            syslog(LOG_WARNING, "Voltage out of range: %.2f V", voltage);
            gpioDelay(SAMPLE_PERIOD_US); // Wait for the next sample
            continue;
        }

        // Convert voltage to Gauss
        float gauss = voltage_to_gauss(voltage);

        // Add Gauss value to circular buffer
        circular_buffer_add(&gauss_buffer, gauss);

        // Calculate rolling average
        float average_gauss = circular_buffer_average(&gauss_buffer);

        // Log data
        syslog(LOG_INFO, "ADC: %d, Voltage: %.2f V, Gauss: %.2f G, Average Gauss: %.2f G", adc_value, voltage, gauss, average_gauss);

        // Check threshold
        if (average_gauss > THRESHOLD_GAUSS) {
            shutdown_gpio(GPIO_SHUTDOWN);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

