                    log_event(adc_value);
                    gpioDelay(WATERING_DURATION * 1000000); // Water for 10 seconds
                    control_pump(0); // Deactivate pump
                    printf("Pump deactivated\n");
                }
            } else {
                fprintf(stderr, "Warning: Invalid ADC reading: %d\n", adc_value);
                invalid_readings++;
            }
        }

        if (invalid_readings > ADC_VALIDATION_THRESHOLD) {
            fprintf(stderr, "Error: Too many invalid ADC readings, exiting\n");
            terminate = 1;
        }

        gpioDelay(ADC_READ_DELAY * 1000000); // Delay for 60 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_pump(0); // Ensure pump is off
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

