#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int16_t read_adc();
double adc_to_gauss(int16_t adc_value);
void blink_led();
void signal_handler(int signal);
void cleanup();

// Structure for program configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_pin;
    double threshold;
} program_config;

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from ADS1115
int16_t read_adc() {
    char config[3];
    int16_t adc_value;

    // Configure ADS1115 for single-ended AIN0, PGA gain 4.096V, continuous conversion mode
    config[0] = CONFIG_REG;
    config[1] = 0xC2; // 0b11000010
    config[2] = 0x83; // 0b10000011

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 125ms for 8 SPS)
    gpioDelay(150);

    // Read conversion register
    char read_buf[2];
    if (i2cWriteDevice(i2c_handle, (char[]){CONVERSION_REG}, 1) != 0) {
        fprintf(stderr, "Failed to write to I2C device for reading\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
