double adc_to_gauss(int16_t adc_value) {
    // ADS1115 is a 16-bit ADC, but the sign bit is the 15th bit.
    // The resolution is 4.096V / 2^15 = 0.000125 V/LSB
    // The sensitivity of the SS49E is 2.5 mV/Gauss = 0.0025 V/Gauss
    // Therefore, Gauss = ADC_Value * (0.000125 V/LSB) / (0.0025 V/Gauss)
    return adc_value * 0.000125 / 0.0025;
