    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int pump_state = 0; // 0 = off, 1 = on
    float moisture;

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            moisture = calculate_moisture_percentage(adc_value);
            if (moisture >= 0.0) {
                syslog(LOG_INFO, "Moisture: %.2f%%", moisture);

                if (moisture < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
                    control_pump(1);
                    pump_state = 1;
                } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
                    control_pump(0);
                    pump_state = 0;
                }

                publish_moisture(moisture);
            } else {
                syslog(LOG_ERR, "Failed to calculate moisture percentage");
            }
        } else {
            syslog(LOG_ERR, "Failed to read ADC value");
        }

        sleep(SENSOR_READ_INTERVAL);
    }

    // Cleanup
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    spiClose(spi_handle);
    control_pump(0); // Ensure pump is off on exit
    gpioTerminate();
    closelog();

    return 0;
}

