#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3f
#define CSV_FILE "sensor_data.csv"
#define SLEEP_SECONDS 5

// Global variables for signal handling
static volatile int running = 1;
static int spi_handle = -1;
static FILE *fp = NULL;

// Function prototypes
int initialize_pigpio();
int open_spi_channel(int channel, int speed);
int read_mcp3008(int spi_handle, int channel);
float convert_to_voltage(int raw_value, float vref);
int write_to_csv(FILE *fp, float v0, float v1, float v2);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float v0;
    float v1;
    float v2;
} sensor_data_t;

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the SPI channel
int open_spi_channel(int channel, int speed) {
    int handle = spiOpen(channel, speed, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read from the MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct the SPI message to send to the MCP3008
    uint8_t tx_buffer[3];
    uint8_t rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer the SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract the 10-bit ADC value from the response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert the raw ADC value to a voltage
float convert_to_voltage(int raw_value, float vref) {
    return ((float)raw_value / 1023.0f) * vref;
}

// Function to write the sensor data to a CSV file
int write_to_csv(FILE *fp, float v0, float v1, float v2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, v0, v1, v2) < 0) {
        fprintf(stderr, "Error writing to CSV file\n");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open the SPI channel
    spi_handle = open_spi_channel(SPI_CHANNEL, SPI_SPEED);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open the CSV file in append mode
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read ADC values from channels 0, 1, and 2
        int raw_v0 = read_mcp3008(spi_handle, 0);
        int raw_v1 = read_mcp3008(spi_handle, 1);
        int raw_v2 = read_mcp3008(spi_handle, 2);

        if (raw_v0 < 0 || raw_v1 < 0 || raw_v2 < 0) {
            fprintf(stderr, "Error reading ADC values\n");
            break; // Exit the loop on error
        }

        // Convert ADC values to voltages
        float v0 = convert_to_voltage(raw_v0, VREF);
        float v1 = convert_to_voltage(raw_v1, VREF);
        float v2 = convert_to_voltage(raw_v2, VREF);

        // Write data to CSV file
        if (write_to_csv(fp, v0, v1, v2) != 0) {
            break; // Exit the loop on error
        }

        // Sleep for 5 seconds
        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();

    return 0;
}

