#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BH1750_ADDR 0x23
#define I2C_BUS 1
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_handle = -1;
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_db(int adc_value);
int read_bh1750();
float bh1750_to_lux(int raw_value);
int log_data(float sound_level_db, float light_level_lux, int error_code);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to dB (example formula)
float adc_to_db(int adc_value) {
    // This is a placeholder.  Calibration is needed for accurate dB readings.
    // The MAX9814 provides a logarithmic output, so a more complex conversion
    // might be required.
    return (float)adc_value * 0.1; // Example: 0-1023 -> 0-102.3 dB
}

// Function to read from BH1750 light sensor
int read_bh1750() {
    char config_cmd = 0x10; // Continuous high-resolution mode
    char data[2];

    if (i2cWriteDevice(i2c_handle, &config_cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to configure BH1750\n");
        return -1;
    }

    gpioDelay(180); // Wait for measurement (at least 180ms)

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read BH1750 data\n");
        return -1;
    }

    int raw_value = (data[0] << 8) | data[1];
    return raw_value;
}

// Function to convert BH1750 raw value to lux
float bh1750_to_lux(int raw_value) {
    return (float)raw_value / 1.2; // Example conversion
}

// Function to log data to CSV file
int log_data(float sound_level_db, float light_level_lux, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, sound_level_db, light_level_lux, error_code);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("tamper_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        float sound_level_db = 0.0;
        if (adc_value >= 0) {
            sound_level_db = adc_to_db(adc_value);
        } else {
            fprintf(stderr, "Error reading ADC, using default sound level\n");
        }

        int raw_light_value = read_bh1750();
        float light_level_lux = 0.0;
        if (raw_light_value >= 0) {
            light_level_lux = bh1750_to_lux(raw_light_value);
        } else {
            fprintf(stderr, "Error reading BH1750, using default light level\n");
        }

        int error_code = 0;
        if (adc_value < 0) error_code |= 1; // ADC error
        if (raw_light_value < 0) error_code |= 2; // BH1750 error

        log_data(sound_level_db, light_level_lux, error_code);

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

