// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_moisture(int adc_value);
void control_pump(int gpio_pin, int state);
void log_data(int sensor_id, float moisture_level);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to moisture percentage
float convert_to_moisture(int adc_value) {
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
void control_pump(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log data to the console
void log_data(int sensor_id, float moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Sensor %d: Moisture = %.2f%%\n", timestamp, sensor_id, moisture_level);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Monitoring and Irrigation System\n");

    while (!terminate) {
        int pump_on = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = -1;
            int retries = 3;

            // Retry reading from MCP3008 up to 3 times
            while (retries > 0) {
                adc_value = read_mcp3008(i);
                if (adc_value >= 0) {
                    break; // Success, exit retry loop
                }
                fprintf(stderr, "Error: Reading sensor %d failed, retrying...\n", i);
                gpioDelay(100); // Wait 100ms before retrying
                retries--;
            }

            if (adc_value < 0) {
                fprintf(stderr, "Error: Failed to read sensor %d after multiple retries\n", i);
                continue; // Skip to the next sensor
            }

            float moisture_level = convert_to_moisture(adc_value);
            log_data(i, moisture_level);

            if (moisture_level < MOISTURE_THRESHOLD) {
                pump_on = 1; // Turn pump on if any sensor is below threshold
            }
        }

        // Control the pump based on moisture levels
        control_pump(PUMP_GPIO, pump_on);

        gpioDelay(60000); // Wait 60 seconds
    }

    // Cleanup before exiting
    printf("Cleaning up...\n");
    control_pump(PUMP_GPIO, 0); // Turn pump off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

