    SPI_CHANNEL,
    RELAY_GPIO,
    DISTANCE_THRESHOLD,
    LOG_FILE
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    time_t last_detection_time = 0;

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        float distance = adc_to_distance(adc_value);

        time_t current_time = time(NULL);
        if (distance < config.distance_threshold) {
            if (current_time - last_detection_time > DEBOUNCE_DELAY) {
                control_relay(1); // Energize relay
                log_event(distance);
                last_detection_time = current_time;
            }
        } else {
            control_relay(0); // De-energize relay
        }

        gpioDelay(100); // Poll every 100 ms
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

