    float a = 27.0;  // Example value, adjust based on datasheet
    float b = 6.0;   // Example value, adjust based on datasheet

    // Convert ADC value to voltage (assuming 3.3V reference)
    float voltage = (float)adc_value * (3.3 / 1024.0);

    // Convert voltage to distance using the formula from the datasheet
    // This is a simplified example; refer to the GP2Y0A21YK0F datasheet for the correct formula
    float distance = a / (voltage + b);

    return distance;
}

void control_relay(int state) {
    gpioWrite(config.relay_gpio, state);
}

void log_event(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - Distance: %.2f cm - Door opened\n", timestamp, distance);
    fflush(log_file); // Ensure the log is written immediately
    printf("%s - Distance: %.2f cm - Door opened\n", timestamp, distance);
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

