#define NUM_SAMPLES 3
#define LOG_FILE "irrigation.log"
#define LOG_INTERVAL 5 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_average(int *samples, int num_samples);
void set_valve_position(int average);
void log_data(int *samples, int average, int valve_position);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate the average of an array of integers
float calculate_average(int *samples, int num_samples) {
    float sum = 0.0;
    int valid_samples = 0;
    for (int i = 0; i < num_samples; i++) {
        if (samples[i] >= 0) { // Consider only valid samples
            sum += samples[i];
            valid_samples++;
        }
    }
    if (valid_samples > 0) {
        return sum / valid_samples;
    } else {
        return 0.0; // Return 0 if no valid samples
    }
}

// Function to set the valve position using PWM
void set_valve_position(int average) {
    // Map the average ADC value (0-1023) to the PWM duty cycle (0-100)
    int duty_cycle = (int)((average / 1023.0) * PWM_RANGE);

    // Set the PWM duty cycle
    gpioPWM(VALVE_GPIO, duty_cycle);
}

// Function to log data to a file
void log_data(int *samples, int average, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %d, %d\n", timestamp, samples[0], samples[1], samples[2], average, valve_position);
    fflush(log_file); // Ensure data is written to the file immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI device
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output for PWM
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int samples[NUM_SAMPLES];
    int sample_index = 0;
    time_t last_log_time = time(NULL);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0); // Channel 0
        if (adc_value >= 0) {
            samples[sample_index] = adc_value;
            sample_index = (sample_index + 1) % NUM_SAMPLES;
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        // Calculate average and set valve position every NUM_SAMPLES readings
        if (sample_index == 0) {
            float average = calculate_average(samples, NUM_SAMPLES);
            set_valve_position((int)average);

            // Log data every LOG_INTERVAL seconds
            time_t current_time = time(NULL);
            if (difftime(current_time, last_log_time) >= LOG_INTERVAL) {
                log_data(samples, (int)average, gpioGetPWMdutycycle(VALVE_GPIO));
                last_log_time = current_time;
            }
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Graceful shutdown
    printf("Shutting down...\n");
    gpioPWM(VALVE_GPIO, 0); // Set valve PWM to 0
    spiClose(spi_handle); // Close SPI interface
    fclose(log_file); // Close log file
    gpioTerminate(); // Terminate pigpio library

    return 0;
}

