#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define RETRY_COUNT 5
#define BACKOFF_DELAY 100 // milliseconds
#define SAMPLE_INTERVAL 5 // seconds
#define LOG_FILE "soil_data.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_moisture_percentage(int adc_value);
void log_data(float moisture_percentage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int spi_mode;
    int mcp3008_channel;
    int retry_count;
    int backoff_delay;
    int sample_interval;
    char *log_file;
} config_t;

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read from the MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int adc_value = -1; // Initialize to an invalid value
    int retries = 0;
    int delay = BACKOFF_DELAY;

    // Construct the SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    while (retries < RETRY_COUNT) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract the ADC value from the response
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI read failed (attempt %d). Retrying in %d ms\n", retries + 1, delay);
            gpioDelay(delay);
            delay *= 2; // Exponential backoff
            retries++;
        }
    }

    fprintf(stderr, "SPI read failed after %d attempts\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// Function to convert ADC value to moisture percentage
float convert_to_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0; // Indicate error
    }
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to log data to a file
void log_data(float moisture_percentage) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Function to cleanup resources
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value != -1) {
            float moisture_percentage = convert_to_moisture_percentage(adc_value);
            if (moisture_percentage != -1.0) {
                log_data(moisture_percentage);
                printf("Moisture: %.2f%%\n", moisture_percentage);
            } else {
                FILE *fp = fopen(LOG_FILE, "a");
                if (fp != NULL) {
                    time_t t = time(NULL);
                    struct tm *tm = localtime(&t);
                    char timestamp[64];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
                    fprintf(fp, "%s, ERROR: Invalid ADC value\n", timestamp);
                    fclose(fp);
                }
            }
        } else {
            FILE *fp = fopen(LOG_FILE, "a");
            if (fp != NULL) {
                time_t t = time(NULL);
                struct tm *tm = localtime(&t);
                char timestamp[64];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
                fprintf(fp, "%s, ERROR: SPI read failed\n", timestamp);
                fclose(fp);
            }
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

