#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define PWM frequency
#define PWM_FREQUENCY 440 // Hz

// Define calibration parameters file
#define CONFIG_FILE "theremin_config.txt"

// Define error value for distance measurement
#define ERROR_DISTANCE -1.0

// Define timeout for ultrasonic sensor (in microseconds)
#define ULTRASONIC_TIMEOUT 50000 // 50ms

// Global variables
static volatile int running = 1;
static float min_distance = 0.0;
static float max_distance = 100.0;
static float min_volume = 0.0;
static float max_volume = 100.0;
static float last_valid_distance = 50.0; // Default distance
static float last_valid_volume = 50.0;   // Default volume

// Function prototypes
float measure_distance();
int read_ldr();
float map_distance_to_frequency(float distance);
float map_ldr_to_volume(int ldr_value);
void set_pwm_frequency(float frequency);
void set_pwm_duty_cycle(float volume);
void signal_handler(int signal);
int load_configuration();
int save_configuration();

// Function to measure distance using HC-SR04
float measure_distance() {
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);

    uint32_t start_tick = 0;
    uint32_t end_tick = 0;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < ULTRASONIC_TIMEOUT) {
        count++;
        gpioDelay(1); // Check every microsecond
    }

    if (count >= ULTRASONIC_TIMEOUT) {
        fprintf(stderr, "Error: Ultrasonic sensor timeout (echo low)\n");
        return ERROR_DISTANCE;
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < ULTRASONIC_TIMEOUT) {
        count++;
        gpioDelay(1); // Check every microsecond
    }

    if (count >= ULTRASONIC_TIMEOUT) {
        fprintf(stderr, "Error: Ultrasonic sensor timeout (echo high)\n");
        return ERROR_DISTANCE;
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (float)diff / 2.0 / 29.1; // Speed of sound: 29.1 us/cm

    return distance;
}

// Function to read LDR value from MCP3008
int read_ldr() {
    unsigned char buffer[3];
    buffer[0] = 0x01; // Start bit
    buffer[1] = 0x80; // Single-ended channel 0
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    if (distance == ERROR_DISTANCE) {
        return 440.0; // Default frequency
