#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define FAN_GPIO 18
#define LOG_FILE "air_quality.log"
#define MAX_RETRIES 3
#define RETRY_DELAY 1 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_aqi(int adc_value);
void control_fan(int aqi);
void log_data(int aqi);
void signal_handler(int signal);
int initialize_spi();
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract ADC value (10 bits)
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d/%d), retrying...\n", retries + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
            retries++;
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries. Re-initializing SPI.\n", MAX_RETRIES);
    spiClose(spi_handle);
    if (initialize_spi() != 0) {
        fprintf(stderr, "Failed to re-initialize SPI.\n");
        return -1;
    }
    return -1; // Indicate failure
}

// Calculate AQI (Air Quality Index)
float calculate_aqi(int adc_value) {
    // Simple linear mapping (replace with a more accurate calibration curve)
    // Assuming ADC value range: 0-1023
    // Assuming AQI range: 0-500
    float aqi = (float)adc_value / 1023.0 * 500.0;
    return aqi;
}

// Control the ventilation fan
void control_fan(int aqi) {
    if (aqi > 100) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
        printf("Fan ON (AQI: %d)\n", aqi);
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
        printf("Fan OFF (AQI: %d)\n", aqi);
    }
}

// Log data to file
void log_data(int aqi) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, AQI: %d\n", timestamp, aqi);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in 5 seconds.\n");
            gpioDelay(5000); // Wait 5 seconds
            continue;
        }

        // Calculate AQI
        float aqi = calculate_aqi(adc_value);

        // Control fan
        control_fan((int)aqi);

        // Log data
        log_data((int)aqi);

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

