#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25
#define SPI_CE0 8
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define PWM parameters
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000

// Define acceleration/deceleration parameters
#define ACCEL_TIME 2.0 // seconds
#define DECCEL_TIME 2.0 // seconds
#define HOLD_TIME 2.0 // seconds
#define REVERSE_DELAY 0.5 // seconds
#define PAUSE_TIME 5.0 // seconds

// Define motor directions
#define FORWARD 1
#define BACKWARD 0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int map_potentiometer_to_speed(int pot_value);
void set_motor_speed(int motor_enable_pin, int motor_direction_pin, int speed);
void accelerate(int motor_enable_pin, int motor_direction_pin, int target_speed);
void decelerate(int motor_enable_pin, int motor_direction_pin, int current_speed);
void reverse_direction(int motor_direction_pin);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to map potentiometer reading to motor speed
int map_potentiometer_to_speed(int pot_value) {
    // Map the potentiometer value (0-1023) to a speed value (0-1000)
    return (int)(((float)pot_value / 1023.0) * PWM_RANGE);
}

// Function to set motor speed using PWM
void set_motor_speed(int motor_enable_pin, int motor_direction_pin, int speed) {
    gpioPWM(motor_enable_pin, speed);
    gpioWrite(motor_direction_pin, FORWARD); // Set direction to forward
}

// Function to accelerate the motor
void accelerate(int motor_enable_pin, int motor_direction_pin, int target_speed) {
    int current_speed = 0;
    float increment = (float)target_speed / (ACCEL_TIME * PWM_FREQUENCY);
    int num_steps = (int)(ACCEL_TIME * PWM_FREQUENCY);

    for (int i = 0; i < num_steps; i++) {
        current_speed += increment;
        if (current_speed > target_speed) {
            current_speed = target_speed;
        }
        set_motor_speed(motor_enable_pin, motor_direction_pin, (int)current_speed);
        gpioDelay(1000000 / PWM_FREQUENCY); // Delay for 1/PWM_FREQUENCY seconds
    }
}

// Function to decelerate the motor
void decelerate(int motor_enable_pin, int motor_direction_pin, int current_speed) {
    float decrement = (float)current_speed / (DECCEL_TIME * PWM_FREQUENCY);
    int num_steps = (int)(DECCEL_TIME * PWM_FREQUENCY);

    for (int i = 0; i < num_steps; i++) {
        current_speed -= decrement;
        if (current_speed < 0) {
            current_speed = 0;
        }
        set_motor_speed(motor_enable_pin, motor_direction_pin, (int)current_speed);
        gpioDelay(1000000 / PWM_FREQUENCY); // Delay for 1/PWM_FREQUENCY seconds
    }
}

// Function to reverse motor direction
void reverse_direction(int motor_direction_pin) {
    gpioWrite(motor_direction_pin, BACKWARD); // Set direction to backward
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
