#define DEBOUNCE_TIME 10

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int calibrate_noise_level(int duration);
int is_above_threshold(int sample, int baseline, int threshold);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calibrate the noise level
int calibrate_noise_level(int duration) {
    int sum = 0;
    int num_samples = 0;
    time_t start_time = time(NULL);

    printf("Calibrating noise level for %d seconds...\n", duration);

    while (time(NULL) - start_time < duration) {
        int sample = read_mcp3008(0);
        if (sample == -1) {
            fprintf(stderr, "Error: Failed to read sample during calibration.\n");
            return -1;
        }
        sum += sample;
        num_samples++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (num_samples > 0) {
        return sum / num_samples;
    } else {
        fprintf(stderr, "Error: No samples collected during calibration.\n");
        return -1;
    }
}

// Function to check if the sound level is above the threshold
int is_above_threshold(int sample, int baseline, int threshold) {
    return (sample > (baseline + threshold));
}

