    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Configure LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Calibrate noise level
    int baseline = calibrate_noise_level(CALIBRATION_DURATION);
    if (baseline == -1) {
        fprintf(stderr, "Error: Noise level calibration failed.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Noise level baseline: %d\n", baseline);

    // Main loop
    int led_state = 0; // 0 = off, 1 = on
    time_t last_toggle_time = 0;

    while (!terminate) {
        // Read sound level
        int sample = read_mcp3008(0);
        if (sample == -1) {
            fprintf(stderr, "Error: Failed to read sample.\n");
            break; // Exit loop on error
        }

        // Check if sound level is above threshold
        if (is_above_threshold(sample, baseline, 50)) { // Threshold = 50
            time_t current_time = time(NULL);
            if (led_state == 0 && (current_time - last_toggle_time) * 1000 >= DEBOUNCE_TIME) {
                // Turn on LED
                gpioWrite(LED_PIN, 1);
                led_state = 1;
                last_toggle_time = current_time;
                printf("Sound detected! Sample: %d, Baseline: %d\n", sample, baseline);
            }
        } else {
            // Turn off LED
            gpioWrite(LED_PIN, 0);
            led_state = 0;
        }

        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn off LED
    spiClose(spi_handle); // Close SPI
    gpioTerminate(); // Terminate pigpio

    return 0;
}

