#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_PIN 8
#define SAMPLE_RATE 1000 // Hz
#define SAMPLE_PERIOD_NS (1000000000 / SAMPLE_RATE) // nanoseconds
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345

// Global variables
static volatile int keep_running = 1;
static int spi_fd = -1;
static int log_fd = -1;
static int socket_fd = -1;

// Function prototypes
int spi_init(const char *device);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);
void signal_handler(int sig);
int open_log_file(const char *filename);
int write_log_entry(int fd, uint32_t timestamp_ns, uint16_t adc_value);
int connect_to_server(const char *server_ip, int server_port);
int send_data_to_server(int socket_fd, uint32_t timestamp_ns, uint16_t adc_value);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully.\n");
    keep_running = 0;
}

// SPI initialization
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Configure SPI bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Configure SPI max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// GPIO export
int gpio_export(int pin) {
    char buffer[3];
    ssize_t bytes_written;
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd == -1) {
        fprintf(stderr, "Error opening /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }

    int len = snprintf(buffer, sizeof(buffer), "%d", pin);
    bytes_written = write(fd, buffer, len);
    close(fd);
    if (bytes_written < 0) {
        fprintf(stderr, "Error writing to /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// GPIO unexport
int gpio_unexport(int pin) {
    char buffer[3];
    ssize_t bytes_written;
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd == -1) {
        fprintf(stderr, "Error opening /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }

    int len = snprintf(buffer, sizeof(buffer), "%d", pin);
    bytes_written = write(fd, buffer, len);
    close(fd);
    if (bytes_written < 0) {
        fprintf(stderr, "Error writing to /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// GPIO set direction
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (write(fd, direction, strlen(direction)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO set value
int gpio_set_value(int pin, int value) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);

    if (write(fd, val_str, 1) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Open log file
int open_log_file(const char *filename) {
    int fd = open(filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Write log entry
int write_log_entry(int fd, uint32_t timestamp_ns, uint16_t adc_value) {
    char buffer[64];
    int len = snprintf(buffer, sizeof(buffer), "%u|%u\n", timestamp_ns, adc_value);
    if (len < 0 || len >= sizeof(buffer)) {
        fprintf(stderr, "Error formatting log entry.\n");
        return -1;
    }

    if (write(fd, buffer, len) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fsync(fd) < 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Connect to server
int connect_to_server(const char *server_ip, int server_port) {
    struct sockaddr_in server_addr;

    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported \n");
        close(socket_fd);
        return -1;
    }

    if (connect(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error connecting to server: %s\n", strerror(errno));
        close(socket_fd);
        return -1;
    }

    return 0;
}

// Send data to server
int send_data_to_server(int socket_fd, uint32_t timestamp_ns, uint16_t adc_value) {
    char buffer[64];
    int len = snprintf(buffer, sizeof(buffer), "%u|%u\n", timestamp_ns, adc_value);
    if (len < 0 || len >= sizeof(buffer)) {
        fprintf(stderr, "Error formatting data for server.\n");
        return -1;
    }

    if (send(socket_fd, buffer, len, 0) < 0) {
        fprintf(stderr, "Error sending data to server: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    // Export GPIO pin
    if (gpio_export(GPIO_PIN) < 0) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set GPIO direction to output
    if (gpio_set_direction(GPIO_PIN, "out") < 0) {
        gpio_unexport(GPIO_PIN);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_fd = open_log_file("audio_log.txt");
    if (log_fd < 0) {
        gpio_unexport(GPIO_PIN);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Connect to server
    if (connect_to_server(SERVER_IP, SERVER_PORT) < 0) {
        fprintf(stderr, "Failed to connect to server. Continuing without network logging.\n");
    }

    // Main loop
    struct timespec ts;
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    uint32_t timestamp_ns;
    uint16_t adc_value;

    while (keep_running) {
        // MCP3008 configuration: start bit, single-ended mode, channel 0
        tx_buf[0] = 0x01;  // Start bit
        tx_buf[1] = 0x80;  // Single-ended, channel 0
        tx_buf[2] = 0x00;  // Don't care

        // Select the ADC
        if (gpio_set_value(GPIO_PIN, 0) < 0) {
            fprintf(stderr, "Error setting GPIO value.\n");
            break;
        }

        // Transfer data
        if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
            fprintf(stderr, "Error during SPI transfer.\n");
            break;
        }

        // Deselect the ADC
        if (gpio_set_value(GPIO_PIN, 1) < 0) {
            fprintf(stderr, "Error setting GPIO value.\n");
            break;
        }

        // Extract ADC value
        adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        // Get timestamp
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) < 0) {
            fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
            break;
        }
        timestamp_ns = (uint32_t)ts.tv_sec * 1000000000 + (uint32_t)ts.tv_nsec;

        // Write to log file
        if (write_log_entry(log_fd, timestamp_ns, adc_value) < 0) {
            fprintf(stderr, "Error writing to log file.\n");
            break;
        }

        // Send data to server
        if (socket_fd != -1) {
            if (send_data_to_server(socket_fd, timestamp_ns, adc_value) < 0) {
                fprintf(stderr, "Error sending data to server.\n");
                close(socket_fd);
                socket_fd = -1; // Reset socket_fd to prevent further attempts
            }
        }

        // Sleep until next sample
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = SAMPLE_PERIOD_NS;
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
    if (socket_fd != -1) {
        close(socket_fd);
    }
    gpio_unexport(GPIO_PIN);

    return EXIT_SUCCESS;
}

