#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define LOG_FILE "gas_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_voltage(int adc_value);
void log_data(float voltage, float ppm);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Exiting gracefully...\n");
        terminate = 1;
    }
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (single-ended mode)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (error code %d)\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate voltage from ADC value
float calculate_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to log data to file
void log_data(float voltage, float ppm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Voltage: %.2f V, PPM: %.2f\n", timestamp, voltage, ppm);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (error code %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Propane Leak Detector running. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value. Retrying in 100ms...\n");
            gpioDelay(100); // 100ms delay
            continue; // Retry
        }

        float voltage = calculate_voltage(adc_value);
        float ppm = voltage * 100; // Placeholder PPM calculation

        printf("Voltage: %.2f V, PPM: %.2f\n", voltage, ppm);
        log_data(voltage, ppm);

        gpioDelay(1000); // 1 second delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

