#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define MCP3008_CS 8
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// ADXL335 sensitivity (300mV/g) and Vref (3.3V)
#define SENSITIVITY 0.300
#define VREF 3.3

// Global variables for SPI handle and program state
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Structure to hold Kalman filter parameters
typedef struct {
    float Q;       // Process noise covariance
    float R;       // Measurement noise covariance
    float P;       // Estimate error covariance
    float K;       // Kalman gain
    float x;       // Estimated state
} KalmanFilter;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_g(int adc_value);
void kalman_filter_init(KalmanFilter *kf, float process_noise, float measurement_noise);
float kalman_filter_update(KalmanFilter *kf, float measurement);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    gpioWrite(MCP3008_CS, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to acceleration in g
float convert_to_g(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    float acceleration = (voltage - VREF / 2.0) / SENSITIVITY;
    return acceleration;
}

// Initialize Kalman filter
void kalman_filter_init(KalmanFilter *kf, float process_noise, float measurement_noise) {
    kf->Q = process_noise;
    kf->R = measurement_noise;
    kf->P = 1.0; // Initial estimate error covariance
    kf->x = 0.0; // Initial state
}

// Update Kalman filter with new measurement
float kalman_filter_update(KalmanFilter *kf, float measurement) {
    // Prediction step
    float x_pred = kf->x;
    float P_pred = kf->P + kf->Q;

    // Update step
    kf->K = P_pred / (P_pred + kf->R);
    kf->x = x_pred + kf->K * (measurement - x_pred);
    kf->P = (1 - kf->K) * P_pred;

    return kf->x;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set MCP3008 CS pin as output
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008 initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize Kalman filters for each axis
    KalmanFilter x_kf, y_kf, z_kf;
    kalman_filter_init(&x_kf, 0.01, 0.1); // Adjust Q and R as needed
    kalman_filter_init(&y_kf, 0.01, 0.1);
    kalman_filter_init(&z_kf, 0.01, 0.1);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read ADC values from each channel
        int x_adc = read_mcp3008(0);
        int y_adc = read_mcp3008(1);
        int z_adc = read_mcp3008(2);

        if (x_adc == -1 || y_adc == -1 || z_adc == -1) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert ADC values to acceleration in g
        float x_g = convert_to_g(x_adc);
        float y_g = convert_to_g(y_adc);
        float z_g = convert_to_g(z_adc);

        // Apply Kalman filter
        float x_filtered = kalman_filter_update(&x_kf, x_g);
        float y_filtered = kalman_filter_update(&y_kf, y_g);
        float z_filtered = kalman_filter_update(&z_kf, z_g);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x_filtered, y_filtered, z_filtered);

        // Delay to achieve 10 Hz sampling rate
        gpioDelay(100); // 100 ms delay
    }

    // Clean up and exit
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

