        return -1; // Indicate an error
    }
    return value;
}

// Function to convert the sensor value to a magnetic field strength in millitesla
float convert_to_magnetic_field(int sensor_value) {
    float voltage = (float)sensor_value * MAX_VOLTAGE;
    float magnetic_field = (voltage / MAX_VOLTAGE) * (MAX_MAGNETIC_FIELD - MIN_MAGNETIC_FIELD) + MIN_MAGNETIC_FIELD;
    return magnetic_field;
}

// Function to log the magnetic field values to a file
