#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(int state);
void log_event(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Error: Invalid MCP3008 channel.");
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        log_event("Error: SPI transfer failed.");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    if (state == 1) {
        log_event("Pump turned ON.");
    } else {
        log_event("Pump turned OFF.");
    }
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    log_event("Signal received, shutting down...");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_event("Program started.");

    return 0;
}

// Cleanup function
void cleanup() {
    log_event("Program terminated.");
    control_pump(0); // Turn off pump
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    int pump_state = 0; // 0 = OFF, 1 = ON

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_event("Error reading ADC, retrying...");
            sleep(1); // Wait before retrying
            continue;
        }

        float moisture_percentage = calculate_moisture_percentage(adc_value);
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Moisture level: %.2f%%, ADC value: %d", moisture_percentage, adc_value);
        log_event(log_message);

        if (moisture_percentage < MOISTURE_THRESHOLD && pump_state == 0) {
            control_pump(1);
            pump_state = 1;
        } else if (moisture_percentage >= MOISTURE_THRESHOLD && pump_state == 1) {
            control_pump(0);
            pump_state = 0;
        }

        sleep(60); // Check every 60 seconds
    }

    cleanup();
    return 0;
}

