#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <mosquitto.h>
#include <jansson.h>
#include <pigpio.h>

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define GPIO_PIN 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to log errors with timestamps
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "%d-%02d-%02d %02d:%02d:%02d: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

// MQTT connect callback
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_error("MQTT connection failed");
    }
}

// MQTT message callback
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        json_error_t error;
        json_t *root = json_loads(message->payload, 0, &error);

        if (!root) {
            log_error("JSON parsing error");
            return;
        }

        json_t *led_state = json_object_get(root, "led_state");
        if (!led_state) {
            log_error("Missing 'led_state' key in JSON");
            json_decref(root);
            return;
        }

        if (!json_is_boolean(led_state)) {
            log_error("'led_state' is not a boolean");
            json_decref(root);
            return;
        }

        int state = json_boolean_value(led_state);
        gpioWrite(GPIO_PIN, state);

        json_decref(root);
    } else {
        log_error("Empty MQTT message received");
    }
}

// MQTT disconnect callback
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_error("MQTT disconnected unexpectedly");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signum) {
    running = 0;
    printf("Signal received, exiting...\n");
}

int main() {
    int rc = 0;
    int reconnect_delay = 1;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Turn LED off at startup

    // Initialize libmosquitto
    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create mosquitto instance");
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_message_callback_set(mosq, message_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Connect to MQTT broker with exponential backoff
    while (running) {
        rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
        if (rc == MOSQ_ERR_SUCCESS) {
            break;
        } else {
            log_error("MQTT connection failed, retrying...");
            sleep(reconnect_delay);
            reconnect_delay *= 2;
            if (reconnect_delay > 60) {
                reconnect_delay = 60;
            }
        }
    }

    if (!running) {
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Main loop
    while (running) {
        sleep(1);
    }

    // Clean up
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

