#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/gpio.h>
#include <sys/ioctl.h>
#include <poll.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "Signal received, terminating...\n");
}

int main() {
    int gpio_fd, log_fd;
    struct timespec ts;
    char timestamp[30];
    struct gpio_event_t event;
    struct gpio_pullUpDown_t pull_up_down = PI_PUD_UP; // Use pigpio's pull-up/down enum
    int rc;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, pull_up_down);

    // Open GPIO character device
    gpio_fd = gpioSetMode(GPIO_PIN, PI_INPUT); // Use gpioSetMode to open the GPIO
    if (gpio_fd < 0) {
        perror("Failed to open GPIO character device");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Wait for falling edge
        rc = gpioRead(GPIO_PIN);
        if (rc == 0) {
            // Vibration detected (falling edge)

            // Get current timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                perror("clock_gettime");
                break;
            }
            snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

            // Log event to file
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "%s Vibration detected on GPIO %d\n", timestamp, GPIO_PIN);
            if (write(log_fd, log_message, strlen(log_message)) == -1) {
                perror("Failed to write to log file");
                break;
            }

            // Print to stdout
            printf("%s Vibration detected on GPIO %d\n", timestamp, GPIO_PIN);

            // Initiate shutdown
            if (system("sudo shutdown -h now") == -1) {
                perror("Failed to initiate shutdown");
                break;
            }

            // Shutdown should occur, but in case it doesn't, break the loop
            break;
        } else if (rc < 0) {
            perror("gpioRead failed");
            break;
        }

        // Small delay to avoid busy-waiting
        usleep(10000); // 10ms
    }

    // Cleanup
    close(log_fd);
    gpioTerminate();

    return 0;
}

