#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SPI_BUS "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define MCP3008_CHANNEL 0
#define LOG_FILE "environmental_log.txt"

// Global variables for I2C and SPI file descriptors
int i2c_fd = -1;
int spi_fd = -1;

// Function prototypes
int bh1750_read_lux(int fd);
int mcp3008_read_adc(int fd, int channel);
char* format_log_entry(int lux, int adc_value);
int write_to_log(const char* log_entry);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

// Function to read light level from BH1750 sensor
int bh1750_read_lux(int fd) {
    unsigned char buf[2];
    int lux = -1; // Default to error value

    // Send start measurement command (High Resolution Mode)
    if (write(fd, "\x10", 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    // Wait for measurement to complete (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Convert data to lux value
    lux = (buf[0] << 8) | buf[1];
    lux /= 1.2; // Apply scaling factor

    return lux;
}

// Function to read analog value from MCP3008 ADC
int mcp3008_read_adc(int fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    // Perform SPI transaction
    if (ioctl(fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("SPI transaction failed");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to format log entry
char* format_log_entry(int lux, int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    static char log_entry[100]; // Static to persist across calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(log_entry, sizeof(log_entry), "%s, Light: %d, Sound: %d", timestamp, lux, adc_value);

    return log_entry;
}

// Function to write log entry to file
int write_to_log(const char* log_entry) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%s\n", log_entry);
    fclose(fp);

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Open SPI bus
    spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI bus");
        close(i2c_fd);
        return 1;
    }

    // Configure SPI mode
    unsigned char mode = 0; // SPI_MODE_0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int lux = bh1750_read_lux(i2c_fd);
        int adc_value = mcp3008_read_adc(spi_fd, MCP3008_CHANNEL);

        if (lux != -1 && adc_value != -1) {
            char* log_entry = format_log_entry(lux, adc_value);
            if (write_to_log(log_entry) == 0) {
                printf("Logged: %s\n", log_entry);
            } else {
                fprintf(stderr, "Failed to write log entry.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        sleep(1);
    }

    // Cleanup (should not reach here due to signal handler)
    close(i2c_fd);
    close(spi_fd);

    return 0;
}

