#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_PIN 17
#define LOG_FILE "flame_events.log"

static volatile int running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the flame sensor state
int read_flame_sensor() {
    int state = gpioRead(FLAME_SENSOR_PIN);
    if (state < 0) {
        fprintf(stderr, "Error reading flame sensor: %d\n", state);
        return -1; // Indicate an error
    }
    return state;
}

// Function to log the event to a CSV file
void log_event(int pin, int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, pin, state);
    fclose(fp);
}

// Function to print an alarm message
void print_alarm() {
    printf("ALARM: Flame detected!\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_DOWN);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_state = read_flame_sensor();
        if (sensor_state == -1) {
            // Error reading sensor, exit the loop
            break;
        }

        log_event(FLAME_SENSOR_PIN, sensor_state);

        if (sensor_state == 1) {
            print_alarm();
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Clean up GPIO resources
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

