#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define I2C_BUS 1
#define MCP4725_ADDR 0x60
#define VREF 3.3
#define TEMP_OFFSET 0.5
#define SAMPLE_INTERVAL 0.5 // seconds

// Global variables
int spi_handle = -1;
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_celsius(int adc_value);
int dac_to_voltage(float voltage);
int write_mcp4725(int dac_value);
int log_data(int adc_value, float temperature, float voltage);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float adc_to_celsius(int adc_value) {
    float voltage = (adc_value * VREF) / 1024.0;
    float temperature = (voltage - TEMP_OFFSET) * 100.0;
    return temperature;
}

// Function to convert temperature to DAC value
int dac_to_voltage(float voltage) {
    if (voltage < 0.0) voltage = 0.0;
    if (voltage > VREF) voltage = VREF;

    int dac_value = (int)((voltage / VREF) * 4095.0);
    return dac_value;
}

// Function to write to MCP4725 DAC
int write_mcp4725(int dac_value) {
    char i2c_tx_buf[3];

    // Construct I2C message (MCP4725 datasheet)
    i2c_tx_buf[0] = 0x40; // Write DAC register
    i2c_tx_buf[1] = (dac_value >> 4) & 0x0F; // Upper 4 bits
    i2c_tx_buf[2] = (dac_value << 4) & 0xF0; // Lower 4 bits

    if (i2cWriteDevice(i2c_handle, i2c_tx_buf, 3) != 0) {
        fprintf(stderr, "Error: I2C write failed\n");
        return -1;
    }

    return 0;
}

// Function to log data to file
int log_data(int adc_value, float temperature, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, voltage);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MCP4725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Retry
        }

        // Convert ADC value to Celsius
        float temperature = adc_to_celsius(adc_value);

        // Convert temperature to DAC value
        int dac_value = dac_to_voltage(temperature);

        // Write DAC value to MCP4725
        if (write_mcp4725(dac_value) < 0) {
            fprintf(stderr, "Error: Failed to write DAC value\n");
        }

        // Calculate voltage for logging
        float voltage = (dac_value / 4095.0) * VREF;

        // Log data
        log_data(adc_value, temperature, voltage);

        // Print data to stdout
        printf("ADC: %d, Temp: %.2f C, Voltage: %.2f V\n", adc_value, temperature, voltage);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000); // pigpioDelay takes milliseconds
    }

    // Clean up
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");
    return 0;
}

