#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Function prototypes
int initialize_gpio();
void activate_relay(int pin);
void deactivate_relay(int pin);
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop to control the relays
    while (program_running) {
        // Activate and deactivate each relay in sequence
        activate_relay(RELAY1_PIN);
        gpioDelay(1000000); // 1 second
        deactivate_relay(RELAY1_PIN);
        gpioDelay(1000000); // 1 second

        activate_relay(RELAY2_PIN);
        gpioDelay(1000000); // 1 second
        deactivate_relay(RELAY2_PIN);
        gpioDelay(1000000); // 1 second

        activate_relay(RELAY3_PIN);
        gpioDelay(1000000); // 1 second
        deactivate_relay(RELAY3_PIN);
        gpioDelay(1000000); // 1 second

        activate_relay(RELAY4_PIN);
        gpioDelay(1000000); // 1 second
        deactivate_relay(RELAY4_PIN);
        gpioDelay(1000000); // 1 second
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize all relays to inactive (LOW)
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    return 0;
}

// Function to activate a relay (set GPIO pin HIGH)
void activate_relay(int pin) {
    gpioWrite(pin, 1);
}

// Function to deactivate a relay (set GPIO pin LOW)
void deactivate_relay(int pin) {
    gpioWrite(pin, 0);
}

// Function to cleanup GPIO pins and terminate the pigpio library
void cleanup_gpio() {
    // Deactivate all relays
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();
}

// Signal handler function to catch SIGINT and SIGTERM signals
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

