    printf("Cleaning up resources...\n");

    // Close SPI interface
    spiClose(spi_handle);

    // Turn off LED
    gpioWrite(LED_GPIO, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();
}

