    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0); // Channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            log_event("Error: Failed to read ADC value");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        // Check if sound level exceeds threshold
        if (adc_value > SOUND_THRESHOLD) {
            printf("Sound detected! ADC value: %d\n", adc_value);

            // Turn on LED
            gpioWrite(LED_GPIO, 1);

            // Log event
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Sound detected, ADC value: %d", adc_value);
            log_event(log_message);

            // Wait for LED on duration
            gpioDelay(LED_ON_DURATION_MS);

            // Turn off LED
            gpioWrite(LED_GPIO, 0);

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY_MS);
        }

        // Sample interval
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

