// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define rain threshold
#define RAIN_THRESHOLD 5

// Define PWM range
#define PWM_RANGE 255

// Define motor run time
#define MOTOR_RUN_TIME 3 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rain_sensor();
void control_motor(int direction);
void log_data(int rain_level);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int in1_pin;
    int in2_pin;
    int ena_pin;
    int spi_channel;
    int spi_speed;
    int spi_mode;
    int rain_threshold;
    int pwm_range;
    int motor_run_time;
} Config;

Config config = {
    IN1, IN2, ENA, SPI_CHANNEL, SPI_SPEED, SPI_MODE, RAIN_THRESHOLD, PWM_RANGE, MOTOR_RUN_TIME
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int rain_level = read_rain_sensor();
        if (rain_level < 0) {
            fprintf(stderr, "Error reading rain sensor. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        if (rain_level > config.rain_threshold) {
            control_motor(1); // Close window
        } else {
            control_motor(0); // Open window
        }

        log_data(rain_level);
        sleep(1); // Poll every second
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(config.in1_pin, PI_OUTPUT);
    gpioSetMode(config.in2_pin, PI_OUTPUT);
    gpioSetMode(config.ena_pin, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(config.ena_pin, config.pwm_range);

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, config.spi_mode);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_rain_sensor() {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // MCP3008 configuration: single-ended, channel 0
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = 0x80; // Single-ended, channel 0
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract the ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    // Convert ADC value to rain level (example: linear mapping)
    int rain_level = adc_value; // Simplest mapping: ADC value = rain level

    return rain_level;
}

