    if (direction == 1) { // Close window
        gpioWrite(config.in1_pin, 1);
        gpioWrite(config.in2_pin, 0);
    } else { // Open window
        gpioWrite(config.in1_pin, 0);
        gpioWrite(config.in2_pin, 1);
    }

    gpioPWM(config.ena_pin, config.pwm_range / 2); // 50% duty cycle
    sleep(config.motor_run_time);
    gpioPWM(config.ena_pin, 0); // Stop motor
    gpioWrite(config.in1_pin, 0);
    gpioWrite(config.in2_pin, 0);
}

void log_data(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
}

void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(config.ena_pin, 0); // Stop motor
    gpioWrite(config.in1_pin, 0);
    gpioWrite(config.in2_pin, 0);

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

