#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define ADC_PIN 26
#define LED_PIN 16

// Define constants
#define NUM_SAMPLES 100
#define CLAP_THRESHOLD 500
#define DEBOUNCE_DELAY 50 // milliseconds
#define LED_ON_TIME 500   // milliseconds

// Global variables
volatile sig_atomic_t program_running = 1;
static volatile unsigned long last_clap_time = 0;

// Function prototypes
int initialize_gpio();
int read_adc();
int detect_clap(int *samples, int num_samples);
void control_led(int on);
void print_timestamped_message(const char *message);
void signal_handler(int signal);

// Structure to hold clap detection state
typedef struct {
    int last_clap_time;
} ClapDetectorState;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(ADC_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    return 0;
}

// Function to read analog value using bit-banged ADC
int read_adc() {
    int high_count = 0;
    for (int i = 0; i < NUM_SAMPLES; ++i) {
        if (gpioRead(ADC_PIN) == 1) {
            high_count++;
        }
        gpioDelay(1); // Small delay for sampling
    }
    return high_count;
}

// Function to detect a clap event
int detect_clap(int *samples, int num_samples) {
    int sum = 0;
    for (int i = 0; i < num_samples; ++i) {
        sum += samples[i];
    }
    double average = (double)sum / num_samples;

    if (average > CLAP_THRESHOLD) {
        return 1; // Clap detected
    } else {
        return 0; // No clap detected
    }
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_PIN, on);
}

// Function to print a timestamped message to the console
void print_timestamped_message(const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    printf("[%s] %s\n", buf, message);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    print_timestamped_message("Exiting program...");
    control_led(0); // Turn off LED
    gpioTerminate(); // Release GPIO resources
    exit(0);
}

