volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

int gpio_export(int pin) {
    char buffer[64];
    int fd;

    fd = open(GPIO_PATH "/export", O_WRONLY);
    if (fd < 0) {
        perror("gpio/export");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("gpio/export");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_unexport(int pin) {
    char buffer[64];
    int fd;

    fd = open(GPIO_PATH "/unexport", O_WRONLY);
    if (fd < 0) {
        perror("gpio/unexport");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("gpio/unexport");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), GPIO_PATH "/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("gpio/direction");
        return -1;
    }
    if (write(fd, direction, strlen(direction)) < 0) {
        perror("gpio/direction");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_read_value(int pin) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), GPIO_PATH "/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("gpio/value");
        return -1;
    }
    if (read(fd, value_str, 3) < 0) {
        perror("gpio/value");
        close(fd);
        return -1;
    }
    close(fd);
    return atoi(value_str);
}

int log_distance(int distance) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    fprintf(fp, "%s, %d\n", timestamp, distance);
    fclose(fp);
    return 0;
}

