        fprintf(stderr, "Failed to export GPIO %d. Retrying in 1 second.\n", GPIO_PIN);
        sleep(1);
        return 1;
    }

    // Set GPIO direction to input
    if (gpio_set_direction(GPIO_PIN, "in") < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to input. Retrying in 1 second.\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        sleep(1);
        return 1;
    }

    printf("Monitoring distance sensor on GPIO %d...\n", GPIO_PIN);

    while (program_running) {
        distance = gpio_read_value(GPIO_PIN);
        if (distance < 0) {
            fprintf(stderr, "Failed to read GPIO %d value. Retrying in 1 second.\n", GPIO_PIN);
            sleep(1);
            continue;
        }

        if (log_distance(distance) < 0) {
            fprintf(stderr, "Failed to log distance. Retrying in 1 second.\n");
        }

        if (distance == 0) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    // Unexport GPIO pin on exit
    if (gpio_unexport(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to unexport GPIO %d.\n", GPIO_PIN);
    }

    return 0;
}

