float adc_to_magnetic_field(int adc_value) {
    float voltage = (float)adc_value / 1023.0f * VREF;
    float magnetic_field = (voltage - ZERO_FIELD_OUTPUT) / SENSITIVITY;
    return magnetic_field;
}

