        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Magnetic field sensor logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping sample\n");
            sleep(0.5);
            continue;
        }

        // Convert to magnetic field strength
        magnetic_field = adc_to_magnetic_field(adc_value);

        // Get current timestamp
        current_time = time(NULL);

        // Log data
        if (log_data(current_time, magnetic_field) != 0) {
            fprintf(stderr, "Error logging data, skipping sample\n");
        }

        printf("Magnetic Field: %.2f Gauss\n", magnetic_field);

        sleep(0.5); // Sample every 500ms
    }

    // Cleanup and exit
    cleanup();
    printf("Magnetic field sensor logging stopped.\n");
    return 0;
}

