#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_PIN 17
#define VREF 5.0
#define ADC_RESOLUTION 1024.0
#define SENSITIVITY 0.1
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_transfer(int fd, uint8_t channel);
float adc_to_voltage(int adc_value, float vref);
float voltage_to_current(float voltage, float sensitivity);
int log_current(float current);
void signal_handler(int sig);
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_write(int pin, int value);

// SPI initialization function
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    // Configure SPI max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = 1000000; // 1 MHz
    tr.bits_per_word = 8;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to voltage conversion function
float adc_to_voltage(int adc_value, float vref) {
    return (adc_value / ADC_RESOLUTION) * vref;
}

// Voltage to current conversion function
float voltage_to_current(float voltage, float sensitivity) {
    return voltage / sensitivity;
}

// Logging function
int log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.3f\n", timestamp, current);
        fflush(log_file); // Ensure data is written to disk
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// GPIO export function
int gpio_export(int pin) {
    char buffer[3];
    ssize_t bytes_written;
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd == -1) {
        perror("Failed to open export file");
        return -1;
    }

    int len = snprintf(buffer, sizeof(buffer), "%d", pin);
    bytes_written = write(fd, buffer, len);
    close(fd);
    if (bytes_written < 0) {
        perror("Failed to export GPIO pin");
        return -1;
    }
    return 0;
}

// GPIO unexport function
int gpio_unexport(int pin) {
    char buffer[3];
    ssize_t bytes_written;
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd == -1) {
        perror("Failed to open unexport file");
        return -1;
    }

    int len = snprintf(buffer, sizeof(buffer), "%d", pin);
    bytes_written = write(fd, buffer, len);
    close(fd);
    if (bytes_written < 0) {
        perror("Failed to unexport GPIO pin");
        return -1;
    }
    return 0;
}

// GPIO set direction function
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd == -1) {
        perror("Failed to open GPIO direction file");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) < 0) {
        perror("Failed to set GPIO direction");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO write function
int gpio_write(int pin, int value) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd == -1) {
        perror("Failed to open GPIO value file");
        return -1;
    }

    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d.  Must be 0 or 1.\n", value);
        close(fd);
        return -1;
    }

    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);

    if (write(fd, val_str, 1) < 0) {
        perror("Failed to write GPIO value");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_export(GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO export failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    if (gpio_set_direction(GPIO_PIN, "out") < 0) {
        fprintf(stderr, "GPIO direction setting failed. Exiting.\n");
        gpio_unexport(GPIO_PIN);
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpio_unexport(GPIO_PIN);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Enable sensor
        if (gpio_write(GPIO_PIN, 1) < 0) {
            fprintf(stderr, "Error enabling sensor. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Sample ADC
        int adc_value = spi_transfer(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying.\n");
            gpio_write(GPIO_PIN, 0); // Disable sensor before retrying
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value, VREF);

        // Convert voltage to current
        float current = voltage_to_current(voltage, SENSITIVITY);

        // Log current
        if (log_current(current) < 0) {
            fprintf(stderr, "Error logging current.\n");
        }

        // Disable sensor
        if (gpio_write(GPIO_PIN, 0) < 0) {
            fprintf(stderr, "Error disabling sensor.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    gpio_unexport(GPIO_PIN);

    fprintf(stderr, "Exiting.\n");
    return 0;
}

