#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
void log_data(double moisture_level);
void signal_handler(int signal);
int spi_setup(spi_config_t config);

// Structure for SPI configuration
typedef struct {
    int channel;
    int baud;
    int flags;
} spi_config_t;

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d). Retrying...\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture level percentage
double calculate_moisture_level(int adc_value) {
    double moisture_level = 100.0 - ((double)(adc_value - MIN_ADC) / (double)(MAX_ADC - MIN_ADC) * 100.0);
    if (moisture_level < 0.0) moisture_level = 0.0;
    if (moisture_level > 100.0) moisture_level = 100.0;
    return moisture_level;
}

// Function to log data to file and console
void log_data(double moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Log to file
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
        fclose(fp);
    } else {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
    }

    // Print to console
    printf("%s,%.2f\n", timestamp, moisture_level);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to set up SPI
int spi_setup(spi_config_t config) {
    spi_handle = spiOpen(config.channel, config.baud, config.flags);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel %d (%d)\n", config.channel, spi_handle);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // SPI configuration
    spi_config_t spi_config = {
        .channel = SPI_CHANNEL,
        .baud = SPI_BAUD,
        .flags = 0 // SPI_MODE0
    };

    // Initialize SPI
    if (spi_setup(spi_config) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            // Error reading ADC, retry after delay
            sleep(READ_DELAY);
            continue;
        }

        // Calculate moisture level
        double moisture_level = calculate_moisture_level(adc_value);

        // Log data
        log_data(moisture_level);

        // Wait before next reading
        sleep(READ_DELAY);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

