#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/wait.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <wiringPi.h>

// Configuration
#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define POLL_INTERVAL_MS 50
#define CAPTURE_DIR "/home/pi/security_cam/"
#define LOG_FILE "/var/log/security_cam.log"

// Global variables
volatile sig_atomic_t program_running = 1;
int gpio_initialized = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int debounce();
int capture_image();
int log_event(const char *message);
void signal_handler(int signal);
int create_directory(const char *path);

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
}

// Initialize GPIO
int initialize_gpio() {
    if (wiringPiSetupGpio() == -1) {
        log_event("Failed to initialize wiringPi.");
        return -1;
    }

    pinMode(GPIO_PIN, INPUT);
    pullUpDnControl(GPIO_PIN, PUD_DOWN); // Enable pull-down resistor
    gpio_initialized = 1;
    log_event("GPIO initialized successfully.");
    return 0;
}

// Read PIR sensor
int read_pir_sensor() {
    return digitalRead(GPIO_PIN);
}

// Debounce function
int debounce() {
    delay(DEBOUNCE_DELAY_MS);
    return read_pir_sensor();
}

// Capture image using libcamera-still
int capture_image() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    char filename[256];
    char command[512];
    pid_t pid;
    int status;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    snprintf(filename, sizeof(filename), "%s%s.jpg", CAPTURE_DIR, timestamp);
    snprintf(command, sizeof(command), "libcamera-still -o %s", filename);

    pid = fork();

    if (pid == 0) {
        // Child process
        execlp("libcamera-still", "libcamera-still", "-o", filename, (char *)NULL);
        // execlp only returns on error
        perror("execlp");
        exit(EXIT_FAILURE);
    } else if (pid < 0) {
        // Fork failed
        log_event("Failed to fork process for image capture.");
        return -1;
