#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEFAULT_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 1

// Structure to hold camera buffer information
typedef struct {
    void *start;
    size_t length;
} buffer_t;

// Global variables
static int camera_fd = -1;
static buffer_t buffers[NUM_BUFFERS];
static int buffer_count = 0;
static int image_count = 0;
static char *device_name = NULL;
static volatile sig_atomic_t stop_flag = 0;

// Function prototypes
int init_camera(const char *device);
int configure_camera(int fd);
int start_streaming(int fd);
int dequeue_buffer(int fd, buffer_t *buffer);
int enqueue_buffer(int fd, int buffer_index);
int save_image(const char *filename, const void *data, size_t size);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received: %d.  Stopping...\n", sig);
    stop_flag = 1;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");

    // Stop streaming if it's running
    if (camera_fd != -1) {
        // Unmap buffers
        for (int i = 0; i < buffer_count; i++) {
            if (buffers[i].start != NULL && buffers[i].length != 0) {
                if (munmap(buffers[i].start, buffers[i].length) == -1) {
                    fprintf(stderr, "Error unmapping buffer %d: %s\n", i, strerror(errno));
                }
            }
        }

        // Close the camera device
        if (close(camera_fd) == -1) {
            fprintf(stderr, "Error closing camera device: %s\n", strerror(errno));
        }
        camera_fd = -1;
    }

    // Free allocated memory
    if (device_name != NULL) {
        free(device_name);
        device_name = NULL;
    }

    fprintf(stderr, "Cleanup complete.\n");
}

// Initialize the camera device
int init_camera(const char *device) {
    int fd = open(device, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        fprintf(stderr, "Error opening camera device %s: %s\n", device, strerror(errno));
        return -1;
    }

    fprintf(stderr, "Camera device %s opened successfully.\n", device);
    return fd;
}

// Configure the camera for grayscale capture
int configure_camera(int fd) {
    // Example configuration (replace with actual OV5647 configuration)
    // This is a placeholder and needs to be replaced with the correct
    // V4L2 controls for the OV5647 to set grayscale mode.
    // For example, setting the image format to YUYV and then converting to grayscale in software.

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV; // Example format
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    fprintf(stderr, "Camera format set to %s %dx%d\n", (char*)V4L2_PIX_FMT_YUYV, IMAGE_WIDTH, IMAGE_HEIGHT);

    return 0;
}

// Start streaming from the camera
int start_streaming(int fd) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    buffer_count = req.count;

    for (int i = 0; i < buffer_count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            fprintf(stderr, "Error querying buffer %d: %s\n", i, strerror(errno));
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %d: %s\n", i, strerror(errno));
            return -1;
        }
    }

    // Queue the buffers
    for (int i = 0; i < buffer_count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "Error queuing buffer %d: %s\n", i, strerror(errno));
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    fprintf(stderr, "Streaming started.\n");
    return 0;
}

// Dequeue a buffer from the camera
int dequeue_buffer(int fd, buffer_t *buffer) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = 2; // 2-second timeout
    timeout.tv_usec = 0;

    int select_result = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (select_result == -1) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        return -1;
    } else if (select_result == 0) {
        fprintf(stderr, "Timeout waiting for buffer.\n");
        return -1; // Timeout
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    buffer->index = buf.index;
    buffer->length = buf.length;
    buffer->start = buffers[buf.index].start;

    return 0;
}

// Enqueue a buffer back to the camera
int enqueue_buffer(int fd, int buffer_index) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = buffer_index;

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "Error queuing buffer %d: %s\n", buffer_index, strerror(errno));
        return -1;
    }

    return 0;
}

// Save the image data to a PGM file
int save_image(const char *filename, const void *data, size_t size) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);
    if (fwrite(data, 1, size, fp) != size) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        device_name = strdup(argv[1]);
        if (device_name == NULL) {
            fprintf(stderr, "Error duplicating device name: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }
    } else {
        device_name = strdup(DEFAULT_DEVICE);
        if (device_name == NULL) {
            fprintf(stderr, "Error duplicating default device name: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the camera
    camera_fd = init_camera(device_name);
    if (camera_fd == -1) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure the camera
    if (configure_camera(camera_fd) == -1) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(camera_fd) == -1) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!stop_flag) {
        buffer_t buffer;
        if (dequeue_buffer(camera_fd, &buffer) == 0) {
            // Convert YUYV to grayscale (example)
            unsigned char *yuyv_data = (unsigned char *)buffer.start;
            unsigned char *grayscale_data = malloc(IMAGE_WIDTH * IMAGE_HEIGHT);
            if (grayscale_data == NULL) {
                fprintf(stderr, "Error allocating memory for grayscale data: %s\n", strerror(errno));
                continue; // Skip this frame
            }

            for (int i = 0; i < IMAGE_WIDTH * IMAGE_HEIGHT; i++) {
                grayscale_data[i] = yuyv_data[i * 2]; // Use Y component
            }

            // Save the image
            char filename[20];
            snprintf(filename, sizeof(filename), "image_%04d.pgm", ++image_count);
            if (save_image(filename, grayscale_data, IMAGE_WIDTH * IMAGE_HEIGHT) == -1) {
                fprintf(stderr, "Error saving image %s\n", filename);
            }

            free(grayscale_data);

            // Enqueue the buffer
            if (enqueue_buffer(camera_fd, buffer.index) == -1) {
                fprintf(stderr, "Error enqueuing buffer %d\n", buffer.index);
            }
        } else if (errno != EAGAIN) {
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
            break; // Exit loop on error
        }
    }

    // Stop streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(camera_fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
    }

    // Cleanup resources
    cleanup();

    return EXIT_SUCCESS;
}

