    int select_result = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (select_result == -1) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        return -1;
    } else if (select_result == 0) {
        fprintf(stderr, "Timeout waiting for buffer.\n");
        return -1; // Timeout
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    buffer->index = buf.index;
    buffer->length = buf.length;
    buffer->start = buffers[buf.index].start;

    return 0;
}

// Enqueue a buffer back to the camera
int enqueue_buffer(int fd, int buffer_index) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = buffer_index;

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "Error queuing buffer %d: %s\n", buffer_index, strerror(errno));
        return -1;
    }

    return 0;
}

// Save the image data to a PGM file
int save_image(const char *filename, const void *data, size_t size) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);
    if (fwrite(data, 1, size, fp) != size) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        device_name = strdup(argv[1]);
        if (device_name == NULL) {
            fprintf(stderr, "Error duplicating device name: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }
    } else {
        device_name = strdup(DEFAULT_DEVICE);
        if (device_name == NULL) {
            fprintf(stderr, "Error duplicating default device name: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the camera
    camera_fd = init_camera(device_name);
    if (camera_fd == -1) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure the camera
    if (configure_camera(camera_fd) == -1) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(camera_fd) == -1) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!stop_flag) {
        buffer_t buffer;
        if (dequeue_buffer(camera_fd, &buffer) == 0) {
            // Convert YUYV to grayscale (example)
            unsigned char *yuyv_data = (unsigned char *)buffer.start;
            unsigned char *grayscale_data = malloc(IMAGE_WIDTH * IMAGE_HEIGHT);
            if (grayscale_data == NULL) {
                fprintf(stderr, "Error allocating memory for grayscale data: %s\n", strerror(errno));
                continue; // Skip this frame
            }

            for (int i = 0; i < IMAGE_WIDTH * IMAGE_HEIGHT; i++) {
                grayscale_data[i] = yuyv_data[i * 2]; // Use Y component
            }

            // Save the image
            char filename[20];
            snprintf(filename, sizeof(filename), "image_%04d.pgm", ++image_count);
            if (save_image(filename, grayscale_data, IMAGE_WIDTH * IMAGE_HEIGHT) == -1) {
                fprintf(stderr, "Error saving image %s\n", filename);
            }

            free(grayscale_data);

            // Enqueue the buffer
            if (enqueue_buffer(camera_fd, buffer.index) == -1) {
                fprintf(stderr, "Error enqueuing buffer %d\n", buffer.index);
            }
        } else if (errno != EAGAIN) {
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
            break; // Exit loop on error
        }
    }

    // Stop streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(camera_fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
    }

    // Cleanup resources
    cleanup();

    return EXIT_SUCCESS;
}

