}

// Function to send a frame over UDP
int send_frame(int socket_fd, struct sockaddr_in server_addr, void *buffer, size_t buffer_size, int frame_index) {
    size_t fragment_size = MAX_UDP_SIZE - HEADER_SIZE;
    size_t total_fragments = (buffer_size + fragment_size - 1) / fragment_size; // Calculate total fragments
    size_t bytes_sent = 0;

    for (size_t i = 0; i < total_fragments; i++) {
        size_t current_fragment_size = (i == total_fragments - 1) ? (buffer_size - bytes_sent) : fragment_size;
        size_t payload_size = current_fragment_size;

        // Create header
        unsigned char header[HEADER_SIZE];
        header[0] = (frame_index >> 24) & 0xFF;
        header[1] = (frame_index >> 16) & 0xFF;
        header[2] = (frame_index >> 8) & 0xFF;
        header[3] = frame_index & 0xFF;
        header[4] = (i >> 24) & 0xFF;
        header[5] = (i >> 16) & 0xFF;
        header[6] = (i >> 8) & 0xFF;
        header[7] = i & 0xFF;
        header[8] = (total_fragments >> 24) & 0xFF;
        header[9] = (total_fragments >> 16) & 0xFF;
        header[10] = (total_fragments >> 8) & 0xFF;
        header[11] = total_fragments & 0xFF;
        header[12] = (payload_size >> 24) & 0xFF;
        header[13] = (payload_size >> 16) & 0xFF;
        header[14] = (payload_size >> 8) & 0xFF;
        header[15] = payload_size & 0xFF;

        // Create datagram
        size_t datagram_size = HEADER_SIZE + payload_size;
        unsigned char *datagram = malloc(datagram_size);
        if (datagram == NULL) {
            log_error("Error allocating memory for datagram");
            return -1;
        }
        memcpy(datagram, header, HEADER_SIZE);
        memcpy(datagram + HEADER_SIZE, buffer + bytes_sent, payload_size);

        // Send datagram
        ssize_t sent_bytes = sendto(socket_fd, datagram, datagram_size, 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
        free(datagram);

        if (sent_bytes == -1) {
            log_error("Error sending datagram");
            return -1;
        }

        bytes_sent += payload_size;
    }

    return 0;
}

// Function to unmap buffers
int unmap_buffers(int fd) {
