    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(target_port);
    if (inet_pton(AF_INET, target_ip, &server_addr.sin_addr) <= 0) {
        log_error("Invalid target IP address");
        close_socket(socket_fd);
        unmap_buffers(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(fd) == -1) {
        close_socket(socket_fd);
        unmap_buffers(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    int frame_index = 0;
    int buffer_index;

    // Capture and send frames
    while (running) {
        if (capture_frame(fd, &buffer_index) == -1) {
            break; // Exit loop on error
        }

        if (send_frame(socket_fd, server_addr, buffers[buffer_index].start, buffers[buffer_index].length, frame_index) == -1) {
            break; // Exit loop on error
        }

        frame_index++;

        // Requeue the buffer
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = buffer_index;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            log_error("Error requeuing buffer");
            break; // Exit loop on error
        }
    }

    // Clean up
    printf("Cleaning up...\n");
    stop_streaming(fd);
    unmap_buffers(fd);
    close_device(fd);
    close_socket(socket_fd);

    return EXIT_SUCCESS;
}

