#include <linux/videodev2.h>
#include <signal.h>
#include <unistd.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_FILE "image.jpg"
#define NUM_BUFFERS 4
#define IMAGE_WIDTH 192
#define IMAGE_HEIGHT 144

// Structure to hold buffer information
struct buffer {
    void   *start;
    size_t  length;
};

// Global variables
int fd = -1; // File descriptor for the video device
struct buffer *buffers = NULL; // Array of buffers
int num_buffers = 0; // Number of buffers allocated
FILE *image_file = NULL; // File pointer for the image file

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signum);

        // Stop streaming
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
            perror("VIDIOC_STREAMOFF failed");
        }

        // Unmap buffers
        for (int i = 0; i < num_buffers; i++) {
            if (munmap(buffers[i].start, buffers[i].length) == -1) {
                perror("munmap failed");
            }
        }

        // Free buffer array
        if (buffers != NULL) {
            free(buffers);
        }

        // Close file descriptor
        if (fd != -1) {
            close(fd);
        }

        // Close image file
        if (image_file != NULL) {
            fclose(image_file);
        }

        exit(0);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the video device
