    gpioSetPullUpDown(TILT_UP_PIN, PI_PUD_UP);
    gpioSetMode(TILT_DOWN_PIN, PI_INPUT);
    gpioSetPullUpDown(TILT_DOWN_PIN, PI_PUD_UP);
    gpioSetMode(PAN_LEFT_PIN, PI_INPUT);
    gpioSetPullUpDown(PAN_LEFT_PIN, PI_PUD_UP);
    gpioSetMode(PAN_RIGHT_PIN, PI_INPUT);
    gpioSetPullUpDown(PAN_RIGHT_PIN, PI_PUD_UP);

    // Set PWM frequency and range
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE);

    return 0;
}

// Sets the servo position using PWM
int set_servo_position(int pin, int position) {
    if (position < MIN_SERVO_POSITION || position > MAX_SERVO_POSITION) {
        fprintf(stderr, "Invalid servo position: %d\n", position);
        return -1;
    }

    // Convert position (0-100) to pulse width (1ms - 2ms) within the range of 1000
    int pulse_width = (int)(((float)position / 100.0) * (2000.0 - 1000.0) + 1000.0);

    gpioPWM(pin, pulse_width);
    return 0;
}

// Reads the state of a button
int read_button(int pin) {
    return gpioRead(pin);
}

// Adjusts the pan position
void adjust_pan_position(int direction) {
    if (direction == 1) { // Right
        pan_position += SERVO_ADJUSTMENT_STEP;
        if (pan_position > MAX_SERVO_POSITION) {
            pan_position = MAX_SERVO_POSITION;
        }
    } else if (direction == -1) { // Left
        pan_position -= SERVO_ADJUSTMENT_STEP;
        if (pan_position < MIN_SERVO_POSITION) {
            pan_position = MIN_SERVO_POSITION;
        }
    }
    set_servo_position(PAN_SERVO_PIN, pan_position);
}

// Adjusts the tilt position
void adjust_tilt_position(int direction) {
    if (direction == 1) { // Up
        tilt_position += SERVO_ADJUSTMENT_STEP;
        if (tilt_position > MAX_SERVO_POSITION) {
            tilt_position = MAX_SERVO_POSITION;
        }
    } else if (direction == -1) { // Down
        tilt_position -= SERVO_ADJUSTMENT_STEP;
        if (tilt_position < MIN_SERVO_POSITION) {
            tilt_position = MIN_SERVO_POSITION;
        }
    }
    set_servo_position(TILT_SERVO_PIN, tilt_position);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set initial servo positions
    set_servo_position(PAN_SERVO_PIN, INITIAL_PAN_POSITION);
    set_servo_position(TILT_SERVO_PIN, INITIAL_TILT_POSITION);

    printf("Pan-Tilt control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read button states
        int tilt_up_pressed = (read_button(TILT_UP_PIN) == 0);
        int tilt_down_pressed = (read_button(TILT_DOWN_PIN) == 0);
        int pan_left_pressed = (read_button(PAN_LEFT_PIN) == 0);
        int pan_right_pressed = (read_button(PAN_RIGHT_PIN) == 0);

        // Adjust servo positions based on button presses
        if (tilt_up_pressed) {
            adjust_tilt_position(1);
        }
        if (tilt_down_pressed) {
            adjust_tilt_position(-1);
        }
        if (pan_left_pressed) {
            adjust_pan_position(-1);
        }
        if (pan_right_pressed) {
            adjust_pan_position(1);
        }

        // Delay for 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    return 0;
}

