#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <jpeglib.h>
#include <math.h>

#include <linux/videodev2.h>
#include <libv4l2.h>

#include <pthread.h>

#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define VIDEO_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define BLUR_RADIUS 5
#define JPEG_QUALITY 75
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Global variables (minimize usage)
static int video_fd = -1;
static struct v4l2_buffer *buffers = NULL;
static unsigned int num_buffers = 0;
static unsigned char *image_buffer = NULL;
static unsigned char *rgb_buffer = NULL;
static unsigned char *blurred_buffer = NULL;
static unsigned char *dht_data = NULL;
static unsigned char *dqt_data = NULL;
static unsigned int dht_size = 0;
static unsigned int dqt_size = 0;
static int running = 1;

// Structure to hold image data
typedef struct {
    unsigned char *data;
    int width;
    int height;
    int bytes_per_line;
} image_t;

// Function prototypes
int init_camera();
int capture_frame();
int yuyv_to_rgb24(unsigned char *yuyv, unsigned char *rgb, int width, int height);
int apply_blur_filter(unsigned char *rgb, unsigned char *blurred, int width, int height, int radius);
int encode_jpeg(unsigned char *image, int width, int height, unsigned char **jpeg_data, unsigned long *jpeg_size);
int read_dht_dqt_data(const char *filename, unsigned char **dht_data, unsigned int *dht_size, unsigned char **dqt_data, unsigned int *dqt_size);
int write_jpeg_to_file(const char *filename, unsigned char *jpeg_data, unsigned long jpeg_size, unsigned char *dht_data, unsigned int dht_size, unsigned char *dqt_data, unsigned int dqt_size);
void signal_handler(int signum);
void cleanup();

// Helper function to log errors
void log_error(const char *message) {
    fprintf(stderr, "Error: %s (errno: %d)\n", message, errno);
}

// Helper function to get current timestamp
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y%m%d_%H%M%S", timeinfo);
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "WiringPi initialization failed!\n");
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "SPI initialization failed!\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize camera
    if (init_camera() != 0) {
        fprintf(stderr, "Camera initialization failed!\n");
        cleanup();
        return 1;
    }

    // Allocate memory for image buffers
    image_buffer = (unsigned char *)malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 2); // YUYV
    rgb_buffer = (unsigned char *)malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 3);  // RGB24
    blurred_buffer = (unsigned char *)malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 3); // Blurred RGB24

    if (!image_buffer || !rgb_buffer || !blurred_buffer) {
        log_error("Failed to allocate memory for image buffers");
        cleanup();
        return 1;
    }

    // Read DHT and DQT data from JPEG file
    if (read_dht_dqt_data("image.jpg", &dht_data, &dht_size, &dqt_data, &dqt_size) != 0) {
        fprintf(stderr, "Failed to read DHT/DQT data from image.jpg\n");
        cleanup();
        return 1;
    }

    // Capture frame
    if (capture_frame() != 0) {
        fprintf(stderr, "Failed to capture frame\n");
        cleanup();
        return 1;
    }

    // Convert YUYV to RGB24
    if (yuyv_to_rgb24(image_buffer, rgb_buffer, IMAGE_WIDTH, IMAGE_HEIGHT) != 0) {
        fprintf(stderr, "Failed to convert YUYV to RGB24\n");
        cleanup();
        return 1;
    }

    // Apply blur filter
    if (apply_blur_filter(rgb_buffer, blurred_buffer, IMAGE_WIDTH, IMAGE_HEIGHT, BLUR_RADIUS) != 0) {
        fprintf(stderr, "Failed to apply blur filter\n");
        cleanup();
        return 1;
    }

    // Encode as JPEG
    unsigned char *jpeg_data = NULL;
    unsigned long jpeg_size = 0;
    if (encode_jpeg(blurred_buffer, IMAGE_WIDTH, IMAGE_HEIGHT, &jpeg_data, &jpeg_size) != 0) {
        fprintf(stderr, "Failed to encode JPEG\n");
        cleanup();
        return 1;
    }

    // Write JPEG to file
    char timestamp[20];
    get_timestamp(timestamp);
    char filename[50];
    snprintf(filename, sizeof(filename), "capture_%s.jpg", timestamp);

    if (write_jpeg_to_file(filename, jpeg_data, jpeg_size, dht_data, dht_size, dqt_data, dqt_size) != 0) {
        fprintf(stderr, "Failed to write JPEG to file\n");
