    return 0;
}

int init_camera() {
    video_fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (video_fd < 0) {
        log_error("Failed to open video device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(video_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        log_error("Failed to query capabilities");
        close(video_fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(video_fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(video_fd);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(video_fd, VIDIOC_S_FMT, &fmt) < 0) {
        log_error("Failed to set format");
        close(video_fd);
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 4; // Number of buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(video_fd, VIDIOC_REQBUFS, &req) < 0) {
        log_error("Failed to request buffers");
        close(video_fd);
        return -1;
    }

    num_buffers = req.count;
    buffers = (struct v4l2_buffer *)calloc(num_buffers, sizeof(struct v4l2_buffer));
    if (!buffers) {
        log_error("Failed to allocate memory for buffers");
        close(video_fd);
        return -1;
    }

    for (unsigned int i = 0; i < num_buffers; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(video_fd, VIDIOC_QUERYBUF, &buf) < 0) {
            log_error("Failed to query buffer");
            close(video_fd);
            free(buffers);
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].m.offset = buf.m.offset;
        buffers[i].index = i;

        void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, buf.m.offset);
        if (buffer == MAP_FAILED) {
            log_error("Failed to map buffer");
            close(video_fd);
            free(buffers);
            return -1;
        }
        buffers[i].m.userptr = (unsigned long)buffer;
    }

    for (unsigned int i = 0; i < num_buffers; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(video_fd, VIDIOC_QBUF, &buf) < 0) {
            log_error("Failed to queue buffer");
            close(video_fd);
            free(buffers);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(video_fd, VIDIOC_STREAMON, &type) < 0) {
        log_error("Failed to start streaming");
        close(video_fd);
        free(buffers);
        return -1;
    }

    return 0;
}

int capture_frame() {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(video_fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(video_fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        log_error("Select error");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Select timeout\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(video_fd, VIDIOC_DQBUF, &buf) < 0) {
        log_error("Failed to dequeue buffer");
        return -1;
    }

    // Copy the data from the buffer to our image buffer
    void *buffer = (void *)((unsigned long)buf.m.userptr);
    memcpy(image_buffer, buffer, buf.bytesused);

    if (ioctl(video_fd, VIDIOC_QBUF, &buf) < 0) {
        log_error("Failed to queue buffer");
        return -1;
    }

    return 0;
}

int yuyv_to_rgb24(unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    for (int j = 0; j < height; j++) {
        for (int i = 0; i < width; i += 2) {
            unsigned char y1 = yuyv[j * width * 2 + i * 2];
            unsigned char u = yuyv[j * width * 2 + i * 2 + 1];
            unsigned char y2 = yuyv[j * width * 2 + i * 2 + 2];
            unsigned char v = yuyv[j * width * 2 + i * 2 + 3];

            // Convert YUV to RGB
            int c = y1 - 16;
            int d = u - 128;
            int e = v - 128;

            int r = (298 * c + 409 * e + 128) >> 8;
            int g = (298 * c - 100 * d - 208 * e + 128) >> 8;
            int b = (298 * c + 516 * d + 128) >> 8;

            // Clamp RGB values to 0-255
            r = r < 0 ? 0 : r > 255 ? 255 : r;
            g = g < 0 ? 0 : g > 255 ? 255 : g;
            b = b < 0 ? 0 : b > 255 ? 255 : b;

            // Store RGB values
            rgb[j * width * 3 + i * 3] = r;
            rgb[j * width * 3 + i * 3 + 1] = g;
            rgb[j * width * 3 + i * 3 + 2] = b;

            // Second pixel in the YUYV pair
            c = y2 - 16;

            r = (298 * c + 409 * e + 128) >> 8;
            g = (298 * c - 100 * d - 208 * e + 128) >> 8;
            b = (298 * c + 516 * d + 128) >> 8;

            r = r < 0 ? 0 : r > 255 ? 255 : r;
            g = g < 0 ? 0 : g > 255 ? 255 : g;
            b = b < 0 ? 0 : b > 255 ? 255 : b;

            rgb[j * width * 3 + i * 3 + 3] = r;
            rgb[j * width * 3 + i * 3 + 4] = g;
            rgb[j * width * 3 + i * 3 + 5] = b;
        }
    }
    return 0;
}

int apply_blur_filter(unsigned char *rgb, unsigned char *blurred, int width, int height, int radius) {
    // Simple box blur
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            long sum_r = 0, sum_g = 0, sum_b = 0;
            int count = 0;

            for (int dy = -radius; dy <= radius; dy++) {
                for (int dx = -radius; dx <= radius; dx++) {
                    int ny = y + dy;
                    int nx = x + dx;

                    if (ny >= 0 && ny < height && nx >= 0 && nx < width) {
                        sum_r += rgb[ny * width * 3 + nx * 3];
                        sum_g += rgb[ny * width * 3 + nx * 3 + 1];
                        sum_b += rgb[ny * width * 3 + nx * 3 + 2];
                        count++;
                    }
                }
            }

            blurred[y * width * 3 + x * 3] = sum_r / count;
            blurred[y * width * 3 + x * 3 + 1] = sum_g / count;
            blurred[y * width * 3 + x * 3 + 2] = sum_b / count;
        }
    }
    return 0;
}

int encode_jpeg(unsigned char *image, int width, int height, unsigned char **jpeg_data, unsigned long *jpeg_size) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    unsigned char *outbuffer = NULL;
    unsigned long outsize = 0;
    jpeg_mem_dest(&cinfo, &outbuffer, &outsize);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3; // RGB
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    JSAMPROW row_pointer[1];
    int row_stride = width * 3;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &image[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);

    *jpeg_data = outbuffer;
    *jpeg_size = outsize;

    return 0;
}

int read_dht_dqt_data(const char *filename, unsigned char **dht_data, unsigned int *dht_size, unsigned char **dqt_data, unsigned int *dqt_size) {
    FILE *infile = fopen(filename, "rb");
    if (!infile) {
        log_error("Failed to open JPEG file for reading DHT/DQT data");
        return -1;
    }

    unsigned char marker;
    unsigned char length[2];
    unsigned char segment[65535]; // Maximum segment size

    *dht_data = NULL;
    *dht_size = 0;
    *dqt_data = NULL;
    *dqt_size = 0;

    while (fread(&marker, 1, 1, infile) == 1) {
        if (marker == 0xFF) {
            if (fread(&marker, 1, 1, infile) != 1) break;

            if (marker == 0xC4) { // DQT
                if (fread(length, 2, 1, infile) != 1) break;
                unsigned int segment_length = (length[0] << 8) | length[1];
                if (segment_length > sizeof(segment)) {
                    fprintf(stderr, "DQT segment too large\n");
                    break;
                }
                if (fread(segment, 1, segment_length, infile) != segment_length) break;

                *dqt_data = (unsigned char *)malloc(segment_length);
                if (!*dqt_data) {
                    log_error("Failed to allocate memory for DQT data");
                    fclose(infile);
                    return -1;
                }
                memcpy(*dqt_data, segment, segment_length);
                *dqt_size = segment_length;

            } else if (marker == 0xC0) { // DHT
                if (fread(length, 2, 1, infile) != 1) break;
                unsigned int segment_length = (length[0] << 8) | length[1];
                if (segment_length > sizeof(segment)) {
                    fprintf(stderr, "DHT segment too large\n");
                    break;
                }
                if (fread(segment, 1, segment_length, infile) != segment_length) break;

                *dht_data = (unsigned char *)malloc(segment_length);
                if (!*dht_data) {
                    log_error("Failed to allocate memory for DHT data");
                    fclose(infile);
                    return -1;
                }
                memcpy(*dht_data, segment, segment_length);
                *dht_size = segment_length;
            }
        }
    }

    fclose(infile);
    return 0;
}

int write_jpeg_to_file(const char *filename, unsigned char *jpeg_data, unsigned long jpeg_size, unsigned char *dht_data, unsigned int dht_size, unsigned char *dqt_data, unsigned int dqt_size) {
    FILE *outfile = fopen(filename, "wb");
    if (!outfile) {
        log_error("Failed to open JPEG file for writing");
        return -1;
    }

    // Write the JPEG data
    fwrite(jpeg_data, 1, jpeg_size, outfile);

    // Append DHT and DQT data (not standard, but for demonstration)
    if (dht_data) {
        fwrite(dht_data, 1, dht_size, outfile);
    }
    if (dqt_data) {
        fwrite(dqt_data, 1, dqt_size, outfile);
    }

    fclose(outfile);
    return 0;
}

void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        running = 0;
    }
}

void cleanup() {
    if (video_fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ioctl(video_fd, VIDIOC_STREAMOFF, &type);

        for (unsigned int i = 0; i < num_buffers; i++) {
            void *buffer = (void *)((unsigned long)buffers[i].m.userptr);
            if (buffer != MAP_FAILED && buffer != NULL) {
                munmap(buffer, buffers[i].length);
            }
        }

        close(video_fd);
    }

    if (buffers) {
        free(buffers);
    }
}

