#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_fmtdesc fmtdesc;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    struct v4l2_control control;
    struct v4l2_queryctrl queryctrl;
    int autofocus_supported = 0;

    // Open the device node
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return 1;
    }

    // Check if the device is a V4L2 device
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    printf("Device capabilities: 0x%08x\n", cap.capabilities);

    // Enumerate supported frame sizes
    frmsize.index = 0;
    frmsize.pixel_format = V4L2_PIX_FMT_YUYV; // Assuming YUYV format for simplicity

    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        if (frmsize.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            printf("Supported frame size: %dx%d\n", frmsize.discrete.width, frmsize.discrete.height);

            // Enumerate frame intervals for each frame size
            frmival.index = 0;
            frmival.pixel_format = V4L2_PIX_FMT_YUYV;
            frmival.width = frmsize.discrete.width;
            frmival.height = frmsize.discrete.height;

            while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
                if (frmival.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
                    printf("  Supported frame interval: %d/%d fps\n", frmival.discrete.numerator, frmival.discrete.denominator);
                }
                frmival.index++;
            }
        }
        frmsize.index++;
    }

    // Check for autofocus support
    queryctrl.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) == 0) {
        if (queryctrl.type == V4L2_CTRL_TYPE_BOOLEAN) {
            printf("Autofocus is supported\n");
            autofocus_supported = 1;
        } else {
            printf("Autofocus is present but not a boolean control\n");
        }
    } else {
        if (errno == EINVAL) {
            printf("Autofocus control not present\n");
        } else {
            fprintf(stderr, "Error querying autofocus control: %s\n", strerror(errno));
            close(fd);
            return 1;
        }
    }

    close(fd);
    return 0;
}

