#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define PWM frequency and pulse width limits
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000
#define CENTER_PULSE_WIDTH 1500

// Global variables for pulse widths
int pan_pulse_width = CENTER_PULSE_WIDTH;
int tilt_pulse_width = CENTER_PULSE_WIDTH;

// Function prototypes
void signal_handler(int signal);
void button_callback(int gpio, int level, uint32_t tick);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Stop PWM on both servo pins
    gpioPWM(PAN_SERVO_PIN, 0);
    gpioPWM(TILT_SERVO_PIN, 0);

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

// Callback function for button presses
void button_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Button pressed (active low)
        if (gpio == UP_BUTTON_PIN) {
            tilt_pulse_width -= 10;
            if (tilt_pulse_width < MIN_PULSE_WIDTH) {
                tilt_pulse_width = MIN_PULSE_WIDTH;
            }
