#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <curl/curl.h>
#include <wiringPi.h>

// Configuration
#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 2000
#define POLL_INTERVAL_MS 100
#define IMAGE_QUALITY 85
#define MOTION_CAPTURE_DIR "motion_captures"
#define JSON_BUFFER_SIZE 256

// Global variables
volatile sig_atomic_t program_running = 1;
char *server_ip = NULL;
int server_port = 0;
CURL *curl = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int capture_image(const char *filename);
int create_json_payload(const char *filename, char *json_payload, size_t json_payload_size);
int post_data(const char *filename, const char *json_payload);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        fprintf(stderr, "Received signal %d, shutting down...\n", signal);
        program_running = 0;
    }
}

// Initialize GPIO
int initialize_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(GPIO_PIN, INPUT);
    pullUpDnControl(GPIO_PIN, PUD_DOWN); // Enable pull-down resistor

    return 0;
}

// Capture image using raspistill
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspistill -o %s -q %d -w 640 -h 480", filename, IMAGE_QUALITY);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing raspistill: %s\n", strerror(errno));
        return -1;
    } else if (WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspistill exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

// Create JSON payload
int create_json_payload(const char *filename, char *json_payload, size_t json_payload_size) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%06uZ", timeinfo);

    int ret = snprintf(json_payload, json_payload_size, 
                       "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion\": true, \"gpio_pin\": %d}",
                       filename, timestamp, GPIO_PIN);

    if (ret < 0 || ret >= json_payload_size) {
        fprintf(stderr, "Error creating JSON payload: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Post data to server
int post_data(const char *filename, const char *json_payload) {
    CURLcode res;
    char url[256];
    snprintf(url, sizeof(url), "http://%s:%d/upload", server_ip, server_port);

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);

    // Set the file to upload
    curl_formadd(&formpost, &lastptr, CURLFORM_COPYNAME, "image", CURLFORM_FILE, filename, CURLFORM_END);
    curl_formadd(&formpost, &lastptr, CURLFORM_COPYNAME, "json", CURLFORM_COPYCONTENTS, json_payload, CURLFORM_END);

    curl_easy_setopt(curl, CURLOPT_HTTPPOST, formpost);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        return -1;
    }

    long response_code;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
    if (response_code != 200) {
        fprintf(stderr, "HTTP POST failed with status code: %ld\n", response_code);
        return -1;
    }

    curl_formfree(formpost);

    return 0;
}

// Cleanup resources
void cleanup() {
    if (curl) {
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    server_ip = argv[1];
    server_port = atoi(argv[2]);

    if (server_port <= 0) {
        fprintf(stderr, "Invalid server port: %d\n", server_port);
        return 1;
    }

    // Initialize libcurl
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error initializing libcurl\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() == -1) {
        cleanup();
        return 1;
    }

    // Create motion_captures directory if it doesn't exist
    struct stat st = {0};
    if (stat(MOTION_CAPTURE_DIR, &st) == -1) {
        if (mkdir(MOTION_CAPTURE_DIR, 0777) == -1) {
            fprintf(stderr, "Error creating directory %s: %s\n", MOTION_CAPTURE_DIR, strerror(errno));
            cleanup();
            return 1;
        }
    }

    // Main loop
    int motion_detected = 0;
    while (program_running) {
        int sensor_value = digitalRead(GPIO_PIN);

        if (sensor_value == HIGH) {
            if (!motion_detected) {
                // Debounce
                delay(DEBOUNCE_DELAY_MS);

                // Re-read after debounce
                if (digitalRead(GPIO_PIN) == HIGH) {
                    motion_detected = 1;

                    // Generate filename
                    time_t rawtime;
                    struct tm *timeinfo;
                    char filename[64];
                    char timestamp[30];

                    time(&rawtime);
                    timeinfo = localtime(&rawtime);
                    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);
                    snprintf(filename, sizeof(filename), "%s/%s.jpg", MOTION_CAPTURE_DIR, timestamp);

                    // Capture image
                    if (capture_image(filename) == 0) {
                        // Create JSON payload
                        char json_payload[JSON_BUFFER_SIZE];
                        if (create_json_payload(filename, json_payload, sizeof(json_payload)) == 0) {
                            // Post data
                            if (post_data(filename, json_payload) != 0) {
                                fprintf(stderr, "Error posting data\n");
                            }
                        } else {
                            fprintf(stderr, "Error creating JSON payload\n");
                        }
                    } else {
                        fprintf(stderr, "Error capturing image\n");
                    }
                }
            }
        } else {
            motion_detected = 0;
        }

        delay(POLL_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

