#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <signal.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define CROPPED_FILE "cropped.yuv"
#define CROP_WIDTH 200
#define CROP_HEIGHT 150

// Structure to hold the cropped image data
typedef struct {
    unsigned char *data;
    size_t size;
} CroppedImage;

// Global variables for signal handling
volatile sig_atomic_t stop_flag = 0;
int fd = -1;
void *buffer = NULL;
struct v4l2_buffer *buffers = NULL;
unsigned int n_buffers = 0;

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "Received signal %d, stopping...\n", signum);
        stop_flag = 1;
    }
}

// Function to handle errors
void handle_error(const char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

// Function to query the device capabilities
int query_device_capabilities(int fd) {
    struct v4l2_capability cap;

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        handle_error("VIDIOC_QUERYCAP failed");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    printf("Driver: %s\n", cap.driver);
    printf("Card: %s\n", cap.card);
    printf("Bus info: %s\n", cap.bus_info);
    printf("Version: %u.%u.%u\n", (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);
    printf("Capabilities: 0x%08x\n", cap.capabilities);

    return 0;
}

// Function to set the image format
int set_image_format(int fd, int width, int height) {
    struct v4l2_format fmt;

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        handle_error("VIDIOC_S_FMT failed");
        return -1;
    }

    printf("Image format set to %s %dx%d\n", (char*)V4L2_PIX_FMT_YUYV, width, height);

    return 0;
}

// Function to request buffers
int request_buffers(int fd) {
    struct v4l2_requestbuffers req;

    memset(&req, 0, sizeof(req));
    req.count = 1; // Request only one buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        handle_error("VIDIOC_REQBUFS failed");
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        handle_error("Out of memory");
        return -1;
    }

    n_buffers = req.count;

    return 0;
}

// Function to map the buffer
int map_buffer(int fd, int index) {
    struct v4l2_buffer buf;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = index;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        handle_error("VIDIOC_QUERYBUF failed");
        return -1;
    }

    buffers[index].length = buf.length;
    buffers[index].m.offset = buf.m.offset;

    buffers[index].m.userptr = buf.m.userptr; // Store user pointer

    return 0;
}

// Function to start streaming
int start_streaming(int fd) {
    struct v4l2_buffer buf;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        handle_error("VIDIOC_QBUF failed");
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        handle_error("VIDIOC_STREAMON failed");
        return -1;
    }

    return 0;
}

// Function to capture a frame with timeout
int capture_frame(int fd, void **buffer_ptr) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // 2-second timeout
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "select interrupted by signal\n");
            return -1; // Indicate interruption
        }
        handle_error("select failed");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1; // Indicate timeout
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        handle_error("VIDIOC_DQBUF failed");
        return -1;
    }

    *buffer_ptr = (void*)(buffers[buf.index].m.userptr); // Return the mapped buffer
    return 0;
}

// Function to stop streaming
int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        handle_error("VIDIOC_STREAMOFF failed");
        return -1;
    }

    return 0;
}

// Function to unmap the buffer
int unmap_buffer(int fd) {
    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (ioctl(fd, VIDIOC_QBUF, &buffers[i]) == -1) {
            handle_error("VIDIOC_QBUF failed during unmap");
            return -1;
        }
    }

    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (munmap((void*)(buffers[i].m.userptr), buffers[i].length) == -1) {
            handle_error("munmap failed");
            return -1;
        }
    }

    free(buffers);
    buffers = NULL;
    n_buffers = 0;

    return 0;
}

// Function to crop the image
int crop_image(void *buffer, int width, int height, int crop_width, int crop_height, CroppedImage *cropped_image) {
    size_t yuyv_size = width * height * 2; // YUYV format: 2 bytes per pixel
    size_t crop_size = crop_width * crop_height * 2;

    cropped_image->data = malloc(crop_size);
    if (!cropped_image->data) {
        handle_error("Failed to allocate memory for cropped image");
        return -1;
    }

    cropped_image->size = crop_size;

    // Calculate the starting point for cropping
    size_t start_row = (height - crop_height) / 2;
    size_t start_col = (width - crop_width) / 2;

    // Copy the cropped region
    for (int y = 0; y < crop_height; ++y) {
        for (int x = 0; x < crop_width; ++x) {
            size_t src_index = (start_row + y) * width * 2 + (start_col + x) * 2;
            size_t dest_index = y * crop_width * 2 + x * 2;
            memcpy(cropped_image->data + dest_index, buffer + src_index, 2); // Copy 2 bytes (YUYV)
        }
    }

    return 0;
}

// Function to write the cropped image to a file
int write_cropped_image(const char *filename, const CroppedImage *cropped_image) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        handle_error("Failed to open file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(cropped_image->data, 1, cropped_image->size, fp);
    if (bytes_written != cropped_image->size) {
        fprintf(stderr, "Failed to write all bytes to file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    int width = 640;
    int height = 480;
    CroppedImage cropped_image;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        handle_error("Failed to open device");
        return EXIT_FAILURE;
    }

    // Query device capabilities
    if (query_device_capabilities(fd) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Set image format
    if (set_image_format(fd, width, height) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    if (request_buffers(fd) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Map the buffer
    if (map_buffer(fd, 0) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(fd) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Capture a frame
    void *frame_buffer = NULL;
    if (capture_frame(fd, &frame_buffer) == -1) {
        if (stop_streaming(fd) == -1) {
            unmap_buffer(fd);
            close(fd);
            return EXIT_FAILURE;
        }
        close(fd);
        return EXIT_FAILURE;
    }

    // Crop the image
    if (crop_image(frame_buffer, width, height, CROP_WIDTH, CROP_HEIGHT, &cropped_image) == -1) {
        if (stop_streaming(fd) == -1) {
            unmap_buffer(fd);
            close(fd);
            return EXIT_FAILURE;
        }
        close(fd);
        return EXIT_FAILURE;
    }

    // Write the cropped image to a file
    if (write_cropped_image(CROPPED_FILE, &cropped_image) == -1) {
        if (stop_streaming(fd) == -1) {
            unmap_buffer(fd);
            close(fd);
            return EXIT_FAILURE;
        }
        close(fd);
        return EXIT_FAILURE;
    }

    // Clean up
    if (stop_streaming(fd) == -1) {
        unmap_buffer(fd);
        close(fd);
        return EXIT_FAILURE;
    }

    if (unmap_buffer(fd) == -1) {
        close(fd);
        return EXIT_FAILURE;
    }

    free(cropped_image.data);

    close(fd);

    printf("Cropped image saved to %s\n", CROPPED_FILE);

    return EXIT_SUCCESS;
}

