#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <termios.h>
#include <errno.h>

// Define GPIO pins for pan and tilt servos
#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define pulse width limits (microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define neutral position (90 degrees)
#define NEUTRAL_ANGLE 90

// Define angle increment/decrement step (5 degrees)
#define ANGLE_STEP 5

// Global variables for pan and tilt angles
int pan_angle = NEUTRAL_ANGLE;
int tilt_angle = NEUTRAL_ANGLE;

// Function prototypes
int initialize_gpio();
void set_servo_angle(int gpio_pin, int angle);
void handle_arrow_key(int key);
void handle_q_key();
void signal_handler(int signal);
int setup_terminal();
void restore_terminal();

// Terminal settings structure
struct termios orig_termios;

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM frequency for pan servo
    if (gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency for pan servo: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency for tilt servo
    if (gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency for tilt servo: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to set the angle of a servo motor
void set_servo_angle(int gpio_pin, int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Angle out of range (0-180)\n");
        return;
    }

    // Calculate pulse width based on angle
    int pulse_width = MIN_PULSE_WIDTH + (int)((float)(angle) / 180.0 * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

    // Set PWM duty cycle
    gpioPWM(gpio_pin, pulse_width);
}

// Function to handle arrow key presses
void handle_arrow_key(int key) {
    switch (key) {
        case 65: // Up arrow (pan)
            if (pan_angle + ANGLE_STEP <= 180) {
                pan_angle += ANGLE_STEP;
                set_servo_angle(PAN_SERVO_PIN, pan_angle);
            } else {
                fprintf(stderr, "Error: Pan angle exceeds maximum limit\n");
            }
            break;
        case 66: // Down arrow (pan)
            if (pan_angle - ANGLE_STEP >= 0) {
                pan_angle -= ANGLE_STEP;
                set_servo_angle(PAN_SERVO_PIN, pan_angle);
            } else {
                fprintf(stderr, "Error: Pan angle below minimum limit\n");
            }
            break;
        case 67: // Right arrow (tilt)
            if (tilt_angle + ANGLE_STEP <= 180) {
                tilt_angle += ANGLE_STEP;
                set_servo_angle(TILT_SERVO_PIN, tilt_angle);
            } else {
                fprintf(stderr, "Error: Tilt angle exceeds maximum limit\n");
            }
            break;
        case 68: // Left arrow (tilt)
            if (tilt_angle - ANGLE_STEP >= 0) {
                tilt_angle -= ANGLE_STEP;
                set_servo_angle(TILT_SERVO_PIN, tilt_angle);
            } else {
                fprintf(stderr, "Error: Tilt angle below minimum limit\n");
            }
            break;
        default:
            fprintf(stderr, "Error: Invalid arrow key\n");
            break;
    }
}

// Function to handle 'q' key press
void handle_q_key() {
    printf("Exiting...\n");
    set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE);
    set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE);
    gpioTerminate();
    exit(0);
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE);
    set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE);
    gpioTerminate();
    exit(0);
}

// Function to set terminal to non-canonical mode
int setup_terminal() {
    struct termios new_termios;

    if (tcgetattr(STDIN_FILENO, &orig_termios) != 0) {
        perror("tcgetattr");
        return 1;
    }

    new_termios = orig_termios;

    new_termios.c_lflag &= ~(ICANON | ECHO); // Disable canonical mode and echo
    new_termios.c_cc[VMIN] = 0;            // Read non-blocking
    new_termios.c_cc[VTIME] = 0;           // No timeout

    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) != 0) {
        perror("tcsetattr");
        return 1;
    }

    return 0;
}

// Function to restore terminal to original settings
void restore_terminal() {
    tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set initial servo positions to neutral
    set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE);
    set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE);

    // Set terminal to non-canonical mode
    if (setup_terminal() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Use arrow keys to control pan and tilt, 'q' to quit.\n");

    int key;
    while (1) {
        key = getchar();

        if (key == 'q') {
            handle_q_key();
        } else if (key == 27) { // Escape key (start of arrow key sequence)
            int arrow_key = getchar();
            if (arrow_key == 91) { // '['
                arrow_key = getchar();
                handle_arrow_key(arrow_key);
            }
        }

        usleep(100000); // 100 ms delay
    }

    restore_terminal();
    gpioTerminate();
    return 0;
}

