    fclose(fp);

    // Wait for 1 second
    sleep(1);

    // Read CPU stats again
    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return 0.0f;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        fclose(fp);
        return 0.0f;
    }

    fclose(fp);

    // Calculate deltas
    unsigned long long prev_total = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal;
    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal;

    unsigned long long delta_total = total - prev_total;
    unsigned long long delta_idle = idle - prev_idle;

    // Calculate CPU usage
    usage = 100.0f * (1.0f - (float)delta_idle / (float)delta_total);

    return usage;
}

// Function to initialize the OLED display
void oled_init() {
    // Initialization sequence (SSD1306)
    char init_commands[] = {
        0xAE,       // Display off
        0xD5, 0x80, // Clock divide ratio (0x80 = 100 fps)
        0xA8, 0x3F, // Multiplex ratio (63 = 64 rows)
        0xD3, 0x00, // Display offset
        0x40,       // Start line
        0x8D, 0x14, // Charge pump setting (0x14 = enable)
        0x20, 0x00, // Memory addressing mode (0x00 = horizontal)
        0xA1,       // Segment remap
        0xC8,       // COM scan direction
        0xDA, 0x12, // COM pins hardware configuration
        0x81, 0xCF, // Contrast control
        0xD9, 0xF1, // Precharge period
        0xDB, 0x40, // VCOM deselect level
        0xA4,       // Entire display ON/OFF (0xA4 = normal, 0xA5 = all ON)
        0xA6,       // Normal/Inverse display (0xA6 = normal, 0xA7 = inverse)
        0xAF        // Display on
    };

    for (int i = 0; i < sizeof(init_commands); i++) {
        if (i2cWriteByteData(i2c_handle, 0x00, init_commands[i]) < 0) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }
    }
}

// Function to clear the OLED display
void oled_clear() {
    char buffer[OLED_WIDTH * (OLED_HEIGHT / 8)];
    memset(buffer, 0x00, sizeof(buffer));

    if (i2cWriteI2CBlockData(i2c_handle, 0x40, buffer, sizeof(buffer)) < 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

// Function to draw a character on the OLED display
void oled_draw_char(int x, int y, char c) {
    if (c < 32 || c > 126) c = 0; // Handle out-of-range characters

    c -= 32; // Adjust index to font array

    for (int i = 0; i < 5; i++) {
        unsigned char pixel_data = font[c][i];
        for (int j = 0; j < 8; j++) {
            if ((pixel_data >> j) & 0x01) {
                // Calculate the position in the buffer
                int page = y / 8;
                int bit = y % 8;
                int index = x + i + (page * OLED_WIDTH) + (bit * OLED_WIDTH);

                // Set the bit in the buffer
                char buffer[OLED_WIDTH * (OLED_HEIGHT / 8)];
                memset(buffer, 0x00, sizeof(buffer));

                buffer[index] = 0x01 << bit;

                if (i2cWriteI2CBlockData(i2c_handle, 0x40, buffer, sizeof(buffer)) < 0) {
                    fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
                    exit(EXIT_FAILURE);
                }
            }
        }
    }
}

// Function to draw a string on the OLED display
void oled_draw_string(int x, int y, const char *str) {
    int current_x = x;
    int current_y = y;

    while (*str) {
        oled_draw_char(current_x, current_y, *str);
        current_x += 6; // Character width + 1 pixel spacing
        str++;
    }
}

// Function to update the OLED display (dummy function for now)
void oled_update() {
    // In this simple example, we draw directly to the display.
    // A more complex implementation might use a framebuffer.
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, OLED_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize OLED display
    oled_init();
    oled_clear();

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        float temp = read_cpu_temp();
        char temp_str[20];
        if (temp == -1.0f) {
            snprintf(temp_str, sizeof(temp_str), "Temp Err");
        } else {
            snprintf(temp_str, sizeof(temp_str), "Temp: %.1fC", temp);
        }

        // Calculate CPU usage
        float usage = calculate_cpu_usage();
        char usage_str[20];
        snprintf(usage_str, sizeof(usage_str), "CPU: %.1f%%", usage);

        // Clear the display
        oled_clear();

        // Draw the strings
        oled_draw_string(0, 0, temp_str);
        oled_draw_string(0, 16, usage_str);

        // Update the display
        oled_update();

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    oled_clear();
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

