#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <math.h>

// Configuration
#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27 // Replace with your LCD's I2C address
#define PULSES_PER_LITER 450.0 // YF-S201 specific
#define LOG_INTERVAL_SEC 1
#define LCD_UPDATE_INTERVAL_SEC 10

// Global variables
volatile int pulse_count = 0;
double total_volume = 0.0;
int i2c_handle;
FILE *log_file;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick);
double calculate_flow_rate(int pulses);
void update_lcd(double flow_rate, double total_volume);
void log_data(double flow_rate, double total_volume);
void signal_handler(int signal);
int lcd_init();
void lcd_clear();
void lcd_write_string(const char *str);
void lcd_set_cursor(int row, int col);

// LCD command functions
void lcd_send_command(unsigned char cmd);
void lcd_send_data(unsigned char data);

// Helper function to send data to LCD
void lcd_send_data(unsigned char data) {
    char buf[2];
    buf[0] = data | 0x01; // RS = 1 for data
    buf[1] = data & 0xFE; // Clear bit 0
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing data to LCD: %d\n", i2c_handle);
    }
}

// Helper function to send command to LCD
void lcd_send_command(unsigned char cmd) {
    char buf[2];
    buf[0] = cmd & 0xFE; // RS = 0 for command
    buf[1] = cmd | 0x04; // Enable bit
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing command to LCD: %d\n", i2c_handle);
    }
}

// LCD initialization function
int lcd_init() {
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Initialization sequence (refer to HD44780 datasheet)
    gpioDelay(50000); // Wait 50ms
    lcd_send_command(0x30); // Function set: 8-bit interface
    gpioDelay(5000);  // Wait 5ms
    lcd_send_command(0x30); // Function set: 8-bit interface
    gpioDelay(1000);  // Wait 1ms
    lcd_send_command(0x30); // Function set: 8-bit interface
    gpioDelay(1000);  // Wait 1ms
    lcd_send_command(0x20); // Function set: 4-bit interface
    gpioDelay(1000);  // Wait 1ms

    lcd_send_command(0x28); // Function set: 4-bit, 2 lines, 5x8 font
    lcd_send_command(0x08); // Display off
    lcd_send_command(0x01); // Clear display
    gpioDelay(2000);  // Wait 2ms
    lcd_send_command(0x06); // Entry mode set: increment cursor, no shift
    lcd_send_command(0x0C); // Display on, cursor off, blink off

    return 0;
}

// LCD clear function
void lcd_clear() {
    lcd_send_command(0x01); // Clear display
    gpioDelay(2000);  // Wait 2ms
}

// LCD write string function
void lcd_write_string(const char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        lcd_send_data(str[i]);
    }
}

// LCD set cursor function
void lcd_set_cursor(int row, int col) {
    int addr;
    switch (row) {
        case 0:
            addr = 0x00 + col;
            break;
        case 1:
            addr = 0x40 + col;
            break;
        default:
            addr = 0x00; // Default to first line
            break;
    }
    lcd_send_command(0x80 + addr); // Set DDRAM address
}

// Callback function for pulse counting
void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Function to calculate flow rate
double calculate_flow_rate(int pulses) {
    return (double)pulses / PULSES_PER_LITER / LOG_INTERVAL_SEC; // Liters per second
}

// Function to update the LCD display
void update_lcd(double flow_rate, double total_volume) {
    char flow_str[20];
    char volume_str[20];

    snprintf(flow_str, sizeof(flow_str), "Flow: %.2f L/s", flow_rate);
    snprintf(volume_str, sizeof(volume_str), "Vol: %.2f L", total_volume);

    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_write_string(flow_str);
    lcd_set_cursor(1, 0);
    lcd_write_string(volume_str);
}

// Function to log data to console and file
void log_data(double flow_rate, double total_volume) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s - Flow Rate: %.2f L/s, Total Volume: %.2f L\n", timestamp, flow_rate, total_volume);
    fprintf(log_file, "%s - Flow Rate: %.2f L/s, Total Volume: %.2f L\n", timestamp, flow_rate, total_volume);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, NULL, NULL); // Disable callback
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    if (lcd_init() != 0) {
        fprintf(stderr, "LCD initialization failed!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode and pull-up/down resistor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP);

    // Set up interrupt callback
    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt callback!\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_lcd_update = time(NULL);
    time_t last_log_update = time(NULL);

    // Main loop
    while (1) {
        time_t now = time(NULL);

        // Update flow rate and total volume every LOG_INTERVAL_SEC
        if (now - last_log_update >= LOG_INTERVAL_SEC) {
            double flow_rate = calculate_flow_rate(pulse_count);
            total_volume += flow_rate * LOG_INTERVAL_SEC;
            log_data(flow_rate, total_volume);
            pulse_count = 0; // Reset pulse count
            last_log_update = now;
        }

        // Update LCD every LCD_UPDATE_INTERVAL_SEC
        if (now - last_lcd_update >= LCD_UPDATE_INTERVAL_SEC) {
            double flow_rate = calculate_flow_rate(pulse_count);
            total_volume += flow_rate * LCD_UPDATE_INTERVAL_SEC;
            update_lcd(flow_rate, total_volume);
            pulse_count = 0; // Reset pulse count
            last_lcd_update = now;
        }

        gpioDelay(100); // Small delay to prevent busy-waiting
    }

    return 0;
}

