// Configuration
#define ANEMOMETER_PIN 17 // BCM GPIO17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define I2C_ADDR 0x27       // PCF8574 I2C address
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define SAMPLE_WINDOW_MS 500

// Global variables
volatile int pulse_count = 0;
int i2c_fd;
int spi_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void pulse_counter_isr(void);
float calculate_wind_speed(int pulses);
int read_wind_direction(void);
void lcd_init(void);
void lcd_clear(void);
void lcd_set_cursor(int row, int col);
void lcd_print(const char *str);
