#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>
#include <wiringPiI2C.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define LCD_I2C_ADDR 0x27 // Change if needed
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define PULSES_PER_LITER 450.0 // YF-S201 specific
#define SENSOR_TIMEOUT_SEC 5

// Global variables
volatile int pulse_count = 0;
int lcd_fd;
int sensor_timeout_counter = 0;
int running = 1;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick);
float calculate_flow_rate(int pulses);
void lcd_init();
void lcd_clear();
void lcd_set_cursor(int row, int col);
void lcd_print(const char *str);
void display_flow_rate(float flow_rate);
void signal_handler(int signal);
void check_sensor_status();

// LCD command functions
void lcd_send_command(unsigned char cmd);
void lcd_send_data(unsigned char data);

// Helper function to send data to LCD
void lcd_send_nibble(unsigned char nibble, int is_data) {
    unsigned char data_u, data_l;
    unsigned char data_t[4];
    data_u = nibble & 0xF0;
    data_l = (nibble << 4) & 0xF0;

    data_t[0] = data_u | 0x0C; // Enable pulse high
    data_t[1] = data_u | 0x08; // Enable pulse low
    data_t[2] = data_l | 0x0C; // Enable pulse high
    data_t[3] = data_l | 0x08; // Enable pulse low

    for (int i = 0; i < 4; i++) {
        if (is_data) {
            data_t[i] |= 0x01; // RS = 1 for data
        } else {
            data_t[i] &= ~0x01; // RS = 0 for command
        }
        wiringPiI2CWrite(lcd_fd, data_t[i]);
    }
}

// Function to send a command to the LCD
void lcd_send_command(unsigned char cmd) {
    lcd_send_nibble(cmd >> 4, 0); // Send upper nibble
    lcd_send_nibble(cmd & 0x0F, 0); // Send lower nibble
}

// Function to send data to the LCD
void lcd_send_data(unsigned char data) {
    lcd_send_nibble(data >> 4, 1); // Send upper nibble
    lcd_send_nibble(data & 0x0F, 1); // Send lower nibble
}

// LCD initialization function
void lcd_init() {
    // Initialize LCD in 4-bit mode
    gpioDelay(50000); // Wait for LCD to power up
    lcd_send_command(0x33); // Initialize
    lcd_send_command(0x32); // Initialize
    lcd_send_command(0x28); // 4-bit mode, 2 lines, 5x8 font
    lcd_send_command(0x0C); // Display on, cursor off, blink off
    lcd_send_command(0x06); // Increment cursor, no shift
    lcd_send_command(0x01); // Clear display
    gpioDelay(2000);       // Wait for clear display to complete
}

// LCD clear function
void lcd_clear() {
    lcd_send_command(0x01); // Clear display
    gpioDelay(2000);       // Wait for clear display to complete
}

// LCD set cursor function
void lcd_set_cursor(int row, int col) {
    int addr;
    if (row == 0) {
        addr = 0x80 + col;
    } else {
        addr = 0xC0 + col;
    }
    lcd_send_command(addr);
}

// LCD print function
void lcd_print(const char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        lcd_send_data(str[i]);
    }
}

// Function to calculate flow rate in L/min
float calculate_flow_rate(int pulses) {
    return (float)pulses / PULSES_PER_LITER * 60.0;
}

// Function to display flow rate on LCD
void display_flow_rate(float flow_rate) {
    char buffer[17]; // Ensure buffer is large enough
    snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/min", flow_rate);
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_print("Flow Rate: ");
    lcd_set_cursor(1, 0);
    lcd_print(buffer);
}

// Interrupt handler for flow sensor pulses
void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) { // Count rising edges
        pulse_count++;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Function to check sensor status and handle timeout
void check_sensor_status() {
    if (pulse_count == 0) {
        sensor_timeout_counter++;
        if (sensor_timeout_counter >= SENSOR_TIMEOUT_SEC) {
            lcd_clear();
            lcd_set_cursor(0, 0);
            lcd_print("Sensor Timeout!");
            printf("Sensor timeout detected!\n");
        }
    } else {
        sensor_timeout_counter = 0; // Reset counter if pulses are detected
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPi initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    lcd_fd = wiringPiI2CSetup(LCD_I2C_ADDR);
    if (lcd_fd == -1) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    lcd_init();
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_print("Initializing...");

    // Set GPIO mode for flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Set up interrupt handler for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set up interrupt handler\n");
        lcd_clear();
        lcd_set_cursor(0, 0);
        lcd_print("ISR Setup Failed");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        gpioDelay(1000); // Wait for 1 second

        // Calculate flow rate
        float flow_rate = calculate_flow_rate(pulse_count);

        // Display flow rate on LCD
        display_flow_rate(flow_rate);

        // Reset pulse count
        pulse_count = 0;

        // Check sensor status
        check_sensor_status();
    }

    // Clean up resources before exiting
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_print("Exiting...");
    gpioTerminate();
    return 0;
}

