#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for rows and columns
const int rows[] = {17, 18, 27, 22, 23, 24, 25, 4};
const int cols[] = {5, 6, 12, 13, 19, 16, 26, 20};

// Define the wave pattern
const int wave[] = {0x80, 0x40, 0x20, 0x10, 0x08, 0x04, 0x02, 0x01};

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set row pins as outputs
    for (int i = 0; i < 8; i++) {
        if (gpioSetMode(rows[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set row pin %d as output\n", rows[i]);
            gpioTerminate();
            return -1;
        }
    }

    // Set column pins as outputs
    for (int i = 0; i < 8; i++) {
        if (gpioSetMode(cols[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set column pin %d as output\n", cols[i]);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

// Function to clear the LED matrix
void clear_matrix() {
    for (int i = 0; i < 8; i++) {
        gpioWrite(rows[i], 0); // Turn off row
        for (int j = 0; j < 8; j++) {
            gpioWrite(cols[j], 1); // Turn on column (common anode)
        }
    }
}

// Function to display a frame on the LED matrix
void display_frame(int frame_data[]) {
    for (int i = 0; i < 8; i++) {
        gpioWrite(rows[i], 1); // Turn on row
        for (int j = 0; j < 8; j++) {
            if ((frame_data[i] >> j) & 1) {
                gpioWrite(cols[j], 0); // Turn off column (common anode) to light LED
            } else {
                gpioWrite(cols[j], 1); // Turn on column (common anode) to turn off LED
            }
        }
        gpioDelay(800); // Delay for 800 microseconds
        gpioWrite(rows[i], 0); // Turn off row
        for (int j = 0; j < 8; j++) {
            gpioWrite(cols[j], 1); // Turn on column (common anode)
        }
    }
}

// Function to shift the wave pattern left
void shift_left(int wave[]) {
    int temp = wave[0];
    for (int i = 0; i < 7; i++) {
        wave[i] = wave[i + 1];
    }
    wave[7] = temp;
}

// Function to shift the wave pattern right
void shift_right(int wave[]) {
    int temp = wave[7];
    for (int i = 7; i > 0; i--) {
        wave[i] = wave[i - 1];
    }
    wave[0] = temp;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (program_running) {
        // Left-to-right animation
        for (int i = 0; i < 8; i++) {
            display_frame(wave);
            shift_left(wave);
        }

        // Right-to-left animation
        for (int i = 0; i < 8; i++) {
            display_frame(wave);
            shift_right(wave);
        }
    }

    // Cleanup: Turn off all LEDs and terminate pigpio
    clear_matrix();
    gpioTerminate();

    return 0;
}

