#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PARTID 0x00
#define SI1145_REG_REVID 0x01
#define SI1145_REG_SEQID 0x02

#define SI1145_REG_UCOEF0 0x13
#define SI1145_REG_UCOEF1 0x14
#define SI1145_REG_UCOEF2 0x15
#define SI1145_REG_UCOEF3 0x16

#define SI1145_REG_PARAM_WR 0x17
#define SI1145_REG_COMMAND 0x18
#define SI1145_REG_RESPONSE0 0x20
#define SI1145_REG_RESPONSE1 0x21
#define SI1145_REG_RESPONSE2 0x22
#define SI1145_REG_RESPONSE3 0x23

#define SI1145_REG_IRQ_ENABLE 0x03
#define SI1145_REG_IRQ_MODE1 0x04
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_ALS_RATE 0x0A
#define SI1145_REG_ALS_IR_RATE 0x0B
#define SI1145_REG_PS_RATE 0x0C
#define SI1145_REG_PS1_RATE 0x0D
#define SI1145_REG_PS2_RATE 0x0E
#define SI1145_REG_PS3_RATE 0x0F

#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_ALS_IR_DATA0 0x24
#define SI1145_REG_ALS_IR_DATA1 0x25
#define SI1145_REG_PS1_DATA0 0x26
#define SI1145_REG_PS1_DATA1 0x27

#define SI1145_HW_KEY_VAL 0x17
#define SI1145_RESET 0x01

// Commands
#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_ALS_FORCE 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int si1145_read_data(uint16_t *proximity, uint16_t *ambient_light);
void log_data(const char *timestamp, uint16_t proximity, uint16_t ambient_light);
void signal_handler(int signal);
char* iso8601_timestamp();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to generate ISO 8601 timestamp
char* iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to initialize the Si1145 sensor
int si1145_init() {
    // Reset the device
    if (i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1145_REG_MEAS_RATE0, 0xFF) < 0) {
        fprintf(stderr, "Error: Failed to write MEAS_RATE0.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1145_REG_MEAS_RATE1, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write MEAS_RATE1.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1145_REG_ALS_RATE, 0xFF) < 0) {
        fprintf(stderr, "Error: Failed to write ALS_RATE.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1145_REG_PS_RATE, 0xFF) < 0) {
        fprintf(stderr, "Error: Failed to write PS_RATE.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1145_REG_IRQ_ENABLE, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write IRQ_ENABLE.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) {
        fprintf(stderr, "Error: Failed to write command.\n");
        return -1;
    }

    return 0;
}

// Function to read data from the Si1145 sensor
int si1145_read_data(uint16_t *proximity, uint16_t *ambient_light) {
    int result;

    // Read proximity data
    result = i2cReadWordData(i2c_handle, SI1145_REG_PS1_DATA0);
    if (result < 0) {
        fprintf(stderr, "Error: Failed to read proximity data.\n");
        return -1;
    }
    *proximity = (uint16_t)result;

    // Read ambient light data
    result = i2cReadWordData(i2c_handle, SI1145_REG_ALS_VIS_DATA0);
    if (result < 0) {
        fprintf(stderr, "Error: Failed to read ambient light data.\n");
        return -1;
    }
    *ambient_light = (uint16_t)result;

    return 0;
}

// Function to log data to a file
void log_data(const char *timestamp, uint16_t proximity, uint16_t ambient_light) {
    fprintf(log_file, "%s,%u,%u\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (si1145_init() < 0) {
        fprintf(stderr, "Error: Si1145 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t proximity, ambient_light;
        char* timestamp = iso8601_timestamp();

        // Read sensor data
        if (si1145_read_data(&proximity, &ambient_light) == 0) {
            // Log data
            log_data(timestamp, proximity, ambient_light);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }

        free(timestamp);

        // Wait 500ms
        gpioDelay(500);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

