int get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return 0;
}

