    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    int last_sensor_value = 1; // Initialize to HIGH (no object detected)

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int current_sensor_value = read_sensor();

        if (current_sensor_value == 0 && last_sensor_value == 1) {
            // Falling edge detected (object detected)
            char timestamp[21];
            if (get_iso8601_timestamp(timestamp) == 0) {
                if (log_detection(timestamp) == 0) {
                    blink_led();
                } else {
                    fprintf(stderr, "Error blinking LED\n");
                }
            } else {
                fprintf(stderr, "Error getting timestamp\n");
            }
        }

        last_sensor_value = current_sensor_value;
        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup GPIO
    gpioTerminate();
    printf("GPIO terminated. Exiting.\n");
    return 0;
}

