#include <pigpio.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_PS1_DATA0 0x24

// Expected PART_ID value
#define SI1145_PART_ID_VALUE 0x45

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_read_register(int handle, uint8_t reg);
int si1145_write_register(int handle, uint8_t reg, uint8_t value);
int si1145_init(int handle);
int si1145_read_proximity(int handle);
int si1145_read_ambient_light(int handle);
void signal_handler(int signal);
int get_iso8601_timestamp(char *timestamp);

// Function to read a single byte from a Si1145 register
int si1145_read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to a Si1145 register
int si1145_write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the Si1145 sensor
int si1145_init(int handle) {
    // Reset the device
    if (si1145_write_register(handle, 0x07, 0x00) < 0) return -1;
    gpioDelay(10); // Delay for reset to complete

    // Configure the sensor (example configuration - adjust as needed)
    if (si1145_write_register(handle, 0x18, 0x7B) < 0) return -1; // UCOEF
    if (si1145_write_register(handle, 0x19, 0x6B) < 0) return -1; // UCOEF
    if (si1145_write_register(handle, 0x1A, 0x00) < 0) return -1; // UCOEF
    if (si1145_write_register(handle, 0x1B, 0x00) < 0) return -1; // UCOEF
    if (si1145_write_register(handle, 0x1C, 0x00) < 0) return -1; // UCOEF
    if (si1145_write_register(handle, 0x1D, 0x00) < 0) return -1; // UCOEF
    if (si1145_write_register(handle, 0x1E, 0x00) < 0) return -1; // UCOEF
    if (si1145_write_register(handle, 0x1F, 0x00) < 0) return -1; // UCOEF

    if (si1145_write_register(handle, 0x08, 0x03) < 0) return -1; // MEASRATE
    if (si1145_write_register(handle, 0x09, 0x00) < 0) return -1; // MEASRATE
    if (si1145_write_register(handle, 0x0A, 0x00) < 0) return -1; // MEASRATE
    if (si1145_write_register(handle, 0x0B, 0x00) < 0) return -1; // MEASRATE

    if (si1145_write_register(handle, 0x0C, 0x01) < 0) return -1; // ALS_EN
    if (si1145_write_register(handle, 0x0D, 0x01) < 0) return -1; // PS_EN

    if (si1145_write_register(handle, 0x07, 0x01) < 0) return -1; // HW_KEY

    return 0;
}

// Function to read the proximity value from the Si1145 sensor
int si1145_read_proximity(int handle) {
    int result = si1145_read_register(handle, SI1145_REG_PS1_DATA0);
    if (result < 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }
    return result;
}

// Function to read the ambient light value from the Si1145 sensor
int si1145_read_ambient_light(int handle) {
    int result = si1145_read_register(handle, SI1145_REG_ALS_VIS_DATA0);
    if (result < 0) {
        fprintf(stderr, "Error reading ambient light data\n");
        return -1;
    }
    return result;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to get the current timestamp in ISO 8601 format
int get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting time information\n");
        return -1;
    }

    if (strftime(timestamp, 32, "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor PART_ID
    int part_id = si1145_read_register(i2c_handle, SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (part_id != SI1145_PART_ID_VALUE) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID_VALUE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (si1145_init(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        int proximity = si1145_read_proximity(i2c_handle);
        int ambient_light = si1145_read_ambient_light(i2c_handle);

        if (proximity < 0 || ambient_light < 0) {
            fprintf(stderr, "Error reading sensor data\n");
        } else {
            // Get timestamp
            char timestamp[32];
            if (get_iso8601_timestamp(timestamp) == 0) {
                // Log data to file
                fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
                fflush(log_file); // Flush the buffer to ensure data is written
            } else {
                fprintf(stderr, "Error getting timestamp\n");
            }
        }

        sleep(1); // Sample once per second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

