#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30 ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define WATERING_THRESHOLD 15.0 // cm
#define LOG_FILE "distance_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    double distance;
    int status;
} SensorData;

// Function prototypes
void signal_handler(int signal);
int initialize();
void trigger_pulse();
long long measure_pulse_width();
double calculate_distance(long long pulse_width);
int validate_distance(double distance);
void log_data(SensorData data);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio and GPIO pins
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); // Wait 1ms

    return 0;
}

// Generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the pulse width of the echo signal
long long measure_pulse_width() {
    long long start_tick, end_tick, pulse_width;

    // Wait for echo to go high (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout waiting for rising edge
    }

    start_tick = gpioTick();

    // Wait for echo to go low (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        return -2; // Timeout waiting for falling edge
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick rollover
    }

    return pulse_width;
}

// Calculate distance from pulse width
double calculate_distance(long long pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Validate distance reading
int validate_distance(double distance) {
    return (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE);
}

// Log data to file
void log_data(SensorData data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        if (data.status == 0) {
            fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, data.distance);
            if (data.distance < WATERING_THRESHOLD) {
                fprintf(log_file, "%s, Time to water the plant!\n", timestamp);
            }
        } else {
            fprintf(log_file, "%s, Error: %d\n", timestamp, data.status);
        }
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(TRIGGER_PIN, 0); // Set trigger low
    gpioSetMode(TRIGGER_PIN, PI_INPUT); // Set trigger to input
    gpioSetMode(ECHO_PIN, PI_INPUT); // Set echo to input

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    while (running) {
        SensorData data;
        data.status = 0; // Assume success initially

        trigger_pulse();
        long long pulse_width = measure_pulse_width();

        if (pulse_width == -1) {
            data.status = 1; // Timeout waiting for rising edge
            fprintf(stderr, "Timeout waiting for rising edge\n");
        } else if (pulse_width == -2) {
            data.status = 2; // Timeout waiting for falling edge
            fprintf(stderr, "Timeout waiting for falling edge\n");
        } else {
            data.distance = calculate_distance(pulse_width);

            if (!validate_distance(data.distance)) {
                data.status = 3; // Invalid distance
                fprintf(stderr, "Invalid distance: %.2f cm\n", data.distance);
            }
        }

        log_data(data);

        gpioDelay(60000); // Wait 60 seconds
    }

    cleanup();
    return 0;
}

