#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// APDS9960 I2C address
#define APDS9960_I2C_ADDR 0x39

// APDS9960 register addresses
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_PTIME 0x82
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0x8F
#define APDS9960_CONFIG1 0x90
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATAL 0x9C

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t green;
    uint16_t blue;
    uint8_t proximity;
} sensor_data_t;

// Function prototypes
int init_apds9960();
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize the APDS9960 sensor
int init_apds9960() {
    // Enable power and proximity sensing
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03) < 0) {
        perror("Error writing to ENABLE register");
        return -1;
    }

    // Set proximity pulse length to 1 pulse
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x01) < 0) {
        perror("Error writing to PPULSE register");
        return -1;
    }

    // Set proximity gain to 4x
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x60) < 0) {
        perror("Error writing to CONTROL register");
        return -1;
    }

    return 0;
}

// Read sensor data from the APDS9960
int read_sensor_data(sensor_data_t *data) {
    uint8_t status;

    // Read proximity data
    status = i2cReadByteData(i2c_handle, APDS9960_STATUS);
    if (status < 0) {
        perror("Error reading STATUS register");
        return -1;
    }

    if (status & 0x04) {
        data->proximity = i2cReadByteData(i2c_handle, APDS9960_PDATAL);
        if (data->proximity < 0) {
            perror("Error reading PDATAL register");
            return -1;
        }

        // Read color data
        data->red = i2cReadByteData(i2c_handle, APDS9960_RDATAL) | (i2cReadByteData(i2c_handle, APDS9960_RDATAH) << 8);
        if (data->red < 0) {
            perror("Error reading RDATAL register");
            return -1;
        }

        data->green = i2cReadByteData(i2c_handle, APDS9960_GDATAL) | (i2cReadByteData(i2c_handle, APDS9960_GDATAH) << 8);
        if (data->green < 0) {
            perror("Error reading GDATAL register");
            return -1;
        }

        data->blue = i2cReadByteData(i2c_handle, APDS9960_BDATAL) | (i2cReadByteData(i2c_handle, APDS9960_BDATAH) << 8);
        if (data->blue < 0) {
            perror("Error reading BDATAL register");
            return -1;
        }
    } else {
        data->red = 0;
        data->green = 0;
        data->blue = 0;
        data->proximity = 0;
    }

    return 0;
}

// Log data to the CSV file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, data.red, data.green, data.blue, data.proximity);
    fflush(log_file);

    return 0;
}

int main() {
    sensor_data_t sensor_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the APDS9960 sensor
    if (init_apds9960() < 0) {
        fprintf(stderr, "APDS9960 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the CSV header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Check for proximity event
            if (sensor_data.proximity > PROXIMITY_THRESHOLD) {
                // Log the data
                log_data(sensor_data);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, re-initializing...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %s\n", strerror(errno));
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (init_apds9960() < 0) {
                    fprintf(stderr, "APDS9960 re-initialization failed\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

