#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PROX_DATA_REG 0x02 // Example register address, adjust as needed
#define HEART_RATE_WINDOW_MS 1000
#define SAMPLE_INTERVAL_MS 100
#define HEART_RATE_MIN 40
#define HEART_RATE_MAX 200

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t running = 1;

// Structure to hold sensor data
typedef struct {
    int prox_value;
    struct timespec timestamp;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_proximity_data(int *prox_value);
double calculate_bpm(sensor_data_t *data, int window_size);
int write_to_csv(struct timespec ts, double bpm);
void signal_handler(int signal);
char* get_iso8601_timestamp(struct timespec ts);

// Signal handler
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read proximity data from the sensor
int read_proximity_data(int *prox_value) {
    int result = i2cReadWordData(i2c_handle, PROX_DATA_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading proximity data: %d\n", result);
        return -1;
    }
    *prox_value = result; // Assuming the data is a 16-bit value
    return 0;
}

// Calculate BPM from proximity data
double calculate_bpm(sensor_data_t *data, int window_size) {
    if (window_size < 2) return 0.0; // Need at least two data points

    int peaks = 0;
    for (int i = 1; i < window_size - 1; i++) {
        if (data[i].prox_value > data[i - 1].prox_value && data[i].prox_value > data[i + 1].prox_value) {
            peaks++;
        }
    }

    // Estimate BPM based on the number of peaks in the window
    double bpm = (double)peaks * 60.0 / ((double)window_size * SAMPLE_INTERVAL_MS / 1000.0); // Convert ms to seconds

    // Clamp BPM to a reasonable range
    if (bpm < HEART_RATE_MIN) bpm = HEART_RATE_MIN;
    if (bpm > HEART_RATE_MAX) bpm = HEART_RATE_MAX;

    return bpm;
}

