    time_t rawtime = ts.tv_sec;
    struct tm *info;
    char *buffer = malloc(30 * sizeof(char)); // Allocate memory for the timestamp string
    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    info = localtime(&rawtime);
    if (info == NULL) {
        perror("Failed to get local time");
        free(buffer);
        return NULL;
    }

    strftime(buffer, 30, "%Y-%m-%dT%H:%M:%S", info);
    snprintf(buffer + strlen(buffer), 30 - strlen(buffer), ".%09ldZ", ts.tv_nsec);

    return buffer;
}

