    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    fp = fopen("heartrate.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Data buffer for BPM calculation
    int window_size = HEART_RATE_WINDOW_MS / SAMPLE_INTERVAL_MS;
    sensor_data_t data_buffer[window_size];
    int data_index = 0;

    // Main loop
    while (running) {
        int prox_value;
        struct timespec ts;

        // Read proximity data
        if (read_proximity_data(&prox_value) == 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            data_buffer[data_index].prox_value = prox_value;
            data_buffer[data_index].timestamp = ts;

            // Calculate BPM if enough data is available
            if (data_index >= window_size - 1) {
                double bpm = calculate_bpm(data_buffer, window_size);
                if (write_to_csv(ts, bpm) != 0) {
                    fprintf(stderr, "Error writing to CSV\n");
                }
            }

            data_index = (data_index + 1) % window_size; // Circular buffer
        } else {
            fprintf(stderr, "Failed to read proximity data, skipping sample\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

