int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    char buf[2];
    int result;

    // Trigger measurement (if needed, depends on the sensor)
    // For CH101, no trigger is needed, it continuously measures

    // Wait for measurement to complete
    gpioDelay(TRIGGER_DELAY_MS * 1000); // Delay in microseconds

    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

// Log distance to file and stdout
int log_distance(int distance) {
    char timestamp_buffer[20];

    if (get_timestamp(timestamp_buffer, sizeof(timestamp_buffer)) == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return -1;
    }

    fprintf(log_file, "%s, %d\n", timestamp_buffer, distance);
    fflush(log_file); // Ensure data is written to disk immediately
    printf("%s, %d\n", timestamp_buffer, distance);

    return 0;
}

