char* get_timestamp(char* timestamp_buffer, size_t buffer_size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = localtime(&timer);

    if (strftime(timestamp_buffer, buffer_size, "%Y-%m-%d %H:%M:%S", tm_info) == 0) {
        return NULL; // Error formatting timestamp
    }
    return timestamp_buffer;
}

