    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance
        result = read_distance(&distance);
        if (result == 0) {
            // Log distance
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Error logging distance\n");
            }
        } else {
            fprintf(stderr, "Error reading distance, skipping sample\n");
        }

        // Wait for next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

