// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor data with retries
int read_sensor_data(int handle, int *proximity, int *ambient_light) {
    int retries = 0;
    int status;

    while (retries < MAX_RETRIES) {
        // Read proximity data
        status = i2cReadByteData(handle, PROX_DATA_REG);
        if (status < 0) {
            fprintf(stderr, "Error reading proximity data (attempt %d): %d\n", retries + 1, status);
            gpioDelay(10); // Small delay before retrying
            retries++;
            continue;
        }
        *proximity = status;

        // Read ambient light data
        status = i2cReadByteData(handle, ALS_DATA_REG);
        if (status < 0) {
            fprintf(stderr, "Error reading ambient light data (attempt %d): %d\n", retries + 1, status);
            gpioDelay(10); // Small delay before retrying
            retries++;
            continue;
        }
        *ambient_light = status;

        // If both reads were successful, return 0 (success)
        return 0;
    }

    // If all retries failed, return an error code
    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1;
}

