int log_data(FILE *fp, int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d\n", timestamp, proximity, ambient_light) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

