#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define MEASURE_COMMAND_SIZE 4
#define MEASURE_COMMAND {0x01, 0x02, 0x03, 0x04}
#define RESPONSE_SIZE 15
#define HEADER_VALUE 0xAA
#define DISTANCE_BYTES 2
#define SAMPLES_PER_CYCLE 10
#define SAMPLE_DELAY_MS 100
#define INTRUSION_THRESHOLD_MM 1000
#define INTRUSION_THRESHOLD_M 1.0
#define LOG_FILE "intrusion_log.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
int verify_header(uint8_t *data);
int extract_distance(uint8_t *data, uint16_t *distance);
float calculate_average_distance(uint16_t *distances, int num_samples);
int log_intrusion(float average_distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads data from the sensor
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, RESPONSE_SIZE);
    if (bytes_read != RESPONSE_SIZE) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Verifies the header of the response
int verify_header(uint8_t *data) {
    if (data[0] != HEADER_VALUE) {
        fprintf(stderr, "Header verification failed: 0x%02X != 0x%02X\n", data[0], HEADER_VALUE);
        return -1;
    }
    return 0;
}

// Extracts the distance from the response
int extract_distance(uint8_t *data, uint16_t *distance) {
    *distance = (uint16_t)((((uint16_t)data[11]) << 8) | (uint16_t)data[12]);
    return 0;
}

// Calculates the average distance from an array of distances
float calculate_average_distance(uint16_t *distances, int num_samples) {
    float sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += distances[i];
    }
    return sum / num_samples;
}

// Logs the intrusion event to a file
int log_intrusion(float average_distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, average_distance);
    fclose(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    uint8_t command[MEASURE_COMMAND_SIZE] = MEASURE_COMMAND;
    uint8_t response[RESPONSE_SIZE];
    uint16_t distances[SAMPLES_PER_CYCLE];
    uint16_t distance;
    float average_distance;

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (i2cWriteDevice(i2c_handle, (char *)command, MEASURE_COMMAND_SIZE) != MEASURE_COMMAND_SIZE) {
            fprintf(stderr, "Error writing to I2C\n");
            break;
        }

        // Wait for measurement to complete
        gpioDelay(10); // 10 ms

        // Read sensor data
        if (read_sensor_data(response) != 0) {
            break;
        }

        // Verify header
        if (verify_header(response) != 0) {
            break;
        }

        // Extract distance
        if (extract_distance(response, &distance) != 0) {
            break;
        }

        distances[0] = distance;

        // Sample the sensor multiple times
        for (int i = 1; i < SAMPLES_PER_CYCLE; i++) {
            if (i2cWriteDevice(i2c_handle, (char *)command, MEASURE_COMMAND_SIZE) != MEASURE_COMMAND_SIZE) {
                fprintf(stderr, "Error writing to I2C\n");
                break;
            }
            gpioDelay(SAMPLE_DELAY_MS);
            if (read_sensor_data(response) != 0) {
                break;
            }
            if (verify_header(response) != 0) {
                break;
            }
            if (extract_distance(response, &distance) != 0) {
                break;
            }
            distances[i] = distance;
        }

        // Calculate average distance
        average_distance = calculate_average_distance(distances, SAMPLES_PER_CYCLE);

        // Check for intrusion
        if (average_distance < INTRUSION_THRESHOLD_MM) {
            if (log_intrusion(average_distance) != 0) {
                break;
            }
        }

        // Delay before next cycle
        gpioDelay(100); // 100 ms
    }

    // Cleanup
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

