#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4A // Replace with the actual I2C address

// Define the register address for distance measurement (replace with actual value)
#define DISTANCE_REG 0x00

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to set the I2C slave address
int set_i2c_slave(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a register from the I2C device
int read_register(int fd, unsigned char reg) {
    unsigned char buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return buf[0];
}

// Function to read the distance from the MLX75030
int read_distance(int fd) {
    int distance = read_register(fd, DISTANCE_REG);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance from MLX75030\n");
        return -1;
    }
    return distance;
}

// Function to print the distance to stdout
void print_distance(int distance) {
    printf("Distance: %d mm\n", distance);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C bus. Exiting.\n");
        return 1;
    }

    // Set the I2C slave address
    if (set_i2c_slave(i2c_fd, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the distance
        int distance = read_distance(i2c_fd);

        // Print the distance if the read was successful
        if (distance >= 0) {
            print_distance(distance);
        }

        // Sleep for 500ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 500ms
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

