        return -1;
    }
    return 0;
}

// Function to read distance data from the OPT3101
int read_distance(int handle, uint16_t *distance) {
    uint8_t data[2];
    if (read_register(handle, OPT3101_REG_DISTANCE, data, 2) != 0) {
        return -1;
    }
    *distance = (data[0] << 8) | data[1];
    return 0;
}

// Function to read ambient light data from the OPT3101
int read_ambient(int handle, uint16_t *ambient) {
    uint8_t data[2];
    if (read_register(handle, OPT3101_REG_AMBIENT, data, 2) != 0) {
        return -1;
    }
    *ambient = (data[0] << 8) | data[1];
    return 0;
}

// Function to read status data from the OPT3101
int read_status(int handle, uint8_t *status) {
    if (read_register(handle, OPT3101_REG_STATUS, status, 1) != 0) {
        return -1;
    }
    return 0;
}

