    i2c_handle = i2cOpen(1, OPT3101_ADDR, 0); // Bus 1, address 0x64, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t distance;
        uint16_t ambient;
        uint8_t status;

        // Read distance
        if (read_distance(i2c_handle, &distance) != 0) {
            fprintf(stderr, "Error reading distance\n");
        } else {
            // Read ambient light
            if (read_ambient(i2c_handle, &ambient) != 0) {
                fprintf(stderr, "Error reading ambient light\n");
            } else {
                // Read status
                if (read_status(i2c_handle, &status) != 0) {
                    fprintf(stderr, "Error reading status\n");
                } else {
                    // Log data to console
                    printf("Distance: %d, Ambient: %d, Status: 0x%02X\n", distance, ambient, status);
                }
            }
        }

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

