#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 200000       // Timeout in microseconds (200ms)
#define MAX_DISTANCE_US 38000   // Maximum distance in microseconds (38ms)

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to measure distance using HC-SR04 sensor
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo rising edge
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Timeout waiting for rising edge\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo falling edge
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Timeout waiting for falling edge\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    // Calculate pulse duration
    diff_tick = end_tick - start_tick;

    if (diff_tick <= 0) {
        fprintf(stderr, "Error: Invalid pulse duration (<= 0 us)\n");
        return -1.0; // Indicate invalid pulse duration
    }

    if (diff_tick > MAX_DISTANCE_US) {
        fprintf(stderr, "Error: Invalid pulse duration (> 38 ms)\n");
        return -1.0; // Indicate invalid pulse duration
    }

    // Calculate distance in centimeters
    float distance = (diff_tick * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 100 to convert m to cm

    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Measure distance
        float distance = measure_distance();

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        // Log data to console
        if (distance >= 0) {
            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s Distance: %.2f cm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Error: Invalid distance measurement\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

