#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define GPIO_PIN 17
#define MAGIC_WORD_LENGTH 8
#define RANGE_PROFILE_LENGTH 128
#define TARGET_THRESHOLD 1.0 // meters
#define ALERT_DURATION 2 // seconds
#define MAX_RETRIES 3

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;

// Structure for configuration
typedef struct {
    int gpio_pin;
    float target_threshold;
    char *uart_device;
    int baud_rate;
} Config;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_uart_data(int fd, unsigned char *buffer, int length);
int validate_magic_word(const unsigned char *buffer, int length);
float decode_range_profile(const unsigned char *buffer, int length);
int detect_target(float distance);
int log_intrusion(float distance);
int activate_alert(int gpio_pin, int duration);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize UART
int initialize_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_lflag = 0;        // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;        // no remapping, no delays
    tty.c_cc[VMIN] = 0;      // read doesn't block
    tty.c_cc[VTIME] = 5;     // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from UART
int read_uart_data(int fd, unsigned char *buffer, int length) {
    ssize_t bytes_read = read(fd, buffer, length);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read != length) {
        fprintf(stderr, "Warning: Read %zd bytes, expected %d\n", bytes_read, length);
        return -1; // Indicate incomplete read
    }
    return 0;
}

// Validate magic word
int validate_magic_word(const unsigned char *buffer, int length) {
    const unsigned char magic_word[] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    if (length != sizeof(magic_word)) return 0;
    return memcmp(buffer, magic_word, sizeof(magic_word)) == 0;
}

// Decode range profile data
float decode_range_profile(const unsigned char *buffer, int length) {
    if (length != RANGE_PROFILE_LENGTH) {
        fprintf(stderr, "Error: Invalid range profile length: %d\n", length);
        return -1.0; // Indicate error
    }

    // Find the minimum value in the range profile
    int16_t min_value = 65535; // Initialize to maximum possible value
    for (int i = 0; i < 64; i++) {
        int16_t value = (buffer[i * 2 + 1] << 8) | buffer[i * 2];
        if (value < min_value) {
            min_value = value;
        }
    }

    // Convert the minimum value to a distance (example scaling)
    float distance = (float)min_value * 0.01; // Example: 1 unit = 0.01 meters
    return distance;
}

// Detect target
int detect_target(float distance) {
    return (distance <= TARGET_THRESHOLD);
}

// Log intrusion
int log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fclose(log_file);
    return 0;
}

// Activate alert
int activate_alert(int gpio_pin, int duration) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(duration * 1000000); // Delay for specified duration (microseconds)
    gpioWrite(gpio_pin, 0); // Turn LED off
    return 0;
}

// Cleanup resources
void cleanup() {
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    Config config = {
        .gpio_pin = GPIO_PIN,
        .target_threshold = TARGET_THRESHOLD,
        .uart_device = UART_DEVICE,
        .baud_rate = BAUD_RATE
    };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.gpio_pin, PI_OUTPUT);

    // Initialize UART with retry logic
    int retries = 0;
    while (retries < MAX_RETRIES) {
        uart_fd = initialize_uart(config.uart_device, config.baud_rate);
        if (uart_fd != -1) {
            break;
        }
        retries++;
        fprintf(stderr, "Retrying UART initialization (%d/%d)\n", retries, MAX_RETRIES);
        sleep(1); // Wait before retrying
    }

    if (uart_fd == -1) {
        fprintf(stderr, "Failed to initialize UART after multiple retries.\n");
        cleanup();
        return 1;
    }

    unsigned char buffer[MAGIC_WORD_LENGTH + RANGE_PROFILE_LENGTH];
    int read_attempts = 0;

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read data from UART
        if (read_uart_data(uart_fd, buffer, MAGIC_WORD_LENGTH + RANGE_PROFILE_LENGTH) == 0) {
            // Validate magic word
            if (validate_magic_word(buffer, MAGIC_WORD_LENGTH)) {
                // Decode range profile
                float distance = decode_range_profile(buffer + MAGIC_WORD_LENGTH, RANGE_PROFILE_LENGTH);

                if (distance >= 0.0) {
                    // Detect target
                    if (detect_target(distance)) {
                        printf("Target detected! Distance: %.2f meters\n", distance);

                        // Log intrusion
                        if (log_intrusion(distance) == 0) {
                            printf("Intrusion logged.\n");
                        } else {
                            fprintf(stderr, "Failed to log intrusion.\n");
                        }

                        // Activate alert
                        activate_alert(config.gpio_pin, ALERT_DURATION);
                    }
                } else {
                    fprintf(stderr, "Error decoding range profile.\n");
                }
            } else {
                fprintf(stderr, "Invalid magic word.\n");
            }
        } else {
            fprintf(stderr, "Error reading data from UART. Attempt: %d\n", ++read_attempts);
            if (read_attempts > 5) {
                fprintf(stderr, "Too many consecutive read errors. Exiting.\n");
                program_running = 0;
            }
        }
        gpioDelay(10000); // Delay to avoid busy-waiting (10ms)
    }

    cleanup();
    printf("Intrusion detection system stopped.\n");
    return 0;
}

