    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (setup() != 0) {
        return 1;
    }

    int last_sensor_state = -1; // Initialize to an invalid state

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break;
        }

        // Obstacle detected (active low)
        if (sensor_value == 0) {
            if (last_sensor_state != 0) {
                control_buzzer(1); // Turn on buzzer
                log_event("Obstacle detected");
                last_sensor_state = 0;
            }
        } else {
            if (last_sensor_state != 1) {
                control_buzzer(0); // Turn off buzzer
                log_event("Obstacle removed");
                last_sensor_state = 1;
            }
        }

        gpioDelay(100); // Poll every 100ms
    }

    cleanup();
    return 0;
}

