#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x70
#define LED_GPIO 18
#define MAX_DISTANCE 1000 // Maximum measurable distance in mm
#define MIN_FREQUENCY 1   // Minimum LED blink frequency in Hz
#define MAX_FREQUENCY 10  // Maximum LED blink frequency in Hz
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_distance();
void set_led_frequency(float frequency);
void log_data(int distance, float frequency);
void signal_handler(int signal);
int i2c_read_retry(int handle, char *buf, int count);
int i2c_write_retry(int handle, char *buf, int count);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// I2C read with retry
int i2c_read_retry(int handle, char *buf, int count) {
    int result, retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(handle, buf, count);
        if (result == count) {
            return result;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "I2C read failed after %d retries.\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// I2C write with retry
int i2c_write_retry(int handle, char *buf, int count) {
    int result, retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteDevice(handle, buf, count);
        if (result == count) {
            return result;
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %s\n", retries + 1, strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "I2C write failed after %d retries.\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// Read distance from CH201 sensor
int read_distance() {
    char cmd[1] = {0x00}; // Command to trigger a measurement
    char data[2];          // Buffer to store the received data
    int distance;

    // Trigger measurement
    if (i2c_write_retry(i2c_handle, cmd, 1) != 1) {
        fprintf(stderr, "Failed to trigger measurement.\n");
        return -1;
    }

    gpioDelay(50000); // Wait for measurement (50ms)

    // Read distance data
    if (i2c_read_retry(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read distance data.\n");
        return -1;
    }

    distance = (data[0] << 8) | data[1];

    return distance;
}

// Set LED blink frequency
void set_led_frequency(float frequency) {
    float period = 1.0 / frequency; // Period in seconds
    float on_time = period / 2.0;   // On time is half the period
    int on_us = (int)(on_time * 1000000); // Convert to microseconds

    gpioWrite(LED_GPIO, 1); // Turn LED on
    gpioDelay(on_us);       // Wait for on time
    gpioWrite(LED_GPIO, 0); // Turn LED off
}

// Log data to stdout
void log_data(int distance, float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Distance: %d mm, Frequency: %.2f Hz\n", timestamp, distance, frequency);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            // Calculate LED blink frequency based on distance
            float frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * (1.0 - (float)distance / MAX_DISTANCE);
            if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
            if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;

            set_led_frequency(frequency);
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

