// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger measurement
int trigger_measurement() {
    int result, retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteByteData(i2c_handle, MEASURE_CMD, 0); // Send trigger command
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (trigger): %d, retry %d\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "Failed to trigger measurement after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Read distance data
int read_distance(uint16_t *distance) {
    int result, retries = 0;
    char buffer[2];

    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2); // Read 2 bytes
        if (result == 2) {
            *distance = (buffer[0] << 8) | buffer[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %d, retry %d\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "Failed to read distance after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

