        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    uint16_t raw_distance;
    float distance_cm;
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement.\n");
        } else {
            // Wait for measurement to complete (adjust delay as needed)
            gpioDelay(50000); // 50ms

            // Read distance
            if (read_distance(&raw_distance) != 0) {
                fprintf(stderr, "Failed to read distance.\n");
            } else {
