int read_distance(uint16_t *distance) {
    int result, retries = 0;
    char buffer[2];

    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2); // Read 2 bytes
        if (result == 2) {
            *distance = (buffer[0] << 8) | buffer[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %d, retry %d\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "Failed to read distance after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

