#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
FILE *log_file = NULL;
int running = 1;

// Structure to hold sensor state
typedef struct {
    int gpio;
    int last_state;
    unsigned long last_change_time;
} sensor_t;

sensor_t sensor1 = {SENSOR_1_GPIO, 1, 0}; // Initialize last_state to 1 (no obstacle)
sensor_t sensor2 = {SENSOR_2_GPIO, 1, 0};

// Function prototypes
int read_sensor(int gpio);
int debounce(int gpio, int current_state);
int log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);
int setup();
void cleanup();

// Function to read the sensor value
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to debounce the sensor
int debounce(int gpio, int current_state) {
    unsigned long now = gpioTick();
    if (current_state != gpioRead(gpio)) {
        if (now - sensor1.last_change_time > DEBOUNCE_TIME * 1000) {
            sensor1.last_state = current_state;
            sensor1.last_change_time = now;
        } else if (gpio == SENSOR_2_GPIO) {
            if (now - sensor2.last_change_time > DEBOUNCE_TIME * 1000) {
                sensor2.last_state = current_state;
                sensor2.last_change_time = now;
            }
        }
    }
    if (gpio == SENSOR_1_GPIO) {
        return sensor1.last_state;
    } else {
        return sensor2.last_state;
    }
}

// Function to log the event to a file
int log_event(int sensor_id, const char *event_type) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, Sensor %d, %s\n", buf, sensor_id, event_type) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
