int setup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return -1;
    }

    // Open the log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup() != 0) {
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor 1
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        if (sensor1_value < 0) {
            running = 0; // Exit on error
            continue;
        }
        int debounced_sensor1_value = debounce(SENSOR_1_GPIO, sensor1_value);

        // Read sensor 2
        int sensor2_value = read_sensor(SENSOR_2_GPIO);
        if (sensor2_value < 0) {
            running = 0; // Exit on error
            continue;
        }
        int debounced_sensor2_value = debounce(SENSOR_2_GPIO, sensor2_value);

        // Check for state changes and log events
        if (debounced_sensor1_value != sensor1.last_state) {
            if (debounced_sensor1_value == 0) {
                log_event(1, "DETECTED");
            } else {
                log_event(1, "CLEARED");
            }
        }

        if (debounced_sensor2_value != sensor2.last_state) {
            if (debounced_sensor2_value == 0) {
                log_event(2, "DETECTED");
            } else {
                log_event(2, "CLEARED");
            }
        }

        gpioDelay(10); // Poll every 10ms
    }

    cleanup();
    return 0;
}

