#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define CH101_ADDR 0x50
#define MEAS_STATUS_REG 0x00
#define DISTANCE_REG 0x01
#define MEASUREMENT_DELAY_MS 50
#define SAMPLE_DELAY_MS 500
#define CSV_FILENAME "distance_log.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_setup(int bus, int addr);
int read_register(int fd, unsigned char reg);
int write_register(int fd, unsigned char reg, unsigned char value);
int read_distance(int fd);
void log_distance(FILE *fp, int distance);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// I2C setup function
int i2c_setup(int bus, int addr) {
    int fd = i2cOpen(bus, addr, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Read register function
int read_register(int fd, unsigned char reg) {
    int result = i2cReadByteData(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// Write register function
int write_register(int fd, unsigned char reg, unsigned char value) {
    int result = i2cWriteByteData(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Read distance function
int read_distance(int fd) {
    int status;
    int distance;

    // Poll MEAS_STATUS register
    do {
        status = read_register(fd, MEAS_STATUS_REG);
        if (status < 0) {
            fprintf(stderr, "Error reading MEAS_STATUS register.\n");
            return -1;
        }
        gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay in microseconds
    } while ((status & 0x01) == 0 && !terminate); // Wait for measurement ready

    if (terminate) return -1; // Exit if signal received during polling

    // Read distance data
    distance = read_register(fd, DISTANCE_REG);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance register.\n");
        return -1;
    }

    return distance;
}

// Log distance function
void log_distance(FILE *fp, int distance) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp.\n");
        return;
    }

    fprintf(fp, "%s,%d\n", timestamp, distance);
    fflush(fp); // Ensure data is written to file immediately
    free(timestamp);
}

// Get ISO 8601 timestamp function
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string
    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(buffer, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Setup I2C
    i2c_fd = i2c_setup(I2C_BUS, CH101_ADDR);
    if (i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_fd);
        if (distance >= 0) {
            log_distance(csv_file, distance);
        } else {
            fprintf(stderr, "Failed to read distance. Skipping sample.\n");
        }

        gpioDelay(SAMPLE_DELAY_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_fd);
    fclose(csv_file);
    gpioTerminate();

    return 0;
}

