#define VL53L4CX_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L4CX_REG_INTERRUPT_CLEAR 0x0086
#define VL53L4CX_REG_INTERRUPT_STATUS 0x0084
#define VL53L4CX_REG_START_STOP_MEASURE 0x0000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to write a byte to a VL53L4CX register
int vl53l4cx_write_byte(int handle, uint8_t reg, uint8_t data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to register 0x%02x: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L4CX register
int vl53l4cx_read_byte(int handle, uint8_t reg, uint8_t *data) {
    int result = i2cWriteDevice(handle, &reg, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }
    result = i2cReadDevice(handle, data, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading from register 0x%02x: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VL53L4CX register
int vl53l4cx_read_word(int handle, uint8_t reg, uint16_t *data) {
    char buf[1];
    buf[0] = reg;
    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing register address for word read: %s\n", strerror(errno));
        return -1;
    }
    char read_buf[2];
    result = i2cReadDevice(handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading word from register 0x%02x: %s\n", reg, strerror(errno));
        return -1;
    }
    *data = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

