#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100 // mm
#define CONTINUOUS_RANGING_MODE 0x00 // Example mode, adjust as needed

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_buzzer(int state);
void signal_handler(int signal);
void log_error(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to log errors with timestamp
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (replace with actual VL53L1X init)
    // This is a placeholder, refer to the VL53L1X datasheet for the correct initialization sequence
    char init_data[] = {0x00, 0x01, 0x02, 0x03}; // Example data
    int result = i2cWriteDevice(i2c_handle, init_data, sizeof(init_data));
    if (result != 0) {
        log_error("Failed to initialize VL53L1X sensor.");
        return -1;
    }
    return 0;
}

// Function to read distance from the VL53L1X sensor
int read_distance() {
    char cmd = 0x00; // Command to trigger a single measurement (adjust as needed)
    char buffer[2]; // Buffer to store the distance data (adjust size as needed)
    int result;

    // Trigger a measurement
    result = i2cWriteDevice(i2c_handle, &cmd, 1);
    if (result != 0) {
        log_error("Failed to trigger measurement.");
        return -1;
    }

    // Wait for measurement to complete (adjust delay as needed)
    gpioDelay(10000); // 10ms

    // Read the distance data
    result = i2cReadDevice(i2c_handle, buffer, sizeof(buffer));
    if (result != sizeof(buffer)) {
        log_error("Failed to read distance data.");
        return -1;
    }

    // Convert the data to distance (adjust conversion as needed)
    int distance = (buffer[0] << 8) | buffer[1]; // Example conversion

    return distance;
}

// Function to control the buzzer
void control_buzzer(int state) {
    gpioWrite(BUZZER_GPIO, state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus.");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
            if (distance < DISTANCE_THRESHOLD) {
                control_buzzer(1); // Activate buzzer
            } else {
                control_buzzer(0); // Deactivate buzzer
            }
        } else {
            log_error("Failed to read distance, skipping iteration.");
        }

        gpioDelay(500000); // 500ms delay
    }

    // Clean up resources before exiting
    i2cClose(i2c_handle);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioTerminate();

    return 0;
}

