#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100 // mm
#define MESSAGE_QUEUE_KEY 1234
#define MAX_RETRIES 3

// Message queue message structure
typedef struct {
    long mtype;       // Message type (must be > 0)
    int distance;     // Distance in mm
} message_t;

// Global variables
int i2c_handle;
int msg_queue_id;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void activate_buzzer();
void deactivate_buzzer();
void signal_handler(int signal);
int send_message(int distance);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (replace with actual VL53L1X init)
    // This is a placeholder; refer to the VL53L1X datasheet for the correct initialization sequence.
    char init_data[] = {0x00, 0x01, 0x02, 0x03}; // Example data
    int result = i2cWriteDevice(i2c_handle, init_data, sizeof(init_data));
    if (result != 0) {
        fprintf(stderr, "Error initializing VL53L1X: %d\n", result);
        return -1;
    }
    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    char cmd = 0x00; // Command to trigger a single measurement
    char buffer[2];  // Buffer to store the distance data (2 bytes)
    int result;

    // Trigger measurement
    result = i2cWriteDevice(i2c_handle, &cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (adjust as needed)
    gpioDelay(50000); // 50ms

    // Read distance data
    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1;
    }

    // Combine the two bytes to form the distance
    int distance = (buffer[0] << 8) | buffer[1];

    return distance;
}

// Activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Set GPIO high
}

// Deactivate the buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_GPIO, 0); // Set GPIO low
}

// Send distance message to the message queue
int send_message(int distance) {
    message_t message;
    message.mtype = 1; // Message type (must be > 0)
    message.distance = distance;

    if (msgsnd(msg_queue_id, &message, sizeof(message.distance), 0) == -1) {
        perror("msgsnd failed");
        return -1;
    }
    return 0;
}

