    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create message queue
    msg_queue_id = msgget(MESSAGE_QUEUE_KEY, 0666 | IPC_CREAT);
    if (msg_queue_id == -1) {
        perror("msgget failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Distance monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance > 0) {
            printf("Distance: %d mm\n", distance);

            // Send distance to message queue
            if (send_message(distance) != 0) {
                fprintf(stderr, "Error sending message\n");
            }

            // Activate buzzer if distance is below threshold
            if (distance < DISTANCE_THRESHOLD) {
                activate_buzzer();
            } else {
                deactivate_buzzer();
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(50000); // 50ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    msgctl(msg_queue_id, IPC_RMID, NULL);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioTerminate();

    return 0;
}

