#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define BUZZER_THRESHOLD 30.0  // cm

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int timeout_flag = 0;
static volatile double distance = -1.0; // Initialize to an invalid value

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user);
double calculate_distance(uint32_t start, uint32_t end);
void output_distance(double distance);
void control_buzzer(double distance);
void signal_handler(int signal);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();           // Terminate pigpio
    exit(0);
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) {
        // Rising edge
        start_tick = tick;
        echo_received = 1;
        timeout_flag = 0; // Reset timeout flag
    } else if (level == 0) {
        // Falling edge
        if (echo_received) {
            end_tick = tick;
            echo_received = 0;
        }
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t start, uint32_t end) {
    uint32_t diff = end - start;
    if (start > end) {
        diff = (0xFFFFFFFF - start) + end; // Handle tick wraparound
    }
    double time_taken = (double)diff / 1000000.0; // Time in seconds
    double distance_cm = (time_taken * SPEED_OF_SOUND) / 2.0;
    return distance_cm;
}

// Function to output distance to the console
void output_distance(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        printf("Invalid reading: Distance = %.2f cm\n", distance);
    } else {
        printf("Distance: %.2f cm\n", distance);
    }
}

// Function to control the buzzer based on distance
void control_buzzer(double distance) {
    if (distance < BUZZER_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register interrupt handler for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        trigger_pulse();
        gpioDelay(50); // Delay between measurements

        // Check for timeout
        if (echo_received == 0) {
            timeout_flag = 1;
            echo_received = 0; // Reset flag for next measurement
        }

        if (echo_received) {
            distance = calculate_distance(start_tick, end_tick);
            output_distance(distance);
            control_buzzer(distance);
        } else if (timeout_flag) {
            printf("Timeout: No echo received\n");
            distance = -1.0; // Set to invalid value
            control_buzzer(distance); // Turn off buzzer in case of timeout
            timeout_flag = 0; // Reset timeout flag
        } else {
            printf("No echo received yet\n");
        }

        gpioDelay(100); // Delay between measurements
    }

    return 0;
}

