#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TRIGGER_PULSE_DURATION 10 // us
#define SAMPLING_RATE 5 // Hz
#define SAMPLING_PERIOD (1000000 / SAMPLING_RATE) // us
#define MIN_PULSE_WIDTH 100 // us
#define MAX_PULSE_WIDTH 30000 // us
#define TIMEOUT_THRESHOLD 60000 // us (60 ms)

// Global variables
static volatile uint32_t rising_tick = 0;
static volatile uint32_t falling_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Structure to hold the last two ticks for wraparound handling
typedef struct {
    uint32_t last_tick;
    uint32_t second_last_tick;
} TickHistory;

TickHistory tick_history = {0, 0};

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        // Rising edge
        rising_tick = tick;
        echo_received = 1;
        tick_history.second_last_tick = tick_history.last_tick;
        tick_history.last_tick = tick;
    } else if (level == 0) {
        // Falling edge
        falling_tick = tick;
        echo_received = 1;
