// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_configure(int i2c_handle, int timing_budget_ms);
int vl53l1x_start_ranging(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void control_gate(int open);
void log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// VL53L1X Initialization function
int vl53l1x_init(int i2c_handle) {
    // Soft reset (Example - adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x01) < 0) {
        fprintf(stderr, "Error: VL53L1X soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Check sensor ID (Example - adjust based on datasheet)
    int sensor_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error: VL53L1X sensor ID read failed\n");
        return -1;
    }
    if (sensor_id != 0xEACC) {
        fprintf(stderr, "Error: VL53L1X sensor ID mismatch (0x%X)\n", sensor_id);
        return -1;
    }

    printf("VL53L1X sensor initialized successfully\n");
    return 0;
}

// VL53L1X Configuration function
int vl53l1x_configure(int i2c_handle, int timing_budget_ms) {
    // Configure timing budget (Example - adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, 0x0088, timing_budget_ms) < 0) {
        fprintf(stderr, "Error: VL53L1X timing budget configuration failed\n");
        return -1;
    }

    printf("VL53L1X sensor configured with timing budget: %d ms\n", timing_budget_ms);
    return 0;
}

// VL53L1X Start Ranging function
int vl53l1x_start_ranging(int i2c_handle) {
    // Start ranging (Example - adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, 0x0001, 0x01) < 0) {
        fprintf(stderr, "Error: VL53L1X start ranging failed\n");
        return -1;
    }

    printf("VL53L1X sensor started ranging\n");
    return 0;
}

// VL53L1X Read Distance function
int vl53l1x_read_distance(int i2c_handle) {
    // Read distance (Example - adjust based on datasheet)
    int distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        fprintf(stderr, "Error: VL53L1X distance read failed\n");
        return -1;
    }

    return distance;
}

// Control Gate function
void control_gate(int open) {
    if (open) {
        gpioWrite(GPIO_OPEN, 1);
        gpioWrite(GPIO_CLOSE, 0);
        log_event("Gate opened");
    } else {
        gpioWrite(GPIO_OPEN, 0);
        gpioWrite(GPIO_CLOSE, 1);
        log_event("Gate closed");
    }
}

