    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gate_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_OPEN, PI_OUTPUT);
    gpioSetMode(GPIO_CLOSE, PI_OUTPUT);

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed\n");
        cleanup();
        return 1;
    }

    // Configure VL53L1X sensor
    if (vl53l1x_configure(i2c_handle, 50) < 0) { // Example: 50ms timing budget
        fprintf(stderr, "Error: VL53L1X configuration failed\n");
        cleanup();
        return 1;
    }

    // Start VL53L1X ranging
    if (vl53l1x_start_ranging(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X start ranging failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int gate_open = 0;
    while (!terminate) {
        // Read distance from VL53L1X sensor
        int distance = vl53l1x_read_distance(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Error: Failed to read distance, retrying...\n");
            gpioDelay(100000); // 100ms delay before retry
            continue;
        }

        // Control gate based on distance
        if (distance <= DISTANCE_THRESHOLD && !gate_open) {
            control_gate(1);
            gate_open = 1;
        } else if (distance > DISTANCE_THRESHOLD && gate_open) {
            control_gate(0);
            gate_open = 0;
        }

        // Wait before next polling
        gpioDelay(POLLING_INTERVAL * 1000); // Convert ms to us
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

