int vl53l1x_init() {
    // Soft reset
    char data[2] = {VL53L1X_REG_SOFT_RESET, 0x00};
    int result = i2cWriteDevice(i2c_handle, data, 2);
    if (result != 0) {
        fprintf(stderr, "Error: VL53L1X soft reset failed (error code %d)\n", result);
        return -1;
    }
    gpioDelay(1000); // 1 ms delay

    // Start measurement
    data[0] = VL53L1X_REG_SYSRANGE_START;
    data[1] = 0x01;
    result = i2cWriteDevice(i2c_handle, data, 2);
    if (result != 0) {
        fprintf(stderr, "Error: VL53L1X start measurement failed (error code %d)\n", result);
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int vl53l1x_read_distance() {
    int retries = 3;
    int delay_ms = 10;
    int result;

    while (retries > 0) {
        // Check if data is ready
        char data[2] = {VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY, 0x00};
        result = i2cWriteDevice(i2c_handle, data, 1);
        if (result != 0) {
            fprintf(stderr, "Error: VL53L1X data ready write failed (error code %d)\n", result);
            gpioDelay(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            retries--;
            continue;
        }

        char ready_data[1];
        result = i2cReadDevice(i2c_handle, ready_data, 1);
        if (result != 0) {
            fprintf(stderr, "Error: VL53L1X data ready read failed (error code %d)\n", result);
            gpioDelay(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            retries--;
            continue;
        }

        if (ready_data[0] & 0x01) {
            // Read distance data
            data[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
            result = i2cWriteDevice(i2c_handle, data, 1);
            if (result != 0) {
                fprintf(stderr, "Error: VL53L1X distance read address write failed (error code %d)\n", result);
                gpioDelay(delay_ms * 1000); // Exponential backoff
                delay_ms *= 2;
                retries--;
                continue;
            }

            char distance_data[2];
            result = i2cReadDevice(i2c_handle, distance_data, 2);
            if (result != 0) {
                fprintf(stderr, "Error: VL53L1X distance read failed (error code %d)\n", result);
                gpioDelay(delay_ms * 1000); // Exponential backoff
                delay_ms *= 2;
                retries--;
                continue;
            }

            distance = (distance_data[0] << 8) | distance_data[1];
            return 0; // Success
        } else {
            gpioDelay(1000); // Wait a bit before checking again
        }
    }

    fprintf(stderr, "Error: VL53L1X read distance failed after multiple retries\n");
    return -1; // Failure
}

