        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (error code %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes for motor control
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);

    // Set GPIO mode for interrupt
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_DOWN); // Optional: Pull-down resistor

    // Set interrupt handler
    if (gpioSetISRFuncEx(INTERRUPT_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set interrupt handler\n");
        motor_stop();
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Program running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        gpioDelay(100000); // Sleep for 0.1 seconds
    }

    return 0;
}

