#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define MPR121_RESET_REG 0x80
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

#define LED_GPIO_0 17
#define LED_GPIO_1 18
#define LED_GPIO_2 27
#define LED_GPIO_3 22

#define NUM_ELECTRODES 12

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status(uint16_t *touch_status);
void set_led_pattern(int electrode);
void log_event(int electrode);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");

    // Close I2C connection
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Release GPIO pins
    gpioSetMode(LED_GPIO_0, PI_INPUT); // Set to input to release
    gpioSetMode(LED_GPIO_1, PI_INPUT);
    gpioSetMode(LED_GPIO_2, PI_INPUT);
    gpioSetMode(LED_GPIO_3, PI_INPUT);

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

// MPR121 initialization function
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_RESET_REG, 0x63) < 0) {
        fprintf(stderr, "Error: I2C write failed during reset.\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure Electrode Configuration Register (ECR) to enable all 12 electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x0C) < 0) {
        fprintf(stderr, "Error: I2C write failed for ECR.\n");
        return -1;
    }

    // Configure MPR121 (example configuration)
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG1, 0x20) < 0) { // Set Electrode Filter Control
        fprintf(stderr, "Error: I2C write failed for CONFIG1.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG2, 0x01) < 0) { // Set Debounce Control
        fprintf(stderr, "Error: I2C write failed for CONFIG2.\n");
        return -1;
    }

    return 0;
}

// MPR121 read touch status function
int mpr121_read_touch_status(uint16_t *touch_status) {
    char buf[2];

    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: I2C read failed for touch status.\n");
        return -1;
    }

    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Set LED pattern function
void set_led_pattern(int electrode) {
    int bit0 = (electrode >> 0) & 1;
    int bit1 = (electrode >> 1) & 1;
    int bit2 = (electrode >> 2) & 1;
    int bit3 = (electrode >> 3) & 1;

    gpioWrite(LED_GPIO_0, bit0);
    gpioWrite(LED_GPIO_1, bit1);
    gpioWrite(LED_GPIO_2, bit2);
    gpioWrite(LED_GPIO_3, bit3);
}

// Log event function
void log_event(int electrode) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Electrode %d touched\n", timestamp, electrode);
    fflush(log_file); // Ensure immediate write to file
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes for LEDs
    gpioSetMode(LED_GPIO_0, PI_OUTPUT);
    gpioSetMode(LED_GPIO_1, PI_OUTPUT);
    gpioSetMode(LED_GPIO_2, PI_OUTPUT);
    gpioSetMode(LED_GPIO_3, PI_OUTPUT);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity art installation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        uint16_t touch_status;

        if (mpr121_read_touch_status(&touch_status) == 0) {
            for (int i = 0; i < NUM_ELECTRODES; i++) {
                if (touch_status & (1 << i)) {
                    set_led_pattern(i);
                    log_event(i);
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status. Retrying...\n");
        }

        gpioDelay(50); // 50ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

