int mpr121_configure(int handle) {
    // Stop mode
    if (mpr121_write_register(handle, MPR121_ELECTRODE_CONFIG, 0x00) < 0) return -1;

    // Configure baseline filtering
    if (mpr121_write_register(handle, MPR121_BASELINE_FILTERING, 0x10) < 0) return -1; // Example value

