#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define TIMEOUT_US 30000       // 30 ms timeout

// Global variables
volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_pulse();
long long measure_pulse_width();
double calculate_distance(long long pulse_width);
int is_valid_distance(double distance);
char* get_iso8601_timestamp();
int log_distance(char *timestamp, double distance);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);

    return 0;
}

// Generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the echo pulse width
long long measure_pulse_width() {
    long long start_time = 0, end_time = 0;
    int timeout = 0;

    // Wait for rising edge
    while (gpioRead(ECHO_PIN) == 0) {
        start_time = gpioTick();
        if (start_time - gpioTick() > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return -1; // Timeout
        }
    }

    // Wait for falling edge
    while (gpioRead(ECHO_PIN) == 1) {
        end_time = gpioTick();
        if (end_time - start_time > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return -1; // Timeout
        }
    }

    return end_time - start_time;
}

// Calculate distance from pulse width
double calculate_distance(long long pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance, convert us to s
}

// Validate distance
int is_valid_distance(double distance) {
    return (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE);
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Log distance to file
int log_distance(char *timestamp, double distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Flush the buffer to ensure data is written to the file

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        trigger_pulse();
        long long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            double distance = calculate_distance(pulse_width);

            if (is_valid_distance(distance)) {
                char *timestamp = get_iso8601_timestamp();
                if (log_distance(timestamp, distance) != 0) {
                    fprintf(stderr, "Error logging distance\n");
                }
                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "Invalid distance: %.2f cm\n", distance);
            }
        } else {
            fprintf(stderr, "Error measuring pulse width\n");
        }

        sleep(1); // Measure every 1 second
    }

    cleanup();
    return 0;
}

