#define SPEED_OF_SOUND 343.0 // m/s
#define MIN_DISTANCE 0.01   // 1 cm
#define MAX_DISTANCE 4.0    // 4 m
#define MIN_PULSE_WIDTH 58   // 58 us
#define MAX_PULSE_WIDTH 25000 // 25 ms
#define TRIGGER_PULSE_DURATION 10 // us

// Global variables
static volatile int pulse_start = 0;
static volatile int pulse_end = 0;
static volatile int pulse_width = 0;
static volatile int echo_active = 0;
static FILE *log_file = NULL;
static int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

