// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// GPIO pin for XSHUT
#define XSHUT_PIN 27

// I2C bus
#define I2C_BUS 1

// VL53L1X register addresses (Example - adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0049
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    terminate = 1;
}

// VL53L1X initialization function
int vl53l1x_init() {
    // Example initialization sequence (adjust as needed)
    // This is a placeholder, refer to the VL53L1X datasheet for the correct initialization sequence
    char init_data[] = {0x00, 0x01}; // Example data
    int status;

    // Check sensor ID (example)
    char model_id;
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1);
    if (status < 0) {
        syslog(LOG_ERR, "Failed to read model ID: %d", status);
        return -1;
    }
    if (model_id != 0xEACC) {
        syslog(LOG_ERR, "Incorrect model ID: 0x%02X", model_id);
        return -1;
    }

    // Write initialization data (example)
    status = i2cWriteI2CBlockData(i2c_handle, 0x02D8, init_data, sizeof(init_data));
    if (status < 0) {
        syslog(LOG_ERR, "Failed to write initialization data: %d", status);
        return -1;
    }

    // Start continuous ranging (example)
    char start_ranging[] = {0x00, 0x01};
    status = i2cWriteI2CBlockData(i2c_handle, 0x0010, start_ranging, sizeof(start_ranging));
    if (status < 0) {
        syslog(LOG_ERR, "Failed to start ranging: %d", status);
        return -1;
    }

    syslog(LOG_INFO, "VL53L1X initialized successfully.");
    return 0;
}

// VL53L1X read distance function
int vl53l1x_read_distance(int *distance) {
    char data[2];
    int status;

    // Check if data is ready
    char data_ready;
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY, &data_ready, 1);
    if (status < 0) {
        syslog(LOG_ERR, "Failed to read data ready status: %d", status);
        return -1;
    }

    if (data_ready & 0x01) {
        // Read distance data
        status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2);
        if (status < 0) {
            syslog(LOG_ERR, "Failed to read distance data: %d", status);
            return -1;
        }

        *distance = (data[0] << 8) | data[1];
        return 0;
    } else {
        syslog(LOG_WARNING, "Data not ready yet.");
        return -1; // Data not ready
    }
}

int main() {
    // Initialize syslog
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set XSHUT pin as output
    gpioSetMode(XSHUT_PIN, PI_OUTPUT);

    // Set XSHUT pin high to enable the sensor
    gpioWrite(XSHUT_PIN, 1);

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    int distance;
    while (!terminate) {
        if (vl53l1x_read_distance(&distance) == 0) {
            syslog(LOG_INFO, "Distance: %d mm", distance);
        } else {
            syslog(LOG_ERR, "Failed to read distance");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return 0;
}

