#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_GATE 24
#define DISTANCE_THRESHOLD 20 // cm
#define POLLING_INTERVAL 100 // ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_gate(int distance_cm);
void log_message(const char *message);
void signal_handler(int signal);

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0049
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Helper function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int reg, int data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        return -1; // Error writing to I2C
    }
    return 0;
}

// Helper function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int reg, int *data) {
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 1) {
        return -1; // Error writing register address
    }
    if (i2cReadDevice(i2c_handle, (char *)data, 1) != 1) {
        return -1; // Error reading from I2C
    }
    return 0;
}

// Helper function to read two bytes from a VL53L1X register
int vl53l1x_read_word(int reg, int *data) {
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 1) {
        return -1; // Error writing register address
    }
    if (i2cReadDevice(i2c_handle, (char *)data, 2) != 2) {
        return -1; // Error reading from I2C
    }
    return 0;
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    int model_id;

    // Check sensor ID (example)
    if (vl53l1x_read_byte(VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        log_message("Error reading sensor ID");
        return -1;
    }
    if (model_id != 0xEA) {
        log_message("Incorrect sensor ID");
        return -1;
    }

    // Add initialization sequence here (refer to VL53L1X datasheet)
    // This is a placeholder - replace with actual initialization
    if (vl53l1x_write_byte(0x02D8, 0x01) != 0) return -1; // Example register write
    if (vl53l1x_write_byte(0x02D9, 0x02) != 0) return -1; // Example register write

    log_message("VL53L1X sensor initialized");
    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance() {
    int distance_mm;

    // Start a measurement (example - adjust based on datasheet)
    if (vl53l1x_write_byte(0x0000, 0x01) != 0) {
        log_message("Error starting measurement");
        return -1;
    }

    // Wait for measurement to be ready (example - adjust based on datasheet)
    int ready = 0;
    int timeout = 100; // Timeout after 100ms
    while (!ready && timeout > 0) {
        int data;
        if (vl53l1x_read_byte(VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY, &data) == 0) {
            ready = (data & 0x01);
        } else {
            log_message("Error reading measurement ready status");
            return -1;
        }
        gpioDelay(1); // Wait 1ms
        timeout--;
    }

    if (!ready) {
        log_message("Timeout waiting for measurement");
        return -1;
    }

    // Read the distance (example - adjust based on datasheet)
    if (vl53l1x_read_word(VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance_mm) != 0) {
        log_message("Error reading distance");
        return -1;
    }

    return distance_mm;
}

// Control the gate based on the distance
void control_gate(int distance_cm) {
    static int gate_open = 0; // Track gate state

    if (distance_cm < DISTANCE_THRESHOLD && !gate_open) {
        gpioWrite(GPIO_GATE, 1); // Open the gate
        gate_open = 1;
        log_message("Gate opened");
    } else if (distance_cm >= DISTANCE_THRESHOLD && gate_open) {
        gpioWrite(GPIO_GATE, 0); // Close the gate
        gate_open = 0;
        log_message("Gate closed");
    }
}

// Log a message to the log file with a timestamp
void log_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file); // Ensure the message is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message("Received signal, shutting down...");
    terminate = 1;
}

