#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30 ms timeout
#define MOVING_AVG_SIZE 5

// Global variables
volatile uint32_t pulse_width = 0;
volatile int new_pulse = 0;
volatile sig_atomic_t terminate = 0;

// Moving average filter buffer
float distance_history[MOVING_AVG_SIZE];
int history_index = 0;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
float calculate_distance(uint32_t pulse_width);
int set_servo_angle(float distance);
int log_data(float distance, int angle);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t start_tick = 0;
    static uint32_t end_tick = 0;
    static int echo_state = 0; // 0: low, 1: high

    if (level == 1) {
        // Rising edge
        start_tick = tick;
        echo_state = 1;
    } else if (level == 0) {
        // Falling edge
        if (echo_state == 1) {
            end_tick = tick;
            uint32_t diff = end_tick - start_tick;

            // Handle tick counter wrap-around
            if (end_tick < start_tick) {
                diff = (0xFFFFFFFF - start_tick) + end_tick;
            }

            pulse_width = diff;
            new_pulse = 1;
            echo_state = 0;
        }
    }
}

// Function to calculate distance in centimeters
float calculate_distance(uint32_t pulse_width) {
    if (pulse_width > TIMEOUT_US) {
        return -1.0; // Timeout
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to set the servo angle based on distance
int set_servo_angle(float distance) {
    int angle = 0;

    if (distance < 200.0) {
        angle = 0;
    } else if (distance > 200.0 && distance < 400.0) {
        angle = (int)((distance - 200.0) * 180.0 / 200.0);
    } else {
        angle = 180;
    }

    if (gpioServo(SERVO_PIN, angle * 1000 / 180 + 500) != 0) {
        fprintf(stderr, "Failed to set servo angle\n");
        return -1;
    }
    return angle;
}

// Function to log data to a CSV file
int log_data(float distance, int angle) {
    FILE *fp = fopen("distance_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, distance, angle);
    fflush(fp);
    fclose(fp);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function to stop servo and terminate pigpio
void cleanup() {
    gpioServo(SERVO_PIN, 0); // Stop servo
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize distance history
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        distance_history[i] = 0.0;
    }

    // Set up interrupt callback
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (!terminate) {
        trigger_sensor();
        gpioDelay(100); // 100 ms delay

        if (new_pulse) {
            new_pulse = 0;
            float distance = calculate_distance(pulse_width);

            // Moving average filter
            distance_history[history_index] = distance;
            history_index = (history_index + 1) % MOVING_AVG_SIZE;

            float sum = 0.0;
            for (int i = 0; i < MOVING_AVG_SIZE; i++) {
                sum += distance_history[i];
            }
            float filtered_distance = sum / MOVING_AVG_SIZE;

            int angle = set_servo_angle(filtered_distance);

            if (filtered_distance < 2.0 || filtered_distance > 400.0 || filtered_distance == -1.0) {
                log_data(-1.0, 90);
                set_servo_angle(90.0);
            } else {
                log_data(filtered_distance, angle);
            }
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

