#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define GPIO_INTERRUPT 27 // BCM numbering
#define LOG_FILE "proximity.log"

// Global variables (minimize usage)
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile int running = 1;
static int proximity_threshold = DEFAULT_THRESHOLD;
static int i2c_address = DEFAULT_I2C_ADDRESS;

// Function prototypes
int initialize_i2c(int address);
int configure_sensor(int i2c_handle);
int read_proximity_value(int i2c_handle);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void log_data(int proximity_value);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C interface
int initialize_i2c(int address) {
    int handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to configure the Si1102 sensor
int configure_sensor(int i2c_handle) {
    // Example configuration (replace with actual Si1102 configuration)
    // This is a placeholder; refer to the Si1102 datasheet for proper configuration
    char config_data[] = {0x01, 0x00}; // Example register and value
    int result = i2cWriteDevice(i2c_handle, config_data, sizeof(config_data));
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the proximity value from the sensor
int read_proximity_value(int i2c_handle) {
    char reg = 0x02; // Example register to read proximity value
    char buffer[2];
    int result = i2cWriteDevice(i2c_handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading proximity value: %d\n", result);
        return -1;
    }
    return (buffer[0] << 8) | buffer[1]; // Combine the two bytes into a 16-bit value
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge
        int proximity_value = read_proximity_value(i2c_handle);
        if (proximity_value >= 0) {
            log_data(proximity_value);
        } else {
            fprintf(stderr, "Error reading proximity value in interrupt handler\n");
        }
    }
}

// Function to log the data to a file
void log_data(int proximity_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %s\n", timestamp, proximity_value, (proximity_value <= proximity_threshold) ? "SAFE" : "ALERT");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        running = 0;
    }
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:a:")) != -1) {
        switch (opt) {
            case 't':
                proximity_threshold = atoi(optarg);
                break;
            case 'a':
                if (sscanf(optarg, "%x", &i2c_address) != 1) {
                    if (sscanf(optarg, "%d", &i2c_address) != 1) {
                        fprintf(stderr, "Invalid I2C address format\n");
                        return 1;
                    }
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-a i2c_address]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = initialize_i2c(i2c_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor(i2c_handle) != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up interrupt handler
    gpioSetMode(GPIO_INTERRUPT, PI_INPUT);
    gpioSetISRFuncEx(GPIO_INTERRUPT, RISING_EDGE, 0, interrupt_handler, NULL);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1); // Sleep for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

