#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 200.0     // cm
#define MIN_FREQUENCY 200.0    // Hz
#define MAX_FREQUENCY 2000.0   // Hz
#define TIMEOUT_US 200000       // 200 ms

// Global variables
static volatile int running = 1;
static double current_frequency = 440.0; // Initial frequency

// Function prototypes
void signal_handler(int signal);
double measure_distance();
double map_distance_to_frequency(double distance);
void set_pwm_frequency(double frequency);
void trigger_sensor();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Measures the distance using the HC-SR04 sensor
double measure_distance() {
    long long start_tick, end_tick, diff_tick;

    trigger_sensor(); // Trigger the sensor

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Delay 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal timeout\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Delay 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal timeout (low)\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    double distance = (double)diff_tick * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2

    return distance;
}

// Maps the distance to a frequency on a logarithmic scale
double map_distance_to_frequency(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: Distance out of range (%f cm). Using previous frequency.\n", distance);
        return current_frequency; // Return previous frequency
    }

    // Logarithmic mapping
    double log_distance = log10(distance - MIN_DISTANCE + 1); // Shift to start at 1
    double log_range = log10(MAX_DISTANCE - MIN_DISTANCE + 1);
    double frequency = MIN_FREQUENCY * pow(MAX_FREQUENCY / MIN_FREQUENCY, log_distance / log_range);

    return frequency;
}

// Sets the PWM frequency on GPIO18
void set_pwm_frequency(double frequency) {
    if (frequency > 0) {
        gpioSetPWMfrequency(PWM_PIN, (int)frequency);
        current_frequency = frequency; // Update current frequency
    } else {
        fprintf(stderr, "Error: Invalid frequency (%f Hz)\n", frequency);
    }
}

// Triggers the HC-SR04 sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM range (affects duty cycle)
    gpioSetPWMrange(PWM_PIN, 1000); // Adjust as needed

    // Set PWM duty cycle to 50%
    gpioPWM(PWM_PIN, 500); // 50% of 1000

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        double distance = measure_distance();

        if (distance > 0) {
            double frequency = map_distance_to_frequency(distance);
            set_pwm_frequency(frequency);
        } else {
            // Keep the previous frequency if there's an error
            set_pwm_frequency(current_frequency);
        }

        gpioDelay(50); // Delay 50 ms
    }

    // Cleanup (should not reach here if signal handler works)
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();       // Terminate pigpio

    return 0;
}

