#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000        // 50 ms timeout in microseconds
#define MIN_DISTANCE 2.0       // Minimum valid distance in cm
#define MAX_DISTANCE 400.0     // Maximum valid distance in cm
#define TOO_CLOSE_DISTANCE 10.0 // Distance below which object is too close

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to measure distance using HC-SR04 sensor
float measure_distance() {
    long long start_tick, end_tick, diff;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure echo pulse duration
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            return -1.0; // Timeout
        }
    }
    start_tick = gpioTick();

    end_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - end_tick > TIMEOUT_US) {
            return -1.0; // Timeout
        }
    }
    end_tick = gpioTick();

    diff = end_tick - start_tick;

    // Calculate distance in centimeters
    return (float)diff * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float distance = measure_distance();

        if (distance < 0) {
            fprintf(stderr, "Timeout occurred\n");
        } else if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Invalid reading\n");
        } else {
            printf("Distance: %.2f cm", distance);
            if (distance < TOO_CLOSE_DISTANCE) {
                printf(" - Too close!\n");
            } else {
                printf("\n");
            }
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

