#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (CE0)
#define DISTANCE_MIN 200
#define DISTANCE_MAX 5000
#define LOG_FILE "distance_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t distance;
    uint16_t status;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize the sensor
int initialize_sensor() {
    // Add initialization sequence here (if needed for ICU-20201)
    // This is a placeholder, replace with actual initialization commands
    printf("Initializing sensor...\n");
    return 0; // Return 0 for success, -1 for failure
}

// Read data from the sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char tx_buffer[2] = {0x00, 0x00}; // Example transmit buffer
    char rx_buffer[2] = {0x00, 0x00}; // Example receive buffer

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);

    if (result != 2) {
        fprintf(stderr, "SPI read error: %d\n", result);
        data.distance = 0; // Indicate error
        data.status = 1;    // Indicate error
        return data;
    }

    // Example: Assuming the first byte is distance and the second is status
    data.distance = rx_buffer[0];
    data.status = rx_buffer[1];

    return data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (data.distance < DISTANCE_MIN || data.distance > DISTANCE_MAX) {
        fprintf(stderr, "Error: Distance out of range: %d mm\n", data.distance);
        fprintf(log_file, "%s,ERROR,Distance out of range\n", timestamp);
        fflush(log_file);
        return -1;
    }

    fprintf(log_file, "%s,%d,%d\n", timestamp, data.distance, data.status);
    fflush(log_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deactivate chip select initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (mm),Status\n");
    }
    fflush(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();

        if (data.status == 0) {
            log_data(data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

