#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define SI1182_ADDR 0x60
#define PART_ID_REG 0x00
#define MEAS_RATE_REG 0x08
#define LUX_DATA_REG 0x22
#define PROX_DATA_REG 0x24
#define LOG_FILE "biometric_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float lux;
    int proximity;
} sensor_data_t;

// Function prototypes
int i2c_write_byte(int fd, unsigned char reg, unsigned char value);
int i2c_read_byte(int fd, unsigned char reg, unsigned char *value);
int i2c_read_word(int fd, unsigned char reg, unsigned short *value);
int verify_sensor(int fd);
int configure_sensor(int fd);
sensor_data_t read_sensor_data(int fd);
char* format_log_entry(float lux, int proximity);
int log_data(const char *log_entry);
void signal_handler(int signal);

// I2C write function
int i2c_write_byte(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_byte(int fd, unsigned char reg, unsigned char *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// I2C read word function
int i2c_read_word(int fd, unsigned char reg, unsigned short *value) {
    unsigned char buf[1];
    unsigned char data[2];

    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }

    *value = (data[1] << 8) | data[0]; // Big-endian
    return 0;
}

// Verify sensor function
int verify_sensor(int fd) {
    unsigned char part_id;
    if (i2c_read_byte(fd, PART_ID_REG, &part_id) != 0) {
        fprintf(stderr, "Failed to read part ID.\n");
        return -1;
    }

    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect part ID: 0x%02X\n", part_id);
        return -1;
    }

    printf("Sensor verified. Part ID: 0x%02X\n", part_id);
    return 0;
}

// Configure sensor function
int configure_sensor(int fd) {
    // Configure measurement rate (example: every 100ms)
    if (i2c_write_byte(fd, MEAS_RATE_REG, 0x0A) != 0) {
        fprintf(stderr, "Failed to configure measurement rate.\n");
        return -1;
    }
    printf("Sensor configured.\n");
    return 0;
}

// Read sensor data function
sensor_data_t read_sensor_data(int fd) {
    sensor_data_t data;
    unsigned short lux_raw, prox_raw;

    if (i2c_read_word(fd, LUX_DATA_REG, &lux_raw) != 0) {
        fprintf(stderr, "Failed to read lux data.\n");
        data.lux = -1.0; // Indicate error
    } else {
        // Convert raw lux data to lux (example conversion, adjust as needed)
        data.lux = (float)lux_raw * 0.01; // Example conversion factor
    }

    if (i2c_read_word(fd, PROX_DATA_REG, &prox_raw) != 0) {
        fprintf(stderr, "Failed to read proximity data.\n");
        data.proximity = -1; // Indicate error
    } else {
        data.proximity = (int)prox_raw;
    }

    return data;
