// I2C write function
int i2c_write_byte(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_byte(int fd, unsigned char reg, unsigned char *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// I2C read word function
int i2c_read_word(int fd, unsigned char reg, unsigned short *value) {
    unsigned char buf[1];
    unsigned char data[2];

    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        perror("I2C read failed");
        return -1;
