#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define DISTANCE_THRESHOLD 20.0 // cm
#define TRIGGER_PULSE_DURATION 10 // us

// Global variables
static volatile int echo_start_time = 0;
static volatile int echo_end_time = 0;
static volatile int echo_received = 0;
static volatile double distance = 0.0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void print_distance();
void set_buzzer(int state);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_time = tick;
        echo_received = 1; // Indicate that rising edge is received
    } else if (level == 0 && echo_received == 1) {
        echo_end_time = tick;
        echo_received = 0; // Reset the flag

        // Calculate pulse width in microseconds
        int pulse_width = echo_end_time - echo_start_time;

        // Calculate distance in centimeters
        distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 2 for one-way distance
    }
}

// Function to print the distance
void print_distance() {
    printf("Distance: %.2f cm\n", distance);
}

// Function to set the buzzer state
void set_buzzer(int state) {
    gpioWrite(BUZZER_PIN, state);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register interrupt handler for ECHO_PIN
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Generate trigger pulse
        trigger_pulse();

        // Wait for a short period
        gpioDelay(50); // Reduced delay to improve responsiveness

        // Print distance
        print_distance();

        // Control buzzer
        if (distance < DISTANCE_THRESHOLD) {
            set_buzzer(1); // Turn buzzer on
        } else {
            set_buzzer(0); // Turn buzzer off
        }

        // Wait for 1 second
        gpioDelay(1000); // Delay for 1 second
    }

    // This point will not be reached due to the infinite loop, but included for completeness
    gpioTerminate();
    return 0;
}

