#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_SERVO 18
#define PWM_RANGE 20000 // 20ms period (50Hz)
#define DISTANCE_THRESHOLD_OPEN 250 // mm
#define DISTANCE_THRESHOLD_CLOSE 200 // mm
#define LOG_FILE "gate_log.txt"

// VL53L1X Registers
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0049
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L1X_REG_SYSRANGE_START 0x000
#define VL53L1X_REG_INTERMEASUREMENT_PERIOD 0x0080

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void set_servo_pulse_width(int gpio, int pulse_width);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// VL53L1X Initialization
int vl53l1x_init(int i2c_handle) {
    // Check model ID
    char model_id;
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Set timing budget (example: 50ms)
    char timing_budget[2] = {0x00, 0x32}; // 50ms in ms
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_INTERMEASUREMENT_PERIOD, timing_budget, 2) != 2) {
        fprintf(stderr, "Error setting timing budget\n");
        return -1;
    }

    return 0;
}

// VL53L1X Read Distance
int vl53l1x_read_distance(int i2c_handle) {
    // Start ranging
    char start_ranging = 0x01;
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSRANGE_START, &start_ranging, 1) != 1) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    // Wait for data ready
    int data_ready = 0;
    int timeout = 100; // Timeout after 100ms
    while (!data_ready && timeout > 0) {
        char status;
        if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY, &status, 1) == 1) {
            data_ready = (status & 0x01);
        } else {
            fprintf(stderr, "Error reading data ready status\n");
            return -1;
        }
        gpioDelay(1); // Wait 1ms
        timeout--;
    }

    if (!data_ready) {
        fprintf(stderr, "Timeout waiting for data ready\n");
        return -1;
    }

    // Read distance
    char distance_data[2];
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, distance_data, 2) != 2) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    int distance = (distance_data[0] << 8) | distance_data[1];
    return distance;
}

// Set Servo Pulse Width
void set_servo_pulse_width(int gpio, int pulse_width) {
    gpioPWM(gpio, pulse_width);
}

// Log Event
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for servo
    gpioSetMode(GPIO_SERVO, PI_OUTPUT);
    gpioSetPWMrange(GPIO_SERVO, PWM_RANGE);
    gpioSetPWMfrequency(GPIO_SERVO, 50); // 50Hz

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int distance;
    int pulse_width = 1000; // Initial pulse width
    int gate_open = 0; // 0 = closed, 1 = open

    // Main loop
    while (!terminate) {
        distance = vl53l1x_read_distance(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Hysteresis logic
        if (distance > DISTANCE_THRESHOLD_OPEN && !gate_open) {
            pulse_width = 1000;
            gate_open = 1;
            log_event("Gate opened");
        } else if (distance < DISTANCE_THRESHOLD_CLOSE && gate_open) {
            pulse_width = 2000;
            gate_open = 0;
            log_event("Gate closed");
        }

        // Smooth transition (example: linear interpolation)
        // This part can be improved with a more sophisticated smoothing algorithm
        // For simplicity, we just set the pulse width directly based on the hysteresis logic

        set_servo_pulse_width(GPIO_SERVO, pulse_width);
        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioPWM(GPIO_SERVO, 0); // Stop PWM
    fclose(log_file);
    gpioTerminate();

    return 0;
}

