#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define MIN_ANGLE 0.0
#define MAX_ANGLE 180.0
#define TIMEOUT_US 50000 // 50ms timeout

// Global variable for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Shutting down gracefully...\n");
        program_running = 0;
        // Stop the servo
        gpioServo(SERVO_PIN, 0); // Send 0 degree command
        gpioDelay(100); // Give it some time to stop
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
