#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define CONFIG_REG 0x0F
#define TEMP_REG 0x00
#define HUMID_REG 0x01
#define MEASURE_TEMP_CMD 0x2C
#define MEASURE_HUMID_CMD 0x2D

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int write_i2c_reg(int handle, int reg, int val);
int read_i2c_reg(int handle, int reg);
float read_temperature(int handle);
float read_humidity(int handle);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write to I2C register
int write_i2c_reg(int handle, int reg, int val) {
    int result = i2cWriteByteData(handle, reg, val);
    if (result < 0) {
        fprintf(stderr, "Failed to write to I2C register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read from I2C register
int read_i2c_reg(int handle, int reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Failed to read from I2C register: %d\n", result);
        return -1;
    }
    return result;
}

// Read temperature from sensor
float read_temperature(int handle) {
    if (write_i2c_reg(handle, CONFIG_REG, MEASURE_TEMP_CMD) < 0) {
        return -1000.0; // Indicate error
    }
    gpioDelay(10000); // 10ms delay
    int raw_temp = read_i2c_reg(handle, TEMP_REG);
    if (raw_temp < 0) {
        return -1000.0; // Indicate error
    }
    return (float)raw_temp;
}

// Read humidity from sensor
float read_humidity(int handle) {
    if (write_i2c_reg(handle, CONFIG_REG, MEASURE_HUMID_CMD) < 0) {
        return -1000.0; // Indicate error
    }
    gpioDelay(10000); // 10ms delay
    int raw_humidity = read_i2c_reg(handle, HUMID_REG);
    if (raw_humidity < 0) {
        return -1000.0; // Indicate error
    }
    return (float)raw_humidity;
}

// Log data to console
void log_data(float temperature, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() < 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SI7005_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature(i2c_handle);
        float humidity = read_humidity(i2c_handle);

        if (temperature > -999.0 && humidity > -999.0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data. Re-initializing I2C.\n");
            i2cClose(i2c_handle);
            i2c_handle = open_i2c_bus(I2C_BUS, SI7005_ADDR);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break; // Exit loop if re-initialization fails
            }
        }

        gpioDelay(2000000); // 2 seconds delay
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

