#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// High repeatability measurement command
#define SHT40_MEASURE_CMD 0xFD

// I2C bus
#define I2C_BUS 1

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT40
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    uint8_t data[6];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, SHT40_MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 10ms)
    gpioDelay(10000); // 10ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Validate CRC checksums
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    // Convert data to temperature and humidity
    uint16_t temperature_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
    *humidity = 100.0 * (float)humidity_raw / 65535.0;

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    int read_result;

    // Main loop
    while (1) {
        read_result = read_sht40(i2c_handle, &temperature, &humidity);

        if (read_result == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading SHT40, retrying...\n");
            i2cClose(i2c_handle);
            gpioDelay(100000); // 100ms delay
            i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                gpioTerminate();
                return 1;
            }
            continue; // Skip the sleep and retry immediately
        }

        gpioDelay(5000000); // 5 seconds
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

