#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define TEMP_SCALE 0.02
#define TEMP_OFFSET 273.15
#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL_SEC 5

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(int reg);
float convert_to_celsius(int raw_temp);
int log_temperature(float ambient_temp, float object_temp);
void signal_handler(int signal);
void cleanup();

// Structure to hold temperature data
typedef struct {
    float ambient_temp;
    float object_temp;
} TemperatureData;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature data from the sensor
int read_temperature(int reg) {
    int raw_temp = i2cReadWordData(i2c_handle, reg);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature from register 0x%02X: %d\n", reg, raw_temp);
        return -1;
    }
    return raw_temp;
}

// Function to convert raw temperature data to Celsius
float convert_to_celsius(int raw_temp) {
    return (raw_temp * TEMP_SCALE) - TEMP_OFFSET;
}

// Function to log temperature data to a file
int log_temperature(float ambient_temp, float object_temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, ambient_temp, object_temp);
    fclose(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperature data
        int raw_ambient_temp = read_temperature(AMBIENT_TEMP_REG);
        int raw_object_temp = read_temperature(OBJECT_TEMP_REG);

        if (raw_ambient_temp >= 0 && raw_object_temp >= 0) {
            // Convert to Celsius
            float ambient_temp = convert_to_celsius(raw_ambient_temp);
            float object_temp = convert_to_celsius(raw_object_temp);

            // Log temperature data
            if (log_temperature(ambient_temp, object_temp) != 0) {
                fprintf(stderr, "Error logging temperature data\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature data, skipping logging\n");
        }

        // Wait for the next reading
        gpioSleep(PI_TIME_RELATIVE, READ_INTERVAL_SEC, 0);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

