    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t data[DATA_FRAME_SIZE];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Validate CRCs
            if (validate_crc(data, 3) == 0 && validate_crc(data + 3, 3) == 0 && validate_crc(data + 6, 3) == 0) {
                // Convert data
                sensor_data = convert_data(data);

                // Log data
                log_data(sensor_data);
