#define SHT40_ADDR 0x44

// High repeatability measurement command
#define MEASURE_HIGH_REPEATABILITY 0xFD

// Global variables for I2C handle and log file
int i2c_handle = -1;
FILE *log_file = NULL;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT40
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    uint8_t data[6];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, MEASURE_HIGH_REPEATABILITY);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Temperature CRC error\n");
        return -1;
    }
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Humidity CRC error\n");
        return -1;
    }

    // Convert data to temperature and humidity
    uint16_t temperature_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
    *humidity = 100.0 * (float)humidity_raw / 65535.0;

    return 0;
}

// Function to log data to file
int log_data(FILE *log_file, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    float temperature, humidity;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sht40_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read temperature and humidity
        result = read_sht40(i2c_handle, &temperature, &humidity);
        if (result == 0) {
            // Log data
            log_data(log_file, temperature, humidity);
        } else {
            fprintf(stderr, "Error reading SHT40 data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

