        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Write to I2C register
int write_i2c(int handle, int reg, int val) {
    int result, retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cWriteByteData(handle, reg, val);
        if (result == 0) {
            return 0; // Success
        } else {
