int read_sensor_data(int handle, float *temperature, float *humidity) {
    char buf[2];
    int raw_temperature, raw_humidity;

    // Measure temperature
    if (write_i2c(handle, 0, TEMP_CMD) != 0) {
        fprintf(stderr, "Failed to send temperature command.\n");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_MS);
    if (read_i2c(handle, 0, buf, 2) != 0) {
        fprintf(stderr, "Failed to read temperature data.\n");
        return -1;
    }
    raw_temperature = (buf[0] << 8) | buf[1];

    // Measure humidity
    if (write_i2c(handle, 0, HUMID_CMD) != 0) {
        fprintf(stderr, "Failed to send humidity command.\n");
        return -1;
