    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t raw_temperature;
        if (send_measurement_command() == 0) {
            gpioDelay(15000); // Wait 15ms
            if (read_temperature(&raw_temperature) == 0) {
                float temperature = convert_temperature(raw_temperature);
                if (log_temperature(temperature) != 0) {
                    fprintf(stderr, "Failed to log temperature\n");
                }
                printf("Temperature: %.2f °C\n", temperature);
            }
        } else {
            fprintf(stderr, "Failed to send measurement command\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Wait for the next sample
    }

    // Cleanup and exit
    cleanup();
    printf("Temperature monitoring stopped.\n");
    return 0;
}

