    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(FILENAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Send measurement command
    if (send_command(i2c_handle, MEASURE_COMMAND) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char buffer[DATA_LENGTH];
        int retry = 0;

        // Read data with retries
        while (retry < RETRY_COUNT) {
            if (read_data(i2c_handle, buffer, DATA_LENGTH) == 0) {
                break; // Success, exit retry loop
            } else {
                retry++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read data after %d retries.\n", RETRY_COUNT);
            continue; // Skip to the next iteration
        }

        // Validate CRC
        if (validate_crc(buffer, DATA_LENGTH) == 0) {
            // Process data
