#define BUFFER_SIZE 60
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer entries
typedef struct {
    time_t timestamp;
    float temperature;
} SensorData;

// Circular buffer
SensorData buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_temperature(float *temperature);
void control_fan(float temperature);
void buffer_data(float temperature);
void print_data(float temperature);
void signal_handler(int signal);
int init_gpio();
void cleanup();

// Function to initialize GPIO
int init_gpio() {
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode.\n");
        return -1;
    }
    return 0;
}

// Function to read temperature from Si7021 sensor
int read_temperature(float *temperature) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, TEMP_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing temperature command: %d. Retry %d\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        gpioDelay(10000); // Wait for measurement (10ms)

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading temperature data: %d. Retry %d\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        // Convert raw data to temperature (Celsius)
        uint16_t raw_temp = (buf[0] << 8) | buf[1];
        *temperature = (175.72 * raw_temp / 65536.0) - 46.85;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to control the cooling fan
void control_fan(float temperature) {
    static int fan_on = 0;

    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON\n");
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF\n");
    }
}

// Function to buffer temperature data with timestamp
void buffer_data(float temperature) {
    time(&buffer[buffer_index].timestamp);
    buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print temperature data with timestamp
void print_data(float temperature) {
    time_t now;
    time(&now);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    printf("%s Temperature: %.2f °C\n", buf, temperature);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    float temperature;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO for fan control
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            buffer_data(temperature);
            print_data(temperature);
            control_fan(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Continuing...\n");
        }

        gpioDelay(2000000); // Wait 2 seconds (2000000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    printf("Temperature monitoring stopped.\n");
    return 0;
}

