#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int send_command(uint16_t command);
int read_data(uint8_t *data, int count);
int check_data_ready();
int read_measurement(sensor_data_t *data);
int verify_crc(uint8_t data[], int len);
uint8_t calculate_crc(uint8_t data[], int len);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to SCD40
int send_command(uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read data from SCD40
int read_data(uint8_t *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Check if data is ready
int check_data_ready() {
    uint8_t data[3];
    if (read_data(data, 3) != 0) {
        return 0; // Assume not ready if read fails
    }
    return (data[0] == 0xE0 && data[1] == 0x00 && data[2] == 0x01);
}

// Read measurement data
int read_measurement(sensor_data_t *data) {
    uint8_t buf[9];
    if (read_data(buf, 9) != 0) {
        return -1;
    }

    // Verify CRC for each 2-byte word
    if (verify_crc(buf, 2) != 0 || verify_crc(buf + 2, 2) != 0 || verify_crc(buf + 4, 2) != 0) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    data->co2 = (buf[0] << 8) | buf[1];
    data->temperature = (buf[3] << 8) | buf[4];
    data->humidity = (buf[6] << 8) | buf[7];

    return 0;
}

// Verify CRC
int verify_crc(uint8_t data[], int len) {
    uint8_t crc = calculate_crc(data, len);
    return (crc != data[len]);
}

// Calculate CRC-8
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Log data to file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%u,%.2f,%.2f\n", timestamp, data.co2, (float)data.temperature / 100.0, (float)data.humidity / 100.0);
    fflush(log_file);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        send_command(CMD_STOP_PERIODIC_MEASUREMENT);
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Start periodic measurement
    if (send_command(CMD_START_PERIODIC_MEASUREMENT) != 0) {
        cleanup();
        return 1;
    }

    // Wait for at least 1 second
    gpioDelay(1000000); // 1 second

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Check if data is ready
        if (check_data_ready()) {
            // Read measurement
            if (read_measurement(&sensor_data) == 0) {
                // Log data
                log_data(sensor_data);
            } else {
                fprintf(stderr, "Failed to read measurement\n");
            }
        } else {
            //printf("Data not ready yet\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

