#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// GPIO pin for the warning LED
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 20

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int init_scd40();
int read_scd40_data(uint16_t *co2, float *temperature, float *humidity);
uint8_t crc8(const uint8_t *data, int len);
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
sensor_data_t get_latest_data(circular_buffer_t *buffer);
void control_led(uint16_t co2);
void signal_handler(int signal);
void cleanup();

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize SCD40 sensor
int init_scd40() {
    char buf[2];
    buf[0] = 0x21; // Start periodic measurement command
    buf[1] = 0xB1;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send start periodic measurement command: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for the command to be processed
    return 0;
}

// Read data from SCD40 sensor
int read_scd40_data(uint16_t *co2, float *temperature, float *humidity) {
    char buf[2];
    buf[0] = 0xE4; // Read measurement command
    buf[1] = 0xB8;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send read measurement command: %d\n", result);
        return -1;
    }
    gpioDelay(1); // Wait for the command to be processed

    char data[9];
    result = i2cReadDevice(i2c_handle, data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // CRC check
    if (crc8((uint8_t *)data, 2) != data[2] ||
        crc8((uint8_t *)data + 3, 2) != data[5] ||
        crc8((uint8_t *)data + 6, 2) != data[8]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    *co2 = (uint16_t)((data[0] << 8) | data[1]);
    *temperature = -45 + 175 * ((uint16_t)((data[3] << 8) | data[4])) / 65535.0;
    *humidity = 100 * ((uint16_t)((data[6] << 8) | data[7])) / 65535.0;

    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get the latest data from the circular buffer
sensor_data_t get_latest_data(circular_buffer_t *buffer) {
    int index = (buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return buffer->data[index];
}

// Control the warning LED based on CO2 concentration
void control_led(uint16_t co2) {
    if (co2 > 1000) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    // Stop periodic measurement
    char buf[2];
    buf[0] = 0x3F; // Stop periodic measurement command
    buf[1] = 0x86;
    i2cWriteDevice(i2c_handle, buf, 2);
    gpioDelay(10);

    // Close I2C device
    i2cClose(i2c_handle);

    // Release GPIO
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioSetMode(LED_PIN, PI_INPUT); // Set back to input

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize SCD40 sensor
    if (init_scd40() != 0) {
        cleanup();
        return 1;
    }

    // Configure LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize circular buffer
    buffer.head = 0;
    buffer.count = 0;

    // Main loop
    while (!terminate) {
        uint16_t co2;
        float temperature;
        float humidity;

        if (read_scd40_data(&co2, &temperature, &humidity) == 0) {
            // Validate sensor readings
            if (co2 > 0 && co2 < 5000 && temperature > -40 && temperature < 125 && humidity > 0 && humidity < 100) {
                // Create sensor data struct
                sensor_data_t data = {co2, temperature, humidity};

                // Add data to circular buffer
                add_to_buffer(&buffer, data);

                // Print data to stdout
                printf("CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%\n", co2, temperature, humidity);

                // Control LED
                control_led(co2);
            } else {
                fprintf(stderr, "Invalid sensor readings\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup resources
    cleanup();

    return 0;
}

