#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 5 // seconds
#define TIMEOUT_US 50000 // 50ms timeout

// Global variables for signal handling
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int high_time;
    int low_time;
    int total_time;
} sensor_data_t;

// Function prototypes
int initialize_gpio();
sensor_data_t read_sensor_data();
double calculate_temperature(sensor_data_t data);
void log_temperature(double temperature);
void handle_signal(int signal);
void cleanup();

// Signal handler function
void handle_signal(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to initialize the pigpio library and GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    return 0; // Indicate success
}

// Function to read sensor data (high time, low time, total time)
sensor_data_t read_sensor_data() {
    sensor_data_t data = {0, 0, 0};
    uint32_t start_tick, end_tick, current_tick;
    int timeout_count = 0;

    // Measure high time
    while (gpioRead(GPIO_PIN) == 0 && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        timeout_count++;
    }
    if (timeout_count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for high pulse\n");
        data.high_time = -1; // Indicate error
        return data;
    }
    start_tick = gpioTick();

    timeout_count = 0;
    while (gpioRead(GPIO_PIN) == 1 && timeout_count < TIMEOUT_US) {
        gpioDelay(1);
        timeout_count++;
    }
    if (timeout_count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for low pulse\n");
        data.high_time = -1; // Indicate error
        return data;
    }
    end_tick = gpioTick();
    data.high_time = end_tick - start_tick;

    // Measure low time
    timeout_count = 0;
    while (gpioRead(GPIO_PIN) == 0 && timeout_count < TIMEOUT_US) {
        gpioDelay(1);
        timeout_count++;
    }
    if (timeout_count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for high pulse after low\n");
        data.low_time = -1; // Indicate error
        return data;
    }
    start_tick = gpioTick();

    timeout_count = 0;
    while (gpioRead(GPIO_PIN) == 1 && timeout_count < TIMEOUT_US) {
        gpioDelay(1);
        timeout_count++;
    }
    if (timeout_count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for low pulse after high\n");
        data.low_time = -1; // Indicate error
        return data;
    }
    end_tick = gpioTick();
    data.low_time = end_tick - start_tick;

    data.total_time = data.high_time + data.low_time;

    return data;
}

// Function to calculate temperature from sensor data
double calculate_temperature(sensor_data_t data) {
    if (data.low_time == 0) {
        fprintf(stderr, "Division by zero error: low_time is zero\n");
        return -999.0; // Indicate error
    }

    double duty_cycle = (double)data.high_time / (double)data.low_time;
    double temperature = (duty_cycle * 100.0 - 50.0) * 0.1;

    return temperature;
}

// Function to log temperature data to a file
void log_temperature(double temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

int main() {
    int consecutive_failures = 0;
    sensor_data_t sensor_data;
    double temperature;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        sensor_data = read_sensor_data();

        if (sensor_data.high_time == -1 || sensor_data.low_time == -1) {
            fprintf(stderr, "Error reading sensor data\n");
            consecutive_failures++;
            if (consecutive_failures >= 3) {
                fprintf(log_file, "SENSOR MALFUNCTION\n");
                fflush(log_file);
                consecutive_failures = 0; // Reset counter after logging malfunction
            }
        } else {
            temperature = calculate_temperature(sensor_data);

            if (temperature < -40.0 || temperature > 150.0) {
                fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
                fprintf(log_file, "Temperature out of range: %.2f\n", temperature);
                fflush(log_file);
            } else {
                log_temperature(temperature);
                consecutive_failures = 0; // Reset failure counter on successful read
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    printf("Temperature monitoring stopped.\n");
    return 0;
}

