#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x2400
#define RETRY_COUNT 3
#define RETRY_DELAY 1 // seconds
#define LOG_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL 5 // seconds
#define SINE_PERIOD 3600 // seconds (1 hour)

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_pigpio();
int open_i2c_device();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum);
int validate_crc(uint8_t data[], int nbrOfBytes);
SensorData convert_raw_data(uint16_t raw_temperature, uint16_t raw_humidity);
SensorData apply_sinusoidal_offset(SensorData data, time_t timestamp);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, cmd, 2);
        if (result == 0) {
            gpioDelay(15000); // Wait 15 ms
            result = i2cReadDevice(i2c_handle, (char *)data, 6);
            if (result == 6) {
                return 0; // Success
            } else {
                fprintf(stderr, "I2C read failed (attempt %d): %d\n", i + 1, result);
            }
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", i + 1, result);
        }
        gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
    }
    return -1; // Failure after retries
}

// Calculate CRC
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= (data[i]);
        for (bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc_calculated = calculate_crc(data, nbrOfBytes, 0);
    return (crc_calculated == data[nbrOfBytes]);
}

// Convert raw data to temperature and humidity
SensorData convert_raw_data(uint16_t raw_temperature, uint16_t raw_humidity) {
    SensorData data;
    data.temperature = -45.0 + (175.0 * (float)raw_temperature / 65535.0);
    data.humidity = 100.0 * (float)raw_humidity / 65535.0;
    return data;
}

// Apply sinusoidal offset
SensorData apply_sinusoidal_offset(SensorData data, time_t timestamp) {
    SensorData offset_data;
    double time_in_seconds = difftime(timestamp, time(NULL) - SINE_PERIOD);

    offset_data.temperature = data.temperature + 2.0 * sin(2 * M_PI * time_in_seconds / SINE_PERIOD);
    offset_data.humidity = data.humidity + 5.0 * sin(2 * M_PI * time_in_seconds / SINE_PERIOD);

    // Clamp humidity to 0-100%
    if (offset_data.humidity < 0.0) offset_data.humidity = 0.0;
    if (offset_data.humidity > 100.0) offset_data.humidity = 100.0;

    return offset_data;
}

// Log data to file
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", buf, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    if (open_i2c_device() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint8_t data[6];
    SensorData sensor_data;
    time_t current_time;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Validate CRC
            if (validate_crc(data, 2) && validate_crc(data + 3, 2)) {
                // Convert raw data
                uint16_t raw_temperature = (data[0] << 8) | data[1];
                uint16_t raw_humidity = (data[3] << 8) | data[4];
