        // Read data
        if (read_data(i2c_handle, data, 9) != 0) {
            fprintf(stderr, "Failed to read data\n");
            break;
        }

        // Validate CRC
        if (validate_crc(data, 9) != 0) {
            fprintf(stderr, "CRC validation failed\n");
            break;
