#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// SHT35 I2C address
#define SHT35_ADDR 0x44

// SHT35 command for single-shot high-repeatability measurement
#define SHT35_MEASURE_CMD 0x2400

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int write_i2c_data(int handle, uint16_t command);
int read_i2c_data(int handle, uint8_t *data, int count);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
sensor_data_t read_sensor_data(int handle);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(1, SHT35_ADDR, 0); // Bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Write data to I2C device
int write_i2c_data(int handle, uint16_t command) {
    uint8_t data[2];
    data[0] = (command >> 8) & 0xFF;
    data[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, (char *)data, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from I2C device
int read_i2c_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_crc(const uint8_t *data, int len) {
    if (len != 2) return -1; // Expecting 2 bytes for temperature and humidity
    uint8_t crc_temp = crc8(data, 2);
    if (crc_temp != data[2]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    uint8_t crc_humidity = crc8(data + 3, 2);
    if (crc_humidity != data[5]) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }
    return 0;
}

// Read sensor data
sensor_data_t read_sensor_data(int handle) {
    sensor_data_t data;
    uint8_t raw_data[6];

    // Send measurement command
    if (write_i2c_data(handle, SHT35_MEASURE_CMD) != 0) {
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // Wait for measurement (at least 15ms)
