int open_i2c_bus() {
    i2c_handle = i2cOpen(1, SHT35_ADDR, 0); // Bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
