#define MEASURE_TEMP_CMD 0xE3
#define MEASURE_HUMID_CMD 0xE5
#define RESET_CMD 0xFE
#define LOG_FILE "environment.log"
#define POLL_DELAY_MS 10
#define MAX_RETRIES 10
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t command, uint8_t *data, int data_len);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int verify_crc(uint8_t msb, uint8_t lsb, uint8_t crc);
void log_data(float temperature, float humidity);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x131; // Polynomial: x^8 + x^5 + x^4 + 1
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retry and timeout
int read_sensor_data(uint8_t command, uint8_t *data, int data_len) {
    int retries = 0;
    int bytes_read = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteByte(i2c_handle, command) != 0) {
            fprintf(stderr, "Error writing command: %d\n", command);
            log_error("I2C write error");
            return -1;
        }

        gpioDelay(POLL_DELAY_MS * 1000); // Delay for sensor to prepare data

        bytes_read = i2cReadDevice(i2c_handle, (char *)data, data_len);
        if (bytes_read == data_len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, bytes_read);
            log_error("I2C read error");
            retries++;
            gpioDelay(POLL_DELAY_MS * 1000); // Wait before retrying
        }
    }

    fprintf(stderr, "Max retries reached for command 0x%02X\n", command);
    log_error("Max retries reached");
    return -1; // Failure after max retries
