    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_C,humidity_percent\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        uint8_t temp_data[3];
        uint8_t humid_data[3];
        float temperature, humidity;

        // Read temperature
        if (read_sensor_data(MEASURE_TEMP_CMD, temp_data, 3) == 0) {
            if (verify_crc(temp_data[0], temp_data[1], temp_data[2])) {
