                temperature = convert_temperature(raw_temp);
            } else {
                log_error("Temperature CRC error");
                temperature = -999.0; // Indicate error
            }
        } else {
            log_error("Temperature read error");
            temperature = -999.0; // Indicate error
        }

        // Read humidity
        if (read_sensor_data(MEASURE_HUMID_CMD, humid_data, 3) == 0) {
