#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define AIRFLOW_FILE "airflow.dat"

// Global variables
int i2c_handle = -1;
FILE *fp = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int write_i2c(int handle, uint16_t cmd);
int read_i2c(int handle, char *buf, int count);
int crc8(const char *data, int len);
int validate_crc(const char *data, int len);
sensor_data_t convert_data(const char *buf);
int log_data(FILE *fp, float pressure, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Write command to I2C device
int write_i2c(int handle, uint16_t cmd) {
    char buf[2];
    buf[0] = (cmd >> 8) & 0xFF;
    buf[1] = cmd & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from I2C device
int read_i2c(int handle, char *buf, int count) {
    int result = i2cReadDevice(handle, buf, count);
    if (result != count) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// CRC-8 calculation
int crc8(const char *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(const char *data, int len) {
    uint8_t calculated_crc = crc8(data, len - 1);
    uint8_t received_crc = data[len - 1];
    return (calculated_crc == received_crc);
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(const char *buf) {
    sensor_data_t data;
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    int16_t raw_temperature = (buf[3] << 8) | buf[4];

    // Scale factors (from SDP810 datasheet)
    float pressure_scale_factor = 60.0; // Pa
    float temperature_scale_factor = 200.0; // °C

    data.pressure = (float)raw_pressure / pressure_scale_factor;
    data.temperature = (float)raw_temperature / temperature_scale_factor;

    return data;
}

// Log data to file
int log_data(FILE *fp, float pressure, float temperature) {
    if (fwrite(&pressure, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Failed to write pressure to file: %s\n", strerror(errno));
        return -1;
    }
    if (fwrite(&temperature, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Failed to write temperature to file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SDP810_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open data file
    fp = fopen(AIRFLOW_FILE, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open data file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char buf[9];
        sensor_data_t sensor_data;

        // Send measurement command
        if (write_i2c(i2c_handle, MEASURE_CMD) != 0) {
            break;
        }

        // Wait for conversion time (at least 20ms)
        gpioDelay(25000); // 25ms

        // Read data
        if (read_i2c(i2c_handle, buf, 9) != 0) {
            break;
        }

        // Validate CRC
        if (!validate_crc(buf, 3) || !validate_crc(buf + 3, 3)) {
            fprintf(stderr, "CRC validation failed\n");
            break;
        }

        // Convert data
        sensor_data = convert_data(buf);

        // Log data
        if (log_data(fp, sensor_data.pressure, sensor_data.temperature) != 0) {
            break;
        }

        // Wait for next sample
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();

    return 0;
}

