    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            update_buffer(temperature);
            float average_temperature = calculate_average();
            control_led(average_temperature);
            printf("Temperature: %.2f°C, Average: %.2f°C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Skipping iteration due to read error.\n");
        }

        sleep(1);
    }

    // Cleanup
    gpioWrite(GPIO_LED, 0); // Turn LED off
    i2cClose(i2c_handle);
