#define SCD30_I2C_ADDR 0x61

// SCD30 commands
#define SCD30_CMD_START_PERIODIC_MEASUREMENT 0x0010
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_GET_DATA_READY 0x0202
#define SCD30_CMD_SET_MEASUREMENT_INTERVAL 0x4600

// Measurement interval (seconds)
#define MEASUREMENT_INTERVAL 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int configure_scd30();
int start_periodic_measurement();
int read_measurement(sensor_data_t *data);
int check_data_ready();
int calculate_crc(uint16_t data);
int log_data(sensor_data_t data);
void ventilation_control(float co2);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0); // Bus 1, address 0x61, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Configure SCD30 sensor
int configure_scd30() {
    // Set measurement interval to 5 seconds
    char buf[3];
    buf[0] = (SCD30_CMD_SET_MEASUREMENT_INTERVAL >> 8) & 0xFF;
    buf[1] = SCD30_CMD_SET_MEASUREMENT_INTERVAL & 0xFF;
    buf[2] = MEASUREMENT_INTERVAL; // Interval in seconds

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Failed to set measurement interval: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100); // Wait for the command to be processed
    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (SCD30_CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = SCD30_CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Failed to start periodic measurement: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100); // Wait for the command to be processed
    return 0;
}

// Check if data is ready
int check_data_ready() {
    char buf[2];
    char result[3];
    buf[0] = (SCD30_CMD_GET_DATA_READY >> 8) & 0xFF;
    buf[1] = SCD30_CMD_GET_DATA_READY & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Failed to write data ready command: %s\n", strerror(errno));
        return -1;
    }

    if (i2cReadDevice(i2c_handle, result, 3) != 3) {
        fprintf(stderr, "Failed to read data ready status: %s\n", strerror(errno));
        return -1;
    }

    uint16_t data_ready = (result[0] << 8) | result[1];

    return (data_ready > 0) ? 1 : 0;
}

// Calculate CRC checksum
int calculate_crc(uint16_t data) {
    uint8_t data_bytes[2];
    data_bytes[0] = (data >> 8) & 0xFF;
    data_bytes[1] = data & 0xFF;

    uint8_t crc = 0xFF;
    for (int i = 0; i < 2; i++) {
        crc ^= data_bytes[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Read measurement data
int read_measurement(sensor_data_t *data) {
    char buf[2];
    char result[18];
    buf[0] = (SCD30_CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = SCD30_CMD_READ_MEASUREMENT & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Failed to write read measurement command: %s\n", strerror(errno));
        return -1;
    }

    if (i2cReadDevice(i2c_handle, result, 18) != 18) {
        fprintf(stderr, "Failed to read measurement data: %s\n", strerror(errno));
        return -1;
    }

    // Extract CO2, temperature and humidity values
    uint16_t co2_raw = (result[0] << 8) | result[1];
    uint16_t temperature_raw = (result[6] << 8) | result[7];
    uint16_t humidity_raw = (result[12] << 8) | result[13];

    // CRC Check
    uint8_t co2_crc = result[2];
    uint8_t temperature_crc = result[8];
    uint8_t humidity_crc = result[14];

    if (calculate_crc(co2_raw) != co2_crc) {
        fprintf(stderr, "CO2 CRC check failed\n");
        return -1;
    }
    if (calculate_crc(temperature_raw) != temperature_crc) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }
    if (calculate_crc(humidity_raw) != humidity_crc) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    // Convert raw values to float
    data->co2 = *((float*)&co2_raw);
    data->temperature = *((float*)&temperature_raw);
    data->humidity = *((float*)&humidity_raw);

    return 0;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file);

    return 0;
}

// Ventilation control logic
void ventilation_control(float co2) {
    if (co2 < 800) {
        printf("Ventilation: OFF\n");
    } else if (co2 < 1200) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        cleanup();
        return 1;
    }

    // Configure SCD30 sensor
    if (configure_scd30() != 0) {
        cleanup();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Check if data is ready
        if (check_data_ready()) {
            // Read measurement data
            if (read_measurement(&sensor_data) == 0) {
                // Log data
                log_data(sensor_data);

                // Ventilation control
                ventilation_control(sensor_data.co2);
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
            }
        } else {
            printf("Data not ready yet\n");
        }

        // Wait for the next measurement interval
        gpioDelay(MEASUREMENT_INTERVAL * 1000); // Convert seconds to milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

