#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// SDP32 I2C address
#define SDP32_ADDR 0x21

// SDP32 command to start continuous measurement
#define SDP32_MEASURE_CMD 0x362F // Trigger continuous measurement without averaging

// Global variables for I2C handle and program termination
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint16_t scale_factor;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sdp32_data(sensor_data_t *data);
int verify_crc8(uint8_t data, uint8_t crc);
float convert_pressure(int16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
void print_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SDP32_ADDR, 0); // Bus 1, address 0x21, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read data from SDP32 sensor
int read_sdp32_data(sensor_data_t *data) {
    char buf[9];
    int result = i2cReadDevice(i2c_handle, buf, 9);

    if (result != 9) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    // Extract data from buffer
    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    uint8_t pressure_crc = buf[2];
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);
    uint8_t temperature_crc = buf[5];
    data->scale_factor = (uint16_t)((buf[6] << 8) | buf[7]);
    uint8_t scale_factor_crc = buf[8];

    // Verify CRC8 checksums
    if (!verify_crc8((uint8_t)((buf[0] << 8) | buf[1]), pressure_crc)) {
        fprintf(stderr, "Pressure CRC check failed\n");
        return -1;
    }
    if (!verify_crc8((uint8_t)((buf[3] << 8) | buf[4]), temperature_crc)) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }
    if (!verify_crc8((uint8_t)((buf[6] << 8) | buf[7]), scale_factor_crc)) {
        fprintf(stderr, "Scale factor CRC check failed\n");
        return -1;
    }

    return 0;
}

// Verify CRC8 checksum
int verify_crc8(uint8_t data, uint8_t crc) {
    uint8_t crc_calculated = 0xFF;
    for (int i = 0; i < 8; i++) {
        if ((crc_calculated ^ data) & 0x80) {
            crc_calculated = (crc_calculated << 1) ^ 0x31; // Polynomial 0x31
        } else {
            crc_calculated <<= 1;
        }
        data <<= 1;
    }
    return (crc_calculated == crc);
}

// Convert raw pressure to Pascal
float convert_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / 60.0f; // Sensitivity from datasheet
}

// Convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return (float)raw_temperature / 200.0f; // Offset from datasheet
}

// Print sensor data with timestamp
void print_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    float pressure = convert_pressure(data.pressure);
    float temperature = convert_temperature(data.temperature);

    printf("%s - Pressure: %.2f Pa, Temperature: %.2f C, Scale Factor: %u\n", timestamp, pressure, temperature, data.scale_factor);
}

int main(int argc, char *argv[]) {
    int interval_ms = 1000; // Default interval

    // Parse command-line argument for interval
    if (argc > 1) {
        interval_ms = atoi(argv[1]);
        if (interval_ms <= 0) {
            fprintf(stderr, "Invalid interval. Using default 1000ms.\n");
            interval_ms = 1000;
        }
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Start continuous measurement
    char cmd[2] = {(SDP32_MEASURE_CMD >> 8) & 0xFF, SDP32_MEASURE_CMD & 0xFF};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Failed to send measurement command\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
