typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to process sensor data
int process_sensor_data(const uint8_t *data, sensor_data_t *sensor_data) {
    // Extract raw values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Extract scale factors
    uint16_t scale_factor_pressure = (data[6] << 8) | data[7];
    uint16_t scale_factor_temperature = (data[8] << 8) | data[9];

    // CRC validation
    if (crc8(data, 3) != data[2]) {
        fprintf(stderr, "CRC error for pressure data\n");
        return -1;
    }
    if (crc8(data + 3, 3) != data[5]) {
        fprintf(stderr, "CRC error for temperature data\n");
        return -1;
    }

    // Convert to physical units
    sensor_data->pressure = (float)raw_pressure / (float)scale_factor_pressure;
    sensor_data->temperature = (float)raw_temperature / (float)scale_factor_temperature;

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stdout, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

