    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint8_t data[9];
    sensor_data_t sensor_data;
    time_t last_log_time = 0;

    while (!terminate) {
        // Trigger measurement
        uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
            fprintf(stderr, "Error writing to I2C\n");
        }

        // Wait for conversion to complete (at least 45ms)
        gpioDelay(45000); // 45ms

        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Process sensor data
            if (process_sensor_data(data, &sensor_data) == 0) {
                // Log data every second
                time_t current_time = time(NULL);
                if (current_time - last_log_time >= 1) {
                    printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", sensor_data.pressure, sensor_data.temperature);
                    last_log_time = current_time;
                }
            } else {
                fprintf(stderr, "Error processing sensor data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Sleep for a short interval
        gpioDelay(10000); // 10ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

