// HDC1000 I2C address
#define HDC1000_ADDR 0x40

// HDC1000 register addresses
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x01
#define CONFIGURATION_REG 0x02

// I2C bus
#define I2C_BUS 1

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature and humidity from HDC1000
int read_hdc1000(int i2c_handle, float *temperature, float *humidity) {
    uint8_t data[4];
    int result;

    // Trigger temperature and humidity measurement
    result = i2cWriteByteData(i2c_handle, CONFIGURATION_REG, 0x00); // Reset
    if (result < 0) {
        fprintf(stderr, "Error writing to configuration register: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(15); // Wait for reset to complete

    result = i2cWriteByteData(i2c_handle, CONFIGURATION_REG, 0x00); // Configure for temperature and humidity measurement
    if (result < 0) {
        fprintf(stderr, "Error writing to configuration register: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(20); // Wait for conversion

    // Read temperature data
    result = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, (char *)data, 4);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature and humidity data: %s\n", strerror(errno));
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t temperature_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[2] << 8) | data[3];

    *temperature = ((float)temperature_raw / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)humidity_raw / 65536.0) * 100.0;

    return 0;
}

int main() {
    float temperature, humidity;
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, HDC1000_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read temperature and humidity
        result = read_hdc1000(i2c_handle, &temperature, &humidity);
        if (result == 0) {
            // Print temperature and humidity
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup (should not reach here in normal operation due to signal handler)
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

