#define ICP10101_MEASURE 0x71
#define ICP10101_TEMP_MSB 0x03
#define ICP10101_PRESS_MSB 0x00

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_raw_data(uint32_t *raw_temperature, uint32_t *raw_pressure);
sensor_data_t convert_data(uint32_t raw_temperature, uint32_t raw_pressure);
void print_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, ICP10101_ADDR, 0); // Bus 1, address 0x69, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger a measurement
int trigger_measurement() {
    char buf[1];
    buf[0] = 0x07; // Command to trigger measurement (replace with actual command)
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(7000); // Wait 7 ms
    return 0;
}

// Read raw temperature and pressure data
int read_raw_data(uint32_t *raw_temperature, uint32_t *raw_pressure) {
    char buf[6];
    int result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    *raw_pressure = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | (uint32_t)buf[2];
    *raw_temperature = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | (uint32_t)buf[5];

    return 0;
}

// Convert raw data to temperature and pressure
sensor_data_t convert_data(uint32_t raw_temperature, uint32_t raw_pressure) {
    sensor_data_t data;
    // Replace with actual conversion formulas from the datasheet
    data.temperature = (float)raw_temperature / 100.0; // Example conversion
    data.pressure = (float)raw_pressure; // Example conversion
    return data;
}

// Print data with timestamp
void print_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, data.temperature, data.pressure);
}

// Cleanup function
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint32_t raw_temperature, raw_pressure;

        if (trigger_measurement() == 0) {
            if (read_raw_data(&raw_temperature, &raw_pressure) == 0) {
                sensor_data_t data = convert_data(raw_temperature, raw_pressure);
                print_data(data);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        } else {
            fprintf(stderr, "Error triggering measurement\n");
        }

        sleep(5); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

