int read_sensor_data(sensor_data_t *data) {
    char buf[3];
    char cmd[2] = {(MEASURE_COMMAND >> 8) & 0xFF, MEASURE_COMMAND & 0xFF};
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
            fprintf(stderr, "Failed to write trigger command: %d\n", i2c_handle);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        gpioDelay(8000); // Wait 8ms

        if (i2cReadDevice(i2c_handle, buf, 3) != 3) {
            fprintf(stderr, "Failed to read sensor data: %d\n", i2c_handle);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        data->pressure_raw = (buf[0] << 8) | buf[1];
        data->crc = buf[2];
        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries\n");
    return -1; // Failure
}

