    if (access(LOG_FILE, F_OK) == 0) {
        FILE *fp = fopen(LOG_FILE, "r");
        if (fp != NULL) {
            int c = fgetc(fp);
            if (c == EOF) {
                // File is empty, add header
                fprintf(log_file, "Timestamp,Pressure (Pa)\n");
            }
            fclose(fp);
        }
    } else {
        // File doesn't exist, create it and add header
        fprintf(log_file, "Timestamp,Pressure (Pa)\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

