    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            // CRC check
            uint8_t data[2] = {(sensor_data.pressure_raw >> 8) & 0xFF, sensor_data.pressure_raw & 0xFF};
            uint8_t calculated_crc = calculate_crc(data, 2);

            if (calculated_crc == sensor_data.crc) {
                float pressure = convert_to_pressure(sensor_data.pressure_raw);
                log_data(pressure);
                printf("Pressure: %.2f Pa\n", pressure);
            } else {
                fprintf(stderr, "CRC check failed! Expected: 0x%02X, Got: 0x%02X\n", sensor_data.crc, calculated_crc);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

