#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define MEASURE_CMD 0x00
#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE 1048576 // 1MB
#define MEASUREMENT_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(uint16_t *humidity, uint16_t *temperature);
sensor_data_t process_sensor_data(uint16_t raw_humidity, uint16_t raw_temperature);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger a measurement on the HIH6130
int trigger_measurement() {
    int result = i2cWriteByte(i2c_handle, MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(40000); // Wait 40ms
    return 0;
}

// Read sensor data from the HIH6130
int read_sensor_data(uint16_t *humidity, uint16_t *temperature) {
    char buf[4];
    int result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Check status bits (first two bits of the first byte)
    uint16_t status = (buf[0] << 8) | buf[1];
    status = status >> 14; // Shift right to get the status bits

    if (status != 0) {
        fprintf(stderr, "Error: Invalid sensor status: 0x%X\n", status);
        return -1;
    }

    *humidity = ((buf[0] & 0x3F) << 8) | buf[1];
    *temperature = (buf[2] << 6) | (buf[3] >> 2);

    return 0;
}

// Process raw sensor data to get temperature and humidity
sensor_data_t process_sensor_data(uint16_t raw_humidity, uint16_t raw_temperature) {
    sensor_data_t data;
    data.humidity = ((float)raw_humidity / 16383) * 100;
    data.temperature = ((float)raw_temperature / 16383) * 165 - 40;
    return data;
}

// Log data to a file with ISO-8601 timestamp
int log_data(sensor_data_t data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    // Check file size and truncate if necessary
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size > MAX_LOG_SIZE) {
        fclose(fp);
        fp = fopen(LOG_FILE, "w"); // Open in write mode to truncate
        if (fp == NULL) {
            fprintf(stderr, "Error opening log file for truncation!\n");
            return -1;
        }
    }

    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fclose(fp);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Starting environmental data logging...\n");

    while (!terminate) {
        uint16_t raw_humidity, raw_temperature;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Measurement trigger failed, retrying in %d seconds...\n", MEASUREMENT_INTERVAL);
            sleep(MEASUREMENT_INTERVAL);
            continue;
        }

        // Read sensor data
        if (read_sensor_data(&raw_humidity, &raw_temperature) != 0) {
            fprintf(stderr, "Sensor read failed, retrying in %d seconds...\n", MEASUREMENT_INTERVAL);
            sleep(MEASUREMENT_INTERVAL);
            continue;
        }

        // Process sensor data
        sensor_data_t data = process_sensor_data(raw_humidity, raw_temperature);

        // Log data
        if (log_data(data) != 0) {
            fprintf(stderr, "Logging failed, retrying in %d seconds...\n", MEASUREMENT_INTERVAL);
        }

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", data.temperature, data.humidity);

        sleep(MEASUREMENT_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

