    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
        fflush(log_file); // Ensure data is written to disk
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }
}

// Cleanup resources before exiting
