#define MIN_PULSE_WIDTH 12
#define MAX_PULSE_WIDTH 271

// Structure to hold SENT data
typedef struct {
    unsigned int status;
    unsigned int data1;
    unsigned int data2;
    unsigned int data3;
    unsigned int checksum;
} SENTData;

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sent_data(SENTData *data);
int decode_sent_data(const unsigned int *pulse_widths, SENTData *data);
float calculate_pressure(const SENTData *data);
int log_pressure_data(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Read SENT data from the sensor
int read_sent_data(SENTData *data) {
    int i;
    unsigned int pulse_widths[8]; // 8 nibbles: sync, status, data1, data2, data3, checksum
    unsigned int start_time, end_time, pulse_width;
    int nibble_count = 0;

    // Wait for the start of the SENT frame (falling edge)
    while (gpioRead(GPIO_PIN) == 1 && running) {
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    start_time = gpioTick();

    for (i = 0; i < 8; i++) {
        // Measure the pulse width
        while (gpioRead(GPIO_PIN) == 1 && running) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for falling edge\n");
                return -1; // Timeout
            }
        }
        start_time = gpioTick();

        while (gpioRead(GPIO_PIN) == 0 && running) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for rising edge\n");
                return -1; // Timeout
            }
        }
        end_time = gpioTick();

        pulse_width = end_time - start_time;

        if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Invalid pulse width: %u ticks\n", pulse_width);
            return -1; // Invalid pulse width
        }

        pulse_widths[i] = pulse_width;
    }

    return decode_sent_data(pulse_widths, data);
}

// Decode the SENT data
int decode_sent_data(const unsigned int *pulse_widths, SENTData *data) {
    int i;
    unsigned int nibble;

    // Check synchronization pulse
    if (pulse_widths[0] < SENT_SYNC_PULSE * 0.8 || pulse_widths[0] > SENT_SYNC_PULSE * 1.2) {
        fprintf(stderr, "Invalid synchronization pulse: %u ticks\n", pulse_widths[0]);
        return -1; // Invalid sync pulse
    }

    // Decode nibbles
    for (i = 1; i < 8; i++) {
        nibble = 0;
        if (pulse_widths[i] > 100) {
            nibble = 15; // Long pulse
        } else if (pulse_widths[i] > 80) {
            nibble = 14;
        } else if (pulse_widths[i] > 60) {
            nibble = 13;
        } else if (pulse_widths[i] > 40) {
            nibble = 12;
        } else if (pulse_widths[i] > 20) {
            nibble = 11;
        } else {
            nibble = 0; // Short pulse
        }

        switch (i) {
            case 1:
