#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// SHT40 command for high precision measurement
#define SHT40_MEASURE_HIGH_PRECISION 0xFD

// Global variables for cleanup
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int read_sht40(int i2c_handle, float *temperature, float *humidity);
uint8_t crc8(const uint8_t *data, size_t len);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to read data from SHT40 sensor
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    uint8_t data[6];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, 0, SHT40_MEASURE_HIGH_PRECISION);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 8.5 ms)
    gpioDelay(8500); // Delay in microseconds

    // Read 6 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // CRC validation for temperature
    uint8_t temp_data[2] = {data[0], data[1]};
    uint8_t temp_crc = data[2];
    if (crc8(temp_data, 2) != temp_crc) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    // CRC validation for humidity
    uint8_t humidity_data[2] = {data[3], data[4]};
    uint8_t humidity_crc = data[5];
    if (crc8(humidity_data, 2) != humidity_crc) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    uint16_t temp_raw = (data[0] << 8) | data[1];
    *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;

    // Convert raw data to humidity (%RH)
    uint16_t humidity_raw = (data[3] << 8) | data[4];
    *humidity = 100.0 * (float)humidity_raw / 65535.0;

    return 0;
}

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    size_t i, j;

    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close I2C handle
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    sensor_data_t sensor_data;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C interface
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read sensor data
        result = read_sht40(i2c_handle, &sensor_data.temperature, &sensor_data.humidity);
        if (result == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Write data to log file
            fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, sensor_data.temperature, sensor_data.humidity);
            fflush(log_file); // Flush the buffer to ensure data is written immediately

            printf("%s,%.2f,%.2f\n", timestamp, sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // Delay in microseconds
    }

    return 0;
}

