#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SHTC3 I2C address
#define SHTC3_ADDR 0x70

// SHTC3 command for single shot measurement with clock stretching disabled
#define SHTC3_MEASURE_CMD 0x7866

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
uint8_t crc8(const uint8_t *data, size_t len);
int validate_data(uint8_t *data);
int convert_data(uint8_t *data, float *temperature, float *humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0); // Bus 1, address 0x70, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read data from the SHTC3 sensor
int read_sensor_data(uint8_t *data) {
    char cmd[2] = {(SHTC3_MEASURE_CMD >> 8) & 0xFF, SHTC3_MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(12500); // Wait 12.5 ms

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }

    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate the CRC checksums
int validate_data(uint8_t *data) {
    uint8_t temp_crc = crc8(data, 2);
    uint8_t hum_crc = crc8(data + 3, 2);

    if (temp_crc != data[2] || hum_crc != data[5]) {
        fprintf(stderr, "CRC check failed!\n");
        return -1;
    }

    return 0;
}

// Convert raw data to temperature and humidity
int convert_data(uint8_t *data, float *temperature, float *humidity) {
    uint16_t temp_raw = (data[0] << 8) | data[1];
    uint16_t hum_raw = (data[3] << 8) | data[4];

    *temperature = 175.0f * temp_raw / 65535.0f - 45.0f;
    *humidity = 100.0f * hum_raw / 65535.0f;

    return 0;
}

// Log data to file
int log_data(float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("shtc3_environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t data[6];
    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Validate data
            if (validate_data(data) == 0) {
                // Convert data
                if (convert_data(data, &temperature, &humidity) == 0) {
                    // Check for out-of-range values
                    if (temperature >= -40.0f && temperature <= 125.0f && humidity >= 0.0f && humidity <= 100.0f) {
                        // Log data
                        if (log_data(temperature, humidity) != 0) {
                            fprintf(stderr, "Failed to log data\n");
                        }

                        // Print data to stdout
                        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
                    } else {
                        fprintf(stderr, "Temperature or humidity out of range\n");
                    }
                } else {
                    fprintf(stderr, "Failed to convert data\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Close I2C handle and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

