#define SI7202_REG_TEMP 0x01
#define LOG_FILE "mag_temp_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(float *speed, float *temperature);
int log_data(float speed, float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    float speed;
    float temperature;
} sensor_data_t;

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "Error initializing I2C. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Speed (RPM),Temperature (C)\n");
    }
    rewind(log_file);

    float speed, temperature;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&speed, &temperature) != 0) {
            fprintf(stderr, "Error reading sensor data. Logging NaN values.\n");
            speed = NAN;
            temperature = NAN;
        }

        // Log data
        if (log_data(speed, temperature) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(float *speed, float *temperature) {
    char buf[4];
    int result;

    // Read speed data
    result = i2cReadI2CBlockData(i2c_handle, SI7202_REG_SPEED, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading speed data: %d\n", result);
        return 1;
    }
    int16_t raw_speed = (buf[0] << 8) | buf[1];
    *speed = (float)raw_speed; // Assuming raw value is RPM

    // Read temperature data
    result = i2cReadI2CBlockData(i2c_handle, SI7202_REG_TEMP, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return 1;
    }
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    *temperature = (float)raw_temp / 10.0; // Assuming raw value is * 10 degrees C

    return 0;
}

// Log data to file
int log_data(float speed, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, speed, temperature) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return 1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Ctrl+C pressed. Exiting.\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

