#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define FLOW_SCALE_FACTOR 0.01
#define TEMPERATURE_OFFSET 200.0
#define TEMPERATURE_SCALE_FACTOR 0.01
#define SAMPLE_DELAY_MS 1000 // 1 second
#define MAX_REINIT_ATTEMPTS 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float flow_slpm;
    float temperature_c;
} SensorData;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
SensorData process_sensor_data(const uint8_t *data);
int log_sensor_data(const SensorData *data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to process sensor data
SensorData process_sensor_data(const uint8_t *data) {
    SensorData sensor_data;
    // Extract flow data (14 bits)
    int16_t raw_flow = (data[0] << 8) | data[1];
    raw_flow = raw_flow >> 2; // Shift right by 2 bits to get 14-bit value
    sensor_data.flow_slpm = (float)raw_flow * FLOW_SCALE_FACTOR;

    // Extract temperature data (12 bits)
    int16_t raw_temperature = (data[2] << 8) | data[3];
    raw_temperature = raw_temperature >> 4; // Shift right by 4 bits to get 12-bit value
    sensor_data.temperature_c = ((float)raw_temperature * TEMPERATURE_SCALE_FACTOR) - TEMPERATURE_OFFSET;

    return sensor_data;
}

// Function to log sensor data
int log_sensor_data(const SensorData *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, data->flow_slpm, data->temperature_c);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    int reinit_attempts = 0;
    while (initialize_i2c() != 0 && reinit_attempts < MAX_REINIT_ATTEMPTS) {
        fprintf(stderr, "Attempting to re-initialize I2C... (%d/%d)\n", reinit_attempts + 1, MAX_REINIT_ATTEMPTS);
        reinit_attempts++;
        sleep(1); // Wait before re-initializing
    }

    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to initialize I2C after multiple attempts. Exiting.\n");
        cleanup();
        return 1;
    }

    uint8_t sensor_data[4];
    SensorData processed_data;
    int first_read = 1;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(sensor_data) == 0) {
            if (!first_read) {
                processed_data = process_sensor_data(sensor_data);
                log_sensor_data(&processed_data);
            } else {
                first_read = 0;
                printf("First read complete, discarding data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Attempting to re-initialize I2C.\n");
            i2cClose(i2c_handle);
            i2c_handle = -1; // Reset handle
            reinit_attempts = 0;
            while (initialize_i2c() != 0 && reinit_attempts < MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Attempting to re-initialize I2C... (%d/%d)\n", reinit_attempts + 1, MAX_REINIT_ATTEMPTS);
                reinit_attempts++;
                sleep(1); // Wait before re-initializing
            }
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        gpioDelay(SAMPLE_DELAY_MS); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

