#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SHT31-D I2C address
#define SHT31_ADDR 0x44

// Measurement command (High Repeatability, Clock Stretching Enabled)
#define MEASURE_CMD 0x2C06

// Global variables for I2C handle and log file
int i2c_handle = -1;
FILE *log_file = NULL;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT31-D
int read_sht31d(int i2c_handle, float *temperature, float *humidity) {
    uint8_t write_data[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t read_data[6];
    int result;

    // Send measurement command
    result = i2cWriteDevice(i2c_handle, (char *)write_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 15ms)
    gpioDelay(15000); // 15ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)read_data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // CRC validation
    if (crc8(read_data, 2) != read_data[2] || crc8(read_data + 3, 2) != read_data[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data to temperature and humidity
    uint16_t temperature_raw = (read_data[0] << 8) | read_data[1];
    uint16_t humidity_raw = (read_data[3] << 8) | read_data[4];

    *temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
    *humidity = 100.0 * (float)humidity_raw / 65535.0;

    return 0;
}

// Function to log data to file
int log_data(FILE *log_file, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Write data to log file
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

int main() {
    float temperature, humidity;
    int retries = 3; // Number of retries for I2C communication

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sht31d_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Retry I2C communication up to 3 times
        for (int i = 0; i < retries; i++) {
            if (read_sht31d(i2c_handle, &temperature, &humidity) == 0) {
                // Log data to file
                log_data(log_file, temperature, humidity);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d/%d)\n", i + 1, retries);
                gpioDelay(100000); // Wait 100ms before retrying
            }
        }

        if (i == retries) {
            fprintf(stderr, "I2C read failed after %d retries\n", retries);
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

