// Define the I2C address of the MLX90824 sensor
#define MLX90824_I2C_ADDR 0x40

// Define the register addresses for pressure and temperature data
#define PRESSURE_REG 0x00
#define TEMPERATURE_REG 0x02

// Define the size of the pressure and temperature data (in bytes)
#define PRESSURE_SIZE 2
#define TEMPERATURE_SIZE 2

// Global variables for I2C handle and log file
int i2c_handle = -1;
FILE *log_file = NULL;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close the I2C handle if it's open
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to read data from the MLX90824 sensor
int read_mlx90824(int i2c_handle, float *pressure, float *temperature) {
    char buffer[PRESSURE_SIZE + TEMPERATURE_SIZE];
    int result;

    // Read pressure data
    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buffer, PRESSURE_SIZE);
    if (result != PRESSURE_SIZE) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1;
    }

    // Read temperature data
    result = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, buffer + PRESSURE_SIZE, TEMPERATURE_SIZE);
    if (result != TEMPERATURE_SIZE) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }

    // Convert the raw data to pressure and temperature values
    // (Replace with actual conversion formulas from the datasheet)
    *pressure = (float)((buffer[0] << 8) | buffer[1]) / 10.0; // Example conversion
    *temperature = (float)((buffer[2] << 8) | buffer[3]) / 10.0; // Example conversion

    return 0;
}

// Function to log data to a file
void log_data(FILE *log_file, float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    // Get the current time
    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    // Format the timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Write the data to the log file
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    float pressure, temperature;
    int result;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(1, MLX90824_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read data from the sensor
        result = read_mlx90824(i2c_handle, &pressure, &temperature);
        if (result == 0) {
            // Log the data to the file
            log_data(log_file, pressure, temperature);
        } else {
            // Log the error to the file
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[30];

            // Get the current time
            time(&rawtime);
            timeinfo = gmtime(&rawtime);

            // Format the timestamp in ISO 8601 format
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            fprintf(log_file, "%s,Error reading sensor data\n", timestamp);
            fflush(log_file);
        }

        // Wait for 2 seconds
        sleep(2);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness in case the loop is ever modified.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

