    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from LM75B
float read_temperature() {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits
    float temperature = raw_temp * 0.125;

    return temperature;
}

// Update circular buffer
void update_circular_buffer(CircularBuffer *cb, float temp) {
    cb->buffer[cb->head] = temp;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate average temperature
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Control fan based on average temperature
void control_fan(float average_temp) {
    if (average_temp > TEMP_THRESHOLD_HIGH) {
        if (gpioWrite(FAN_GPIO, 1) != 0) {
            fprintf(stderr, "Error writing to GPIO %d\n", FAN_GPIO);
        }
    } else if (average_temp < TEMP_THRESHOLD_LOW) {
        if (gpioWrite(FAN_GPIO, 0) != 0) {
            fprintf(stderr, "Error writing to GPIO %d\n", FAN_GPIO);
        }
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Circular buffer
    CircularBuffer temp_buffer = {{0.0}, 0, 0};

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            update_circular_buffer(&temp_buffer, temperature);
            float average_temp = calculate_average(&temp_buffer);
            printf("Temperature: %.2f°C, Average: %.2f°C\n", temperature, average_temp);
            control_fan(average_temp);
        } else {
            fprintf(stderr, "Invalid temperature reading, skipping fan control\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

