    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    uint8_t sensor_data[9];
    sensor_data_t processed_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(sensor_data) == 0) {
            if (validate_crc(sensor_data, 9) == 0) {
                processed_data = process_sensor_data(sensor_data);
                log_data(processed_data);
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

