#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_ADDR 0x4A
#define LED_GPIO 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
double read_temperature();
void control_led(double temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x4A, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read temperature from STTS2004 sensor
double read_temperature() {
    char buf[2];
    int result;
    int retry = 0;

    while (retry < I2C_RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Success
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            double temperature = (double)raw_temp / 256.0;
            return temperature;
        } else {
            // Error
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retry + 1, result);
            retry++;
            usleep(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "I2C read failed after %d attempts. Exiting.\n", I2C_RETRY_COUNT);
    gpioTerminate();
    exit(1);
}

// Control LED based on temperature with hysteresis
void control_led(double temperature) {
    static int led_state = 0; // 0 = off, 1 = on

    if (temperature > TEMP_THRESHOLD_HIGH && led_state == 0) {
        gpioWrite(LED_GPIO, 1);
        led_state = 1;
        printf("Temperature above threshold, turning LED ON\n");
    } else if (temperature < TEMP_THRESHOLD_LOW && led_state == 1) {
        gpioWrite(LED_GPIO, 0);
        led_state = 0;
        printf("Temperature below threshold, turning LED OFF\n");
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        double temperature = read_temperature();
        printf("Temperature: %.2f °C\n", temperature);
        control_led(temperature);
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

