#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define MEASURE_COMMAND 0x362F
#define DATA_LENGTH 9
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define MEASUREMENT_DELAY_MS 45
#define FLOW_DATA_FILE "flow_data.txt"
#define ERROR_LOG_FILE "error.log"

// Global variables
int i2c_handle;
FILE *flow_data_fp = NULL;
FILE *error_log_fp = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t differential_pressure;
    int16_t temperature;
    uint8_t scale_factor[3];
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int validate_crc(uint8_t data[], uint8_t crc);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();
void log_error(const char *message);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[DATA_LENGTH];
    int result;

    // Send measurement command
    uint8_t command[2] = {(MEASURE_COMMAND >> 8) & 0xFF, MEASURE_COMMAND & 0xFF};
    result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (result != 0) {
        log_error("Failed to send measurement command");
        return -1;
    }

    // Wait for measurement to complete
    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Convert ms to us

    // Read data from sensor
    result = i2cReadDevice(i2c_handle, (char *)buffer, DATA_LENGTH);
    if (result != DATA_LENGTH) {
        log_error("Failed to read data from sensor");
        return -1;
    }

    // Validate CRC
    if (!validate_crc(buffer, buffer[2])) {
        log_error("Differential pressure CRC check failed");
        return -1;
    }
    if (!validate_crc(buffer + 3, buffer[5])) {
        log_error("Temperature CRC check failed");
        return -1;
    }

    // Extract data
    data->differential_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    memcpy(data->scale_factor, buffer + 6, 3);

    return 0;
}

// Validate CRC
int validate_crc(uint8_t data[], uint8_t crc) {
    return (crc8(data, 2) == crc);
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
