    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(flow_data_fp, "%s, %d, %d, %d, %d, %d\n",
            timestamp, data.differential_pressure, data.temperature,
            data.scale_factor[0], data.scale_factor[1], data.scale_factor[2]);
    fflush(flow_data_fp);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    if (flow_data_fp != NULL) {
        fclose(flow_data_fp);
    }
    if (error_log_fp != NULL) {
        fclose(error_log_fp);
    }
}

// Log errors to file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(error_log_fp, "%s, %s\n", timestamp, message);
    fflush(error_log_fp);
}

int main() {
    sensor_data_t sensor_data;
    int retries = 0;

    // Set up signal handler
