#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// HDC1080 I2C address
#define HDC1080_ADDR 0x40

// HDC1080 register addresses
#define HDC1080_TEMP_REG 0x00
#define HDC1080_HUMID_REG 0x01
#define HDC1080_CONFIG_REG 0x02

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the HDC1080 sensor
int init_hdc1080() {
    // Configure the sensor for temperature and humidity measurement
    // 14-bit temperature and humidity resolution, 1 Hz measurement rate
    uint16_t config_value = 0x0000; // Reset value
    char buf[3];
    buf[0] = HDC1080_CONFIG_REG;
    buf[1] = config_value & 0xFF;
    buf[2] = (config_value >> 8) & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read temperature and humidity data from the HDC1080
int read_hdc1080(sensor_data_t *data) {
    // Trigger measurement
    char trigger_buf[1] = {0x00};
    int result = i2cWriteDevice(i2c_handle, trigger_buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 20 ms)
    gpioDelay(25000); // 25 ms

    // Read temperature and humidity registers
    char read_buf[4];
    result = i2cReadDevice(i2c_handle, read_buf, 4);
    if (result != 0) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temperature = (read_buf[0] << 8) | read_buf[1];
    uint16_t raw_humidity = (read_buf[2] << 8) | read_buf[3];

    data->temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    data->humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

// Function to log data to a file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the HDC1080 sensor
    if (init_hdc1080() != 0) {
        fprintf(stderr, "HDC1080 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("enviro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;
    time_t last_log_time = 0;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_hdc1080(&sensor_data) == 0) {
            // Log data every 5 seconds
            time_t current_time = time(NULL);
            if (current_time - last_log_time >= 5) {
                log_data(sensor_data);
                last_log_time = current_time;
            }
        } else {
            fprintf(stderr, "Error reading sensor data, skipping log entry\n");
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

