#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define STS40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define CRC8_POLYNOMIAL 0x31
#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "temperature_log.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_temperature(uint16_t *raw_temperature);
uint8_t calculate_crc(uint8_t data[], int len);
float convert_to_celsius(uint16_t raw_temperature);
int log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int i2c_handle;
    FILE *log_file;
} ProgramState;

ProgramState state;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        uint16_t raw_temperature;
        float temperature;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue; // Continue to the next iteration
        }

        // Wait for conversion (10ms)
        gpioDelay(10000); // 10ms

        // Read temperature
        if (read_temperature(&raw_temperature) != 0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue; // Continue to the next iteration
        }

        // Convert to Celsius
        temperature = convert_to_celsius(raw_temperature);

        // Log temperature
        if (log_temperature(temperature) != 0) {
            fprintf(stderr, "Failed to log temperature\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Convert seconds to microseconds
    }

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Trigger measurement
int trigger_measurement() {
    int result = i2cWriteByteData(i2c_handle, 0x00, MEASURE_HIGH_PRECISION);
    if (result != 0) {
        fprintf(stderr, "Failed to write trigger command: %d\n", result);
        return 1;
    }
    return 0;
}

// Read temperature data
int read_temperature(uint16_t *raw_temperature) {
    char buf[3];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return 1;
    }

    // CRC check
    uint8_t crc = calculate_crc((uint8_t *)buf, 2);
    if (crc != buf[2]) {
        fprintf(stderr, "CRC check failed: calculated 0x%02X, received 0x%02X\n", crc, buf[2]);
        return 1;
    }

    *raw_temperature = (buf[0] << 8) | buf[1];
    return 0;
}

// Calculate CRC8
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw temperature to Celsius
float convert_to_celsius(uint16_t raw_temperature) {
    return -45.0 + (175.0 * (float)raw_temperature / 65535.0);
}

// Log temperature to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

