#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x3615
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_MS (1000 / SAMPLE_RATE_HZ)
#define LOG_FILE "hvac_pressure_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_Pa;
    float temperature_C;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
sensor_data_t process_data(const uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Trigger a measurement
int trigger_measurement() {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(const uint8_t *data, int len) {
    if (len != 9) {
        fprintf(stderr, "Invalid data length for CRC validation: %d\n", len);
        return -1;
    }

    uint8_t pressure_crc = data[2];
    uint8_t temperature_crc = data[5];

    if (crc8(data, 2) != pressure_crc) {
        fprintf(stderr, "Pressure CRC validation failed\n");
        return -1;
    }

    if (crc8(data + 3, 2) != temperature_crc) {
        fprintf(stderr, "Temperature CRC validation failed\n");
        return -1;
    }

    return 0;
}

// Process sensor data
sensor_data_t process_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t pressure_raw = (data[0] << 8) | data[1];
    int16_t temperature_raw = (data[3] << 8) | data[4];

    // Scale factors (from datasheet)
    float pressure_scale_factor = 0.1; // Example value, check datasheet
    float temperature_scale_factor = 0.1; // Example value, check datasheet

    sensor_data.pressure_Pa = (float)pressure_raw * pressure_scale_factor;
    sensor_data.temperature_C = (float)temperature_raw * temperature_scale_factor;

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure_Pa, data.temperature_C);
    fflush(log_file);

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed, exiting\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint8_t sensor_data[9];
    sensor_data_t processed_data;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Measurement trigger failed\n");
            continue; // Continue to the next iteration
        }

        // Wait for measurement to complete (at least 50ms)
        gpioDelay(50);

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Sensor data read failed\n");
            continue; // Continue to the next iteration
        }

        // Validate CRC
        if (validate_crc(sensor_data, 9) != 0) {
            fprintf(stderr, "CRC validation failed\n");
            continue; // Continue to the next iteration
        }

        // Process data
        processed_data = process_data(sensor_data);

        // Log data
        if (log_data(processed_data) != 0) {
            fprintf(stderr, "Data logging failed\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_PERIOD_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

