    sensor_data_t processed_data;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Measurement trigger failed\n");
            continue; // Continue to the next iteration
        }

        // Wait for measurement to complete (at least 50ms)
        gpioDelay(50);

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Sensor data read failed\n");
            continue; // Continue to the next iteration
        }

        // Validate CRC
        if (validate_crc(sensor_data, 9) != 0) {
            fprintf(stderr, "CRC validation failed\n");
            continue; // Continue to the next iteration
        }

        // Process data
        processed_data = process_data(sensor_data);

        // Log data
        if (log_data(processed_data) != 0) {
            fprintf(stderr, "Data logging failed\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_PERIOD_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

