#include <pthread.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// CRC-8 parameters
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold sensor data
typedef struct {
    time_t timestamp;
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t running = 1;

// Function prototypes
void signal_handler(int signal);
int init_i2c();
void close_i2c();
int start_periodic_measurement();
int read_measurement(uint16_t *co2, uint16_t *temperature, uint16_t *humidity);
int stop_periodic_measurement();
uint8_t crc8(const uint8_t *data, int len);
void buffer_init(circular_buffer_t *buffer);
int buffer_add(circular_buffer_t *buffer, sensor_data_t data);
int buffer_read(circular_buffer_t *buffer, sensor_data_t *data);
void *logging_thread(void *arg);
void log_error(const char *message);
void flush_buffer_to_csv();

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, stopping...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SCD40_ADDR, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Close I2C
void close_i2c() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

// Start periodic measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to start periodic measurement");
        return -1;
    }
    return 0;
}

// Read measurement
int read_measurement(uint16_t *co2, uint16_t *temperature, uint16_t *humidity) {
    char buf[2];
    buf[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_READ_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to send read measurement command");
        return -1;
    }

    gpioDelay(1); // Small delay before reading

    char data[9];
    result = i2cReadDevice(i2c_handle, data, 9);
    if (result != 9) {
        log_error("Failed to read measurement data");
        return -1;
    }

    // CRC check
    if (crc8((uint8_t *)data, 2) != data[2] ||
        crc8((uint8_t *)data + 3, 2) != data[5] ||
        crc8((uint8_t *)data + 6, 2) != data[8]) {
        log_error("CRC check failed");
        return -1;
    }

    *co2 = (data[0] << 8) | data[1];
    *temperature = (data[3] << 8) | data[4];
    *humidity = (data[6] << 8) | data[7];

    return 0;
}

// Stop periodic measurement
int stop_periodic_measurement() {
    char buf[2];
    buf[0] = (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to stop periodic measurement");
        return -1;
    }
    return 0;
}

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize circular buffer
void buffer_init(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

// Add data to circular buffer
int buffer_add(circular_buffer_t *buffer, sensor_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Read data from circular buffer
int buffer_read(circular_buffer_t *buffer, sensor_data_t *data) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count == 0) {
        pthread_mutex_unlock(&buffer->mutex);
        return -1; // Buffer is empty
    }
    *data = buffer->data[buffer->tail];
    buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    buffer->count--;
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Logging thread function
void *logging_thread(void *arg) {
    while (running) {
        sleep(60);
        flush_buffer_to_csv();
    }
    return NULL;
}

// Log error to file
void log_error(const char *message) {
    FILE *fp = fopen("/var/log/scd40_error.log", "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Flush buffer to CSV file
void flush_buffer_to_csv() {
    char filename[256];
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    sprintf(filename, "/var/log/scd40_data/scd40_%d%02d%02d_%02d%02d%02d.csv", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);

    // Create directory if it doesn't exist
    char dir[256];
    sprintf(dir, "/var/log/scd40_data/");
    struct stat st = {0};
    if (stat(dir, &st) == -1) {
        mkdir(dir, 0777);
    }

    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        log_error("Failed to open CSV file for writing");
        return;
    }

    fprintf(fp, "timestamp,co2,temperature,humidity\n");

    sensor_data_t data;
    while (buffer_read(&buffer, &data) == 0) {
        fprintf(fp, "%ld,%u,%u,%u\n", data.timestamp, data.co2, data.temperature, data.humidity);
    }

    fclose(fp);
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize circular buffer
    buffer_init(&buffer);

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        close_i2c();
        return 1;
    }

    // Create logging thread
    pthread_t logging_thread_id;
    if (pthread_create(&logging_thread_id, NULL, logging_thread, NULL) != 0) {
        log_error("Failed to create logging thread");
        stop_periodic_measurement();
        close_i2c();
        return 1;
    }

    // Main loop
    sleep(1); // Wait 1 second after starting periodic measurement
    while (running) {
        uint16_t co2, temperature, humidity;
        if (read_measurement(&co2, &temperature, &humidity) == 0) {
            sensor_data_t data;
            data.timestamp = time(NULL);
            data.co2 = co2;
            data.temperature = temperature;
            data.humidity = humidity;
            buffer_add(&buffer, data);
        }
        sleep(5); // Read every 5 seconds
    }

    // Stop periodic measurement
    if (stop_periodic_measurement() != 0) {
        log_error("Failed to stop periodic measurement during shutdown");
    }

    // Join logging thread
    pthread_join(logging_thread_id, NULL);

    // Flush remaining data to CSV
    flush_buffer_to_csv();

    // Close I2C
    close_i2c();

    return 0;
}

