#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ICP_10125_ADDR 0x69
#define GPIO_LED 17
#define PRESSURE_THRESHOLD 95000.0f
#define NORMAL_BLINK_RATE 1.0f
#define WARNING_BLINK_RATE 5.0f
#define DELAY_MS 20

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_sensor_data(uint8_t *data);
float calculate_pressure(uint8_t *data);
float calculate_temperature(uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int len);
int verify_crc(uint8_t *data);
void control_led(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t sensor_data[6];
        sensor_data_t sensor_values;

        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Verify CRC
            if (verify_crc(sensor_data)) {
                // Calculate pressure and temperature
                sensor_values.pressure = calculate_pressure(sensor_data);
                sensor_values.temperature = calculate_temperature(sensor_data);

                // Control LED based on pressure
                control_led(sensor_values.pressure);

                // Print sensor data
                printf("Pressure: %.2f Pa, Temperature: %.2f C\n", sensor_values.pressure, sensor_values.temperature);
            } else {
                fprintf(stderr, "CRC check failed.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Delay for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICP_10125_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Failed to read 6 bytes from I2C: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(DELAY_MS); // Delay after read
    return 0;
}

// Calculate pressure (example formula, adjust as needed)
float calculate_pressure(uint8_t *data) {
    // Assuming pressure data is in the first two bytes
    int16_t raw_pressure = (data[0] << 8) | data[1];
    // Apply calibration and conversion formula from the datasheet
    // This is a placeholder, replace with the actual formula
    return (float)raw_pressure; // Placeholder
}

// Calculate temperature (example formula, adjust as needed)
float calculate_temperature(uint8_t *data) {
    // Assuming temperature data is in the next two bytes
    int16_t raw_temperature = (data[2] << 8) | data[3];
    // Apply calibration and conversion formula from the datasheet
    // This is a placeholder, replace with the actual formula
    return (float)raw_temperature / 10.0f; // Placeholder
}

// Calculate CRC (example implementation, adjust as needed)
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31; // Polynomial X^8 + X^5 + X^4 + 1
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Verify CRC
int verify_crc(uint8_t *data) {
    uint8_t calculated_crc = calculate_crc(data, 4); // Calculate CRC for the first 4 bytes
    uint8_t received_crc = (data[4] << 8) | data[5]; // Assuming CRC is in the last two bytes

    return (calculated_crc == received_crc);
}

// Control LED based on pressure
void control_led(float pressure) {
    if (pressure < PRESSURE_THRESHOLD) {
        // 5 Hz blinking
        gpioWrite(GPIO_LED, 1);
        gpioDelay(100); // 100ms on
        gpioWrite(GPIO_LED, 0);
        gpioDelay(100); // 100ms off
    } else {
        // 1 Hz blinking
        gpioWrite(GPIO_LED, 1);
        gpioDelay(500); // 500ms on
        gpioWrite(GPIO_LED, 0);
        gpioDelay(500); // 500ms off
    }
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();
}

