#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define LOG_FILE "temperature_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int read_temperature(int reg);
float convert_to_celsius(int raw_temp);
int log_temperature(float ambient_temp, float object_temp);
int control_fan(float object_temp);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int mlx90614_address;
    int fan_gpio;
    float temp_threshold_high;
    float temp_threshold_low;
    char* log_file;
} config_t;

config_t config = {
    .i2c_bus = I2C_BUS,
    .mlx90614_address = MLX90614_ADDR,
    .fan_gpio = FAN_GPIO,
    .temp_threshold_high = TEMP_THRESHOLD_HIGH,
    .temp_threshold_low = TEMP_THRESHOLD_LOW,
    .log_file = LOG_FILE
};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperatures
        int ambient_raw = read_temperature(AMBIENT_TEMP_REG);
        int object_raw = read_temperature(OBJECT_TEMP_REG);

        // Convert to Celsius
        float ambient_temp = convert_to_celsius(ambient_raw);
        float object_temp = convert_to_celsius(object_raw);

        // Log temperature
        if (ambient_temp != -1000.0 && object_temp != -1000.0) {
            if (log_temperature(ambient_temp, object_temp) != 0) {
                fprintf(stderr, "Failed to log temperature.\n");
            }
        } else {
            fprintf(stderr, "Invalid temperature reading. Skipping logging.\n");
        }

        // Control fan
        if (control_fan(object_temp) != 0) {
            fprintf(stderr, "Failed to control fan.\n");
        }

        // Wait 2 seconds
        gpioDelay(2000); // pigpio's replacement for time_sleep
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(config.i2c_bus, config.mlx90614_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read temperature from sensor
int read_temperature(int reg) {
    int raw_temp = -1;
    for (int i = 0; i < RETRY_COUNT; ++i) {
        raw_temp = i2cReadWordData(i2c_handle, reg);
        if (raw_temp >= 0) {
            // Success
            return raw_temp;
        } else {
            fprintf(stderr, "I2C read failed (reg 0x%02X, attempt %d): %d\n", reg, i + 1, raw_temp);
            gpioDelay(RETRY_DELAY_MS); // Delay in milliseconds
        }
    }
    fprintf(stderr, "Failed to read temperature from register 0x%02X after %d retries.\n", reg, RETRY_COUNT);
    return -1; // Indicate failure
}

// Convert raw temperature to Celsius
float convert_to_celsius(int raw_temp) {
    if (raw_temp < 0) return -1000.0; // Indicate error
    return (float)raw_temp * 0.02 - 273.15;
}

// Log temperature to file
int log_temperature(float ambient_temp, float object_temp) {
    FILE *fp = fopen(config.log_file, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Ambient: %.2f C, Object: %.2f C\n", timestamp, ambient_temp, object_temp);
    fclose(fp);
    return 0;
}

// Control fan with hysteresis
int control_fan(float object_temp) {
    static int fan_on = 0; // Track fan state

    if (object_temp > config.temp_threshold_high && !fan_on) {
        gpioWrite(config.fan_gpio, 1); // Turn on fan
        fan_on = 1;
        printf("Fan turned ON (Object Temp: %.2f C)\n", object_temp);
    } else if (object_temp < config.temp_threshold_low && fan_on) {
        gpioWrite(config.fan_gpio, 0); // Turn off fan
        fan_on = 0;
        printf("Fan turned OFF (Object Temp: %.2f C)\n", object_temp);
    }
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

