            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(10000); // Wait for at least 10ms

        result = i2cReadDevice(i2c_handle, buf, 6);
        if (result == 6) {
            // Success, process the data
            unsigned short raw_temp = (buf[0] << 8) | buf[1];
            unsigned short raw_humidity = (buf[3] << 8) | buf[4];

            data->temperature = convert_temperature(raw_temp);
            data->humidity = convert_humidity(raw_humidity);

            // Clamp humidity to 0-100%
            if (data->humidity < 0.0) data->humidity = 0.0;
            if (data->humidity > 100.0) data->humidity = 100.0;

            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C: %d\n", result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to convert raw temperature data to Celsius
float convert_temperature(unsigned short raw_temp) {
    return -45.0 + 175.0 * (float)raw_temp / 65535.0;
}

// Function to convert raw humidity data to percentage
float convert_humidity(unsigned short raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Function to handle client connection
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    SensorData sensor_data;
    char html_response[512];

    // Read sensor data
    if (read_sht40(&sensor_data) != 0) {
        fprintf(stderr, "Failed to read sensor data.\n");
        const char *error_message = "Error reading sensor data";
        send(client_socket, error_message, strlen(error_message), 0);
        close(client_socket);
        return;
    }

    // Create HTML response
    snprintf(html_response, sizeof(html_response), 
             "Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);

    // Send HTML response to client
    send(client_socket, html_response, strlen(html_response), 0);

    // Close client socket
    close(client_socket);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("Socket creation failed");
        cleanup();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        cleanup();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    // Main loop
    while (1) {
        // Accept connection
        int client_socket;
        struct sockaddr_in client_address;
        int addrlen = sizeof(client_address);

        client_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&addrlen);
        if (client_socket < 0) {
            perror("Accept failed");
            cleanup();
            return 1;
        }

        // Handle client connection
        handle_client(client_socket);
    }

    return 0;
}

