#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define MEASUREMENT_CONFIG 0x0E
#define TEMP_MSB 0x00
#define HUMID_MSB 0x02

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// I2C handle
int i2c_handle;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the HDC2010 sensor
int init_hdc2010() {
    // Configure the sensor for temperature and humidity measurement
    // Continuous mode, 1 Hz, 14-bit resolution
    uint8_t config_data[2] = {0x00, 0x00}; // Reset and configure
    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to MEASUREMENT_CONFIG register: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Small delay after writing config

    return 0;
}

// Function to read temperature and humidity data from the HDC2010
int read_hdc2010(float *temperature, float *humidity) {
    uint8_t data[4];
    int result;

    // Read temperature and humidity data
    result = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading temperature and humidity data: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature and humidity
    int temp_raw = (data[0] << 8) | data[1];
    int humid_raw = (data[2] << 8) | data[3];

    *temperature = ((float)temp_raw / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)humid_raw / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the HDC2010 sensor
    if (init_hdc2010() != 0) {
        fprintf(stderr, "HDC2010 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;
    time_t last_output_time = 0;

    // Main loop
    while (!terminate) {
        // Read temperature and humidity
        if (read_hdc2010(&temperature, &humidity) == 0) {
            // Get current time
            time_t current_time = time(NULL);

            // Output data every 5 seconds
            if (difftime(current_time, last_output_time) >= 5.0) {
                printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
                last_output_time = current_time;
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

