#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0  // CE0
#define SPI_SPEED 500000 // 500 kHz
#define SSR_GPIO 17      // BCM numbering
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// PID Gains
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Global Variables
int spi_handle;
FILE *log_file;
FILE *profile_file;
double target_temperature = 0.0;
double last_error = 0.0;
double integral = 0.0;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int initialize();
double read_temperature();
double calculate_pid(double current_temperature);
void control_ssr(double pid_output);
void log_data(double temperature, double target_temperature, double pid_output);
void load_profile();
void signal_handler(int signal);
void cleanup();

// Structure for PID parameters
typedef struct {
    double Kp;
    double Ki;
    double Kd;
} PIDParams;

PIDParams pid_params = {Kp, Ki, Kd};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    load_profile();

    while (!terminate) {
        double current_temperature = read_temperature();
        if (current_temperature < -1000) {
            fprintf(stderr, "Error reading temperature. Check thermocouple connection.\n");
            log_data(current_temperature, target_temperature, -1.0); // Log error
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double pid_output = calculate_pid(current_temperature);
        control_ssr(pid_output);
        log_data(current_temperature, target_temperature, pid_output);

        // Check if we need to update the target temperature from the profile
        if (profile_file != NULL) {
            // Simple profile update logic (replace with a more robust implementation)
            // This example assumes the profile file is small and can be read quickly.
            // A more robust implementation would involve parsing the file line by line
            // and keeping track of the current line.
            // For simplicity, we'll just reload the file each time.
            fclose(profile_file);
            profile_file = fopen(PROFILE_FILE, "r");
            if (profile_file == NULL) {
                fprintf(stderr, "Error opening profile file. Using previous target temperature.\n");
            } else {
                // Read the first line (assuming it's the current target)
                char line[256];
                if (fgets(line, sizeof(line), profile_file) != NULL) {
                    if (sscanf(line, "%lf,%lf", &target_temperature, &target_temperature) == 2) {
                        // Successfully read the target temperature
                    } else {
                        fprintf(stderr, "Error parsing profile file. Using previous target temperature.\n");
                    }
                } else {
                    fprintf(stderr, "Profile file is empty. Using previous target temperature.\n");
                }
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SSR_GPIO, PI_OUTPUT);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    profile_file = fopen(PROFILE_FILE, "r");
    if (profile_file == NULL) {
        fprintf(stderr, "Failed to open profile file. Using default target temperature.\n");
        target_temperature = 25.0; // Default temperature
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

double read_temperature() {
    unsigned char data[2];
    int result = spiRead(spi_handle, data, 2);

    if (result != 2) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return -2000.0; // Indicate error
    }

    // MAX6675 returns data in the format: [MSB][LSB][0][0]
    // The temperature is in the first 14 bits.
    int raw = (data[0] << 8) | data[1];
    raw >>= 3; // Remove the 3 status bits

    if (raw & 0x04) {
        fprintf(stderr, "Thermocouple not connected\n");
        return -3000.0; // Indicate no thermocouple
    }

    double temperature = raw * 0.25;
    return temperature;
}

double calculate_pid(double current_temperature) {
    double error = target_temperature - current_temperature;

    integral += error;
    double derivative = error - last_error;

    double output = pid_params.Kp * error + pid_params.Ki * integral + pid_params.Kd * derivative;

    last_error = error;

    // Clamp the output to the range [0, 1]
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

void control_ssr(double pid_output) {
    // Use PWM to control the SSR duty cycle
    int duty_cycle = (int)(pid_output * 1000000.0); // Convert to microseconds
    gpioPWM(SSR_GPIO, duty_cycle);
}

void log_data(double temperature, double target_temperature, double pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, target_temperature, pid_output);
    fflush(log_file); // Ensure data is written to disk immediately
}

void load_profile() {
    // This function is intentionally left empty because the profile is loaded
    // in the main loop to allow for dynamic updates.
    // The profile file is read each time through the loop.
}

void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (profile_file != NULL) {
        fclose(profile_file);
    }
    gpioWrite(SSR_GPIO, 0); // Turn off SSR
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

