#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define DS18B20_ADDR "28-0314a6e6e3ff" // Replace with your sensor's address
#define DS18B20_PATH "/sys/bus/w1/devices/" DS18B20_ADDR "/w1_slave"
#define HEATER_GPIO 17
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000000   // 0-100% duty cycle
#define LOG_FILE "greenhouse.log"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
double setpoint = 25.0; // Default setpoint
double Kp = 1.0;       // Default Kp
double Ki = 0.1;       // Default Ki
double Kd = 0.01;      // Default Kd
double integral = 0.0;
double previous_error = 0.0;
FILE *log_file = NULL;
int running = 1;

// Function prototypes
double read_temperature();
double calculate_pid(double temperature);
void set_pwm_duty_cycle(double pid_output);
void log_data(double temperature, double pid_output, double duty_cycle);
void signal_handler(int signal);
int validate_crc(const char *data);

// Function to read temperature from DS18B20 sensor
double read_temperature() {
    FILE *fp;
    char buffer[256];
    double temperature = -1000.0; // Initialize to an invalid value
    int crc_valid = 0;

    fp = fopen(DS18B20_PATH, "r");
    if (fp == NULL) {
        perror("Error opening DS18B20 file");
        return -1000.0; // Indicate error
    }

    // Read the file twice to get the temperature
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fclose(fp);
        return -1000.0;
    }
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fclose(fp);
        return -1000.0;
    }

    fclose(fp);

    // Check for CRC error
    if (strstr(buffer, "YES") != NULL) {
        crc_valid = 1;
    }

    if (crc_valid) {
        char *token = strstr(buffer, "t=");
        if (token != NULL) {
            temperature = atof(token + 2) / 1000.0;
        }
    } else {
        fprintf(stderr, "CRC check failed. Temperature reading discarded.\n");
        return -1000.0; // Indicate error
    }

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double temperature) {
    double error = setpoint - temperature;
    integral += error * SAMPLE_INTERVAL;
    double derivative = (error - previous_error) / SAMPLE_INTERVAL;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(double pid_output) {
    int duty_cycle = (int)(pid_output * PWM_RANGE / 100.0); // Scale PID output to duty cycle

    // Clamp duty cycle to 0-100%
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > PWM_RANGE) {
        duty_cycle = PWM_RANGE;
    }

    gpioPWM(PWM_GPIO, duty_cycle / 10000); // pigpio takes values 0-255

    // Relay control (simple on/off based on PID output)
    if (pid_output > 0) {
        gpioWrite(HEATER_GPIO, 1); // Turn on heater
    } else {
        gpioWrite(HEATER_GPIO, 0); // Turn off heater
    }
}

// Function to log data to file
void log_data(double temperature, double pid_output, double duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, temperature, setpoint, pid_output, duty_cycle);
    fflush(log_file); // Ensure data is written to disk
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    setpoint = atof(argv[1]);
    Kp = atof(argv[2]);
    Ki = atof(argv[3]);
    Kd = atof(argv[4]);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Greenhouse controller started. Setpoint: %.2f, Kp: %.2f, Ki: %.2f, Kd: %.2f\n", setpoint, Kp, Ki, Kd);

    // Main loop
    while (running) {
        double temperature = read_temperature();
        if (temperature > -999.0) { // Valid temperature reading
            double pid_output = calculate_pid(temperature);
            set_pwm_duty_cycle(pid_output);
            log_data(temperature, pid_output, pid_output * 100.0); // Log PID output as duty cycle percentage
        } else {
            fprintf(stderr, "Error reading temperature. Check sensor connection.\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(HEATER_GPIO, 0); // Turn off heater
    gpioPWM(PWM_GPIO, 0);      // Set PWM to 0
    fclose(log_file);
    gpioTerminate();

    return 0;
}

