#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define DEHUMIDIFIER_GPIO 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASUREMENT_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_aht20();
int read_aht20(float *humidity);
void control_dehumidifier(float humidity);
void signal_handler(int signal);
void log_error(const char *message);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize AHT20 sensor
int init_aht20() {
    char init_cmd[3] = {0xBE, 0x08, 0x00};
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, init_cmd, 3);
        if (result == 0) {
            return 0; // Success
        } else {
            log_error("Failed to initialize AHT20, retrying...");
            gpioDelay(10000); // 10 ms
            retries--;
        }
    }

    log_error("Failed to initialize AHT20 after multiple retries.");
    return -1; // Failure
}

// Read humidity from AHT20 sensor
int read_aht20(float *humidity) {
    char measure_cmd[1] = {0xAC};
    char data[6];
    int retries = 3;
    int result;

    while (retries > 0) {
        // Trigger measurement
        result = i2cWriteDevice(i2c_handle, measure_cmd, 1);
        if (result != 0) {
            log_error("Failed to trigger measurement, retrying...");
            gpioDelay(10000); // 10 ms
            retries--;
            continue;
        }

        gpioDelay(80000); // 80 ms

        // Read 6 bytes of data
        result = i2cReadDevice(i2c_handle, data, 6);
        if (result != 6) {
            log_error("Failed to read data, retrying...");
            gpioDelay(10000); // 10 ms
            retries--;
            continue;
        }

        // Verify status byte
        if ((data[0] & 0x80) != 0) {
            log_error("AHT20 busy, retrying...");
            gpioDelay(10000); // 10 ms
            retries--;
            continue;
        }

        // Calculate humidity
        uint32_t humidity_raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
        *humidity = ((float)humidity_raw / 0x100000) * 100;

        return 0; // Success
    }

    log_error("Failed to read humidity after multiple retries.");
    return -1; // Failure
}

// Control dehumidifier based on humidity
void control_dehumidifier(float humidity) {
    static int dehumidifier_on = 0;

    if (humidity > HUMIDITY_THRESHOLD_HIGH && !dehumidifier_on) {
        gpioWrite(DEHUMIDIFIER_GPIO, 1); // Turn on dehumidifier
        dehumidifier_on = 1;
        printf("Dehumidifier ON\n");
    } else if (humidity < HUMIDITY_THRESHOLD_LOW && dehumidifier_on) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
        dehumidifier_on = 0;
        printf("Dehumidifier OFF\n");
    }
}

// Log error messages to stderr
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    if (init_aht20() != 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT);
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Initially off

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float humidity;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Main loop
    while (!terminate) {
        if (read_aht20(&humidity) == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log humidity reading with timestamp
            printf("[%s] Humidity: %.2f%%\n", timestamp, humidity);

            // Control dehumidifier
            control_dehumidifier(humidity);
        } else {
            log_error("Failed to read humidity.");
        }

        gpioDelay(MEASUREMENT_INTERVAL * 1000000); // Sleep for 5 seconds
    }

    // Cleanup
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

