#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// HTU21D I2C address
#define HTU21D_ADDR 0x40

// HTU21D commands
#define TRIGGER_TEMP_MEASURE 0xE3
#define TRIGGER_HUMIDITY_MEASURE 0xE5

// API endpoint
#define API_ENDPOINT "api.example.com"
#define API_PORT 80
#define API_PATH "/humidity"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_humidity(float *humidity);
int crc8(const unsigned char *data, int len);
int send_data(float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float humidity;
    time_t timestamp;
} sensor_data_t;

int main() {
    // Initialize syslog
    openlog("humidity_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        syslog(LOG_ERR, "Failed to initialize I2C. Exiting.");
        closelog();
        return 1;
    }

    float humidity;
    // Main loop
    while (!terminate) {
        // Read humidity
        if (read_humidity(&humidity) == 0) {
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);

            // Send data to API
            if (send_data(humidity) != 0) {
                syslog(LOG_ERR, "Failed to send data to API.");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity.");
        }

        // Wait 60 seconds
        sleep(60);
    }

    // Cleanup
    cleanup();

    // Close syslog
    closelog();

    return 0;
}

// Initialize I2C
int init_i2c() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HTU21D_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %d", i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read humidity from HTU21D
int read_humidity(float *humidity) {
    unsigned char data[3];
    int result;

    // Trigger humidity measurement
    result = i2cWriteByte(i2c_handle, TRIGGER_HUMIDITY_MEASURE);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to trigger humidity measurement: %d", result);
        return 1;
    }

    // Wait for measurement to complete (at least 50ms)
    gpioDelay(50000);

    // Read 3 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (result != 3) {
        syslog(LOG_ERR, "Failed to read humidity data: %d", result);
        return 1;
    }

    // CRC check
    if (crc8(data, 2) != data[2]) {
        syslog(LOG_ERR, "CRC check failed");
        return 1;
    }

    // Convert data to humidity
    unsigned int raw_humidity = (data[0] << 8) | data[1];
    *humidity = (float)raw_humidity * 125.0 / 65536.0 - 6.0;

    return 0;
}

// CRC-8 checksum calculation
int crc8(const unsigned char *data, int len) {
    unsigned char crc = 0x00;
    for (int i = 0; i < len; i++) {
        unsigned char byte = data[i];
        for (int j = 0; j < 8; j++) {
            unsigned char lsb = crc ^ byte & 0x01;
            crc >>= 1;
            if (lsb) {
                crc ^= 0x131; // Polynomial X^8 + X^5 + X^4 + 1
            }
            byte >>= 1;
        }
    }
    return crc;
}

// Send data to API
int send_data(float humidity) {
    int sock = 0;
    struct sockaddr_in serv_addr;
    char json_data[100];
    char buffer[1024] = {0};

    // Create JSON data
    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    // Create socket
    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        syslog(LOG_ERR, "Socket creation error");
        return 1;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(API_PORT);

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, API_ENDPOINT, &serv_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        close(sock);
        return 1;
    }

    // Connect to server
    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        syslog(LOG_ERR, "Connection Failed");
        close(sock);
        return 1;
    }

    // Send data
    if (send(sock, json_data, strlen(json_data), 0) < 0) {
        syslog(LOG_ERR, "Send failed");
        close(sock);
        return 1;
    }

    // Receive response (optional)
    ssize_t valread = recv(sock, buffer, sizeof(buffer) - 1, 0);
    if (valread > 0) {
        buffer[valread] = '\0';
        syslog(LOG_INFO, "Received: %s", buffer);
    }

    // Close socket
    close(sock);

    return 0;
}

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d. Terminating...", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

