#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define I2C_BUS 1
#define LOG_FILE_PATH "/home/pi/sensor_data/"
#define MAX_RETRIES 3
#define BACKOFF_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_tmp117(float *temperature);
int read_aht20(float *humidity);
int read_pir();
int log_data(float temperature, float humidity, int motion_detected);
void create_log_file();
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
    int motion_detected;
} sensor_data_t;

int main() {
    sensor_data_t sensor_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PIR GPIO as input
    gpioSetMode(PIR_GPIO, PI_INPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create the log file
    create_log_file();

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_tmp117(&sensor_data.temperature) != 0) {
            fprintf(stderr, "Failed to read temperature\n");
            sensor_data.temperature = -999.0; // Indicate error
        }
        if (read_aht20(&sensor_data.humidity) != 0) {
            fprintf(stderr, "Failed to read humidity\n");
            sensor_data.humidity = -999.0; // Indicate error
        }
        sensor_data.motion_detected = read_pir();

        // Log data
        if (log_data(sensor_data.temperature, sensor_data.humidity, sensor_data.motion_detected) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0); // Open with TMP117 address first
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device (TMP117): %s\n", strerror(errno));
        i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0); // Try AHT20
        if (i2c_handle < 0) {
            fprintf(stderr, "Failed to open I2C device (AHT20): %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

// Read temperature from TMP117
int read_tmp117(float *temperature) {
    char buf[2];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        bytes_read = i2cReadDevice(i2c_handle, buf, 2);
        if (bytes_read == 2) {
            // Success
            int raw_temp = (buf[0] << 8) | buf[1];
            *temperature = raw_temp * 0.0078125;
            return 0;
        } else {
            fprintf(stderr, "I2C read failed (TMP117), retry %d: %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(BACKOFF_DELAY_MS * (1 << retries) * 1000); // Exponential backoff
        }
    }
    return -1; // All retries failed
}

// Read humidity from AHT20
int read_aht20(float *humidity) {
    char buf[6];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        bytes_read = i2cReadDevice(i2c_handle, buf, 6);
        if (bytes_read == 6) {
            // Success
            // Check status bits (bits 7 and 6 of byte 0)
            if ((buf[0] & 0xC0) != 0) {
                fprintf(stderr, "AHT20 busy or calibration needed\n");
                return -1;
            }

            // Convert data
            unsigned long humidity_data = ((unsigned long)buf[1] << 12) | ((unsigned long)buf[2] << 4) | ((unsigned long)buf[3] >> 4);
            *humidity = ((float)humidity_data / 0x100000) * 100;
            return 0;
        } else {
            fprintf(stderr, "I2C read failed (AHT20), retry %d: %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(BACKOFF_DELAY_MS * (1 << retries) * 1000); // Exponential backoff
        }
    }
    return -1; // All retries failed
}

// Read motion from PIR sensor
int read_pir() {
    return gpioRead(PIR_GPIO);
}

// Log data to CSV file
int log_data(float temperature, float humidity, int motion_detected) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Create a new log file at midnight
void create_log_file() {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[50];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, sizeof(filename), LOG_FILE_PATH "%Y-%m-%d.csv", timeinfo);

    // Check if it's a new day
    static char last_filename[50] = {0};
    if (strcmp(filename, last_filename) != 0) {
        if (log_file != NULL) {
            fclose(log_file);
        }
        log_file = fopen(filename, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            return;
        }

        // Write header if the file is new
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
        }

        strcpy(last_filename, filename);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
