        if (read_rain_sensor() == 0) {
            log_message("Rain detected!");
            open_window();
        }
        gpioDelay(2000000); // 2 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    return 0;
}

