#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <wiringPi.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM range
#define PWM_RANGE 1024

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Turn off the LED
    pwmWrite(RED_PIN, PWM_RANGE);   // Full off for common anode
    pwmWrite(GREEN_PIN, PWM_RANGE);
    pwmWrite(BLUE_PIN, PWM_RANGE);

    // Clean up and exit
    exit(0);
}

// Function to read CPU load from /proc/stat
float read_cpu_load() {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    float cpu_usage;

    // Read initial CPU stats
    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1.0; // Indicate error
    }
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        fclose(fp);
        fprintf(stderr, "Error reading /proc/stat\n");
        return -1.0; // Indicate error
    }
    fclose(fp);

    // Wait for 500ms
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 500000000; // 500ms
    nanosleep(&ts, NULL);

    // Read CPU stats again
    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1.0; // Indicate error
    }
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fclose(fp);
        fprintf(stderr, "Error reading /proc/stat\n");
        return -1.0; // Indicate error
    }
    fclose(fp);

    // Calculate CPU usage
    unsigned long long prev_idle_all = prev_idle + prev_iowait;
    unsigned long long idle_all = idle + iowait;

    unsigned long long prev_non_idle = prev_user + prev_nice + prev_system + prev_irq + prev_softirq + prev_steal;
    unsigned long long non_idle = user + nice + system + irq + softirq + steal;

    unsigned long long prev_total = prev_idle_all + prev_non_idle;
    unsigned long long total = idle_all + non_idle;

    unsigned long long totald = total - prev_total;
    unsigned long long idled = idle_all - prev_idle_all;

    cpu_usage = (float)(totald - idled) / totald;

    return cpu_usage * 100.0; // Return as percentage
}

// Function to map CPU load to RGB color values
void map_load_to_color(float cpu_load, int *red, int *green, int *blue) {
    if (cpu_load < 0.0 || cpu_load > 100.0) {
        fprintf(stderr, "Invalid CPU load value: %.2f\n", cpu_load);
        *red = 0;   // Green
        *green = 255;
        *blue = 0;
        return;
    }

    if (cpu_load <= 50.0) {
        // Green to Yellow gradient
        *red = (int)((cpu_load / 50.0) * 255.0);
        *green = 255;
        *blue = 0;
    } else {
        // Yellow to Red gradient
        *red = 255;
        *green = 255 - (int)(((cpu_load - 50.0) / 50.0) * 255.0);
        *blue = 0;
    }
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    pwmWrite(RED_PIN, PWM_RANGE - (red * PWM_RANGE / 255)); // Common anode
    pwmWrite(GREEN_PIN, PWM_RANGE - (green * PWM_RANGE / 255));
    pwmWrite(BLUE_PIN, PWM_RANGE - (blue * PWM_RANGE / 255));
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins to PWM output mode
    pinMode(RED_PIN, PWM_OUTPUT);
    pinMode(GREEN_PIN, PWM_OUTPUT);
    pinMode(BLUE_PIN, PWM_OUTPUT);

    // Set PWM range
    pwmSetRange(PWM_RANGE);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("CPU Load Monitor started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read CPU load
        float cpu_load = read_cpu_load();
        if (cpu_load < 0.0) {
            fprintf(stderr, "Error reading CPU load, using default color.\n");
            set_led_color(0, 255, 0); // Default to green
        } else {
            // Map CPU load to color
            int red, green, blue;
            map_load_to_color(cpu_load, &red, &green, &blue);

            // Set LED color
            set_led_color(red, green, blue);

            printf("CPU Load: %.2f%%, RGB: (%d, %d, %d)\n", cpu_load, red, green, blue);
        }

        // Wait for 500ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 500000000; // 500ms
        nanosleep(&ts, NULL);
    }

    return 0;
}

