    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// BMP280 initialization function
int init_bmp280() {
    // Set the sensor to forced mode and configure oversampling
    char config_data[2];
    config_data[0] = BMP280_REG_CTRL_MEAS;
    config_data[1] = 0b00110111; // Oversampling x16, forced mode

    if (i2cWriteDevice(i2c_handle, config_data, 2) != 0) {
        fprintf(stderr, "Failed to write to CTRL_MEAS register\n");
        return -1;
    }

    config_data[0] = BMP280_REG_CONFIG;
    config_data[1] = 0b00010000; // t_sb = 0.5ms

    if (i2cWriteDevice(i2c_handle, config_data, 2) != 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        return -1;
