    var2 = p * ((double)dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)dig_P7)) / 16.0;

    return p;
}

// Format data into JSON string
char *format_json(double temperature, double pressure) {
    char *json_string = (char *)malloc(100 * sizeof(char));
    if (json_string == NULL) {
        fprintf(stderr, "Failed to allocate memory for JSON string\n");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\": %.2f, \"pressure\": %.2f}", temperature, pressure);
    return json_string;
}

// Send UDP packet
int send_udp_packet(const char *json_string) {
    if (sendto(udp_socket, json_string, strlen(json_string), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Failed to send UDP packet\n");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize BMP280 sensor
    if (init_bmp280() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() < 0) {
