        gpioTerminate();
        return 1;
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Failed to create UDP socket\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(5000);
    if (inet_pton(AF_INET, "192.168.1.100", &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported \n");
        close(udp_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_temperature, raw_pressure;
        double temperature, pressure;
        char *json_string;

        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) < 0) {
            fprintf(stderr, "Failed to read raw data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature);
        pressure = compensate_pressure(raw_pressure, temperature);

        // Format data into JSON string
        json_string = format_json(temperature, pressure);
        if (json_string == NULL) {
            fprintf(stderr, "Failed to format JSON string, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Send UDP packet
        if (send_udp_packet(json_string) < 0) {
            fprintf(stderr, "Failed to send UDP packet, retrying...\n");
        }

        free(json_string);

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup
    close(udp_socket);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
