#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 255
#define BUFFER_SIZE 20

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer entries
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} buffer_entry_t;

// Circular buffer
buffer_entry_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize();
int read_max31855(float *temperature);
int calculate_duty_cycle(float temperature);
int set_fan_speed(int duty_cycle);
void store_data(float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read temperature from MAX31855
int read_max31855(float *temperature) {
    unsigned char data[4];
    int result = spiRead(spi_handle, data, 4);

    if (result != 4) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return 1;
    }

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: %02X %02X %02X %02X\n", data[0], data[1], data[2], data[3]);
        return 1;
    }

    // Extract temperature data (ignoring the fault bit)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2; // Shift right by 2 to remove fault bit
    *temperature = (float)raw_temp * 0.25;

    return 0;
}

// Function to calculate the PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle = 0;

    if (temperature < 25.0) {
        duty_cycle = 0;
    } else if (temperature < 40.0) {
        duty_cycle = (int)((temperature - 25.0) / 15.0 * 50.0);
    } else if (temperature < 60.0) {
        duty_cycle = 50 + (int)((temperature - 40.0) / 20.0 * 150.0);
    } else {
        duty_cycle = 255;
    }

    return duty_cycle;
}

// Function to set the fan speed using PWM
int set_fan_speed(int duty_cycle) {
    gpioPWM(PWM_GPIO, duty_cycle);
    return 0;
}

// Function to store data in the circular buffer
void store_data(float temperature, int duty_cycle) {
    circular_buffer[buffer_index].timestamp = time(NULL);
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].duty_cycle = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Circular Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        struct tm *timeinfo = localtime(&circular_buffer[i].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("[%d] Timestamp: %s, Temperature: %.2f, Duty Cycle: %d\n",
               i, timestamp_str, circular_buffer[i].temperature, circular_buffer[i].duty_cycle);
    }
    printf("--- End of Buffer ---\n\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function to stop PWM, close SPI, and terminate pigpio
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(PWM_GPIO, 0); // Stop the fan
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    float temperature;
    int duty_cycle;

    printf("Temperature-controlled fan started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read temperature
        if (read_max31855(&temperature) == 0) {
            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(temperature);

            // Set fan speed
            set_fan_speed(duty_cycle);

            // Store data
            store_data(temperature, duty_cycle);

            printf("Temperature: %.2f°C, Duty Cycle: %d\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping fan update.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Print the circular buffer
    print_buffer();

    // Cleanup and exit
    cleanup();
