#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 // Oss = 0
#define BMP180_CMD_PRESSURE1 0x74 // Oss = 1
#define BMP180_CMD_PRESSURE2 0xB4 // Oss = 2
#define BMP180_CMD_PRESSURE3 0xF4 // Oss = 3

// GPIO pin for alert
#define ALERT_GPIO 24

// Rolling average window size (60 seconds * 20 Hz = 1200 samples)
#define ROLLING_AVG_SIZE 1200

// Sampling rate (20 Hz)
#define SAMPLING_RATE 20 // Hz

// Timer interval (50 ms)
#define TIMER_INTERVAL 50 // ms

// Pressure deviation threshold (5 hPa)
#define PRESSURE_THRESHOLD 5.0 // hPa

// Calibration data structure
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Circular buffer entry
typedef struct {
    time_t timestamp;
    float pressure;
} circular_buffer_entry_t;

// Global variables
int i2c_handle;
bmp180_calibration_data_t calibration_data;
circular_buffer_entry_t rolling_avg_buffer[ROLLING_AVG_SIZE];
int buffer_index = 0;
bool running = true;

// Function prototypes
int init_i2c();
int read_calibration_data(bmp180_calibration_data_t *calibration_data);
int read_raw_temperature(int32_t *raw_temperature);
int read_raw_pressure(int oss, int32_t *raw_pressure);
float calculate_pressure(int32_t raw_temperature, int32_t raw_pressure, const bmp180_calibration_data_t *calibration_data);
void add_to_circular_buffer(float pressure);
float calculate_rolling_average();
void check_pressure_deviation(float current_pressure, float rolling_average);
void timer_callback();
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // I2C bus 1, BMP180 address
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data(bmp180_calibration_data_t *calibration_data) {
    uint8_t data[22];
    if (i2cReadI2CBlockData(i2c_handle, 0xAA, (char *)data, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calibration_data->ac1 = (data[0] << 8) | data[1];
    calibration_data->ac2 = (data[2] << 8) | data[3];
    calibration_data->ac3 = (data[4] << 8) | data[5];
    calibration_data->ac4 = (data[6] << 8) | data[7];
    calibration_data->ac5 = (data[8] << 8) | data[9];
    calibration_data->ac6 = (data[10] << 8) | data[11];
    calibration_data->b1 = (data[12] << 8) | data[13];
    calibration_data->b2 = (data[14] << 8) | data[15];
    calibration_data->mb = (data[16] << 8) | data[17];
    calibration_data->mc = (data[18] << 8) | data[19];
    calibration_data->md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(int32_t *raw_temperature) {
    char buf[1];
    buf[0] = BMP180_CMD_TEMP;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5ms

    uint8_t data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temperature = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data from BMP180
int read_raw_pressure(int oss, int32_t *raw_pressure) {
    char buf[1];
    uint8_t cmd;

    switch (oss) {
        case 0:
            cmd = BMP180_CMD_PRESSURE0;
            break;
        case 1:
            cmd = BMP180_CMD_PRESSURE1;
            break;
        case 2:
            cmd = BMP180_CMD_PRESSURE2;
            break;
        case 3:
            cmd = BMP180_CMD_PRESSURE3;
            break;
        default:
            fprintf(stderr, "Invalid OSS value\n");
            return -1;
    }

    buf[0] = cmd;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    uint8_t data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((int32_t)data[0] << 16 | (int32_t)data[1] << 8 | (int32_t)data[2]) >> (8 - oss);
    return 0;
}

// Function to calculate pressure in hPa
float calculate_pressure(int32_t raw_temperature, int32_t raw_pressure, const bmp180_calibration_data_t *calibration_data) {
    int32_t X1 = ((raw_temperature - calibration_data->ac6) * calibration_data->ac5) >> 15;
    int32_t X2 = (calibration_data->mc << 11) / (X1 + calibration_data->md);
    int32_t B5 = X1 + X2;

    int32_t B6 = B5 - 4000;
    X1 = (calibration_data->b2 * (B6 * B6) >> 12) >> 11;
    X2 = (calibration_data->ac2 * B6) >> 11;
    int32_t X3 = X1 + X2;
    int32_t B3 = (((calibration_data->ac1 * 4 + X3) << 0) + 2) >> 2; // OSS = 0

    X1 = (calibration_data->ac3 * B6) >> 13;
    X2 = (calibration_data->b1 * ((B6 * B6) >> 12)) >> 16;
    X3 = ((X1 + X2) + 2) >> 2;
    uint32_t B4 = (calibration_data->ac4 * (uint32_t)(X3 + 32768)) >> 15;

    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> 0); // OSS = 0
    int32_t p;
    if (B7 < 0x80000000) {
        p = (B7 * 2) / B4;
    } else {
        p = (B7 / B4) * 2;
    }

    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    float pressure = p + ((X1 + X2 + 3791) >> 4);

    return pressure / 100.0; // Convert to hPa
}

// Function to add pressure reading to the circular buffer
void add_to_circular_buffer(float pressure) {
    time(&rolling_avg_buffer[buffer_index].timestamp);
    rolling_avg_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % ROLLING_AVG_SIZE;
}

// Function to calculate the rolling average of pressure readings
float calculate_rolling_average() {
    float sum = 0.0;
    for (int i = 0; i < ROLLING_AVG_SIZE; i++) {
        sum += rolling_avg_buffer[i].pressure;
    }
    return sum / ROLLING_AVG_SIZE;
}

// Function to check for pressure deviation and trigger alert
void check_pressure_deviation(float current_pressure, float rolling_average) {
    float diff = fabs(current_pressure - rolling_average);
    if (diff > PRESSURE_THRESHOLD) {
        fprintf(stderr, "Pressure deviation detected: Current = %.2f hPa, Average = %.2f hPa, Deviation = %.2f hPa\n",
                current_pressure, rolling_average, diff);
        gpioWrite(ALERT_GPIO, 1); // Set GPIO HIGH
        gpioDelay(1000);          // Wait 1 second
        gpioWrite(ALERT_GPIO, 0); // Set GPIO LOW
    }
}

// Timer callback function
void timer_callback() {
    int32_t raw_temperature, raw_pressure;
    float pressure, rolling_average;

    if (read_raw_temperature(&raw_temperature) != 0) {
        fprintf(stderr, "Error reading raw temperature\n");
        return;
    }

    if (read_raw_pressure(0, &raw_pressure) != 0) {
        fprintf(stderr, "Error reading raw pressure\n");
        return;
    }

    pressure = calculate_pressure(raw_temperature, raw_pressure, &calibration_data);
    add_to_circular_buffer(pressure);
