#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP280 I2C addresses
#define BMP280_ADDR_1 0x76
#define BMP280_ADDR_2 0x77

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_ID 0xD0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Oversampling settings
#define BMP280_OVERSAMPLING_TEMP 2 // x2
#define BMP280_OVERSAMPLING_PRESS 5 // x16
#define BMP280_MODE_FORCED 1

// Global variables
int i2c_handle;
FILE *log_file;
FILE *error_file;
int bmp280_address = BMP280_ADDR_1; // Default address
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t dig_T1, dig_T2, dig_T3;
int16_t dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;

// Function prototypes
int init_i2c(int address);
int read_calibration_data(int i2c_handle);
int read_raw_data(int i2c_handle, int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, double t_fine);
int log_data(double temperature, double pressure);
void signal_handler(int signal);
int check_sensor_id(int i2c_handle);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize I2C
int init_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Check sensor ID
int check_sensor_id(int i2c_handle) {
    char id;
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_ID, &id, 1) != 1) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }
    if (id != 0x58) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02x\n", id);
        return -1;
    }
    return 0;
}

// Read calibration data
int read_calibration_data(int i2c_handle) {
    uint8_t data[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, (char *)data, 26) != 26) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    dig_T1 = (data[1] << 8) | data[0];
    dig_T2 = (data[3] << 8) | data[2];
    dig_T3 = (data[5] << 8) | data[4];
    dig_P1 = (data[7] << 8) | data[6];
    dig_P2 = (data[9] << 8) | data[8];
    dig_P3 = (data[11] << 8) | data[10];
    dig_P4 = (data[13] << 8) | data[12];
    dig_P5 = (data[15] << 8) | data[14];
    dig_P6 = (data[17] << 8) | data[16];
    dig_P7 = (data[19] << 8) | data[18];
    dig_P8 = (data[21] << 8) | data[20];
    dig_P9 = (data[23] << 8) | data[22];

    return 0;
}

// Read raw temperature and pressure data
int read_raw_data(int i2c_handle, int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];

    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    *temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    return 0;
}

// Compensate temperature
double compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    double t_fine;

    var1 = (((double)raw_temperature / 16384.0) - ((double)dig_T1) / 1024.0) * ((double)dig_T2);
    var2 = ((((double)raw_temperature / 131072.0) - ((double)dig_T1) / 8192.0) * (((double)raw_temperature / 131072.0) - ((double)dig_T1) / 8192.0)) * ((double)dig_T3);
    t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure
double compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)dig_P4) * 65536.0);
    var1 = (((double)dig_P3) * var1 * var1 / 524288.0 + ((double)dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)dig_P1);

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)dig_P7)) / 16.0;

    return p / 100.0; // in hPa
}

// Log data to file
int log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

int main() {
    int status;
    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("weather_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_file = fopen("error_log.txt", "a");
    if (error_file == NULL) {
        fprintf(stderr, "Error opening error log file\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C with the default address
    if (init_i2c(bmp280_address) != 0) {
        fprintf(stderr, "Failed to initialize I2C with address 0x%02x, trying alternative address.\n", bmp280_address);
        bmp280_address = BMP280_ADDR_2;
        if (init_i2c(bmp280_address) != 0) {
            fprintf(stderr, "Failed to initialize I2C with address 0x%02x as well.\n", bmp280_address);
            fclose(log_file);
            fclose(error_file);
            gpioTerminate();
            return 1;
        }
    }

    // Check sensor ID
    if (check_sensor_id(i2c_handle) != 0) {
        fprintf(stderr, "Sensor ID check failed. Exiting.\n");
        fclose(log_file);
        fclose(error_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle) != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        fclose(log_file);
        fclose(error_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor: forced mode, oversampling
    char config_data[2];
    config_data[0] = (BMP280_OVERSAMPLING_TEMP << 5) | (BMP280_OVERSAMPLING_PRESS << 2) | BMP280_MODE_FORCED;
    config_data[1] = 0x00; //Default config

    if (i2cWriteI2CBlockData(i2c_handle, BMP280_REG_CTRL_MEAS, config_data, 1) != 1) {
        fprintf(stderr, "Error writing control register\n");
        fclose(log_file);
        fclose(error_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteI2CBlockData(i2c_handle, BMP280_REG_CONFIG, config_data + 1, 1) != 1) {
        fprintf(stderr, "Error writing config register\n");
        fclose(log_file);
        fclose(error_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
