        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle) != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        fclose(log_file);
        fclose(error_file);
