#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Constants
#define LM75_ADDR 0x48
#define GPIO_LED 18 // BCM numbering
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define I2C_RETRY_DELAY 1 // seconds

// Global variables
static volatile sig_atomic_t program_running = 1;
static int i2c_fd = -1;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0; // Number of elements in the buffer

// Function prototypes
void signal_handler(int signal);
int init_i2c();
float read_temperature();
void update_buffer(float temperature);
float calculate_average();
void *led_control_thread(void *arg);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        program_running = 0;
    }
}

// I2C initialization function
int init_i2c() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return -1;
    }

    i2c_fd = wiringPiI2CSetup(LM75_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Temperature reading function
float read_temperature() {
    int raw_temp;
    float temperature;

    raw_temp = wiringPiI2CReadReg16(i2c_fd, 0); // Read temperature register
    if (raw_temp == -1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    // LM75 returns temperature in 0.5 degree Celsius increments
    temperature = (float)((raw_temp >> 5) * 0.5);
    return temperature;
}

// Circular buffer update function
void update_buffer(float temperature) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
    pthread_mutex_unlock(&buffer_mutex);
}

// Running average calculation function
float calculate_average() {
    float sum = 0.0;
    pthread_mutex_lock(&buffer_mutex);
    for (int i = 0; i < buffer_count; i++) {
        sum += temperature_buffer[i];
    }
    pthread_mutex_unlock(&buffer_mutex);
    return sum / buffer_count;
}

// LED control thread function
void *led_control_thread(void *arg) {
    float average_temperature;

    while (program_running) {
        average_temperature = calculate_average();

        if (average_temperature > TEMP_THRESHOLD) {
            digitalWrite(GPIO_LED, HIGH); // Turn LED on
        } else {
            digitalWrite(GPIO_LED, LOW);  // Turn LED off
        }

        sleep(1); // Check every second
    }

    return NULL;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Turn off LED
    digitalWrite(GPIO_LED, LOW);

    // Release GPIO
    pinMode(GPIO_LED, INPUT); // Set to input to avoid leaving it in a fixed state

    // Close I2C
    if (i2c_fd != -1) {
        // No direct close function in wiringPi, but setting to -1 effectively disables it
        i2c_fd = -1; // Invalidate the file descriptor
    }

    // Destroy mutex
    pthread_mutex_destroy(&buffer_mutex);

    printf("Cleanup complete.\n");
}

int main() {
    pthread_t led_thread;
    float temperature;
    int init_attempts = 0;

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C with retry
    while (init_i2c() == -1 && init_attempts < 3) {
        fprintf(stderr, "I2C initialization failed. Retrying in %d seconds...\n", I2C_RETRY_DELAY);
        sleep(I2C_RETRY_DELAY);
        init_attempts++;
    }

    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to initialize I2C after multiple attempts. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    pinMode(GPIO_LED, OUTPUT);

    // Create LED control thread
    if (pthread_create(&led_thread, NULL, led_control_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create LED control thread: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        temperature = read_temperature();

        if (temperature > -999.0) { // Check for read error
            update_buffer(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying I2C initialization...\n");
            i2c_fd = -1; // Invalidate the file descriptor
            if (init_i2c() == -1) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                program_running = 0; // Exit the main loop
            }
        }

        sleep(1); // Read every second
    }

    // Wait for LED thread to finish
    pthread_join(led_thread, NULL);

    // Cleanup
    cleanup();

    return 0;
}

