// Configuration structure
typedef struct {
    double target_temperature;
    double kp;
    double ki;
    double kd;
} Config;

// Global variables
int spi_handle;
int pwm_gpio = 18;
double current_temperature = 0.0;
double integral = 0.0;
double previous_error = 0.0;
Config config;
volatile sig_atomic_t terminate = 0;

// Function prototypes
