#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
int calculate_temperature(int raw_temp);
int calculate_pressure(int raw_pressure, int raw_temp);
void log_breach(float temperature, float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read calibration data from BMP180
int read_calibration_data() {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error reading calibration data: %d\n", i2c_handle);
        return -1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Read raw temperature value
int read_raw_temperature(int *raw_temp) {
    char buf[2];
    char write_buf[2];

    write_buf[0] = BMP180_REG_CONTROL;
    write_buf[1] = 0x2E; // Temperature measurement command

    if (i2cWriteDevice(i2c_handle, write_buf, 2) != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", i2c_handle);
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    write_buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, write_buf, 1) != 0) {
        fprintf(stderr, "Error writing register address for temperature: %d\n", i2c_handle);
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature: %d\n", i2c_handle);
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Read raw pressure value
int read_raw_pressure(int *raw_pressure) {
    char buf[3];
    char write_buf[2];

    write_buf[0] = BMP180_REG_CONTROL;
    write_buf[1] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command

    if (i2cWriteDevice(i2c_handle, write_buf, 2) != 0) {
        fprintf(stderr, "Error writing pressure command: %d\n", i2c_handle);
        return -1;
    }

    gpioDelay(2 + (3 << BMP180_OSS) * 1000); // Wait for conversion

    write_buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, write_buf, 1) != 0) {
        fprintf(stderr, "Error writing register address for pressure: %d\n", i2c_handle);
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure: %d\n", i2c_handle);
        return -1;
    }

    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Calculate temperature in degrees Celsius
int calculate_temperature(int raw_temp) {
    int X1 = ((raw_temp - (int)ac6) * (int)ac5) >> 15;
    int X2 = ((int)mc << 11) / (X1 + (int)md);
    int B5 = X1 + X2;
    int temperature = (B5 + 8) >> 4;
    return temperature;
}

// Calculate pressure in hPa
int calculate_pressure(int raw_pressure, int raw_temp) {
    int X1 = ((raw_temp - (int)ac6) * (int)ac5) >> 15;
    int X2 = ((int)mc << 11) / (X1 + (int)md);
    int B5 = X1 + X2;

    int B6 = B5 - 4000;
    int X3 = ((int)b2 * (B6 * B6) >> 12) >> 11;
    int X4 = ((int)ac2 * B6) >> 11;
    int B3 = (((((int)ac1) * 4 + X3) << BMP180_OSS) + 2) >> 2;

    int X1_pressure = ((int)ac3 * B6) >> 13;
    int X2_pressure = ((int)b1 * ((B6 * B6) >> 12)) >> 16;
    int X3_pressure = ((X1_pressure + X2_pressure + 2) >> 2);
    uint32_t B4 = ((uint32_t)ac4 * (uint32_t)(X3_pressure + 32768)) >> 15;
    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> BMP180_OSS);

    int pressure;
    if (B7 < 0x80000000) {
        pressure = (B7 * 2) / B4;
    } else {
        pressure = (B7 / B4) * 2;
    }

    X1_pressure = (pressure >> 8) * (pressure >> 8);
    X1_pressure = (X1_pressure * 3038) >> 16;
    X2_pressure = (-7357 * pressure) >> 16;
    pressure = pressure + ((X1_pressure + X2_pressure + 3791) >> 4);

    return pressure;
}

// Log breach to file
void log_breach(float temperature, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s - Temperature: %.2f°C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("breach_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    int raw_temp, raw_pressure;
    float temperature, pressure;

    // Main loop
    while (!terminate) {
        // Read raw temperature and pressure
        if (read_raw_temperature(&raw_temp) != 0 || read_raw_pressure(&raw_pressure) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Calculate temperature and pressure
        temperature = calculate_temperature(raw_temp);
        pressure = calculate_pressure(raw_pressure, raw_temp);

        // Check for breaches
        if (temperature > 30.0 || pressure < 950.0) {
            log_breach(temperature, pressure);
        }

        gpioDelay(1000); // Sample once per second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

