    if (i2cWriteDevice(i2c_handle, write_buf, 1) != 0) {
        fprintf(stderr, "Error writing register address for pressure: %d\n", i2c_handle);
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure: %d\n", i2c_handle);
        return -1;
    }

    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Calculate temperature in degrees Celsius
int calculate_temperature(int raw_temp) {
    int X1 = ((raw_temp - (int)ac6) * (int)ac5) >> 15;
    int X2 = ((int)mc << 11) / (X1 + (int)md);
    int B5 = X1 + X2;
    int temperature = (B5 + 8) >> 4;
    return temperature;
}

// Calculate pressure in hPa
int calculate_pressure(int raw_pressure, int raw_temp) {
    int X1 = ((raw_temp - (int)ac6) * (int)ac5) >> 15;
    int X2 = ((int)mc << 11) / (X1 + (int)md);
    int B5 = X1 + X2;

    int B6 = B5 - 4000;
    int X3 = ((int)b2 * (B6 * B6) >> 12) >> 11;
    int X4 = ((int)ac2 * B6) >> 11;
    int B3 = (((((int)ac1) * 4 + X3) << BMP180_OSS) + 2) >> 2;

    int X1_pressure = ((int)ac3 * B6) >> 13;
    int X2_pressure = ((int)b1 * ((B6 * B6) >> 12)) >> 16;
    int X3_pressure = ((X1_pressure + X2_pressure + 2) >> 2);
    uint32_t B4 = ((uint32_t)ac4 * (uint32_t)(X3_pressure + 32768)) >> 15;
    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> BMP180_OSS);

    int pressure;
    if (B7 < 0x80000000) {
        pressure = (B7 * 2) / B4;
    } else {
        pressure = (B7 / B4) * 2;
    }

    X1_pressure = (pressure >> 8) * (pressure >> 8);
    X1_pressure = (X1_pressure * 3038) >> 16;
    X2_pressure = (-7357 * pressure) >> 16;
    pressure = pressure + ((X1_pressure + X2_pressure + 3791) >> 4);

    return pressure;
}

