void print_buffer() {
    printf("Timestamp,Temperature(C),Pressure(Pa)\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%ld,%.2f,%.2f\n", buffer[i].timestamp, buffer[i].temperature, buffer[i].pressure);
