#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HEATER_PIN 17
#define SPI_CE0 8
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define SPI_FLAGS 0

// Define PI controller parameters
#define TARGET_TEMPERATURE 25.0
#define KP 1.0
#define KI 0.1
#define MAX_INTEGRAL 10.0

// Define safe maximum duty cycle
#define MAX_DUTY_CYCLE 80.0

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// Function prototypes
double read_temperature();
double calculate_duty_cycle(double current_temperature, double target_temperature, double kp, double ki, double *integral);
void set_heater_duty_cycle(int gpio_pin, double duty_cycle);
void log_data(double temperature, double duty_cycle, const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CE0, PI_OUTPUT);
    gpioSetMode(SPI_MISO, PI_INPUT);
    gpioSetMode(SPI_MOSI, PI_OUTPUT);
    gpioSetMode(SPI_SCLK, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heater_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature,DutyCycle,Message\n");
    }

    return 0;
}

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char data[4];
    int i;

    gpioWrite(SPI_CE0, 0); // Select the chip
    spiRead(spi_handle, data, 4);
    gpioWrite(SPI_CE0, 1); // Deselect the chip

    // Check for fault conditions
    if (data[3] & 0x01) {
        log_data(0.0, 0.0, "MAX31855 Fault: Open circuit");
        return -1000.0; // Indicate error
    }
    if (data[3] & 0x02) {
        log_data(0.0, 0.0, "MAX31855 Fault: Short to GND");
        return -1000.0; // Indicate error
    }
    if (data[3] & 0x04) {
        log_data(0.0, 0.0, "MAX31855 Fault: Short to VCC");
        return -1000.0; // Indicate error
    }

    // Extract temperature data
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    double temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate duty cycle using PI controller
double calculate_duty_cycle(double current_temperature, double target_temperature, double kp, double ki, double *integral) {
    double error = target_temperature - current_temperature;
    *integral += error;

    // Anti-windup
    if (*integral > MAX_INTEGRAL) {
        *integral = MAX_INTEGRAL;
    } else if (*integral < -MAX_INTEGRAL) {
        *integral = -MAX_INTEGRAL;
    }

    double duty_cycle = kp * error + ki * (*integral);

    // Limit duty cycle
    if (duty_cycle > MAX_DUTY_CYCLE) {
        duty_cycle = MAX_DUTY_CYCLE;
    } else if (duty_cycle < 0.0) {
        duty_cycle = 0.0;
    }

    return duty_cycle;
}

// Function to set heater duty cycle using PWM
void set_heater_duty_cycle(int gpio_pin, double duty_cycle) {
    int pwm_range = 1000; // Define PWM range
    int pwm_value = (int)(duty_cycle * pwm_range / 100.0);
    gpioPWM(gpio_pin, pwm_value);
}

// Function to log data to file
void log_data(double temperature, double duty_cycle, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f,%s\n", timestamp, temperature, duty_cycle, message);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, shutting down...\n", signal);
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    set_heater_duty_cycle(HEATER_PIN, 0.0); // Turn off heater
    spiClose(spi_handle); // Close SPI
    fclose(log_file); // Close log file
    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    double integral = 0.0;
    double current_temperature, duty_cycle;

    while (running) {
        current_temperature = read_temperature();

        if (current_temperature < -900.0) {
            // Error reading temperature, set duty cycle to 0 and log the error
            set_heater_duty_cycle(HEATER_PIN, 0.0);
            duty_cycle = 0.0;
        } else {
            duty_cycle = calculate_duty_cycle(current_temperature, TARGET_TEMPERATURE, KP, KI, &integral);
            set_heater_duty_cycle(HEATER_PIN, duty_cycle);
        }

        log_data(current_temperature, duty_cycle, "OK");

        gpioDelay(100); // Delay for 100ms
    }

    cleanup();
    return 0;
}

