#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define temperature thresholds (in millidegrees Celsius)
#define TEMP_BLUE  40000
#define TEMP_GREEN 60000

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Function to read CPU temperature from file
int read_temperature() {
    FILE *fp;
    int temperature = 0;
    int result;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file.\n");
        return -1; // Indicate error
    }

    result = fscanf(fp, "%d", &temperature);
    if (result != 1) {
        fprintf(stderr, "Error: Could not read temperature from file.\n");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return temperature;
}

// Function to set RGB LED color using PWM
int set_led_color(int red, int green, int blue) {
    int result;

    result = gpioPWM(RED_PIN, 255 - red); // Invert duty cycle for common anode
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set red PWM value. Error code: %d\n", result);
        return -1;
    }

    result = gpioPWM(GREEN_PIN, 255 - green); // Invert duty cycle for common anode
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set green PWM value. Error code: %d\n", result);
        return -1;
    }

    result = gpioPWM(BLUE_PIN, 255 - blue); // Invert duty cycle for common anode
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set blue PWM value. Error code: %d\n", result);
        return -1;
    }

    return 0; // Indicate success
}

int main() {
    int temperature;
    int red, green, blue;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        temperature = read_temperature();
        if (temperature == -1) {
            // Error reading temperature, skip this iteration
            sleep(0.5);
            continue;
        }

        // Determine LED color based on temperature
        if (temperature < TEMP_BLUE) {
            red = 0;
            green = 0;
            blue = 255;
        } else if (temperature < TEMP_GREEN) {
            red = 0;
            green = 255;
            blue = 0;
        } else {
            red = 255;
            green = 0;
            blue = 0;
        }

        // Set LED color
        if (set_led_color(red, green, blue) != 0) {
            // Error setting LED color, terminate program
            break;
        }

        // Print temperature and PWM values
        printf("Temperature: %d m°C, Red: %d, Green: %d, Blue: %d\n", temperature, red, green, blue);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Turn off all LED channels
    gpioPWM(RED_PIN, 255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN, 255);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

