#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define SERVER_URL "http://yourserver.com/api/humidity"

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} SensorData;

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    return 0;
}

// Function to read data from DHT22 sensor
SensorData read_dht22() {
    SensorData data = {0.0, 0.0, 0};
    int retries = 0;
    int bit_idx = 0;
    int byte_idx = 0;
    unsigned int raw_data[5] = {0, 0, 0, 0, 0};

    while (retries < MAX_RETRIES) {
        // Send start signal
        gpioSetMode(DHT22_GPIO, PI_OUTPUT);
        gpioWrite(DHT22_GPIO, 0);
        gpioDelay(1); // 1ms
        gpioWrite(DHT22_GPIO, 1);
        gpioDelay(30); // 30us

        // Switch to input mode
        gpioSetMode(DHT22_GPIO, PI_INPUT);

        // Wait for response (low for ~80us, high for ~80us)
        int timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            gpioDelay(1); // 1us
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for start signal\n");
                retries++;
                break;
            }
        }

        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            gpioDelay(1); // 1us
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for end of start signal\n");
                retries++;
                break;
            }
        }

        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            gpioDelay(1); // 1us
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for data signal\n");
                retries++;
                break;
            }
        }

        // Read 40 bits of data
        if (timeout <= 100) {
            for (int i = 0; i < 40; i++) {
                timeout = 0;
                while (gpioRead(DHT22_GPIO) == 0) {
                    gpioDelay(1); // 1us
                    timeout++;
                    if (timeout > 100) {
                        fprintf(stderr, "DHT22 timeout waiting for data bit start\n");
                        retries++;
                        goto retry;
                    }
                }

                timeout = 0;
                while (gpioRead(DHT22_GPIO) == 1) {
                    gpioDelay(1); // 1us
                    timeout++;
                    if (timeout > 100) {
                        fprintf(stderr, "DHT22 timeout waiting for data bit end\n");
                        retries++;
                        goto retry;
                    }
                }

                if (timeout > 40) {
                    raw_data[byte_idx] |= (1 << (7 - bit_idx));
                }

                bit_idx++;
                if (bit_idx == 8) {
                    bit_idx = 0;
                    byte_idx++;
                }
            }

            // Validate checksum
            if ((raw_data[0] + raw_data[1] + raw_data[2] + raw_data[3]) == raw_data[4]) {
                // Convert data
                float humidity = ((raw_data[0] * 256) + raw_data[1]) / 10.0;
                float temperature = (((raw_data[2] & 0x7F) * 256) + raw_data[3]) / 10.0;
                if (raw_data[2] & 0x80) {
                    temperature = -temperature;
                }

                data.temperature = temperature;
                data.humidity = humidity;
                data.valid = 1;
                return data;
            } else {
                fprintf(stderr, "DHT22 checksum error\n");
                retries++;
            }
        } else {
            retries++;
        }

        retry:
        gpioDelay(1000); // Wait before retrying
    }

    fprintf(stderr, "DHT22 read failed after %d retries\n", MAX_RETRIES);
    return data; // Return invalid data
}

// Function to format data as JSON
char* format_json(float temperature, float humidity) {
    char *json_string = (char*)malloc(100 * sizeof(char)); // Allocate memory
    if (json_string == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    sprintf(json_string, "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);
    return json_string;
}

// Function to post data to server
int post_data(const char *json_string) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);

        // Set content type to application/json
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 200 && response_code < 300) {
                printf("Data posted successfully\n");
            } else {
                fprintf(stderr, "HTTP request failed with code: %ld\n", response_code);
            }
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        SensorData sensor_data = read_dht22();

        if (sensor_data.valid) {
            char *json_string = format_json(sensor_data.temperature, sensor_data.humidity);
            if (json_string != NULL) {
                post_data(json_string);
                free(json_string); // Free allocated memory
            }
        } else {
            fprintf(stderr, "Invalid sensor data, skipping post\n");
        }

        sleep(60); // Wait 60 seconds
    }

    // Clean up
    gpioTerminate();
    return 0;
}

