#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <curl/curl.h>
#include <pigpio.h>
#include <getopt.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define BACKOFF_DELAY 2 // seconds
#define API_ENDPOINT "http://your-the-librarys-API-call.com/api/humidity"

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

// Global variables
static volatile int running = 1;
static char *api_url = API_ENDPOINT;

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Function to read DHT22 sensor data
DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0.0, 0};
    int retries = 0;
    int bit_idx = 0;
    int byte_idx = 0;
    unsigned int raw_data[5] = {0, 0, 0, 0, 0};

    while (retries < MAX_RETRIES) {
        // Send start signal
        gpioSetMode(DHT22_GPIO, PI_OUTPUT);
        gpioWrite(DHT22_GPIO, 0);
        gpioDelay(1); // 1 ms
        gpioWrite(DHT22_GPIO, 1);
        gpioDelay(30); // 30 us

        gpioSetMode(DHT22_GPIO, PI_INPUT);

        // Wait for response (low for ~80us, high for ~80us)
        int timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            gpioDelay(1); // Check every 1 us
            timeout++;
            if (timeout > 100) {
                syslog(LOG_ERR, "DHT22 response timeout (low)");
                break;
            }
        }

        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) {
                syslog(LOG_ERR, "DHT22 response timeout (high)");
                break;
            }
        }

        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) {
                syslog(LOG_ERR, "DHT22 response timeout (high after low)");
                break;
            }
        }

        // Read 40 bits
        for (int i = 0; i < 40; i++) {
            timeout = 0;
            while (gpioRead(DHT22_GPIO) == 0) {
                gpioDelay(1);
                timeout++;
                if (timeout > 100) {
                    syslog(LOG_ERR, "DHT22 data timeout (low)");
                    goto retry;
                }
            }

            long start = gpioTick();
            timeout = 0;
            while (gpioRead(DHT22_GPIO) == 1) {
                gpioDelay(1);
                timeout++;
                if (timeout > 100) {
                    syslog(LOG_ERR, "DHT22 data timeout (high)");
                    goto retry;
                }
            }
            long end = gpioTick();

            if ((end - start) > 40) {
                raw_data[byte_idx] |= (1 << (7 - bit_idx));
            }

            bit_idx++;
            if (bit_idx == 8) {
                bit_idx = 0;
                byte_idx++;
            }
        }

        // Validate checksum
        if ((raw_data[0] + raw_data[1] + raw_data[2] + raw_data[3]) == raw_data[4]) {
            data.humidity = (float)(((raw_data[0] << 8) | raw_data[1])) / 10.0;
            data.temperature = (float)(((raw_data[2] << 8) | raw_data[3])) / 10.0;
            if (data.temperature > 125) {
                data.temperature = data.temperature - 256;
            }
            data.valid = 1;
            syslog(LOG_INFO, "DHT22 data read successfully: Temperature = %.1f, Humidity = %.1f", data.temperature, data.humidity);
            return data;
        } else {
            syslog(LOG_ERR, "DHT22 checksum failed");
        }

        retry:
        retries++;
        syslog(LOG_WARNING, "DHT22 read failed, retrying (%d/%d)", retries, MAX_RETRIES);
        sleep(BACKOFF_DELAY * retries);
    }

    syslog(LOG_ERR, "DHT22 read failed after %d retries", MAX_RETRIES);
    return data; // Return invalid data
}

// Function to format data as JSON
char *format_json(float temperature, float humidity) {
    char *json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for JSON string");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);
    return json_string;
}

// Function to post data to the API endpoint
int post_data(const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, api_url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));

        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 200 && response_code < 300) {
                syslog(LOG_INFO, "Data posted successfully, HTTP status: %ld", response_code);
            } else {
                syslog(LOG_ERR, "Data post failed, HTTP status: %ld", response_code);
            }
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    } else {
        syslog(LOG_ERR, "curl_easy_init() failed");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                api_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <api_url>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio, exiting");
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        DHT22Data dht22_data = read_dht22();

        if (dht22_data.valid) {
            char *json_data = format_json(dht22_data.temperature, dht22_data.humidity);
            if (json_data != NULL) {
                int retries = 0;
                while (retries < MAX_RETRIES) {
                    if (post_data(json_data) == 0) {
                        break; // Success, exit retry loop
                    } else {
                        retries++;
                        syslog(LOG_WARNING, "Data post failed, retrying (%d/%d)", retries, MAX_RETRIES);
                        sleep(BACKOFF_DELAY * retries);
                    }
                }
                free(json_data);
            }
        }

        sleep(10);
    }

    // Cleanup
    gpioTerminate();
    closelog();
    return 0;
