}

int read_fan_state() {
    FILE *fp;
    int fan_state = -1;

    fp = fopen(FAN_STATE_FILE, "r");
    if (fp == NULL) {
        perror("Error opening fan state file");
        return -1;
    }

    if (fscanf(fp, "%d", &fan_state) != 1) {
        perror("Error reading fan state");
        fclose(fp);
        return -1;
    }

