        perror("Error reading max state");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return max_state;
}

int set_fan_state(int state) {
    FILE *fp;

    fp = fopen(FAN_STATE_FILE, "w");
    if (fp == NULL) {
        perror("Error opening fan state file for writing");
        return -1;
    }

    if (fprintf(fp, "%d", state) < 0) {
        perror("Error writing fan state");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

void log_event(const char *message) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
