    int temperature, fan_state, max_state, new_fan_state;
    int temperature_read_attempts = 0;
    int fan_state_read_attempts = 0;
    int max_state_read_attempts = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initial read of max_state
    max_state = read_max_state();
    if (max_state == -1) {
        fprintf(stderr, "Failed to read max_state. Exiting.\n");
        return 1;
    }

    while (program_running) {
        // Read temperature with retry
        temperature = -1;
        temperature_read_attempts = 0;
        while (temperature == -1 && temperature_read_attempts < 3) {
            temperature = read_temperature();
            if (temperature == -1) {
                temperature_read_attempts++;
                fprintf(stderr, "Temperature read failed, attempt %d. Retrying in 1 second.\n", temperature_read_attempts);
                sleep(1);
            }
        }

        if (temperature == -1) {
            fprintf(stderr, "Failed to read temperature after multiple attempts. Continuing with previous value.\n");
        }

        // Read fan state with retry
        fan_state = -1;
        fan_state_read_attempts = 0;
        while (fan_state == -1 && fan_state_read_attempts < 3) {
            fan_state = read_fan_state();
            if (fan_state == -1) {
                fan_state_read_attempts++;
                fprintf(stderr, "Fan state read failed, attempt %d. Retrying in 1 second.\n", fan_state_read_attempts);
                sleep(1);
            }
        }

        if (fan_state == -1) {
            fprintf(stderr, "Failed to read fan state after multiple attempts. Continuing with previous value.\n");
        }

        // Determine new fan state based on temperature
        if (temperature < 4500) {
            new_fan_state = 0;
        } else if (temperature < 5500) {
            new_fan_state = 1;
        } else if (temperature < 6500) {
            new_fan_state = 2;
        } else {
            new_fan_state = 3;
        }

        // Ensure new fan state is within the valid range
        if (new_fan_state < 0) new_fan_state = 0;
        if (new_fan_state > max_state) new_fan_state = max_state;

        // Set fan state if it has changed
        if (new_fan_state != fan_state) {
            if (set_fan_state(new_fan_state) == 0) {
                char log_message[128];
                snprintf(log_message, sizeof(log_message), "Fan state changed from %d to %d", fan_state, new_fan_state);
                log_event(log_message);
            } else {
                fprintf(stderr, "Failed to set fan state.\n");
            }
        }

        sleep(5);
    }

    // Shutdown sequence: set fan to state 0
    if (set_fan_state(0) == 0) {
        log_event("Fan set to 0 during shutdown.");
    } else {
        fprintf(stderr, "Failed to set fan to 0 during shutdown.\n");
    }

    return 0;
}

