#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Constants
#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define TARGET_TEMPERATURE 50.0
#define LOG_FILE "heater_log.txt"
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0

// PID Gains
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// PID State
static float integral = 0.0;
static float previous_error = 0.0;

// Function Prototypes
void signal_handler(int signal);
int initialize();
void cleanup();
float read_temperature();
float calculate_pid(float current_temperature);
void set_heater_duty_cycle(float pid_output);
void log_data(float temperature, float duty_cycle, float pid_output);
void handle_max31855_fault(uint32_t raw_data);

// Signal Handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialization Function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup Function
void cleanup() {
    // Turn off heater
    gpioPWM(HEATER_GPIO, 0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

// Read Temperature from MAX31855
float read_temperature() {
    uint8_t data[4];
    int result = spiRead(spi_handle, data, 4);

    if (result != 4) {
        fprintf(stderr, "SPI read failed\n");
        return -1000.0; // Indicate error
    }

    // Check for fault bits
    if (data[3] & 0x07) {
        handle_max31855_fault((uint32_t)data[0] << 24 | (uint32_t)data[1] << 16 | (uint32_t)data[2] << 8 | (uint32_t)data[3]);
        return -1000.0; // Indicate error
    }

    // Extract temperature data
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    float temperature = raw_temp * 0.25;

    return temperature;
}

// Calculate PID output
float calculate_pid(float current_temperature) {
    float error = TARGET_TEMPERATURE - current_temperature;

    integral += error;
    float derivative = error - previous_error;

    float output = Kp * error + Ki * integral + Kd * derivative;

    previous_error = error;

    // Clamp output to 0-100
    if (output < 0) output = 0;
    if (output > 100) output = 100;

    return output;
}

// Set Heater Duty Cycle
void set_heater_duty_cycle(float pid_output) {
    int duty_cycle = (int)pid_output;
    gpioPWM(HEATER_GPIO, duty_cycle);
}

// Log Data to File
void log_data(float temperature, float duty_cycle, float pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
