        fprintf(stderr, "  Short to GND\n");
    }
    if (raw_data & 0x04) {
        fprintf(stderr, "  Short to VCC\n");
    }

    // Disable heater
    gpioPWM(HEATER_GPIO, 0);

    // Reset PID state
    integral = 0.0;
    previous_error = 0.0;

    fprintf(log_file, "MAX31855 Fault Detected! Heater disabled.\n");
    fflush(log_file);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Temperature control started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read temperature
        float temperature = read_temperature();

        if (temperature < MIN_TEMPERATURE || temperature > MAX_TEMPERATURE) {
