#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define LOG_FILE "cooling_log.csv"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
float read_cpu_temperature();
float read_gpu_temperature();
float map_temperature_to_duty_cycle(float temperature);
int set_fan_speed(int duty_cycle);
int log_data(float cpu_temp, float gpu_temp, int duty_cycle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read CPU temperature from /sys/class/thermal/thermal_zone0/temp
float read_cpu_temperature() {
    FILE *fp;
    char buffer[10];
    float temperature = 0.0;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Error opening CPU temperature file");
        return -1.0; // Indicate error
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temperature = atoi(buffer) / 1000.0;
    } else {
        perror("Error reading CPU temperature");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    return temperature;
}

// Function to read GPU temperature from /sys/class/thermal/thermal_zone1/temp
float read_gpu_temperature() {
    FILE *fp;
    char buffer[10];
    float temperature = 0.0;

    fp = fopen("/sys/class/thermal/thermal_zone1/temp", "r");
    if (fp == NULL) {
        perror("Error opening GPU temperature file");
        return -1.0; // Indicate error
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temperature = atoi(buffer) / 1000.0;
    } else {
        perror("Error reading GPU temperature");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    return temperature;
}

// Function to map temperature to duty cycle
float map_temperature_to_duty_cycle(float temperature) {
    float duty_cycle = 0.0;

    if (temperature <= 40.0) {
        duty_cycle = 0.0;
    } else if (temperature >= 70.0) {
        duty_cycle = 100.0;
    } else {
        duty_cycle = (temperature - 40.0) * (100.0 / (70.0 - 40.0));
    }

    return duty_cycle;
}

// Function to set fan speed using pigpio
int set_fan_speed(int duty_cycle) {
    int result = gpioPWM(FAN_GPIO, duty_cycle);
    if (result != 0) {
        fprintf(stderr, "Error setting fan speed: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to log data to a CSV file
int log_data(float cpu_temp, float gpu_temp, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, cpu_temp, gpu_temp, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int result;
    float cpu_temp, gpu_temp, duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    result = gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    if (result != 0) {
        fprintf(stderr, "Error setting PWM frequency: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,CPU Temperature (C),GPU Temperature (C),Duty Cycle (%)\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read temperatures
        cpu_temp = read_cpu_temperature();
        gpu_temp = read_gpu_temperature();

        if (cpu_temp < 0 || gpu_temp < 0) {
            fprintf(stderr, "Error reading temperature, skipping this iteration.\n");
            sleep(5);
            continue;
        }

        // Calculate duty cycle
        duty_cycle = map_temperature_to_duty_cycle(cpu_temp);

        // Set fan speed
        if (set_fan_speed((int)duty_cycle) != 0) {
            fprintf(stderr, "Error setting fan speed, skipping this iteration.\n");
        }

        // Log data
        if (log_data(cpu_temp, gpu_temp, (int)duty_cycle) != 0) {
            fprintf(stderr, "Error logging data, skipping this iteration.\n");
        }

        printf("CPU Temp: %.2f C, GPU Temp: %.2f C, Duty Cycle: %.2f %%\n", cpu_temp, gpu_temp, duty_cycle);

        sleep(5);
    }

    // Clean up
    set_fan_speed(0); // Turn off the fan
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

