#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x70
#define FLOW_LOG_FILE "flow_log.txt"
#define MAX_RETRIES 3

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flow_sensor(int i2c_handle);
float convert_flow(int raw_flow);
void log_flow_data(float flow1, float flow2);
void signal_handler(int signal);
int crc8(const unsigned char *data, int len);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// CRC-8 calculation function
int crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read flow sensor data
int read_flow_sensor(int i2c_handle) {
    unsigned char buffer[3];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        bytes_read = i2cReadDevice(i2c_handle, (char *)buffer, 3);
        if (bytes_read == 3) {
            // CRC validation
            if (crc8(buffer, 2) == buffer[2]) {
                return (buffer[0] << 8) | buffer[1];
            } else {
                fprintf(stderr, "CRC check failed. Retry %d\n", retries + 1);
            }
        } else {
            fprintf(stderr, "I2C read error (bytes read: %d). Retry %d\n", bytes_read, retries + 1);
        }
        retries++;
        gpioDelay(1000); // Wait 1ms before retrying
    }

    fprintf(stderr, "Failed to read flow sensor after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to convert raw flow data to ml/min
float convert_flow(int raw_flow) {
    // Conversion formula from SLF3S-1300F datasheet
    return (float)raw_flow / 120.0f; // Example conversion, adjust as needed
}

// Function to log flow data to a file
void log_flow_data(float flow1, float flow2) {
    FILE *fp = fopen(FLOW_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_flow1 = read_flow_sensor(i2c_handle1);
        int raw_flow2 = read_flow_sensor(i2c_handle2);

        if (raw_flow1 != -1 && raw_flow2 != -1) {
            float flow1 = convert_flow(raw_flow1);
            float flow2 = convert_flow(raw_flow2);
            log_flow_data(flow1, flow2);
        }

        gpioDelay(1000); // Poll every 1 second
    }

    // Clean up
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

