#define PULSES_PER_REVOLUTION 360.0

// Global variables
volatile int encoder_position = 0; // Current encoder position
volatile int last_encoder_position = 0; // Last encoder position
FILE *log_file = NULL; // File pointer for the log file

// Function prototypes
int initialize_gpio();
int read_encoder_channels(int *a, int *b);
void update_encoder_position(int a, int b);
double calculate_angle();
int log_position(double angle);
void signal_handler(int signal);

// Structure to hold encoder state
typedef struct {
    int a;
    int b;
    int state;
} EncoderState;

EncoderState encoder_state = {0, 0, 0};

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(ENCODER_A, PI_INPUT);
    gpioSetPullUpDown(ENCODER_A, PI_PUD_UP);
    gpioSetMode(ENCODER_B, PI_INPUT);
    gpioSetPullUpDown(ENCODER_B, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to read the current state of the encoder channels
int read_encoder_channels(int *a, int *b) {
    *a = gpioRead(ENCODER_A);
    *b = gpioRead(ENCODER_B);
    return 0;
}

// Function to update the encoder position based on the quadrature state machine
void update_encoder_position(int a, int b) {
    int new_state = 0;
    switch (encoder_state.state) {
        case 0:
            if (a == 1 && b == 0) new_state = 1;
            else if (a == 0 && b == 1) new_state = 3;
            break;
        case 1:
            if (a == 1 && b == 1) new_state = 2;
            else if (a == 0 && b == 0) new_state = 0;
            break;
        case 2:
            if (a == 0 && b == 1) new_state = 3;
            else if (a == 1 && b == 0) new_state = 1;
            break;
        case 3:
            if (a == 0 && b == 0) new_state = 0;
            else if (a == 1 && b == 1) new_state = 2;
            break;
    }

    if (new_state != encoder_state.state) {
        if (new_state > encoder_state.state) {
            encoder_position++;
        } else {
            encoder_position--;
        }

        encoder_state.state = new_state;
        encoder_state.a = a;
        encoder_state.b = b;
    }
}

// Function to calculate the normalized angular position
double calculate_angle() {
    double angle = (double)encoder_position / PULSES_PER_REVOLUTION * 360.0;
    if (angle < 0.0) {
        angle += 360.0;
    } else if (angle >= 360.0) {
        angle -= 360.0;
    }
    return angle;
}

// Function to log the timestamped position change to a file
int log_position(double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, angle);
        fflush(log_file); // Ensure data is written to the file immediately
        return 0; // Indicate success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1; // Indicate failure
    }
}

// Signal handler function to catch SIGINT and SIGTERM signals
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if GPIO initialization fails
    }

    // Open the log file
    log_file = fopen("encoder_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1; // Exit if file opening fails
    }

    int a, b;
    double angle;

    // Main loop
    while (1) {
        // Read encoder channels
        if (read_encoder_channels(&a, &b) == 0) {
            // Update encoder position
            update_encoder_position(a, b);

            // Calculate angle
            angle = calculate_angle();

            // Log position if it has changed
            if (angle != (double)last_encoder_position / PULSES_PER_REVOLUTION * 360.0) {
                if (log_position(angle) == 0) {
                    last_encoder_position = encoder_position;
                } else {
                    fprintf(stderr, "Error logging position.\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading encoder channels.\n");
        }

        // Delay to avoid excessive CPU usage
        gpioDelay(1); // 1 millisecond delay
    }

    return 0; // This line will never be reached due to the infinite loop
}

