#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x38
#define RED_REG 0x00
#define IR_REG 0x02
#define GPIO_LED 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_adpd144ri(uint16_t *red, uint16_t *ir);
void log_data(uint16_t red, uint16_t ir);
void control_led(uint16_t ir);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t ir;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO_LED as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_adpd144ri(&sensor_data.red, &sensor_data.ir) == 0) {
            // Log data
            log_data(sensor_data.red, sensor_data.ir);

            // Control LED
            control_led(sensor_data.ir);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }
    return 0;
}

// Read ADPD144RI sensor data
int read_adpd144ri(uint16_t *red, uint16_t *ir) {
    char buf[4];
    int result;

    // Read Red value
    result = i2cReadI2CBlockData(i2c_handle, RED_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read Red value: %s\n", strerror(errno));
        return 1;
    }
    *red = (buf[1] << 8) | buf[0];

    // Read IR value
    result = i2cReadI2CBlockData(i2c_handle, IR_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read IR value: %s\n", strerror(errno));
        return 1;
    }
    *ir = (buf[1] << 8) | buf[0];

    return 0;
}

// Log data to CSV file
void log_data(uint16_t red, uint16_t ir) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, red, ir);
    fflush(log_file); // Ensure data is written to file immediately
}

// Control LED based on IR value
void control_led(uint16_t ir) {
    if (ir > IR_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();
}

