#include <time.h>
#include <string.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to configure GPIO pin as input with pull-down resistor
int configure_gpio() {
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    return 0;
}

// Interrupt service routine (ISR) for rising edge detection
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) { // Rising edge
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

