    int current_level = gpioRead(AUDIO_PIN);
    gpioDelay(1); // Small delay to avoid multiple triggers
    int next_level = gpioRead(AUDIO_PIN);

    return (current_level == 0 && next_level == 1) ? 1 : 0;
}

