#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define FLOW_RATE_SCALE_FACTOR 0.064 // uL/min per raw unit
#define MEASUREMENT_INTERVAL_MS 1000
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int read_flow_rate(uint16_t *raw_value);
uint8_t calculate_crc(uint8_t data[], int len);
int validate_crc(uint8_t data[], int len, uint8_t crc);
float convert_to_flow_rate(uint16_t raw_value);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    uint16_t raw_value;
    float flow_rate;
    time_t timestamp;
} sensor_data_t;

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        fprintf(stderr, "Failed to open I2C connection. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s. Exiting.\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    uint16_t raw_value;
    float flow_rate;
    while (!terminate) {
        // Read flow rate
        if (read_flow_rate(&raw_value) == 0) {
            // Convert to flow rate
            flow_rate = convert_to_flow_rate(raw_value);

            // Log flow rate
            if (log_flow_rate(flow_rate) != 0) {
                fprintf(stderr, "Failed to log flow rate.\n");
            }
        } else {
            fprintf(stderr, "Failed to read flow rate.\n");
        }

        // Wait for the next measurement interval
        gpioDelay(MEASUREMENT_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }
    return 0;
}

// Read flow rate from the sensor
int read_flow_rate(uint16_t *raw_value) {
    uint8_t buffer[3];
    int result;

    // Read 3 bytes from the sensor
    result = i2cReadDevice(i2c_handle, (char *)buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Validate CRC
    if (validate_crc(buffer, 2, buffer[2]) != 0) {
        fprintf(stderr, "CRC validation failed.\n");
        return 1;
    }

    // Combine the two bytes into a 16-bit value
    *raw_value = (buffer[0] << 8) | buffer[1];

    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
