int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
SensorData read_sensor_data() {
    SensorData data;
    unsigned char buffer[4];
    int result;

    // Read 4 bytes from the sensor
    result = i2cReadDevice(i2c_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        data.tvoc = -1.0; // Indicate error
        data.eco2 = -1.0;
        return data;
    }

    // Convert the bytes to TVOC and eCO2 values
    // Assuming TVOC is in bytes 0-1 and eCO2 in bytes 2-3 (adjust as needed)
    unsigned int tvoc_raw = (buffer[0] << 8) | buffer[1];
    unsigned int eco2_raw = (buffer[2] << 8) | buffer[3];

    // Apply scaling factors (adjust based on sensor datasheet)
    data.tvoc = (float)tvoc_raw / 10.0; // Example scaling
    data.eco2 = (float)eco2_raw / 10.0; // Example scaling

    return data;
}

// Function to calculate IAQ index
float calculate_iaq(float tvoc, float eco2) {
    // Simple linear combination (adjust weights as needed)
    return 0.5 * tvoc + 0.5 * eco2;
}

