int log_data(float iaq, float tvoc, float eco2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, iaq, tvoc, eco2);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        SensorData sensor_data = read_sensor_data();

        if (sensor_data.tvoc >= 0.0 && sensor_data.eco2 >= 0.0) {
            float iaq = calculate_iaq(sensor_data.tvoc, sensor_data.eco2);
            log_data(iaq, sensor_data.tvoc, sensor_data.eco2);
            printf("IAQ: %.2f, TVOC: %.2f ppb, eCO2: %.2f ppm\n", iaq, sensor_data.tvoc, sensor_data.eco2);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, READ_INTERVAL_SEC, 0); // Sleep for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

