#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 17
#define ALERT_DURATION 5.0 // seconds
#define POLL_INTERVAL 0.1 // seconds

static volatile int running = 1;
static volatile double alert_start_time = 0.0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to read the sensor value
int read_sensor() {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to check for intrusion
void check_intrusion() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double current_time = ts.tv_sec + ts.tv_nsec / 1000000000.0;

    if (read_sensor() == 1) {
        if (alert_start_time == 0.0) {
            alert_start_time = current_time;
        } else if (current_time - alert_start_time >= ALERT_DURATION) {
            printf("Intrusion detected!\n");
            alert_start_time = 0.0; // Reset timer after alert
        }
    } else {
        alert_start_time = 0.0; // Reset timer if sensor is released
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    printf("Tamper detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        check_intrusion();
        gpioDelay(POLL_INTERVAL * 1000000); // pigpioDelay takes microseconds
    }

    // Cleanup
    gpioTerminate();
    printf("pigpio terminated.\n");

    return EXIT_SUCCESS;
}

