#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

#define ALSA_DEVICE "default" // Or "hw:1,0" if needed
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define SAMPLE_SIZE 16 // bits
#define GPIO_PIN 17
#define BUFFER_SIZE 4096

static volatile int keep_running = 1;
static int audio_fd = -1;
static snd_pcm_t *pcm_handle = NULL;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
    keep_running = 0;
}

// Function to initialize ALSA
int init_alsa(snd_pcm_t **pcm_handle) {
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(pcm_handle, ALSA_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening ALSA device %s: %s\n", ALSA_DEVICE, snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_prepare(*pcm_handle)) < 0) {
        fprintf(stderr, "Error preparing PCM: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Set GPIO low to select left channel
    return 0;
}

// Function to capture audio and write to file
int capture_audio(snd_pcm_t *pcm_handle, int audio_fd) {
    char buffer[BUFFER_SIZE];
    int frames;
    int err;

    frames = BUFFER_SIZE / (NUM_CHANNELS * (SAMPLE_SIZE / 8));

    while (keep_running) {
        err = snd_pcm_readi(pcm_handle, buffer, frames);
        if (err == -EPIPE) {
            /* EPIPE means overrun */
            fprintf(stderr, "overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err < 0) {
            fprintf(stderr, "Error reading PCM: %s\n", snd_strerror(err));
            return -1;
        } else if (err != frames) {
            fprintf(stderr, "Short read, read %d frames\n", err);
        } else {
            if (write(audio_fd, buffer, BUFFER_SIZE) != BUFFER_SIZE) {
                fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
                return -1;
            }
        }
    }

    return 0;
}

// Function to cleanup resources
void cleanup(snd_pcm_t *pcm_handle, int audio_fd) {
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
    if (audio_fd != -1) {
        close(audio_fd);
    }
    gpioWrite(GPIO_PIN, 0); // Set GPIO low
    gpioTerminate();
}

int main() {
    signal(SIGINT, signal_handler);

    if (init_gpio() != 0) {
        return 1;
    }

    if (init_alsa(&pcm_handle) != 0) {
        cleanup(NULL, -1);
        return 1;
    }

    audio_fd = open("audio_capture.pcm", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (audio_fd == -1) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        cleanup(pcm_handle, -1);
        return 1;
    }

    if (capture_audio(pcm_handle, audio_fd) != 0) {
        cleanup(pcm_handle, audio_fd);
        return 1;
    }

    cleanup(pcm_handle, audio_fd);

    fprintf(stderr, "Audio capture complete.\n");
    return 0;
}

