#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define debounce time (milliseconds)
#define DEBOUNCE_TIME 50

// Define sensor timeout (seconds)
#define SENSOR_TIMEOUT 5

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int state);
void log_event(const char *event_type);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int flame_detected;
    time_t last_valid_reading;
} ProgramState;

ProgramState state = {0, 0};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    log_event("System Start");

    // Main loop
    while (running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0) { // Flame detected (LOW signal)
            if (!state.flame_detected) {
                log_event("Flame Detected");
                control_fan(1); // Turn on fan
                state.flame_detected = 1;
                state.last_valid_reading = time(NULL);
            }
        } else if (sensor_value == 1) { // No flame (HIGH signal)
            if (state.flame_detected) {
                log_event("Flame Ended");
                control_fan(0); // Turn off fan
                state.flame_detected = 0;
            }
            state.last_valid_reading = time(NULL);
        } else {
            // Error reading sensor
            fprintf(stderr, "Error reading flame sensor.\n");
        }

        // Check for sensor timeout
        if (state.flame_detected && (time(NULL) - state.last_valid_reading > SENSOR_TIMEOUT)) {
            fprintf(stderr, "Sensor timeout. Assuming sensor failure.\n");
            log_event("Sensor Timeout");
            control_fan(0); // Turn off fan
            state.flame_detected = 0;
        }

        gpioDelay(50); // Check every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);

    return 0;
}

// Read flame sensor with debouncing
int read_flame_sensor() {
    int reading = gpioRead(FLAME_SENSOR_PIN);
    if (reading < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", FLAME_SENSOR_PIN);
        return -1; // Indicate error
    }

    gpioDelay(DEBOUNCE_TIME); // Debounce

    int debounced_reading = gpioRead(FLAME_SENSOR_PIN);
    if (debounced_reading < 0) {
        fprintf(stderr, "Error reading GPIO %d during debounce\n", FLAME_SENSOR_PIN);
        return -1; // Indicate error
    }

    return debounced_reading;
}

// Control the cooling fan using PWM
void control_fan(int state) {
    if (state) {
        gpioPWM(FAN_PIN, 128); // 50% duty cycle (128/255)
    } else {
        gpioPWM(FAN_PIN, 0); // Turn off fan
    }
}

// Log events to file
void log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(log_file, "%s: %s\n", buf, event_type);
    fflush(log_file); // Ensure immediate write
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d. Shutting down...\n", signal);
    running = 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    control_fan(0); // Turn off fan
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
    log_event("System Shutdown");
}

