#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define FRAME_SIZE 32768
#define LOG_FILE "radar_data.bin"
#define MAGIC_NUMBER 4144

// Define GPIO pins
#define FRAME_TRIGGER_PIN 23
#define DATA_READY_PIN 24

// Define configuration struct
typedef struct {
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint16_t chirps;
    uint16_t samples;
} radar_config_t;

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int initialize_gpio();
int initialize_logging();
int configure_radar(radar_config_t *config);
int trigger_frame();
int read_frame(uint8_t *frame_data);
int log_frame(uint8_t *frame_data, radar_config_t *config);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    gpioSetMode(FRAME_TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(DATA_READY_PIN, PI_INPUT);
    gpioSetPullUpDown(DATA_READY_PIN, PI_PUD_DOWN); // Pull-down resistor

    // Set interrupt callback for data ready pin
    if (gpioSetAlertFunc(DATA_READY_PIN, trigger_frame) != 0) {
        fprintf(stderr, "Failed to set alert function for DATA_READY_PIN\n");
        return -1;
    }

    return 0;
}

// Initialize logging
int initialize_logging() {
    log_file = fopen(LOG_FILE, "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    // Write header
    uint32_t magic = MAGIC_NUMBER;
    fwrite(&magic, sizeof(uint32_t), 1, log_file);

    radar_config_t config = {77, 79, 64, 256};
    fwrite(&config, sizeof(radar_config_t), 1, log_file);

    return 0;
}

// Configure radar (Placeholder - replace with actual SDK calls)
int configure_radar(radar_config_t *config) {
    // In a real application, this function would use the TI mmWave SDK
    // to configure the radar sensor with the specified parameters.
    // For this example, we just print the configuration.
    printf("Configuring radar:\n");
    printf("  Start Frequency: %u GHz\n", config->start_frequency);
    printf("  End Frequency: %u GHz\n", config->end_frequency);
    printf("  Chirps: %u\n", config->chirps);
    printf("  Samples: %u\n", config->samples);
    return 0;
}

// Trigger a frame
int trigger_frame() {
    gpioWrite(FRAME_TRIGGER_PIN, 1); // Set high
    gpioDelay(1); // Short pulse
    gpioWrite(FRAME_TRIGGER_PIN, 0); // Set low
    return 0;
}

// Read a frame of data
int read_frame(uint8_t *frame_data) {
    int bytes_read = spiRead(spi_handle, frame_data, FRAME_SIZE);
    if (bytes_read != FRAME_SIZE) {
        fprintf(stderr, "SPI read failed: %d bytes read (expected %d)\n", bytes_read, FRAME_SIZE);
        return -1;
    }
    return 0;
}

// Log a frame of data
int log_frame(uint8_t *frame_data, radar_config_t *config) {
    time_t timestamp = time(NULL);
    fwrite(&timestamp, sizeof(time_t), 1, log_file);
    uint32_t frame_number = 0; // Replace with actual frame number if available
    fwrite(&frame_number, sizeof(uint32_t), 1, log_file);
    fwrite(frame_data, sizeof(uint8_t), FRAME_SIZE, log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    // Configure radar
    radar_config_t config = {77, 79, 64, 256};
    if (configure_radar(&config) != 0) {
        cleanup();
        return 1;
    }

    uint8_t *frame_data = (uint8_t *)malloc(FRAME_SIZE);
    if (frame_data == NULL) {
        fprintf(stderr, "Failed to allocate memory for frame data\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger frame
        if (trigger_frame() != 0) {
            fprintf(stderr, "Failed to trigger frame\n");
        }

        // Wait for data ready interrupt (handled by callback)

        // Read frame
        if (read_frame(frame_data) != 0) {
            fprintf(stderr, "Failed to read frame\n");
        }

        // Log frame
        if (log_frame(frame_data, &config) != 0) {
            fprintf(stderr, "Failed to log frame\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Free memory
    free(frame_data);

    // Cleanup resources
    cleanup();

    return 0;
}

