#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 20
#define LOG_FILE "flame_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the flame state to a file
int log_flame_state(const char *timestamp, int state) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    const char *state_str = (state == 0) ? "Flame Detected" : "Flame Cleared";
    if (fprintf(log_file, "%s %s\n", timestamp, state_str) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    int current_state = -1; // Initialize to an invalid state
    int previous_state = -1;
    int gpio_status;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO20 as an input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read the current state of the flame sensor
        current_state = gpioRead(GPIO_PIN);
        gpio_status = gpioGetLastError();

        if (gpio_status != PI_INIT_FAILED) {
            if (current_state != previous_state) {
                // State has changed, log the event
                char *timestamp = get_iso8601_timestamp();
                if (timestamp != NULL) {
                    if (log_flame_state(timestamp, current_state) != 0) {
                        fprintf(stderr, "Error logging flame state.\n");
                    }
                    free(timestamp);
                } else {
                    fprintf(stderr, "Error getting timestamp.\n");
                }
                previous_state = current_state;
            }
        } else {
            fprintf(stderr, "pigpio error: %d\n", gpio_status);
            running = 0; // Exit loop on pigpio error
        }

        gpioDelay(100); // Wait 100ms
    }

    // Clean up resources before exiting
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

