#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define LUX_DATA_LEN 2
#define CONFIG_VALUE 0xCB01 // Continuous conversion mode, auto range
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SLEEP_MS 100

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
FILE *data_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int config_opt3001();
int read_lux(float *lux);
int write_data_to_file(float lux);
void signal_handler(int signal);
void cleanup();

// Structure for grouping sensor data (optional)
typedef struct {
    float lux;
    time_t timestamp;
} sensor_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Configure OPT3001
    if (config_opt3001() != 0) {
        fprintf(stderr, "OPT3001 configuration failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Open data file
    data_file = fopen("light_data.txt", "a");
    if (data_file == NULL) {
        perror("Failed to open data file");
        cleanup();
        return 1;
    }

    float lux;
    // Main loop
    while (!terminate) {
        if (read_lux(&lux) == 0) {
            if (write_data_to_file(lux) != 0) {
                fprintf(log_file, "Error writing data to file\n");
                fflush(log_file);
            }
        } else {
            fprintf(log_file, "Error reading lux value\n");
            fflush(log_file);
        }
        gpioDelay(SLEEP_MS * 1000); // Sleep for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure OPT3001
int config_opt3001() {
    char buf[2];
    buf[0] = CONFIG_REG;
    buf[1] = CONFIG_VALUE & 0xFF; //LSB
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write config register: %d\n", result);
        return 1;
    }
    return 0;
}

// Read lux value from OPT3001
int read_lux(float *lux) {
    char buf[1];
    char data[LUX_DATA_LEN];
    int result;

    buf[0] = RESULT_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write result register address: %d\n", result);
        return 1;
    }

    gpioDelay(10); // Wait for conversion

    result = i2cReadDevice(i2c_handle, data, LUX_DATA_LEN);
    if (result != LUX_DATA_LEN) {
        fprintf(stderr, "Failed to read result register: %d\n", result);
        return 1;
    }

    uint16_t raw_result = (data[0] << 8) | data[1];
    *lux = (float)raw_result * 0.01; // Simplified conversion

    return 0;
}

// Write data to file
int write_data_to_file(float lux) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(data_file, "%s,%.2f\n", buf, lux);
    fflush(data_file);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(log_file, "Received signal %d, terminating...\n", signal);
    fflush(log_file);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    gpioTerminate();
}

