#define FLAME_SENSOR_GPIO 17

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int main() {
    int rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", rc);
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO %d\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %d\n", FLAME_SENSOR_GPIO, sensor_value);
            break; // Exit loop on read error
        }

        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (sensor_value == 0) {
            printf("%s Flame Detected: YES\n", timestamp);
        } else {
            printf("%s Flame Detected: NO\n", timestamp);
        }

        gpioDelay(1000); // Wait for 1 second
    }

    gpioTerminate();
    return 0;
}

