#include <pigpio.h>

// Define the GPIO pins connected to the TTP226 sensor channels
const int sensor_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = 8;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the sensor data
int read_sensor_data(int *data) {
    for (int i = 0; i < num_channels; ++i) {
        data[i] = gpioRead(sensor_pins[i]);
        if (data[i] < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", sensor_pins[i]);
            return -1; // Indicate an error
        }
    }
    return 0; // Indicate success
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs with pull-down resistors
    for (int i = 0; i < num_channels; ++i) {
        gpioSetMode(sensor_pins[i], PI_INPUT);
        gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN);
    }

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to read and print sensor data
    int sensor_data[num_channels];
    int sample_count = 0;
    while (program_running) {
        // Read the sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Print the sensor data to the console
            printf("[%+4d ms] ", sample_count * 100);
            for (int i = 0; i < num_channels; ++i) {
                printf("CH%d=%d ", i + 1, sensor_data[i]);
            }
            printf("\n");
        } else {
            fprintf(stderr, "Error reading sensor data, exiting...\n");
            program_running = 0; // Exit the loop on error
        }

        // Increment the sample count
        sample_count++;

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

