#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TILT_PIN 4 // BCM GPIO 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nExiting gracefully...\n");
    }
}

int main() {
    int current_state, previous_state = -1; // Initialize to an invalid state
    int rc;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO4 as an input with pull-up resistor
    gpioSetMode(TILT_PIN, PI_INPUT);
    gpioSetPullUpDown(TILT_PIN, PI_PUD_UP);

    // Print startup banner
    printf("Tilt Sensor Monitoring Program\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the state of the tilt sensor
        current_state = gpioRead(TILT_PIN);
        rc = gpioRead(TILT_PIN); // Read the pin again to check for errors
        if (rc < 0) {
            fprintf(stderr, "Error reading GPIO %d: %d\n", TILT_PIN, rc);
            gpioTerminate();
            return 1;
        }

        // Check if the state has changed
        if (current_state != previous_state) {
            fflush(stdout); // Flush stdout

            if (current_state == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }

            previous_state = current_state;
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    return 0;
}

