#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define ALARM_GPIO 17
#define FLOW_THRESHOLD 0.5
#define LOG_FILE "flow_log.txt"
#define START_COMMAND_SIZE 2
#define FLOW_DATA_SIZE 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int handle;
    float flow_rate;
    int valid;
} sensor_data_t;

// Function prototypes
void signal_handler(int signal);
int initialize();
void cleanup();
int start_sensor(int handle);
int read_sensor_data(int handle, uint8_t *data);
float calculate_flow_rate(uint8_t *data);
uint8_t crc8(const uint8_t *data, size_t len);
void log_data(float flow_rate);
void control_alarm(float flow_rate);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio, I2C, and GPIO
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Initially low

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
}

// Start the sensor
int start_sensor(int handle) {
    uint8_t start_command[START_COMMAND_SIZE] = {0x36, 0x08};
    int result = i2cWriteDevice(handle, (char *)start_command, START_COMMAND_SIZE);
    if (result != 0) {
        fprintf(stderr, "Failed to send start command: %d\n", result);
        return 1;
    }
    gpioDelay(100); // Wait 100ms
    return 0;
}

// Read flow data from the sensor
int read_sensor_data(int handle, uint8_t *data) {
    int result = i2cReadDevice(handle, (char *)data, FLOW_DATA_SIZE);
    if (result != FLOW_DATA_SIZE) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return 1;
    }
    return 0;
}

// Calculate flow rate from raw data
float calculate_flow_rate(uint8_t *data) {
    int16_t raw_flow = (data[0] << 8) | data[1];
    return (float)raw_flow / 100.0; // ml/min
}

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Log flow rate to file
void log_data(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f ml/min\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written immediately
}

// Control the alarm based on flow rate
void control_alarm(float flow_rate) {
    if (flow_rate < FLOW_THRESHOLD) {
        gpioWrite(ALARM_GPIO, 1); // High
    } else {
        gpioWrite(ALARM_GPIO, 0); // Low
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    uint8_t sensor1_data[FLOW_DATA_SIZE];
    uint8_t sensor2_data[FLOW_DATA_SIZE];
    float flow_rate1, flow_rate2, avg_flow_rate;
    int sensor1_valid, sensor2_valid;

    // Start both sensors
    if (start_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Failed to start sensor 1\n");
    }
    if (start_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Failed to start sensor 2\n");
    }

    while (!terminate) {
        sensor1_valid = 1;
        sensor2_valid = 1;

        // Read sensor 1
        if (read_sensor_data(i2c_handle, sensor1_data) == 0) {
            uint8_t crc = crc8(sensor1_data, FLOW_DATA_SIZE - 1);
            if (crc != sensor1_data[FLOW_DATA_SIZE - 1]) {
                fprintf(stderr, "CRC check failed for sensor 1\n");
                sensor1_valid = 0;
            } else {
                flow_rate1 = calculate_flow_rate(sensor1_data);
            }
        } else {
            sensor1_valid = 0;
        }

        // Read sensor 2
        if (read_sensor_data(i2c_handle, sensor2_data) == 0) {
            uint8_t crc = crc8(sensor2_data, FLOW_DATA_SIZE - 1);
            if (crc != sensor2_data[FLOW_DATA_SIZE - 1]) {
                fprintf(stderr, "CRC check failed for sensor 2\n");
                sensor2_valid = 0;
            } else {
                flow_rate2 = calculate_flow_rate(sensor2_data);
            }
        } else {
            sensor2_valid = 0;
        }

        // Calculate average flow rate
        int valid_count = 0;
        float total_flow = 0.0;
        if (sensor1_valid) {
            total_flow += flow_rate1;
            valid_count++;
        }
        if (sensor2_valid) {
            total_flow += flow_rate2;
            valid_count++;
        }

        if (valid_count > 0) {
            avg_flow_rate = total_flow / valid_count;
        } else {
            avg_flow_rate = 0.0; // Or some other default value
        }

        // Log data and control alarm
        log_data(avg_flow_rate);
        control_alarm(avg_flow_rate);

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

