#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100

// Structure to hold the circular buffer and its index
typedef struct {
    int buffer[BUFFER_SIZE];
    int index;
} CircularBuffer;

CircularBuffer obstacle_buffer;

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(int value);
void print_buffer();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize the circular buffer
    obstacle_buffer.index = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        obstacle_buffer.buffer[i] = 0; // Initialize to no obstacle
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    printf("Obstacle avoidance sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) { // Obstacle detected (LOW signal)
            add_to_buffer(1); // Add 1 to buffer
            printf("Obstacle detected!\n");
        } else {
            add_to_buffer(0); // Add 0 to buffer
        }

        gpioDelay(50); // Sample every 50ms
    }

    // Print the contents of the circular buffer before exiting
    print_buffer();

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Function to initialize the pigpio library and configure the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
