#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define D7S_ADDR 0x4C
#define MODE_REG 0x10
#define X_REG 0x28
#define Y_REG 0x2A
#define Z_REG 0x2C
#define DATA_LENGTH 6
#define RETRY_DELAY_MS 10
#define POLLING_INTERVAL_MS 500
#define TIMEOUT_MS 1000

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_bytes(int handle, uint8_t reg, char *buf, int count);
int i2c_write_byte(int handle, uint8_t reg, uint8_t value);
int read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z);
int write_mode(int handle, uint8_t mode);
int check_sensor_status(int handle);
void signal_handler(int signal);
int open_i2c_device(int bus, int addr);
int open_csv_file(const char *filename);
void close_resources();

// I2C read function with retry
int i2c_read_bytes(int handle, uint8_t reg, char *buf, int count) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadI2CBlockData(handle, reg, buf, count);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "I2C read error: %s (reg 0x%02X, count %d), retrying...\n", strerror(errno), reg, count);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X, count %d)\n", reg, count);
    return -1; // Indicate failure
}

// I2C write function with retry
int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0;
        } else {
            fprintf(stderr, "I2C write error: %s (reg 0x%02X, value 0x%02X), retrying...\n", strerror(errno), reg, value);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, value 0x%02X)\n", reg, value);
    return -1; // Indicate failure
}

// Read acceleration data
int read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[DATA_LENGTH];
    int result = i2c_read_bytes(handle, X_REG, buf, DATA_LENGTH);
    if (result != DATA_LENGTH) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Write mode register
int write_mode(int handle, uint8_t mode) {
    return i2c_write_byte(handle, MODE_REG, mode);
}

// Check sensor status
int check_sensor_status(int handle) {
    int retries = TIMEOUT_MS / RETRY_DELAY_MS;
    int result;

    while (retries > 0) {
        char buf[2];
        result = i2c_read_bytes(handle, MODE_REG, buf, 2);
        if (result == 2) {
            uint8_t mode = buf[1];
            if (mode == 0x01) {
                return 0; // Sensor is active
            }
        } else {
            fprintf(stderr, "Failed to read mode register, retrying...\n");
        }
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries--;
    }
    fprintf(stderr, "Sensor did not become active within timeout\n");
    return -1; // Sensor not active
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Open I2C device
int open_i2c_device(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Open CSV file
int open_csv_file(const char *filename) {
    FILE *fp = fopen(filename, "a+");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,X,Y,Z\n");
    }

    rewind(fp);
    return (int)(intptr_t)fp; // Cast FILE* to int for return
}

// Close resources
void close_resources() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c_device(I2C_BUS, D7S_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    fp = (FILE*)open_csv_file("fan_health.csv");
    if (fp == NULL) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Write mode register to switch to active mode
    if (write_mode(i2c_handle, 0x01) != 0) {
        fprintf(stderr, "Failed to write mode register\n");
        close_resources();
        return 1;
    }

    // Check sensor status
    if (check_sensor_status(i2c_handle) != 0) {
        fprintf(stderr, "Sensor did not become active\n");
        close_resources();
        return 1;
    }

    // Main loop
    int16_t x, y, z;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            // Get timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

            // Write data to CSV file
            fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
            fflush(fp); // Ensure data is written to disk
        } else {
            fprintf(stderr, "Failed to read acceleration data in main loop\n");
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Close resources before exiting
    close_resources();
    return 0;
}

