    }

    // Check if the last line in the file is the same as the current timestamp
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size > 0) {
        fseek(log_file, -1, SEEK_END);
        while (ftell(log_file) > 0 && fgetc(log_file) != '\n') {
