#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// TMAG5170-Q1 I2C address
#define TMAG5170_ADDR 0x0E

// TMAG5170-Q1 Register Addresses
#define REG_XOUT_L 0x00
#define REG_XOUT_H 0x01
#define REG_YOUT_L 0x02
#define REG_YOUT_H 0x03
#define REG_ZOUT_L 0x04
#define REG_ZOUT_H 0x05
#define REG_CTRL1 0x0B

// Configuration values
#define CONTINUOUS_MODE 0x01 // Continuous conversion mode
#define RANGE_50MT 0x00       // +/- 50 mT range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
char* get_iso8601_timestamp();
int log_data(sensor_data_t data, char* timestamp);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the sensor
int initialize_sensor() {
    // Configure CTRL1 register for continuous mode and 50mT range
    uint8_t config_data[2];
    config_data[0] = REG_CTRL1;
    config_data[1] = (CONTINUOUS_MODE << 1) | RANGE_50MT; // Set continuous mode and range

    int result = i2cWriteDevice(i2c_handle, (char *)config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to CTRL1 register: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[6];

    int result = i2cReadI2CBlockData(i2c_handle, REG_XOUT_L, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        data.x = 0.0; // Set default values in case of error
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes for each axis
    int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw values to milliTesla (mT) - Adjust scale factor as needed
    data.x = (float)x_raw * 0.00014; // Example scale factor, check datasheet
    data.y = (float)y_raw * 0.00014;
    data.z = (float)z_raw * 0.00014;

    return data;
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log data to CSV file
int log_data(sensor_data_t data, char* timestamp) {
    // Check if the file is newly created by checking its size
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    fseek(log_file, 0, SEEK_SET);

    if (file_size == 0) {
        // Write header row if the file is newly created
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }

    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Flush the buffer to ensure data is written to the file

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t data = read_sensor_data();

        // Get timestamp
        char* timestamp = get_iso8601_timestamp();

        // Log data
        log_data(data, timestamp);

        // Free the allocated memory for timestamp
        free(timestamp);

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Clean up resources
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

