            fprintf(stderr, "Failed to read GPIO pin, attempting re-initialization in 60 seconds...\n");
            gpioTerminate();
            sleep(60);
            if (gpioInitialise() < 0) {
                fprintf(stderr, "pigpio re-initialisation failed\n");
                log_message("ERROR: pigpio re-initialisation failed");
