#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"

static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold program state
typedef struct {
    int gpio_pin;
    char *log_file_name;
} program_state_t;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);
int initialize_gpio();
int open_log_file();
void log_rpm(int rpm);
void cleanup();
char* get_iso8601_timestamp();

// Pulse counter function (called by interrupt)
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

