        perror("Failed to open log file");
        return -1;
    }
    return 0;
}

// Log RPM to file and stdout
void log_rpm(int rpm) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp\n");
        return;
    }

    fprintf(log_file, "%s %d\n", timestamp, rpm);
    fflush(log_file);
    printf("%s %d\n", timestamp, rpm);
    free(timestamp);
}

