void cleanup() {
    printf("Cleaning up resources...\n");
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

