#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the quadrature state enum
typedef enum {
    STATE_00,
    STATE_01,
    STATE_10,
    STATE_11
} QuadratureState;

// Define the rotation direction enum
typedef enum {
    CLOCKWISE,
    COUNTER_CLOCKWISE,
    UNKNOWN
} RotationDirection;

// Define the interrupt handler function type
typedef void (*InterruptHandler)(int gpio, int level, uint32_t tick, void *user);

// Global variables
static FILE *log_file = NULL;
static QuadratureState current_state = STATE_00;
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t state_cond = PTHREAD_COND_INITIALIZER;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
RotationDirection determine_rotation_direction(QuadratureState previous_state, QuadratureState current_state);
int log_rotation_event(RotationDirection direction);
void *main_loop(void *arg);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", signal);
    terminate = 1;
    pthread_cond_signal(&state_cond); // Wake up the main loop
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)user; // Suppress unused parameter warning
    (void)tick; // Suppress unused parameter warning

    QuadratureState previous_state;
    pthread_mutex_lock(&state_mutex);
    previous_state = current_state;

    if (gpio == SENSOR_A_GPIO) {
        if (level == 1) {
            current_state = (current_state == STATE_00) ? STATE_01 : ((current_state == STATE_01) ? STATE_11 : ((current_state == STATE_11) ? STATE_10 : STATE_00));
        } else {
            current_state = (current_state == STATE_00) ? STATE_10 : ((current_state == STATE_10) ? STATE_11 : ((current_state == STATE_11) ? STATE_01 : STATE_00));
        }
    } else if (gpio == SENSOR_B_GPIO) {
        if (level == 1) {
            current_state = (current_state == STATE_00) ? STATE_10 : ((current_state == STATE_10) ? STATE_00 : ((current_state == STATE_11) ? STATE_01 : STATE_11));
        } else {
            current_state = (current_state == STATE_00) ? STATE_11 : ((current_state == STATE_11) ? STATE_00 : ((current_state == STATE_01) ? STATE_10 : STATE_01));
        }
    }

    pthread_mutex_unlock(&state_mutex);
    pthread_cond_signal(&state_cond); // Signal the main loop
}

// Function to determine the rotation direction
RotationDirection determine_rotation_direction(QuadratureState previous_state, QuadratureState current_state) {
    if (previous_state == STATE_00 && current_state == STATE_01) return CLOCKWISE;
    if (previous_state == STATE_01 && current_state == STATE_11) return CLOCKWISE;
    if (previous_state == STATE_11 && current_state == STATE_10) return CLOCKWISE;
    if (previous_state == STATE_10 && current_state == STATE_00) return CLOCKWISE;

    if (previous_state == STATE_00 && current_state == STATE_10) return COUNTER_CLOCKWISE;
    if (previous_state == STATE_10 && current_state == STATE_00) return COUNTER_CLOCKWISE;
    if (previous_state == STATE_11 && current_state == STATE_01) return COUNTER_CLOCKWISE;
    if (previous_state == STATE_01 && current_state == STATE_00) return COUNTER_CLOCKWISE;

    return UNKNOWN;
}

// Function to log the rotation event
int log_rotation_event(RotationDirection direction) {
    struct timespec ts;
    char timestamp[30];
    struct tm tm_info;

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    const char *direction_str;
    switch (direction) {
        case CLOCKWISE:
            direction_str = "CLOCKWISE";
            break;
        case COUNTER_CLOCKWISE:
            direction_str = "COUNTER_CLOCKWISE";
            break;
        default:
            direction_str = "UNKNOWN";
            break;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, direction_str) < 0) {
        perror("fprintf");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Main loop function (runs in a separate thread)
void *main_loop(void *arg) {
    (void)arg; // Suppress unused parameter warning
    QuadratureState previous_state;
    RotationDirection direction;

    while (!terminate) {
        pthread_mutex_lock(&state_mutex);
        pthread_cond_wait(&state_cond, &state_mutex); // Wait for a signal

        previous_state = current_state;

        direction = determine_rotation_direction(previous_state, current_state);

        if (direction != UNKNOWN) {
            if (log_rotation_event(direction) != 0) {
                fprintf(stderr, "Error logging rotation event.\n");
            }
        }

        pthread_mutex_unlock(&state_mutex);
    }

    pthread_exit(NULL);
}

int main() {
    pthread_t main_thread;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes and pull-up resistors
    gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_B_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handlers
    if (gpioSetISRFuncEx(SENSOR_A_GPIO, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting ISR for SENSOR_A_GPIO\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(SENSOR_A_GPIO, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting ISR for SENSOR_A_GPIO\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(SENSOR_B_GPIO, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting ISR for SENSOR_B_GPIO\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(SENSOR_B_GPIO, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting ISR for SENSOR_B_GPIO\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Create the main loop thread
    result = pthread_create(&main_thread, NULL, main_loop, NULL);
    if (result != 0) {
        fprintf(stderr, "Error creating main loop thread: %d\n", result);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Wait for termination signal
    pthread_join(main_thread, NULL);

    // Clean up
    fclose(log_file);
    gpioTerminate();

    return 0;
}

