// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    syslog(LOG_INFO, "GPIO initialisation complete");
    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    syslog(LOG_INFO, "GPIO cleanup complete");
}

