#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 17
#define LED_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variable to track LED state
static volatile int led_state = 0;

// Global variable to track pigpio initialization status
static volatile int pigpio_initialized = 0;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void touch_callback(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Callback function for touch sensor events
void touch_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge detected
        led_state = !led_state; // Toggle LED state
        gpioWrite(LED_PIN, led_state); // Set LED state
        gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    pigpio_initialized = 1;

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin as output\n");
        gpioTerminate();
        return -1;
    }

    // Set touch sensor pin as input
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set touch sensor pin as input\n");
        gpioTerminate();
        return -1;
    }

    // Set initial LED state to LOW
    gpioWrite(LED_PIN, 0);

    // Set up interrupt on touch sensor pin
    if (gpioSetAlertFuncEx(TOUCH_SENSOR_PIN, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set up interrupt on touch sensor pin\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    if (pigpio_initialized) {
        gpioWrite(LED_PIN, 0); // Turn off LED
        gpioTerminate(); // Terminate pigpio
        pigpio_initialized = 0;
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Touch sensor and LED control started. Press Ctrl+C to exit.\n");

    // Keep the program running until a signal is received
    while (1) {
        sleep(1); // Sleep to reduce CPU usage
    }

    return 0;
}

