#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define log entry structure
typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} log_entry_t;

// Define circular buffer structure
typedef struct {
    log_entry_t entries[100];
    int head;
    int count;
    int overflow_count;
} circular_buffer_t;

// Global variables
circular_buffer_t log_buffer;
int running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
void set_led(int gpio_pin, int state);
void log_event(int sensor_pin, int state);
void print_log_buffer();
void signal_handler(int signal);
void initialize_buffer(circular_buffer_t *buffer);

// Function to initialize the circular buffer
void initialize_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
    buffer->overflow_count = 0;
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to set LED state
void set_led(int gpio_pin, int state) {
    int result = gpioWrite(gpio_pin, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to LED on GPIO %d: %d\n", gpio_pin, result);
    }
}

// Function to log event
void log_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    log_entry_t new_entry;
    new_entry.sensor_pin = sensor_pin;
    new_entry.timestamp = now;
    new_entry.state = state;

    log_buffer.entries[log_buffer.head] = new_entry;
    log_buffer.head = (log_buffer.head + 1) % 100;

    if (log_buffer.count < 100) {
        log_buffer.count++;
    } else {
        log_buffer.overflow_count++;
    }
}

// Function to print log buffer
void print_log_buffer() {
    printf("Log Buffer Contents:\n");
    int start_index = (log_buffer.count == 100) ? log_buffer.head : 0;
    for (int i = 0; i < log_buffer.count; i++) {
        int index = (start_index + i) % 100;
        printf("Sensor Pin: %d, Timestamp: %ld, State: %d\n",
               log_buffer.entries[index].sensor_pin,
               log_buffer.entries[index].timestamp,
               log_buffer.entries[index].state);
    }
    printf("Overflow Count: %d\n", log_buffer.overflow_count);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(LED_1_PIN, PI_OUTPUT);
    gpioSetMode(LED_2_PIN, PI_OUTPUT);

    // Initialize circular buffer
    initialize_buffer(&log_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int sensor1_state = 0;
    int sensor2_state = 0;
    while (running) {
        // Read sensor values
        int new_sensor1_state = read_sensor(SENSOR_1_PIN);
        int new_sensor2_state = read_sensor(SENSOR_2_PIN);

        if (new_sensor1_state < 0 || new_sensor2_state < 0) {
            // Error reading sensor, continue to next iteration
            gpioDelay(50); // Debounce delay
            continue;
        }

        // Debounce and update LED states
        if (new_sensor1_state != sensor1_state) {
            gpioDelay(50); // Debounce delay
            new_sensor1_state = read_sensor(SENSOR_1_PIN);
            if (new_sensor1_state == sensor1_state) {
                continue; // Debounce failed
            }
            sensor1_state = new_sensor1_state;
            set_led(LED_1_PIN, sensor1_state);
            log_event(SENSOR_1_PIN, sensor1_state);
        }

        if (new_sensor2_state != sensor2_state) {
            gpioDelay(50); // Debounce delay
            new_sensor2_state = read_sensor(SENSOR_2_PIN);
            if (new_sensor2_state == sensor2_state) {
                continue; // Debounce failed
            }
            sensor2_state = new_sensor2_state;
            set_led(LED_2_PIN, sensor2_state);
            log_event(SENSOR_2_PIN, sensor2_state);
        }

        gpioDelay(50); // Loop delay
    }

    // Shutdown sequence
    set_led(LED_1_PIN, 0);
    set_led(LED_2_PIN, 0);
    gpioTerminate();

    // Print log buffer
    print_log_buffer();

    return 0;
}

