#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

// Function prototypes
int initialize_gpio();
SensorStates read_sensors();
void log_data(SensorStates states);
double calculate_rpm(SensorStates current_states, SensorStates previous_states, double time_diff);
void print_rpm(double rpm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    return 0; // Indicate success
}

// Function to read the states of the Hall-Effect sensors
SensorStates read_sensors() {
    SensorStates states;
    states.sensor1_state = gpioRead(SENSOR1_GPIO);
    states.sensor2_state = gpioRead(SENSOR2_GPIO);
    return states;
}

// Function to log the sensor data to a CSV file
void log_data(SensorStates states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, states.sensor1_state, states.sensor2_state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to calculate the RPM based on sensor state changes
double calculate_rpm(SensorStates current_states, SensorStates previous_states, double time_diff) {
    int state_changes = 0;

    if (current_states.sensor1_state != previous_states.sensor1_state) {
        state_changes++;
    }
    if (current_states.sensor2_state != previous_states.sensor2_state) {
        state_changes++;
    }

    // Each state change represents a quarter rotation (90 degrees)
    double rotations_per_second = (double)state_changes / 4.0;
    double rpm = rotations_per_second * 60.0;

    return rpm;
}

// Function to print the calculated RPM to the console
void print_rpm(double rpm) {
    printf("RPM: %.2f\n", rpm);
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

