    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file in append mode
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1; // Exit if file opening fails
    }

    SensorStates previous_states = read_sensors();
    time_t start_time = time(NULL);

    // Main loop
    while (program_running) {
        SensorStates current_states = read_sensors();
        time_t current_time = time(NULL);
        double time_diff = difftime(current_time, start_time);

        log_data(current_states);
        double rpm = calculate_rpm(current_states, previous_states, time_diff);
        print_rpm(rpm);

        previous_states = current_states;
        start_time = current_time;

        gpioDelay(DEBOUNCE_TIME * 1000); // Debounce delay (in microseconds)
    }

    // Perform cleanup before exiting
    cleanup();

    return 0;
}

