#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define constants
#define ALARM_THRESHOLD 2.0 // seconds
#define POLL_INTERVAL 0.1   // seconds
#define LOG_FILE "bridge_integrity.log"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_sensor(int pin);
int check_alarm_condition(int sensor1_value, int sensor2_value, double *alarm_time);
void activate_alarm();
void deactivate_alarm();
void log_event(const char *event_type, int sensor1_value, int sensor2_value);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    double alarm_start_time;
} BridgeState;

BridgeState bridge_state = {0, 0, 0.0};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value != bridge_state.sensor1_state) {
            log_event("tilt-start", sensor1_value, sensor2_value);
            bridge_state.sensor1_state = sensor1_value;
        }

        if (sensor2_value != bridge_state.sensor2_state) {
            log_event("tilt-start", sensor1_value, sensor2_value);
            bridge_state.sensor2_state = sensor2_value;
        }

        if (check_alarm_condition(sensor1_value, sensor2_value, &bridge_state.alarm_start_time)) {
            activate_alarm();
        } else {
            if (sensor1_value == 0 && sensor2_value == 0 && bridge_state.alarm_start_time > 0) {
                deactivate_alarm();
                bridge_state.alarm_start_time = 0.0;
            }
        }

        gpioDelay(POLL_INTERVAL * 1000); // pigpio uses microseconds
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    gpioWrite(ALARM_PIN, 0); // Initialize alarm to LOW

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

void cleanup() {
    deactivate_alarm();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int read_sensor(int pin) {
    return gpioRead(pin);
}

int check_alarm_condition(int sensor1_value, int sensor2_value, double *alarm_time) {
    if ((sensor1_value == 1 || sensor2_value == 1) && *alarm_time == 0.0) {
        *alarm_time = time_time();
        return 0;
    } else if ((sensor1_value == 1 || sensor2_value == 1) && *alarm_time > 0.0) {
        double current_time = time_time();
        if (current_time - *alarm_time >= ALARM_THRESHOLD) {
            return 1;
        } else {
            return 0;
        }
    } else {
        return 0;
    }
}

void activate_alarm() {
    gpioWrite(ALARM_PIN, 1);
}

void deactivate_alarm() {
    gpioWrite(ALARM_PIN, 0);
}

void log_event(const char *event_type, int sensor1_value, int sensor2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s - %s - Sensor 1: %d, Sensor 2: %d\n", timestamp, event_type, sensor1_value, sensor2_value);
    fflush(log_file); // Ensure the log is written immediately
}

void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

