#include <signal.h>
#include <string.h>
#include <math.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x1D
#define CTRL1_REG 0x02
#define CTRL2_REG 0x03
#define STATUS_REG 0x04
#define X_REG 0x06
#define Y_REG 0x08
#define Z_REG 0x0A
#define LED_GPIO 17
#define THRESHOLD 500.0
#define SAMPLE_RATE_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_event(double magnitude);
void control_led(int on);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the sensor
int initialize_sensor() {
    int retries = 3;
    while (retries > 0) {
        // Verify sensor presence by reading the status register
        char buf[1];
        if (i2cReadI2CBlockData(i2c_handle, STATUS_REG, buf, 1) != 1) {
            fprintf(stderr, "Error reading status register. Retries remaining: %d\n", retries);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        // Check if the sensor is present (STATUS_REG should not be 0)
        if (buf[0] != 0) {
            printf("Sensor detected.\n");

            // Clear the power-down bit in CTRL1
            char ctrl1_value = 0x80; // Set bit 7 to clear power-down
            if (i2cWriteI2CBlockData(i2c_handle, CTRL1_REG, &ctrl1_value, 1) != 1) {
                fprintf(stderr, "Error writing to CTRL1 register. Retries remaining: %d\n", retries);
                gpioDelay(10000); // 10ms delay
                retries--;
                continue;
            }
            gpioDelay(10000); // 10ms delay

            // Configure CTRL2 (optional, set to default value)
            char ctrl2_value = 0x00; // Default value
            if (i2cWriteI2CBlockData(i2c_handle, CTRL2_REG, &ctrl2_value, 1) != 1) {
                fprintf(stderr, "Error writing to CTRL2 register. Retries remaining: %d\n", retries);
                gpioDelay(10000); // 10ms delay
                retries--;
                continue;
            }
            gpioDelay(10000); // 10ms delay

            return 0; // Success
        } else {
            fprintf(stderr, "Sensor not detected. Retries remaining: %d\n", retries);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Reads sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    int retries = 3;
    while (retries > 0) {
        char buf[6];
        if (i2cReadI2CBlockData(i2c_handle, X_REG, buf, 6) != 6) {
            fprintf(stderr, "Error reading sensor data. Retries remaining: %d\n", retries);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        *x = (int16_t)((buf[1] << 8) | buf[0]);
        *y = (int16_t)((buf[3] << 8) | buf[2]);
        *z = (int16_t)((buf[5] << 8) | buf[4]);

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Calculates the Euclidean magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Logs an event to the log file
void log_event(double magnitude) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tstruct);

    fprintf(log_file, "%s, Magnitude: %.2f\n", buf, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Controls the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
    if (on) {
        gpioDelay(1000000); // 1 second
        gpioWrite(LED_GPIO, 0);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    double magnitude;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > THRESHOLD) {
                log_event(magnitude);
                control_led(1);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

