#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the flame sensors
#define SENSOR_1_PIN 2
#define SENSOR_2_PIN 3
#define SENSOR_3_PIN 4
#define SENSOR_4_PIN 17
#define SENSOR_5_PIN 27

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Log file path
#define LOG_FILE "/var/log/flame_events.log"

// Structure to hold sensor information
typedef struct {
    int pin;
    int id;
    int last_state;
} sensor_t;

// Global array to store sensor data
sensor_t sensors[] = {
    {SENSOR_1_PIN, 1, 1}, // Initialize last_state to 1 (HIGH)
    {SENSOR_2_PIN, 2, 1},
    {SENSOR_3_PIN, 3, 1},
    {SENSOR_4_PIN, 4, 1},
    {SENSOR_5_PIN, 5, 1}
};

const int num_sensors = sizeof(sensors) / sizeof(sensors[0]);

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_USER | LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        syslog(LOG_USER | LOG_ERR, "Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log flame detection events to a file
int log_flame_event(int sensor_id, int pin) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_USER | LOG_ERR, "Failed to open log file: %s", LOG_FILE);
        return -1;
    }

    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, sensor_id, pin);
    free(timestamp);

    if (fflush(fp) != 0) {
        syslog(LOG_USER | LOG_ERR, "Failed to flush log file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to read the sensor value with debouncing
int read_sensor(int pin) {
    int current_state = gpioRead(pin);
    if (current_state < 0) {
        syslog(LOG_USER | LOG_ERR, "Failed to read sensor on pin %d", pin);
        return -1; // Indicate an error
    }

    if (current_state == 0) { // Potential flame detected (LOW)
        gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
        int debounced_state = gpioRead(pin);
        if (debounced_state == 0) {
            return 0; // Confirmed flame detected
        }
    }
    return 1; // No flame detected
}

int main() {
    // Initialize syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_USER | LOG_INFO, "Starting flame monitor...");

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_USER | LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins as inputs
    for (int i = 0; i < num_sensors; i++) {
        gpioSetMode(sensors[i].pin, PI_INPUT);
        sensors[i].last_state = gpioRead(sensors[i].pin); // Initialize last_state
        if (sensors[i].last_state < 0) {
            syslog(LOG_USER | LOG_ERR, "Failed to read initial state for sensor on pin %d", sensors[i].pin);
            gpioTerminate();
            closelog();
            return 1;
        }
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        for (int i = 0; i < num_sensors; i++) {
            int current_state = read_sensor(sensors[i].pin);
            if (current_state < 0) {
                // Error reading sensor, continue to the next sensor
                continue;
            }

            if (current_state == 0 && sensors[i].last_state == 1) {
                // Flame detected (transition from HIGH to LOW)
                if (log_flame_event(sensors[i].id, sensors[i].pin) == 0) {
