// Define the GPIO pins connected to the TTP226 sensor channels
const int sensor_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_sensors = sizeof(sensor_pins) / sizeof(sensor_pins[0]);

// Structure to hold the previous sensor states
struct sensor_states {
    int previous_states[8];
};

struct sensor_states current_states = {{0}};

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return timestamp;
}

// Function to read the state of a single sensor channel
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to log a sensor event
void log_event(int sensor_index, int pin, int state) {
    char* timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp, skipping log.\n");
        return;
    }

    printf("%s Sensor %d (GPIO %d): %s\n", timestamp, sensor_index, pin, state ? "Touched" : "Released");
    free(timestamp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Configure the GPIO pins as inputs
    for (int i = 0; i < num_sensors; i++) {
        gpioSetMode(sensor_pins[i], PI_INPUT);
        current_states.previous_states[i] = read_sensor(sensor_pins[i]); // Initialize previous states
    }

    // Main loop to continuously poll the sensor pins
    while (1) {
        for (int i = 0; i < num_sensors; i++) {
            int current_state = read_sensor(sensor_pins[i]);

            if (current_state != current_states.previous_states[i]) {
                log_event(i, sensor_pins[i], current_state);
                current_states.previous_states[i] = current_state;
            }
        }

        gpioDelay(50); // Delay for 50 milliseconds
    }

    // The program should never reach this point due to the infinite loop
    gpioTerminate();
    return 0;
}

