#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define ALS_DATA_REG 0x04
#define CONFIG_REG 0x00
#define GPIO_LED 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000000 // 1 MHz
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int configure_veml7700();
float read_lux();
int map_lux_to_brightness(float lux);
int set_led_brightness(int brightness);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, shutting down...\n", signal);
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure VEML7700
int configure_veml7700() {
    // Example configuration: Integration time = 100ms, Gain = 1/8
    uint16_t config_value = 0x0000; // Default configuration
    if (i2cWriteWordData(i2c_handle, CONFIG_REG, config_value) < 0) {
        fprintf(stderr, "Failed to write to configuration register\n");
        return -1;
    }
    return 0;
}

// Read lux value from VEML7700
float read_lux() {
    int raw_data = i2cReadWordData(i2c_handle, ALS_DATA_REG);
    if (raw_data < 0) {
        fprintf(stderr, "Failed to read ALS data\n");
        return -1.0;
    }

    // Convert raw data to lux (example formula, adjust as needed)
    float lux = (float)raw_data * 0.0576; // Example conversion factor
    return lux;
}

// Map lux value to brightness percentage
int map_lux_to_brightness(float lux) {
    if (lux < 100) {
        return 100;
    } else if (lux < 500) {
        return 75;
    } else if (lux < 1000) {
        return 50;
    } else {
        return 25;
    }
}

// Set LED brightness using PWM
int set_led_brightness(int brightness) {
    int duty_cycle = (int)(((float)brightness / 100.0) * PWM_RANGE);
    gpioPWM(GPIO_LED, duty_cycle);
    return 0;
}

// Log data to file
int log_data(float lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Configure VEML7700
    if (configure_veml7700() != 0) {
        cleanup();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(GPIO_LED, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_LED, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read lux value
        float lux = read_lux();
        int error_code = 0;
        if (lux < 0) {
            error_code = 1; // Sensor read error
            lux = 0.0; // Set to a default value for logging
        }

        // Map lux to brightness
        int brightness = map_lux_to_brightness(lux);

        // Set LED brightness
        set_led_brightness(brightness);

        // Log data
        log_data(lux, brightness, error_code);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

