#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for touch sensor channels
#define TOUCH_CHANNEL_1 2
#define TOUCH_CHANNEL_2 3
#define TOUCH_CHANNEL_3 4
#define TOUCH_CHANNEL_4 5
#define TOUCH_CHANNEL_5 6
#define TOUCH_CHANNEL_6 7
#define TOUCH_CHANNEL_7 8
#define TOUCH_CHANNEL_8 9

// Define GPIO pin for the alert LED
#define ALERT_LED 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_touch_channel(int channel);
void log_touch_event(int channel);
void control_alert_led(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    control_alert_led(0); // Turn off the LED
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins for touch sensor channels as inputs with pull-down resistors
    int channels[] = {TOUCH_CHANNEL_1, TOUCH_CHANNEL_2, TOUCH_CHANNEL_3, TOUCH_CHANNEL_4, TOUCH_CHANNEL_5, TOUCH_CHANNEL_6, TOUCH_CHANNEL_7, TOUCH_CHANNEL_8};
    for (int i = 0; i < 8; i++) {
        gpioSetMode(channels[i], PI_INPUT);
        gpioSetPullUpDown(channels[i], PI_PUD_DOWN);
    }

    // Set GPIO pin for the alert LED as an output
    gpioSetMode(ALERT_LED, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to read the state of a touch sensor channel
int read_touch_channel(int channel) {
    return gpioRead(channel);
}

// Function to log a touch event to a file
void log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char log_message[100];
    FILE *fp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(log_message, sizeof(log_message), "%s - Channel %d Touched\n", timestamp, channel);

    fp = fopen("touch_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening touch_log.txt for writing\n");
        return;
    }

    if (fputs(log_message, fp) == EOF) {
        fprintf(stderr, "Error writing to touch_log.txt\n");
    }

    fclose(fp);
}

// Function to control the alert LED
void control_alert_led(int state) {
    gpioWrite(ALERT_LED, state);
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

