#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define LUX_SCALE 0.01
#define SLEEP_MS 100
#define READ_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor(uint16_t *raw_data);
float calculate_lux(uint16_t raw_data);
int log_data(float lux_value);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    uint16_t config_value;
} sensor_config_t;

// Function to initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to configure the OPT3001 sensor
int configure_sensor() {
    uint16_t config_value = 0b1100000000000000; // Continuous mode, 800ms conversion time
    char buf[3];

    // Byte swap the configuration value
    uint8_t msb = (config_value >> 8) & 0xFF;
    uint8_t lsb = config_value & 0xFF;

    buf[0] = CONFIG_REG;
    buf[1] = msb;
    buf[2] = lsb;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write configuration: %d\n", result);
        return -1;
    }

    gpioDelay(SLEEP_MS * 1000); // Wait for configuration to take effect
    return 0;
}

// Function to read data from the OPT3001 sensor
int read_sensor(uint16_t *raw_data) {
    char buf[1];
    char read_buf[2];
    int result;

    buf[0] = RESULT_REG;

    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write register address for reading: %d\n", result);
        return -1;
    }

    gpioDelay(READ_DELAY_MS * 1000); // Wait before reading

    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // Byte swap the received data
    uint8_t msb = read_buf[0];
    uint8_t lsb = read_buf[1];

    *raw_data = ((uint16_t)msb << 8) | (uint16_t)lsb;

    return 0;
}

// Function to calculate lux value from raw data
float calculate_lux(uint16_t raw_data) {
    uint16_t exponent = (raw_data >> 12) & 0x0F;
    uint16_t result = raw_data & 0x0FFF;
    return (float)result * (0.01 * (1 << exponent));
}

// Function to log data to file and stdout
int log_data(float lux_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux_value);
    fflush(log_file);

    printf("%s, %.2f\n", timestamp, lux_value);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed, exiting\n");
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        fprintf(stderr, "Sensor configuration failed, exiting\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint16_t raw_data;
    float lux_value;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor(&raw_data) == 0) {
            // Calculate lux value
            lux_value = calculate_lux(raw_data);

            // Log data
            log_data(lux_value);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

