#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define MEASURE_CMD 0x3608
#define FLOW_SCALE_FACTOR 0.0648
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define MIN_FLOW_RATE 0.0
#define MAX_FLOW_RATE 100.0
#define SAMPLE_INTERVAL_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t flow_raw;
    uint8_t crc;
    float flow_rate;
    char status[20];
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(int16_t *flow_raw, uint8_t *crc);
float convert_flow_rate(int16_t flow_raw);
uint8_t calculate_crc(uint8_t data[], int len);
int validate_crc(uint8_t data[], int len, uint8_t crc);
int log_data(float flow_rate, uint8_t flags, const char *status);
void signal_handler(int signal);
int write_header();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the SLF3S-1300F
int read_sensor_data(int16_t *flow_raw, uint8_t *crc) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buffer[3];

    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }

    gpioDelay(2); // Wait at least 2ms

    if (i2cReadDevice(i2c_handle, buffer, 3) != 3) {
        fprintf(stderr, "Error reading from I2C device: %d\n", i2c_handle);
        return -1;
    }

    *flow_raw = (int16_t)((buffer[0] << 8) | buffer[1]);
    *crc = buffer[2];

    return 0;
}

// Convert raw flow data to ml/min
float convert_flow_rate(int16_t flow_raw) {
    return (float)flow_raw * FLOW_SCALE_FACTOR;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc) ? 0 : -1;
}

// Log data to CSV file
int log_data(float flow_rate, uint8_t flags, const char *status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%u,%s\n", timestamp, flow_rate, flags, status);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Write CSV header if the file is newly created
int write_header() {
    if (log_file != NULL) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(log_file);
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("cooling_log.csv", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        if (write_header() != 0) {
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }
    }
    rewind(log_file);

    int16_t flow_raw;
    uint8_t crc;
    float flow_rate;
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&flow_raw, &crc) == 0) {
            if (validate_crc((uint8_t[]){(flow_raw >> 8) & 0xFF, flow_raw & 0xFF}, 2, crc) == 0) {
                flow_rate = convert_flow_rate(flow_raw);

                if (flow_rate >= MIN_FLOW_RATE && flow_rate <= MAX_FLOW_RATE) {
                    sensor_data.flow_raw = flow_raw;
                    sensor_data.crc = crc;
                    sensor_data.flow_rate = flow_rate;
                    strcpy(sensor_data.status, "OK");
                } else {
                    sensor_data.flow_raw = flow_raw;
                    sensor_data.crc = crc;
                    sensor_data.flow_rate = flow_rate;
                    strcpy(sensor_data.status, "INVALID");
                }

                if (log_data(sensor_data.flow_rate, 0, sensor_data.status) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed.\n");
                if (log_data(0.0, 0, "CRC ERROR") != 0) {
                    fprintf(stderr, "Error logging CRC error.\n");
                }
                i2cClose(i2c_handle);
                if (init_i2c() != 0) {
                    fprintf(stderr, "Failed to re-initialize I2C.\n");
                    terminate = 1; // Exit if re-initialization fails
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
            if (log_data(0.0, 0, "I2C ERROR") != 0) {
                fprintf(stderr, "Error logging I2C error.\n");
            }
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C.\n");
                terminate = 1; // Exit if re-initialization fails
            }
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Sample once per second
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

