#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <stdbool.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Define the log file name
#define LOG_FILE_NAME "path_log.csv"

// Global variables
FILE *log_file = NULL;
bool running = true;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int write_to_log(const char *timestamp, int left, int middle, int right);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int left;
    int middle;
    int right;
} sensor_data_t;

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", MIDDLE_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the value from a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO%d\n", gpio_pin);
        return -1; // Indicate an error
    }
    return value;
}

// Function to write the sensor data to the log file
int write_to_log(const char *timestamp, int left, int middle, int right) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully...\n");
        running = false;
    }
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Get the current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[30]; // ISO 8601 timestamp format

        time(&rawtime);
        timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Read the sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        if (left_value == -1 || middle_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensor values, skipping log entry.\n");
        } else {
            // Write the data to the log file
            if (write_to_log(timestamp, left_value, middle_value, right_value) != 0) {
                fprintf(stderr, "Error writing to log file.\n");
            }
        }

        // Delay for 50 milliseconds
        gpioDelay(50);
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

