#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <sys/mman.h>

// Constants
#define GPIOCHIP4 4
#define TOUCH_SENSOR_GPIO 23
#define LED_GPIO 24
#define GPIOCHIP5 5
#define TOUCH_SENSOR_GPIO_ALT 17
#define LED_GPIO_ALT 18
#define LOG_FILE "touch_log.txt"
#define DEBOUNCE_DELAY_MS 50

// Global variables
static volatile int keep_running = 1;
static int log_fd = -1;
static int mem_fd = -1;
static void *gpio_map = MAP_FAILED;

// Function prototypes
int gpio_export(int chip, int gpio);
int gpio_unexport(int chip, int gpio);
int gpio_set_direction(int chip, int gpio, const char *direction);
int gpio_read(int chip, int gpio);
int gpio_write(int chip, int gpio, int value);
int log_event(const char *message);
void signal_handler(int sig);
int get_iso8601_timestamp(char *timestamp);
int debounce(int gpio, int value);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Caught signal %d, exiting gracefully.\n", sig);
        keep_running = 0;
    }
}

// GPIO export function
int gpio_export(int chip, int gpio) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", gpio);
    if (write(fd, buffer, len) != len) {
        fprintf(stderr, "Error writing to /sys/class/gpio/export: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO unexport function
int gpio_unexport(int chip, int gpio) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", gpio);
    if (write(fd, buffer, len) != len) {
        fprintf(stderr, "Error writing to /sys/class/gpio/unexport: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO set direction function
int gpio_set_direction(int chip, int gpio, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", gpio);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO read function
int gpio_read(int chip, int gpio) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

// GPIO write function
int gpio_write(int chip, int gpio, int value) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    snprintf(value_str, sizeof(value_str), "%d", value);
    if (write(fd, value_str, strlen(value_str)) != strlen(value_str)) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Log event function
int log_event(const char *message) {
    char timestamp[32];
    if (get_iso8601_timestamp(timestamp) != 0) {
        fprintf(stderr, "Error getting timestamp.\n");
        return -1;
    }

    if (log_fd < 0) {
        fprintf(stderr, "Log file not opened.\n");
        return -1;
    }

    if (write(log_fd, timestamp, strlen(timestamp)) < 0) {
        fprintf(stderr, "Error writing timestamp to log file: %s\n", strerror(errno));
        return -1;
    }

    if (write(log_fd, " ", 1) < 0) {
        fprintf(stderr, "Error writing space to log file: %s\n", strerror(errno));
        return -1;
    }

    if (write(log_fd, message, strlen(message)) < 0) {
        fprintf(stderr, "Error writing message to log file: %s\n", strerror(errno));
        return -1;
    }

    if (write(log_fd, "\n", 1) < 0) {
        fprintf(stderr, "Error writing newline to log file: %s\n", strerror(errno));
        return -1;
    }

    fsync(log_fd);
    return 0;
}

// Get ISO 8601 timestamp function
int get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    if (strftime(timestamp, 32, "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp.\n");
        return -1;
    }

    return 0;
}

// Debounce function
int debounce(int gpio, int value) {
    static int last_value = -1;
    static struct timespec last_time;
    struct timespec current_time;
    long time_diff_ms;

    clock_gettime(CLOCK_MONOTONIC, &current_time);

    if (last_value == -1) {
        last_value = value;
        clock_gettime(CLOCK_MONOTONIC, &last_time);
        return value;
    }

    time_diff_ms = (current_time.tv_sec - last_time.tv_sec) * 1000 + (current_time.tv_nsec - last_time.tv_nsec) / 1000000;

    if (time_diff_ms < DEBOUNCE_DELAY_MS) {
        return last_value;
    }

    if (value != last_value) {
        last_value = value;
        clock_gettime(CLOCK_MONOTONIC, &last_time);
        return value;
    }

    return last_value;
}

int main() {
    int touch_state = 0;
    int led_state = 0;
    int prev_touch_state = 0;
    char timestamp[32];

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // GPIO initialization
    if (gpio_export(GPIOCHIP4, TOUCH_SENSOR_GPIO) != 0 ||
        gpio_export(GPIOCHIP4, LED_GPIO) != 0 ||
        gpio_export(GPIOCHIP5, TOUCH_SENSOR_GPIO_ALT) != 0 ||
        gpio_export(GPIOCHIP5, LED_GPIO_ALT) != 0) {
        goto cleanup;
    }

    if (gpio_set_direction(GPIOCHIP4, TOUCH_SENSOR_GPIO, "in") != 0 ||
        gpio_set_direction(GPIOCHIP4, LED_GPIO, "out") != 0 ||
        gpio_set_direction(GPIOCHIP5, TOUCH_SENSOR_GPIO_ALT, "in") != 0 ||
        gpio_set_direction(GPIOCHIP5, LED_GPIO_ALT, "out") != 0) {
        goto cleanup;
    }

    // Main loop
    while (keep_running) {
        int touch_value = gpio_read(GPIOCHIP4, TOUCH_SENSOR_GPIO);
        int touch_value_alt = gpio_read(GPIOCHIP5, TOUCH_SENSOR_GPIO_ALT);

        if (touch_value < 0 || touch_value_alt < 0) {
            fprintf(stderr, "Error reading touch sensor value.\n");
            goto cleanup;
        }

        touch_state = debounce(GPIOCHIP4, touch_value);
        int touch_state_alt = debounce(GPIOCHIP5, touch_value_alt);

        if (touch_state == 1 && prev_touch_state == 0) {
            led_state = !led_state;
            if (gpio_write(GPIOCHIP4, LED_GPIO, led_state) != 0) {
                fprintf(stderr, "Error writing to LED GPIO.\n");
                goto cleanup;
            }
            if (gpio_write(GPIOCHIP5, LED_GPIO_ALT, led_state) != 0) {
                fprintf(stderr, "Error writing to LED GPIO (ALT).\n");
                goto cleanup;
            }

            if (get_iso8601_timestamp(timestamp) != 0) {
                fprintf(stderr, "Error getting timestamp.\n");
                goto cleanup;
            }

            char log_message[128];
            snprintf(log_message, sizeof(log_message), "Touch detected, LED state: %s", led_state ? "ON" : "OFF");
            if (log_event(log_message) != 0) {
                fprintf(stderr, "Error logging event.\n");
                goto cleanup;
            }
            prev_touch_state = 1;
        } else if (touch_state == 0) {
            prev_touch_state = 0;
        }

        if (touch_state_alt == 1 && prev_touch_state == 0) {
            led_state = !led_state;
            if (gpio_write(GPIOCHIP4, LED_GPIO, led_state) != 0) {
                fprintf(stderr, "Error writing to LED GPIO.\n");
                goto cleanup;
            }
            if (gpio_write(GPIOCHIP5, LED_GPIO_ALT, led_state) != 0) {
                fprintf(stderr, "Error writing to LED GPIO (ALT).\n");
                goto cleanup;
            }

            if (get_iso8601_timestamp(timestamp) != 0) {
                fprintf(stderr, "Error getting timestamp.\n");
                goto cleanup;
            }

            char log_message[128];
            snprintf(log_message, sizeof(log_message), "Touch detected (ALT), LED state: %s", led_state ? "ON" : "OFF");
            if (log_event(log_message) != 0) {
                fprintf(stderr, "Error logging event.\n");
                goto cleanup;
            }
            prev_touch_state = 1;
        } else if (touch_state_alt == 0) {
            prev_touch_state = 0;
        }

        usleep(10000); // 10ms delay
    }

cleanup:
    // Cleanup
    gpio_unexport(GPIOCHIP4, TOUCH_SENSOR_GPIO);
    gpio_unexport(GPIOCHIP4, LED_GPIO);
    gpio_unexport(GPIOCHIP5, TOUCH_SENSOR_GPIO_ALT);
    gpio_unexport(GPIOCHIP5, LED_GPIO_ALT);

    if (log_fd >= 0) {
        close(log_fd);
    }

    return EXIT_FAILURE;
}

