        fprintf(stderr, "Log file not opened.\n");
        return -1;
    }

    if (write(log_fd, timestamp, strlen(timestamp)) < 0) {
        fprintf(stderr, "Error writing timestamp to log file: %s\n", strerror(errno));
        return -1;
    }

    if (write(log_fd, " ", 1) < 0) {
        fprintf(stderr, "Error writing space to log file: %s\n", strerror(errno));
        return -1;
    }

    if (write(log_fd, message, strlen(message)) < 0) {
        fprintf(stderr, "Error writing message to log file: %s\n", strerror(errno));
        return -1;
    }

    if (write(log_fd, "\n", 1) < 0) {
        fprintf(stderr, "Error writing newline to log file: %s\n", strerror(errno));
        return -1;
    }

    fsync(log_fd);
    return 0;
}

// Get ISO 8601 timestamp function
int get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    if (strftime(timestamp, 32, "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp.\n");
        return -1;
    }

    return 0;
}

// Debounce function
int debounce(int gpio, int value) {
    static int last_value = -1;
    static struct timespec last_time;
    struct timespec current_time;
    long time_diff_ms;

    clock_gettime(CLOCK_MONOTONIC, &current_time);

    if (last_value == -1) {
        last_value = value;
        clock_gettime(CLOCK_MONOTONIC, &last_time);
        return value;
    }

    time_diff_ms = (current_time.tv_sec - last_time.tv_sec) * 1000 + (current_time.tv_nsec - last_time.tv_nsec) / 1000000;

    if (time_diff_ms < DEBOUNCE_DELAY_MS) {
        return last_value;
    }

    if (value != last_value) {
        last_value = value;
        clock_gettime(CLOCK_MONOTONIC, &last_time);
        return value;
    }

    return last_value;
}

int main() {
    int touch_state = 0;
    int led_state = 0;
    int prev_touch_state = 0;
    char timestamp[32];

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // GPIO initialization
    if (gpio_export(GPIOCHIP4, TOUCH_SENSOR_GPIO) != 0 ||
        gpio_export(GPIOCHIP4, LED_GPIO) != 0 ||
        gpio_export(GPIOCHIP5, TOUCH_SENSOR_GPIO_ALT) != 0 ||
        gpio_export(GPIOCHIP5, LED_GPIO_ALT) != 0) {
        goto cleanup;
    }

    if (gpio_set_direction(GPIOCHIP4, TOUCH_SENSOR_GPIO, "in") != 0 ||
        gpio_set_direction(GPIOCHIP4, LED_GPIO, "out") != 0 ||
        gpio_set_direction(GPIOCHIP5, TOUCH_SENSOR_GPIO_ALT, "in") != 0 ||
        gpio_set_direction(GPIOCHIP5, LED_GPIO_ALT, "out") != 0) {
        goto cleanup;
    }

    // Main loop
    while (keep_running) {
        int touch_value = gpio_read(GPIOCHIP4, TOUCH_SENSOR_GPIO);
        int touch_value_alt = gpio_read(GPIOCHIP5, TOUCH_SENSOR_GPIO_ALT);

        if (touch_value < 0 || touch_value_alt < 0) {
            fprintf(stderr, "Error reading touch sensor value.\n");
            goto cleanup;
        }

        touch_state = debounce(GPIOCHIP4, touch_value);
        int touch_state_alt = debounce(GPIOCHIP5, touch_value_alt);

        if (touch_state == 1 && prev_touch_state == 0) {
            led_state = !led_state;
