            snprintf(log_message, sizeof(log_message), "Touch detected, LED state: %s", led_state ? "ON" : "OFF");
            if (log_event(log_message) != 0) {
                fprintf(stderr, "Error logging event.\n");
                goto cleanup;
            }
            prev_touch_state = 1;
        } else if (touch_state == 0) {
            prev_touch_state = 0;
        }

        if (touch_state_alt == 1 && prev_touch_state == 0) {
            led_state = !led_state;
            if (gpio_write(GPIOCHIP4, LED_GPIO, led_state) != 0) {
                fprintf(stderr, "Error writing to LED GPIO.\n");
                goto cleanup;
            }
            if (gpio_write(GPIOCHIP5, LED_GPIO_ALT, led_state) != 0) {
                fprintf(stderr, "Error writing to LED GPIO (ALT).\n");
                goto cleanup;
            }

            if (get_iso8601_timestamp(timestamp) != 0) {
                fprintf(stderr, "Error getting timestamp.\n");
                goto cleanup;
            }

            char log_message[128];
            snprintf(log_message, sizeof(log_message), "Touch detected (ALT), LED state: %s", led_state ? "ON" : "OFF");
            if (log_event(log_message) != 0) {
                fprintf(stderr, "Error logging event.\n");
                goto cleanup;
            }
            prev_touch_state = 1;
        } else if (touch_state_alt == 0) {
            prev_touch_state = 0;
        }

        usleep(10000); // 10ms delay
    }

