    // Cleanup
    gpio_unexport(GPIOCHIP4, TOUCH_SENSOR_GPIO);
    gpio_unexport(GPIOCHIP4, LED_GPIO);
    gpio_unexport(GPIOCHIP5, TOUCH_SENSOR_GPIO_ALT);
    gpio_unexport(GPIOCHIP5, LED_GPIO_ALT);

    if (log_fd >= 0) {
        close(log_fd);
    }

    return EXIT_FAILURE;
}

