// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define constants
#define BUZZER_DURATION_MS 2000
#define POLL_INTERVAL_MS 500
#define SLICE_MS 100

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
int activate_buzzer(int duration_ms);
int log_event(const char *message);
void signal_handler(int signal);
