    printf("Signal received (%d). Shutting down...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off initially

    return 0;
}

// Read flame sensor value
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Activate buzzer for a specified duration
int activate_buzzer(int duration_ms) {
    gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
    return 0;
}

// Log an event to the log file
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("alert_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Log system start
    log_event("System started");

    int flame_detected = 0; // Flag to track flame detection state

    // Main loop
    while (running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0) { // Flame detected (LOW signal)
            if (!flame_detected) { // Only trigger on transition
                log_event("FLAME DETECTED");
                activate_buzzer(BUZZER_DURATION_MS);
                flame_detected = 1; // Set the flag
            }
        } else {
            flame_detected = 0; // Reset the flag when no flame is detected
        }

        // Sleep for a slice of the poll interval
        gpioDelay(SLICE_MS * 1000); // Delay in microseconds
    }

    // Log system stop
    log_event("System stopped");

    // Cleanup resources
    cleanup();

    return 0;
}

