#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define MEAS_RATE_REG 0x08
#define LED_DRIVE_REG 0x0F
#define ALS_RATE_REG 0x0A
#define ALS_IR_ADCMUX_REG 0x03
#define ALS_VIS_ADCMUX_REG 0x02
#define ALS_IR_ADC_GAIN_REG 0x04
#define ALS_VIS_ADC_GAIN_REG 0x05
#define ALS_IR_ADC_MISC_REG 0x06
#define ALS_VIS_ADC_MISC_REG 0x07
#define ALS_IR_ADC_DATA_REG 0x22
#define ALS_VIS_ADC_DATA_REG 0x24
#define MEAS_RATE_VAL 0x0A // 10ms
#define LED_DRIVE_VAL 0x3F // Max drive
#define ALS_IR_ADCMUX_VAL 0x40 // Large IR
#define ALS_VIS_ADCMUX_VAL 0x40 // Large VIS
#define ALS_IR_ADC_GAIN_VAL 0x03 // Gain 64x
#define ALS_VIS_ADC_GAIN_VAL 0x03 // Gain 64x
#define ALS_IR_ADC_MISC_VAL 0x00
#define ALS_VIS_ADC_MISC_VAL 0x00
#define PART_ID_EXPECTED 0x82
#define HW_REV_EXPECTED 0x01
#define BPM_MIN 30
#define BPM_MAX 220
#define MOVING_AVG_SIZE 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for moving average filter
typedef struct {
    int values[MOVING_AVG_SIZE];
    int index;
    int count;
    float sum;
} MovingAverageFilter;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(int *ir_value, int *vis_value);
float calculate_bpm(int ir_value, int vis_value);
int validate_bpm(float bpm);
int log_data(float bpm);
void signal_handler(int signal);
void init_moving_average(MovingAverageFilter *filter);
float update_moving_average(MovingAverageFilter *filter, float new_value);

// Initialize moving average filter
void init_moving_average(MovingAverageFilter *filter) {
    filter->index = 0;
    filter->count = 0;
    filter->sum = 0.0;
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        filter->values[i] = 0;
    }
}

// Update moving average filter
float update_moving_average(MovingAverageFilter *filter, float new_value) {
    filter->sum -= filter->values[filter->index];
    filter->sum += new_value;
    filter->values[filter->index] = (int)new_value; // Store the new value
    filter->index = (filter->index + 1) % MOVING_AVG_SIZE;
    if (filter->count < MOVING_AVG_SIZE) {
        filter->count++;
    }
    return filter->sum / filter->count;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize sensor
int init_sensor() {
    int part_id, hw_rev;

    // Read PART_ID
    part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", part_id);
        return -1;
    }
    if (part_id != PART_ID_EXPECTED) {
        fprintf(stderr, "Error: Incorrect PART_ID: 0x%02X (expected 0x%02X)\n", part_id, PART_ID_EXPECTED);
        return -1;
    }

    // Read HW_REV
    hw_rev = i2cReadByteData(i2c_handle, HW_REV_REG);
    if (hw_rev < 0) {
        fprintf(stderr, "Error reading HW_REV: %d\n", hw_rev);
        return -1;
    }
    if (hw_rev != HW_REV_EXPECTED) {
        fprintf(stderr, "Error: Incorrect HW_REV: 0x%02X (expected 0x%02X)\n", hw_rev, HW_REV_EXPECTED);
        return -1;
    }

    // Configure sensor
    if (i2cWriteByteData(i2c_handle, MEAS_RATE_REG, MEAS_RATE_VAL) < 0) {
        fprintf(stderr, "Error writing MEAS_RATE_REG\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, LED_DRIVE_REG, LED_DRIVE_VAL) < 0) {
        fprintf(stderr, "Error writing LED_DRIVE_REG\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ALS_RATE_REG, 0x0A) < 0) {
        fprintf(stderr, "Error writing ALS_RATE_REG\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ALS_IR_ADCMUX_REG, ALS_IR_ADCMUX_VAL) < 0) {
        fprintf(stderr, "Error writing ALS_IR_ADCMUX_REG\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ALS_VIS_ADCMUX_REG, ALS_VIS_ADCMUX_VAL) < 0) {
        fprintf(stderr, "Error writing ALS_VIS_ADCMUX_REG\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ALS_IR_ADC_GAIN_REG, ALS_IR_ADC_GAIN_VAL) < 0) {
        fprintf(stderr, "Error writing ALS_IR_ADC_GAIN_REG\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ALS_VIS_ADC_GAIN_REG, ALS_VIS_ADC_GAIN_VAL) < 0) {
        fprintf(stderr, "Error writing ALS_VIS_ADC_GAIN_REG\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ALS_IR_ADC_MISC_REG, ALS_IR_ADC_MISC_VAL) < 0) {
        fprintf(stderr, "Error writing ALS_IR_ADC_MISC_REG\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ALS_VIS_ADC_MISC_REG, ALS_VIS_ADC_MISC_VAL) < 0) {
        fprintf(stderr, "Error writing ALS_VIS_ADC_MISC_REG\n");
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(int *ir_value, int *vis_value) {
    int retries = 3;
    int ir, vis;

    while (retries > 0) {
        ir = i2cReadWordData(i2c_handle, ALS_IR_ADC_DATA_REG);
        if (ir >= 0) break;
        fprintf(stderr, "Error reading IR data, retrying...\n");
        gpioDelay(1000); // 1ms delay
        retries--;
    }
    if (ir < 0) {
        fprintf(stderr, "Failed to read IR data after multiple retries.\n");
        return -1;
    }

    retries = 3;
    while (retries > 0) {
        vis = i2cReadWordData(i2c_handle, ALS_VIS_ADC_DATA_REG);
        if (vis >= 0) break;
        fprintf(stderr, "Error reading VIS data, retrying...\n");
        gpioDelay(1000); // 1ms delay
        retries--;
    }
    if (vis < 0) {
        fprintf(stderr, "Failed to read VIS data after multiple retries.\n");
        return -1;
    }

    *ir_value = ir;
    *vis_value = vis;
    return 0;
}

// Calculate BPM (Placeholder - replace with actual calculation)
float calculate_bpm(int ir_value, int vis_value) {
    // This is a placeholder.  A real implementation would analyze the IR and VIS
