    // For example, you might look for peaks in the IR data that correspond to heartbeats.
    // This is a simplified example that just returns a value based on the IR data.
    return (float)ir_value / 100.0; // Replace with actual BPM calculation
}

// Validate BPM
int validate_bpm(float bpm) {
    return (bpm >= BPM_MIN && bpm <= BPM_MAX);
}

// Log data to file
int log_data(float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    MovingAverageFilter bpm_filter;
    init_moving_average(&bpm_filter);

    int ir_value, vis_value;
    float bpm, filtered_bpm;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&ir_value, &vis_value) == 0) {
            // Calculate BPM
            bpm = calculate_bpm(ir_value, vis_value);

            // Apply moving average filter
            filtered_bpm = update_moving_average(&bpm_filter, bpm);

            // Validate BPM
            if (validate_bpm(filtered_bpm)) {
                // Log data
                log_data(filtered_bpm);
            } else {
                fprintf(stderr, "Invalid BPM: %.2f\n", filtered_bpm);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(1000); // 1 second delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

