#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins for sensor inputs and counter outputs
const int sensor_pins[] = {5, 6, 7, 8, 9, 10, 11, 12};
const int output_pins[] = {17, 18, 19, 20, 21, 22, 23, 24};
const int num_channels = 8;

// Global variables
static volatile int running = 1;
static int counter = 0;
static FILE *log_file = NULL;

// Function prototypes
int read_sensor(int pin);
int update_counter(int *counter);
int update_outputs(int counter);
int log_event(int channel, int counter);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor value
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on pin %d: %s\n", pin, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to update the counter
int update_counter(int *counter) {
    (*counter)++;
    if (*counter > 255) {
        *counter = 0;
    }
    return *counter;
}

// Function to update the output pins
int update_outputs(int counter) {
    for (int i = 0; i < num_channels; i++) {
        int bit = (counter >> i) & 1;
        int result = gpioWrite(output_pins[i], bit);
        if (result != 0) {
            fprintf(stderr, "Error writing to output pin %d: %s\n", output_pins[i], strerror(errno));
            return -1; // Indicate error
        }
    }
    return 0;
}

// Function to log the event
int log_event(int channel, int counter) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", buf, channel, counter);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Log file not opened. Cannot log event.\n");
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    // Set sensor pins as inputs
    for (int i = 0; i < num_channels; i++) {
        gpioSetMode(sensor_pins[i], PI_INPUT);
    }

    // Set output pins as outputs
    for (int i = 0; i < num_channels; i++) {
        gpioSetMode(output_pins[i], PI_OUTPUT);
    }

    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio() {
    // Reset all output pins to 0
    for (int i = 0; i < num_channels; i++) {
        gpioWrite(output_pins[i], 0);
    }

    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        // Continue without logging to file
    }

    // Stabilization delay
    gpioDelay(200000); // 200 ms

    int previous_values[8];
    for (int i = 0; i < num_channels; i++) {
        previous_values[i] = read_sensor(sensor_pins[i]);
        if (previous_values[i] < 0) {
            // Handle sensor read error, possibly exit or continue with other channels
            fprintf(stderr, "Error reading initial sensor value on pin %d, skipping channel.\n", sensor_pins[i]);
        }
    }

    // Main loop
    while (running) {
        for (int i = 0; i < num_channels; i++) {
            int current_value = read_sensor(sensor_pins[i]);
            if (current_value < 0) {
                // Skip to the next channel if there's an error reading the sensor
                continue;
            }

            if (current_value == 1 && previous_values[i] == 0) {
                // Rising edge detected
                counter = update_counter(&counter);
                if (update_outputs(counter) != 0) {
                    fprintf(stderr, "Error updating outputs, continuing.\n");
                }
                log_event(i + 1, counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
            previous_values[i] = current_value;
        }

        gpioDelay(10000); // 10 ms
    }

    // Cleanup
    cleanup_gpio();

    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

