#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN 22

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
void set_led(int gpio_pin, int state);
void log_data(FILE *fp, int sensor1_value, int sensor2_value, int led_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        running = 0;
        set_led(LED_PIN, 0); // Turn off LED
        if (log_file != NULL) {
            fclose(log_file);
        }
        gpioTerminate(); // Release GPIO resources
        exit(0);
    }
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on pin %d\n", gpio_pin);
        return -1; // Indicate error
    }
    return value;
}

// Function to set LED state
void set_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log data to file
void log_data(FILE *fp, int sensor1_value, int sensor2_value, int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, led_state) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    }
    fflush(fp); // Flush the buffer to ensure data is written to the file
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("obstacle_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensors, exiting.\n");
            break; // Exit loop if sensor reading fails
        }

        int led_state = 0;
        if (sensor1_value == 0 && sensor2_value == 0) {
            led_state = 1;
        }
        set_led(LED_PIN, led_state);

        log_data(log_file, sensor1_value, sensor2_value, led_state);

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup (in case the loop breaks due to an error)
    set_led(LED_PIN, 0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Release GPIO resources

    return 0;
}

