#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define MICROPHONE_PIN 4
#define LED_PIN 17

// Define sampling rate and period
#define SAMPLING_RATE 8000
#define SAMPLING_PERIOD_US (1000000 / SAMPLING_RATE)

// Define LED on time
#define LED_ON_TIME_MS 100

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, terminating...\n");
}

// Function to initialize GPIO pins
int initialize_gpio()
{
    if (gpioSetMode(MICROPHONE_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting microphone pin mode\n");
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting LED pin mode\n");
        return -1;
    }

    return 0;
}

// Function to read microphone data
int read_microphone()
{
    return gpioRead(MICROPHONE_PIN);
}

// Function to detect a peak
int detect_peak(int microphone_value)
{
    return (microphone_value == 1) ? 1 : 0;
}

// Function to get timestamp
void get_timestamp(char *timestamp)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);
    sprintf(timestamp, "%ld", milliseconds);
}

// Function to control the LED
void control_led(int on)
{
    gpioWrite(LED_PIN, on);
}

// Function to cleanup GPIO
void cleanup_gpio()
{
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
}

int main()
{
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read microphone data
        int microphone_value = read_microphone();

        // Detect peak
        if (detect_peak(microphone_value)) {
            // Get timestamp
            char timestamp[20];
            get_timestamp(timestamp);

            // Print timestamp
            printf("%s\n", timestamp);

            // Turn on LED
            control_led(1);

            // Wait for LED on time
            gpioDelay(LED_ON_TIME_MS * 1000); // Convert ms to us

            // Turn off LED
            control_led(0);
        }

        // Delay for sampling period
        gpioDelay(SAMPLING_PERIOD_US);
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

