#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR 17
#define CENTER_SENSOR 27
#define RIGHT_SENSOR 22

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the sensor values
int read_sensors(int *left, int *center, int *right) {
    int left_val, center_val, right_val;

    left_val = gpioRead(LEFT_SENSOR);
    if (left_val < 0) {
        fprintf(stderr, "Error reading left sensor: %d\n", left_val);
        return -1;
    }

    center_val = gpioRead(CENTER_SENSOR);
    if (center_val < 0) {
        fprintf(stderr, "Error reading center sensor: %d\n", center_val);
        return -1;
    }

    right_val = gpioRead(RIGHT_SENSOR);
    if (right_val < 0) {
        fprintf(stderr, "Error reading right sensor: %d\n", right_val);
        return -1;
    }

    *left = left_val;
    *center = center_val;
    *right = right_val;

    return 0;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT) failed");
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM) failed");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(LEFT_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LEFT_SENSOR\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(LEFT_SENSOR, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for LEFT_SENSOR\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(CENTER_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for CENTER_SENSOR\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(CENTER_SENSOR, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for CENTER_SENSOR\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RIGHT_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for RIGHT_SENSOR\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for RIGHT_SENSOR\n");
        gpioTerminate();
        return 1;
    }

    // Main loop to read and print sensor values
    int left, center, right;
    while (program_running) {
        if (read_sensors(&left, &center, &right) == 0) {
            printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
        } else {
            fprintf(stderr, "Failed to read sensors\n");
        }
        gpioDelay(100); // Delay for 100ms
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    fprintf(stderr, "pigpio terminated\n");
    return 0;
}

