        perror("signal(SIGTERM) failed");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(LEFT_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LEFT_SENSOR\n");
        gpioTerminate();
        return 1;
    }
