        fprintf(stderr, "Failed to set pull-up for LEFT_SENSOR\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(CENTER_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for CENTER_SENSOR\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(CENTER_SENSOR, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for CENTER_SENSOR\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RIGHT_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for RIGHT_SENSOR\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for RIGHT_SENSOR\n");
        gpioTerminate();
        return 1;
    }

