// Si1175 I2C address
#define SI1175_ADDR 0x60

// Si1175 register addresses
#define SI1175_REG_ALS_LSB 0x22
#define SI1175_REG_ALS_MSB 0x23

// I2C bus
#define I2C_BUS 1

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read ALS data from Si1175
int read_als_data(int i2c_handle) {
    int lsb, msb;

    // Read ALS LSB
    lsb = i2cReadByteData(i2c_handle, SI1175_REG_ALS_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error reading ALS LSB: %d\n", lsb);
        return -1;
    }

    // Read ALS MSB
    msb = i2cReadByteData(i2c_handle, SI1175_REG_ALS_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading ALS MSB: %d\n", msb);
        return -1;
    }

    // Combine LSB and MSB into a 16-bit value
    return (msb << 8) | lsb;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int als_data = read_als_data(i2c_handle);

        if (als_data >= 0) {
            printf("ALS Data: %d\n", als_data);
        } else {
            fprintf(stderr, "Error reading ALS data\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate
    // proper resource cleanup in case the loop is ever modified.
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

