#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR 2
#define MIDDLE_SENSOR 3
#define RIGHT_SENSOR 4

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
    }
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

int main() {
    // Register the signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);

    // Main loop to read and log sensor values
    while (program_running) {
        int left_value = read_sensor(LEFT_SENSOR);
        int middle_value = read_sensor(MIDDLE_SENSOR);
        int right_value = read_sensor(RIGHT_SENSOR);

        // Check for errors during sensor reading
        if (left_value == -1 || middle_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensor values, exiting...\n");
            break; // Exit the loop if there's an error
        }

        // Log the sensor values to stdout
        printf("L:%d M:%d R:%d\n", left_value, middle_value, right_value);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");

    return 0;
}

