#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for each channel
#define CH1_PIN 5
#define CH2_PIN 6
#define CH3_PIN 13
#define CH4_PIN 19
#define CH5_PIN 26
#define CH6_PIN 12
#define CH7_PIN 16
#define CH8_PIN 20

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read the state of a single channel
int read_channel(int pin) {
    return gpioRead(pin);
}

// Function to read all channels and return an array of their states
int* read_all_channels() {
    static int channel_states[8];
    channel_states[0] = read_channel(CH1_PIN);
    channel_states[1] = read_channel(CH2_PIN);
    channel_states[2] = read_channel(CH3_PIN);
    channel_states[3] = read_channel(CH4_PIN);
    channel_states[4] = read_channel(CH5_PIN);
    channel_states[5] = read_channel(CH6_PIN);
    channel_states[6] = read_channel(CH7_PIN);
    channel_states[7] = read_channel(CH8_PIN);
    return channel_states;
}

// Function to format the output string
void format_output(char* buffer, size_t buffer_size, struct timespec ts, int* channel_states) {
    snprintf(buffer, buffer_size, "[%ld.%09ld] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d",
             ts.tv_sec, ts.tv_nsec, channel_states[0], channel_states[1], channel_states[2], channel_states[3],
             channel_states[4], channel_states[5], channel_states[6], channel_states[7]);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Could not register signal handler.\n");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(CH1_PIN, PI_INPUT);
    gpioSetMode(CH2_PIN, PI_INPUT);
    gpioSetMode(CH3_PIN, PI_INPUT);
    gpioSetMode(CH4_PIN, PI_INPUT);
    gpioSetMode(CH5_PIN, PI_INPUT);
    gpioSetMode(CH6_PIN, PI_INPUT);
    gpioSetMode(CH7_PIN, PI_INPUT);
    gpioSetMode(CH8_PIN, PI_INPUT);

    // Main loop
    while (!terminate) {
        // Get current time
        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
            fprintf(stderr, "Error: Could not get current time.\n");
            break; // Exit loop on error
        }

        // Read all channels
        int* channel_states = read_all_channels();

        // Format output string
        char output_buffer[256];
        format_output(output_buffer, sizeof(output_buffer), ts, channel_states);

        // Print output to console
        printf("%s\n", output_buffer);

        // Wait for 200ms
        gpioDelay(200000); // Delay in microseconds
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

