// Number of interpolation steps
#define INTERPOLATION_STEPS 50

// Global variables for current and target RGB values
static volatile int current_red   = 0;
static volatile int current_green = 0;
static volatile int current_blue  = 0;
static volatile int target_red   = 0;
static volatile int target_green = 0;
static volatile int target_blue  = 0;

// Flag to indicate program termination
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int sig);
void set_rgb(int red, int green, int blue);
void interpolate_rgb();
void generate_random_hue();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    terminate = 1;
    set_rgb(0, 0, 0); // Turn off the LED
    closelog();
    exit(0);
}

// Function to set the RGB LED color using PWM
void set_rgb(int red, int green, int blue) {
    // Common anode, so invert the values
    softPwmWrite(RED_PIN, PWM_RANGE - red);
    softPwmWrite(GREEN_PIN, PWM_RANGE - green);
    softPwmWrite(BLUE_PIN, PWM_RANGE - blue);
}

// Function to interpolate between current and target RGB values
void interpolate_rgb() {
    int red_diff   = target_red   - current_red;
    int green_diff = target_green - current_green;
    int blue_diff  = target_blue  - current_blue;

    float red_step   = (float)red_diff   / INTERPOLATION_STEPS;
    float green_step = (float)green_diff / INTERPOLATION_STEPS;
    float blue_step  = (float)blue_diff  / INTERPOLATION_STEPS;

    for (int i = 0; i < INTERPOLATION_STEPS; i++) {
        current_red   += red_step;
        current_green += green_step;
        current_blue  += blue_step;

        // Clamp values to 0-255 range
        if (current_red   < 0) current_red   = 0;
        if (current_red   > 255) current_red   = 255;
        if (current_green < 0) current_green = 0;
        if (current_green > 255) current_green = 255;
        if (current_blue  < 0) current_blue  = 0;
        if (current_blue  > 255) current_blue  = 255;

        set_rgb(current_red, current_green, current_blue);
        delay(50); // Delay for 50ms (5 seconds / 50 steps)
    }

    // Ensure the final color is exactly the target color
    set_rgb(target_red, target_green, target_blue);
    current_red   = target_red;
    current_green = target_green;
    current_blue  = target_blue;
}

// Function to generate a random hue and convert it to RGB
void generate_random_hue() {
    // Generate a random hue (0-360 degrees)
    float hue = (float)rand() / RAND_MAX * 360.0;

    // Convert HSL to RGB (simplified, assuming saturation = 1 and lightness = 0.5)
    float c = 1.0; // Chroma
    float x = c * (1 - fabs(fmod(hue / 60.0, 2) - 1));
    float m = 0.5;

    float r = 0, g = 0, b = 0;

    if (hue >= 0 && hue < 60) {
        r = c; g = x; b = 0;
    } else if (hue >= 60 && hue < 120) {
        r = x; g = c; b = 0;
    } else if (hue >= 120 && hue < 180) {
        r = 0; g = c; b = x;
    } else if (hue >= 180 && hue < 240) {
        r = 0; g = x; b = c;
    } else if (hue >= 240 && hue < 300) {
        r = x; g = 0; b = c;
    } else {
        r = c; g = 0; b = x;
    }

    // Convert to 0-255 range and clamp
    target_red   = (int)((r + m) * 255);
    target_green = (int)((g + m) * 255);
    target_blue  = (int)((b + m) * 255);

    if (target_red   < 0) target_red   = 0;
    if (target_red   > 255) target_red   = 255;
    if (target_green < 0) target_green = 0;
    if (target_green > 255) target_green = 255;
    if (target_blue  < 0) target_blue  = 0;
    if (target_blue  > 255) target_blue  = 255;
}

int main() {
    // Initialize syslog
    openlog("rgb_fader", LOG_PID | LOG_CONS, LOG_USER);

    // Seed the random number generator
    FILE *fp = fopen("/dev/urandom", "r");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open /dev/urandom: %s", strerror(errno));
        return 1;
    }
    unsigned int seed;
    fread(&seed, sizeof(seed), 1, fp);
    fclose(fp);
    srand(seed);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        syslog(LOG_ERR, "Failed to initialize wiringPi: %s", strerror(errno));
        return 1;
    }

    // Set PWM mode to mark:space and range
    softPwmSetMode(RED_PIN, PWM_RANGE, 0);
    softPwmSetMode(GREEN_PIN, PWM_RANGE, 0);
    softPwmSetMode(BLUE_PIN, PWM_RANGE, 0);

    // Set initial RGB values to black (common anode)
    set_rgb(0, 0, 0);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        generate_random_hue();
        interpolate_rgb();
        delay(100); // Delay between hue changes
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_rgb(0, 0, 0);
    closelog();
    return 0;
}

