#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPi.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 registers
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Enable register values
#define TCS34725_PON 0x01
#define TCS34725_AEN 0x02

// Integration time values
#define TCS34725_INTEGRATIONTIME_2_4MS 0xFF   // 2.4ms - 1 cycle    - Max Count: 1024
#define TCS34725_INTEGRATIONTIME_24MS 0xF6   // 24ms  - 10 cycles   - Max Count: 10240
#define TCS34725_INTEGRATIONTIME_50MS 0xEB   // 50ms  - 20 cycles   - Max Count: 20480
#define TCS34725_INTEGRATIONTIME_101MS 0xD5  // 101ms - 42 cycles   - Max Count: 42592
#define TCS34725_INTEGRATIONTIME_154MS 0xC0  // 154ms - 64 cycles   - Max Count: 65535
#define TCS34725_INTEGRATIONTIME_238MS 0x80  // 238ms - 98 cycles   - Max Count: 100864
#define TCS34725_INTEGRATIONTIME_377MS 0x40  // 377ms - 156 cycles  - Max Count: 162201
#define TCS34725_INTEGRATIONTIME_565MS 0x00  // 565ms - 234 cycles  - Max Count: 238208

// GPIO pin for LED
#define LED_PIN 17

// Red value threshold
#define RED_THRESHOLD 200

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int tcs34725_init(int fd);
int tcs34725_read_raw_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
int tcs34725_calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *r, float *g, float *b);
void led_control(int red_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// TCS34725 initialization function
int tcs34725_init(int fd) {
    uint8_t enable_value = TCS34725_PON | TCS34725_AEN;
    uint8_t atime_value = TCS34725_INTEGRATIONTIME_154MS;
    uint8_t control_value = 0x00; // Power saving mode

    // Power on and enable RGBC
    if (write(fd, &enable_value, 1) != 1) {
        perror("Error writing to ENABLE register");
        return -1;
    }

    // Set integration time
    if (write(fd, &atime_value, 1) != 1) {
        perror("Error writing to ATIME register");
        return -1;
    }

    // Set control register (power saving mode)
    if (write(fd, &control_value, 1) != 1) {
        perror("Error writing to CONTROL register");
        return -1;
    }

    return 0;
}

// TCS34725 read raw data function
int tcs34725_read_raw_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buffer[8];

    // Read all color data registers in one go
    if (write(fd, TCS34725_COMMAND_BIT | TCS34725_CDATA, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(fd, buffer, 8) != 8) {
        perror("Error reading from I2C device");
        return -1;
    }

    *clear = (buffer[1] << 8) | buffer[0];
    *red   = (buffer[3] << 8) | buffer[2];
    *green = (buffer[5] << 8) | buffer[4];
    *blue  = (buffer[7] << 8) | buffer[6];

    return 0;
}

// TCS34725 calibrate data function
int tcs34725_calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *r, float *g, float *b) {
    // Simple calibration (replace with actual calibration values)
    float clear_inv = 1.0f / (float)clear;

    *r = (float)red * clear_inv;
    *g = (float)green * clear_inv;
    *b = (float)blue * clear_inv;

    return 0;
}

// LED control function
void led_control(int red_value) {
    if (red_value > RED_THRESHOLD) {
        digitalWrite(LED_PIN, HIGH); // Turn LED on
    } else {
        digitalWrite(LED_PIN, LOW);  // Turn LED off
    }
}

int main() {
    uint16_t clear, red, green, blue;
    float r, g, b;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) != 0) {
        fprintf(stderr, "TCS34725 initialization failed. Retrying...\n");
        close(i2c_fd);
        i2c_fd = open("/dev/i2c-1", O_RDWR);
        if (i2c_fd < 0) {
            perror("Error opening I2C bus");
            return 1;
        }
        if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
            perror("Error setting I2C slave address");
            close(i2c_fd);
            return 1;
        }
        if (tcs34725_init(i2c_fd) != 0) {
            fprintf(stderr, "TCS34725 initialization failed after retry. Exiting.\n");
            close(i2c_fd);
            return 1;
        }
    }

    printf("TCS34725 sensor initialized successfully.\n");

    // Main loop
    while (program_running) {
        // Read raw data from sensor
        if (tcs34725_read_raw_data(i2c_fd, &clear, &red, &green, &blue) == 0) {
            // Calibrate data
            if (tcs34725_calibrate_data(clear, red, green, blue, &r, &g, &b) == 0) {
                // Print calibrated values
                printf("R: %.2f, G: %.2f, B: %.2f, C: %d\n", r, g, b, clear);

                // Control LED
                led_control(red);
            } else {
                fprintf(stderr, "Error calibrating data.\n");
            }
        } else {
            fprintf(stderr, "Error reading raw data. Re-initializing sensor...\n");
            close(i2c_fd);
            i2c_fd = open("/dev/i2c-1", O_RDWR);
            if (i2c_fd < 0) {
                perror("Error opening I2C bus");
                program_running = 0; // Exit loop if I2C fails repeatedly
                continue;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
                perror("Error setting I2C slave address");
                close(i2c_fd);
                program_running = 0; // Exit loop if I2C fails repeatedly
                continue;
            }
            if (tcs34725_init(i2c_fd) != 0) {
                fprintf(stderr, "TCS34725 initialization failed after retry. Exiting.\n");
                program_running = 0;
            }
        }

        // Delay for 200ms
        delay(200);
    }

    // Clean up resources
    printf("Cleaning up resources...\n");
    digitalWrite(LED_PIN, LOW); // Turn off LED
    close(i2c_fd);

    return 0;
}

