#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define WS2812B_GPIO 18
#define NUM_LEDS 10
#define PWM_RANGE 4096 // Adjust as needed
#define PWM_FREQUENCY 800000 // 800kHz

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_bh1750();
float read_lux();
int map_lux_to_brightness(float lux);
int set_led_brightness(int brightness);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize BH1750 sensor
int init_bh1750() {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Set continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750
float read_lux() {
    int raw_value;
    float lux;

    // Read two bytes from the sensor
    raw_value = i2cReadWordData(i2c_handle, 0x00);
    if (raw_value < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", i2c_handle);
        return -1.0; // Indicate error
    }

    // BH1750 returns big-endian, so swap bytes
    raw_value = ((raw_value & 0xFF00) >> 8) | ((raw_value & 0x00FF) << 8);

    // Convert to lux
    lux = (float)raw_value / 1.2;

    return lux;
}

// Map lux value to brightness level (0-255)
int map_lux_to_brightness(float lux) {
    // Use a logarithmic scale for brightness mapping
    float log_lux = log10(lux + 1); // Add 1 to avoid log(0)
    float brightness_float = 255.0 * (log_lux / log10(10000)); // Scale to 0-255 (assuming max lux of 10000)

    // Clamp the brightness value to the range 0-255
    int brightness = (int)brightness_float;
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    return brightness;
}

// Set the brightness of the WS2812B LED strip
int set_led_brightness(int brightness) {
    // Create a wave to represent the LED data
    gpioWaveClear();

    // Calculate the number of pulses for each bit
    int num_pulses = PWM_RANGE; // Number of pulses for a full cycle

    // Calculate the number of pulses for a '0' and '1' bit
    int zero_pulses = num_pulses / 2; // 50% duty cycle
