#define I2C_RETRY_COUNT 3

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_setup(const char *bus);
int bh1750_init(int fd);
int bh1750_read(int fd, uint16_t *lux);
int spi_setup(const char *bus);
int apa102_set_leds(int fd, uint8_t brightness, uint8_t red, uint8_t green, uint8_t blue);
int apa102_send_data(int fd, uint8_t *data, size_t len);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// I2C setup function
int i2c_setup(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// BH1750 initialization function
int bh1750_init(int fd) {
    uint8_t config[1] = {0x10}; // Continuous high-resolution mode
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    if (write(fd, config, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// BH1750 read function
int bh1750_read(int fd, uint16_t *lux) {
    uint8_t buffer[2];
    int retries = I2C_RETRY_COUNT;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
            perror("Error setting I2C slave address");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        if (read(fd, buffer, 2) == 2) {
            *lux = (buffer[0] << 8) | buffer[1];
            return 0;
        } else {
            perror("Error reading from I2C device");
            retries--;
            usleep(10000); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read BH1750 after multiple retries.\n");
    return -1;
}

// SPI setup function
int spi_setup(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI bus");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// APA102 set LEDs function
int apa102_set_leds(int fd, uint8_t brightness, uint8_t red, uint8_t green, uint8_t blue) {
    uint8_t data[4];
    data[0] = 0xE0 | brightness; // Global brightness
    data[1] = blue;
    data[2] = green;
    data[3] = red;
    return apa102_send_data(fd, data, 4);
}

// APA102 send data function
int apa102_send_data(int fd, uint8_t *data, size_t len) {
    uint8_t spi_data[len];
    memcpy(spi_data, data, len);

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)spi_data,
        .len = len,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error sending SPI message");
        return -1;
    }
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Turn off all LEDs
    if (spi_fd != -1) {
        uint8_t end_frame[4] = {0x00, 0x00, 0x00, 0x00};
        apa102_send_data(spi_fd, end_frame, 4);
        close(spi_fd);
    }

    // Close I2C bus
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    printf("Cleanup complete.\n");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C setup failed. Exiting.\n");
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_setup(SPI_BUS);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI setup failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Send start frame
    uint8_t start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    if (apa102_send_data(spi_fd, start_frame, 4) < 0) {
        fprintf(stderr, "Failed to send start frame. Exiting.\n");
        cleanup();
        return 1;
    }

    uint16_t lux;
    uint8_t brightness = 0;

    while (!terminate) {
        // Read light level
        if (bh1750_read(i2c_fd, &lux) == 0) {
            // Scale brightness (example: map 0-1000 lux to 0-31 brightness)
            brightness = (uint8_t)(lux > 1000 ? 31 : (lux * 31) / 1000);

            // Set LED color (example: white)
            if (apa102_set_leds(spi_fd, brightness, 0xFF, 0xFF, 0xFF) < 0) {
                fprintf(stderr, "Failed to set LEDs.\n");
            }
        } else {
            fprintf(stderr, "Failed to read light level.\n");
        }

        usleep(100000); // 100ms delay
    }

    cleanup();
    return 0;
}

