// Initialize BH1750 sensor
int init_bh1750(int address) {
    int handle = i2cOpen(I2C_BUS, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", address, handle);
        return -1;
    }

    int result = i2cWriteByteData(handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device at address 0x%02X: %d\n", address, result);
        i2cClose(handle);
        return -1;
    }

    return handle;
}

// Read light level from BH1750 sensor
int read_bh1750(int handle) {
    int retries = NUM_RETRIES;
    while (retries > 0) {
        int result = i2cReadWordData(handle, 0x00);
        if (result >= 0) {
            // Byte swap needed for correct value
            return (result >> 8) | (result << 8);
        } else {
            fprintf(stderr, "Error reading from I2C device: %d, retries left: %d\n", result, retries);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }
    return -1; // Indicate error after retries
}

// Average light levels from valid sensors
float average_light_level(int *readings, int num_sensors) {
    float sum = 0.0;
    int count = 0;
    for (int i = 0; i < num_sensors; i++) {
        if (readings[i] > 0) {
            sum += readings[i];
            count++;
        }
    }
    if (count > 0) {
        return sum / count;
    } else {
        return 0.0; // Return 0 if no valid readings
    }
}

