#include <math.h>

// VEML7700 I2C address
#define VEML7700_ADDR 0x48

// VEML7700 register addresses
#define VEML7700_ALS_CONF 0x00
#define VEML7700_ALS_WH 0x01
#define VEML7700_ALS_WL 0x02
#define VEML7700_ALS 0x04
#define VEML7700_WHITE 0x05
#define VEML7700_POWER_SAVE 0x06

// WS2812B GPIO pin
#define WS2812B_GPIO 18

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int veml7700_init(int i2c_handle);
float veml7700_read_lux(int i2c_handle);
int gamma_correct(float lux);
void ws2812b_set_color(int gpio, int brightness);
void ws2812b_send_data(int gpio, int brightness);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// VEML7700 initialization function
int veml7700_init(int i2c_handle) {
    // Configuration: Integration time = 100ms, Gain = 1/8
    uint16_t config_value = 0x0000; // Default configuration
    config_value |= (0x02 << 11); // Integration time = 100ms
    config_value |= (0x00 << 6);  // Gain = 1/8

    char buf[3];
    buf[0] = VEML7700_ALS_CONF;
    buf[1] = config_value & 0xFF;
    buf[2] = (config_value >> 8) & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to VEML7700 configuration register: %d\n", result);
        return -1;
    }

    return 0;
}

// VEML7700 read lux function
float veml7700_read_lux(int i2c_handle) {
    char reg = VEML7700_ALS;
    char data[2];
    int result;

    result = i2cWriteDevice(i2c_handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to VEML7700 ALS register: %d\n", result);
        return -1.0f;
    }

    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading from VEML7700 ALS register: %d\n", result);
        return -1.0f;
    }

    uint16_t als_data = (data[1] << 8) | data[0];

    // Conversion formula (example, adjust based on datasheet)
    float lux = (float)als_data * 0.0576; // Example conversion factor

    return lux;
}

// Gamma correction function
int gamma_correct(float lux) {
    float gamma = 2.2f;
    float brightness_float = powf(lux / 1000.0f, gamma); // Normalize lux and apply gamma
    if (brightness_float < 0.0f) brightness_float = 0.0f;
    if (brightness_float > 1.0f) brightness_float = 1.0f;

    return (int)(brightness_float * 255.0f);
}

// WS2812B set color function (simplified for single color)
void ws2812b_set_color(int gpio, int brightness) {
    ws2812b_send_data(gpio, brightness);
}

// WS2812B send data function (bit-banging)
void ws2812b_send_data(int gpio, int brightness) {
    // WS2812B timing (approximate, adjust as needed)
    int t0h = 0.4;  // 0.4 us
    int t0l = 0.85; // 0.85 us
    int t1h = 0.8;  // 0.8 us
    int t1l = 0.45; // 0.45 us
    int reset_time = 50; // Reset time in us

    // Send start bit (0)
    gpioWrite(gpio, 0);
    gpioDelay(t0h * 1000); // Convert us to ns
    gpioWrite(gpio, 1);
    gpioDelay(t0l * 1000);

    // Send color data (GRB, but only brightness here)
    for (int i = 23; i >= 0; i--) {
        if ((brightness >> i) & 1) {
            // Send 1
            gpioWrite(gpio, 0);
            gpioDelay(t1h * 1000);
            gpioWrite(gpio, 1);
            gpioDelay(t1l * 1000);
        } else {
            // Send 0
            gpioWrite(gpio, 0);
            gpioDelay(t0h * 1000);
            gpioWrite(gpio, 1);
            gpioDelay(t0l * 1000);
        }
    }

    // Reset signal
    gpioWrite(gpio, 0);
    gpioDelay(reset_time * 1000);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700 sensor
    if (veml7700_init(i2c_handle) != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set WS2812B GPIO as output
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read lux value
        float lux = veml7700_read_lux(i2c_handle);
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value\n");
            continue; // Skip to the next iteration
        }

        // Apply gamma correction
        int brightness = gamma_correct(lux);

        // Set LED brightness
        ws2812b_set_color(WS2812B_GPIO, brightness);

        // Print lux and brightness values
        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        // Pause for 200ms
        gpioDelay(200000); // 200ms = 200000 us
    }

    // Cleanup
    ws2812b_set_color(WS2812B_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

