#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_LED 17
#define BUFFER_SIZE 60
#define MIN_LUX 0.0
#define MAX_LUX 1000.0
#define MIN_FREQUENCY 0.5
#define MAX_FREQUENCY 5.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int init_gpio();
void init_circular_buffer(CircularBuffer *cb);
void add_to_circular_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
float map_lux_to_frequency(float lux);
void set_led_frequency(float frequency);
void signal_handler(int signal);
void cleanup();

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error configuring BH1750: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        cb->buffer[i] = 0.0;
    }
}

// Add value to circular buffer
void add_to_circular_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate average of circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Map lux value to frequency
float map_lux_to_frequency(float lux) {
    if (lux <= MIN_LUX) {
        return MIN_FREQUENCY;
    } else if (lux >= MAX_LUX) {
        return MAX_FREQUENCY;
    } else {
        return MIN_FREQUENCY + (lux - MIN_LUX) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_LUX - MIN_LUX);
    }
}

// Set LED blinking frequency
void set_led_frequency(float frequency) {
    if (frequency <= 0.0) {
        gpioWrite(GPIO_LED, 0); // Turn off LED
        return;
    }

    // Calculate on/off times in microseconds
    int period_us = (int)(1000000.0 / frequency);
    int on_time_us = period_us / 2;
    int off_time_us = period_us - on_time_us;

    gpioWrite(GPIO_LED, 1); // Turn on LED
    gpioDelay(on_time_us);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioDelay(off_time_us);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioSetMode(GPIO_LED, PI_INPUT); // Set GPIO to input mode
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer lux_buffer;
    init_circular_buffer(&lux_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Program running. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read lux value from BH1750
        int lux_raw = i2cReadWordData(i2c_handle, 0x00);
        if (lux_raw < 0) {
            fprintf(stderr, "Error reading lux value: %s\n", strerror(errno));
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert raw value to lux
        float lux = (float)lux_raw / 1.2; // BH1750 datasheet conversion

        // Add lux value to circular buffer
        add_to_circular_buffer(&lux_buffer, lux);

        // Calculate average lux
        float average_lux = calculate_average(&lux_buffer);

        // Map average lux to frequency
        float frequency = map_lux_to_frequency(average_lux);

        // Set LED frequency
        set_led_frequency(frequency);

        // Wait 1 second
        gpioDelay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

