    0b00111111, // 0
    0b00000110, // 1
    0b01011011, // 2
    0b01001111, // 3
    0b01100110, // 4
    0b01101101, // 5
    0b01111101, // 6
    0b00000111, // 7
    0b01111111, // 8
    0b01101111  // 9
};

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to shift out data to the 74HC595
void shift_out(unsigned char data) {
    for (int i = 0; i < 8; i++) {
        // Set data pin based on the current bit
        gpioWrite(DATA_PIN, (data >> (7 - i)) & 0x01);

        // Clock high
        gpioWrite(CLOCK_PIN, 1);
        gpioDelay(1); // Small delay for clock stability

        // Clock low
        gpioWrite(CLOCK_PIN, 0);
        gpioDelay(1); // Small delay for clock stability
    }
}

// Function to latch the data to the output
void latch() {
    gpioWrite(LATCH_PIN, 1);
    gpioDelay(1); // Small delay for latch stability
    gpioWrite(LATCH_PIN, 0);
    gpioDelay(1); // Small delay for latch stability
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(DATA_PIN, PI_OUTPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(LATCH_PIN, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Shift out the pattern for digit '5'
        shift_out(segment_patterns[5]);

        // Latch the data
        latch();

        // Wait for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds

        // Turn off the display by shifting out 0s
        shift_out(0x00);
        latch();
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Clean up GPIO pins
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);
    gpioSetMode(DATA_PIN, PI_INPUT); // Set back to input to avoid issues
    gpioSetMode(CLOCK_PIN, PI_INPUT);
    gpioSetMode(LATCH_PIN, PI_INPUT);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

