#include <gpiod.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Define GPIO chip
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *led_line;
struct gpiod_line *button_line;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int ret;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request LED line as output
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(led_line, "blink_button", 0); // Initial value: LOW
    if (ret < 0) {
        perror("Error requesting LED line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request button line as input with pull-up
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Error getting button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(button_line, "blink_button");
    if (ret < 0) {
        perror("Error requesting button line as input");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set pull-up resistor on button line
    ret = gpiod_line_set_pull_request(button_line, GPIOD_LINE_REQUEST_PULL_UP);
    if (ret < 0) {
        perror("Error setting pull-up resistor on button line");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request falling edge event detection on button line
    struct gpiod_line_event event;
    ret = gpiod_line_event_wait(button_line, &event, 1); // Timeout of 1 second
    if (ret < 0) {
        perror("Error requesting falling edge event detection");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Blink LED with 2-second period (1 second on, 1 second off)
    while (1) {
        // Turn LED on
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("Error setting LED value to 1");
            gpiod_line_release(led_line);
            gpiod_line_release(button_line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Wait for 1 second
        ret = gpiod_line_event_wait(button_line, &event, 1);
        if (ret < 0) {
            perror("Error waiting for event");
            gpiod_line_release(led_line);
            gpiod_line_release(button_line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Check if button was pressed during the wait
        if (ret > 0) {
            // Button pressed, stop blinking
            break;
        }

        // Turn LED off
        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("Error setting LED value to 0");
            gpiod_line_release(led_line);
            gpiod_line_release(button_line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Wait for 1 second
        ret = gpiod_line_event_wait(button_line, &event, 1);
        if (ret < 0) {
            perror("Error waiting for event");
            gpiod_line_release(led_line);
            gpiod_line_release(button_line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Check if button was pressed during the wait
        if (ret > 0) {
            // Button pressed, stop blinking
            break;
        }
    }

    // Button was pressed, turn LED off and print message
    ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        perror("Error setting LED value to 0");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Button pressed! Stopping blinking.\n");

    // Release GPIO lines
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

