#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for RGB LED
#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

// PWM frequency (Hz)
#define PWM_FREQUENCY 100

// PWM period (microseconds)
#define PWM_PERIOD (1000000 / PWM_FREQUENCY)

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal)
{
    if (signal == SIGINT)
    {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set the intensity of a single color channel using software PWM
void set_color_intensity(int gpio_pin, int intensity)
{
    if (intensity < 0 || intensity > 100)
    {
        fprintf(stderr, "Error: Invalid intensity value. Must be between 0 and 100.\n");
        return;
    }

    // Calculate on and off times based on intensity
    int on_time = (intensity * PWM_PERIOD) / 100;
    int off_time = PWM_PERIOD - on_time;

    // Set the GPIO pin HIGH for the on time
    gpioWrite(gpio_pin, 1);
    gpioDelay(on_time);

    // Set the GPIO pin LOW for the off time
    gpioWrite(gpio_pin, 0);
    gpioDelay(off_time);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Seed the random number generator
    srand(time(NULL));

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("RGB LED control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running)
    {
        // Generate random intensity values for each color channel
        int red_intensity = rand() % 101;
        int green_intensity = rand() % 101;
        int blue_intensity = rand() % 101;

        // Set the color intensities using software PWM
        set_color_intensity(RED_PIN, red_intensity);
        set_color_intensity(GREEN_PIN, green_intensity);
        set_color_intensity(BLUE_PIN, blue_intensity);

        // Wait for 100ms before changing the color
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Clean up GPIO resources before exiting
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);

    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

