#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x19

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

// GPIO pin for impact interrupt
#define IMPACT_PIN 17

// Default G-force threshold
#define DEFAULT_THRESHOLD 2.0

// Global variables
int i2c_handle;
double g_threshold = DEFAULT_THRESHOLD;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x, y, z;
} accelerometer_data_t;

// Function prototypes
int init_i2c();
int init_gpio();
int init_lsm303();
accelerometer_data_t read_accelerometer_data();
double calculate_g_force_magnitude(accelerometer_data_t data);
void trigger_impact_interrupt();
void log_data(accelerometer_data_t data, double magnitude);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0); // Bus 1, address 0x19, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(IMPACT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    gpioWrite(IMPACT_PIN, 0); // Ensure pin is initially LOW
    return 0;
}

// Initialize LSM303DLHC accelerometer
int init_lsm303() {
    // Enable accelerometer, 10 Hz data rate
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return -1;
    }
    return 0;
}

// Read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Calculate G-force magnitude
double calculate_g_force_magnitude(accelerometer_data_t data) {
    double x = (double)data.x / 16384.0; // Assuming +/- 2G sensitivity
    double y = (double)data.y / 16384.0;
    double z = (double)data.z / 16384.0;
    return sqrt(x * x + y * y + z * z);
}

// Trigger impact interrupt
void trigger_impact_interrupt() {
    gpioWrite(IMPACT_PIN, 1); // Set pin HIGH
    gpioDelay(50000);         // Wait 50 ms
    gpioWrite(IMPACT_PIN, 0); // Set pin LOW
}

// Log data to file
void log_data(accelerometer_data_t data, double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %.4f\n", timestamp, data.x, data.y, data.z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(IMPACT_PIN, 0); // Ensure pin is LOW
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        g_threshold = strtod(argv[1], &endptr);
        if (*endptr != '\0') {
            fprintf(stderr, "Invalid threshold value: %s\n", argv[1]);
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize LSM303DLHC
    if (init_lsm303() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring accelerometer... (Threshold: %.2f G)\n", g_threshold);

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();
        double magnitude = calculate_g_force_magnitude(data);

        if (magnitude > g_threshold) {
            trigger_impact_interrupt();
        }

        log_data(data, magnitude);
        gpioDelay(100000); // 10 Hz polling rate (100 ms delay)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

