#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ADPD188BI I2C address
#define ADPD188BI_ADDR 0x39

// Register addresses (replace with actual values from datasheet)
#define ALS_LSB_REG 0x00
#define ALS_MSB_REG 0x01
#define RED_LSB_REG 0x02
#define RED_MSB_REG 0x03
#define GREEN_LSB_REG 0x04
#define GREEN_MSB_REG 0x05
#define BLUE_LSB_REG 0x06
#define BLUE_MSB_REG 0x07

// GPIO pin for LED control
#define LED_PIN 18

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
uint16_t combine_als(uint8_t lsb, uint8_t msb);
void log_data(sensor_data_t data);
void control_led(uint16_t als_value);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, ADPD188BI_ADDR, 0); // Bus 1, address 0x39, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data from ADPD188BI
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[8];
    int result;

    // Read ALS LSB and MSB
    result = i2cReadI2CBlockData(i2c_handle, ALS_LSB_REG, (char *)buffer, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    // Combine ALS data
    data->als = combine_als(buffer[0], buffer[1]);

    // Combine Red data
    data->red = combine_als(buffer[2], buffer[3]);

    // Combine Green data
    data->green = combine_als(buffer[4], buffer[5]);

    // Combine Blue data
    data->blue = combine_als(buffer[6], buffer[7]);

    return 0;
}

// Combine ALS LSB and MSB into a 16-bit unsigned value
uint16_t combine_als(uint8_t lsb, uint8_t msb) {
    return ((uint16_t)msb << 8) | lsb;
}

// Log data to CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, data.als, data.red, data.green, data.blue);
    fflush(log_file); // Ensure data is written to file immediately
}

// Control LED brightness using PWM
void control_led(uint16_t als_value) {
    // Map ALS value to PWM duty cycle (0-1000000)
    int duty_cycle = (int)(((float)als_value / 65535.0) * 1000000.0);

    // Set PWM duty cycle
    gpioPWM(LED_PIN, duty_cycle);
}

// Cleanup resources before exiting
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LED_PIN, PWM_FREQUENCY);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data
            log_data(sensor_data);

            // Control LED
            control_led(sensor_data.als);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

