#define ACCEL_RANGE_2G 0x00
#define DATA_RATE_200HZ 0x3F

#define IMPACT_THRESHOLD 2.0f

// Global variables
static int i2c_handle;
static volatile int running = 1;

// Function prototypes
int init_fxos8700cq();
int read_accel_data(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void log_impact(float x, float y, float z, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the FXOS8700CQ sensor
int init_fxos8700cq() {
    int status;

    // Verify WHO_AM_I register
    status = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", status);
        return -1;
    }
    if (status != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, status);
        return -1;
    }

    // Standby mode
    status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing CTRL_REG1 (standby): %d\n", status);
        return -1;
    }

    // Configure accelerometer range
    status = i2cWriteByteData(i2c_handle, CTRL_REG2, ACCEL_RANGE_2G);
    if (status < 0) {
        fprintf(stderr, "Error writing CTRL_REG2 (accel range): %d\n", status);
        return -1;
    }

    // Configure data rate
    status = i2cWriteByteData(i2c_handle, CTRL_REG1, DATA_RATE_200HZ);
    if (status < 0) {
        fprintf(stderr, "Error writing CTRL_REG1 (data rate): %d\n", status);
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accel_data(float *x, float *y, float *z) {
    char buffer[6];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", status);
        return -1;
    }

    // Combine MSB and LSB, and convert to g
    *x = (float)((int16_t)((buffer[0] << 8) | buffer[1])) / 4096.0f; // 2^12 = 4096
    *y = (float)((int16_t)((buffer[2] << 8) | buffer[3])) / 4096.0f;
    *z = (float)((int16_t)((buffer[4] << 8) | buffer[5])) / 4096.0f;

    return 0;
}

// Calculate acceleration magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

// Log impact event to file
void log_impact(float x, float y, float z, float magnitude) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);
}

int main() {
    float x, y, z, magnitude;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_fxos8700cq() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        if (read_accel_data(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > IMPACT_THRESHOLD) {
                log_impact(x, y, z, magnitude);
                printf("Impact detected: x=%.3f, y=%.3f, z=%.3f, magnitude=%.3f\n", x, y, z, magnitude);
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data. Retrying...\n");
        }

        gpioDelay(50); // 50 ms delay
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

