#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// GY-50 L3G4200D I2C address
#define GY50_ADDR 0x69

// L3G4200D registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F

// WHO_AM_I expected value
#define WHO_AM_I_VALUE 0xD3

// Sensitivity (for +/- 250 dps range)
#define SENSITIVITY 0.00875 // dps/LSB

// Alert threshold (dps)
#define ALERT_THRESHOLD 50.0

// Sampling rate (Hz)
#define SAMPLING_RATE 20

// Calibration samples
#define CALIBRATION_SAMPLES 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_i2c();
int init_gyro();
int read_gyro_data(gyro_data_t *data);
int calibrate_gyro(float *x_offset, float *y_offset, float *z_offset);
int log_data(gyro_data_t data, float x_offset, float y_offset, float z_offset);
void signal_handler(int signal);
int i2c_read_reg(int handle, uint8_t reg);
int i2c_write_reg(int handle, uint8_t reg, uint8_t value);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

// I2C read register function with error handling
int i2c_read_reg(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// I2C write register function with error handling
int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, GY50_ADDR, 0); // Bus 1, address 0x69, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize gyroscope
int init_gyro() {
    // Enable gyroscope, 100Hz data rate, normal mode
    if (i2c_write_reg(i2c_handle, CTRL_REG1, 0x0F) < 0) {
        return -1;
    }

    // Set full-scale range to +/- 250 dps
    if (i2c_write_reg(i2c_handle, CTRL_REG4, 0x00) < 0) {
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2c_read_reg(i2c_handle, WHO_AM_I);
    if (who_am_i < 0 || who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I check failed: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    int16_t x, y, z;

    int x_l = i2c_read_reg(i2c_handle, OUT_X_L);
    int x_h = i2c_read_reg(i2c_handle, OUT_X_H);
    int y_l = i2c_read_reg(i2c_handle, OUT_Y_L);
    int y_h = i2c_read_reg(i2c_handle, OUT_Y_H);
    int z_l = i2c_read_reg(i2c_handle, OUT_Z_L);
    int z_h = i2c_read_reg(i2c_handle, OUT_Z_H);

    if (x_l < 0 || x_h < 0 || y_l < 0 || y_h < 0 || z_l < 0 || z_h < 0) {
        return -1;
    }

    x = (int16_t)((x_h << 8) | x_l);
    y = (int16_t)((y_h << 8) | y_l);
    z = (int16_t)((z_h << 8) | z_l);

    data->x = (float)x * SENSITIVITY;
    data->y = (float)y * SENSITIVITY;
    data->z = (float)z * SENSITIVITY;

    return 0;
}

// Calibrate gyroscope
int calibrate_gyro(float *x_offset, float *y_offset, float *z_offset) {
    float x_sum = 0, y_sum = 0, z_sum = 0;
    gyro_data_t data;

    printf("Calibrating gyroscope...\n");
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (read_gyro_data(&data) < 0) {
            fprintf(stderr, "Error reading gyro data during calibration\n");
            return -1;
        }
        x_sum += data.x;
        y_sum += data.y;
        z_sum += data.z;
        gpioDelay(5); // Small delay between readings
    }

    *x_offset = x_sum / CALIBRATION_SAMPLES;
    *y_offset = y_sum / CALIBRATION_SAMPLES;
    *z_offset = z_sum / CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.3f, Y=%.3f, Z=%.3f\n", *x_offset, *y_offset, *z_offset);
    return 0;
}

// Log data to file
int log_data(gyro_data_t data, float x_offset, float y_offset, float z_offset) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x - x_offset, data.y - y_offset, data.z - z_offset);
    fflush(log_file);

    // Check for alert condition
    if (fabs(data.x - x_offset) > ALERT_THRESHOLD ||
        fabs(data.y - y_offset) > ALERT_THRESHOLD ||
        fabs(data.z - z_offset) > ALERT_THRESHOLD) {
        fprintf(log_file, "%s,ALERT: X=%.3f, Y=%.3f, Z=%.3f\n", timestamp, data.x - x_offset, data.y - y_offset, data.z - z_offset);
        fprintf(stderr, "ALERT: X=%.3f, Y=%.3f, Z=%.3f\n", data.x - x_offset, data.y - y_offset, data.z - z_offset);
        fflush(log_file);
    }

    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize gyroscope
    if (init_gyro() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Calibrate gyroscope
    float x_offset, y_offset, z_offset;
    if (calibrate_gyro(&x_offset, &y_offset, &z_offset) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gyro_data_t data;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&data) < 0) {
            fprintf(stderr, "Error reading gyro data\n");
            break;
        }

        if (log_data(data, x_offset, y_offset, z_offset) < 0) {
            fprintf(stderr, "Error logging data\n");
            break;
        }

        gpioDelay(50); // 50 ms delay for 20 Hz sampling rate
    }

    // Close I2C and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

