#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Define I2C bus
#define I2C_BUS 1

// Define sampling interval (10 ms)
#define SAMPLING_INTERVAL 10000 // microseconds

// Define TDOA threshold (5 ms)
#define TDOA_THRESHOLD 5000 // microseconds

// Define data file name
#define DATA_FILE "audio_log.dat"

// Structure to hold sensor data and I2C handle
typedef struct {
    int i2c_handle;
    int address;
    char *name;
} sensor_t;

// Global variables
static volatile int running = 1;
static FILE *data_file = NULL;
sensor_t sensor1, sensor2;

// Function prototypes
int initialize_pigpio();
int initialize_i2c(sensor_t *sensor);
int read_sensor_data(sensor_t *sensor, int16_t *data);
int calculate_tdoa(int16_t sensor1_data, int16_t sensor2_data);
int log_data(int sec, int nsec, int16_t sensor1_data, int16_t sensor2_data, int tdoa);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C for a sensor
int initialize_i2c(sensor_t *sensor) {
    sensor->i2c_handle = i2cOpen(I2C_BUS, sensor->address, 0);
    if (sensor->i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device for %s at address 0x%02x: %s\n", sensor->name, sensor->address, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read data from a sensor
int read_sensor_data(sensor_t *sensor, int16_t *data) {
    char buffer[2];
    int bytes_read = i2cReadDevice(sensor->i2c_handle, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read data from %s: %s\n", sensor->name, strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *data = (int16_t)((buffer[0] << 8) | buffer[1]);
    return 0;
}

// Function to calculate TDOA
int calculate_tdoa(int16_t sensor1_data, int16_t sensor2_data) {
    // Simple TDOA calculation based on the difference in sample values
    // This is a placeholder and needs to be replaced with a proper TDOA algorithm
    // based on cross-correlation or other suitable methods.
    int tdoa = sensor1_data - sensor2_data;
    return tdoa;
}

// Function to log data to a file
int log_data(int sec, int nsec, int16_t sensor1_data, int16_t sensor2_data, int tdoa) {
    if (data_file == NULL) {
        fprintf(stderr, "Data file is not open\n");
        return -1;
    }

    fprintf(data_file, "%d,%d,%d,%d,%d\n", sec, nsec, sensor1_data, sensor2_data, tdoa);
    fflush(data_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to perform cleanup
void cleanup() {
    printf("Cleaning up...\n");

    // Close I2C handles
    if (sensor1.i2c_handle >= 0) {
        i2cClose(sensor1.i2c_handle);
    }
    if (sensor2.i2c_handle >= 0) {
        i2cClose(sensor2.i2c_handle);
    }

    // Close data file
    if (data_file != NULL) {
        fclose(data_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Initialize sensor structures
    sensor1.address = SENSOR1_ADDR;
    sensor1.name = "Sensor 1";
    sensor1.i2c_handle = -1; // Initialize to an invalid handle

    sensor2.address = SENSOR2_ADDR;
    sensor2.name = "Sensor 2";
    sensor2.i2c_handle = -1; // Initialize to an invalid handle

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C for both sensors
    if (initialize_i2c(&sensor1) != 0) {
        cleanup();
        return 1;
    }
    if (initialize_i2c(&sensor2) != 0) {
        cleanup();
        return 1;
    }

    // Open data file
    data_file = fopen(DATA_FILE, "a");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open data file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        struct timespec ts;
        int16_t sensor1_data, sensor2_data;
        int tdoa;

        // Read data from sensor 1
        if (read_sensor_data(&sensor1, &sensor1_data) != 0) {
            fprintf(stderr, "Error reading sensor 1 data, retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        // Read data from sensor 2
        if (read_sensor_data(&sensor2, &sensor2_data) != 0) {
            fprintf(stderr, "Error reading sensor 2 data, retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        // Calculate TDOA
        tdoa = calculate_tdoa(sensor1_data, sensor2_data);

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Failed to get timestamp: %s\n", strerror(errno));
            continue;
        }

        // Log data
        if (log_data(ts.tv_sec, ts.tv_nsec, sensor1_data, sensor2_data, tdoa) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Delay for sampling interval
        gpioDelay(SAMPLING_INTERVAL);
    }

    // Perform cleanup before exiting
    cleanup();

    return 0;
}

