#define ACCEL_SENSITIVITY 0.00025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t running = 1;

// Function prototypes
int read_register(int handle, uint8_t reg_addr);
int write_register(int handle, uint8_t reg_addr, uint16_t data);
int read_imu_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z);
void log_data(FILE *fp, struct timespec ts, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z);
void cleanup(int signum);

// Signal handler
void signal_handler(int signum) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signum);
}

// Function to read a single register from the ADIS16488A
int read_register(int handle, uint8_t reg_addr) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = 0x00; // Command bit is 0 for read
    tx_buf[1] = reg_addr;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI transfer failed in read_register\n");
        return -1;
    }

    return (rx_buf[0] << 8) | rx_buf[1]; // Combine the two bytes into a 16-bit value
}

// Function to write a single register to the ADIS16488A
int write_register(int handle, uint8_t reg_addr, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = 0x80; // Command bit is 1 for write
    tx_buf[1] = reg_addr;
    tx_buf[2] = data & 0xFF; //LSB

    if (spiXfer(handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed in write_register\n");
        return -1;
    }

    return 0;
}

// Function to read IMU data and convert to physical units
int read_imu_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z) {
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

    raw_gyro_x = read_register(handle, REG_GYRO_XOUT);
    raw_gyro_y = read_register(handle, REG_GYRO_YOUT);
    raw_gyro_z = read_register(handle, REG_GYRO_ZOUT);
    raw_accel_x = read_register(handle, REG_ACCEL_XOUT);
    raw_accel_y = read_register(handle, REG_ACCEL_YOUT);
    raw_accel_z = read_register(handle, REG_ACCEL_ZOUT);

    if (raw_gyro_x == -1 || raw_gyro_y == -1 || raw_gyro_z == -1 ||
        raw_accel_x == -1 || raw_accel_y == -1 || raw_accel_z == -1) {
        fprintf(stderr, "Error: Failed to read IMU data\n");
        return -1;
    }

    *gyro_x = (float)raw_gyro_x * GYRO_SENSITIVITY;
    *gyro_y = (float)raw_gyro_y * GYRO_SENSITIVITY;
    *gyro_z = (float)raw_gyro_z * GYRO_SENSITIVITY;
    *accel_x = (float)raw_accel_x * ACCEL_SENSITIVITY;
    *accel_y = (float)raw_accel_y * ACCEL_SENSITIVITY;
    *accel_z = (float)raw_accel_z * ACCEL_SENSITIVITY;

    return 0;
}

// Function to log data to a CSV file
void log_data(FILE *fp, struct timespec ts, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z) {
    fprintf(fp, "%ld.%09ld,%f,%f,%f,%f,%f,%f\n",
            ts.tv_sec, ts.tv_nsec, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Cleanup function to close SPI and file handles
void cleanup(int signum) {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    struct timespec ts;
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for writing
    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open imu_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row
    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    atexit(cleanup);

    // Main loop
    while (running) {
        // Read IMU data
        if (read_imu_data(spi_handle, &gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                // Log data to file
                log_data(fp, ts, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
            } else {
                fprintf(stderr, "Error: Failed to get timestamp\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read IMU data, skipping sample\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    return 0;
}

