#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Sensitivity scales (adjust as needed based on your configuration)
#define ACCEL_SCALE 16384.0f // +/- 2g range
#define GYRO_SCALE  131.0f   // +/- 250 deg/s range

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the MPU-6886
int init_mpu6886() {
    // Wake up the MPU-6886 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6886: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

