            retries--;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    fprintf(stderr, "Fatal error: Could not read register 0x%02X after multiple retries.\n", reg);
    return 0; // Return 0 as a default value in case of failure
}

