        int16_t gyro_y_raw = read_raw_value(GYRO_XOUT_H + 2);
        int16_t gyro_z_raw = read_raw_value(GYRO_XOUT_H + 4);

        // Convert raw values to g and degrees/second
        float accel_x = (float)accel_x_raw / ACCEL_SCALE;
        float accel_y = (float)accel_y_raw / ACCEL_SCALE;
        float accel_z = (float)accel_z_raw / ACCEL_SCALE;
