        float gyro_y = (float)gyro_y_raw / GYRO_SCALE;
        float gyro_z = (float)gyro_z_raw / GYRO_SCALE;

        // Print the values
        printf("Accel: X=%.3f g, Y=%.3f g, Z=%.3f g  Gyro: X=%.3f deg/s, Y=%.3f deg/s, Z=%.3f deg/s\n",
