#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define MMA8451Q_ID_REG 0x0C
#define MMA8451Q_ID_VALUE 0x2A
#define MMA8451Q_CTRL_REG1 0x2A
#define MMA8451Q_XOUT_L 0x01
#define LED_GPIO 17
#define SAMPLE_RATE_MS 100
#define LED_ON_TIME_MS 500
#define G_THRESHOLD 2.0
#define G_PER_COUNT 1024.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int initialize_i2c();
int verify_sensor_id();
int configure_sensor();
accelerometer_data_t read_accelerometer_data();
double calculate_magnitude(accelerometer_data_t data);
void log_data(accelerometer_data_t data, double magnitude);
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MMA8451Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Sensor ID verification function
int verify_sensor_id() {
    int id = i2cReadByteData(i2c_handle, MMA8451Q_ID_REG);
    if (id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", id);
        return -1;
    }
    if (id != MMA8451Q_ID_VALUE) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X (expected 0x%02X)\n", id, MMA8451Q_ID_VALUE);
        return -1;
    }
    printf("Sensor ID verified: 0x%02X\n", id);
    return 0;
}

// Sensor configuration function
int configure_sensor() {
    // Set to active mode, ±2g range
    if (i2cWriteByteData(i2c_handle, MMA8451Q_CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    return 0;
}

// Data acquisition function
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char raw_data[6];

    if (i2cReadI2CBlockData(i2c_handle, MMA8451Q_XOUT_L, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    data.y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    data.z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    return data;
}

// Data processing function
double calculate_magnitude(accelerometer_data_t data) {
    double x_g = (double)data.x / G_PER_COUNT;
    double y_g = (double)data.y / G_PER_COUNT;
    double z_g = (double)data.z / G_PER_COUNT;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Data logging function
void log_data(accelerometer_data_t data, double magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %d, %d, %d, %.4f\n", timestamp, data.x, data.y, data.z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// LED control function
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioSetMode(LED_GPIO, PI_INPUT); // Release GPIO
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        accelerometer_data_t data = read_accelerometer_data();

        // Calculate magnitude
        double magnitude = calculate_magnitude(data);

        // Log data
        log_data(data, magnitude);

        // Check for impact
        if (magnitude > G_THRESHOLD) {
            printf("Impact detected! Magnitude: %.4f g\n", magnitude);
            control_led(1); // Turn on LED
            gpioDelay(LED_ON_TIME_MS * 1000); // Delay for 500ms
            control_led(0); // Turn off LED
        }

        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

