    }

    if (fprintf(log_file, "%s", data) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup function to close I2C and log file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        printf("I2C device closed.\n");
    }
    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            char *formatted_data = format_data(sensor_data);
            if (write_to_log(formatted_data) != 0) {
                fprintf(stderr, "Error writing data to log.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Continuing...\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

