#define ADXL345_REG_FILTER_CTL 0x2C
#define ADXL345_FREEFALL_THRESHOLD 0x0A // Example value, adjust as needed
#define ADXL345_FREEFALL_TIME 0x0A      // Example value, adjust as needed
