// Function to initialize the ADXL345
int adxl345_init() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    if (adxl345_verify_device_id() != 0) {
        fprintf(stderr, "Error: ADXL345 device ID verification failed.\n");
        close(i2c_fd);
        return -1;
    }

    adxl345_enter_standby();
    adxl345_configure_freefall_detection();
    adxl345_exit_standby();
    adxl345_enable_interrupts();

    return 0;
}

// Function to read a single register from the ADXL345
int adxl345_read_register(int reg) {
    int value = i2c_smbus_read_byte_data(i2c_fd, reg);
    if (value < 0) {
        perror("Error reading I2C register");
        return -1;
    }
    return value;
}

// Function to write a single register to the ADXL345
int adxl345_write_register(int reg, int value) {
    int result = i2c_smbus_write_byte_data(i2c_fd, reg, value);
    if (result < 0) {
        perror("Error writing I2C register");
        return -1;
    }
    return 0;
}

// Function to verify the ADXL345 device ID
int adxl345_verify_device_id() {
    int device_id = adxl345_read_register(ADXL345_REG_DEVID);
    if (device_id < 0) {
        return -1;
    }

    if (device_id != 0xE5) {
        fprintf(stderr, "Error: Incorrect device ID: 0x%X\n", device_id);
        return -1;
    }

    printf("ADXL345 device ID verified: 0x%X\n", device_id);
    return 0;
}

