int adxl345_configure_freefall_detection() {
    if (adxl345_write_register(ADXL345_REG_THRESH_FF, ADXL345_FREEFALL_THRESHOLD) != 0) {
        return -1;
    }
    if (adxl345_write_register(ADXL345_REG_TIME_FF, ADXL345_FREEFALL_TIME) != 0) {
        return -1;
    }
    return 0;
}

// Function to place the ADXL345 in standby mode
void adxl345_enter_standby() {
    if (adxl345_write_register(ADXL345_REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Error entering standby mode.\n");
    }
}

// Function to wake the ADXL345 from standby mode
void adxl345_exit_standby() {
    if (adxl345_write_register(ADXL345_REG_POWER_CTL, 0x08) != 0) { // Measure mode
        fprintf(stderr, "Error exiting standby mode.\n");
    }
}

// Function to enable interrupts
void adxl345_enable_interrupts() {
    if (adxl345_write_register(ADXL345_REG_INT_ENABLE, 0x40) != 0) { // Enable free-fall interrupt
        fprintf(stderr, "Error enabling interrupts.\n");
    }
}

// Function to disable interrupts
void adxl345_disable_interrupts() {
    if (adxl345_write_register(ADXL345_REG_INT_ENABLE, 0x00) != 0) {
        fprintf(stderr, "Error disabling interrupts.\n");
    }
}

// Function to read acceleration data
int read_acceleration(int *x, int *y, int *z) {
    char data[6];
    if (read(i2c_fd, data, 6) != 6) {
        perror("Error reading acceleration data");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

