#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define WHO_AM_I 0x0F
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_A 0x28
#define OUTX_H_A 0x29
#define OUTY_L_A 0x2A
#define OUTY_H_A 0x2B
#define OUTZ_L_A 0x2C
#define OUTZ_H_A 0x2D

// Accelerometer and gyroscope ranges
#define ACCEL_RANGE_2G 2.0f
#define GYRO_RANGE_250DPS 250.0f

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f

// Fall detection time window
#define FALL_DETECTION_WINDOW 1.0f

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    float accel_x;
    float accel_y;
    float accel_z;
    float gyro_x;
    float gyro_y;
    float gyro_z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_lsm6dsr();
sensor_data_t read_sensor_data();
float calculate_acceleration_magnitude(sensor_data_t data);
void log_data(sensor_data_t data, const char *state);
void signal_handler(int signal);
void fall_detection(sensor_data_t data);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize LSM6DSR sensor
int init_lsm6dsr() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0 || who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I check failed: %d\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Configure accelerometer: 104 Hz, ±2g
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x60) < 0) {
        fprintf(stderr, "Failed to write CTRL1_XL\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Configure gyroscope: 104 Hz, ±250 dps
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x60) < 0) {
        fprintf(stderr, "Failed to write CTRL2_G\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[12];

    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12) < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        data.accel_x = data.accel_y = data.accel_z = data.gyro_x = data.gyro_y = data.gyro_z = 0.0f;
        return data;
    }

    // Combine high and low bytes for gyroscope data
    int16_t gyro_x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t gyro_y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t gyro_z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Combine high and low bytes for accelerometer data
    int16_t accel_x_raw = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t accel_y_raw = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t accel_z_raw = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert raw data to g and dps
    data.gyro_x = (float)gyro_x_raw / 32768.0f * GYRO_RANGE_250DPS;
    data.gyro_y = (float)gyro_y_raw / 32768.0f * GYRO_RANGE_250DPS;
    data.gyro_z = (float)gyro_z_raw / 32768.0f * GYRO_RANGE_250DPS;
    data.accel_x = (float)accel_x_raw / 32768.0f * ACCEL_RANGE_2G;
    data.accel_y = (float)accel_y_raw / 32768.0f * ACCEL_RANGE_2G;
    data.accel_z = (float)accel_z_raw / 32768.0f * ACCEL_RANGE_2G;

    return data;
}

// Calculate acceleration magnitude
float calculate_acceleration_magnitude(sensor_data_t data) {
    return sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);
}

// Log data to CSV file
void log_data(sensor_data_t data, const char *state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%s\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z, data.gyro_x, data.gyro_y, data.gyro_z, state);
    fflush(log_file);
}

