#define ADIS16266_WHO_AM_I   0x02
#define ADIS16266_GYRO_XOUT  0x04
#define ADIS16266_GYRO_YOUT  0x06
#define ADIS16266_GYRO_ZOUT  0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000 // 1 MHz
#define SPI_FLAGS   0       // SPI_MODE_3 is handled by pigpio

// Gyroscope Scale Factor
#define GYRO_SCALE_FACTOR 0.0305 // deg/sec/LSB

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t address);
int spi_write_register(int handle, uint8_t address, uint16_t data);
int verify_who_am_i(int handle);
int read_gyro_data(int handle, float *x, float *y, float *z);
void log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Exiting gracefully.\n");
        terminate = 1;
    }
}

// SPI Read Register Function
int spi_read_register(int handle, uint8_t address) {
    char tx[2];
    char rx[2];

    tx[0] = address | 0x80; // Set MSB for read command
    tx[1] = 0x00;           // Dummy byte

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "Error: SPI read failed for address 0x%02X\n", address);
        return -1;
    }

    return (rx[1] << 8) | rx[0]; // Combine bytes into 16-bit value
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t address, uint16_t data) {
    char tx[3];
    char rx[3];

    tx[0] = address & 0x7F; // Clear MSB for write command
    tx[1] = (data >> 8) & 0xFF; // MSB of data
    tx[2] = data & 0xFF;      // LSB of data

    if (spiXfer(handle, tx, rx, 3) != 0) {
        fprintf(stderr, "Error: SPI write failed for address 0x%02X\n", address);
        return -1;
    }

    return 0;
}

// Verify WHO_AM_I Register
int verify_who_am_i(int handle) {
    int who_am_i = spi_read_register(handle, ADIS16266_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x5641) {
        fprintf(stderr, "Error: WHO_AM_I value mismatch. Expected 0x5641, got 0x%04X\n", who_am_i);
        return -1;
    }

    printf("WHO_AM_I verification successful. Value: 0x%04X\n", who_am_i);
    return 0;
}

// Read Gyroscope Data
int read_gyro_data(int handle, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;

    raw_x = spi_read_register(handle, ADIS16266_GYRO_XOUT);
    raw_y = spi_read_register(handle, ADIS16266_GYRO_YOUT);
    raw_z = spi_read_register(handle, ADIS16266_GYRO_ZOUT);

    if (raw_x < 0 || raw_y < 0 || raw_z < 0) {
        fprintf(stderr, "Error: Failed to read gyro data\n");
        return -1;
    }

    *x = (float)raw_x * GYRO_SCALE_FACTOR;
    *y = (float)raw_y * GYRO_SCALE_FACTOR;
    *z = (float)raw_z * GYRO_SCALE_FACTOR;

    return 0;
}

// Log Data to File
void log_data(FILE *fp, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.4f,%.4f,%.4f\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I register
    if (verify_who_am_i(spi_handle) != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_Rate(deg/s),Y_Rate(deg/s),Z_Rate(deg/s)\n");
    }
    rewind(log_file);

    // Register signal handler
    signal(SIGINT, signal_handler);

    float x_rate, y_rate, z_rate;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(spi_handle, &x_rate, &y_rate, &z_rate) == 0) {
            log_data(log_file, x_rate, y_rate, z_rate);
        } else {
            fprintf(stderr, "Error: Failed to read or log data\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Close SPI and log file
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

