            log_flame_event(sensor_value == 0); // Active LOW
            handle_flame_detection(sensor_value == 0);
        } else {
            fprintf(stderr, "Error reading sensor, logging error to file.\n");
            if (log_file != NULL) {
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[20];

                time(&rawtime);
                timeinfo = localtime(&rawtime);

                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
