// Function to read data from the D7S sensor
int read_d7s_data(int i2c_handle, float *x, float *y, float *z) {
    char buf[6];
    int result = i2cReadDevice(i2c_handle, buf, 6);

    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1; // Indicate failure
    }

    // Convert raw data to float (assuming little-endian)
    *x = (float)((int16_t)((buf[0] << 8) | buf[1])) / 1000.0; // Example scaling
    *y = (float)((int16_t)((buf[2] << 8) | buf[3])) / 1000.0;
    *z = (float)((int16_t)((buf[4] << 8) | buf[5])) / 1000.0;

    return 0; // Indicate success
