#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define LOG_FILE "conveyor_log.txt"

static volatile int running = 1;
FILE *log_file = NULL;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    return 0;
}

// Function to read sensor values
int read_sensors(int *sensor1_value, int *sensor2_value) {
    *sensor1_value = gpioRead(SENSOR_1_GPIO);
    *sensor2_value = gpioRead(SENSOR_2_GPIO);
    return 0;
}

// Function to log sensor data to a file
int log_data(int sensor1_value, int sensor2_value) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%ld,%d,%d\n", timestamp_ms, sensor1_value, sensor2_value);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to check conveyor status
void check_conveyor_status(int sensor1_value, int sensor2_value) {
    if (sensor1_value == 1 && sensor2_value == 1) {
        printf("Conveyor halted!\n");
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup_gpio();
        return 1;
    }

    int sensor1_value, sensor2_value;

    printf("Monitoring Hall-Effect sensors. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_sensors(&sensor1_value, &sensor2_value) == 0) {
            if (log_data(sensor1_value, sensor2_value) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
            check_conveyor_status(sensor1_value, sensor2_value);
        } else {
            fprintf(stderr, "Error reading sensors\n");
        }

        gpioDelay(50); // Wait 50ms
    }

    // Cleanup and exit
    fclose(log_file);
    cleanup_gpio();
    printf("Exiting.\n");
    return 0;
}

