#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I 0x0D
#define WHO_AM_I_VALUE 0x2A
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define DATA_REG 0x01
#define DATA_LEN 6
#define SAMPLE_RATE 100 // Hz
#define LOOP_DELAY_US (1000000 / SAMPLE_RATE) // microseconds
#define TILT_THRESHOLD 45.0 // degrees
#define PI 3.14159265359

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_sensor();
int init_sensor();
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt(int16_t x, int16_t y, int16_t z);
int log_fall(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, exiting gracefully.\n");
    terminate = 1;
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MMA8452Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Sensor verification function
int verify_sensor() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value. Expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
        return -1;
    }

    printf("Sensor verified successfully.\n");
    return 0;
}

// Sensor initialization function
int init_sensor() {
    // Standby mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (standby): %s\n", strerror(errno));
        return -1;
    }

    // Set data rate to 100 Hz (ODR = 011)
    if (i2cWriteByteData(i2c_handle, CTRL_REG2, 0x03) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2 (data rate): %s\n", strerror(errno));
        return -1;
    }

    // Active mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (active): %s\n", strerror(errno));
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

// Accelerometer data reading function
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[DATA_LEN];
    if (i2cReadI2CBlockData(i2c_handle, DATA_REG, buffer, DATA_LEN) != DATA_LEN) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    // Combine MSB and LSB, right-shift by 4 bits
    *x = ((int16_t)buffer[0] << 8 | (int16_t)buffer[1]) >> 4;
    *y = ((int16_t)buffer[2] << 8 | (int16_t)buffer[3]) >> 4;
    *z = ((int16_t)buffer[4] << 8 | (int16_t)buffer[5]) >> 4;

    return 0;
}

// Tilt calculation function
double calculate_tilt(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 2048.0; // Assuming +/- 2g range
    double y_g = (double)y / 2048.0;
    double z_g = (double)z / 2048.0;

    double tilt_x = atan2(y_g, sqrt(x_g * x_g + z_g * z_g)) * 180.0 / PI;
    double tilt_y = atan2(x_g, sqrt(y_g * y_g + z_g * z_g)) * 180.0 / PI;

    return fmax(fabs(tilt_x), fabs(tilt_y));
}

// Fall logging function
int log_fall(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(log_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor
    if (verify_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int16_t x, y, z;
    double tilt;

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        if (read_accelerometer(&x, &y, &z) == 0) {
            // Calculate tilt
            tilt = calculate_tilt(x, y, z);

            // Check for fall
            if (tilt > TILT_THRESHOLD) {
                log_fall(x, y, z);
                printf("Fall detected! Tilt: %.2f degrees\n", tilt);
            }
        }

        // Delay for 10 ms
        usleep(LOOP_DELAY_US);
    }

    // Close I2C and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

