// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_X_H 0x29
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Y_H 0x2B
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_OUT_Z_H 0x2D

// Calibration constants
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 1.0
#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Sensitivity
#define SENSITIVITY 0.146 // mG/LSB

// Metal detector threshold
#define METAL_THRESHOLD 800.0 // mG

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

// Function prototypes
int initialize_i2c();
int configure_magnetometer();
magnetometer_data_t read_magnetometer_data();
magnetometer_data_t calibrate_data(magnetometer_data_t raw_data);
float calculate_magnitude(magnetometer_data_t calibrated_data);
void log_data(magnetometer_data_t calibrated_data);
void metal_detector_alert(float magnitude);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Magnetometer configuration function
int configure_magnetometer() {
    // Set continuous conversion mode and 10 Hz ODR
    if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG1, 0x70) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    // Set ±4 gauss full scale
    if (i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG3, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG3: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Data acquisition function
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t raw_data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LIS3MDL_OUT_X_L, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data: %s\n", strerror(errno));
        raw_data.x = 0.0; // Set to 0 to avoid using uninitialized data
        raw_data.y = 0.0;
        raw_data.z = 0.0;
        return raw_data;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    raw_data.x = (float)x;
    raw_data.y = (float)y;
    raw_data.z = (float)z;

    return raw_data;
}

