magnetometer_data_t calibrate_data(magnetometer_data_t raw_data) {
    magnetometer_data_t calibrated_data;

    calibrated_data.x = (raw_data.x - X_OFFSET) * X_SCALE * SENSITIVITY;
    calibrated_data.y = (raw_data.y - Y_OFFSET) * Y_SCALE * SENSITIVITY;
    calibrated_data.z = (raw_data.z - Z_OFFSET) * Z_SCALE * SENSITIVITY;

    return calibrated_data;
}

// Magnitude calculation function
float calculate_magnitude(magnetometer_data_t calibrated_data) {
    return sqrt(calibrated_data.x * calibrated_data.x + calibrated_data.y * calibrated_data.y + calibrated_data.z * calibrated_data.z);
}

// Data logging function
void log_data(magnetometer_data_t calibrated_data) {
    fprintf(log_file, "%.3f,%.3f,%.3f\n", calibrated_data.x, calibrated_data.y, calibrated_data.z);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
}

// Metal detector alert function
void metal_detector_alert(float magnitude) {
    fprintf(stderr, "Metal detected! Magnitude: %.3f mG\n", magnitude);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("magnetic_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize I2C with retry logic
    int init_retries = 3;
    while (initialize_i2c() != 0 && init_retries > 0) {
        fprintf(stderr, "I2C initialization failed, retrying... (%d retries remaining)\n", init_retries - 1);
        init_retries--;
        gpioDelay(1000); // Wait 1 second before retrying
    }
    if (init_retries == 0) {
        fprintf(stderr, "I2C initialization failed after multiple retries. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

