    if (configure_magnetometer() != 0) {
        fprintf(stderr, "Magnetometer configuration failed. Exiting.\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read magnetometer data
