        if (magnitude > METAL_THRESHOLD) {
            metal_detector_alert(magnitude);
        }

        // Delay for 100 ms (10 Hz sampling rate)
        gpioDelay(100);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

