    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI Write Error: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg, uint8_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg | 0x81; // Set MSB for read
    tx_buf[1] = 0x00;       // Dummy byte for reading

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI Read Error: %s\n", strerror(errno));
        return -1;
    }

    *value = rx_buf[1];
    return 0;
}

// ADXL354B Reset Function
int adxl354b_reset(int handle) {
    if (spi_write_register(handle, ADXL354B_REG_RESET, 0x52) != 0) {
        fprintf(stderr, "ADXL354B Reset Error\n");
        return -1;
    }
    gpioDelay(1000); // 1 ms delay
    return 0;
}

// ADXL354B Configure Function
int adxl354b_configure(int handle) {
    if (spi_write_register(handle, ADXL354B_REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "ADXL354B Power Control Write Error\n");
        return -1;
    }

    // Wait for STABLE bit to be set
    int timeout = 100; // 100 * 10ms = 1 second
    while (timeout > 0) {
        uint8_t status;
        if (spi_read_register(handle, ADXL354B_REG_STATUS, &status) == 0) {
            if (status & 0x01) {
                break; // STABLE bit is set
            }
        } else {
            fprintf(stderr, "ADXL354B Status Read Error\n");
            return -1;
        }
        gpioDelay(10000); // 10 ms delay
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "ADXL354B Timeout waiting for STABLE bit\n");
        return -1;
    }

    if (spi_write_register(handle, ADXL354B_REG_POWER_CTL, 0x02) != 0) {
        fprintf(stderr, "ADXL354B Power Control Write Error (RUN)\n");
        return -1;
    }

    return 0;
}

// ADXL354B Verify Part ID Function
int adxl354b_verify_partid(int handle) {
    uint8_t partid;
    if (spi_read_register(handle, ADXL354B_REG_PARTID, &partid) != 0) {
        fprintf(stderr, "ADXL354B Part ID Read Error\n");
        return -1;
    }

    if (partid != ADXL354B_PARTID) {
        fprintf(stderr, "ADXL354B Part ID Mismatch: 0x%02X (Expected 0x%02X)\n", partid, ADXL354B_PARTID);
        return -1;
    }

    return 0;
}

// ADXL354B Read Acceleration Data Function
int adxl354b_read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char tx_buf[7];
    char rx_buf[7];

    // Read X, Y, and Z data (6 bytes)
    tx_buf[0] = ADXL354B_REG_XDATA_L | 0x81; // Read XDATA_L
    memset(tx_buf + 1, 0x00, 6); // Dummy bytes

    if (spiXfer(handle, tx_buf, rx_buf, 7) != 0) {
        fprintf(stderr, "ADXL354B Acceleration Read Error: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((rx_buf[2] << 8) | rx_buf[1]);
    *y = (int16_t)((rx_buf[4] << 8) | rx_buf[3]);
    *z = (int16_t)((rx_buf[6] << 8) | rx_buf[5]);

    return 0;
}

// Log Data Function
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal Handler Function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // ADXL354B Initialization
    if (adxl354b_reset(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B Reset Failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (adxl354b_configure(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B Configuration Failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (adxl354b_verify_partid(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B Part ID Verification Failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int16_t x, y, z;
    while (!terminate) {
        if (adxl354b_read_acceleration(spi_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

