#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16362 Register Addresses
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCEL_OUT 0x0A
#define Y_ACCEL_OUT 0x0C
#define Z_ACCEL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec per LSB
#define ACCEL_SCALE 0.0025 // g per LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    double x_gyro;
    double y_gyro;
    double z_gyro;
    double x_accel;
    double y_accel;
    double z_accel;
} imu_data_t;

// Function prototypes
int initialize_spi();
void close_spi();
int read_register(uint8_t reg_addr, int16_t *data);
imu_data_t process_data(int16_t x_gyro_raw, int16_t y_gyro_raw, int16_t z_gyro_raw, int16_t x_accel_raw, int16_t y_accel_raw, int16_t z_accel_raw);
int log_data(imu_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Closes the SPI interface
void close_spi() {
    spiClose(spi_handle);
}

// Reads data from a specific register on the ADIS16362
int read_register(uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB of register address for read operation
    tx_buf[0] = reg_addr | 0x80; // Read command
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit data
    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Processes raw data and scales it to meaningful units
imu_data_t process_data(int16_t x_gyro_raw, int16_t y_gyro_raw, int16_t z_gyro_raw, int16_t x_accel_raw, int16_t y_accel_raw, int16_t z_accel_raw) {
    imu_data_t data;

    data.x_gyro = (double)x_gyro_raw * GYRO_SCALE;
    data.y_gyro = (double)y_gyro_raw * GYRO_SCALE;
    data.z_gyro = (double)z_gyro_raw * GYRO_SCALE;
    data.x_accel = (double)x_accel_raw * ACCEL_SCALE;
    data.y_accel = (double)y_accel_raw * ACCEL_SCALE;
    data.z_accel = (double)z_accel_raw * ACCEL_SCALE;

    return data;
}

// Logs the IMU data to a CSV file
int log_data(imu_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    // Check if the file is empty to write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    }

    fprintf(log_file, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            ts.tv_sec, ts.tv_nsec,
            data.x_gyro, data.y_gyro, data.z_gyro,
            data.x_accel, data.y_accel, data.z_accel);

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        close_spi();
        gpioTerminate();
        return 1;
    }

    int16_t x_gyro_raw, y_gyro_raw, z_gyro_raw, x_accel_raw, y_accel_raw, z_accel_raw;
    imu_data_t imu_data;

    // Main loop
    while (!terminate) {
        // Read raw data from the IMU
        if (read_register(X_GYRO_OUT, &x_gyro_raw) != 0 ||
            read_register(Y_GYRO_OUT, &y_gyro_raw) != 0 ||
            read_register(Z_GYRO_OUT, &z_gyro_raw) != 0 ||
            read_register(X_ACCEL_OUT, &x_accel_raw) != 0 ||
            read_register(Y_ACCEL_OUT, &y_accel_raw) != 0 ||
            read_register(Z_ACCEL_OUT, &z_accel_raw) != 0) {
            fprintf(stderr, "Error reading IMU data, retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        // Process the raw data
        imu_data = process_data(x_gyro_raw, y_gyro_raw, z_gyro_raw, x_accel_raw, y_accel_raw, z_accel_raw);

        // Log the data
        if (log_data(imu_data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Delay for approximately 10ms (100Hz sampling rate)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close the log file
    fclose(log_file);

    // Close SPI
    close_spi();

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

