#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define POLLING_INTERVAL_MS 1000

static volatile int terminate = 0;

void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", sig);
    gpioTerminate();
    terminate = 1;
    exit(0);
}

int main() {
    int rc;
    int sensor_value;
    time_t rawtime;
    struct tm *timeinfo;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    printf("Self-parking system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read the sensor value
        sensor_value = gpioRead(GPIO_PIN);

        if (sensor_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO %d\n", GPIO_PIN);
            gpioTerminate();
            return 1;
        }

        // Check if an obstacle is detected (LOW signal)
        if (sensor_value == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            // Log the start of the self-parking sequence
            printf("[%04d-%02d-%02d %02d:%02d:%02d] Self-parking sequence started\n",
                   timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                   timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);

            // Simulate the self-parking routine (1 second)
            gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay in microseconds

            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            // Log the completion of the self-parking sequence
            printf("[%04d-%02d-%02d %02d:%02d:%02d] Self-parking sequence completed\n",
                   timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                   timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
        }

        // Wait for the next polling interval
        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    return 0;
}

