#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000 // 1 MHz

// Define ADIS16266 register addresses
#define ADIS16266_XGYRO_OUT 0x04
#define ADIS16266_YGYRO_OUT 0x06
#define ADIS16266_ZGYRO_OUT 0x08

// Define scale factor
#define SCALE_FACTOR 0.02 // deg/sec per LSB

// Global variable for SPI file descriptor
int spi_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to initialize SPI
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read data from ADIS16266 register
int16_t read_register(uint8_t reg_addr, uint8_t *data) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr;

    // Set MSB of register address for read operation
    tx_buf[0] = reg_addr | 0x80; // Read bit
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Combine the two received bytes into a 16-bit value
    data[0] = rx_buf[1];
    data[1] = rx_buf[2];
    return (int16_t)((data[0] << 8) | data[1]);
}

// Function to convert raw data to degrees per second
float convert_to_deg_per_sec(int16_t raw_data) {
    return (float)raw_data * SCALE_FACTOR;
}

// Function to log data with timestamp
void log_data(float x_rate, float y_rate, float z_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", timestamp, x_rate, y_rate, z_rate);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    printf("ADIS16266 Gyroscope Data Logger\n");

    // Main loop
    while (1) {
        uint8_t data[2];
        int16_t raw_x, raw_y, raw_z;
        float x_rate, y_rate, z_rate;

        // Read X, Y, and Z angular rates
        raw_x = read_register(ADIS16266_XGYRO_OUT, data);
        raw_y = read_register(ADIS16266_YGYRO_OUT, data);
        raw_z = read_register(ADIS16266_ZGYRO_OUT, data);

        if (raw_x == -1 || raw_y == -1 || raw_z == -1) {
            fprintf(stderr, "Error reading gyroscope data. Retrying.\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Convert raw data to degrees per second
        x_rate = convert_to_deg_per_sec(raw_x);
        y_rate = convert_to_deg_per_sec(raw_y);
        z_rate = convert_to_deg_per_sec(raw_z);

        // Log the data
        log_data(x_rate, y_rate, z_rate);

        // Wait 100ms
        usleep(100000);
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", sig);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

