// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1F

// FXOS8700 register addresses
#define FXOS8700_WHO_AM_I 0x0D
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_XYZ_DATA_CFG 0x0E
#define FXOS8700_STATUS 0x00
#define FXOS8700_OUT_X_MSB 0x01

// Expected WHO_AM_I value
#define FXOS8700_WHO_AM_I_VALUE 0xC7

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a single byte from an I2C register
int i2c_read_register(int handle, uint8_t reg) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %d, retrying...\n", reg, result);
            gpioDelay(1000); // 1ms delay
            retries--;
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X)\n", reg);
    return -1; // Indicate failure
}

// Function to write a single byte to an I2C register
int i2c_write_register(int handle, uint8_t reg, uint8_t value) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X): %d, retrying...\n", reg, value, result);
            gpioDelay(1000); // 1ms delay
            retries--;
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, value 0x%02X)\n", reg, value);
    return -1; // Indicate failure
}

// Function to initialize the FXOS8700 sensor
int fxos8700_init(int handle) {
    // Set accelerometer range to +/- 2g
    if (i2c_write_register(handle, FXOS8700_XYZ_DATA_CFG, 0x00) != 0) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        return -1;
    }

    // Set active mode and 100 Hz data rate
    if (i2c_write_register(handle, FXOS8700_CTRL_REG1, 0x01 | (1 << 2)) != 0) {
        fprintf(stderr, "Failed to set active mode and data rate\n");
        return -1;
    }

    return 0;
}

