int fxos8700_read_data(int handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    char buffer[12];
    int result, retries = 3;

    while (retries > 0) {
        result = i2cReadI2CBlockData(handle, FXOS8700_OUT_X_MSB, buffer, 12);
        if (result == 12) {
            // Combine MSB and LSB for accelerometer data (14-bit left-aligned)
            *accel_x = ((int16_t)buffer[0] << 6) | (buffer[1] >> 2);
            *accel_y = ((int16_t)buffer[2] << 6) | (buffer[3] >> 2);
            *accel_z = ((int16_t)buffer[4] << 6) | (buffer[5] >> 2);

