            *mag_x = ((int16_t)buffer[6] << 8) | buffer[7];
            *mag_y = ((int16_t)buffer[8] << 8) | buffer[9];
            *mag_z = ((int16_t)buffer[10] << 8) | buffer[11];

            return 0; // Success
        } else {
            fprintf(stderr, "I2C block read error: %d, retrying...\n", result);
            gpioDelay(1000); // 1ms delay
            retries--;
        }
    }
    fprintf(stderr, "I2C block read failed after multiple retries\n");
    return -1; // Indicate failure
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify device presence
    int who_am_i = i2c_read_register(i2c_handle, FXOS8700_WHO_AM_I);
    if (who_am_i != FXOS8700_WHO_AM_I_VALUE) {
        fprintf(stderr, "FXOS8700 not found. WHO_AM_I=0x%02X (expected 0x%02X)\n", who_am_i, FXOS8700_WHO_AM_I_VALUE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("FXOS8700 found. WHO_AM_I=0x%02X\n", who_am_i);

    // Initialize the sensor
    if (fxos8700_init(i2c_handle) != 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int16_t accel_x, accel_y, accel_z, mag_x, mag_y, mag_z;
    while (!terminate) {
