#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAZ0 0x36

// Scaling factor (3.9mg/LSB)
#define SCALE_FACTOR 0.0039

// Tilt threshold (degrees)
#define TILT_THRESHOLD 30.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_adxl345();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
int log_tilt_event(double angle);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initializes the ADXL345 accelerometer
int initialize_adxl345() {
    // Set POWER_CTL register to enable measurement mode
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Reads acceleration data from the ADXL345
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];

    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, data, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Calculates the tilt angle from acceleration data
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double x_g = x * SCALE_FACTOR;
    double y_g = y * SCALE_FACTOR;
    double z_g = z * SCALE_FACTOR;

    double angle_x = atan2(x_g, sqrt(y_g * y_g + z_g * z_g)) * 180.0 / M_PI;
    double angle_y = atan2(y_g, sqrt(x_g * x_g + z_g * z_g)) * 180.0 / M_PI;
    double angle_z = atan2(z_g, sqrt(x_g * x_g + y_g * y_g)) * 180.0 / M_PI;

    // Return the maximum tilt angle
    double max_angle = angle_x;
    if (fabs(angle_y) > fabs(max_angle)) {
        max_angle = angle_y;
    }
    if (fabs(angle_z) > fabs(max_angle)) {
        max_angle = angle_z;
    }

    return max_angle;
}

// Logs a tilt event to the log file
int log_tilt_event(double angle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("/var/log/tilt_events.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%s - Tilt angle: %.2f degrees\n", timestamp, angle);
    fclose(fp);

    return 0;
}

int main() {
    int16_t x, y, z;
    double tilt_angle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (initialize_adxl345() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Tilt monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate tilt angle
            tilt_angle = calculate_tilt_angle(x, y, z);

            // Check if tilt exceeds threshold
            if (fabs(tilt_angle) > TILT_THRESHOLD) {
                // Log tilt event
                if (log_tilt_event(tilt_angle) != 0) {
                    fprintf(stderr, "Error logging tilt event\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Tilt monitoring stopped.\n");

    return 0;
}

