#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5 // seconds
#define SAMPLE_INTERVAL 1 // milliseconds
#define PAUSE_DURATION 1 // seconds

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

int main(int argc, char *argv[]) {
    int threshold;
    int i;
    int high_count;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Check command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    char *endptr;
    threshold = strtol(argv[1], &endptr, 10);

    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold. Please provide a positive integer.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        high_count = 0;

        // Sampling window
        for (i = 0; i < (WINDOW_SIZE * 1000) / SAMPLE_INTERVAL; ++i) {
            int level = gpioRead(GPIO_PIN);
            if (level == PI_HIGH) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL * 1000); // pigpioDelay takes microseconds
        }

        // Get timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Print result
        if (high_count > threshold) {
            printf("%s ALERT\n", timestamp);
        } else {
            printf("%s Status: OK (High count: %d, Threshold: %d)\n", timestamp, high_count, threshold);
        }

        // Pause
        gpioDelay(PAUSE_DURATION * 1000000); // pigpioDelay takes microseconds
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

