#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <mqueue.h>
#include <pigpio.h>

// Constants
#define DOOR_A_GPIO 17
#define DOOR_B_GPIO 27
#define UNLOCK_DURATION 5 // seconds
#define SECURITY_CODE_MIN 100000
#define SECURITY_CODE_MAX 999999
#define MESSAGE_QUEUE_NAME "/door_access_queue"
#define LOG_FILE_NAME "access_log.txt"
#define MAX_CODE_LENGTH 7 // 6 digits + null terminator

// Global variables
static volatile sig_atomic_t terminate = 0;
static mqd_t mq;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int generate_security_code(int *code);
int read_user_input(char *input);
int compare_codes(int code1, int code2);
int unlock_door(int gpio_pin);
int log_access(int code);
int send_message(const char *message);
int receive_message(char *message, size_t message_size);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "Signal received, terminating...\n");
}

// Generate a random security code
int generate_security_code(int *code) {
    srand(time(NULL));
    *code = (rand() % (SECURITY_CODE_MAX - SECURITY_CODE_MIN + 1)) + SECURITY_CODE_MIN;
    return 0;
}

// Read user input
int read_user_input(char *input) {
    char buffer[MAX_CODE_LENGTH];
    int i = 0;

    printf("Enter security code: ");
    while (1) {
        char c = getchar();
        if (c == '\n' || c == '\r') {
            break;
        }
        if (c < '0' || c > '9') {
            fprintf(stderr, "Invalid input. Please enter a numeric code.\n");
            // Clear the input buffer
            while (getchar() != '\n');
            return -1; // Indicate invalid input
        }
        if (i < MAX_CODE_LENGTH - 1) {
            buffer[i++] = c;
        }
    }
    buffer[i] = '\0';
    strncpy(input, buffer, MAX_CODE_LENGTH - 1);
    input[MAX_CODE_LENGTH - 1] = '\0'; // Ensure null termination
    return 0;
}

// Compare security codes
int compare_codes(int code1, int code2) {
    return (code1 == code2) ? 0 : -1;
}

// Unlock the door
int unlock_door(int gpio_pin) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    gpioDelay(UNLOCK_DURATION * 1000000); // microseconds
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error setting GPIO %d LOW: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return 0;
}

// Log access to file
int log_access(int code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%06d\n", timestamp, code);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Send message to message queue
int send_message(const char *message) {
    if (mq_send(mq, message, strlen(message), 0) == -1) {
        fprintf(stderr, "Error sending message: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Receive message from message queue
int receive_message(char *message, size_t message_size) {
    ssize_t bytes_read = mq_receive(mq, message, message_size, NULL);
    if (bytes_read == -1) {
        fprintf(stderr, "Error receiving message: %s\n", strerror(errno));
        return -1;
    }
    message[bytes_read] = '\0'; // Null-terminate the received message
    return 0;
}

int main() {
    int security_code;
    char user_input[MAX_CODE_LENGTH];
    char message[256];
    int door_a_unlocked = 0;
    int door_b_unlocked = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(DOOR_A_GPIO, PI_OUTPUT);
    gpioSetMode(DOOR_B_GPIO, PI_OUTPUT);

    // Set initial state (locked)
    gpioWrite(DOOR_A_GPIO, 0);
    gpioWrite(DOOR_B_GPIO, 0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create message queue attributes
    struct mq_attr attr;
    attr.mq_flags = 0;
    attr.mq_maxmsg = 10; // Maximum number of messages in the queue
    attr.mq_msgsize = 256; // Maximum message size
    attr.mq_curmsgs = 0;

    // Create message queue
    mq = mq_open(MESSAGE_QUEUE_NAME, O_CREAT | O_RDWR | O_NONBLOCK, 0666, &attr);
    if (mq == (mqd_t)-1) {
        fprintf(stderr, "Error creating message queue: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        mq_close(mq);
        mq_unlink(MESSAGE_QUEUE_NAME);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Generate security code
        if (generate_security_code(&security_code) != 0) {
            fprintf(stderr, "Error generating security code.\n");
            break;
        }

        // Send security code to message queue
        snprintf(message, sizeof(message), "%06d", security_code);
        if (send_message(message) != 0) {
            fprintf(stderr, "Error sending security code to message queue.\n");
            break;
        }

        // Receive security code from message queue
        if (receive_message(message, sizeof(message)) != 0) {
            fprintf(stderr, "Error receiving security code from message queue.\n");
            break;
        }

        // Read user input
        if (read_user_input(user_input) != 0) {
            fprintf(stderr, "Error reading user input.\n");
            continue; // Prompt again
        }

        // Convert user input to integer
        int entered_code = atoi(user_input);

        // Compare codes
        if (compare_codes(entered_code, security_code) == 0) {
            printf("Access granted!\n");

            // Unlock doors sequentially
            if (!door_a_unlocked) {
                if (unlock_door(DOOR_A_GPIO) != 0) {
                    fprintf(stderr, "Error unlocking door A.\n");
                } else {
                    door_a_unlocked = 1;
                }
            }

            if (!door_b_unlocked) {
                if (unlock_door(DOOR_B_GPIO) != 0) {
                    fprintf(stderr, "Error unlocking door B.\n");
                } else {
                    door_b_unlocked = 1;
                }
            }

            // Log access
            if (log_access(entered_code) != 0) {
                fprintf(stderr, "Error logging access.\n");
            }
        } else {
            printf("Access denied.\n");
        }
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(DOOR_A_GPIO, 0); // Lock door A
    gpioWrite(DOOR_B_GPIO, 0); // Lock door B
    mq_close(mq);
    mq_unlink(MESSAGE_QUEUE_NAME);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

