#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define OUT_X_L_M 0x08
#define OUT_X_H_M 0x09
#define OUT_Y_L_M 0x0A
#define OUT_Y_H_M 0x0B
#define OUT_Z_L_M 0x0C
#define OUT_Z_H_M 0x0D

// GPIO pin for LED
#define LED_PIN 17

// PWM frequency
#define PWM_FREQUENCY 1000

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function prototypes
int initialize();
void cleanup();
void signal_handler(int signal);
int read_magnetometer_data(magnetometer_data_t *data);
float calculate_magnitude(magnetometer_data_t data);
void set_led_brightness(float magnitude);
void log_error(const char *message);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize pigpio and I2C
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LED_PIN, PWM_FREQUENCY);

    // Open log file
    log_file = fopen("magnetometer.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");

    // Stop PWM
    gpioPWM(LED_PIN, 0);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

// Read magnetometer data
int read_magnetometer_data(magnetometer_data_t *data) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, OUT_X_L_M, buffer, 6);

    if (result != 6) {
        log_error("Failed to read magnetometer data");
        return 1;
    }

    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate Z-axis magnitude
float calculate_magnitude(magnetometer_data_t data) {
    return fabs((float)data.z);
}

// Set LED brightness using PWM
void set_led_brightness(float magnitude) {
    // Scale magnitude to PWM range (0-255)
    int pwm_value = (int)(magnitude * 10); // Adjust scaling factor as needed
    if (pwm_value > 255) {
        pwm_value = 255;
    } else if (pwm_value < 0) {
        pwm_value = 0;
    }

    gpioPWM(LED_PIN, pwm_value);
}

// Log errors to file
void log_error(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    magnetometer_data_t magnetometer_data;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&magnetometer_data) == 0) {
            // Calculate Z-axis magnitude
            float magnitude = calculate_magnitude(magnetometer_data);

            // Set LED brightness
            set_led_brightness(magnitude);
        } else {
            // Error reading data, already logged in read_magnetometer_data
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    cleanup();

    return 0;
}

