#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define LSM303D_WHO_AM_I 0x0F
#define LSM303D_CTRL_REG1_A 0x20
#define LSM303D_CTRL_REG4_A 0x23
#define LSM303D_OUT_X_L_A 0x28
#define LSM303D_OUT_X_H_A 0x29
#define LSM303D_OUT_Y_L_A 0x2A
#define LSM303D_OUT_Y_H_A 0x2B
#define LSM303D_OUT_Z_L_A 0x2C
#define LSM303D_OUT_Z_H_A 0x2D

// GPIO pin for interrupt
#define INT1_PIN 23

// Circular buffer size
#define BUFFER_SIZE 64

// Sensitivity (mg/LSB)
#define SENSITIVITY 0.061

// Interrupt threshold (mg)
#define INTERRUPT_THRESHOLD 2000.0

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Circular buffer
accelerometer_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_lsm303d();
int read_accelerometer_data(accelerometer_data_t *data);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void dump_buffer_data();
void signal_handler(int signal);

// Function to initialize the LSM303D
int initialize_lsm303d() {
    // Verify device identity
    int who_am_i = i2cReadByteData(i2c_handle, LSM303D_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != 0x49) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X (expected 0x49)\n", who_am_i);
        return -1;
    }

    // Configure accelerometer
    // CTRL_REG1_A: 0x57 (ODR = 100 Hz, Enable X, Y, Z axes)
    if (i2cWriteByteData(i2c_handle, LSM303D_CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1_A register: %s\n", strerror(errno));
        return -1;
    }

    // CTRL_REG4_A: 0x88 (High resolution, +/- 2g, Interrupt enable)
    if (i2cWriteByteData(i2c_handle, LSM303D_CTRL_REG4_A, 0x88) < 0) {
        fprintf(stderr, "Error writing CTRL_REG4_A register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(accelerometer_data_t *data) {
    char raw_data[6];
    int16_t x, y, z;

    // Read raw accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, LSM303D_OUT_X_L_A, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes
    x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to milli-g
    data->x = (float)x * SENSITIVITY;
    data->y = (float)y * SENSITIVITY;
    data->z = (float)z * SENSITIVITY;

    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick;  // unused
    (void)user_data; // unused
    dump_buffer_data();
}

// Function to dump buffer data to the console
void dump_buffer_data() {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    printf("%s\n", buf);

    // Print the last 10 samples from the circular buffer
    for (int i = 0; i < 10; i++) {
        int index = (buffer_index - 10 + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("Sample %d: X=%.2f mg, Y=%.2f mg, Z=%.2f mg\n", i + 1, circular_buffer[index].x, circular_buffer[index].y, circular_buffer[index].z);
    }
    printf("\n");
}

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // unused
    program_running = 0;
    printf("Caught signal, exiting gracefully...\n");

    // Disable accelerometer
    if (i2cWriteByteData(i2c_handle, LSM303D_CTRL_REG1_A, 0x00) < 0) {
        fprintf(stderr, "Error disabling accelerometer: %s\n", strerror(errno));
    }

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, LSM303D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize LSM303D
    if (initialize_lsm303d() < 0) {
        fprintf(stderr, "LSM303D initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for interrupt pin
    gpioSetMode(INT1_PIN, PI_INPUT);
    gpioSetPullUpDown(INT1_PIN, PI_PUD_UP);

    // Set interrupt handler
    if (gpioSetISRFuncEx(INT1_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    accelerometer_data_t data;
    while (program_running) {
        // Read accelerometer data
        if (read_accelerometer_data(&data) == 0) {
            // Store data in circular buffer
            circular_buffer[buffer_index] = data;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        } else {
            fprintf(stderr, "Warning: Failed to read accelerometer data, skipping sample\n");
        }

        // Delay for approximately 10 ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    return 0;
}

