    fprintf(stderr, "Signal received, cleaning up and exiting...\n");
    cleanup_gpio();
    exit(0);
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(SOLENOID1_GPIO, PI_OUTPUT);
    gpioSetMode(SOLENOID2_GPIO, PI_OUTPUT);

    // Ensure both solenoids are initially deactivated
    gpioWrite(SOLENOID1_GPIO, 0);
    gpioWrite(SOLENOID2_GPIO, 0);

    return 0; // Indicate success
}

// Function to activate a solenoid
void activate_solenoid(int solenoid_number) {
    if (solenoid_number == SOLENOID1_ACTIVE) {
        gpioWrite(SOLENOID1_GPIO, 1);
        gpioWrite(SOLENOID2_GPIO, 0);
        current_active_solenoid = SOLENOID1_ACTIVE;
    } else if (solenoid_number == SOLENOID2_ACTIVE) {
        gpioWrite(SOLENOID1_GPIO, 0);
        gpioWrite(SOLENOID2_GPIO, 1);
        current_active_solenoid = SOLENOID2_ACTIVE;
    } else {
        fprintf(stderr, "Invalid solenoid number: %d\n", solenoid_number);
    }
}

// Function to deactivate a solenoid
void deactivate_solenoid(int solenoid_number) {
    if (solenoid_number == SOLENOID1_ACTIVE) {
        gpioWrite(SOLENOID1_GPIO, 0);
    } else if (solenoid_number == SOLENOID2_ACTIVE) {
        gpioWrite(SOLENOID2_GPIO, 0);
    } else {
        fprintf(stderr, "Invalid solenoid number: %d\n", solenoid_number);
    }
}

