void switch_solenoids() {
    if (current_active_solenoid == SOLENOID1_ACTIVE) {
        activate_solenoid(SOLENOID2_ACTIVE);
    } else if (current_active_solenoid == SOLENOID2_ACTIVE) {
        activate_solenoid(SOLENOID1_ACTIVE);
    } else {
        activate_solenoid(SOLENOID1_ACTIVE);
        current_active_solenoid = SOLENOID1_ACTIVE;
    }
}

