#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define UART0_DEVICE "/dev/serial0"
#define UART1_DEVICE "/dev/serial1"
#define BAUD_RATE 9600
#define TIMEOUT_MS 5000 // 5 seconds
#define LOCK_GPIO 17
#define UNLOCK_GPIO 27
#define EXPECTED_CODE "123456"
#define CODE_LENGTH 6
#define UNLOCK_DURATION_MS 2000

// Global variables
int uart0_fd = -1;
int uart1_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_uart(const char *device);
int read_code(int fd, char *code);
int compare_codes(const char *code1, const char *code2, const char *expected_code);
int control_lock(int lock_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
    control_lock(0); // Lock the door
    if (uart0_fd != -1) {
        close(uart0_fd);
    }
    if (uart1_fd != -1) {
        close(uart1_fd);
    }
    gpioTerminate();
    exit(0);
}

// Initialize UART port
int initialize_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes for %s: %s\n", device, strerror(errno));
        close(fd);
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN] = 0;              // read doesn't block
    tty.c_cc[VTIME] = 0;             // no inter-character timer

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;           // 1 stop bit
    tty.c_cflag &= ~CRTSCTS;          // disable hardware flowcontrol

    cfsetospeed(&tty, B9600);
    cfsetispeed(&tty, B9600);

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes for %s: %s\n", device, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Read code from UART port
int read_code(int fd, char *code) {
    memset(code, 0, CODE_LENGTH + 1); // Initialize code buffer
    int i = 0;
    struct timeval start_time, current_time;
    gettimeofday(&start_time, NULL);

    while (1) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = TIMEOUT_MS / 1000;
        timeout.tv_usec = (TIMEOUT_MS % 1000) * 1000;

        int select_result = select(fd + 1, &readfds, NULL, NULL, &timeout);

        if (select_result == -1) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            fprintf(stderr, "Error in select: %s\n", strerror(errno));
            return -1;
        } else if (select_result == 0) {
            // Timeout
            fprintf(stderr, "Timeout reading from UART\n");
            return -1;
        } else {
            // Data available
            char c = (char)tcgetchar(fd);
            if (c == -1) {
                fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
                return -1;
            }

            if (c >= '0' && c <= '9') {
                code[i++] = c;
                if (i == CODE_LENGTH) {
                    code[i] = '\0'; // Null-terminate the string
                    return 0;        // Code received successfully
                }
            } else {
                // Invalid character, reset buffer
                i = 0;
                code[0] = '\0';
            }
        }

        gettimeofday(&current_time, NULL);
        long elapsed_time = (current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_usec - start_time.tv_usec) / 1000;
        if (elapsed_time >= TIMEOUT_MS) {
            fprintf(stderr, "Timeout reading from UART\n");
            return -1;
        }
    }

    return -1; // Timeout or error
}

// Compare codes using constant-time comparison
int compare_codes(const char *code1, const char *code2, const char *expected_code) {
    if (strlen(code1) != strlen(expected_code) || strlen(code2) != strlen(expected_code)) {
        return 0; // Codes are of different lengths
    }

    int result = 1; // Assume codes are equal
    for (int i = 0; i < strlen(expected_code); i++) {
        result &= (code1[i] == expected_code[i]);
        result &= (code2[i] == expected_code[i]);
    }
    return result;
}

// Control the lock (HIGH for unlock, LOW for lock)
int control_lock(int lock_state) {
    if (gpioWrite(LOCK_GPIO, lock_state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", LOCK_GPIO, strerror(errno));
        return -1;
    }
    if (gpioWrite(UNLOCK_GPIO, lock_state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", UNLOCK_GPIO, strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK_GPIO, PI_OUTPUT);
    gpioSetMode(UNLOCK_GPIO, PI_OUTPUT);

    // Initialize UART ports
    uart0_fd = initialize_uart(UART0_DEVICE);
    if (uart0_fd == -1) {
        gpioTerminate();
        return 1;
    }

    uart1_fd = initialize_uart(UART1_DEVICE);
    if (uart1_fd == -1) {
        close(uart0_fd);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char code0[CODE_LENGTH + 1];
    char code1[CODE_LENGTH + 1];

    // Main loop
    while (!terminate) {
        int read0_result = read_code(uart0_fd, code0);
        int read1_result = read_code(uart1_fd, code1);

        if (read0_result == 0 && read1_result == 0) {
            // Both codes received
            if (compare_codes(code0, code1, EXPECTED_CODE)) {
                // Codes match expected code
                printf("Codes match: %s, %s\n", code0, code1);
                if (control_lock(1) == 0) { // Unlock
                    gpioDelay(UNLOCK_DURATION_MS);
                    control_lock(0);       // Lock
                }
            } else {
                printf("Codes do not match: %s, %s\n", code0, code1);
            }
        } else if (read0_result != 0) {
            fprintf(stderr, "Error reading from UART0\n");
        } else if (read1_result != 0) {
            fprintf(stderr, "Error reading from UART1\n");
        }

        gpioDelay(100); // Small delay to prevent busy-waiting
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_lock(0); // Lock the door
    close(uart0_fd);
    close(uart1_fd);
    gpioTerminate();

    return 0;
}

