#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON_TIME 1  // seconds
#define MOTION_TIMEOUT 10 // seconds
#define POLL_INTERVAL 50 // milliseconds

// Global variables
static volatile int running = 1;
static volatile unsigned long last_motion_time = 0;
static volatile int relay_state = 0; // 0 = off, 1 = on

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_relay(int state);
int log_event(int priority, const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Initialize relay to OFF state
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;

    log_event(LOG_INFO, "GPIO initialization complete");
    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Function to control the relay
int control_relay(int state) {
    if (state != relay_state) {
        gpioWrite(RELAY_PIN, state);
        relay_state = state;
        if (state == 1) {
