#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the relays (BCM numbering)
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define constants for timing
#define RELAY_ON_TIME 300  // 5 minutes in seconds
#define RELAY_OFF_TIME 60  // 1 minute in seconds
#define TIMER_INTERVAL 60  // 60 seconds

// Define the number of relays
#define NUM_RELAYS 4

// Global variables
static volatile sig_atomic_t terminate = 0;
static int current_relay = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
void activate_relay(int relay_number);
void deactivate_relay(int relay_number);
void timer_callback();

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, terminating...", signal);
    terminate = 1;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Set GPIO pins as outputs and initialize to HIGH (relay OFF)
    int gpios[] = {RELAY1_GPIO, RELAY2_GPIO, RELAY3_GPIO, RELAY4_GPIO};
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioSetMode(gpios[i], PI_OUTPUT);
        gpioWrite(gpios[i], 1); // Initialize to HIGH (relay OFF)
        syslog(LOG_INFO, "Initialized GPIO %d as output and set to HIGH", gpios[i]);
    }

    return 0;
}

// Cleanup GPIO pins
void cleanup_gpio() {
    // Set all relays to OFF (HIGH)
    int gpios[] = {RELAY1_GPIO, RELAY2_GPIO, RELAY3_GPIO, RELAY4_GPIO};
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(gpios[i], 1);
        syslog(LOG_INFO, "Deactivated relay on GPIO %d", gpios[i]);
    }

    gpioTerminate();
    syslog(LOG_INFO, "pigpio terminated");
}

// Activate a relay
void activate_relay(int relay_number) {
    int gpio_pin;
    switch (relay_number) {
        case 0:
            gpio_pin = RELAY1_GPIO;
            break;
        case 1:
            gpio_pin = RELAY2_GPIO;
            break;
        case 2:
            gpio_pin = RELAY3_GPIO;
            break;
        case 3:
            gpio_pin = RELAY4_GPIO;
            break;
        default:
            syslog(LOG_ERR, "Invalid relay number: %d", relay_number);
            return;
    }

    if (gpioWrite(gpio_pin, 0) != 0) {
        syslog(LOG_ERR, "Failed to activate relay on GPIO %d", gpio_pin);
    } else {
        syslog(LOG_INFO, "Activated relay on GPIO %d", gpio_pin);
    }
}

// Deactivate a relay
void deactivate_relay(int relay_number) {
    int gpio_pin;
    switch (relay_number) {
        case 0:
            gpio_pin = RELAY1_GPIO;
            break;
        case 1:
            gpio_pin = RELAY2_GPIO;
            break;
        case 2:
            gpio_pin = RELAY3_GPIO;
            break;
        case 3:
            gpio_pin = RELAY4_GPIO;
            break;
        default:
            syslog(LOG_ERR, "Invalid relay number: %d", relay_number);
            return;
    }

    if (gpioWrite(gpio_pin, 1) != 0) {
        syslog(LOG_ERR, "Failed to deactivate relay on GPIO %d", gpio_pin);
    } else {
        syslog(LOG_INFO, "Deactivated relay on GPIO %d", gpio_pin);
    }
}

// Timer callback function
void timer_callback() {
    syslog(LOG_INFO, "Timer callback triggered");

    // Deactivate the current relay
    deactivate_relay(current_relay);

    // Increment the relay number, wrapping around if necessary
    current_relay = (current_relay + 1) % NUM_RELAYS;

    // Activate the next relay
    activate_relay(current_relay);

    // Set a timer for the relay ON time
    gpioSetTimerFuncEx(0, RELAY_ON_TIME, timer_callback, NULL); // Timer 0, every RELAY_ON_TIME seconds

    // Set a timer for the relay OFF time (after the ON time)
    gpioSetTimerFuncEx(1, RELAY_OFF_TIME, timer_callback, NULL); // Timer 1, every RELAY_OFF_TIME seconds
}

int main() {
    // Open syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Set up the initial timer (timer 0)
    gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback, NULL);

    // Main loop
    while (!terminate) {
        sleep(1); // Sleep for 1 second
    }

    // Cleanup GPIO
    cleanup_gpio();

    // Close syslog
    closelog();

    return 0;
}

