#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>

// Configuration
#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define PWR_MGMT_1 0x6B
#define SAMPLE_RATE 100 // Hz
#define BUFFER_SIZE 100
#define SYSFS_PATH "/sys/kernel/mpu6050_accel/latest"

// Data structure for accelerometer readings
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accel_data_t;

// Global variables
static int i2c_fd = -1;
static int sysfs_fd = -1;
static accel_data_t *circular_buffer = NULL;
static int buffer_index = 0;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int addr);
int init_mpu6050(int fd);
int read_accel_data(int fd, accel_data_t *data);
int write_sysfs(const char *path, const char *value);
int read_sysfs(const char *path, char *value, size_t size);
void signal_handler(int sig);
void cleanup();

// I2C initialization function
int init_i2c(int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// MPU6050 initialization function
int init_mpu6050(int fd) {
    // Wake up the MPU6050 (set power management register to 0)
    uint8_t data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00;

    if (write(fd, data, 2) != 2) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data from MPU6050
int read_accel_data(int fd, accel_data_t *data) {
    uint8_t buffer[6];

    if (write(fd, (uint8_t[]){ACCEL_XOUT_H}, 1) != 1) {
        perror("Error writing to accelerometer register");
        return -1;
    }

    if (read(fd, buffer, 6) != 6) {
        perror("Error reading accelerometer data");
        return -1;
    }

    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to write to sysfs file
int write_sysfs(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening sysfs file for writing");
        return -1;
    }

    ssize_t bytes_written = write(fd, value, strlen(value));
    if (bytes_written < 0) {
        perror("Error writing to sysfs file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read from sysfs file
int read_sysfs(const char *path, char *value, size_t size) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("Error opening sysfs file for reading");
        return -1;
    }

    ssize_t bytes_read = read(fd, value, size - 1);
    if (bytes_read < 0) {
        perror("Error reading from sysfs file");
        close(fd);
        return -1;
    }

    value[bytes_read] = '\0';
    close(fd);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", sig);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");

    // Close I2C device
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Unlink sysfs file
    if (sysfs_fd != -1) {
        close(sysfs_fd);
        unlink(SYSFS_PATH);
    }

    // Free circular buffer
    if (circular_buffer != NULL) {
        free(circular_buffer);
    }

    fprintf(stderr, "Cleanup complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Allocate circular buffer
    circular_buffer = (accel_data_t *)malloc(BUFFER_SIZE * sizeof(accel_data_t));
    if (circular_buffer == NULL) {
        perror("Error allocating circular buffer");
        cleanup();
        return 1;
    }

    // Create sysfs file
    int fd = open(SYSFS_PATH, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("Error creating sysfs file");
        cleanup();
        return 1;
    }
    sysfs_fd = fd;
    close(sysfs_fd);

    // Main loop
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 1000000000 / SAMPLE_RATE; // 100 Hz

    while (!terminate) {
        accel_data_t data;

        // Read accelerometer data
        if (read_accel_data(i2c_fd, &data) == 0) {
            // Store data in circular buffer
            circular_buffer[buffer_index] = data;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Write latest data to sysfs file
            char buffer[256];
            snprintf(buffer, sizeof(buffer), "%d,%d,%d", data.x, data.y, data.z);
            if (write_sysfs(SYSFS_PATH, buffer) != 0) {
                fprintf(stderr, "Error writing to sysfs file.\n");
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data.\n");
        }

        // Sleep for a short time
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

