#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 18
#define RELAY2_GPIO 23
#define RELAY3_GPIO 24
#define RELAY4_GPIO 25

// Define intervals for each relay (in seconds)
#define RELAY1_INTERVAL 2
#define RELAY2_INTERVAL 3
#define RELAY3_INTERVAL 5
#define RELAY4_INTERVAL 7

// Global variables to store the last toggle time for each relay
struct timespec last_toggle_time1 = {0, 0};
struct timespec last_toggle_time2 = {0, 0};
struct timespec last_toggle_time3 = {0, 0};
struct timespec last_toggle_time4 = {0, 0};

// Function prototypes
int initialize_gpio();
void toggle_relay(int gpio_pin, int interval, struct timespec *last_toggle_time);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RELAY1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY2_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY3_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY3_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY4_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY4_GPIO);
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to toggle a relay based on a given interval
void toggle_relay(int gpio_pin, int interval, struct timespec *last_toggle_time) {
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    // Calculate the time difference in seconds
    double time_diff = (current_time.tv_sec - last_toggle_time->tv_sec) +
                       (current_time.tv_nsec - last_toggle_time->tv_nsec) / 1000000000.0;

    // Check if the interval has elapsed
    if (time_diff >= interval) {
        // Toggle the relay
        int current_level = gpioRead(gpio_pin);
        if (gpioWrite(gpio_pin, !current_level) != 0) {
            fprintf(stderr, "Failed to write to GPIO%d\n", gpio_pin);
        }

        // Update the last toggle time
        last_toggle_time->tv_sec = current_time.tv_sec;
        last_toggle_time->tv_nsec = current_time.tv_nsec;
    }
}

// Function to cleanup GPIO pins and terminate the pigpio library
void cleanup_gpio() {
    // Turn off all relays
    gpioWrite(RELAY1_GPIO, 0);
    gpioWrite(RELAY2_GPIO, 0);
    gpioWrite(RELAY3_GPIO, 0);
    gpioWrite(RELAY4_GPIO, 0);

    // Terminate the pigpio library
    gpioTerminate();
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        toggle_relay(RELAY1_GPIO, RELAY1_INTERVAL, &last_toggle_time1);
        toggle_relay(RELAY2_GPIO, RELAY2_INTERVAL, &last_toggle_time2);
        toggle_relay(RELAY3_GPIO, RELAY3_INTERVAL, &last_toggle_time3);
        toggle_relay(RELAY4_GPIO, RELAY4_INTERVAL, &last_toggle_time4);

        // Small delay to prevent busy-waiting
        gpioDelay(100); // 100 milliseconds
    }

    return 0; // This line will never be reached due to the infinite loop
}

