// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define constants
#define RELAY_ON_TIME 3  // seconds
#define DEBOUNCE_TIME 0.5 // seconds
#define POLLING_INTERVAL 0.1 // seconds

// Global variables
static volatile int running = 1;
static volatile double last_activation_time = 0.0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
int activate_relay();
int log_event();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioWrite(RELAY_PIN, 0); // Turn off relay
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off initially

    return 0;
}

// Read sound sensor value
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Activate relay for a specified duration
int activate_relay() {
    gpioWrite(RELAY_PIN, 1); // Turn on relay
    gpioDelay(RELAY_ON_TIME * 1000000); // Delay for 3 seconds (microseconds)
    gpioWrite(RELAY_PIN, 0); // Turn off relay
    return 0;
}

// Log event to file
int log_event() {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: Sound event detected, relay activated\n", s);
    fclose(fp);
    return 0;
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sound sensor
        int sound_detected = read_sound_sensor();

        // Check for sound event and debounce
        if (sound_detected == 0) { // KY-038 outputs LOW when sound is detected
            double current_time = time_time();
            if (current_time - last_activation_time > DEBOUNCE_TIME) {
                printf("Sound detected! Activating relay.\n");
                activate_relay();
                log_event();
                last_activation_time = current_time;
            }
        }

        gpioDelay(POLLING_INTERVAL * 100000); // Delay for 100ms (microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate(); // Terminate pigpio

    return 0;
}

