#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

// Sensitivity scale factor for gyroscope (±250°/s)
#define GYRO_SCALE 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold (degrees/second)
#define ANGULAR_VELOCITY_THRESHOLD 50.0

// I2C device path
#define I2C_DEVICE "/dev/i2c-1"

// Global variables
int i2c_fd = -1; // I2C file descriptor
bool running = true; // Flag to control the main loop

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c(void);
int init_mpu6050(void);
int read_gyro_data(float *x, float *y, float *z);
float calculate_angular_velocity(float x, float y, float z);
void buffer_init(CircularBuffer *cb);
void buffer_add(CircularBuffer *cb, float value);
float buffer_get_average(CircularBuffer *cb);
void angular_velocity_callback(float x, float y, float z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        running = false;
    }
}

// Initialize I2C
int init_i2c(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize MPU-6050
int init_mpu6050(void) {
    uint8_t data[2];

    // Wake up the MPU-6050 (clear sleep mode bit)
    data[0] = PWR_MGMT_1;
    data[1] = 0x00;
    if (write(i2c_fd, data, 2) != 2) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    uint8_t data[6];
    int16_t raw_x, raw_y, raw_z;

    // Read gyroscope data registers
    if (write(i2c_fd, (uint8_t[]){GYRO_XOUT_H}, 1) != 1) {
        perror("Error writing to GYRO_XOUT_H register");
        return -1;
    }

    if (read(i2c_fd, data, 6) != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    // Combine high and low bytes to get raw values
    raw_x = (int16_t)((data[0] << 8) | data[1]);
    raw_y = (int16_t)((data[2] << 8) | data[3]);
    raw_z = (int16_t)((data[4] << 8) | data[5]);

    // Convert raw values to degrees/second
    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;

    return 0;
}

