#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>

// Define UART device and baud rate
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B9600

// Define MH-Z19B command
#define MHZ19B_COMMAND_LENGTH 9
const unsigned char MHZ19B_COMMAND[MHZ19B_COMMAND_LENGTH] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};

// Define log file names
#define CO2_LOG_FILE "co2_log.json"
#define CO2_ERROR_LOG_FILE "co2_error.log"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *co2_log_fp = NULL;
FILE *co2_error_fp = NULL;

// Structure to hold sensor data
typedef struct {
    long long timestamp;
    int ppm;
    int error;
} sensor_data_t;

// Function prototypes
int initialize_uart(const char *device, speed_t baud_rate);
int read_mhz19b(int fd, unsigned char *response);
int validate_checksum(const unsigned char *response);
int parse_ppm(const unsigned char *response);
long long get_timestamp_us();
int log_data(const sensor_data_t *data);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the UART
int initialize_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 5; // Wait for 0.5 seconds (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the MH-Z19B sensor
int read_mhz19b(int fd, unsigned char *response) {
    ssize_t bytes_read = 0;
    ssize_t total_bytes_read = 0;
    time_t start_time = time(NULL);

    while (total_bytes_read < MHZ19B_COMMAND_LENGTH && (time(NULL) - start_time) < 1) {
        bytes_read = read(fd, response + total_bytes_read, MHZ19B_COMMAND_LENGTH - total_bytes_read);
        if (bytes_read > 0) {
            total_bytes_read += bytes_read;
        } else if (bytes_read < 0) {
            perror("Error reading from UART");
            return -1;
        } else {
            usleep(10000); // Wait 10ms before retrying
        }
    }

    if (total_bytes_read != MHZ19B_COMMAND_LENGTH) {
        fprintf(stderr, "Timeout reading from MH-Z19B\n");
        return -1;
    }

    return 0;
}

// Function to validate the checksum of the response
int validate_checksum(const unsigned char *response) {
    unsigned char checksum = 0;
    for (int i = 1; i < MHZ19B_COMMAND_LENGTH - 1; i++) {
        checksum += response[i];
    }

    if (checksum != response[MHZ19B_COMMAND_LENGTH - 1]) {
        return -1; // Checksum mismatch
    }

    return 0;
}

// Function to parse the PPM value from the response
int parse_ppm(const unsigned char *response) {
    return (response[2] << 8) | response[3];
}

// Function to get the current timestamp in microseconds
long long get_timestamp_us() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (long long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
}

// Function to log the sensor data to a file
int log_data(const sensor_data_t *data) {
    if (co2_log_fp == NULL) {
        fprintf(stderr, "Log file not opened\n");
        return -1;
    }

    fprintf(co2_log_fp, "{\"timestamp\": %lld, \"ppm\": %d, \"error\": %d}\n", data->timestamp, data->ppm, data->error);
    fflush(co2_log_fp);
    return 0;
}

// Function to log errors to a file
int log_error(const char *message) {
    if (co2_error_fp == NULL) {
        fprintf(stderr, "Error log file not opened\n");
        return -1;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(co2_error_fp, "%s: %s\n", timestamp, message);
    fflush(co2_error_fp);
    return 0;
}

// Function to perform cleanup before exiting
void cleanup() {
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (co2_log_fp != NULL) {
        fclose(co2_log_fp);
    }
    if (co2_error_fp != NULL) {
        fclose(co2_error_fp);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log files
    co2_log_fp = fopen(CO2_LOG_FILE, "a");
    if (co2_log_fp == NULL) {
        perror("Error opening co2_log.json");
        return EXIT_FAILURE;
    }

    co2_error_fp = fopen(CO2_ERROR_LOG_FILE, "a");
    if (co2_error_fp == NULL) {
        perror("Error opening co2_error.log");
        fclose(co2_log_fp);
        return EXIT_FAILURE;
    }

    // Initialize UART
    uart_fd = initialize_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        log_error("Failed to initialize UART");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (program_running) {
        unsigned char response[MHZ19B_COMMAND_LENGTH];
        sensor_data_t data;

        // Send command to MH-Z19B
        if (write(uart_fd, MHZ19B_COMMAND, MHZ19B_COMMAND_LENGTH) != MHZ19B_COMMAND_LENGTH) {
            log_error("Failed to write command to MH-Z19B");
            data.error = 1;
        } else {
            // Read response from MH-Z19B
            if (read_mhz19b(uart_fd, response) == 0) {
                // Validate checksum
                if (validate_checksum(response) == 0) {
                    // Parse PPM value
                    data.ppm = parse_ppm(response);
                    data.error = 0;
                } else {
                    log_error("Checksum mismatch");
                    data.error = 1;
                }
            } else {
                data.error = 1;
            }
        }

        // Get timestamp
        data.timestamp = get_timestamp_us();

        // Log data
        if (log_data(&data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Print data to stdout (simulating remote API call)
        printf("{\"timestamp\": %lld, \"ppm\": %d, \"error\": %d}\n", data.timestamp, data.ppm, data.error);

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

