#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Hard-iron offsets
#define HARD_IRON_X_OFFSET 100.0f
#define HARD_IRON_Y_OFFSET -50.0f

// Target heading
#define TARGET_HEADING 90.0f

// GPIO pin for output
#define GPIO_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Sampling interval (milliseconds)
#define SAMPLE_INTERVAL 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

circular_buffer_t heading_buffer;

// Function prototypes
int init_i2c();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t x, int16_t y);
float apply_hard_iron_compensation(int16_t x, int16_t y);
void add_to_buffer(circular_buffer_t *buffer, float value);
float get_average_heading(circular_buffer_t *buffer);
void set_gpio_output(float heading);
void signal_handler(int signal);
void cleanup();

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Configure the HMC5883L
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) { // 8-average, 15 Hz, normal measurement
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0xA0) < 0) { // Gain = 5
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) { // Continuous measurement mode
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate heading in degrees
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2((float)y, (float)x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Apply hard-iron compensation
float apply_hard_iron_compensation(int16_t x, int16_t y) {
    float compensated_x = (float)x - HARD_IRON_X_OFFSET;
    float compensated_y = (float)y - HARD_IRON_Y_OFFSET;
    return calculate_heading((int16_t)compensated_x, (int16_t)compensated_y);
}

// Add value to circular buffer
void add_to_buffer(circular_buffer_t *buffer, float value) {
    buffer->buffer[buffer->head] = value;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get average heading from circular buffer
float get_average_heading(circular_buffer_t *buffer) {
    if (buffer->count == 0) {
        return 0.0f;
    }

    float sum = 0.0f;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->buffer[i];
    }
    return sum / buffer->count;
}

// Set GPIO output based on heading deviation
void set_gpio_output(float heading) {
    float deviation = fabs(heading - TARGET_HEADING);
    if (deviation > 10.0f) {
        gpioWrite(GPIO_PIN, 1); // High
    } else {
        gpioWrite(GPIO_PIN, 0); // Low
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(GPIO_PIN, 0); // Set GPIO low before exiting
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    heading_buffer.head = 0;
    heading_buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float heading, average_heading;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Apply hard-iron compensation
            heading = apply_hard_iron_compensation(x, y);

            // Add heading to circular buffer
            add_to_buffer(&heading_buffer, heading);

            // Calculate average heading
            average_heading = get_average_heading(&heading_buffer);

            // Set GPIO output
            set_gpio_output(average_heading);

            // Print heading (for debugging)
            printf("Heading: %.2f, Average Heading: %.2f\n", heading, average_heading);
        } else {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

