#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RED_GPIO 17
#define GREEN_GPIO 27
#define BLUE_GPIO 22
#define LOG_FILE "lighting_log.txt"
#define SLEEP_DURATION 1.0 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int read_bh1750(float *lux);
void control_relays(float lux);
void log_data(float lux, int red_state, int green_state, int blue_state);
void cleanup();
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize GPIO pins
int init_gpio() {
    if (gpioSetMode(RED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting RED_GPIO mode: %s\n", strerror(errno));
        return -1;
    }
    if (gpioSetMode(GREEN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GREEN_GPIO mode: %s\n", strerror(errno));
        return -1;
    }
    if (gpioSetMode(BLUE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting BLUE_GPIO mode: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    char config[1] = {0x10}; // Continuous high-resolution mode
    char buffer[2];
    int result;

    result = i2cWriteDevice(i2c_handle, config, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(120); // Wait for conversion (at least 120ms)

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2; // Convert to lux

    return 0;
}

// Control relays based on lux value
void control_relays(float lux) {
    int red_state = 0, green_state = 0, blue_state = 0;

    if (lux < 50) {
        red_state = 1;
    } else if (lux >= 50 && lux < 150) {
        green_state = 1;
    } else if (lux >= 150 && lux < 300) {
        blue_state = 1;
    } else if (lux >= 300) {
        red_state = 1;
        green_state = 1;
        blue_state = 1;
    }

    gpioWrite(RED_GPIO, red_state);
    gpioWrite(GREEN_GPIO, green_state);
    gpioWrite(BLUE_GPIO, blue_state);
}

// Log data to file
void log_data(float lux, int red_state, int green_state, int blue_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%d,%d,%d\n", timestamp, lux, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to disk
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(RED_GPIO, 0);
    gpioWrite(GREEN_GPIO, 0);
    gpioWrite(BLUE_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    int red_state, green_state, blue_state;

    printf("Starting main loop...\n");

    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            control_relays(lux);
            red_state = gpioRead(RED_GPIO);
            green_state = gpioRead(GREEN_GPIO);
            blue_state = gpioRead(BLUE_GPIO);
            log_data(lux, red_state, green_state, blue_state);
        } else {
            fprintf(stderr, "Error reading BH1750 sensor.\n");
        }

        gpioDelay((int)(SLEEP_DURATION * 1000)); // Sleep for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

