#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor A GPIOs
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B GPIOs
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM Frequency (Hz)
#define PWM_FREQUENCY 1000

// Proportional Gain
#define PROPORTIONAL_GAIN 2

// Distance Range
#define MIN_DISTANCE 10
#define MAX_DISTANCE 100

// Global flag for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and cleaning up...\n", signal);
}

// Function to set motor direction
void set_motor_direction(int in1_pin, int in2_pin, int direction) {
    if (direction == 1) { // Forward
        gpioWrite(in1_pin, 1);
        gpioWrite(in2_pin, 0);
    } else if (direction == -1) { // Backward
        gpioWrite(in1_pin, 0);
        gpioWrite(in2_pin, 1);
    } else { // Stop
        gpioWrite(in1_pin, 0);
        gpioWrite(in2_pin, 0);
    }
}

// Function to set motor speed using PWM
void set_motor_speed(int in2_pin, int in4_pin, int distance_a, int distance_b) {
    // Calculate duty cycle for Motor A
    int duty_cycle_a = (int)(((float)(distance_a - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * 255.0);
    if (duty_cycle_a < 0) duty_cycle_a = 0;
    if (duty_cycle_a > 255) duty_cycle_a = 255;

    // Calculate duty cycle for Motor B
    int duty_cycle_b = (int)(((float)(distance_b - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * 255.0);
    if (duty_cycle_b < 0) duty_cycle_b = 0;
    if (duty_cycle_b > 255) duty_cycle_b = 255;

    // Set PWM duty cycle for Motor A
    gpioPWM(in2_pin, duty_cycle_a);

    // Set PWM duty cycle for Motor B
    gpioPWM(in4_pin, duty_cycle_b);
}

int main(int argc, char *argv[]) {
    // Check for correct number of command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_a> <distance_b>\n", argv[0]);
        return 1;
    }

    // Parse command-line arguments
    int distance_a = atoi(argv[1]);
    int distance_b = atoi(argv[2]);

    // Validate command-line arguments
    if (distance_a < MIN_DISTANCE || distance_a > MAX_DISTANCE || distance_b < MIN_DISTANCE || distance_b > MAX_DISTANCE) {
        fprintf(stderr, "Error: Distance values must be between %d and %d cm\n", MIN_DISTANCE, MAX_DISTANCE);
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for Motor A
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);

    // Set GPIO modes for Motor B
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency for Motor A
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);

    // Set PWM frequency for Motor B
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (program_running) {
        // Determine direction based on distance
        int direction_a = (distance_a < 50) ? 1 : -1;
        int direction_b = (distance_b < 50) ? 1 : -1;

        // Set motor direction
        set_motor_direction(MOTOR_A_IN1, MOTOR_A_IN2, direction_a);
        set_motor_direction(MOTOR_B_IN3, MOTOR_B_IN4, direction_b);

        // Set motor speed
        set_motor_speed(MOTOR_A_IN2, MOTOR_B_IN4, distance_a, distance_b);

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Stop motors and cleanup
    set_motor_direction(MOTOR_A_IN1, MOTOR_A_IN2, 0);
    set_motor_direction(MOTOR_B_IN3, MOTOR_B_IN4, 0);
    gpioTerminate();

    return 0;
}

