#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define PI 3.14159265359
#define SERVO_GPIO 18
#define PWM_CHIP 2
#define PWM_NUM 0
#define PWM_PERIOD 20000 // 20ms (50Hz)
#define MIN_DUTY 1000     // 1ms
#define MAX_DUTY 2000     // 2ms
#define LOG_FILE "solar_tracker.log"

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_mpu6050();
int read_mpu6050(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void calculate_pitch_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll);
int set_servo_angle(float pitch);
int log_data(float pitch, float roll, int servo_position);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize MPU6050
int init_mpu6050() {
    // Wake up the MPU6050
    char data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00; // Clear sleep mode bit
    if (write(i2c_fd, data, 2) != 2) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }

    // Configure accelerometer range to +/- 2g
    data[0] = ACCEL_CONFIG;
    data[1] = 0x00; // 0x00 = +/- 2g
    if (write(i2c_fd, data, 2) != 2) {
        perror("Error writing to ACCEL_CONFIG");
        return -1;
    }

    // Configure gyroscope range to +/- 250 deg/s
    data[0] = GYRO_CONFIG;
    data[1] = 0x00; // 0x00 = +/- 250 deg/s
    if (write(i2c_fd, data, 2) != 2) {
        perror("Error writing to GYRO_CONFIG");
        return -1;
    }

    return 0;
}

// Read MPU6050 data
int read_mpu6050(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char reg = ACCEL_XOUT_H;
    char data[14];

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (read(i2c_fd, data, 14) != 14) {
        perror("Error reading data");
        return -1;
    }

    *accel_x = (data[0] << 8) | data[1];
    *accel_y = (data[2] << 8) | data[3];
    *accel_z = (data[4] << 8) | data[5];
    *gyro_x = (data[8] << 8) | data[9];
    *gyro_y = (data[10] << 8) | data[11];
    *gyro_z = (data[12] << 8) | data[13];

    return 0;
}

// Calculate pitch and roll
void calculate_pitch_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll) {
    float ax = (float)accel_x;
    float ay = (float)accel_y;
    float az = (float)accel_z;

    *pitch = atan2(ax, sqrt(ay * ay + az * az)) * 180 / PI;
    *roll = atan2(ay, sqrt(ax * ax + az * az)) * 180 / PI;
}

// Set servo angle using pigpio
int set_servo_angle(float pitch) {
    // Map pitch to servo duty cycle (0-180 degrees)
    int duty_cycle = (int)((pitch + 90) * (MAX_DUTY - MIN_DUTY) / 180 + MIN_DUTY); // Assuming pitch range is -90 to 90

    // Clamp duty cycle to valid range
    if (duty_cycle < MIN_DUTY) {
        duty_cycle = MIN_DUTY;
    } else if (duty_cycle > MAX_DUTY) {
        duty_cycle = MAX_DUTY;
    }

    // Set PWM duty cycle
    gpioPWM(SERVO_GPIO, duty_cycle * 10000 / PWM_PERIOD); // pigpio uses range 0-1000000

    return duty_cycle;
}

// Log data to file
int log_data(float pitch, float roll, int servo_position) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_position);
    fflush(log_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() != 0) {
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize PWM
    char pwm_path[64];
    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwmchip%d/pwm%d", PWM_CHIP, PWM_NUM);
    int pwm_fd = open(pwm_path, O_WRONLY);
    if (pwm_fd < 0) {
        perror("Error opening PWM file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    char enable_path[64];
    snprintf(enable_path, sizeof(enable_path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_NUM);
    if (write(pwm_fd, "1", 1) != 1) {
        perror("Error enabling PWM");
        close(pwm_fd);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    char period_path[64];
    snprintf(period_path, sizeof(period_path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_NUM);
    char period_str[16];
    snprintf(period_str, sizeof(period_str), "%d", PWM_PERIOD);
    if (write(pwm_fd, period_str, strlen(period_str)) != strlen(period_str)) {
