#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define fade duration
#define FADE_DURATION 1800 // seconds

// Define schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Structure to represent a schedule entry
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int on_off;
} schedule_entry_t;

// Global variables
static volatile int running = 1;
static schedule_entry_t *schedule = NULL;
static int schedule_size = 0;

// Function prototypes
int read_schedule(const char *filename);
void set_relay_state(int relay_number, int state);
void fade_lights(int relay_number, int target_state);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to read the schedule from a file
int read_schedule(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    // Determine the number of lines in the file
    char line[256];
    schedule_size = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        schedule_size++;
    }

    // Allocate memory for the schedule
    schedule = (schedule_entry_t *)malloc(schedule_size * sizeof(schedule_entry_t));
    if (schedule == NULL) {
        perror("Error allocating memory for schedule");
        fclose(fp);
        return -1;
    }

    // Rewind the file pointer to the beginning
    rewind(fp);

    // Read the schedule entries
    int i = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "%d:%d:%d,%d,%d", &schedule[i].hour, &schedule[i].minute, &schedule[i].second, &schedule[i].relay_number, &schedule[i].on_off) != 5) {
            fprintf(stderr, "Error parsing schedule entry: %s", line);
            free(schedule);
            schedule = NULL;
            schedule_size = 0;
            fclose(fp);
            return -1;
        }
        i++;
    }

    fclose(fp);
    return 0;
}

// Function to set the state of a relay
void set_relay_state(int relay_number, int state) {
    int gpio_pin;

    switch (relay_number) {
        case 1:
            gpio_pin = RELAY1_GPIO;
            break;
        case 2:
            gpio_pin = RELAY2_GPIO;
            break;
        case 3:
            gpio_pin = RELAY3_GPIO;
            break;
        case 4:
            gpio_pin = RELAY4_GPIO;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    gpioWrite(gpio_pin, state);
    printf("Relay %d set to %s\n", relay_number, state ? "ON" : "OFF");
}

// Function to fade the lights
void fade_lights(int relay_number, int target_state) {
    int gpio_pin;

    switch (relay_number) {
        case 1:
            gpio_pin = RELAY1_GPIO;
            break;
        case 2:
            gpio_pin = RELAY2_GPIO;
            break;
        case 3:
            gpio_pin = RELAY3_GPIO;
            break;
        case 4:
            gpio_pin = RELAY4_GPIO;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(gpio_pin, PWM_FREQUENCY);

    // Calculate the number of steps for the fade
    int num_steps = FADE_DURATION * PWM_FREQUENCY; // 1800 seconds * 100 Hz

    // Calculate the step size for the duty cycle
    int step_size = (target_state == 1) ? 100 / num_steps : -100 / num_steps;

    // Perform the fade
    for (int i = 0; i <= num_steps; i++) {
        int duty_cycle = (i * step_size);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 100) duty_cycle = 100;

        gpioPWM(gpio_pin, duty_cycle);
        gpioDelay(5); // Delay for 5ms (adjust as needed)
    }

    // Ensure the relay is fully on or off after the fade
    gpioWrite(gpio_pin, target_state);
}

// Function to cleanup GPIO resources
void cleanup() {
    printf("Cleaning up GPIO resources...\n");

    // Turn off all relays
    set_relay_state(1, 0);
    set_relay_state(2, 0);
    set_relay_state(3, 0);
    set_relay_state(4, 0);

    // Release GPIO resources
    gpioTerminate();

    // Free the schedule memory
    if (schedule != NULL) {
        free(schedule);
        schedule = NULL;
    }

    printf("Cleanup complete.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    // Read the schedule
    if (read_schedule(SCHEDULE_FILE) != 0) {
        fprintf(stderr, "Failed to read schedule. Exiting.\n");
        cleanup();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    time_t current_time;
    struct tm *time_info;
    int i;

    while (running) {
        // Get current time
        time(&current_time);
        time_info = localtime(&current_time);

        // Get current time in seconds since epoch
        time_t now = time(NULL);

        // Iterate through the schedule
        for (i = 0; i < schedule_size; i++) {
            // Calculate the scheduled time in seconds since epoch
            time_t scheduled_time = mktime(time_info);
            time_info->tm_hour = schedule[i].hour;
            time_info->tm_min = schedule[i].minute;
            time_info->tm_sec = schedule[i].second;
            time_t scheduled_time_seconds = mktime(time_info);

            // Check if the scheduled time is within a reasonable range of the current time
            if (abs(now - scheduled_time_seconds) < 60) { // Check within a minute
                printf("Schedule entry: %02d:%02d:%02d, Relay %d, %s\n",
                       schedule[i].hour, schedule[i].minute, schedule[i].second,
                       schedule[i].relay_number, schedule[i].on_off ? "ON" : "OFF");

                // Fade the lights
                fade_lights(schedule[i].relay_number, schedule[i].on_off);
            }
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

