#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define MIN_DISTANCE 2       // cm
#define MAX_DISTANCE 20      // cm
#define MIN_FREQUENCY 200    // Hz
#define MAX_FREQUENCY 2000   // Hz
#define TIMEOUT_US 50000      // 50ms timeout

// Global variables
static volatile int running = 1;
static volatile unsigned int start_tick = 0;
static volatile unsigned int end_tick = 0;
static volatile int echo_received = 0;

// Function prototypes
void signal_handler(int signal);
void trigger_sensor();
float get_distance();
float map_distance_to_frequency(float distance);
void set_buzzer_frequency(float frequency);
void echo_callback(int gpio, int level, unsigned int tick);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioPWM(BUZZER_PIN, 0); // Silence the buzzer
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1;
    } else if (level == 0 && echo_received) {
        end_tick = tick;
        echo_received = 0;
    }
}

// Function to get the distance from the ultrasonic sensor
float get_distance() {
    trigger_sensor();
    start_tick = 0; // Reset start tick
    end_tick = 0;   // Reset end tick
    echo_received = 0; // Reset echo received flag

    // Wait for echo or timeout
    int timeout_count = 0;
    while (!echo_received && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        timeout_count++;
    }

    if (!echo_received) {
        fprintf(stderr, "Error: Timeout waiting for echo.\n");
        return -1.0; // Indicate timeout error
    }

    // Calculate pulse width in microseconds
    unsigned int pulse_width = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 100 to convert m to cm

    return distance;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    // Clamp distance to the defined range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Map distance to frequency linearly
    float frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);

    return frequency;
}

// Function to set the buzzer frequency using PWM
void set_buzzer_frequency(float frequency) {
    // Clamp frequency to the valid range
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    // Calculate PWM duty cycle (0-1000)
    int duty_cycle = (int)((frequency / 1000.0) * 1000.0); // pigpio uses 0-1000 for duty cycle

    gpioPWM(BUZZER_PIN, duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range (0-1000)
    gpioSetPWMrange(BUZZER_PIN, 1000);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(BUZZER_PIN, 400); // Initial frequency

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (running) {
        // Get distance
        float distance = get_distance();

        if (distance > 0) {
            // Map distance to frequency
            float frequency = map_distance_to_frequency(distance);

            // Set buzzer frequency
            set_buzzer_frequency(frequency);

            // Print distance and frequency (for debugging)
            printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        } else {
            // Handle error (e.g., timeout)
            fprintf(stderr, "Error: Could not read distance.\n");
        }

        // Delay to achieve approximately 50 Hz loop rate (20 ms)
        gpioDelay(20);
    }

    // Clean up (should not reach here if signal handler works correctly)
    gpioPWM(BUZZER_PIN, 0); // Silence the buzzer
    gpioTerminate();         // Terminate pigpio

    return 0;
}

