#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Sensitivity scale factor for gyroscope (LSB/deg/s)
#define GYRO_SCALE 131.0

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully.\n");
    terminate = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050(int fd) {
    // Wake up the MPU-6050 (clear sleep mode bit)
    uint8_t data = 0x00;
    uint8_t reg = PWR_MGMT_1;
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to PWR_MGMT_1 register");
        return -1;
    }
    if (write(fd, &data, 1) != 1) {
        perror("Failed to write to PWR_MGMT_1 register");
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t buffer[6];
    uint8_t reg = GYRO_XOUT_H;

    // Write the register address to be read
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    // Read 6 bytes of data (X, Y, Z axis)
    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read gyroscope data");
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit integer
    int16_t gyro_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t gyro_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t gyro_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to degrees per second
    *x = (float)gyro_x / GYRO_SCALE;
    *y = (float)gyro_y / GYRO_SCALE;
    *z = (float)gyro_z / GYRO_SCALE;

    return 0;
}

// Function to log data to file
int log_data(FILE *fp, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    float x, y, z;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            // Log data to file
            if (log_data(log_file, x, y, z) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyroscope data.\n");
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

