#include <pigpio.h>

// Define GPIO pins
#define BUTTON_GPIO 17
#define BUZZER_GPIO 18

// Define PWM frequency
#define PWM_FREQUENCY 440

// Define debounce interval (milliseconds)
#define DEBOUNCE_INTERVAL 50

// Define melody lookup table
const int melody[] = {440, 494, 523, 587, 659, 698, 784, 880};
const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Global variables
volatile int button_pressed = 0;
volatile int melody_playing = 0;
volatile int melody_index = 0;

// Function prototypes
void button_isr(int gpio, int level, uint32_t tick, void *user);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_melody();
    gpioTerminate();
    exit(0);
}

// Button interrupt service routine
void button_isr(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    // Debounce the button
    if (current_tick - last_tick > DEBOUNCE_INTERVAL * 1000) {
        if (level == 0) { // Button pressed (active low)
            button_pressed = 1;
            if (!melody_playing) {
                play_melody();
            } else {
                stop_melody();
            }
        }
        last_tick = current_tick;
    }
}

// Function to play the melody
void play_melody() {
    if (melody_playing) return; // Prevent re-entry
    melody_playing = 1;
    melody_index = 0;

    while (melody_index < melody_length && melody_playing) {
        gpioPWM(BUZZER_GPIO, 128); // 50% duty cycle
        gpioSetPWMfrequency(BUZZER_GPIO, melody[melody_index]);
        gpioDelay(200); // Play each note for 200ms
        gpioPWM(BUZZER_GPIO, 0); // Stop the tone
        gpioDelay(50); // Short pause between notes
        melody_index++;
    }

    if (melody_index >= melody_length) {
        melody_playing = 0;
    }
}

// Function to stop the melody
void stop_melody() {
    gpioPWM(BUZZER_GPIO, 0); // Stop PWM
    melody_playing = 0;
    melody_index = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input with pull-up resistor
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    // Set GPIO18 as output for PWM
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(BUZZER_GPIO, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(BUZZER_GPIO, 255);

    // Register interrupt handler for button press
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Doorbell system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (button_pressed) {
            button_pressed = 0;
            // The ISR already handles playing/stopping the melody
        }
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    return 0;
}

