#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 17
#define DEFAULT_TIMEOUT 1000
#define WINDOW_SIZE 5

// Structure to hold the last few events
typedef struct {
    int events[WINDOW_SIZE];
    int index;
} EventWindow;

// Global variables
static volatile sig_atomic_t terminate = 0;
static FILE *log_file = NULL;
static int timeout_ms = DEFAULT_TIMEOUT;

// Function prototypes
void signal_handler(int signal);
int read_sensor();
void log_event(int value);
void check_earthquake_alert(EventWindow *window, int new_value);
char* get_iso8601_timestamp();
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to log an event to the file
void log_event(int value) {
    char *timestamp = get_iso8601_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s %d\n", timestamp, value);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    free(timestamp);
}

// Function to check for an earthquake alert
void check_earthquake_alert(EventWindow *window, int new_value) {
    window->events[window->index] = new_value;
    window->index = (window->index + 1) % WINDOW_SIZE;

    int high_count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        if (window->events[i] == 1) {
            high_count++;
        }
    }

    if (high_count >= 3) {
        char *timestamp = get_iso8601_timestamp();
        printf("%s EARTHQUAKE ALERT\n", timestamp);
        free(timestamp);
    }
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(buffer, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default timeout of %d ms.\n", DEFAULT_TIMEOUT);
            timeout_ms = DEFAULT_TIMEOUT;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open the log file
    log_file = fopen("vibration_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize event window
    EventWindow event_window = {{0}, 0};

    // Main loop
    while (!terminate) {
        int sensor_value = read_sensor();
        log_event(sensor_value);
        check_earthquake_alert(&event_window, sensor_value);
        gpioDelay(timeout_ms); // Delay for the specified timeout
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

