    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0; // Indicate success
}

// Function to calibrate magnetometer data
void calibrate_magnetometer_data(int16_t x, int16_t y, int16_t z, int16_t *x_calibrated, int16_t *y_calibrated, int16_t *z_calibrated) {
    *x_calibrated = x - X_OFFSET;
    *y_calibrated = y - Y_OFFSET;
    *z_calibrated = z - Z_OFFSET;
}

// Function to calculate heading
float calculate_heading(int16_t x_calibrated, int16_t y_calibrated) {
    float heading = atan2(y_calibrated, x_calibrated) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Function to map heading to compass direction
const char *map_heading_to_direction(float heading) {
    if (heading >= 337.5 || heading < 22.5) {
        return "N";
    } else if (heading >= 22.5 && heading < 67.5) {
        return "NE";
    } else if (heading >= 67.5 && heading < 112.5) {
        return "E";
    } else if (heading >= 112.5 && heading < 157.5) {
        return "SE";
    } else if (heading >= 157.5 && heading < 202.5) {
        return "S";
    } else if (heading >= 202.5 && heading < 247.5) {
        return "SW";
    } else if (heading >= 247.5 && heading < 292.5) {
        return "W";
    } else {
        return "NW";
    }
}

// Function to log data to file
void log_data(FILE *fp, int16_t x_calibrated, int16_t y_calibrated, int16_t z_calibrated, float heading) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %d, %d, %d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x_calibrated, y_calibrated, z_calibrated, heading);
    fflush(fp); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z, x_calibrated, y_calibrated, z_calibrated;
    float heading;
    const char *direction;

    // Main loop
    while (1) {
        // Read magnetometer data
        if (read_magnetometer_data(i2c_handle, &x, &y, &z) == 0) {
            // Calibrate magnetometer data
            calibrate_magnetometer_data(x, y, z, &x_calibrated, &y_calibrated, &z_calibrated);

            // Calculate heading
            heading = calculate_heading(x_calibrated, y_calibrated);

            // Map heading to direction
            direction = map_heading_to_direction(heading);

            // Log data to file
            log_data(log_file, x_calibrated, y_calibrated, z_calibrated, heading);

            // Print heading and direction to console
            printf("Heading: %.2f, Direction: %s\n", heading, direction);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Skipping sample.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate proper cleanup.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

