static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile unsigned int last_touch_time = 0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void touch_callback(int gpio, int level, unsigned int tick);
