    while (1) {
        pause(); // Wait for a signal
    }

    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input with pull-down resistor
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Set GPIO17 as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF

    // Set interrupt callback for touch sensor
    if (gpioSetISRFuncEx(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Interrupt service routine for touch sensor
void touch_callback(int gpio, int level, unsigned int tick) {
    unsigned int current_time = gpioTick();

    // Debounce the touch sensor
    if (current_time - last_touch_time < DEBOUNCE_TIME * 1000) {
        return; // Ignore the touch
    }

    last_touch_time = current_time;

    // Toggle the relay
    if (toggle_relay() != 0) {
        fprintf(stderr, "Failed to toggle relay\n");
    }
}

// Toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);

    // Log the relay state
    if (log_relay_state(relay_state ? "ON" : "OFF") != 0) {
        fprintf(stderr, "Failed to log relay state\n");
        return 1;
    }

    return 0;
}

// Log the relay state to a file
int log_relay_state(const char *state) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", buf, state);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Turn off the relay
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;

    // Log the final OFF state
    log_relay_state("OFF");

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    if (state.pigpio_initialized) {
        gpioTerminate();
    }

    exit(0);
}

