// Define GPIO pins for relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define moisture threshold
#define MOISTURE_THRESHOLD 30

// Define relay activation duration (seconds)
#define RELAY_DURATION 5

// Define delay between relay activations (seconds)
#define RELAY_DELAY 1

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_moisture();
int control_relay(int relay_number, int state);
int log_data(int relay_number, int moisture_level);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize all relays to inactive (HIGH)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0;
}

// Function to read simulated moisture level
int read_moisture() {
    return rand() % 101; // Returns a value between 0 and 100
}

// Function to control a relay
int control_relay(int relay_number, int state) {
    int pin;

    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return 1;
    }

    gpioWrite(pin, state);
    return 0;
}

// Function to log data to file
int log_data(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Relay %d, Moisture: %d\n", timestamp, relay_number, moisture_level);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Cleanup function
void cleanup() {
    // Deactivate all relays
    control_relay(1, 1);
    control_relay(2, 1);
    control_relay(3, 1);
    control_relay(4, 1);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read moisture level
        int moisture_level = read_moisture();
        printf("Moisture level: %d\n", moisture_level);

        // Check if irrigation is needed
        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Irrigation needed!\n");

            // Activate relays sequentially
            for (int i = 1; i <= 4; i++) {
                if (!running) break; // Check for signal during loop
                printf("Activating relay %d\n", i);
                if (control_relay(i, 0) != 0) {
                    fprintf(stderr, "Error controlling relay %d\n", i);
                }
                if (log_data(i, moisture_level) != 0) {
                    fprintf(stderr, "Error logging data for relay %d\n", i);
                }
                sleep(RELAY_DURATION);
                if (control_relay(i, 1) != 0) {
                    fprintf(stderr, "Error deactivating relay %d\n", i);
                }
                if (i < 4) {
                    sleep(RELAY_DELAY);
                }
            }
        }

        sleep(10);
    }

    // Cleanup and exit
    cleanup();
    printf("Smart Irrigation System stopped.\n");
    return 0;
}

