#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

// Define moisture levels
int moisture_levels[] = {20, 40, 60, 80, 100};
int moisture_index = 0;

// Define servo pulse widths (microseconds)
#define VALVE_OPEN_PULSE 1500
#define VALVE_CLOSED_PULSE 500
#define NOZZLE_0_PULSE 500
#define NOZZLE_45_PULSE 1000
#define NOZZLE_90_PULSE 1500
#define NOZZLE_135_PULSE 2000
#define NOZZLE_180_PULSE 2500

// Define watering parameters
#define VALVE_OPEN_TIME 2
#define NOZZLE_HOLD_TIME 5
#define VALVE_CLOSE_TIME 5
#define CYCLE_DELAY 5

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;

    // Stop servos
    gpioServo(VALVE_SERVO_PIN, 0);
    gpioServo(NOZZLE_SERVO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to set servo angle with retry and backoff
int set_servo_angle(int pin, int pulse_width) {
    int retries = 3;
    int delay_ms = 100;
    int result;

    while (retries > 0) {
        result = gpioServo(pin, pulse_width);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error setting servo angle (pin %d, pulse %d): %d. Retrying in %d ms...\n", pin, pulse_width, result, delay_ms);
            gpioDelay(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }

    fprintf(stderr, "Critical error: Failed to set servo angle (pin %d, pulse %d) after multiple retries.\n", pin, pulse_width);
    gpioTerminate();
    exit(1); // Unrecoverable error
}

// Function to open the valve
int open_valve() {
