#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Sensitivity scale factor for gyroscope (LSB/deg/s)
#define GYRO_SCALE 131.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_i2c();
int init_mpu6050();
gyro_data_t read_gyro_data();
char* format_data(gyro_data_t data, char* buffer);
int write_to_file(const char* data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Failed to read gyro data: %s\n", strerror(errno));
        data.x = 0.0; // Set to 0 to avoid using uninitialized data
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes, and convert to degrees per second
    int16_t gyro_x = (buf[0] << 8) | buf[1];
    int16_t gyro_y = (buf[2] << 8) | buf[3];
    int16_t gyro_z = (buf[4] << 8) | buf[5];

    data.x = (float)gyro_x / GYRO_SCALE;
    data.y = (float)gyro_y / GYRO_SCALE;
    data.z = (float)gyro_z / GYRO_SCALE;

    return data;
}

// Format data into CSV string
char* format_data(gyro_data_t data, char* buffer) {
    time_t rawtime;
    struct tm * timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, 80, "%Y-%m-%d %H:%M:%S", timeinfo);
    sprintf(buffer + strlen(buffer), ",%.2f,%.2f,%.2f\n", data.x, data.y, data.z);
    return buffer;
}

// Write data to file
int write_to_file(const char* data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s", data) < 0) {
        fprintf(stderr, "Failed to write to file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    gyro_data_t gyro_data;
    char data_buffer[100]; // Buffer to hold formatted data

    while (!terminate) {
        // Read gyroscope data
        gyro_data = read_gyro_data();

        // Format data
        format_data(gyro_data, data_buffer);

        // Write data to file
        if (write_to_file(data_buffer) < 0) {
            break; // Exit loop on write error
        }

        // Delay for 100ms (10 Hz sampling rate)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

