#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <wiringPi.h>

// Define GPIO pins (BCM numbering)
#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

// Define motor steps
const int steps[8] = {0b0001, 0b0011, 0b0010, 0b0110, 0b0100, 0b1100, 0b1000, 0b1001};

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Step delay in milliseconds
#define STEP_DELAY 3

// Number of steps for lock/unlock
#define NUM_STEPS 512

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
void step(int step_number);
void lock();
void unlock();
void cleanup();
void signal_handler(int signal);

// Function to perform a single step
void step(int step_number) {
    digitalWrite(IN1, (steps[step_number] & 0b0001) ? HIGH : LOW);
    digitalWrite(IN2, (steps[step_number] & 0b0010) ? HIGH : LOW);
    digitalWrite(IN3, (steps[step_number] & 0b0100) ? HIGH : LOW);
    digitalWrite(IN4, (steps[step_number] & 0b1000) ? HIGH : LOW);
    delay(STEP_DELAY);
}

// Function to lock the door (rotate clockwise)
void lock() {
    printf("Locking door...\n");
    for (int i = 0; i < NUM_STEPS; i++) {
        step(i % 8);
    }
    // De-energize coils
    digitalWrite(IN1, LOW);
    digitalWrite(IN2, LOW);
    digitalWrite(IN3, LOW);
    digitalWrite(IN4, LOW);
    printf("Door locked.\n");
}

// Function to unlock the door (rotate counter-clockwise)
void unlock() {
    printf("Unlocking door...\n");
    for (int i = 0; i < NUM_STEPS; i++) {
        step(7 - (i % 8)); // Reverse the step sequence
    }
    // De-energize coils
    digitalWrite(IN1, LOW);
    digitalWrite(IN2, LOW);
    digitalWrite(IN3, LOW);
    digitalWrite(IN4, LOW);
    printf("Door unlocked.\n");
}

// Function to de-energize all coils
void cleanup() {
    printf("Cleaning up and exiting...\n");
    digitalWrite(IN1, LOW);
    digitalWrite(IN2, LOW);
    digitalWrite(IN3, LOW);
    digitalWrite(IN4, LOW);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    cleanup();
    exit(0);
}

int main() {
    // Initialize wiringPi using BCM GPIO numbering
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi.\n");
        return 1;
    }

    // Set pin modes
    pinMode(IN1, OUTPUT);
    pinMode(IN2, OUTPUT);
    pinMode(IN3, OUTPUT);
    pinMode(IN4, OUTPUT);
    pinMode(LOCK_BUTTON, INPUT);
    pinMode(UNLOCK_BUTTON, INPUT);

    // Enable internal pull-up resistors
    pullUpDnControl(LOCK_BUTTON, PUD_UP);
    pullUpDnControl(UNLOCK_BUTTON, PUD_UP);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check for lock button press
        if (digitalRead(LOCK_BUTTON) == LOW) {
            lock();
            delay(DEBOUNCE_DELAY);
        }

        // Check for unlock button press
        if (digitalRead(UNLOCK_BUTTON) == LOW) {
            unlock();
            delay(DEBOUNCE_DELAY);
        }

        delay(10); // Small delay to prevent busy-waiting
    }

    return 0;
}

