#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50 ms timeout
#define TRIGGER_PULSE_US 10    // 10 us trigger pulse

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_pulse();
long long measure_pulse_width();
float calculate_distance(long long pulse_width);
void log_distance(float distance);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Initializes the pigpio library and sets up GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    return 0; // Indicate success
}

// Generates a 10 us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

// Measures the pulse width of the echo signal with timeout
long long measure_pulse_width() {
    long long start_tick, end_tick, pulse_width;

    // Wait for rising edge with timeout
    int timeout_counter = 0;
    while (gpioRead(ECHO_PIN) == 0) {
        start_tick = gpioTick();
        if (start_tick < 0) {
            fprintf(stderr, "Error reading start tick\n");
            return -1;
        }
        if (timeout_counter++ > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return -1;
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Wait for falling edge with timeout
    timeout_counter = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        end_tick = gpioTick();
        if (end_tick < 0) {
            fprintf(stderr, "Error reading end tick\n");
            return -1;
        }
        if (timeout_counter++ > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return -1;
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    pulse_width = end_tick - start_tick;
    return pulse_width;
}

// Calculates the distance in centimeters
float calculate_distance(long long pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Logs the distance to the file
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Cleans up GPIO and closes the log file
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Set up signal handling for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse();
        long long pulse_width = measure_pulse_width();

        if (pulse_width < 0) {
            fprintf(stderr, "Error: Timeout or error measuring pulse width.\n");
            log_distance(-1.0); // Log -1 for error
        } else {
            float distance = calculate_distance(pulse_width);
            log_distance(distance);
            printf("Distance: %.2f cm\n", distance);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Clean up and exit
    cleanup();
    return 0;
}

