#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_RELAY 18
#define DISTANCE_THRESHOLD 50 // cm
#define POLLING_INTERVAL_MS 100

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0049
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void control_relay(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
        terminate = 1;
    }
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Check if the sensor is present by reading a register
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading VL53L1X model ID: %s\n", strerror(errno));
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "VL53L1X sensor not found (Model ID: 0x%02X)\n", model_id);
        return -1;
    }

    fprintf(stderr, "VL53L1X sensor initialized successfully.\n");
    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    // Read the ranging measurement data ready status
    int data_ready = i2cReadByteData(i2c_handle, VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY);
    if (data_ready < 0) {
        fprintf(stderr, "Error reading data ready status: %s\n", strerror(errno));
        return -1;
    }

    if (data_ready & 0x01) {
        // Read the distance data (2 bytes)
        int range = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
        if (range < 0) {
            fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
            return -1;
        }

        // Convert mm to cm
        *distance = range / 10;
        return 0;
    } else {
        fprintf(stderr, "Distance data not ready yet.\n");
        return -1; // Data not ready
    }
}

// Control the relay based on distance
void control_relay(int distance) {
    if (distance <= DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_RELAY, 1); // HIGH
        fprintf(stderr, "Distance: %d cm, Relay: HIGH\n", distance);
    } else {
        gpioWrite(GPIO_RELAY, 0); // LOW
        fprintf(stderr, "Distance: %d cm, Relay: LOW\n", distance);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Initialize to LOW

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int distance;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            control_relay(distance);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(GPIO_RELAY, 0); // Set relay LOW before exiting
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

