#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the log file name
#define LOG_FILE "watering_log.txt"

// Define the watering cycle duration (in seconds)
#define WATERING_CYCLE_DURATION 86400 // 24 hours

// Define the watering duration for each relay (in seconds)
#define WATERING_DURATION 5

// Global variable to store the log file pointer
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void activate_relay(int pin);
void deactivate_relay(int pin);
void log_watering_event();
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set all relays to inactive (HIGH) initially
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0; // Indicate success
}

// Function to activate a relay (set GPIO pin LOW)
void activate_relay(int pin) {
    gpioWrite(pin, 0); // Activate relay (LOW)
    printf("Activating relay on pin %d\n", pin);
}

// Function to deactivate a relay (set GPIO pin HIGH)
void deactivate_relay(int pin) {
    gpioWrite(pin, 1); // Deactivate relay (HIGH)
    printf("Deactivating relay on pin %d\n", pin);
}

// Function to log the watering event to a file
void log_watering_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        perror("fopen");
        return;
    }

    fprintf(log_file, "%s\n", timestamp);
    fclose(log_file);
    printf("Watering event logged: %s\n", timestamp);
}

// Function to cleanup GPIO pins and terminate the pigpio library
void cleanup_gpio() {
    // Deactivate all relays
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    gpioTerminate();
    printf("pigpio terminated\n");
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Automated Plant Watering System started\n");

    // Main loop
    while (1) {
        // Log the watering event
        log_watering_event();

        // Activate relays sequentially
        activate_relay(RELAY1_PIN);
        gpioDelay(WATERING_DURATION * 1000); // Delay for 5 seconds
        deactivate_relay(RELAY1_PIN);

        activate_relay(RELAY2_PIN);
        gpioDelay(WATERING_DURATION * 1000); // Delay for 5 seconds
        deactivate_relay(RELAY2_PIN);

        activate_relay(RELAY3_PIN);
        gpioDelay(WATERING_DURATION * 1000); // Delay for 5 seconds
        deactivate_relay(RELAY3_PIN);

        activate_relay(RELAY4_PIN);
        gpioDelay(WATERING_DURATION * 1000); // Delay for 5 seconds
        deactivate_relay(RELAY4_PIN);

        // Wait for the remaining time in the watering cycle
        gpioDelay((WATERING_CYCLE_DURATION - 20) * 1000); // Delay for the remaining time (86400 - 20 seconds)
    }

    return 0;
}

