#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 17
#define RELAY2_GPIO 18
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Define sunrise duration
#define SUNRISE_DURATION 1800 // 30 minutes in seconds

// Define PWM range
#define PWM_RANGE 255

// Global variables
FILE *log_file;
int running = 1;

// Function prototypes
int initialize_gpio();
int set_gpio_mode(int gpio, int mode);
int set_pwm_frequency(int gpio, int frequency);
int set_pwm_range(int gpio, int range);
int set_pwm_dutycycle(int gpio, int dutycycle);
int log_event(const char *message);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }

    if (set_gpio_mode(RELAY1_GPIO, PI_OUTPUT) != 0) return -1;
    if (set_gpio_mode(RELAY2_GPIO, PI_OUTPUT) != 0) return -1;
    if (set_gpio_mode(RELAY3_GPIO, PI_OUTPUT) != 0) return -1;
    if (set_gpio_mode(RELAY4_GPIO, PI_OUTPUT) != 0) return -1;

    if (set_pwm_frequency(RELAY1_GPIO, PWM_FREQUENCY) != 0) return -1;
    if (set_pwm_frequency(RELAY2_GPIO, PWM_FREQUENCY) != 0) return -1;
    if (set_pwm_frequency(RELAY3_GPIO, PWM_FREQUENCY) != 0) return -1;
    if (set_pwm_frequency(RELAY4_GPIO, PWM_FREQUENCY) != 0) return -1;

    if (set_pwm_range(RELAY1_GPIO, PWM_RANGE) != 0) return -1;
    if (set_pwm_range(RELAY2_GPIO, PWM_RANGE) != 0) return -1;
    if (set_pwm_range(RELAY3_GPIO, PWM_RANGE) != 0) return -1;
    if (set_pwm_range(RELAY4_GPIO, PWM_RANGE) != 0) return -1;

    return 0;
}

// Function to set GPIO pin mode
int set_gpio_mode(int gpio, int mode) {
    int result = gpioSetMode(gpio, mode);
    if (result != 0) {
        char message[100];
        sprintf(message, "Failed to set GPIO %d mode: %d", gpio, result);
        log_event(message);
        return -1;
    }
    return 0;
}

// Function to set PWM frequency
int set_pwm_frequency(int gpio, int frequency) {
    int result = gpioSetPWMfrequency(gpio, frequency);
    if (result != 0) {
        char message[100];
        sprintf(message, "Failed to set PWM frequency for GPIO %d: %d", gpio, result);
        log_event(message);
        return -1;
    }
    return 0;
}

// Function to set PWM range
int set_pwm_range(int gpio, int range) {
    int result = gpioSetPWMrange(gpio, range);
    if (result != 0) {
        char message[100];
        sprintf(message, "Failed to set PWM range for GPIO %d: %d", gpio, result);
        log_event(message);
        return -1;
    }
    return 0;
}

// Function to set PWM duty cycle
int set_pwm_dutycycle(int gpio, int dutycycle) {
    int result = gpioPWM(gpio, dutycycle);
    if (result != 0) {
        char message[100];
        sprintf(message, "Failed to set PWM dutycycle for GPIO %d: %d", gpio, result);
        log_event(message);
        return -1;
    }
    return 0;
}

// Function to log events to a file
int log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
}

int main() {
    // Open log file
    log_file = fopen("smart_lighting.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting");
        fclose(log_file);
        return 1;
    }

    log_event("Smart lighting system started");

    // Sunrise effect
    for (int i = 0; i <= SUNRISE_DURATION && running; i++) {
        // Calculate duty cycle (0-255 over 30 minutes)
        int dutycycle = (int)(((float)i / SUNRISE_DURATION) * PWM_RANGE);

        // Set PWM duty cycle for each relay
        if (set_pwm_dutycycle(RELAY1_GPIO, dutycycle) != 0) break;
        if (set_pwm_dutycycle(RELAY2_GPIO, dutycycle) != 0) break;
        if (set_pwm_dutycycle(RELAY3_GPIO, dutycycle) != 0) break;
        if (set_pwm_dutycycle(RELAY4_GPIO, dutycycle) != 0) break;

        // Log the current duty cycle
        char message[100];
        sprintf(message, "Duty cycle: %d", dutycycle);
        log_event(message);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Turn off all relays
    set_pwm_dutycycle(RELAY1_GPIO, 0);
    set_pwm_dutycycle(RELAY2_GPIO, 0);
    set_pwm_dutycycle(RELAY3_GPIO, 0);
    set_pwm_dutycycle(RELAY4_GPIO, 0);

    log_event("Sunrise effect complete, turning off lights");

    // Clean up and exit
    gpioTerminate();
    fclose(log_file);
    return 0;
}

