#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// LED GPIO pin
#define LED_PIN 17

// Angular velocity threshold (deg/s)
#define ANGULAR_VELOCITY_THRESHOLD 250.0f

// Circular buffer size
#define BUFFER_SIZE 100

// Sampling rate (Hz)
#define SAMPLING_RATE 20

// Structure to hold gyroscope data
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t gyro_buffer;
bool running = true;

// Function prototypes
int init_i2c();
int read_gyro_data(float *x, float *y, float *z);
void control_led(float x, float y, float z);
void add_to_buffer(circular_buffer_t *buffer, struct timespec timestamp, float x, float y, float z);
void signal_handler(int signal);

// Initialize the circular buffer
void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read gyroscope data from the MPU-6050
int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    raw_x = (buf[0] << 8) | buf[1];
    raw_y = (buf[2] << 8) | buf[3];
    raw_z = (buf[4] << 8) | buf[5];

    // Convert raw data to degrees per second (dps)
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;

    return 0;
}

// Control the LED based on angular velocity
void control_led(float x, float y, float z) {
    if (fabs(x) > ANGULAR_VELOCITY_THRESHOLD ||
        fabs(y) > ANGULAR_VELOCITY_THRESHOLD ||
        fabs(z) > ANGULAR_VELOCITY_THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, struct timespec timestamp, float x, float y, float z) {
    buffer->data[buffer->head].timestamp = timestamp;
    buffer->data[buffer->head].x = x;
    buffer->data[buffer->head].y = y;
    buffer->data[buffer->head].z = z;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

