    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&gyro_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;
    struct timespec ts;

    // Main loop
    while (running) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Get timestamp
            clock_gettime(CLOCK_REALTIME, &ts);

            // Add data to circular buffer
            add_to_buffer(&gyro_buffer, ts, x, y, z);

            // Control LED
            control_led(x, y, z);
