        // Sleep for 50ms (20Hz sampling rate)
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

