#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN 8
#define SPI_SPEED 1000000 // 1 MHz
#define GYRO_SENSITIVITY 131.0f // LSB/deg/s for +/- 250 deg/s range
#define LOG_FILE "gyro_log.txt"
#define SAMPLE_INTERVAL_NS 10000000 // 10 ms

// MPU-9250 Registers
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_gyro_data(int fd, float *x_rate, float *y_rate, float *z_rate);
int log_data(FILE *fp, struct timespec ts, float x_rate, float y_rate, float z_rate);
void signal_handler(int sig);
int setup_gpio(void);
int cleanup(void);

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

// Read gyroscope data function
int read_gyro_data(int fd, float *x_rate, float *y_rate, float *z_rate) {
    uint8_t tx_buf[7];
    uint8_t rx_buf[7];
    int16_t raw_x, raw_y, raw_z;

    // Set chip select low
    if (gpiod_line_set_value(gpio_line, 0) < 0) {
        perror("Failed to set GPIO low");
        return -1;
    }

    // Read X, Y, and Z data
    tx_buf[0] = GYRO_XOUT_H | 0x80; // Read multiple bytes starting from GYRO_XOUT_H
    if (spi_transfer(fd, tx_buf, rx_buf, 7) < 0) {
        fprintf(stderr, "SPI transfer error during gyro read\n");
        // Set chip select high
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            perror("Failed to set GPIO high");
            return -1;
        }
        return -1;
    }

    // Set chip select high
    if (gpiod_line_set_value(gpio_line, 1) < 0) {
        perror("Failed to set GPIO high");
        return -1;
    }

    raw_x = (rx_buf[1] << 8) | rx_buf[2];
    raw_y = (rx_buf[3] << 8) | rx_buf[4];
    raw_z = (rx_buf[5] << 8) | rx_buf[6];

    *x_rate = (float)raw_x / GYRO_SENSITIVITY;
    *y_rate = (float)raw_y / GYRO_SENSITIVITY;
    *z_rate = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Log data to file function
int log_data(FILE *fp, struct timespec ts, float x_rate, float y_rate, float z_rate) {
    char timestamp[30];
    struct tm tm_info;

    // Format timestamp
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);

    // Write to file
    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x_rate, y_rate, z_rate) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Setup GPIO function
int setup_gpio(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "gyro_reader", 1) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Set initial value to high (inactive)
    if (gpiod_line_set_value(gpio_line, 1) < 0) {
        perror("Failed to set initial GPIO value");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Cleanup function
int cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    return 0;
}

int main(void) {
    struct timespec ts;
    float x_rate, y_rate, z_rate;
    int retries;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed, exiting\n");
        return EXIT_FAILURE;
    }

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < 3) {
            if (read_gyro_data(spi_fd, &x_rate, &y_rate, &z_rate) == 0) {
                if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                    if (log_data(log_file, ts, x_rate, y_rate, z_rate) != 0) {
                        fprintf(stderr, "Failed to log data\n");
                    }
                } else {
                    perror("Failed to get timestamp");
                }
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Gyro read failed, retry %d\n", retries + 1);
                retries++;
                usleep(1000); // Wait before retrying
            }
        }

        if (retries == 3) {
            fprintf(stderr, "Gyro read failed after 3 retries\n");
        }

        nanosleep(&(struct timespec){0, SAMPLE_INTERVAL_NS}, NULL);
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Exiting cleanly\n");
    return EXIT_SUCCESS;
}

