#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x60
#define LED_GPIO 17
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define READ_DELAY_MS 100

// Si1145 Registers
#define REG_ALS_VIS_DATA0 0x22
#define REG_PS1_DATA0 0x24

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_register(int fd, unsigned char reg);
int i2c_write_register(int fd, unsigned char reg, unsigned char value);
int read_sensor_data(int fd, unsigned int *ambient_light, unsigned int *proximity);
void log_data(FILE *fp, unsigned int ambient_light, unsigned int proximity);
void control_led(int gpio_pin, int state);
void signal_handler(int signal);
int initialize();
void cleanup();

// I2C read register function
int i2c_read_register(int fd, unsigned char reg) {
    int result;
    unsigned char buf[1];

    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }

    result = buf[0];
    return result;
}

// I2C write register function
int i2c_write_register(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register");
        return -1;
    }
    return 0;
}

// Read sensor data function
int read_sensor_data(int fd, unsigned int *ambient_light, unsigned int *proximity) {
    int retry;
    int als_low, als_high, prox_low, prox_high;

    for (retry = 0; retry < RETRY_COUNT; retry++) {
        als_low = i2c_read_register(fd, REG_ALS_VIS_DATA0);
        if (als_low < 0) {
            fprintf(stderr, "Error reading ALS_VIS_DATA0, retry %d\n", retry + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        als_high = i2c_read_register(fd, REG_ALS_VIS_DATA0 + 1);
        if (als_high < 0) {
            fprintf(stderr, "Error reading ALS_VIS_DATA0 + 1, retry %d\n", retry + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

