#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define ADXRS290 register addresses
#define ADXRS290_REG_X_RATE 0x08  // X-axis rate register
#define ADXRS290_REG_Y_RATE 0x0A  // Y-axis rate register
#define ADXRS290_REG_TEMP   0x0C  // Temperature register
#define ADXRS290_REG_DIAG   0x0E  // Diagnostic register
#define ADXRS290_REG_GLOB_CMD 0x00 // Global command register
#define ADXRS290_REG_GLOB_STAT 0x02 // Global status register

// Define ADXRS290 commands
#define ADXRS290_CMD_RESET 0x80

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0 // Mode 0 (CPOL=0, CPHA=0)

// Define sampling rate and delay
#define SAMPLE_RATE 100 // Hz
#define SAMPLE_DELAY 10000 // 10 ms in microseconds

// Define retry parameters
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// Function prototypes
int spi_init();
int spi_read_register(uint8_t reg_addr, uint8_t *data);
int spi_write_register(uint8_t reg_addr, uint8_t data);
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// SPI initialization function
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// SPI read register function
int spi_read_register(uint8_t reg_addr, uint8_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr | 0x80; // Set read bit (MSB)
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error during SPI read\n");
        return -1;
    }

    *data = rx_buf[1];
    return 0;
}

// SPI write register function
int spi_write_register(uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr & 0x7F; // Clear read bit (MSB)
    tx_buf[1] = data;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error during SPI write\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    uint8_t x_rate_msb, x_rate_lsb, y_rate_msb, y_rate_lsb;

    if (spi_read_register(ADXRS290_REG_X_RATE, &x_rate_msb) != 0) {
        fprintf(stderr, "Error reading X rate MSB\n");
        data.x_rate = 0; // Set to 0 on error
    } else if (spi_read_register(ADXRS290_REG_X_RATE + 1, &x_rate_lsb) != 0) {
        fprintf(stderr, "Error reading X rate LSB\n");
        data.x_rate = 0; // Set to 0 on error
    } else {
        data.x_rate = (int16_t)((x_rate_msb << 8) | x_rate_lsb);
    }

    if (spi_read_register(ADXRS290_REG_Y_RATE, &y_rate_msb) != 0) {
        fprintf(stderr, "Error reading Y rate MSB\n");
        data.y_rate = 0; // Set to 0 on error
    } else if (spi_read_register(ADXRS290_REG_Y_RATE + 1, &y_rate_lsb) != 0) {
        fprintf(stderr, "Error reading Y rate LSB\n");
        data.y_rate = 0; // Set to 0 on error
    } else {
        data.y_rate = (int16_t)((y_rate_msb << 8) | y_rate_lsb);
    }

    return data;
}

// Function to log data to file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp = (long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000; // Microseconds

    fprintf(fp, "%ld,%d,%d\n", timestamp, data.x_rate, data.y_rate);
    fflush(fp); // Ensure data is written to disk immediately
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI with retry logic
    int spi_init_attempts = 0;
    while (spi_init_attempts < MAX_RETRIES) {
        if (spi_init() == 0) {
            break; // SPI initialized successfully
        } else {
            fprintf(stderr, "SPI initialization failed, retrying... (%d/%d)\n", spi_init_attempts + 1, MAX_RETRIES);
            spi_init_attempts++;
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }

    if (spi_handle < 0) {
        fprintf(stderr, "Failed to initialize SPI after %d retries. Exiting.\n", MAX_RETRIES);
        cleanup();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write CSV header
    fprintf(fp, "timestamp,x_rate,y_rate\n");

    // Main loop
    while (!terminate) {
        gyro_data_t data = read_gyro_data();
        log_data(data);
        gpioDelay(SAMPLE_DELAY); // Delay for 10 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

