#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>
#include <math.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define LED_GPIO 17
#define THRESHOLD 20.0
#define BUFFER_SIZE 100

// Define ADXRS290 register addresses
#define ADXRS290_REG_X_RATE 0x08 // Example address, check datasheet

// Structure to hold gyroscope data and timestamp
typedef struct {
    int16_t rate;
    struct timespec timestamp;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global variables
int spi_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_spi();
int read_gyro_data(int16_t *rate);
void add_to_buffer(circular_buffer_t *buffer, int16_t rate, struct timespec timestamp);
int check_threshold(int16_t rate);
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, int16_t rate, struct timespec timestamp) {
    buffer->buffer[buffer->head].rate = rate;
    buffer->buffer[buffer->head].timestamp = timestamp;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from the gyroscope
int read_gyro_data(int16_t *rate) {
    char tx_buffer[2];
    char rx_buffer[2];

    // Set MSB of register address for read
    tx_buffer[0] = ADXRS290_REG_X_RATE | 0x80; // Example address, check datasheet
    tx_buffer[1] = 0x00; // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 2) != 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit rate value
    *rate = (int16_t)((rx_buffer[0] << 8) | rx_buffer[1]);

    return 0;
}

// Check if the rate exceeds the threshold
int check_threshold(int16_t rate) {
    return (fabs(rate) > THRESHOLD) ? 1 : 0;
}

// Control the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&gyro_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t rate;
    struct timespec ts;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&rate) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
                // Add data to buffer
                add_to_buffer(&gyro_buffer, rate, ts);

                // Check threshold and control LED
                if (check_threshold(rate)) {
                    control_led(1); // Turn on LED
                } else {
                    control_led(0); // Turn off LED
                }
            } else {
                fprintf(stderr, "Error getting timestamp\n");
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data\n");
        }

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

