#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define PWM range
#define PWM_RANGE 255

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, shutting down gracefully...\n", signal);
}

// Function to fade a lamp from full brightness to off
void fade_lamp(int gpio, int duration) {
    int i;
    float decrement = (float)PWM_RANGE / duration;
    for (i = 0; i < duration && program_running; i++) {
        int duty_cycle = PWM_RANGE - (int)(decrement * i);
        if (duty_cycle < 0) duty_cycle = 0; // Ensure duty cycle doesn't go negative
        gpioPWM(gpio, duty_cycle);
        gpioDelay(1000000 / PWM_FREQUENCY); // Delay for 1/PWM_FREQUENCY seconds
    }
    gpioPWM(gpio, 0); // Ensure lamp is off after fade
}

int main(int argc, char *argv[]) {
    int total_duration;

    // Check for command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_duration_in_seconds>\n", argv[0]);
        return 1;
    }

    // Parse the total duration from the command-line argument
    total_duration = atoi(argv[1]);

    // Validate the total duration
    if (total_duration < 1 || total_duration > 3600) {
        fprintf(stderr, "Error: Total duration must be between 1 and 3600 seconds.\n");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency and range for each lamp
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sunset simulator started. Total duration: %d seconds\n", total_duration);

    // Calculate fade duration for each lamp
    int fade_duration = total_duration / 3;

    // Fade lamp 1
    printf("Fading lamp 1 for %d seconds...\n", fade_duration);
    fade_lamp(LAMP1_GPIO, fade_duration);

    // Fade lamp 2
    printf("Fading lamp 2 for %d seconds...\n", fade_duration);
    fade_lamp(LAMP2_GPIO, fade_duration);

    // Fade lamp 3
    printf("Fading lamp 3 for %d seconds...\n", fade_duration);
    fade_lamp(LAMP3_GPIO, fade_duration);

    printf("Sunset simulation complete.\n");

    // Turn off all lamps
    gpioPWM(LAMP1_GPIO, 0);
    gpioPWM(LAMP2_GPIO, 0);
    gpioPWM(LAMP3_GPIO, 0);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

