#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays (BCM numbering)
#define RED1_PIN   17
#define RED2_PIN   22
#define GREEN_PIN  23
#define YELLOW_PIN 24

// Define the duration of each state in seconds
#define RED_DURATION   10
#define YELLOW_DURATION 2
#define GREEN_DURATION  10
#define YELLOW2_DURATION 3

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a relay (active low)
int set_relay_state(int pin, int state) {
    int result = gpioWrite(pin, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", pin, result);
        return -1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to turn on a relay (active low)
int turn_on_relay(int pin) {
    return set_relay_state(pin, 0); // LOW to turn on
}

// Function to turn off a relay (active low)
int turn_off_relay(int pin) {
    return set_relay_state(pin, 1); // HIGH to turn off
}

// Function to set the traffic light state
int set_traffic_light_state(int red1_state, int red2_state, int green_state, int yellow_state) {
    if (turn_on_relay(RED1_PIN) != 0) return -1;
