#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define GPIO_RELAY 17
#define DEBOUNCE_DELAY_MS 100
#define RELAY_TOGGLE_DELAY_MS 500
#define NUM_ELECTRODES 12

// Global variables
int i2c_handle;
FILE *log_file;
bool running = true;

// Function prototypes
int init_mpr121();
int read_touch_status(uint16_t *touch_status);
bool debounce_touch(uint16_t current_status, uint16_t *last_status, uint32_t *last_change_time);
void toggle_relay();
void log_message(const char *message);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    uint16_t last_touch_status;
    uint32_t last_touch_change_time;
    bool relay_state;
} ProgramState;

ProgramState state = {0, 0, false};

// Function to initialize the MPR121
int init_mpr121() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x00) < 0) {
        log_message("Error: Failed to set MPR121 to stop mode.");
        return -1;
    }

    // Electrode configuration
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) {
        log_message("Error: Failed to set electrode configuration.");
        return -1;
    }

    // Touch and release thresholds
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x30) < 0) { // Touch threshold
            log_message("Error: Failed to set touch threshold for electrode.");
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x10) < 0) { // Release threshold
            log_message("Error: Failed to set release threshold for electrode.");
            return -1;
        }
    }

    // Debounce configuration
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) {
        log_message("Error: Failed to set debounce configuration.");
        return -1;
    }

    // Start mode
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) {
        log_message("Error: Failed to set MPR121 to start mode.");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        log_message("Error: Failed to read touch status.");
        return -1;
    }

    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Function to debounce touch events
bool debounce_touch(uint16_t current_status, uint16_t *last_status, uint32_t *last_change_time) {
    uint32_t now = gpioTick();
    if (current_status != *last_status) {
        if ((now - *last_change_time) > DEBOUNCE_DELAY_MS * 1000) {
            *last_status = current_status;
            *last_change_time = now;
            return true; // Valid touch event
        }
    }
    return false; // Not a valid touch event
}

// Function to toggle the relay
void toggle_relay() {
    state.relay_state = !state.relay_state;
    gpioWrite(GPIO_RELAY, state.relay_state);
    log_message("Relay toggled.");
    gpioDelay(RELAY_TOGGLE_DELAY_MS * 1000); // Delay to prevent rapid toggling
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = false;
    log_message("Signal received, shutting down...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Error: Failed to open I2C bus.");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() < 0) {
        log_message("Error: Failed to initialize MPR121.");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Initialize to LOW
    log_message("GPIO17 initialized as output and set to LOW.");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        uint16_t touch_status;
        if (read_touch_status(&touch_status) == 0) {
            if (debounce_touch(touch_status, &state.last_touch_status, &state.last_touch_change_time)) {
                if (touch_status & (1 << 0)) { // Electrode 0 touched
                    toggle_relay();
                }
            }
        } else {
            log_message("Error reading touch status, retrying...");
        }
        gpioDelay(10 * 1000); // 10ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_RELAY, 0); // Set GPIO to LOW before exiting
    gpioTerminate();
    fclose(log_file);

    return 0;
}

