#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_1 17
#define FLAME_SENSOR_2 22
#define FLAME_SENSOR_3 27
#define BUZZER 18
#define LED 23

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_flame_sensor(int gpio);
int log_flame_detection(const char *timestamp);
int activate_buzzer(int gpio);
int activate_led(int gpio);
int deactivate_buzzer(int gpio);
int deactivate_led(int gpio);
void signal_handler(int signal);

// Function to read the flame sensor
int read_flame_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate error
    }
    return (value == 0) ? 1 : 0; // Active low
}

// Function to log flame detection
int log_flame_detection(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
    if (fprintf(log_file, "%s Flame Detected\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to activate the buzzer
int activate_buzzer(int gpio) {
    int result = gpioWrite(gpio, 1);
    if (result != 0) {
        fprintf(stderr, "Error activating buzzer (GPIO %d): %d\n", gpio, result);
        return -1;
    }
    return 0;
}

// Function to activate the LED
int activate_led(int gpio) {
    int result = gpioWrite(gpio, 1);
    if (result != 0) {
        fprintf(stderr, "Error activating LED (GPIO %d): %d\n", gpio, result);
        return -1;
    }
    return 0;
}

// Function to deactivate the buzzer
int deactivate_buzzer(int gpio) {
    int result = gpioWrite(gpio, 0);
    if (result != 0) {
        fprintf(stderr, "Error deactivating buzzer (GPIO %d): %d\n", gpio, result);
        return -1;
    }
    return 0;
}

// Function to deactivate the LED
int deactivate_led(int gpio) {
    int result = gpioWrite(gpio, 0);
    if (result != 0) {
        fprintf(stderr, "Error deactivating LED (GPIO %d): %d\n", gpio, result);
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_1, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_2, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_3, PI_INPUT);
    gpioSetMode(BUZZER, PI_OUTPUT);
    gpioSetMode(LED, PI_OUTPUT);

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read flame sensors
        int sensor1_low = read_flame_sensor(FLAME_SENSOR_1);
        int sensor2_low = read_flame_sensor(FLAME_SENSOR_2);
        int sensor3_low = read_flame_sensor(FLAME_SENSOR_3);

        if (sensor1_low < 0 || sensor2_low < 0 || sensor3_low < 0) {
            fprintf(stderr, "Error reading flame sensors. Exiting.\n");
            break;
        }

        // Check for flame detection
        if (sensor1_low && sensor2_low && sensor3_low) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log flame detection
            if (log_flame_detection(timestamp) != 0) {
                fprintf(stderr, "Error logging flame detection. Exiting.\n");
                break;
            }

            // Activate buzzer and LED
            if (activate_buzzer(BUZZER) != 0 || activate_led(LED) != 0) {
                fprintf(stderr, "Error activating buzzer/LED. Exiting.\n");
                break;
            }

            // Wait for flame to clear
            while (sensor1_low && sensor2_low && sensor3_low && running) {
