// Function to read the flame sensor
int read_flame_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate error
    }
    return (value == 0) ? 1 : 0; // Active low
}

// Function to log flame detection
int log_flame_detection(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
    if (fprintf(log_file, "%s Flame Detected\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to activate the buzzer
int activate_buzzer(int gpio) {
    int result = gpioWrite(gpio, 1);
    if (result != 0) {
        fprintf(stderr, "Error activating buzzer (GPIO %d): %d\n", gpio, result);
        return -1;
    }
    return 0;
}

// Function to activate the LED
int activate_led(int gpio) {
    int result = gpioWrite(gpio, 1);
    if (result != 0) {
        fprintf(stderr, "Error activating LED (GPIO %d): %d\n", gpio, result);
        return -1;
    }
    return 0;
}

