// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define dispense duration and interval
#define DISPENSE_DURATION_MS 1000
#define DISPENSE_INTERVAL_S 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int dispense(int solenoid_pin, int duration_ms);
int log_dispense(int solenoid_pin, int duration_ms);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Cleaning up and exiting.\n");
        program_running = 0;
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    return 0;
}

// Function to dispense using a solenoid
int dispense(int solenoid_pin, int duration_ms) {
    gpioWrite(solenoid_pin, 1); // Activate solenoid
    gpioDelay(duration_ms * 1000); // Delay for specified duration (microseconds)
    gpioWrite(solenoid_pin, 0); // Deactivate solenoid
    return 0;
}

// Function to log dispense events to a file
int log_dispense(int solenoid_pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Solenoid: %d, Duration: %d ms\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            solenoid_pin, duration_ms);

    fclose(fp);
    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(SOLENOID_1_PIN, 0); // Ensure solenoid 1 is off
    gpioWrite(SOLENOID_2_PIN, 0); // Ensure solenoid 2 is off
    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Dispensing system started. Press Ctrl+C to exit.\n");

    // Main dispensing loop
    while (program_running) {
        // Dispense with solenoid 1
        if (dispense(SOLENOID_1_PIN, DISPENSE_DURATION_MS / 2) != 0) {
            fprintf(stderr, "Error during solenoid 1 dispense.\n");
        }
        if (log_dispense(SOLENOID_1_PIN, DISPENSE_DURATION_MS / 2) != 0) {
            fprintf(stderr, "Error logging solenoid 1 dispense.\n");
        }

        // Dispense with solenoid 2
        if (dispense(SOLENOID_2_PIN, DISPENSE_DURATION_MS / 2) != 0) {
            fprintf(stderr, "Error during solenoid 2 dispense.\n");
        }
        if (log_dispense(SOLENOID_2_PIN, DISPENSE_DURATION_MS / 2) != 0) {
            fprintf(stderr, "Error logging solenoid 2 dispense.\n");
        }

        // Wait for the next dispense interval
        gpioDelay(DISPENSE_INTERVAL_S * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

