#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define ENA 24

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENB 25

// PID Gains
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Obstacle Avoidance Threshold
#define OBSTACLE_THRESHOLD 20.0

// PWM Frequency
#define PWM_FREQUENCY 1000

// PWM Range
#define PWM_RANGE 255

// Log File Name
#define LOG_FILE "balance_log.txt"

// Global Variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// PID Variables
double integral = 0.0;
double previous_error = 0.0;

// Function Prototypes
void signal_handler(int signal);
int initialize_gpio();
void set_motor_speed(int motor_a_speed, int motor_b_speed);
double calculate_pid(double tilt_error, double distance);
double simulate_tilt_error();
double simulate_distance();
void log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed);
void stop_motors();

// Signal Handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Stopping motors and exiting.\n");
        program_running = 0;
        stop_motors();
        if (log_file != NULL) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(0);
    }
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(ENB, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(ENA, PWM_RANGE);
    gpioSetPWMrange(ENB, PWM_RANGE);

    // Enable motors
    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    return 0;
}

// Set Motor Speed
void set_motor_speed(int motor_a_speed, int motor_b_speed) {
    // Clamp motor speeds
    if (motor_a_speed > PWM_RANGE) motor_a_speed = PWM_RANGE;
    if (motor_a_speed < -PWM_RANGE) motor_a_speed = -PWM_RANGE;
    if (motor_b_speed > PWM_RANGE) motor_b_speed = PWM_RANGE;
    if (motor_b_speed < -PWM_RANGE) motor_b_speed = -PWM_RANGE;

    // Motor A
    if (motor_a_speed > 0) {
        gpioWrite(MOTOR_A_FORWARD, 1);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(ENA, motor_a_speed);
    } else if (motor_a_speed < 0) {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 1);
        gpioPWM(ENA, abs(motor_a_speed));
    } else {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(ENA, 0);
    }

    // Motor B
    if (motor_b_speed > 0) {
        gpioWrite(MOTOR_B_FORWARD, 1);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(ENB, motor_b_speed);
    } else if (motor_b_speed < 0) {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 1);
        gpioPWM(ENB, abs(motor_b_speed));
    } else {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(ENB, 0);
    }
}

// Calculate PID
double calculate_pid(double tilt_error, double distance) {
    double proportional = Kp * tilt_error;
    integral += Ki * tilt_error;
    double derivative = Kd * (tilt_error - previous_error);
    double output = proportional + integral + derivative;

    previous_error = tilt_error;

    // Obstacle avoidance
    if (distance < OBSTACLE_THRESHOLD) {
        return -50.0; // Reverse both motors at 50% speed
    }

    return output;
}

// Simulate Tilt Error
double simulate_tilt_error() {
    return ((double)rand() / RAND_MAX) * 20.0 - 10.0; // Random float between -10.0 and 10.0
}

// Simulate Distance
double simulate_distance() {
    return ((double)rand() / RAND_MAX) * 398.0 + 2.0; // Random float between 2.0 and 400.0
}

// Log Data
void log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Stop Motors
void stop_motors() {
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
    gpioPWM(ENA, 0);
    gpioPWM(ENB, 0);
}

int main() {
    // Seed random number generator
    srand(time(NULL));

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        stop_motors();
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Simulate sensor data
        double tilt_error = simulate_tilt_error();
        double distance = simulate_distance();

        // Calculate PID output
        double pid_output = calculate_pid(tilt_error, distance);

        // Set motor speeds
        int motor_a_speed = (int)pid_output;
        int motor_b_speed = (int)pid_output;

        set_motor_speed(motor_a_speed, motor_b_speed);

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Wait 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    // Clean up
    stop_motors();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

