#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track relay state
static volatile int relay_state = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int toggle_relay();
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input with pull-down resistor
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO%d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read touch sensor value
int read_touch_sensor() {
    int value = gpioRead(TOUCH_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO%d\n", TOUCH_SENSOR_PIN);
        return -1; // Indicate error
    }
    return value;
}

// Toggle relay state
int toggle_relay() {
    relay_state = !relay_state;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", RELAY_PIN);
        return 1;
    }
    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int touch_value = read_touch_sensor();
        if (touch_value == 1) {
            printf("Touch detected!\n");
            if (toggle_relay() != 0) {
                fprintf(stderr, "Failed to toggle relay\n");
            }
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        } else if (touch_value < 0) {
            fprintf(stderr, "Error reading touch sensor, exiting...\n");
            cleanup_gpio();
            return 1;
        }
        gpioDelay(1000); // Small delay to prevent busy-waiting
    }

    return 0;
}

