#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>

// ALSA includes
#ifdef ALSA_AVAILABLE
#include <alsa/asoundlib.h>
#endif

// pigpio includes
#include <pigpio.h>

// Configuration
#define SAMPLE_RATE 8000
#define NUM_CHANNELS 1
#define SAMPLE_SIZE 16 // bits
#define PERIOD_SIZE 1024
#define LED_RED_GPIO 17
#define LED_GREEN_GPIO 18
#define LED_BLUE_GPIO 27
#define PWM_RANGE 255
#define PWM_FREQUENCY 1000 // Hz
#define SENSITIVITY_DEFAULT 1.0
#define SINE_WAVE_FREQUENCY 440.0 // Hz

// Global variables (minimize usage)
static volatile int running = 1;
static snd_pcm_t *pcm_handle = NULL;
static double sensitivity = SENSITIVITY_DEFAULT;
static double sine_wave_phase = 0.0;

// Function prototypes
double calculate_rms(const short *buffer, int buffer_size);
void map_amplitude_to_color(double amplitude, double sensitivity, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);
#ifdef ALSA_AVAILABLE
int capture_audio(short *buffer, int buffer_size);
#else
double simulate_audio();
#endif

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Cleaning up and exiting.\n", signal);
    running = 0;
}

// Calculate RMS amplitude
double calculate_rms(const short *buffer, int buffer_size) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum_of_squares += (double)buffer[i] * buffer[i];
    }
    return sqrt(sum_of_squares / buffer_size);
}

// Map amplitude to RGB color (non-linear mapping)
void map_amplitude_to_color(double amplitude, double sensitivity, int *red, int *green, int *blue) {
    // Scale amplitude by sensitivity
    amplitude *= sensitivity;

    // Non-linear mapping (example: logarithmic)
    double scaled_amplitude = log10(1 + amplitude) / log10(1 + 1000); // Scale to 0-1 range

    // Map to RGB color space (example: HSL to RGB)
    double hue = scaled_amplitude * 360.0; // Hue from 0 to 360
    double saturation = 1.0; // Full saturation
    double lightness = 0.5; // Medium lightness

    double C = saturation * lightness * (lightness < 0.5 ? 1 : 1 - lightness);
    double H = hue / 60.0;
    double X = C * (1 - fabs(fmod(H, 2) - 1));

    double r_prime, g_prime, b_prime;
    if (H < 1) {
        r_prime = C; g_prime = X; b_prime = 0;
    } else if (H < 2) {
        r_prime = X; g_prime = C; b_prime = 0;
    } else if (H < 3) {
        r_prime = 0; g_prime = C; b_prime = X;
    } else if (H < 4) {
        r_prime = 0; g_prime = X; b_prime = C;
    } else if (H < 5) {
        r_prime = X; g_prime = 0; b_prime = C;
    } else {
        r_prime = C; g_prime = 0; b_prime = X;
    }

    double m = lightness - C / 2.0;
    *red = (int)((r_prime + m) * PWM_RANGE);
    *green = (int)((g_prime + m) * PWM_RANGE);
    *blue = (int)((b_prime + m) * PWM_RANGE);

    // Clamp values to 0-255 range
    *red = (*red > PWM_RANGE) ? PWM_RANGE : (*red < 0) ? 0 : *red;
    *green = (*green > PWM_RANGE) ? PWM_RANGE : (*green < 0) ? 0 : *green;
    *blue = (*blue > PWM_RANGE) ? PWM_RANGE : (*blue < 0) ? 0 : *blue;
}

// Set LED color using software PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(LED_RED_GPIO, red);
    gpioPWM(LED_GREEN_GPIO, green);
    gpioPWM(LED_BLUE_GPIO, blue);
}

#ifdef ALSA_AVAILABLE
// Capture audio from ALSA
int capture_audio(short *buffer, int buffer_size) {
    int rc = snd_pcm_readi(pcm_handle, buffer, buffer_size);
    if (rc == -EPIPE) {
        /* EPIPE means overrun */
        fprintf(stderr, "overrun occurred\n");
        snd_pcm_prepare(pcm_handle);
    } else if (rc < 0) {
        fprintf(stderr, "error from read: %s\n", snd_strerror(rc));
        return -1;
    } else if (rc != buffer_size) {
        fprintf(stderr, "short read, read %d frames\n", rc);
    }
    return 0;
}
#else
// Simulate audio input with a sine wave
double simulate_audio() {
    double amplitude = 1000.0 * sin(2 * M_PI * SINE_WAVE_FREQUENCY * (double)time(NULL) / SAMPLE_RATE);
    sine_wave_phase += 2 * M_PI * SINE_WAVE_FREQUENCY / SAMPLE_RATE;
    if (sine_wave_phase > 2 * M_PI) {
        sine_wave_phase -= 2 * M_PI;
    }
    return amplitude;
}
#endif

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        sensitivity = strtod(argv[1], &endptr);
        if (*endptr != '\0' || sensitivity <= 0.0) {
            fprintf(stderr, "Invalid sensitivity value. Using default: %f\n", SENSITIVITY_DEFAULT);
            sensitivity = SENSITIVITY_DEFAULT;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for PWM
    gpioSetMode(LED_RED_GPIO, PI_OUTPUT);
    gpioSetMode(LED_GREEN_GPIO, PI_OUTPUT);
    gpioSetMode(LED_BLUE_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(LED_RED_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LED_GREEN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LED_BLUE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_RED_GPIO, PWM_RANGE);
    gpioSetPWMrange(LED_GREEN_GPIO, PWM_RANGE);
    gpioSetPWMrange(LED_BLUE_GPIO, PWM_RANGE);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

#ifdef ALSA_AVAILABLE
    // Initialize ALSA
    int rc = snd_pcm_open(&pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (rc < 0) {
        fprintf(stderr, "cannot open audio device default (%s)\n", snd_strerror(rc));
        gpioTerminate();
        return 1;
    }

    snd_pcm_hw_params_t *hw_params;
    snd_pcm_hw_params_alloca(&hw_params);

    rc = snd_pcm_hw_params_any(pcm_handle, hw_params);
    if (rc < 0) {
        fprintf(stderr, "cannot initialize hardware parameter structure (%s)\n", snd_strerror(rc));
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    rc = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (rc < 0) {
        fprintf(stderr, "cannot set access type (%s)\n", snd_strerror(rc));
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    rc = snd_pcm_hw_params_set_format(pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE);
    if (rc < 0) {
        fprintf(stderr, "cannot set sample format (%s)\n", snd_strerror(rc));
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    rc = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, NUM_CHANNELS);
    if (rc < 0) {
        fprintf(stderr, "cannot set channel count (%s)\n", snd_strerror(rc));
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    unsigned int val = SAMPLE_RATE;
    int dir = 0;
    rc = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &val, &dir);
    if (rc < 0) {
        fprintf(stderr, "cannot set sample rate (%s)\n", snd_strerror(rc));
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    rc = snd_pcm_hw_params_set_period_size(pcm_handle, hw_params, PERIOD_SIZE, 0);
    if (rc < 0) {
        fprintf(stderr, "cannot set period size (%s)\n", snd_strerror(rc));
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    rc = snd_pcm_hw_params(pcm_handle, hw_params);
    if (rc < 0) {
        fprintf(stderr, "cannot set parameters (%s)\n", snd_strerror(rc));
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    snd_pcm_prepare(pcm_handle);

    short *buffer = (short *)malloc(PERIOD_SIZE * sizeof(short));
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate audio buffer\n");
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    int red, green, blue;
    while (running) {
        if (capture_audio(buffer, PERIOD_SIZE) == 0) {
            double rms_amplitude = calculate_rms(buffer, PERIOD_SIZE);
            map_amplitude_to_color(rms_amplitude, sensitivity, &red, &green, &blue);
            set_led_color(red, green, blue);
        } else {
            fprintf(stderr, "Error capturing audio\n");
        }
        usleep(10000); // 10ms
    }

    free(buffer);
    snd_pcm_close(pcm_handle);
#else
    // Simulate audio and control LED
    int red, green, blue;
    while (running) {
        double amplitude = simulate_audio();
        map_amplitude_to_color(amplitude, sensitivity, &red, &green, &blue);
        set_led_color(red, green, blue);
        usleep(10000); // 10ms
    }
#endif

    // Clean up
    gpioWrite(LED_RED_GPIO, 0);
    gpioWrite(LED_GREEN_GPIO, 0);
    gpioWrite(LED_BLUE_GPIO, 0);
    gpioTerminate();

    fprintf(stderr, "Exiting cleanly.\n");
    return 0;
}

