            fprintf(stderr, "Invalid sensitivity value. Using default: %f\n", SENSITIVITY_DEFAULT);
            sensitivity = SENSITIVITY_DEFAULT;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for PWM
    gpioSetMode(LED_RED_GPIO, PI_OUTPUT);
    gpioSetMode(LED_GREEN_GPIO, PI_OUTPUT);
    gpioSetMode(LED_BLUE_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(LED_RED_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LED_GREEN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LED_BLUE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_RED_GPIO, PWM_RANGE);
    gpioSetPWMrange(LED_GREEN_GPIO, PWM_RANGE);
    gpioSetPWMrange(LED_BLUE_GPIO, PWM_RANGE);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

#ifdef ALSA_AVAILABLE
    // Initialize ALSA
    int rc = snd_pcm_open(&pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (rc < 0) {
        fprintf(stderr, "cannot open audio device default (%s)\n", snd_strerror(rc));
        gpioTerminate();
        return 1;
    }

    snd_pcm_hw_params_t *hw_params;
    snd_pcm_hw_params_alloca(&hw_params);

    rc = snd_pcm_hw_params_any(pcm_handle, hw_params);
    if (rc < 0) {
        fprintf(stderr, "cannot initialize hardware parameter structure (%s)\n", snd_strerror(rc));
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    rc = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (rc < 0) {
        fprintf(stderr, "cannot set access type (%s)\n", snd_strerror(rc));
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    rc = snd_pcm_hw_params_set_format(pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE);
    if (rc < 0) {
        fprintf(stderr, "cannot set sample format (%s)\n", snd_strerror(rc));
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    rc = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, NUM_CHANNELS);
    if (rc < 0) {
        fprintf(stderr, "cannot set channel count (%s)\n", snd_strerror(rc));
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    unsigned int val = SAMPLE_RATE;
    int dir = 0;
    rc = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &val, &dir);
    if (rc < 0) {
        fprintf(stderr, "cannot set sample rate (%s)\n", snd_strerror(rc));
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    rc = snd_pcm_hw_params_set_period_size(pcm_handle, hw_params, PERIOD_SIZE, 0);
    if (rc < 0) {
        fprintf(stderr, "cannot set period size (%s)\n", snd_strerror(rc));
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    rc = snd_pcm_hw_params(pcm_handle, hw_params);
    if (rc < 0) {
        fprintf(stderr, "cannot set parameters (%s)\n", snd_strerror(rc));
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    snd_pcm_prepare(pcm_handle);

    short *buffer = (short *)malloc(PERIOD_SIZE * sizeof(short));
    if (buffer == NULL) {
        fprintf(stderr, "Failed to allocate audio buffer\n");
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    int red, green, blue;
    while (running) {
        if (capture_audio(buffer, PERIOD_SIZE) == 0) {
            double rms_amplitude = calculate_rms(buffer, PERIOD_SIZE);
            map_amplitude_to_color(rms_amplitude, sensitivity, &red, &green, &blue);
            set_led_color(red, green, blue);
        } else {
            fprintf(stderr, "Error capturing audio\n");
        }
        usleep(10000); // 10ms
    }

    free(buffer);
    snd_pcm_close(pcm_handle);
#else
    // Simulate audio and control LED
    int red, green, blue;
    while (running) {
        double amplitude = simulate_audio();
        map_amplitude_to_color(amplitude, sensitivity, &red, &green, &blue);
        set_led_color(red, green, blue);
        usleep(10000); // 10ms
    }
#endif

    // Clean up
    gpioWrite(LED_RED_GPIO, 0);
    gpioWrite(LED_GREEN_GPIO, 0);
    gpioWrite(LED_BLUE_GPIO, 0);
    gpioTerminate();

    fprintf(stderr, "Exiting cleanly.\n");
    return 0;
