#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ATIME           (0x01)
#define TCS34725_CONTROL         (0x0F)
#define TCS34725_ID              (0x12)
#define TCS34725_STATUS          (0x13)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)

// Enable Register Values
#define TCS34725_ENABLE_PON      (0x01)
#define TCS34725_ENABLE_AEN      (0x02)

// Integration Time Values
#define TCS34725_INTEGRATIONTIME_2_4MS  (0xFF)   // 2.4ms - 1 cycle    - Max Count: 1024
#define TCS34725_INTEGRATIONTIME_24MS   (0xF6)   // 24ms  - 10 cycles   - Max Count: 10240
#define TCS34725_INTEGRATIONTIME_50MS   (0xEB)   // 50ms  - 20 cycles   - Max Count: 20480
#define TCS34725_INTEGRATIONTIME_101MS  (0xD5)   // 101ms - 42 cycles   - Max Count: 42592
#define TCS34725_INTEGRATIONTIME_154MS  (0xC0)   // 154ms - 64 cycles   - Max Count: 65535
#define TCS34725_INTEGRATIONTIME_238MS  (0x80)   // 238ms - 98 cycles   - Max Count: 100864
#define TCS34725_INTEGRATIONTIME_377MS  (0x00)   // 377ms - 156 cycles  - Max Count: 160768

// Gain Values
#define TCS34725_GAIN_1X          (0x00)   // No gain
#define TCS34725_GAIN_4X          (0x01)   // 4x gain
#define TCS34725_GAIN_16X         (0x02)   // 16x gain
#define TCS34725_GAIN_60X         (0x03)   // 60x gain

// Global Variables
static int i2c_handle;
static FILE *fp;
static volatile int running = 1;

// Structure to hold color data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} color_data_t;

// Function Prototypes
int tcs34725_init(int i2c_handle);
int tcs34725_read_raw(int i2c_handle, color_data_t *data);
int tcs34725_calibrate(int i2c_handle, color_data_t *raw_data, color_data_t *calibrated_data);
int log_data(FILE *fp, color_data_t *data);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// TCS34725 Initialization Function
int tcs34725_init(int i2c_handle) {
    // Enable power and ALS
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) {
        fprintf(stderr, "Error: Could not enable power. %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(3); // Wait for power-on (3ms)
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        fprintf(stderr, "Error: Could not enable ALS. %s\n", strerror(errno));
        return -1;
    }

    // Set integration time to 154ms
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ATIME, TCS34725_INTEGRATIONTIME_154MS) < 0) {
        fprintf(stderr, "Error: Could not set integration time. %s\n", strerror(errno));
        return -1;
    }

    // Set gain to 1x
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_CONTROL, TCS34725_GAIN_1X) < 0) {
        fprintf(stderr, "Error: Could not set gain. %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// TCS34725 Read Raw Data Function
int tcs34725_read_raw(int i2c_handle, color_data_t *data) {
    char buf[8];

    if (i2cReadI2CBlockData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_CDATA, buf, 8) < 0) {
        fprintf(stderr, "Error: Could not read color data. %s\n", strerror(errno));
        return -1;
    }

    data->clear = (buf[1] << 8) | buf[0];
    data->red   = (buf[3] << 8) | buf[2];
    data->green = (buf[5] << 8) | buf[4];
    data->blue  = (buf[7] << 8) | buf[6];

    return 0;
}

// TCS34725 Calibrate Data Function
int tcs34725_calibrate(int i2c_handle, color_data_t *raw_data, color_data_t *calibrated_data) {
    // Simple calibration (replace with your actual calibration logic)
    calibrated_data->clear = raw_data->clear; // Example: No calibration
    calibrated_data->red   = raw_data->red;   // Example: No calibration
    calibrated_data->green = raw_data->green; // Example: No calibration
    calibrated_data->blue  = raw_data->blue;  // Example: No calibration

    return 0;
}

// Log Data Function
int log_data(FILE *fp, color_data_t *data) {
    time_t now = time(NULL);
    if (fprintf(fp, "%ld,%u,%u,%u,%u\n", now, data->clear, data->red, data->green, data->blue) < 0) {
        fprintf(stderr, "Error: Could not write to file. %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: TCS34725 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open CSV file. %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "timestamp,C,R,G,B\n");
    }
    fflush(fp);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    color_data_t raw_data, calibrated_data;

    // Main loop
    while (running) {
        // Read raw data from the sensor
        if (tcs34725_read_raw(i2c_handle, &raw_data) < 0) {
            fprintf(stderr, "Error: Failed to read raw data, logging zeros.\n");
            calibrated_data.clear = 0;
            calibrated_data.red = 0;
            calibrated_data.green = 0;
            calibrated_data.blue = 0;
        } else {
            // Calibrate the data
            if (tcs34725_calibrate(i2c_handle, &raw_data, &calibrated_data) < 0) {
                fprintf(stderr, "Error: Failed to calibrate data, logging raw data.\n");
            }
        }

        // Log the data
        if (log_data(fp, &calibrated_data) < 0) {
            fprintf(stderr, "Error: Failed to log data.\n");
        }

        // Wait for 500ms
        gpioDelay(500000); // 500ms
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

