#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define the duration of each phase in seconds
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 51840

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the state of a relay (active low)
void set_relay_state(int pin, int state) {
    gpioWrite(pin, !state); // Invert the state because relays are active low
}

// Function to calculate the duty cycle based on time
int calculate_duty_cycle(int time_elapsed, int phase_duration) {
    if (time_elapsed <= phase_duration) {
        return (int)(((float)time_elapsed / phase_duration) * 255);
    } else {
        return 0;
    }
}

// Function to control the relays based on the duty cycle
void control_relays(int duty_cycle) {
    // Map the duty cycle to GPIO states (simplified PWM)
    int on_time = duty_cycle; // Time the relay is on
    int off_time = 255 - duty_cycle; // Time the relay is off

    // Turn on the relays for the on_time duration
    set_relay_state(RELAY1_PIN, 1);
    set_relay_state(RELAY2_PIN, 1);
    set_relay_state(RELAY3_PIN, 1);
    set_relay_state(RELAY4_PIN, 1);
    gpioDelay(on_time * 10); // Delay in microseconds (adjust as needed)

    // Turn off the relays for the off_time duration
    set_relay_state(RELAY1_PIN, 0);
    set_relay_state(RELAY2_PIN, 0);
    set_relay_state(RELAY3_PIN, 0);
    set_relay_state(RELAY4_PIN, 0);
    gpioDelay(off_time * 10); // Delay in microseconds (adjust as needed)
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Sunrise phase
        for (int i = 0; i <= SUNRISE_DURATION && program_running; ++i) {
            int duty_cycle = calculate_duty_cycle(i, SUNRISE_DURATION);
            control_relays(duty_cycle);
            gpioDelay(1000); // Delay for 1 second
        }

