#define GPIO_PIN 17
#define DEBOUNCE_MS 200
#define VIDEO_DURATION_SEC 5
#define VIDEO_DIR "/home/pi/videos/"
#define LOG_FILE "/home/pi/logs/motion_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle SIGINT signal (Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to generate a timestamp string
void generate_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 21, "%Y%m%d_%H%M%S", timeinfo);
}

// Function to capture a video using raspivid
int capture_video(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspivid -o %s%s -t %d", VIDEO_DIR, filename, VIDEO_DURATION_SEC * 1000);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing raspivid command\n");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid command failed with exit status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

// Function to log a motion event
int log_motion(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s Motion detected\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately

    return 0;
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    int last_trigger_time = 0;
    char timestamp[21];

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) { // Active-low
            int current_time = gpioTick();

            if (current_time - last_trigger_time > DEBOUNCE_MS * 1000) {
                generate_timestamp(timestamp);

                printf("Motion detected at %s\n", timestamp);

                // Capture video
                if (capture_video(timestamp) != 0) {
                    fprintf(stderr, "Video capture failed\n");
                }

                // Log motion event
                if (log_motion(timestamp) != 0) {
                    fprintf(stderr, "Failed to log motion event\n");
                }

                last_trigger_time = current_time;
            }
        }

        gpioDelay(50); // Check every 50ms
    }

    // Clean up resources before exiting
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

