#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAZ0 0x36

// Free-fall threshold (in g)
#define FREEFALL_THRESHOLD 0.2

// Free-fall duration (in seconds)
#define FREEFALL_DURATION 0.5

// Alarm duration (in seconds)
#define ALARM_DURATION 5

// GPIO pin for alarm
#define ALARM_GPIO 27

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int adxl345_init();
accelerometer_data_t read_accelerometer_data();
int is_freefall(accelerometer_data_t data);
void trigger_alarm();
void log_freefall(accelerometer_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to initialize the ADXL345
int adxl345_init() {
    // Set the ADXL345 to measurement mode
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Could not set ADXL345 to measurement mode.\n");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data from the ADXL345
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char raw_data[6];
    int16_t x, y, z;

    // Read 6 bytes of data (X, Y, and Z axes)
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, raw_data, 6) < 0) {
        fprintf(stderr, "Error: Could not read accelerometer data.\n");
        data.x = 0.0; // Set to 0.0 to avoid using uninitialized values
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine the two bytes for each axis
    x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g units (assuming +/- 2g range and 10-bit resolution)
    data.x = (float)x / 256.0;
    data.y = (float)y / 256.0;
    data.z = (float)z / 256.0;

    return data;
}

// Function to check if the accelerometer is in free-fall
int is_freefall(accelerometer_data_t data) {
    return (fabs(data.x) < FREEFALL_THRESHOLD &&
            fabs(data.y) < FREEFALL_THRESHOLD &&
            fabs(data.z) < FREEFALL_THRESHOLD);
}

// Function to trigger the alarm
void trigger_alarm() {
    gpioWrite(ALARM_GPIO, 1); // Set GPIO high
    gpioDelay(ALARM_DURATION * 1000000); // Wait for alarm duration
    gpioWrite(ALARM_GPIO, 0); // Set GPIO low
}

// Function to log free-fall events to a file
void log_freefall(accelerometer_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Write to the log file
    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to clean up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C connection. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Ensure it starts LOW

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();

        if (is_freefall(data)) {
            // First free-fall detection
            printf("Potential free-fall detected.\n");
            gpioDelay(FREEFALL_DURATION * 1000000); // Wait for free-fall duration

            // Re-read accelerometer data
            accelerometer_data_t data2 = read_accelerometer_data();

            if (is_freefall(data2)) {
                // Confirmed free-fall
                printf("Free-fall confirmed!\n");
                log_freefall(data2);
                trigger_alarm();
            }
        }

        gpioDelay(100000); // Poll every 100ms
    }

    // Clean up and exit
    cleanup();
    return 0;
}

