#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 400.0    // cm
#define MAX_PULSE_WIDTH 23200  // us
#define TIMEOUT_US 100000      // 100 ms
#define TRIGGER_PULSE_DURATION 10 // us
#define TRIGGER_DELAY 200       // ms

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int timeout_flag = 0;
static FILE *log_file = NULL;
static pthread_mutex_t mutex;
static int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user);
void timeout_callback();
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold callback data
typedef struct {
    int gpio;
    int level;
    uint32_t tick;
} callback_data_t;

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick, void *user) {
    callback_data_t *data = (callback_data_t *)user;
    data->gpio = gpio;
    data->level = level;
    data->tick = tick;

    pthread_mutex_lock(&mutex);
    if (level == 1) {
        start_tick = tick;
        echo_received = 1;
        timeout_flag = 0; // Reset timeout flag on rising edge
    } else if (level == 0) {
        end_tick = tick;
    }
    pthread_mutex_unlock(&mutex);
}

// Timeout callback function
void timeout_callback() {
    pthread_mutex_lock(&mutex);
    timeout_flag = 1;
    pthread_mutex_unlock(&mutex);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize mutex
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt callbacks
    gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, echo_callback, NULL);
    gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, echo_callback, NULL);

    // Set up timeout callback
    gpioSetTimerFuncEx(0, TIMEOUT_US, timeout_callback, NULL);

    return 0;
}

// Cleanup function
void cleanup() {
    // Cancel callbacks
    gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioSetTimerFuncEx(0, 0, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy mutex
    pthread_mutex_destroy(&mutex);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Ultrasonic sensor measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        // Generate trigger pulse
        trigger_pulse();

        // Wait for echo or timeout
        usleep(TRIGGER_DELAY * 1000); // Convert ms to us

