#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define BUZZER_GPIO 17
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5

// Global variables
int i2c_handle;
double freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
double impact_threshold = DEFAULT_IMPACT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_lis3dh();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void activate_buzzer();
void deactivate_buzzer();
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize LIS3DH
int init_lis3dh() {
    // Enable accelerometer, 100Hz data rate, normal mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set full-scale range to +/- 2g
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int retries = 3;
    int bytes_read;

    while (retries > 0) {
        bytes_read = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
        if (bytes_read == 6) {
            // Combine high and low bytes, convert to g
            *x = (float)((short)((buffer[1] << 8) | buffer[0])) / 16384.0;
            *y = (float)((short)((buffer[3] << 8) | buffer[2])) / 16384.0;
            *z = (float)((short)((buffer[5] << 8) | buffer[4])) / 16384.0;
            return 0;
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying... (%d retries left)\n", retries - 1);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read acceleration data after multiple retries.\n");
    return -1;
}

// Calculate acceleration magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Activate buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // HIGH
    gpioDelay(1000000);       // 1 second
    deactivate_buzzer();
}

// Deactivate buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_GPIO, 0); // LOW
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    deactivate_buzzer();
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    printf("Freefall threshold: %.2f g\n", freefall_threshold);
    printf("Impact threshold: %.2f g\n", impact_threshold);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh() < 0) {
        cleanup();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    deactivate_buzzer(); // Ensure buzzer is off initially

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z, magnitude;
    int freefall_detected = 0;

    printf("Monitoring accelerometer...\n");

    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude < freefall_threshold && !freefall_detected) {
                printf("Freefall detected! Magnitude: %.2f g\n", magnitude);
                freefall_detected = 1;
            } else if (magnitude > impact_threshold && freefall_detected) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                activate_buzzer();
                freefall_detected = 0; // Reset freefall flag after impact
            } else if (magnitude > freefall_threshold && freefall_detected) {
                freefall_detected = 0; // Reset freefall flag if acceleration increases
            }
        } else {
            fprintf(stderr, "Error reading acceleration data.\n");
        }

        gpioDelay(10000); // 10ms delay
    }

    cleanup();
    return 0;
}

