// Define square side length (in mm)
#define SQUARE_SIDE_LENGTH 50.0

// Define steps per mm (calculated based on motor and gear ratio)
#define STEPS_PER_MM (STEPS_PER_REVOLUTION / (3.14 * 20.0)) // Assuming 20mm pulley diameter

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void set_motor_pins(int motor, int step);
void move_motor(int motor, int direction, int steps);
void move_x(int steps);
void move_y(int steps);
void stop_motors();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Stopping motors and exiting.\n");
        program_running = 0;
        stop_motors();
        gpioTerminate();
        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN4, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to set motor pins based on step sequence
void set_motor_pins(int motor, int step) {
    int in1, in2, in3, in4;

    if (motor == MOTOR1) {
        in1 = MOTOR1_IN1;
        in2 = MOTOR1_IN2;
        in3 = MOTOR1_IN3;
        in4 = MOTOR1_IN4;
    } else if (motor == MOTOR2) {
        in1 = MOTOR2_IN1;
        in2 = MOTOR2_IN2;
        in3 = MOTOR2_IN3;
        in4 = MOTOR2_IN4;
    } else {
        fprintf(stderr, "Invalid motor ID: %d\n", motor);
        return;
    }

    gpioWrite(in1, step_sequence[step][0]);
    gpioWrite(in2, step_sequence[step][1]);
    gpioWrite(in3, step_sequence[step][2]);
    gpioWrite(in4, step_sequence[step][3]);
}

// Function to move a motor a specified number of steps
void move_motor(int motor, int direction, int steps) {
    int i;
    for (i = 0; i < steps; i++) {
        static int current_step = 0;
        if (direction == FORWARD) {
            current_step = (current_step + 1) % 4;
        } else {
            current_step = (current_step + 3) % 4; // Equivalent to (current_step - 1) % 4
        }

        set_motor_pins(motor, current_step);
        gpioDelay(STEP_DELAY);
    }
}

// Function to move the X-axis motor
void move_x(int steps) {
    move_motor(MOTOR1, (steps > 0) ? FORWARD : BACKWARD, abs(steps));
}

// Function to move the Y-axis motor
void move_y(int steps) {
    move_motor(MOTOR2, (steps > 0) ? FORWARD : BACKWARD, abs(steps));
}

// Function to stop both motors and set all GPIO pins low
void stop_motors() {
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR1_IN3, 0);
    gpioWrite(MOTOR1_IN4, 0);
    gpioWrite(MOTOR2_IN1, 0);
    gpioWrite(MOTOR2_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Calculate the number of steps required to move 50mm
    int steps_per_side = (int)(SQUARE_SIDE_LENGTH * STEPS_PER_MM);

    printf("Moving X-axis forward %d steps\n", steps_per_side);
    move_x(steps_per_side);

    printf("Moving Y-axis forward %d steps\n", steps_per_side);
    move_y(steps_per_side);

    printf("Moving X-axis backward %d steps\n", steps_per_side);
    move_x(-steps_per_side);

    printf("Moving Y-axis backward %d steps\n", steps_per_side);
    move_y(-steps_per_side);

    // Stop motors and terminate GPIO
    stop_motors();
    gpioTerminate();

    return 0;
}

