#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// LIS3DH Registers
#define LIS3DH_REG_WHO_AM_I   0x0F
#define LIS3DH_REG_CTRL_REG1  0x20
#define LIS3DH_REG_CTRL_REG4  0x23
#define LIS3DH_REG_OUT_X_L    0x28
#define LIS3DH_REG_OUT_X_H    0x29
#define LIS3DH_REG_OUT_Y_L    0x2A
#define LIS3DH_REG_OUT_Y_H    0x2B
#define LIS3DH_REG_OUT_Z_L    0x2C
#define LIS3DH_REG_OUT_Z_H    0x2D

// Default I2C address
#define DEFAULT_I2C_ADDRESS 0x18

// Default threshold
#define DEFAULT_THRESHOLD 2.0

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lis3dh(int i2c_handle);
int read_acceleration(int i2c_handle, float *x, float *y, float *z);
int check_threshold(float x, float y, float z, double threshold);
void log_acceleration(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize LIS3DH sensor
int init_lis3dh(int i2c_handle) {
    // Set CTRL_REG1: Normal mode, 100 Hz ODR, enable all axes
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL_REG1, 0x77) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set CTRL_REG4: ±2g range, high-resolution mode
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL_REG4, 0x88) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from LIS3DH
int read_acceleration(int i2c_handle, float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    // Read all six bytes at once
    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_REG_OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        *x = 0.0;
        *y = 0.0;
        *z = 0.0;
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to g units (12-bit resolution, ±2g range)
    *x = (float)raw_x / 4096.0;
    *y = (float)raw_y / 4096.0;
    *z = (float)raw_z / 4096.0;

    return 0;
}

// Check if acceleration exceeds threshold
int check_threshold(float x, float y, float z, double threshold) {
    if (fabs(x) > threshold || fabs(y) > threshold || fabs(z) > threshold) {
        return 1;
    }
    return 0;
}

// Log acceleration data to file
void log_acceleration(float x, float y, float z) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, X: %.3f g, Y: %.3f g, Z: %.3f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);

    fclose(fp);
    printf("Acceleration threshold exceeded. Logging data and shutting down.\n");
    system("sudo shutdown -h now");
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                if (i2c_address < 0x08 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address. Using default 0x18.\n");
                    i2c_address = DEFAULT_I2C_ADDRESS;
                }
                break;
            case 't':
                threshold = strtod(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Invalid threshold. Using default 2.0 g.\n");
                    threshold = DEFAULT_THRESHOLD;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH sensor
    if (init_lis3dh(i2c_handle) != 0) {
        fprintf(stderr, "LIS3DH initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            // Check if threshold is exceeded
            if (check_threshold(x, y, z, threshold)) {
                log_acceleration(x, y, z);
                break; // Exit loop after logging and shutdown
            }
        }

        // Delay for 100 ms (10 Hz sampling rate)
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

