#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_PIN 22

// Define motor control commands
#define FORWARD 1
#define LEFT 2
#define RIGHT 3
#define STOP 0

// Define circular buffer size
#define BUFFER_SIZE 5

// Structure to hold sensor readings
typedef struct {
    int left;
    int center;
    int right;
} SensorReadings;

// Global variables
volatile sig_atomic_t program_running = 1;
int center_no_line_count = 0;

// Function prototypes
int read_sensor(int gpio_pin);
void add_reading(SensorReadings readings, SensorReadings *buffer, int *head, int *tail, int buffer_size);
SensorReadings get_latest_reading(SensorReadings *buffer, int head, int buffer_size);
void control_motor(int command);
void activate_alert();
void signal_handler(int signal);
int initialize_gpio();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    control_motor(STOP);
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(CENTER_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d\n", gpio_pin);
        return -1; // Indicate error
    }
    return value;
}

// Function to add a reading to the circular buffer
void add_reading(SensorReadings readings, SensorReadings *buffer, int *head, int *tail, int buffer_size) {
    buffer[*head] = readings;
    *head = (*head + 1) % buffer_size;
    if (*head == *tail) {
        *tail = (*tail + 1) % buffer_size;
    }
}

// Function to get the latest reading from the circular buffer
SensorReadings get_latest_reading(SensorReadings *buffer, int head, int buffer_size) {
    if (head == -1) {
        // Buffer is empty
        SensorReadings empty_reading = {0, 0, 0};
        return empty_reading;
    }
    int index = (head - 1 + buffer_size) % buffer_size;
    return buffer[index];
}

// Function to control the motor (placeholder)
void control_motor(int command) {
    printf("Motor command: %d\n", command);
}

// Function to activate the alert (buzzer/LED)
void activate_alert() {
    gpioWrite(ALERT_PIN, 1);
    gpioDelay(2000); // 2 seconds
    gpioWrite(ALERT_PIN, 0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize circular buffer
    SensorReadings sensor_buffer[BUFFER_SIZE];
    int head = -1; // Initialize to -1 to indicate empty buffer
    int tail = 0;

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR);
        int center_value = read_sensor(CENTER_SENSOR);
        int right_value = read_sensor(RIGHT_SENSOR);

        if (left_value == -1 || center_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break; // Exit loop on sensor read error
        }

        SensorReadings current_reading = {left_value, center_value, right_value};

        // Add reading to circular buffer
        add_reading(current_reading, sensor_buffer, &head, &tail, BUFFER_SIZE);

        // Get the latest reading from the buffer
        SensorReadings latest_reading = get_latest_reading(sensor_buffer, head, BUFFER_SIZE);

        // Line following logic
        if (center_value == 0) {
            control_motor(FORWARD);
            center_no_line_count = 0; // Reset counter
        } else if (left_value == 0) {
            control_motor(LEFT);
            center_no_line_count = 0; // Reset counter
        } else if (right_value == 0) {
            control_motor(RIGHT);
            center_no_line_count = 0; // Reset counter
        } else {
            control_motor(STOP);
            center_no_line_count++;
            if (center_no_line_count >= 5) {
                activate_alert();
                center_no_line_count = 0; // Reset counter after alert
            }
        }

        // Delay for 10ms
        gpioDelay(10000); // 10ms
    }

    // Clean up and exit
    control_motor(STOP);
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
    return 0;
}

