    printf("Motor command: %d\n", command);
}

// Function to activate the alert (buzzer/LED)
void activate_alert() {
    gpioWrite(ALERT_PIN, 1);
    gpioDelay(2000); // 2 seconds
    gpioWrite(ALERT_PIN, 0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize circular buffer
    SensorReadings sensor_buffer[BUFFER_SIZE];
    int head = -1; // Initialize to -1 to indicate empty buffer
    int tail = 0;

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR);
        int center_value = read_sensor(CENTER_SENSOR);
        int right_value = read_sensor(RIGHT_SENSOR);

        if (left_value == -1 || center_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break; // Exit loop on sensor read error
        }

        SensorReadings current_reading = {left_value, center_value, right_value};

        // Add reading to circular buffer
        add_reading(current_reading, sensor_buffer, &head, &tail, BUFFER_SIZE);

        // Get the latest reading from the buffer
        SensorReadings latest_reading = get_latest_reading(sensor_buffer, head, BUFFER_SIZE);

        // Line following logic
        if (center_value == 0) {
            control_motor(FORWARD);
            center_no_line_count = 0; // Reset counter
        } else if (left_value == 0) {
            control_motor(LEFT);
            center_no_line_count = 0; // Reset counter
        } else if (right_value == 0) {
            control_motor(RIGHT);
            center_no_line_count = 0; // Reset counter
        } else {
            control_motor(STOP);
            center_no_line_count++;
            if (center_no_line_count >= 5) {
