#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PORT 5000
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

// Global variables for signal handling
static volatile int keep_running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int setup_gpio();
int setup_socket();
void handle_client(int client_fd);
void log_event(const char *event);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signal);
        keep_running = 0;
    }
}

// Setup GPIO using pigpio
int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF state
    return 0;
}

// Setup socket
int setup_socket() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    // Forcefully attaching socket to the port 5000
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 5000
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        return -1;
    }
    printf("Listening on port %d...\n", PORT);
    return server_fd;
}

// Handle client connection
void handle_client(int client_fd) {
    char buffer[BUFFER_SIZE] = {0};
    ssize_t valread;

    valread = read(client_fd, buffer, BUFFER_SIZE - 1);
    if (valread < 0) {
        perror("read");
        log_event("Error reading from socket");
        close(client_fd);
        return;
    }

    // Remove trailing whitespace
    char *endptr = buffer + valread - 1;
    while (endptr > buffer && (*endptr == ' ' || *endptr == '\t' || *endptr == '\n' || *endptr == '\r')) {
        *endptr = '\0';
        endptr--;
    }

    // Convert to uppercase
    for (int i = 0; buffer[i]; i++) {
        buffer[i] = toupper(buffer[i]);
    }

    if (strcmp(buffer, "ON") == 0) {
        gpioWrite(GPIO_PIN, 1);
        log_event("Relay turned ON");
        send(client_fd, "OK", strlen("OK"), 0);
    } else if (strcmp(buffer, "OFF") == 0) {
        gpioWrite(GPIO_PIN, 0);
        log_event("Relay turned OFF");
        send(client_fd, "OK", strlen("OK"), 0);
    } else {
        log_event("Invalid command received");
        send(client_fd, "Invalid command", strlen("Invalid command"), 0);
    }

    close(client_fd);
}

// Log events to file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (server_fd != -1) {
        close(server_fd);
    }
    gpioWrite(GPIO_PIN, 0); // Turn off relay
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize GPIO
    if (setup_gpio() != 0) {
        log_event("GPIO setup failed");
        cleanup();
        return 1;
    }

    // Setup socket
    server_fd = setup_socket();
    if (server_fd == -1) {
        log_event("Socket setup failed");
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    int addrlen = sizeof(address);
    int new_socket;

    printf("Server started. Listening for connections...\n");

    while (keep_running) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            if (keep_running) { // Only print error if we're not shutting down
                perror("accept");
                log_event("Error accepting connection");
            }
            continue; // Continue listening if accept fails, unless shutting down
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(address.sin_addr), ntohs(address.sin_port));
        handle_client(new_socket);
    }

    cleanup();
    return 0;
}

