#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0 // ml/min
#define POLLING_INTERVAL_MS 100
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0x00

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
void cleanup();
void signal_handler(int signal);
int read_sensor(int i2c_handle, float *flow_rate);
uint8_t crc8(const uint8_t *data, size_t len);
void log_flow(float flow1, float flow2);
void control_relay(float flow1, float flow2);

// Structure to hold sensor data
typedef struct {
    int i2c_handle;
    uint8_t address;
} sensor_t;

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, shutting down...\n");
    terminate = 1;
}

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read flow rate from a sensor
int read_sensor(int i2c_handle, float *flow_rate) {
    uint8_t buffer[3];
    int bytes_read = i2cReadDevice(i2c_handle, (char *)buffer, 3);

    if (bytes_read != 3) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }

    uint8_t crc = crc8(buffer, 2);
    if (crc != buffer[2]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert raw data to flow rate (example conversion, adjust as needed)
    int16_t raw_flow = (buffer[0] << 8) | buffer[1];
    *flow_rate = (float)raw_flow / 100.0; // Example scaling

    return 0;
}

// Function to log flow rates
void log_flow(float flow1, float flow2) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s, Flow1: %.2f ml/min, Flow2: %.2f ml/min\n", timestamp, flow1, flow2);
    fflush(log_file);
}

// Function to control the relay
void control_relay(float flow1, float flow2) {
    if (flow1 < FLOW_THRESHOLD || flow2 < FLOW_THRESHOLD) {
        gpioWrite(RELAY_GPIO, 1); // Energize relay
    } else {
        gpioWrite(RELAY_GPIO, 0); // De-energize relay
    }
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus for sensor 1
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return -1;
    }

    // Open I2C bus for sensor 2
    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return -1;
    }

    // Configure relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to de-energized state

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // De-energize relay
    gpioWrite(RELAY_GPIO, 0);

    // Close I2C handles
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);

    // Close log file
    if (log_file != NULL) fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    float flow1, flow2;

    // Main loop
    while (!terminate) {
        // Read flow rates from sensors
        int read1_result = read_sensor(i2c_handle1, &flow1);
        int read2_result = read_sensor(i2c_handle2, &flow2);

        if (read1_result == 0 && read2_result == 0) {
            // Log flow rates
            log_flow(flow1, flow2);

            // Control relay
            control_relay(flow1, flow2);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging and relay control.\n");
        }

        // Wait for the next polling interval
        gpioDelay(POLLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

