#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor control constants
#define MOTOR_FORWARD 1
#define MOTOR_BACKWARD 2
#define MOTOR_STOP 0

// Define rain detection threshold
#define RAIN_DETECTED 0
#define DRY 1

// Define motor run time (seconds)
#define MOTOR_RUN_TIME 5

// Global variable to track rain state
static volatile int rain_detected = 0;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
int control_motor(int direction);
void stop_motor();
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Signal handler function
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, shutting down...");
    stop_motor();
    gpioTerminate();
    closelog();
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Set GPIO modes
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        log_message(LOG_ERR, "Failed to set RAIN_SENSOR_PIN to input");
        return -1;
    }
    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_ENA_PIN to output");
        return -1;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_IN1_PIN to output");
        return -1;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_IN2_PIN to output");
        return -1;
    }

    // Set pull-up resistor on rain sensor pin
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) != 0) {
        log_message(LOG_ERR, "Failed to set pull-up resistor on RAIN_SENSOR_PIN");
        return -1;
    }

    log_message(LOG_INFO, "GPIO initialization complete");
    return 0;
}

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to control the motor
int control_motor(int direction) {
    switch (direction) {
        case MOTOR_FORWARD:
            if (gpioWrite(MOTOR_IN1_PIN, 1) != 0) {
                log_message(LOG_ERR, "Failed to set MOTOR_IN1_PIN high");
                return -1;
            }
            if (gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
                log_message(LOG_ERR, "Failed to set MOTOR_IN2_PIN low");
                return -1;
            }
            if (gpioWrite(MOTOR_ENA_PIN, 1) != 0) {
                log_message(LOG_ERR, "Failed to set MOTOR_ENA_PIN high");
                return -1;
            }
            log_message(LOG_INFO, "Motor started (close window)");
            break;
        case MOTOR_BACKWARD:
            if (gpioWrite(MOTOR_IN1_PIN, 0) != 0) {
                log_message(LOG_ERR, "Failed to set MOTOR_IN1_PIN low");
                return -1;
            }
            if (gpioWrite(MOTOR_IN2_PIN, 1) != 0) {
                log_message(LOG_ERR, "Failed to set MOTOR_IN2_PIN high");
                return -1;
            }
            if (gpioWrite(MOTOR_ENA_PIN, 1) != 0) {
                log_message(LOG_ERR, "Failed to set MOTOR_ENA_PIN high");
                return -1;
            }
            log_message(LOG_INFO, "Motor started (open window)");
            break;
        case MOTOR_STOP:
            if (gpioWrite(MOTOR_ENA_PIN, 0) != 0) {
                log_message(LOG_ERR, "Failed to set MOTOR_ENA_PIN low");
                return -1;
            }
            if (gpioWrite(MOTOR_IN1_PIN, 0) != 0) {
                log_message(LOG_ERR, "Failed to set MOTOR_IN1_PIN low");
                return -1;
            }
            if (gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
                log_message(LOG_ERR, "Failed to set MOTOR_IN2_PIN low");
                return -1;
            }
            log_message(LOG_INFO, "Motor stopped");
            break;
        default:
            log_message(LOG_WARNING, "Invalid motor direction");
            return -1;
    }
    return 0;
}

// Function to stop the motor
void stop_motor() {
    control_motor(MOTOR_STOP);
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

int main() {
    // Open syslog
    openlog("rain_window", LOG_PID, LOG_USER);
    log_message(LOG_INFO, "Program started");

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int dry_count = 0;
    while (1) {
        int rain_state = read_rain_sensor();

        if (rain_state == RAIN_DETECTED) {
            dry_count = 0; // Reset dry count
            if (!rain_detected) {
                log_message(LOG_INFO, "Rain detected");
                rain_detected = 1;
                control_motor(MOTOR_FORWARD); // Close window
                usleep(MOTOR_RUN_TIME * 1000000); // Run motor for 5 seconds
                stop_motor();
            }
        } else {
            dry_count++;
            if (dry_count >= 3 && rain_detected) {
                log_message(LOG_INFO, "No rain detected for 600ms");
                rain_detected = 0;
            }
        }

        usleep(200000); // Poll every 200ms
    }

    // This point should not be reached due to the signal handler
    return 0;
}

