#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define FLOODLIGHT_PIN 17

// Define floodlight duration
#define FLOODLIGHT_DURATION 60 // seconds

// Define log file name
#define LOG_FILE "security_log.txt"

// Global variable to track floodlight state
static volatile int floodlight_on = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_floodlight(int on);
int log_event(const char *event_type, const char *timestamp, int duration);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int pigpio_initialized;
} ProgramState;

ProgramState state = {0};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }
    state.pigpio_initialized = 1;

    // Main loop
    while (1) {
        // Read PIR sensor
        int motion_detected = read_pir_sensor();

        // If motion is detected, activate floodlight
        if (motion_detected) {
            // Generate timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[30];
            time(&rawtime);
            timeinfo = gmtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Log activation event
            if (log_event("ACTIVATION", timestamp, 0) != 0) {
                fprintf(stderr, "Failed to log activation event.\n");
            }

            // Activate floodlight
            if (control_floodlight(1) != 0) {
                fprintf(stderr, "Failed to activate floodlight.\n");
            }
            floodlight_on = 1;

            // Wait for floodlight duration
            sleep(FLOODLIGHT_DURATION);

            // Generate timestamp for deactivation
            time(&rawtime);
            timeinfo = gmtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Log deactivation event
            if (log_event("DEACTIVATION", timestamp, FLOODLIGHT_DURATION) != 0) {
                fprintf(stderr, "Failed to log deactivation event.\n");
            }

            // Deactivate floodlight
            if (control_floodlight(0) != 0) {
                fprintf(stderr, "Failed to deactivate floodlight.\n");
            }
            floodlight_on = 0;
        }

        // Polling interval
        gpioDelay(100); // 100 ms
    }

    return 0;
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PIR sensor pin as input
    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);

    // Set floodlight pin as output
    gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT);

    // Ensure floodlight is initially off
    gpioWrite(FLOODLIGHT_PIN, 0);

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Control floodlight (1 for on, 0 for off)
int control_floodlight(int on) {
    gpioWrite(FLOODLIGHT_PIN, on);
    return 0;
}

// Log event to file
int log_event(const char *event_type, const char *timestamp, int duration) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    fprintf(fp, "%s,%s,%d\n", event_type, timestamp, duration);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close log file.\n");
        return 1;
    }

    return 0;
}

// Signal handler to ensure clean exit
void signal_handler(int signal) {
    printf("Caught signal %d. Cleaning up and exiting.\n", signal);

    // Turn off floodlight
    if (floodlight_on) {
        control_floodlight(0);
    }

    // Release GPIO resources
    if (state.pigpio_initialized) {
        gpioTerminate();
    }

    exit(0);
}

