#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define constants
#define MPR121_I2C_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 200

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_ELECTRODE_CONFIG 0x5D

// Global variables
static int i2c_fd;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void debounce_electrode(int electrode);
void toggle_relay();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
    digitalWrite(RELAY_GPIO, LOW); // Ensure relay is OFF on exit
    exit(0);
}

// MPR121 Initialization function
int mpr121_init() {
    int result;

    // Soft reset
    result = wiringPiI2CWriteReg8(i2c_fd, MPR121_ECR, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error: Soft reset failed (error code %d).\n", result);
        return -1;
    }
    delay(1); // Wait for reset to complete

    // Configure baseline filtering
    result = wiringPiI2CWriteReg8(i2c_fd, MPR121_MHDR, 0x01);
    if (result < 0) return -1;
    result = wiringPiI2CWriteReg8(i2c_fd, MPR121_NHDR, 0x01);
    if (result < 0) return -1;
    result = wiringPiI2CWriteReg8(i2c_fd, MPR121_NCLR, 0x0E);
    if (result < 0) return -1;
    result = wiringPiI2CWriteReg8(i2c_fd, MPR121_FDLR, 0x00);
    if (result < 0) return -1;

    result = wiringPiI2CWriteReg8(i2c_fd, MPR121_MHDF, 0x01);
    if (result < 0) return -1;
    result = wiringPiI2CWriteReg8(i2c_fd, MPR121_NHDF, 0x01);
    if (result < 0) return -1;
    result = wiringPiI2CWriteReg8(i2c_fd, MPR121_NCLF, 0x0E);
    if (result < 0) return -1;
    result = wiringPiI2CWriteReg8(i2c_fd, MPR121_FDLF, 0x00);
    if (result < 0) return -1;

    // Configure debounce
    result = wiringPiI2CWriteReg8(i2c_fd, MPR121_CONFIG2, 0x01); // Debounce = 1
    if (result < 0) return -1;

    // Configure FFI, SFI and CDT
    result = wiringPiI2CWriteReg8(i2c_fd, MPR121_CONFIG1, 0x10 | (0x0A << 4) | (0x05 << 8)); // FFI = 16, SFI = 10, CDT = 5
    if (result < 0) return -1;

    // Enable auto-config
    result = wiringPiI2CWriteReg8(i2c_fd, MPR121_ELECTRODE_CONFIG, 0x0C); // Enable electrodes 0-11
    if (result < 0) return -1;

    // Enable the MPR121 (start sensing)
    result = wiringPiI2CWriteReg8(i2c_fd, MPR121_ECR, 0x8F); // Enable all electrodes
    if (result < 0) {
        fprintf(stderr, "Error: Failed to enable MPR121 (error code %d).\n", result);
        return -1;
    }

    return 0;
}

// Read Touch Status function
int read_touch_status(uint16_t *touch_status) {
    int result;
    uint8_t touch_status_l, touch_status_h;

    touch_status_l = wiringPiI2CReadReg8(i2c_fd, MPR121_TOUCHSTATUS_L);
    if (touch_status_l < 0) {
        fprintf(stderr, "Error: Failed to read touch status low byte (error code %d).\n", touch_status_l);
        return -1;
    }

    touch_status_h = wiringPiI2CReadReg8(i2c_fd, MPR121_TOUCHSTATUS_H);
    if (touch_status_h < 0) {
        fprintf(stderr, "Error: Failed to read touch status high byte (error code %d).\n", touch_status_h);
        return -1;
    }

    *touch_status = (touch_status_h << 8) | touch_status_l;
    return 0;
}

// Debounce Electrode function
void debounce_electrode(int electrode) {
    static uint32_t last_touch_time[12] = {0}; // Store last touch time for each electrode
    uint32_t current_time = millis();

    if (current_time - last_touch_time[electrode] > DEBOUNCE_DELAY_MS) {
        last_touch_time[electrode] = current_time;
    } else {
        return; // Ignore the touch event
    }
}

// Toggle Relay function
void toggle_relay() {
    static bool relay_state = false; // Keep track of the relay state

    relay_state = !relay_state;
    digitalWrite(RELAY_GPIO, relay_state ? HIGH : LOW);
    printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
}

int main() {
    uint16_t touch_status;
    int result;

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Failed to initialize wiringPi.\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_I2C_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: Failed to initialize I2C communication.\n");
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() == -1) {
        fprintf(stderr, "Error: Failed to initialize MPR121.\n");
        return 1;
    }

    // Set relay GPIO as output
    pinMode(RELAY_GPIO, OUTPUT);
    digitalWrite(RELAY_GPIO, LOW); // Ensure relay is OFF at startup

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 and Relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read touch status
        result = read_touch_status(&touch_status);
        if (result == -1) {
            fprintf(stderr, "Error: Failed to read touch status.\n");
            delay(100); // Small delay before retrying
            continue;
        }

        // Check if electrode 0 is touched
        if (touch_status & 0x01) {
            debounce_electrode(0);
            toggle_relay();
        }

        delay(50); // Small delay to avoid busy-waiting
    }

    // Cleanup (should not reach here if signal handler works correctly)
    digitalWrite(RELAY_GPIO, LOW); // Ensure relay is OFF on exit
    return 0;
}

