#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <stdarg.h>
#include <pigpio.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 1000 // 1ms
#define MAX_PULSE_WIDTH 2000 // 2ms
#define RANGE 2000

// Global variables for graceful shutdown
int server_fd = 0;
FILE *log_file = NULL;

// Function prototypes
void log_message(int priority, const char *format, ...);
int set_servo_angle(int angle);
int read_pir_sensor();
int handle_client(int client_fd);
void signal_handler(int signum);

// Logging function
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Log to syslog
    vsyslog(priority, format, args);

    // Log to file
    if (log_file != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);

        fprintf(log_file, "%s ", timestamp);
        vfprintf(log_file, format, args);
        fflush(log_file);
    }

    va_end(args);
}

// Servo control function
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_message(LOG_ERR, "Invalid servo angle: %d\n", angle);
        return -1;
    }

    // Calculate pulse width based on angle
    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)angle / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

    gpioPWM(SERVO_PIN, pulse_width); // Set PWM duty cycle
    log_message(LOG_INFO, "Servo angle set to: %d, Pulse width: %d\n", angle, pulse_width);
    return 0;
}

// PIR sensor reading function
int read_pir_sensor() {
    int value = gpioRead(PIR_PIN);
    log_message(LOG_INFO, "PIR sensor value: %d\n", value);
    return value;
}

// Client handling function
int handle_client(int client_fd) {
    char buffer[1024] = {0};
    ssize_t bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);

    if (bytes_received < 0) {
        log_message(LOG_ERR, "Error receiving data: %s\n", strerror(errno));
        close(client_fd);
        return -1;
    } else if (bytes_received == 0) {
        log_message(LOG_INFO, "Client disconnected\n");
        close(client_fd);
        return 0;
    }

    log_message(LOG_INFO, "Received: %s\n", buffer);

    if (strncmp(buffer, "set_angle", 9) == 0) {
        int angle = atoi(buffer + 10);
        if (set_servo_angle(angle) != 0) {
            const char *error_message = "Invalid angle\n";
            send(client_fd, error_message, strlen(error_message), 0);
            log_message(LOG_ERR, "Failed to set servo angle\n");
        }
    } else if (strncmp(buffer, "PIR", 3) == 0) {
        int pir_value = read_pir_sensor();
        char response[20];
        snprintf(response, sizeof(response), "PIR:%d\n", pir_value);
        send(client_fd, response, strlen(response), 0);
    } else {
        const char *error_message = "Invalid command\n";
        send(client_fd, error_message, strlen(error_message), 0);
        log_message(LOG_ERR, "Invalid command received\n");
    }

    close(client_fd);
    return 0;
}

// Signal handler function
void signal_handler(int signum) {
    log_message(LOG_INFO, "Signal received: %d. Shutting down...\n", signum);

    // Stop PWM
    gpioPWM(SERVO_PIN, 0);

    // Close socket
    if (server_fd > 0) {
        close(server_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize syslog
    openlog("servo_control", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen("security.log", "a");
    if (log_file == NULL) {
        log_message(LOG_ERR, "Failed to open log file: %s\n", strerror(errno));
        closelog();
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed: %s\n", strerror(errno));
        fclose(log_file);
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(PIR_PIN, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(SERVO_PIN, RANGE);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        log_message(LOG_ERR, "Socket creation failed: %s\n", strerror(errno));
        gpioTerminate();
        fclose(log_file);
        closelog();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed: %s\n", strerror(errno));
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        closelog();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed: %s\n", strerror(errno));
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Listening on port %d\n", PORT);

    // Main loop
    while (1) {
        struct sockaddr_in client_address;
        int client_fd = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&client_address);
        if (client_fd < 0) {
            log_message(LOG_ERR, "Accept failed: %s\n", strerror(errno));
            continue; // Continue listening for other connections
        }

        log_message(LOG_INFO, "Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        handle_client(client_fd);
    }

    // The following lines will never be reached due to the infinite loop.
    close(server_fd);
    gpioTerminate();
    fclose(log_file);
    closelog();

    return 0;
}

