        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_GPIO, 0); // Deactivate relay
    gpioTerminate();
}

// Read lux value from BH1750
int read_lux(float *lux) {
    char config[1] = {CONTINUOUS_HIGH_RES_MODE};
    char buffer[2];
    int result;

    result = i2cWriteDevice(i2c_handle, config, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(120); // Wait for measurement

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2; // Convert to lux

    return 0;
}

// Control the relay based on lux value
void control_relay(float lux) {
    if (lux < LUX_THRESHOLD) {
        gpioWrite(RELAY_GPIO, 1); // Activate relay
    } else {
        gpioWrite(RELAY_GPIO, 0); // Deactivate relay
    }
}

// Log data to file
void log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f lux\n", timestamp, lux);
    fflush(log_file); // Ensure data is written immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize resources
    if (init_i2c() != 0 || init_gpio() != 0 || init_logging() != 0) {
        cleanup();
        return 1;
    }

    float lux;

    printf("Starting grow light control...\n");

    while (!terminate) {
        if (read_lux(&lux) == 0) {
            log_data(lux);
            control_relay(lux);
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Error reading lux, retrying in %d seconds...\n", RETRY_DELAY);
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s, Error reading lux\n", timestamp);
            fflush(log_file);
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

