#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_DURATION 200

// Global variables
static volatile int running = 1;
static double threshold = DEFAULT_THRESHOLD;
static double scale_factor = DEFAULT_SCALE_FACTOR;
static int duration = DEFAULT_DURATION;

// Function prototypes
int read_hx711();
double tare_hx711();
double get_weight();
void control_solenoid(int state);
void signal_handler(int signal);
void parse_arguments(int argc, char *argv[]);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    running = 0;
    control_solenoid(0); // Ensure solenoid is off
    gpioTerminate();       // Terminate pigpio
    closelog();            // Close syslog
    exit(0);
}

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int i;

    // Wait for DOUT to go low (with timeout)
    int timeout = 1000; // 1 second timeout
    while (gpioRead(HX711_DOUT) == 1 && timeout > 0) {
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        syslog(LOG_ERR, "HX711 DOUT timeout");
        return -1; // Indicate error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Apply one more clock pulse for gain 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to tare the HX711
double tare_hx711() {
    double sum = 0.0;
    int i, reading;

    // Average 10 readings
    for (i = 0; i < 10; i++) {
        reading = read_hx711();
        if (reading == -1) {
            syslog(LOG_ERR, "Tare failed: HX711 read error");
            return -1.0; // Indicate error
        }
        sum += reading;
        gpioDelay(10); // Small delay between readings
    }

    return sum / 10.0;
}

// Function to get the current weight
double get_weight() {
    double sum = 0.0;
    int i, reading;

    // Average 5 readings
    for (i = 0; i < 5; i++) {
        reading = read_hx711();
        if (reading == -1) {
            syslog(LOG_ERR, "Weight read failed: HX711 read error");
            return -1.0; // Indicate error
        }
        sum += reading;
        gpioDelay(10); // Small delay between readings
    }

    return sum / 5.0;
}

// Function to control the solenoid lock
void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
}

// Function to parse command-line arguments
void parse_arguments(int argc, char *argv[]) {
    int i;
    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--threshold") == 0 && i + 1 < argc) {
            threshold = atof(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "--scale") == 0 && i + 1 < argc) {
            scale_factor = atof(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "--duration") == 0 && i + 1 < argc) {
            duration = atoi(argv[i + 1]);
            i++;
        } else {
            fprintf(stderr, "Usage: %s [--threshold <grams>] [--scale <factor>] [--duration <ms>]\n", argv[0]);
            exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Parse command-line arguments
    parse_arguments(argc, argv);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Tare the HX711
    double tare_value = tare_hx711();
    if (tare_value == -1.0) {
        syslog(LOG_ERR, "Tare failed, exiting");
        gpioTerminate();
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "Tare value: %f", tare_value);

    // Main loop
    while (running) {
        double weight = get_weight();
        if (weight == -1.0) {
            syslog(LOG_ERR, "Failed to read weight, retrying...");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Apply scale factor
        weight = (weight - tare_value) * scale_factor;

        syslog(LOG_INFO, "Weight: %f grams", weight);

        // Check if weight exceeds threshold
        if (weight > threshold) {
            syslog(LOG_INFO, "Weight exceeds threshold, activating solenoid");
            control_solenoid(1); // Activate solenoid
            gpioDelay(duration);   // Keep solenoid active for specified duration
            control_solenoid(0); // Deactivate solenoid
            syslog(LOG_INFO, "Solenoid deactivated");
        }

        gpioDelay(500); // Poll every 500 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_solenoid(0); // Ensure solenoid is off
    gpioTerminate();       // Terminate pigpio
    closelog();            // Close syslog

    return 0;
}

