#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17

struct mosquitto *mosq = NULL;

// Function to set the relay state
void set_relay_state(int state) {
    gpioWrite(GPIO_PIN, state);
    syslog(LOG_INFO, "Relay set to %s", state ? "ON" : "OFF");
}

// Callback function for when the MQTT client connects to the broker
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_HOST, MQTT_PORT);
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_connack_string(result));
    }
}

// Callback function for when the MQTT client disconnects from the broker
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "MQTT disconnected with code %d", rc);
}

// Callback function for when the MQTT client receives a message
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(payload, "ON") == 0) {
            set_relay_state(1);
        } else if (strcmp(payload, "OFF") == 0) {
            set_relay_state(0);
        } else {
            syslog(LOG_ERR, "Invalid payload received: %s", payload);
        }
    } else {
        syslog(LOG_ERR, "Empty payload received");
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    set_relay_state(0);
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO17 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set initial relay state to OFF
    set_relay_state(0);

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new MQTT client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client instance");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set callback functions
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    // Connect to the MQTT broker
    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to handle MQTT messages
    while (1) {
        rc = mosquitto_loop(mosq, -1, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT loop error: %s", mosquitto_strerror(rc));
            sleep(5);
            mosquitto_reconnect(mosq);
        }
    }

    // Cleanup (should not reach here under normal circumstances due to the signal handler)
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

