// Define GPIO pins for the servos
#define SERVO1_GPIO 7
#define SERVO2_GPIO 8
#define SERVO3_GPIO 9
#define SERVO4_GPIO 10
#define SERVO5_GPIO 11

// Define target pulse widths for each servo (in microseconds)
#define SERVO1_TARGET 1000
#define SERVO2_TARGET 1500
#define SERVO3_TARGET 2000
#define SERVO4_TARGET 500
#define SERVO5_TARGET 2500

// Define minimum and maximum pulse widths (in microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define PWM frequency (in Hz)
#define PWM_FREQUENCY 50

// Define PWM period (in microseconds)
#define PWM_PERIOD (1000000 / PWM_FREQUENCY)

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
