#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <pthread.h>
#include <time.h>

// Motor A
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18

// Motor B
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23

// Encoder A
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Encoder B
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// Target RPM
#define TARGET_RPM 50.0

// PWM Frequency
#define PWM_FREQUENCY 10000 // 10 kHz

// PI Controller Gains
#define Kp 0.5
#define Ki 0.1

// Stall Detection Time (seconds)
#define STALL_TIME 2.0

// Global Variables
volatile int encoder_a_ticks = 0;
volatile int encoder_b_ticks = 0;
double integral_a = 0.0;
double integral_b = 0.0;
double last_time_a = 0.0;
double last_time_b = 0.0;
int stall_flag_a = 0;
int stall_flag_b = 0;
pthread_mutex_t mutex_a = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t mutex_b = PTHREAD_MUTEX_INITIALIZER;

// Function Prototypes
void signal_handler(int signal);
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int ticks, double time_elapsed);
double pi_control(double setpoint, double actual, double *integral, double dt);
void set_motor_speed(int motor_pwm, int motor_dir, int duty_cycle);
void stop_motors();
void stall_detection(int encoder_ticks, double *last_time, int *stall_flag);

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);
    gpioSetMode(ENCODER_A_A, PI_INPUT);
    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR_A_PWM, 255);
    gpioSetPWMrange(MOTOR_B_PWM, 255);

    // Register interrupt handlers
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for Encoder A A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for Encoder A B\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for Encoder B A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for Encoder B B\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Get current time
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        double current_time = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

        // Stall detection
        stall_detection(encoder_a_ticks, &last_time_a, &stall_flag_a);
        stall_detection(encoder_b_ticks, &last_time_b, &stall_flag_b);

        // Calculate RPM
        double rpm_a = calculate_rpm(encoder_a_ticks, current_time - last_time_a);
        double rpm_b = calculate_rpm(encoder_b_ticks, current_time - last_time_b);

        // PI control
        double duty_cycle_a = pi_control(TARGET_RPM, rpm_a, &integral_a, current_time - last_time_a);
        double duty_cycle_b = pi_control(TARGET_RPM, rpm_b, &integral_b, current_time - last_time_b);

        // Set motor speeds
        set_motor_speed(MOTOR_A_PWM, MOTOR_A_DIR, (int)duty_cycle_a);
        set_motor_speed(MOTOR_B_PWM, MOTOR_B_DIR, (int)duty_cycle_b);

        // Print data
        printf("Motor A: RPM = %.2f, Duty Cycle = %d\n", rpm_a, (int)duty_cycle_a);
        printf("Motor B: RPM = %.2f, Duty Cycle = %d\n", rpm_b, (int)duty_cycle_b);

        // Update last time
        last_time_a = current_time;
        last_time_b = current_time;

        // Reset encoder ticks
        pthread_mutex_lock(&mutex_a);
        encoder_a_ticks = 0;
        pthread_mutex_unlock(&mutex_a);
        pthread_mutex_lock(&mutex_b);
        encoder_b_ticks = 0;
        pthread_mutex_unlock(&mutex_b);

        // Sleep for 100 ms
        gpioDelay(100000); // 100 ms
    }

    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Stopping motors and exiting.\n");
    stop_motors();
    gpioTerminate();
    exit(0);
}

// Encoder A ISR
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    pthread_mutex_lock(&mutex_a);
    encoder_a_ticks++;
    pthread_mutex_unlock(&mutex_a);
}

// Encoder B ISR
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    pthread_mutex_lock(&mutex_b);
    encoder_b_ticks++;
    pthread_mutex_unlock(&mutex_b);
}

// Calculate RPM
double calculate_rpm(int ticks, double time_elapsed) {
    if (time_elapsed > 0.0) {
        return (double)ticks / time_elapsed * 60.0 / 64.0; // 64 ticks per revolution
    } else {
        return 0.0;
    }
}

// PI control
double pi_control(double setpoint, double actual, double *integral, double dt) {
    double error = setpoint - actual;
    *integral += error * dt;

    // Anti-windup
    if (*integral > 100.0) {
        *integral = 100.0;
    } else if (*integral < -100.0) {
        *integral = -100.0;
    }

    double output = Kp * error + Ki * (*integral);

    // Clamp output
    if (output > 255.0) {
        output = 255.0;
    } else if (output < 0.0) {
        output = 0.0;
    }

    return output;
}

// Set motor speed
void set_motor_speed(int motor_pwm, int motor_dir, int duty_cycle) {
    gpioPWM(motor_pwm, duty_cycle);
    gpioWrite(motor_dir, 1); // Forward direction
}

// Stop motors
void stop_motors() {
    gpioPWM(MOTOR_A_PWM, 0);
    gpioPWM(MOTOR_B_PWM, 0);
    gpioWrite(MOTOR_A_DIR, 0);
    gpioWrite(MOTOR_B_DIR, 0);
}

// Stall detection
void stall_detection(int encoder_ticks, double *last_time, int *stall_flag) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double current_time = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    if (encoder_ticks == 0) {
        if (*stall_flag == 0) {
            *last_time = current_time;
            *stall_flag = 1;
        } else {
            if (current_time - *last_time > STALL_TIME) {
                printf("Stall detected!\n");
                *stall_flag = 2; // Permanent stall
            }
        }
    } else {
        *stall_flag = 0; // Reset stall flag
    }
}

