int read_touch_sensor();
void toggle_relay();
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, turning relay OFF and exiting...\n");
        gpioWrite(RELAY_PIN, 0); // Turn relay OFF
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Function to read the touch sensor with debouncing
int read_touch_sensor() {
    int initial_state = gpioRead(TOUCH_SENSOR_PIN);
    if (initial_state != 0 && initial_state != 1) {
        fprintf(stderr, "Error reading initial touch sensor state: %d\n", initial_state);
        return -1; // Indicate an error
    }

    if (initial_state == 1) {
        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay (microseconds)
        int final_state = gpioRead(TOUCH_SENSOR_PIN);
        if (final_state != 0 && final_state != 1) {
            fprintf(stderr, "Error reading final touch sensor state: %d\n", final_state);
            return -1; // Indicate an error
        }

        if (final_state == 1) {
            // Wait for the sensor to return LOW
            while (gpioRead(TOUCH_SENSOR_PIN) == 1) {
                gpioDelay(1000); // Small delay to avoid busy-waiting
            }
            return 1; // Valid touch detected
        }
    }
    return 0; // No valid touch detected
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    log_relay_state(relay_state);
}

// Function to log the relay state with a timestamp
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    const char *state_str = (state == 1) ? "ON" : "OFF";
    printf("%s Relay is %s\n", timestamp, state_str);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

