    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Touch-activated relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int touch_detected = read_touch_sensor();
        if (touch_detected == 1) {
            toggle_relay();
        } else if (touch_detected == -1) {
            fprintf(stderr, "Error reading touch sensor, skipping toggle.\n");
        }
        gpioDelay(10000); // Sleep for 10ms (microseconds)
    }

    return 0; // This line will never be reached due to the infinite loop
}

