#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define FLOW_THRESHOLD_HIGH 5.0
#define FLOW_THRESHOLD_LOW 4.5
#define DEBOUNCE_TIME_MS 1000 // 1 second debounce

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file;
int running = 1;

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_lpm(int pulse_count);
void control_solenoid(double lpm);
void log_data(double lpm, int solenoid_state);
void signal_handler(int signal);

// Function to handle the flow sensor interrupt
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    // This ISR is triggered on both rising and falling edges.
    // We only increment the pulse count on rising edges.
    if (level == 1) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Function to calculate liters per minute (LPM)
double calculate_lpm(int pulse_count) {
    return (double)pulse_count / PULSES_PER_LITER * 60.0;
}

// Function to control the solenoid valve
void control_solenoid(double lpm) {
    static int solenoid_state = 1; // 1 = open, 0 = closed
    int new_solenoid_state = solenoid_state;

    if (lpm > FLOW_THRESHOLD_HIGH && solenoid_state == 1) {
        new_solenoid_state = 0; // Close the solenoid
    } else if (lpm < FLOW_THRESHOLD_LOW && solenoid_state == 0) {
        new_solenoid_state = 1; // Open the solenoid
    }

    if (new_solenoid_state != solenoid_state) {
        gpioWrite(SOLENOID_GPIO, new_solenoid_state);
        solenoid_state = new_solenoid_state;
        log_data(-1.0, solenoid_state); // Log solenoid state change
    }
}

// Function to log data to a file
void log_data(double lpm, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        if (lpm >= 0.0) {
            fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state ? "Open" : "Closed");
            fflush(log_file); // Ensure data is written to disk immediately
        } else {
            fprintf(log_file, "%s, Solenoid: %s\n", timestamp, solenoid_state ? "Open" : "Closed");
            fflush(log_file);
        }
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Open log file if it's not already open
    if (log_file == NULL) {
        log_file = fopen("water_flow.log", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file!\n");
        }
    }

    if (log_file != NULL) {
        log_data(-2.0, 1); // Log signal event and open solenoid
        fclose(log_file);
    }

    // Ensure solenoid is open
    gpioWrite(SOLENOID_GPIO, 1);

    // Destroy mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(SOLENOID_GPIO, PI_OUTPUT);

    // Initialize solenoid to open state
    gpioWrite(SOLENOID_GPIO, 1);

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler with debounce
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_TIME_MS, flow_sensor_isr, NULL);

    // Main loop
    while (running) {
        // Sleep for 1 second
        gpioDelay(1000); // 1000 ms = 1 second

        // Get pulse count
        int current_pulse_count;
        pthread_mutex_lock(&pulse_mutex);
        current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count
        pthread_mutex_unlock(&pulse_mutex);

        // Calculate LPM
        double lpm = calculate_lpm(current_pulse_count);

        // Control solenoid
        control_solenoid(lpm);

        // Log data
        log_data(lpm, gpioRead(SOLENOID_GPIO));
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(SOLENOID_GPIO, 1);
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();

    return 0;
}

