#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <jansson.h>
#include <errno.h>

// Configuration
#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_KNOWN_WEIGHT 100.0
#define DEFAULT_TARGET_WEIGHT 50.0
#define DEFAULT_SERVO_PIN 18
#define DEFAULT_DATA_PIN 23
#define DEFAULT_SCK_PIN 24
#define DEFAULT_PORT 12345
#define DEFAULT_IP "127.0.0.1"

// HX711 Timeout
#define HX711_TIMEOUT_ATTEMPTS 1000

// Servo Pulse Width Range
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000

// Global Variables
static volatile int running = 1;
static int socket_fd = -1;
static int calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static float known_weight = DEFAULT_KNOWN_WEIGHT;
static int servo_pin = DEFAULT_SERVO_PIN;
static int data_pin = DEFAULT_DATA_PIN;
static int sck_pin = DEFAULT_SCK_PIN;
static int port = DEFAULT_PORT;
static char ip_address[INET_ADDRSTRLEN] = DEFAULT_IP;

// Function Prototypes
void signal_handler(int signal);
int load_config();
long read_hx711();
float calibrate_weight(long raw_value);
int map_weight_to_pulse_width(float weight);
int dispense_ingredient(int pulse_width);
int log_event(const char *event_type, float target_weight, float actual_weight, const char *error_message);
int handle_client(int client_fd);

// Signal Handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Load Configuration from File
int load_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open config file %s, using defaults.\n", CONFIG_FILE);
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "calibration_factor") == 0) {
            calibration_factor = atof(value);
        } else if (strcmp(key, "known_weight") == 0) {
            known_weight = atof(value);
        } else if (strcmp(key, "servo_pin") == 0) {
            servo_pin = atoi(value);
        } else if (strcmp(key, "data_pin") == 0) {
            data_pin = atoi(value);
        } else if (strcmp(key, "sck_pin") == 0) {
            sck_pin = atoi(value);
        } else if (strcmp(key, "port") == 0) {
            port = atoi(value);
        } else if (strcmp(key, "ip_address") == 0) {
            strncpy(ip_address, value, INET_ADDRSTRLEN - 1);
            ip_address[INET_ADDRSTRLEN - 1] = '\0'; // Ensure null termination
        }
    }

    fclose(fp);
    printf("Configuration loaded from %s\n", CONFIG_FILE);
    return 0;
}

// Read from HX711 Load Cell
long read_hx711() {
    int i;
    long value = 0;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(sck_pin, PI_OUTPUT);

    // Wait for DATA pin to go low
    for (i = 0; i < HX711_TIMEOUT_ATTEMPTS; i++) {
        if (gpioRead(data_pin) == 0) {
            break;
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (i == HX711_TIMEOUT_ATTEMPTS) {
        fprintf(stderr, "Error: HX711 timeout waiting for DATA pin to go low.\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(sck_pin, 1);
        gpioDelay(1); // 1 us clock pulse
        value = value << 1;
        if (gpioRead(data_pin)) {
            value++;
        }
        gpioWrite(sck_pin, 0);
        gpioDelay(1); // 1 us clock pulse
    }

    // Apply the 25th clock pulse for gain selection (channel A, gain 128)
    gpioWrite(sck_pin, 1);
    gpioDelay(1); // 1 us clock pulse
    gpioWrite(sck_pin, 0);
    gpioDelay(1); // 1 us clock pulse

    // Two's complement conversion if negative
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return value;
}

// Calibrate Weight
float calibrate_weight(long raw_value) {
    return (float)raw_value / calibration_factor;
}

// Map Weight to Servo Pulse Width
int map_weight_to_pulse_width(float weight) {
    // Assuming a linear relationship between weight and pulse width
    // Adjust the formula as needed based on your servo and dispensing mechanism
    float pulse_width_float = SERVO_MIN_PULSE_WIDTH + (weight / DEFAULT_TARGET_WEIGHT) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH);
    int pulse_width = (int)pulse_width_float;

    // Ensure pulse width is within the valid range
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) {
        pulse_width = SERVO_MIN_PULSE_WIDTH;
    } else if (pulse_width > SERVO_MAX_PULSE_WIDTH) {
        pulse_width = SERVO_MAX_PULSE_WIDTH;
    }

    return pulse_width;
}

// Dispense Ingredient
int dispense_ingredient(int pulse_width) {
    gpioServo(servo_pin, pulse_width);
    gpioDelay(1000); // Dispense for 1 second
    gpioServo(servo_pin, 0); // Stop dispensing
    return 0;
}

// Log Event
int log_event(const char *event_type, float target_weight, float actual_weight, const char *error_message) {
    json_t *root = json_object();
    json_t *timestamp = json_string(NULL);
    json_t *event = json_string(event_type);
    json_t *target = json_real(target_weight);
    json_t *actual = json_real(actual_weight);
    json_t *error = json_string(error_message);

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp_str[64];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", &tm);
    json_string_set(timestamp, timestamp_str);

    json_object_set_new(root, "timestamp", timestamp);
    json_object_set_new(root, "event", event);
    json_object_set_new(root, "target_weight", target);
    json_object_set_new(root, "actual_weight", actual);
    json_object_set_new(root, "error", error);

    json_t *array = json_load_file(LOG_FILE, 0, NULL);
    if (!array) {
        array = json_array();
    }

    json_array_append_new(array, root);

    if (json_dump_file(array, LOG_FILE, JSON_INDENT(4)) != 0) {
        fprintf(stderr, "Error: Could not write to log file %s\n", LOG_FILE);
        json_decref(array);
        json_decref(root);
        return -1;
    }

    json_decref(array);
    json_decref(root);
    return 0;
}

// Handle Client Connection
int handle_client(int client_fd) {
    char buffer[1024];
    ssize_t bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Error receiving data");
        return -1;
    }
    buffer[bytes_received] = '\0';

    float target_weight;
    if (sscanf(buffer, "%f", &target_weight) != 1) {
        fprintf(stderr, "Error: Invalid target weight received: %s\n", buffer);
        const char *error_message = "Invalid target weight";
        log_event("ERROR", target_weight, 0.0, error_message);
        const char *response = "Invalid target weight";
        send(client_fd, response, strlen(response), 0);
        close(client_fd);
        return -1;
    }

    printf("Received target weight: %.2f grams\n", target_weight);

    // Dispensing Process
    long raw_value = read_hx711();
    if (raw_value == -1) {
        const char *error_message = "HX711 timeout";
        log_event("ERROR", target_weight, 0.0, error_message);
        const char *response = "HX711 timeout";
        send(client_fd, response, strlen(response), 0);
        close(client_fd);
        return -1;
    }

    float actual_weight = calibrate_weight(raw_value);

    int pulse_width = map_weight_to_pulse_width(target_weight);

    if (dispense_ingredient(pulse_width) != 0) {
        const char *error_message = "Dispensing failed";
        log_event("ERROR", target_weight, actual_weight, error_message);
        const char *response = "Dispensing failed";
        send(client_fd, response, strlen(response), 0);
        close(client_fd);
        return -1;
    }

    // Log the dispensing event
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Dispensed %.2f grams (Target: %.2f)", actual_weight, target_weight);
    log_event("DISPENSE", target_weight, actual_weight, NULL);

    // Send actual weight back to client
    char response[64];
    snprintf(response, sizeof(response), "%.2f", actual_weight);
    send(client_fd, response, strlen(response), 0);

    close(client_fd);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Load configuration
    if (load_config() != 0) {
        fprintf(stderr, "Warning: Using default configuration values.\n");
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        perror("Error creating socket");
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = inet_addr(ip_address);
    address.sin_port = htons(port);

    if (bind(socket_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Error binding socket");
        close(socket_fd);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(socket_fd, 3) < 0) {
        perror("Error listening on socket");
        close(socket_fd);
        gpioTerminate();
        return 1;
    }

    printf("Listening on %s:%d...\n", ip_address, port);

    // Main loop
    while (running) {
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        int client_fd = accept(socket_fd, (struct sockaddr *)&client_address, &client_len);
        if (client_fd < 0) {
            perror("Error accepting connection");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        if (handle_client(client_fd) != 0) {
            fprintf(stderr, "Error handling client connection.\n");
        }
    }

    // Clean up
    close(socket_fd);
    gpioTerminate();

    printf("Exiting cleanly.\n");
    return 0;
}

