#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Default debounce interval in milliseconds
#define DEFAULT_DEBOUNCE_INTERVAL 50

// Global variables
static volatile int running = 1;
static int debounce_interval = DEFAULT_DEBOUNCE_INTERVAL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_relay();
void log_relay_state(int state);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay state
void toggle_relay() {
    static int relay_state = 0; // 0 = OFF, 1 = ON
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    log_relay_state(relay_state);
}

// Function to log the relay state with a timestamp
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (state == 1) {
