#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180

static struct termios old_termios;
static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the terminal for raw input
int init_terminal() {
    struct termios new_termios;

    if (tcgetattr(STDIN_FILENO, &old_termios) != 0) {
        perror("tcgetattr");
        return -1;
    }

    new_termios = old_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    new_termios.c_cc[VMIN] = 0;  // Non-blocking read
    new_termios.c_cc[VTIME] = 0; // No timeout

    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) != 0) {
        perror("tcsetattr");
        return -1;
    }

    return 0;
}

// Function to restore the terminal settings
void restore_terminal() {
    tcsetattr(STDIN_FILENO, TCSANOW, &old_termios);
}

// Function to calculate pulse width from angle
int angle_to_pulse_width(int angle) {
    return (int)(((float)(angle) / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH);
}

// Function to set the servo pulse width using pigpio
int set_servo_pulse_width(int pulse_width) {
    int result = gpioPWM(SERVO_PIN, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting PWM: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to update the servo angle
int update_servo_angle(int current_angle, char input) {
    int new_angle = current_angle;

    if (input == '+') {
        new_angle += 10;
    } else if (input == '-') {
        new_angle -= 10;
    }

    if (new_angle < MIN_ANGLE) {
        new_angle = MIN_ANGLE;
    } else if (new_angle > MAX_ANGLE) {
        new_angle = MAX_ANGLE;
    }

    return new_angle;
}

int main() {
    int current_angle = 90;
    int pulse_width;
    char input;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Initialize terminal
    if (init_terminal() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read input
        input = getchar();

        // Update servo angle
        current_angle = update_servo_angle(current_angle, input);

        // Calculate pulse width
        pulse_width = angle_to_pulse_width(current_angle);

        // Set servo pulse width
        if (set_servo_pulse_width(pulse_width) != 0) {
            running = 0; // Exit loop on error
        }

        // Print current angle
        printf("Current angle: %d\n", current_angle);

        // Exit on 'q'
        if (input == 'q') {
            running = 0;
        }
    }

    // Stop PWM
    gpioPWM(SERVO_PIN, 0);

    // Restore terminal settings
    restore_terminal();

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

