#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define RPM_INTERVAL_SEC 5

static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold the last interrupt time
typedef struct {
    struct timespec last_interrupt_time;
} interrupt_data_t;

interrupt_data_t interrupt_data = {{0, 0}};

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, exiting gracefully.\n");
    running = 0;
}

// Function to initialize the pigpio library and GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    return 0;
}

// Function to set up the interrupt handler
int setup_interrupt() {
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, DEBOUNCE_MS, pulse_counter, &interrupt_data) != 0) {
        fprintf(stderr, "Failed to set up interrupt handler\n");
        return -1;
    }
    return 0;
}

// Interrupt handler function
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    // Debounce check
    double time_diff_ms = (current_time.tv_sec - interrupt_data.last_interrupt_time.tv_sec) * 1000.0 +
                          (current_time.tv_nsec - interrupt_data.last_interrupt_time.tv_nsec) / 1000000.0;

    if (time_diff_ms >= DEBOUNCE_MS) {
        pulse_count++;
        interrupt_data.last_interrupt_time = current_time;
    }
}

// Function to calculate RPM
double calculate_rpm() {
    return (double)pulse_count / RPM_INTERVAL_SEC * 60.0;
}

// Function to log RPM data to a file
int log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
        fflush(log_file);
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }
}

// Function to print RPM to stdout
void print_rpm(double rpm) {
    printf("RPM: %.2f\n", rpm);
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up interrupt handler
    if (setup_interrupt() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motor_rpm.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    time_t start_time, current_time;
    time(&start_time);

    // Main loop
    while (running) {
        time(&current_time);
        if (difftime(current_time, start_time) >= RPM_INTERVAL_SEC) {
            // Calculate RPM
            double rpm = calculate_rpm();

            // Log RPM
            if (log_rpm(rpm) != 0) {
                fprintf(stderr, "Failed to log RPM\n");
            }

            // Print RPM
            print_rpm(rpm);

            // Reset pulse count
            pulse_count = 0;

            // Update start time
            time(&start_time);
        }
        gpioDelay(100); // Check every 100ms
    }

    // Clean up
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    fclose(log_file);
    gpioTerminate();

    return 0;
}

