#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define DEBOUNCE_DELAY_MS 50
#define LONG_PRESS_DURATION_S 10

// Global variables
volatile sig_atomic_t terminate = 0;
int relay_state = 0; // 0 = OFF, 1 = ON
time_t touch_start_time = 0;

// Function prototypes
int read_touch_sensor();
void control_relay(int state);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read the touch sensor with debouncing
int read_touch_sensor() {
    int i, reading;
    int sum = 0;

    for (i = 0; i < 5; i++) {
        reading = gpioRead(TOUCH_SENSOR_PIN);
        if (reading < 0) {
            fprintf(stderr, "Error reading touch sensor: %d\n", reading);
            return -1; // Indicate error
        }
        sum += reading;
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    }

    // Return 1 if the majority of readings are HIGH, 0 otherwise
    return (sum >= 3) ? 1 : 0;
}

// Function to control the relay
void control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Error writing to relay pin\n");
    }
    relay_state = state;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    control_relay(0); // Turn off the relay
    gpioTerminate();   // Terminate pigpio
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting touch sensor pin mode\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting relay pin mode\n");
        cleanup();
        return 1;
    }

    // Set pull-down resistor on the touch sensor pin
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int touch_detected = read_touch_sensor();

        if (touch_detected > 0) {
            if (touch_start_time == 0) {
                touch_start_time = time(NULL);
            }

            if (time(NULL) - touch_start_time >= LONG_PRESS_DURATION_S) {
                printf("Long press detected. Turning relay OFF.\n");
                control_relay(0);
                touch_start_time = 0; // Reset touch start time
            } else {
                // Toggle relay state on rising edge
                if (relay_state == 0) {
                    control_relay(1);
                    printf("Relay turned ON\n");
