#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define PWM frequency
#define PWM_FREQUENCY 1000 // Hz

// Define proportional gain
#define KP 1.0

// Define sampling period
#define SAMPLING_PERIOD_MS 100

// Global variables
volatile int pulse_count = 0;
double target_flow_rate = 0.0;
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_flow_rate();
double calculate_pwm_duty_cycle(double flow_rate);
void set_valve_position(double duty_cycle);
void log_data(double flow_rate, double duty_cycle);
void signal_handler(int signal);
void cleanup();

// Interrupt service routine for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set valve enable pin as output and set high
    gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT);
    gpioWrite(VALVE_ENABLE_PIN, 1);

    // Set flow sensor pin as input with pull-down resistor
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_DOWN);

    // Set PWM frequency for valve control
    gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_PWM_PIN, 255); // Set PWM range to 0-255

    // Register interrupt handler for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for flow sensor\n");
        cleanup();
        exit(1);
    }

    return 0;
}

// Function to calculate flow rate (L/min) from pulse count
double calculate_flow_rate() {
    // YF-S201 flow sensor: 450 pulses per L
    double flow_rate = (double)pulse_count / 450.0 * (1000.0 / SAMPLING_PERIOD_MS); // L/min
    pulse_count = 0; // Reset pulse count
    return flow_rate;
}

// Function to calculate PWM duty cycle based on flow rate
double calculate_pwm_duty_cycle(double flow_rate) {
    double error = target_flow_rate - flow_rate;
    double duty_cycle = KP * error;

    // Clamp duty cycle to 0-255 range
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 255) {
        duty_cycle = 255;
    }

    return duty_cycle;
}

// Function to set valve position using PWM
void set_valve_position(double duty_cycle) {
    gpioPWM(VALVE_PWM_PIN, (int)duty_cycle);
}

// Function to log data to CSV file
void log_data(double flow_rate, double duty_cycle) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(log_file, "%ld,%.3f,%.3f\n", timestamp_ms, flow_rate, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    // Set valve position to 0
    set_valve_position(0.0);

    // Disable valve
    gpioWrite(VALVE_ENABLE_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line argument for target flow rate
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
        return 1;
    }

    if (strncmp(argv[1], "-t", 2) != 0) {
        fprintf(stderr, "Invalid argument. Use -t <target_flow_rate>\n");
        return 1;
    }

    char *flow_rate_str = argv[1] + 2; // Skip "-t "
    char *endptr;

    target_flow_rate = strtod(flow_rate_str, &endptr);

    if (*endptr != '\0' || target_flow_rate <= 0) {
        fprintf(stderr, "Invalid target flow rate. Must be a positive number.\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (running) {
        // Calculate flow rate
        double flow_rate = calculate_flow_rate();

        // Calculate PWM duty cycle
        double duty_cycle = calculate_pwm_duty_cycle(flow_rate);

        // Set valve position
        set_valve_position(duty_cycle);

        // Log data
        log_data(flow_rate, duty_cycle);

        // Wait for sampling period
        gpioDelay(SAMPLING_PERIOD_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

