#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22

// Define RFID tag
const unsigned char VALID_TAG[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};
#define TAG_LENGTH 10

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 100000 // 100 kHz

// Define debounce time (milliseconds)
#define DEBOUNCE_TIME 50

// Define lock disengage time (seconds)
#define LOCK_DISENGAGE_TIME 5

// Define log file path
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rfid(unsigned char *tag);
int validate_tag(const unsigned char *tag);
int read_button();
void control_locks(int disengage);
void log_event(const char *event);
void signal_handler(int signal);

// Function to read RFID tag from SPI
int read_rfid(unsigned char *tag) {
    char rx_buffer[10];
    int result;

    result = spiRead(spi_handle, rx_buffer, 10);
    if (result != 10) {
        log_event("RFID read failure");
        return -1; // Indicate failure
    }

    // Check for no tag present (all zeros)
    int all_zeros = 1;
    for (int i = 0; i < 10; i++) {
        if (rx_buffer[i] != 0) {
            all_zeros = 0;
            break;
        }
    }

    if (all_zeros) {
        return 0; // Indicate no tag present
    }

    memcpy(tag, rx_buffer, 10);
    return 1; // Indicate success
}

// Function to validate RFID tag
int validate_tag(const unsigned char *tag) {
    if (memcmp(tag, VALID_TAG, TAG_LENGTH) == 0) {
        return 1; // Tag is valid
    } else {
        return 0; // Tag is invalid
    }
}

// Function to read button state with debouncing
int read_button() {
    static int last_state = 1; // Initialize to released state
    static unsigned long last_debounce_time = 0;
    int current_state = gpioRead(BUTTON_PIN);
    unsigned long now = gpioTick();

    if (current_state != last_state) {
        last_debounce_time = now;
    }

    if ((now - last_debounce_time) > DEBOUNCE_TIME * 1000) { // Convert ms to us
        if (current_state == 0) { // Button is pressed (active low)
            last_state = current_state;
            return 1; // Button pressed
        }
    }

    last_state = current_state;
    return 0; // Button not pressed
}

// Function to control locks
void control_locks(int disengage) {
    if (disengage) {
        gpioWrite(LOCK1_PIN, 0); // Disengage Lock 1
        gpioWrite(LOCK2_PIN, 0); // Disengage Lock 2
        log_event("Locks disengaged");
        gpioDelay(LOCK_DISENGAGE_TIME * 1000000); // Wait for 5 seconds (microseconds)
        gpioWrite(LOCK1_PIN, 1); // Engage Lock 1
        gpioWrite(LOCK2_PIN, 1); // Engage Lock 2
        log_event("Locks re-engaged");
    } else {
        gpioWrite(LOCK1_PIN, 1); // Engage Lock 1
        gpioWrite(LOCK2_PIN, 1); // Engage Lock 2
        log_event("Locks engaged");
    }
}

// Function to log events
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, exiting...");
    control_locks(0); // Engage locks
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable internal pull-up resistor

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Door access control system started");

    unsigned char tag[TAG_LENGTH];
    int tag_valid;
    int button_pressed;

    while (!terminate) {
        // Read RFID tag
        int rfid_result = read_rfid(tag);

        if (rfid_result == 1) {
            // Validate tag
            tag_valid = validate_tag(tag);

            if (tag_valid) {
                log_event("Valid tag detected");
                // Wait for button press
                button_pressed = 0;
                while (!button_pressed && !terminate) {
                    button_pressed = read_button();
                    gpioDelay(10000); // Check every 10ms
                }

                if (button_pressed) {
                    log_event("Button pressed");
                    control_locks(1); // Disengage locks
                    log_event("Access granted");
                } else {
                    log_event("Button press required");
                }
            } else {
                log_event("Invalid tag");
            }
        } else if (rfid_result == 0) {
            // No tag present
            // Do nothing, just continue polling
        } else {
            // RFID read failure already logged
        }

        gpioDelay(100000); // Check every 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_locks(0); // Engage locks
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

