// Motor 1 GPIOs
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2 GPIOs
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1 GPIOs
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2 GPIOs
#define ENCODER2_A 26
#define ENCODER2_B 19

// Encoder pulses per revolution (PPR)
#define ENCODER_PPR 360

// Target speed (RPM)
#define TARGET_SPEED 60.0

// PWM frequency (Hz)
#define PWM_FREQUENCY 100

// PWM range (0-1000000)
#define PWM_RANGE 1000000

// PID parameters
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Sample time (ms)
#define SAMPLE_TIME 100

// Global variables
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;
double integral1 = 0.0;
double integral2 = 0.0;
double previous_error1 = 0.0;
double previous_error2 = 0.0;
double last_time1 = 0.0;
double last_time2 = 0.0;

pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

FILE *log_file = NULL;
int running = 1;

// Function prototypes
void signal_handler(int signal);
void motor1_forward(int duty_cycle);
void motor1_backward(int duty_cycle);
void motor1_stop();
void motor2_forward(int duty_cycle);
void motor2_backward(int duty_cycle);
void motor2_stop();
double calculate_rpm(int encoder_count, double time_elapsed);
double pid_control(double setpoint, double actual_speed, double *integral, double *previous_error, double dt);
void encoder1_isr(int gpio, int level, uint32_t tick, void *user);
void encoder2_isr(int gpio, int level, uint32_t tick, void *user);
void *encoder1_thread(void *arg);
void *encoder2_thread(void *arg);

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and cleaning up...\n", signal);
    running = 0;

    // Stop motors
    motor1_stop();
    motor2_stop();

    // Release GPIO lines
    gpioSetMode(MOTOR1_ENA, PI_INPUT);
    gpioSetMode(MOTOR1_IN1, PI_INPUT);
    gpioSetMode(MOTOR1_IN2, PI_INPUT);
    gpioSetMode(MOTOR2_ENB, PI_INPUT);
    gpioSetMode(MOTOR2_IN3, PI_INPUT);
    gpioSetMode(MOTOR2_IN4, PI_INPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

