    gpioWrite(MOTOR1_IN1, 1);
    gpioWrite(MOTOR1_IN2, 0);
    gpioPWM(MOTOR1_ENA, duty_cycle);
}

void motor1_backward(int duty_cycle) {
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 1);
    gpioPWM(MOTOR1_ENA, duty_cycle);
}

void motor1_stop() {
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioPWM(MOTOR1_ENA, 0);
}

void motor2_forward(int duty_cycle) {
    gpioWrite(MOTOR2_IN3, 1);
    gpioWrite(MOTOR2_IN4, 0);
    gpioPWM(MOTOR2_ENB, duty_cycle);
}

void motor2_backward(int duty_cycle) {
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 1);
    gpioPWM(MOTOR2_ENB, duty_cycle);
}

void motor2_stop() {
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);
    gpioPWM(MOTOR2_ENB, 0);
}

// RPM calculation
double calculate_rpm(int encoder_count, double time_elapsed) {
    return (double)encoder_count / ENCODER_PPR * 60.0 / time_elapsed;
}

// PID control
double pid_control(double setpoint, double actual_speed, double *integral, double *previous_error, double dt) {
    double error = setpoint - actual_speed;
    *integral += error * dt;
    double derivative = (error - *previous_error) / dt;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Encoder interrupt service routines
void encoder1_isr(int gpio, int level, uint32_t tick, void *user) {
    static int last_level_b = 0;
    int current_level_b = gpioRead(ENCODER1_B);

    pthread_mutex_lock(&encoder1_mutex);
    if (gpio == ENCODER1_A) {
        if (level == PI_HIGH) {
            if (last_level_b == 0) {
                encoder1_count++;
            } else {
                encoder1_count--;
            }
        }
    }
    pthread_mutex_unlock(&encoder1_mutex);
    last_level_b = current_level_b;
}

void encoder2_isr(int gpio, int level, uint32_t tick, void *user) {
