        pthread_mutex_lock(&encoder1_mutex);
        current_count = encoder1_count;
        pthread_mutex_unlock(&encoder1_mutex);
        pthread_mutex_lock(&encoder2_mutex);
        int current_count2 = encoder2_count;
        pthread_mutex_unlock(&encoder2_mutex);

        fprintf(log_file, "%lf,%lf,%lf,%lf,%lf,%lf,%lf,%lf\n",
                time_time(), rpm, TARGET_SPEED, pid_output, calculate_rpm(current_count2, time_elapsed), TARGET_SPEED, pid_output, calculate_rpm(current_count2, time_elapsed));
        fflush(log_file);

