int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR1_ENA, PWM_RANGE);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR2_ENB, PWM_RANGE);

    // Set PWM range for all motors
    gpioSetPWMrange(MOTOR1_ENA, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_ENB, PWM_RANGE);

    // Set PWM frequency for all motors
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);

    // Set up interrupt service routines
    gpioSetISRFuncEx(ENCODER1_A, RISING_EDGE, 0, encoder1_isr, NULL);
    gpioSetISRFuncEx(ENCODER2_A, RISING_EDGE, 0, encoder2_isr, NULL);

    // Open log file
    log_file = fopen("motor_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Encoder1_RPM,Target1,Output1,Encoder2_RPM,Target2,Output2\n");
    fflush(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create threads
    pthread_t encoder1_thread_id, encoder2_thread_id;
    pthread_create(&encoder1_thread_id, NULL, encoder1_thread, NULL);
    pthread_create(&encoder2_thread_id, NULL, encoder2_thread, NULL);

    // Wait for threads to finish
    pthread_join(encoder1_thread_id, NULL);
    pthread_join(encoder2_thread_id, NULL);

    // Clean up
    fclose(log_file);
    gpioTerminate();

    return 0;
}

