    // Open log file
    log_file = fopen("motor_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Encoder1_RPM,Target1,Output1,Encoder2_RPM,Target2,Output2\n");
    fflush(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create threads
    pthread_t encoder1_thread_id, encoder2_thread_id;
    pthread_create(&encoder1_thread_id, NULL, encoder1_thread, NULL);
    pthread_create(&encoder2_thread_id, NULL, encoder2_thread, NULL);

    // Wait for threads to finish
    pthread_join(encoder1_thread_id, NULL);
    pthread_join(encoder2_thread_id, NULL);

    // Clean up
    fclose(log_file);
    gpioTerminate();

    return 0;
}

