#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// MPR121 I2C address
#define MPR121_ADDR 0x5A

// MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_ELECTRODE0_TOUCHTH 0x41
#define MPR121_ELECTRODE0_RELEASETH 0x42

// GPIO pin for relay control
#define RELAY_PIN 17

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *status);
void control_relay(int state);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// MPR121 initialization function
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure filtering parameters
    if (i2cWriteByteData(i2c_handle, MPR121_MHDR, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NHDR, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_FDLR, 0x06) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_MHDF, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NHDF, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NCLF, 0x0E) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_FDLF, 0x06) < 0) return -1;

    // Set touch and release thresholds for each electrode
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE0_TOUCHTH + 2 * i, 0x20) < 0) return -1; // Touch threshold
        if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE0_RELEASETH + 2 * i, 0x10) < 0) return -1; // Release threshold
    }

    // Enable run mode
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x8F) < 0) {
        fprintf(stderr, "Error: Failed to enable MPR121 run mode\n");
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(uint16_t *status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    *status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
}

// Function to log events to a file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    uint16_t touch_status;
    int relay_state = 0; // 0 = LOW, 1 = HIGH

    // Main loop
    while (program_running) {
        if (read_touch_status(&touch_status) == 0) {
            // Check if any electrode is touched
            if (touch_status > 0) {
                if (relay_state == 0) {
                    control_relay(1);
                    relay_state = 1;
                    log_event("Relay set HIGH");
                }
            } else {
                if (relay_state == 1) {
                    control_relay(0);
                    relay_state = 0;
                    log_event("Relay set LOW");
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
            log_event("Error: Failed to read touch status");
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Clean up
    control_relay(0); // Ensure relay is LOW on exit
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

