// Define GPIO pins for the valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define valve activation durations and delays (in milliseconds)
#define VALVE1_DURATION 500
#define VALVE1_DELAY 5000
#define VALVE2_DURATION 1000
#define VALVE2_DELAY 10000

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void activate_valve(int gpio_pin, int duration_ms);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(VALVE1_GPIO, PI_OUTPUT);
    gpioSetMode(VALVE2_GPIO, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to activate a valve for a specified duration
void activate_valve(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Open the valve
    gpioDelay(duration_ms * 1000); // Delay for the specified duration (in microseconds)
    gpioWrite(gpio_pin, 0); // Close the valve
}

// Function to log an event to the valve_log.txt file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", buf, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(VALVE1_GPIO, 0); // Ensure Valve 1 is closed
    gpioWrite(VALVE2_GPIO, 0); // Ensure Valve 2 is closed
    gpioTerminate(); // Terminate the pigpio library

    if (log_file != NULL) {
        fclose(log_file); // Close the log file
    }
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file
    log_file = fopen("valve_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Water distribution schedule started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Activate Valve 1
        printf("Activating Valve 1 for %d ms...\n", VALVE1_DURATION);
        activate_valve(VALVE1_GPIO, VALVE1_DURATION);
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Valve 1 activated for %d ms", VALVE1_DURATION);
        log_event(log_message);
        printf("Valve 1 activated. Waiting for %d ms...\n", VALVE1_DELAY);
        gpioDelay(VALVE1_DELAY * 1000); // Delay after Valve 1 activation

        // Activate Valve 2
        printf("Activating Valve 2 for %d ms...\n", VALVE2_DURATION);
        activate_valve(VALVE2_GPIO, VALVE2_DURATION);
