        log_event(log_message);
        printf("Valve 2 activated. Waiting for %d ms...\n", VALVE2_DELAY);
        gpioDelay(VALVE2_DELAY * 1000); // Delay after Valve 2 activation
    }

    // Perform cleanup before exiting
    cleanup();

    printf("Water distribution schedule stopped.\n");
    return 0;
}

