#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define RELAY_PIN 18

// Define constants
#define RELAY_ACTIVATION_TIME 500 // milliseconds
#define RATE_LIMIT_TIME 2000      // milliseconds
#define POLLING_INTERVAL 50       // milliseconds

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void activate_relay();
void log_event(const char *event_type);
void rate_limit();
void cleanup();
void signal_handler(int signal);

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_PIN, PI_PUD_DOWN);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0; // Indicate success
}

// Function to read the PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Function to activate the relay for a specified duration
void activate_relay() {
    gpioWrite(RELAY_PIN, 1); // Activate relay
    gpioDelay(RELAY_ACTIVATION_TIME * 1000); // Delay for activation time (in microseconds)
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
}

// Function to log an event to the log file
void log_event(const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file); // Ensure the log is written immediately
}

// Function to enforce rate limiting
void rate_limit() {
    gpioDelay(RATE_LIMIT_TIME * 1000); // Delay for rate limit time (in microseconds)
}

// Function to handle program cleanup
void cleanup() {
    printf("Cleaning up and exiting...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("SIGINT received.  Shutting down...\n");
        running = 0; // Set the running flag to 0 to exit the main loop
        cleanup();    // Call the cleanup function
    }
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if GPIO initialization fails
    }

    // Open the log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate(); // Terminate pigpio
        return 1;        // Exit if log file opening fails
    }

    int last_pir_state = 0; // Store the last PIR sensor state

    // Main loop
    while (running) {
        int pir_state = read_pir_sensor();

        // Detect rising edge (0 to 1)
        if (pir_state == 1 && last_pir_state == 0) {
            log_event("Motion Detected");
            activate_relay();
            log_event("Door Unlocked");
            rate_limit();
            log_event("Rate Limited");
        }

        last_pir_state = pir_state; // Update the last PIR sensor state
        gpioDelay(POLLING_INTERVAL * 1000); // Delay for polling interval (in microseconds)
    }

    cleanup(); // Call cleanup before exiting
    return 0;
}

