#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define the number of steps in a pattern
#define MIN_STEPS 5
#define MAX_STEPS 15

// Define the duration of each step in milliseconds
#define MIN_DURATION 50
#define MAX_DURATION 200

// Define the PWM range
#define PWM_RANGE 255

// Define the PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Global flag to signal shutdown
volatile sig_atomic_t shutdown_flag = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, shutting down...\n");
        shutdown_flag = 1;
    }
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR2_GPIO);
        gpioTerminate();
        return -1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", MOTOR1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", MOTOR2_GPIO);
        gpioTerminate();
        return -1;
    }

    // Set PWM range
    if (gpioSetPWMrange(MOTOR1_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", MOTOR1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(MOTOR2_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", MOTOR2_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to generate a random haptic feedback pattern
int generate_pattern(int *motor1_duties, int *motor2_duties, int *durations, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        // Generate random duty cycle for each motor
        motor1_duties[i] = rand() % (PWM_RANGE + 1);
        motor2_duties[i] = rand() % (PWM_RANGE + 1);

        // Generate random duration for each step
        durations[i] = (rand() % (MAX_DURATION - MIN_DURATION + 1)) + MIN_DURATION;
    }
    return 0;
}

// Function to play a haptic feedback pattern
void play_pattern(int *motor1_duties, int *motor2_duties, int *durations, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        // Set PWM duty cycle for each motor
        gpioPWM(MOTOR1_GPIO, motor1_duties[i]);
        gpioPWM(MOTOR2_GPIO, motor2_duties[i]);

        // Wait for the specified duration
        gpioDelay(durations[i] * 1000); // Convert ms to us
    }
}

// Function to stop the motors
void stop_motors() {
    gpioPWM(MOTOR1_GPIO, 0);
    gpioPWM(MOTOR2_GPIO, 0);
}

// Function to clean up and terminate the pigpio library
void cleanup() {
    stop_motors();
    gpioTerminate();
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Haptic feedback generator started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!shutdown_flag) {
        // Generate a random number of steps
        int num_steps = (rand() % (MAX_STEPS - MIN_STEPS + 1)) + MIN_STEPS;

        // Allocate memory for the pattern
        int *motor1_duties = (int *)malloc(num_steps * sizeof(int));
        int *motor2_duties = (int *)malloc(num_steps * sizeof(int));
        int *durations = (int *)malloc(num_steps * sizeof(int));

        if (motor1_duties == NULL || motor2_duties == NULL || durations == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            cleanup();
            return 1;
        }

        // Generate the pattern
        if (generate_pattern(motor1_duties, motor2_duties, durations, num_steps) != 0) {
            fprintf(stderr, "Pattern generation failed\n");
            free(motor1_duties);
            free(motor2_duties);
            free(durations);
            cleanup();
            return 1;
        }

        // Play the pattern
        play_pattern(motor1_duties, motor2_duties, durations, num_steps);

        // Free the allocated memory
        free(motor1_duties);
        free(motor2_duties);
        free(durations);
    }

    // Clean up and terminate
    cleanup();

    printf("Haptic feedback generator stopped.\n");

    return 0;
}

