}

// Function to clean up and terminate the pigpio library
void cleanup() {
    stop_motors();
    gpioTerminate();
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Haptic feedback generator started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!shutdown_flag) {
        // Generate a random number of steps
        int num_steps = (rand() % (MAX_STEPS - MIN_STEPS + 1)) + MIN_STEPS;

        // Allocate memory for the pattern
        int *motor1_duties = (int *)malloc(num_steps * sizeof(int));
        int *motor2_duties = (int *)malloc(num_steps * sizeof(int));
        int *durations = (int *)malloc(num_steps * sizeof(int));

        if (motor1_duties == NULL || motor2_duties == NULL || durations == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            cleanup();
            return 1;
        }

        // Generate the pattern
        if (generate_pattern(motor1_duties, motor2_duties, durations, num_steps) != 0) {
            fprintf(stderr, "Pattern generation failed\n");
            free(motor1_duties);
            free(motor2_duties);
            free(durations);
            cleanup();
            return 1;
        }

        // Play the pattern
        play_pattern(motor1_duties, motor2_duties, durations, num_steps);

        // Free the allocated memory
        free(motor1_duties);
        free(motor2_duties);
        free(durations);
    }

    // Clean up and terminate
    cleanup();

    printf("Haptic feedback generator stopped.\n");

    return 0;
}

