#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define weight threshold
#define WEIGHT_THRESHOLD 10.0

// Define calibration file name
#define CALIBRATION_FILE "calibration.txt"

// Define log file name
#define LOG_FILE "weight_log.txt"

// Global variables
double scale_factor = 1.0;
double offset = 0.0;
FILE *log_file = NULL;
FILE *calibration_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value);
void control_solenoid(double weight);
void load_calibration();
void save_calibration();
void startup_calibration();
void log_data(int raw_value, double weight);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data line to go low
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < 100) {
        gpioDelay(1000); // 1 ms delay
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "Error: HX711 timeout waiting for data line to go low.\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Short delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Short delay
    }

    // Apply the 25th clock pulse for gain selection (default gain = 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // Short delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // Short delay

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return data;
}

// Function to calculate weight from raw value
double calculate_weight(int raw_value) {
    return (raw_value - offset) / scale_factor;
}

// Function to control the solenoid lock
void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Engage solenoid
        printf("Weight above threshold. Engaging solenoid.\n");
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Disengage solenoid
        printf("Weight below threshold. Disengaging solenoid.\n");
    }
}

// Function to load calibration data from file
void load_calibration() {
    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        fprintf(stderr, "Warning: Could not open calibration file. Using default values.\n");
        return;
    }

    if (fscanf(calibration_file, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Warning: Invalid calibration data. Using default values.\n");
        fclose(calibration_file);
        return;
    }

    fclose(calibration_file);
    printf("Calibration data loaded: scale_factor = %lf, offset = %lf\n", scale_factor, offset);
}

// Function to save calibration data to file
void save_calibration() {
    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return;
    }

    fprintf(calibration_file, "%lf %lf", scale_factor, offset);
    fclose(calibration_file);
    printf("Calibration data saved: scale_factor = %lf, offset = %lf\n", scale_factor, offset);
}

// Function to perform startup calibration
void startup_calibration() {
    printf("Starting startup calibration...\n");
    double sum = 0.0;
    int raw_value;
    int i;

    for (i = 0; i < 100; i++) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: HX711 timeout during startup calibration. Skipping.\n");
            return;
        }
        sum += raw_value;
        gpioDelay(10000); // 10 ms delay
    }

    offset = sum / 100.0;
    printf("Startup calibration complete. Offset = %lf\n", offset);
}

// Function to log data to file
void log_data(int raw_value, double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Raw: %d, Weight: %.2lf kg\n", timestamp, raw_value, weight);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Load calibration data
    load_calibration();

    // Perform startup calibration
    startup_calibration();

    // Set solenoid pin as output
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0); // Initialize solenoid to disengaged state

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        gpioTerminate();
        return 1;
    }

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = calculate_weight(raw_value);
            control_solenoid(weight);
            log_data(raw_value, weight);
        } else {
            fprintf(stderr, "Error: HX711 read failed. Skipping iteration.\n");
        }

        gpioDelay(500000); // 500 ms delay
    }

    // Clean up
    gpioWrite(SOLENOID_PIN, 0); // Disengage solenoid
    fclose(log_file);
    gpioTerminate();

    printf("Weight monitoring stopped.\n");
    return 0;
}

