#include <string.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define PWM frequency and duty cycle
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150

// Define debounce parameters
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_MS 50

// Define rain threshold
#define RAIN_THRESHOLD 3

// Define motor run time
#define MOTOR_RUN_TIME 5 // seconds

// Global flag for program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
int debounce_rain_sensor();
void control_motor(int rain_detected);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
    closelog();
    exit(0);
}

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to debounce the rain sensor
int debounce_rain_sensor() {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (read_rain_sensor() == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    }
    return (low_count >= RAIN_THRESHOLD) ? 1 : 0;
}

// Function to control the motor
void control_motor(int rain_detected) {
    if (rain_detected) {
        log_event("Rain detected, closing window...");
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, PWM_DUTY_CYCLE);
        gpioDelay(MOTOR_RUN_TIME * 1000000); // Run for MOTOR_RUN_TIME seconds
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, 0);
        log_event("Window closed.");
    } else {
        log_event("No rain detected.");
    }
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, message);
    syslog(LOG_INFO, "%s", log_message);
}

int main() {
    // Initialize syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started.");

    // Main loop
    while (program_running) {
        int rain_detected = debounce_rain_sensor();
        control_motor(rain_detected);
        gpioDelay(60000000); // Check every 60 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
    closelog();
    return 0;
}

