static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
void activate_solenoid();
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int dt_pin;
    int sck_pin;
    int solenoid_pin;
    float weight_threshold;
    int timeout_ms;
} Config;

Config config = {HX711_DT, HX711_SCK, SOLENOID_PIN, WEIGHT_THRESHOLD, HX711_TIMEOUT};

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int i;
    long start_time;

    gpioSetMode(config.dt_pin, PI_INPUT);
    gpioSetMode(config.sck_pin, PI_OUTPUT);

    // Wait for DT to go low (data ready)
    start_time = time_time();
    while (gpioRead(config.dt_pin) == 1) {
        if (time_time() - start_time > config.timeout_ms / 1000.0) {
            log_event("Error: HX711 timeout waiting for data.");
            return -1; // Timeout
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(config.sck_pin, 1);
