#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define TIMEOUT_MS 100
#define SOLENOID_ACTIVE_TIME 5 // seconds
#define WEIGHT_THRESHOLD 5.0   // kg

// Global variables
static volatile int running = 1;
static FILE *calibration_file = NULL;
static FILE *security_log_file = NULL;
static double calibration_factor = 0.0;

// Function prototypes
int read_hx711();
double calibrate_hx711(double known_weight);
double get_weight();
void control_solenoid(int state);
void log_security_event(double weight);
void signal_handler(int signal);
int load_calibration();
int save_calibration(double factor);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    control_solenoid(0); // Unlock the solenoid
    if (calibration_file != NULL) {
        fclose(calibration_file);
    }
    if (security_log_file != NULL) {
        fclose(security_log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data line to go low
    int timeout_count = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_count < TIMEOUT_MS) {
        gpioDelay(1); // 1 ms delay
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_MS) {
        fprintf(stderr, "Error: HX711 timeout waiting for data line to go low.\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // 1 us delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // 1 us delay
    }

    // Apply the 25th clock pulse for gain 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // 1 us delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // 1 us delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calibrate the HX711
double calibrate_hx711(double known_weight) {
    int raw_value;
    double calibration_factor;

    printf("Place the known weight (%.2f kg) on the load cell and press Enter.\n", known_weight);
    getchar(); // Wait for user input

    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: Calibration failed due to HX711 timeout.\n");
        return -1.0; // Indicate calibration failure
    }

    calibration_factor = (double)raw_value / known_weight;

    printf("Calibration factor: %.2f\n", calibration_factor);

    if (save_calibration(calibration_factor) != 0) {
        fprintf(stderr, "Error: Failed to save calibration factor.\n");
    }

    return calibration_factor;
}

// Function to get the calibrated weight
double get_weight() {
    int raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: Failed to read raw value.\n");
        return -1.0; // Indicate error
    }
    return (double)raw_value / calibration_factor;
}

// Function to control the solenoid
void control_solenoid(int state) {
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, state);
}

// Function to log security events
void log_security_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (security_log_file == NULL) {
        security_log_file = fopen(SECURITY_LOG_FILE, "a");
        if (security_log_file == NULL) {
            fprintf(stderr, "Error: Could not open security log file for writing.\n");
            return;
        }
    }

    fprintf(security_log_file, "%s, Weight: %.2f kg\n", timestamp, weight);
    fflush(security_log_file); // Ensure data is written to disk
}

// Function to load calibration factor from file
int load_calibration() {
    if (calibration_file == NULL) {
        calibration_file = fopen(CALIBRATION_FILE, "r");
        if (calibration_file == NULL) {
            fprintf(stderr, "Warning: Could not open calibration file for reading. Using default calibration.\n");
            return -1; // Indicate failure to open file
        }
    }

    if (fscanf(calibration_file, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Warning: Could not read calibration factor from file. Using default calibration.\n");
        fclose(calibration_file);
        calibration_file = NULL;
        return -1; // Indicate failure to read calibration
    }

    fclose(calibration_file);
    calibration_file = NULL;

    printf("Calibration factor loaded: %.2f\n", calibration_factor);
    return 0; // Indicate success
}

// Function to save calibration factor to file
int save_calibration(double factor) {
    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return -1; // Indicate failure to open file
    }

    fprintf(calibration_file, "%.2f", factor);
    fclose(calibration_file);
    calibration_file = NULL;
    return 0; // Indicate success
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Load calibration factor from file
    if (load_calibration() != 0) {
        // If loading fails, prompt for calibration
        double known_weight;
        printf("Calibration factor not found. Please enter a known weight in kg: ");
        if (scanf("%lf", &known_weight) != 1) {
            fprintf(stderr, "Error: Invalid input for known weight.\n");
            gpioTerminate();
            return 1;
        }
        calibration_factor = calibrate_hx711(known_weight);
        if (calibration_factor == -1.0) {
            fprintf(stderr, "Error: Calibration failed.\n");
            gpioTerminate();
            return 1;
        }
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        double weight = get_weight();
        if (weight >= 0) {
            printf("Weight: %.2f kg\n", weight);

            if (weight > WEIGHT_THRESHOLD) {
                printf("Weight threshold exceeded! Engaging solenoid.\n");
                control_solenoid(1); // Lock the door
                log_security_event(weight);
                sleep(SOLENOID_ACTIVE_TIME);
                control_solenoid(0); // Unlock the door
                printf("Solenoid deactivated.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to get weight.\n");
        }

        gpioDelay(100); // Sample every 100 ms
    }

    // Cleanup (should not reach here if signal handler is working)
    control_solenoid(0); // Unlock the solenoid
    if (calibration_file != NULL) {
        fclose(calibration_file);
    }
    if (security_log_file != NULL) {
        fclose(security_log_file);
    }
    gpioTerminate();

    return 0;
}

