int read_pir_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading PIR sensor on GPIO %d\n", gpio_pin);
        return -1; // Indicate error
    }
    return value;
}

// Function to activate the buzzer for a specified duration
void activate_buzzer(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Turn buzzer on
    usleep(duration_ms * 1000); // Wait for specified duration
    gpioWrite(gpio_pin, 0); // Turn buzzer off
}

// Function to log motion detection with timestamp
void log_motion(const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", timestamp);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0; // Stop the main loop

    // Turn off the buzzer
    gpioWrite(BUZZER_PIN, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Open the log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int motion_detected = read_pir_sensor(PIR_SENSOR_PIN);
        if (motion_detected == 1) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20]; // YYYY-MM-DD HH:MM:SS\0

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the motion
            log_motion(timestamp);

            // Activate the buzzer
            activate_buzzer(BUZZER_PIN, BUZZER_DURATION_MS);

            printf("Motion detected at %s\n", timestamp);
        } else if (motion_detected < 0) {
            // Error reading sensor, exit
            break;
        }

        usleep(100000); // Check every 100ms
    }

    // Cleanup (in case the loop exited without a signal)
    gpioWrite(BUZZER_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

