#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"
#define MAX_DURATION 3600

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d). Terminating program.\n", sig);
    terminate = 1;
}

// Function to read the watering duration from the configuration file
int read_duration(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening configuration file: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        if (feof(fp)) {
            fprintf(stderr, "Error: Configuration file is empty.\n");
        } else {
            fprintf(stderr, "Error reading from configuration file: %s\n", strerror(errno));
        }
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *key = strtok(line, "=");
    char *value = strtok(NULL, "=");

    if (key == NULL || value == NULL || strcmp(key, "duration") != 0) {
        fprintf(stderr, "Error: Invalid configuration file format. Expected 'duration=<seconds>'.\n");
        return -1;
    }

    char *endptr;
    long duration = strtol(value, &endptr, 10);

    if (*endptr != '\0' || duration < 1 || duration > MAX_DURATION) {
        fprintf(stderr, "Error: Invalid duration value. Must be an integer between 1 and %d.\n", MAX_DURATION);
        return -1;
    }

    return (int)duration;
}

// Function to initialize the GPIO pin
int initialize_gpio(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n", pin, strerror(errno));
        return -1;
    }

    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error setting GPIO %d to LOW: %s\n", pin, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to activate the valve
int activate_valve(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error setting GPIO %d to HIGH: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to deactivate the valve
int deactivate_valve(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error setting GPIO %d to LOW: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to perform a signal-safe sleep
void safe_sleep(int seconds) {
    struct timespec req, rem;
    req.tv_sec = seconds;
    req.tv_nsec = 0;

    while (nanosleep(&req, &rem) == -1) {
        if (errno == EINTR) {
            req = rem;
        } else {
            fprintf(stderr, "Error during sleep: %s\n", strerror(errno));
            break;
        }
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error setting GPIO %d to LOW during cleanup: %s\n", pin, strerror(errno));
    }
    gpioSetMode(pin, PI_INPUT); // Set back to input to avoid issues
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Read watering duration from configuration file
    int duration = read_duration(CONFIG_FILE);
    if (duration == -1) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO pin
    if (initialize_gpio(GPIO_PIN) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Watering duration: %d seconds\n", duration);

    // Activate the valve
    if (activate_valve(GPIO_PIN) != 0) {
        cleanup_gpio(GPIO_PIN);
        gpioTerminate();
        return 1;
    }
    printf("Valve ON\n");

    // Wait for the specified duration
    safe_sleep(duration);

    // Deactivate the valve
    if (deactivate_valve(GPIO_PIN) != 0) {
        cleanup_gpio(GPIO_PIN);
        gpioTerminate();
        return 1;
    }
    printf("Valve OFF\n");

    // Cleanup GPIO resources
    cleanup_gpio(GPIO_PIN);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

