#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27
#define LEFT_MOTOR_FORWARD 22
#define LEFT_MOTOR_BACKWARD 23
#define RIGHT_MOTOR_FORWARD 24
#define RIGHT_MOTOR_BACKWARD 25

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Define base motor speed
#define BASE_SPEED 150

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_sensor(int gpio);
void set_motor_speed(int forward_gpio, int backward_gpio, int speed);
void stop_motors();
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_motor_speed, int right_motor_speed);
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to set motor speed
void set_motor_speed(int forward_gpio, int backward_gpio, int speed) {
    gpioPWM(forward_gpio, speed);
    gpioPWM(backward_gpio, 0); // Ensure backward is off
}

// Function to stop motors
void stop_motors() {
    gpioPWM(LEFT_MOTOR_FORWARD, 0);
    gpioPWM(LEFT_MOTOR_BACKWARD, 0);
    gpioPWM(RIGHT_MOTOR_FORWARD, 0);
    gpioPWM(RIGHT_MOTOR_BACKWARD, 0);
}

// Function to log data
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_motor_speed, int right_motor_speed) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tstruct);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", buf, left_sensor, middle_sensor, right_sensor, left_motor_speed, right_motor_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Stopping motors and exiting.\n");
    running = 0;
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetMode(LEFT_MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_BACKWARD, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_BACKWARD, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LEFT_MOTOR_FORWARD, PWM_FREQUENCY);
    gpioSetPWMfrequency(LEFT_MOTOR_BACKWARD, PWM_FREQUENCY);
