#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define I2C_BUS 1
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_lux(float *lux);
void control_relay(int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int relay_pin;
    float lux_threshold;
    char *log_filename;
} config_t;

config_t config = {RELAY_GPIO, LUX_THRESHOLD, LOG_FILE};

int main() {
    float lux;
    int relay_state = 0; // 0 = off, 1 = on

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_filename, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read lux value
        if (read_lux(&lux) == 0) {
            // Control relay based on lux value
            if (lux < config.lux_threshold && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
            } else if (lux >= config.lux_threshold && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
            }

            // Log data
            log_data(lux, relay_state);
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        // Delay
        gpioDelay(100); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Configure BH1750 for continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error configuring BH1750: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read lux value from BH1750
int read_lux(float *lux) {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from BH1750: %s\n", strerror(errno));
        return 1;
    }

    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2; // Convert to lux

    return 0;
}

// Control the relay
void control_relay(int state) {
    gpioWrite(config.relay_pin, state);
}

// Log data to file
void log_data(float lux, int relay_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s, Lux: %.2f, Relay: %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(config.relay_pin, 0); // Turn off relay
    gpioTerminate();
}

