// Define GPIO pins
#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22
#define SERVO_PIN 18

// Define servo pulse widths
#define LOCK_PULSE_WIDTH 1000
#define UNLOCK_PULSE_WIDTH 2000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set pull-up resistors
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to debounce a button press
int debounce_button(int gpio_pin) {
    if (gpioRead(gpio_pin) == 0) {
        gpioDelay(DEBOUNCE_DELAY * 1000); // Delay for 100ms
        if (gpioRead(gpio_pin) == 0) {
            return 1; // Button is pressed
        }
    }
    return 0; // Button is not pressed
}

// Function to set the servo pulse width
void set_servo_pulse_width(int pulse_width) {
    if (pulse_width >= 500 && pulse_width <= 2500) {
        gpioServo(SERVO_PIN, pulse_width);
        printf("Servo pulse width set to %d us\n", pulse_width);
    } else {
        fprintf(stderr, "Error: Pulse width out of range (500-2500 us)\n");
    }
}

// Function to lock the door
void lock_door() {
    printf("Locking door...\n");
    set_servo_pulse_width(LOCK_PULSE_WIDTH);
}

// Function to unlock the door
void unlock_door() {
    printf("Unlocking door...\n");
    set_servo_pulse_width(UNLOCK_PULSE_WIDTH);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (debounce_button(LOCK_BUTTON)) {
            lock_door();
            gpioDelay(500 * 1000); // Small delay to prevent multiple triggers
        }

        if (debounce_button(UNLOCK_BUTTON)) {
            unlock_door();
            gpioDelay(500 * 1000); // Small delay to prevent multiple triggers
        }

        gpioDelay(10 * 1000); // Small delay to reduce CPU usage
    }

    // Clean up and exit
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio
    printf("Program terminated.\n");
    return 0;
}

