#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define motor pulse durations (in milliseconds)
#define MOTOR1_DURATION 200
#define MOTOR2_DURATION 300

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR2_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to pulse a motor
void pulse_motor(int gpio_pin, int duration_ms) {
    if (gpio_pin != MOTOR1_GPIO && gpio_pin != MOTOR2_GPIO) {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return;
    }

    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO%d HIGH\n", gpio_pin);
        return;
    }

    gpioDelay(duration_ms * 1000); // Convert milliseconds to microseconds

    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO%d LOW\n", gpio_pin);
    }
}

// Function to cleanup GPIO pins and terminate the pigpio library
void cleanup_gpio() {
    // Ensure both motors are off
    gpioWrite(MOTOR1_GPIO, 0);
    gpioWrite(MOTOR2_GPIO, 0);

    gpioTerminate();
    fprintf(stderr, "pigpio terminated\n");
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Haptic feedback system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        pulse_motor(MOTOR1_GPIO, MOTOR1_DURATION);
        pulse_motor(MOTOR2_GPIO, MOTOR2_DURATION);
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

