#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <net/if.h>
#include <linux/if_packet.h>
#include <linux/if_ether.h>
#include <pigpio.h>
#include <zmq.h>

// Constants
#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO 27
#define ZMQ_ENDPOINT "tcp://*:5555"
#define ZMQ_TOPIC "SOUND_ALERTS"
#define POLLING_INTERVAL_MS 10
#define ALARM_DURATION_S 1
#define MAX_PACKET_SIZE 65535 // Maximum Ethernet frame size

// Global variables (minimize usage)
static volatile int running = 1;
static void *zmq_context = NULL;
static void *zmq_pub_socket = NULL;
static void *zmq_sub_socket = NULL;

// Function prototypes
int gpio_init(int gpio_pin, int mode);
int gpio_read(int gpio_pin);
int gpio_write(int gpio_pin, int value);
int zmq_init(void **context, void **socket, int socket_type, const char *endpoint);
int zmq_send(void *socket, const char *topic, const char *message);
int zmq_receive(void *socket, char *message, size_t message_size);
int get_mac_address(char *mac_address);
void signal_handler(int signal);
void cleanup(void);

// GPIO functions
int gpio_init(int gpio_pin, int mode) {
    if (gpioSetMode(gpio_pin, mode) != 0) {
        fprintf(stderr, "Error setting GPIO %d mode: %d\n", gpio_pin, gpioGetMode(gpio_pin));
        return -1;
    }
    return 0;
}

int gpio_read(int gpio_pin) {
    return gpioRead(gpio_pin);
}

int gpio_write(int gpio_pin, int value) {
    gpioWrite(gpio_pin, value);
    return 0;
}

// ZeroMQ functions
int zmq_init(void **context, void **socket, int socket_type, const char *endpoint) {
    *context = zmq_ctx_new();
    if (!*context) {
        fprintf(stderr, "Error creating ZeroMQ context: %s\n", zmq_strerror(zmq_errno()));
        return -1;
    }

    *socket = zmq_socket(*context, socket_type);
    if (!*socket) {
        fprintf(stderr, "Error creating ZeroMQ socket: %s\n", zmq_strerror(zmq_errno()));
        zmq_ctx_destroy(*context);
        return -1;
    }

    int rc = zmq_bind(*socket, endpoint);
    if (rc != 0) {
        fprintf(stderr, "Error binding ZeroMQ socket: %s\n", zmq_strerror(zmq_errno()));
        zmq_close(*socket);
        zmq_ctx_destroy(*context);
        return -1;
    }

    return 0;
}

int zmq_send(void *socket, const char *topic, const char *message) {
    char buffer[256]; // Adjust size as needed
    snprintf(buffer, sizeof(buffer), "%s %s", topic, message);
    int rc = zmq_send(socket, buffer, strlen(buffer), 0);
    if (rc == -1) {
        fprintf(stderr, "Error sending ZeroMQ message: %s\n", zmq_strerror(zmq_errno()));
        return -1;
    }
    return 0;
}

int zmq_receive(void *socket, char *message, size_t message_size) {
    zmq_msg_t msg;
    zmq_msg_init(&msg);
    msg.size = message_size;
    int rc = zmq_msg_recv(&msg, socket, 0);
    if (rc == -1) {
        fprintf(stderr, "Error receiving ZeroMQ message: %s\n", zmq_strerror(zmq_errno()));
        zmq_msg_close(&msg);
        return -1;
    }

    memcpy(message, zmq_msg_data(&msg), rc);
    message[rc] = '\0'; // Null-terminate the message
    zmq_msg_close(&msg);
    return 0;
}

// Network functions
int get_mac_address(char *mac_address) {
    int sock;
    struct ifreq ifr;

    sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    ifr.ifr_addr.sa_family = AF_INET;
    strncpy(ifr.ifr_name, "eth0", IFNAMSIZ - 1); // Use "wlan0" for wireless

    if (ioctl(sock, SIOCGIFHWADDR, &ifr) == 0) {
        unsigned char *mac = (unsigned char *)ifr.ifr_hwaddr.sa_data;
        sprintf(mac_address, "%02x:%02x:%02x:%02x:%02x:%02x", mac[0], mac[1], mac[2], mac[3], mac[4], mac[5]);
    } else {
        perror("ioctl");
        close(sock);
        return -1;
    }

    close(sock);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    running = 0;
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up...\n");

    // Release GPIO resources
    gpioWrite(ALARM_LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    // Close ZeroMQ sockets and context
    if (zmq_pub_socket) {
        zmq_close(zmq_pub_socket);
    }
    if (zmq_sub_socket) {
        zmq_close(zmq_sub_socket);
    }
    if (zmq_context) {
        zmq_ctx_destroy(zmq_context);
    }

    printf("Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  mode: sound_sensor | alarm_node\n");
        return 1;
    }

    const char *mode = argv[1];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (strcmp(mode, "sound_sensor") == 0) {
        // Sound sensor mode
        printf("Starting sound sensor mode...\n");

        // Initialize GPIO for sound sensor input
        if (gpio_init(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
            cleanup();
            return 1;
        }

        // Initialize ZeroMQ publisher
        if (zmq_init(&zmq_context, &zmq_pub_socket, ZMQ_PUB, ZMQ_ENDPOINT) != 0) {
            cleanup();
            return 1;
        }

        // Get MAC address
        char mac_address[20];
        if (get_mac_address(mac_address) != 0) {
            fprintf(stderr, "Failed to get MAC address\n");
            cleanup();
            return 1;
        }

        printf("MAC address: %s\n", mac_address);

        // Main loop
        while (running) {
            int sound_detected = (gpio_read(SOUND_SENSOR_GPIO) == 0); // Active low

            if (sound_detected) {
                printf("Sound detected!\n");
                if (zmq_send(zmq_pub_socket, ZMQ_TOPIC, mac_address) != 0) {
                    fprintf(stderr, "Failed to send alert\n");
                }
                gpioDelay(100); // Debounce
            }
            gpioDelay(POLLING_INTERVAL_MS);
        }

    } else if (strcmp(mode, "alarm_node") == 0) {
        // Alarm node mode
        printf("Starting alarm node mode...\n");

        // Initialize GPIO for alarm LED output
        if (gpio_init(ALARM_LED_GPIO, PI_OUTPUT) != 0) {
            cleanup();
            return 1;
        }

        // Initialize ZeroMQ subscriber
        if (zmq_init(&zmq_context, &zmq_sub_socket, ZMQ_SUB, ZMQ_ENDPOINT) != 0) {
            cleanup();
            return 1;
        }

        // Subscribe to the topic
        int rc = zmq_setsockopt(zmq_sub_socket, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC));
        if (rc != 0) {
            fprintf(stderr, "Error subscribing to ZeroMQ topic: %s\n", zmq_strerror(zmq_errno()));
            cleanup();
            return 1;
        }

        // Main loop
        char message[MAX_PACKET_SIZE];
        while (running) {
            if (zmq_receive(zmq_sub_socket, message, sizeof(message)) == 0) {
                printf("Received message: %s\n", message);
                // Extract MAC address (assuming it's the second part of the message)
                char *mac_address = strchr(message, ' ') + 1; // Find space and move pointer
                if (mac_address != NULL) {
                    printf("MAC address: %s\n", mac_address);
                    gpioWrite(ALARM_LED_GPIO, 1); // Turn on LED
                    gpioDelay(ALARM_DURATION_S * 1000); // Wait for alarm duration
                    gpioWrite(ALARM_LED_GPIO, 0); // Turn off LED
                }
            }
            gpioDelay(10); // Small delay to prevent busy-waiting
        }

    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  mode: sound_sensor | alarm_node\n");
        cleanup();
        return 1;
    }

    cleanup();
    return 0;
}

