#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>

// Configuration
#define GPIO_PIN 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define PULSE_BUFFER_SIZE 100
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ZERO_SPACE 560
#define NEC_ONE_SPACE 1690
#define NEC_REPEAT_SPACE 2250

// NEC Frame Structure
typedef struct {
    unsigned int address;
    unsigned int command;
    unsigned int inv_command;
    unsigned int inv_address;
    unsigned int inv_inv_command;
    unsigned int inv_inv_address;
} nec_frame_t;

// Global Variables
static volatile int pulse_count = 0;
static volatile unsigned int pulse_times[PULSE_BUFFER_SIZE];
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function Prototypes
void signal_handler(int sig);
void alert_callback(int gpio, int level, uint32_t tick);
int decode_nec(nec_frame_t *frame);
int validate_checksum(nec_frame_t *frame);
int publish_mqtt(nec_frame_t *frame);
void cleanup();

// Signal Handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Alert Callback
void alert_callback(int gpio, int level, uint32_t tick) {
    if (pulse_count < PULSE_BUFFER_SIZE) {
        pulse_times[pulse_count++] = tick;
    } else {
        syslog(LOG_ERR, "Pulse buffer overflow!");
    }
}

// NEC Decoding Function
int decode_nec(nec_frame_t *frame) {
    if (pulse_count < 68) {
        syslog(LOG_ERR, "Not enough pulses received for NEC frame.");
        return -1;
    }

    // Check for valid header
    if (pulse_times[0] < NEC_HEADER_MARK * 0.8 || pulse_times[0] > NEC_HEADER_MARK * 1.2 ||
        pulse_times[1] < NEC_HEADER_SPACE * 0.8 || pulse_times[1] > NEC_HEADER_SPACE * 1.2) {
        syslog(LOG_ERR, "Invalid NEC header.");
        return -1;
    }

    unsigned int address = 0;
    unsigned int command = 0;
    unsigned int inv_command = 0;
    unsigned int inv_address = 0;
    unsigned int inv_inv_command = 0;
    unsigned int inv_inv_address = 0;

    // Decode address
    for (int i = 0; i < 8; i++) {
        if (pulse_times[2 + (i * 2) + 1] > NEC_ONE_SPACE * 0.8 && pulse_times[2 + (i * 2) + 1] < NEC_ONE_SPACE * 1.2) {
            address |= (1 << i);
        } else if (pulse_times[2 + (i * 2) + 1] > NEC_ZERO_SPACE * 0.8 && pulse_times[2 + (i * 2) + 1] < NEC_ZERO_SPACE * 1.2) {
            // Do nothing, it's a 0
        } else {
            syslog(LOG_ERR, "Invalid address bit.");
            return -1;
        }
    }

    // Decode command
    for (int i = 0; i < 8; i++) {
        if (pulse_times[18 + (i * 2) + 1] > NEC_ONE_SPACE * 0.8 && pulse_times[18 + (i * 2) + 1] < NEC_ONE_SPACE * 1.2) {
            command |= (1 << i);
        } else if (pulse_times[18 + (i * 2) + 1] > NEC_ZERO_SPACE * 0.8 && pulse_times[18 + (i * 2) + 1] < NEC_ZERO_SPACE * 1.2) {
            // Do nothing, it's a 0
        } else {
            syslog(LOG_ERR, "Invalid command bit.");
            return -1;
        }
    }

    // Decode inverted command
    for (int i = 0; i < 8; i++) {
