#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define NUM_SENSORS 4
#define SLEEP_DURATION 1.0 // seconds

// Global variables
static volatile int terminate = 0;
int i2c_handles[NUM_SENSORS];
int udp_socket;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read lux value from a BH1750 sensor
float read_bh1750(int handle) {
    char buf[2];
    int result;

    // Send start conversion command
    result = i2cWriteByteData(handle, 0x00, CONTINUOUS_HIGH_RES_MODE);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return NAN;
    }

    // Wait for conversion (at least 180ms)
    gpioDelay(180000); // microseconds

    // Read two bytes of data
    result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return NAN;
    }

    // Convert to lux value
    unsigned int msb = buf[0];
    unsigned int lsb = buf[1];
    float lux = (float)((msb << 8 | lsb) / 1.2);

    return lux;
}

// Function to format sensor data into a string
char* format_sensor_data(float lux_values[]) {
    char *data = malloc(256); // Allocate memory for the string
    if (data == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }
    data[0] = '\0'; // Initialize as an empty string

    for (int i = 0; i < NUM_SENSORS; i++) {
        char temp[64];
        snprintf(temp, sizeof(temp), "%d,%.2f", i + 1, lux_values[i]);
        strcat(data, temp);
        if (i < NUM_SENSORS - 1) {
            strcat(data, ";");
        }
    }

    return data;
}

// Function to send UDP multicast packet
int send_udp_packet(const char *data) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(udp_socket, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto failed");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C devices
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Error opening I2C device %d: %d\n", i + 1, i2c_handles[i]);
            // Continue to the next sensor, even if one fails
        }
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("socket creation failed");
        // Attempt to close any opened I2C devices before exiting
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] >= 0) {
                i2cClose(i2c_handles[i]);
            }
        }
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float lux_values[NUM_SENSORS];

        // Read sensor data
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] >= 0) {
                lux_values[i] = read_bh1750(i2c_handles[i]);
            } else {
                lux_values[i] = NAN; // Sensor not available
            }
        }

        // Format sensor data
        char *data = format_sensor_data(lux_values);
        if (data != NULL) {
            // Send UDP packet
            if (send_udp_packet(data) != 0) {
                fprintf(stderr, "Error sending UDP packet\n");
            }

            free(data); // Free allocated memory
        }

        // Sleep for 1 second
        sleep(SLEEP_DURATION);
    }

    // Cleanup
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
        }
    }
    close(udp_socket);
    gpioTerminate();

    return 0;
}

