            }

            free(data); // Free allocated memory
        }

        // Sleep for 1 second
        sleep(SLEEP_DURATION);
    }

    // Cleanup
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
