#define FLOW_SCALE_FACTOR 0.01
#define FLOW_OFFSET 0.0
#define LOG_FILE "airflow_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int read_airflow_sensor(int i2c_handle, unsigned char *data);
float convert_to_slpm(unsigned char *data);
int log_flow_rate(float flow_rate, const char *filename);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }

    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

// Function to read airflow sensor data
int read_airflow_sensor(int i2c_handle, unsigned char *data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, (char *)data, 2);

        if (result == 2) {
            return 0; // Success
        } else if (result < 0) {
            fprintf(stderr, "I2C read error: %d, retry %d\n", result, retries + 1);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        } else {
