float convert_to_slpm(unsigned char *data) {
    unsigned int raw_flow = ((unsigned int)data[0] << 8) | data[1];
    raw_flow &= 0x3FFF; // Mask out the status bits
    return (float)raw_flow * FLOW_SCALE_FACTOR + FLOW_OFFSET;
}

