    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(log_file, "%s, %.2f SLPM\n", timestamp, flow_rate);
    fclose(log_file);
    return 0;
}

