#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 Registers
#define AS7341_ID 0x00
#define AS7341_ENABLE 0x80
#define AS7341_CFG6 0x86
#define AS7341_F1DATAH 0x94
#define AS7341_F8DATAH 0xA6

// AS7341 ID value
#define AS7341_ID_VALUE 0x41

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold spectral data
typedef struct {
    uint16_t f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;
} spectral_data_t;

// Function prototypes
int init_i2c();
int verify_sensor_id();
int power_on_sensor();
int configure_sensor();
int read_spectral_data(spectral_data_t *data);
float calculate_lux(spectral_data_t data);
int log_data(spectral_data_t data, float lux);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, AS7341_ADDR, 0); // Open I2C bus 1, address 0x39, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify the sensor's ID
int verify_sensor_id() {
    int id = i2cReadByteData(i2c_handle, AS7341_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", id);
        return -1;
    }
    if (id != AS7341_ID_VALUE) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X (expected 0x%02X)\n", id, AS7341_ID_VALUE);
        return -1;
    }
    return 0;
}

// Power on the sensor
int power_on_sensor() {
    int result = i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x03); // PON = 1, AEN = 1
    if (result < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %d\n", result);
        return -1;
    }
    return 0;
}

// Configure the sensor
int configure_sensor() {
    int result = i2cWriteByteData(i2c_handle, AS7341_CFG6, 0x03); // SMUX = 3 (100ms), Gain = 1
    if (result < 0) {
        fprintf(stderr, "Error writing to CFG6 register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read spectral data from the sensor
int read_spectral_data(spectral_data_t *data) {
    uint8_t buffer[20]; // Buffer to hold all spectral data (10 channels * 2 bytes)
    int result = i2cReadI2CBlockData(i2c_handle, AS7341_F1DATAH, (char *)buffer, 20);
    if (result < 0) {
        fprintf(stderr, "Error reading spectral data: %d\n", result);
        return -1;
    }

    data->f1 = (buffer[1] << 8) | buffer[0];
    data->f2 = (buffer[3] << 8) | buffer[2];
    data->f3 = (buffer[5] << 8) | buffer[4];
    data->f4 = (buffer[7] << 8) | buffer[6];
    data->f5 = (buffer[9] << 8) | buffer[8];
    data->f6 = (buffer[11] << 8) | buffer[10];
    data->f7 = (buffer[13] << 8) | buffer[12];
    data->f8 = (buffer[15] << 8) | buffer[14];
    data->clear = (buffer[17] << 8) | buffer[16];
    data->nir = (buffer[19] << 8) | buffer[18];

    return 0;
}

// Calculate lux approximation
float calculate_lux(spectral_data_t data) {
    // Simplified lux calculation (adjust coefficients as needed)
    float lux = 0.2126 * data.f1 + 0.7152 * data.f2 + 0.0722 * data.f3;
    return lux;
}

// Log data to CSV file
int log_data(spectral_data_t data, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            timestamp, data.f1, data.f2, data.f3, data.f4, data.f5, data.f6, data.f7, data.f8, data.clear, data.nir, lux);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Power on the sensor
    if (power_on_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    }

    spectral_data_t data;
    float lux;

    // Main loop
    while (!terminate) {
        // Read spectral data
        if (read_spectral_data(&data) == 0) {
            // Calculate lux
            lux = calculate_lux(data);

            // Log data
            log_data(data, lux);

            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Error reading or logging data. Retrying...\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

