#define DEFAULT_ERROR_LOG_FILENAME "seismic_error.log"

// D7S Register Addresses (Example - adjust based on datasheet)
#define D7S_REG_X_LSB 0x28
#define D7S_REG_X_MSB 0x29
#define D7S_REG_Y_LSB 0x2A
#define D7S_REG_Y_MSB 0x2B
#define D7S_REG_Z_LSB 0x2C
#define D7S_REG_Z_MSB 0x2D

// Global variables (minimize usage)
static int i2c_handle = -1;
static FILE *csv_file = NULL;
static FILE *error_log_file = NULL;
static int running = 1;

// Structure to hold program configuration
typedef struct {
    int i2c_address;
    int sample_interval;
    char csv_filename[256];
    char error_log_filename[256];
} program_config_t;

// Function prototypes
int read_d7s_data(int i2c_handle, float *x_g, float *y_g, float *z_g);
int log_data(FILE *csv_file, float x_g, float y_g, float z_g);
