int open_error_log_file(const char *filename);
void cleanup();
void parse_arguments(int argc, char *argv[], program_config_t *config);

// Function to read data from the D7S sensor
int read_d7s_data(int i2c_handle, float *x_g, float *y_g, float *z_g) {
    char buffer[6];
    int retries = 3;
    int delay_ms = 10;
    int result;

    while (retries > 0) {
        // Read X, Y, and Z data (6 bytes)
