#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define SLEEP_DURATION 1 // seconds

// Global variables
int i2c_handle;
int udp_socket;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_udp_socket();
float read_lux();
int send_lux(float lux);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Initialize UDP socket
int init_udp_socket() {
    struct sockaddr_in addr;
    int ttl = 1;

    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating socket");
        return -1;
    }

    // Set multicast TTL
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        perror("Error setting TTL");
        close(udp_socket);
        return -1;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (connect(udp_socket, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error connecting socket");
        close(udp_socket);
        return -1;
    }

    return 0;
}

// Read lux value from BH1750
float read_lux() {
    unsigned char buffer[2];
    int bytes_read;

    bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buffer, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1.0;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    return (float)raw_value / 1.2;
}

// Send lux value via UDP multicast
int send_lux(float lux) {
    char buffer[32];
    snprintf(buffer, sizeof(buffer), "%.2f", lux);

    if (send(udp_socket, buffer, strlen(buffer), 0) < 0) {
        perror("Error sending data");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize UDP socket
    if (init_udp_socket() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting light sensor data broadcast...\n");

    while (!terminate) {
        float lux = read_lux();
        if (lux >= 0) {
            if (send_lux(lux) < 0) {
                fprintf(stderr, "Error sending lux value\n");
            }
        } else {
            fprintf(stderr, "Error reading lux value\n");
        }

        sleep(SLEEP_DURATION);
    }

    // Cleanup
    i2cClose(i2c_handle);
    close(udp_socket);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

