#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <sys/select.h>
#include <time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define LINE_BUFFER_SIZE 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int open_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }
    return fd;
}

int configure_uart(int fd) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 second timeout (5 * 0.1 seconds)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        return -1;
    }

    return 0;
}

int read_uart(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            // Timeout occurred, no data available
            return 0;
        }
        perror("Error reading from UART");
        return -1;
    }
    buffer[bytes_read] = '\0';
    return bytes_read;
}

int parse_data(const char *data, long *timestamp, float *range) {
    char *line = strdup(data);
    if (line == NULL) {
        perror("Error duplicating string");
        return -1;
    }

    char *token = strtok(line, ",");
    if (token == NULL) {
        fprintf(stderr, "Error: Missing timestamp in data: %s\n", data);
        free(line);
        return -1;
    }
    *timestamp = strtol(token, NULL, 10);
    if (*timestamp == 0 && errno == ERANGE) {
        fprintf(stderr, "Error: Timestamp out of range: %s\n", data);
        free(line);
        return -1;
    }

    token = strtok(NULL, "\n");
    if (token == NULL) {
        fprintf(stderr, "Error: Missing range in data: %s\n", data);
        free(line);
        return -1;
    }

    *range = strtof(token, NULL);
    if (*range == 0.0 && errno == ERANGE) {
        fprintf(stderr, "Error: Range out of range: %s\n", data);
        free(line);
        return -1;
    }

    free(line);
    return 0;
}

void log_data(long timestamp, float range) {
    time_t rawtime = timestamp;
    struct tm *timeinfo = localtime(&rawtime);
    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = open_uart(UART_DEVICE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    if (configure_uart(uart_fd) != 0) {
        close(uart_fd);
        return EXIT_FAILURE;
    }

    char line_buffer[LINE_BUFFER_SIZE] = {0};
    int buffer_index = 0;
    fd_set readfds;
    struct timeval timeout;

    while (program_running) {
        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        timeout.tv_sec = TIMEOUT_SEC;
        timeout.tv_usec = 0;

        int select_result = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);

        if (select_result == -1) {
            perror("Error in select");
            break;
        } else if (select_result == 0) {
            // Timeout occurred, no data to read
            continue;
        } else {
            // Data is available to read
            int bytes_read = read_uart(uart_fd, line_buffer + buffer_index, LINE_BUFFER_SIZE - buffer_index - 1);
            if (bytes_read > 0) {
                buffer_index += bytes_read;

                // Check for newline character
                char *newline_pos = strchr(line_buffer, '\n');
                if (newline_pos != NULL) {
                    *newline_pos = '\0'; // Null-terminate the line

                    long timestamp;
                    float range;
                    if (parse_data(line_buffer, &timestamp, &range) == 0) {
                        log_data(timestamp, range);
                    } else {
                        fprintf(stderr, "Error parsing data: %s\n", line_buffer);
                    }

                    // Move remaining data to the beginning of the buffer
                    memmove(line_buffer, newline_pos + 1, buffer_index = strlen(newline_pos + 1) + 1); // +1 for null terminator
                } else if (buffer_index >= LINE_BUFFER_SIZE - 1) {
                    // Buffer overflow, discard data
                    fprintf(stderr, "Error: Line buffer overflow\n");
                    buffer_index = 0;
                    line_buffer[0] = '\0';
                }
            } else if (bytes_read < 0) {
                // Error occurred during read, but not EAGAIN or EWOULDBLOCK
                break;
            }
        }
    }

    if (uart_fd != -1) {
        close(uart_fd);
    }

    return EXIT_SUCCESS;
}

