                        fprintf(stderr, "Error parsing data: %s\n", line_buffer);
                    }

                    // Move remaining data to the beginning of the buffer
                    memmove(line_buffer, newline_pos + 1, buffer_index = strlen(newline_pos + 1) + 1); // +1 for null terminator
                } else if (buffer_index >= LINE_BUFFER_SIZE - 1) {
                    // Buffer overflow, discard data
                    fprintf(stderr, "Error: Line buffer overflow\n");
                    buffer_index = 0;
                    line_buffer[0] = '\0';
                }
            } else if (bytes_read < 0) {
                // Error occurred during read, but not EAGAIN or EWOULDBLOCK
                break;
            }
        }
    }

    if (uart_fd != -1) {
        close(uart_fd);
    }

    return EXIT_SUCCESS;
}

